function synchronizeOperationNotice(host, operationKey, terminal, delayMs = 6000) {
    let state = operationNoticeStates.get(host);
    if (!state || state.operationKey !== operationKey) {
        if (state?.timer) clearTimeout(state.timer);
        state = { operationKey, dismissed: false, terminal: false, timer: null };
        operationNoticeStates.set(host, state);
    }
    let close = host.querySelector('[data-dismiss-operation-notice]');
    if (!close) {
        close = document.createElement('button');
        close.type = 'button';
        close.className = 'operation-notice-dismiss';
        close.dataset.dismissOperationNotice = '';
        close.setAttribute('aria-label', '关闭提示');
        close.textContent = '×';
        close.addEventListener('click', () => {
            const current = operationNoticeStates.get(host);
            if (current) {
                current.dismissed = true;
                clearTimeout(current.timer);
            }
            host.hidden = true;
        });
        host.appendChild(close);
    }
    if (terminal && !state.terminal && !state.dismissed) {
        state.timer = setTimeout(() => {
            if (operationNoticeStates.get(host) !== state) return;
            state.dismissed = true;
            host.hidden = true;
        }, delayMs);
    }
    state.terminal = terminal;
    host.hidden = state.dismissed;
}

function ensureArticleWorkspaceSaveProgress() {
    let panel = document.getElementById('articleWorkspaceSaveProgress');
    if (panel) return panel;
    panel = document.createElement('section');
    panel.id = 'articleWorkspaceSaveProgress';
    panel.className = 'article-workspace-save-progress';
    panel.hidden = true;
    panel.setAttribute('role', 'status');
    panel.setAttribute('aria-live', 'polite');
    const heading = document.createElement('div');
    heading.className = 'article-workspace-save-progress-heading';
    const title = document.createElement('strong');
    title.textContent = '保存到本地';
    const summary = document.createElement('span');
    summary.dataset.saveProgressSummary = '';
    summary.textContent = '正在准备…';
    heading.append(title, summary);
    const list = document.createElement('ol');
    list.className = 'article-workspace-save-progress-list';
    ARTICLE_WORKSPACE_SAVE_STAGES.forEach(stage => {
        const row = document.createElement('li');
        row.className = 'article-workspace-save-stage is-pending';
        row.dataset.saveStage = stage.id;
        const marker = document.createElement('span');
        marker.className = 'article-workspace-save-stage-marker';
        marker.setAttribute('aria-hidden', 'true');
        const label = document.createElement('span');
        label.textContent = stage.label;
        const detail = document.createElement('span');
        detail.className = 'article-workspace-save-stage-detail';
        detail.textContent = '等待';
        row.append(marker, label, detail);
        list.appendChild(row);
    });
    panel.append(heading, list);
    document.getElementById('statusMessage')?.after(panel);
    return panel;
}

function articleWorkspaceSaveStageDetail(stage, status, progress = {}) {
    if (status === 'active') {
        const completed = Math.max(0, Number(progress.completedCount) || 0);
        const total = Math.max(completed, Number(progress.totalCount) || 0);
        return total && completed ? `正在保存 ${completed}/${total}` : '处理中';
    }
    if (status === 'error') return '失败';
    if (status === 'warning') return '已跳过或需重试';
    if (status !== 'done') return '等待';
    if (stage === 'permission') return '文件夹可写';
    if (stage === 'sync') return '已写入目录';
    if (stage === 'offline' && progress.disabled === true) return '设置中未启用';
    if (stage === 'offline' && progress.reused === true) return '复用快照并写入';
    const completed = Math.max(0, Number(progress.completedCount) || 0);
    const total = Math.max(completed, Number(progress.totalCount) || 0);
    return total ? `已保存 ${completed}/${total}` : '已完成';
}

function renderArticleWorkspaceSaveProgress(progress = {}) {
    const operationId = String(progress.operationId || '');
    if (!operationId) return;
    if (progress.initialize === true) {
        activeArticleWorkspaceSaveOperationId = operationId;
        clearTimeout(articleWorkspaceSaveProgressDismissTimer);
        articleWorkspaceSaveProgressDismissTimer = null;
    } else if (operationId !== activeArticleWorkspaceSaveOperationId) {
        return;
    }
    const panel = ensureArticleWorkspaceSaveProgress();
    panel.hidden = false;
    const stage = String(progress.stage || 'permission');
    const status = String(progress.status || 'active');
    const stageIndex = ARTICLE_WORKSPACE_SAVE_STAGES.findIndex(item => item.id === stage);
    ARTICLE_WORKSPACE_SAVE_STAGES.forEach((item, index) => {
        const row = panel.querySelector(`[data-save-stage="${item.id}"]`);
        if (!row) return;
        let nextStatus = row.dataset.status || 'pending';
        if (index < stageIndex && nextStatus === 'pending') nextStatus = 'done';
        if (item.id === stage) nextStatus = status;
        row.dataset.status = nextStatus;
        row.className = `article-workspace-save-stage is-${nextStatus}`;
        const detail = row.querySelector('.article-workspace-save-stage-detail');
        if (detail) {
            detail.textContent = item.id === stage
                ? articleWorkspaceSaveStageDetail(item.id, nextStatus, progress)
                : articleWorkspaceSaveStageDetail(item.id, nextStatus);
        }
    });
    const summary = panel.querySelector('[data-save-progress-summary]');
    if (summary) {
        summary.textContent = status === 'error'
            ? '保存未完成'
            : status === 'warning'
                ? '主要内容已保存'
                : stage === 'sync' && status === 'done'
                    ? '全部保存完成'
                    : `${ARTICLE_WORKSPACE_SAVE_STAGES[stageIndex]?.label || '本地内容'}处理中`;
    }
    panel.dataset.status = status === 'error' ? 'error'
        : status === 'warning' ? 'warning'
            : stage === 'sync' && status === 'done' ? 'done' : 'active';
    synchronizeOperationNotice(panel, operationId,
        status === 'error' || (stage === 'sync' && ['done', 'warning'].includes(status)),
        status === 'done' ? 3200 : 6000);
}
