async function queryPanelTargetTab() {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (!tab?.id || tab.url || tab.pendingUrl) return tab || null;

    // Browsers may omit url/title for the extension-owned PDF reader even
    // though it is the active tab. Recover only a previously activated reader
    // URL and verify that the live tab still hosts the PDF workspace before
    // using it, so a stale activation cannot be applied to another extension
    // page in the same tab.
    const activation = await SciLLM.readTabActivation(
        chrome.storage.session,
        tab.id
    ).catch(() => null);
    const readerUrl = SciLLM.isPdfReaderUrl?.(activation?.url)
        ? activation.url
        : '';
    if (!readerUrl) return tab;
    const pdfWorkspace = await SciLLM.sendTabMessageIfPresent(
        chrome,
        tab.id,
        { action: 'getPdfWorkspaceState' }
    ).catch(() => null);
    if (!pdfWorkspace?.success || pdfWorkspace.pdfMode !== true) return tab;
    return {
        ...tab,
        url: readerUrl,
        pendingUrl: readerUrl,
        title: String(activation?.title || '文献 PDF')
    };
}

const sidePanelShortcutPublications = new Map();
const sidePanelShortcutPorts = new Map();

function connectSidePanelShortcutScope(tabId, message, isCurrent) {
    return new Promise(resolve => {
        let port;
        try {
            port = chrome.tabs.connect(tabId, {
                name: 'brevess-side-panel-scope-v1', frameId: 0
            });
        } catch (_) {
            resolve(false);
            return;
        }
        let settled = false;
        let closed = false;
        let timer = null;
        const lease = { port, cancel: () => close(true) };
        const settle = success => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            port.onMessage?.removeListener?.(onMessage);
            resolve(success);
        };
        const close = disconnect => {
            if (closed) return;
            closed = true;
            if (sidePanelShortcutPorts.get(tabId) === lease) {
                sidePanelShortcutPorts.delete(tabId);
            }
            settle(false);
            port.onDisconnect?.removeListener?.(onDisconnect);
            if (disconnect) {
                try { port.disconnect(); } catch (_) { /* Already disconnected. */ }
            }
        };
        const onMessage = response => {
            if (closed) return;
            if (!isCurrent() || sidePanelShortcutPorts.get(tabId) !== lease ||
                response?.success !== true || response.enabled !== true) {
                close(true);
                return;
            }
            settle(true);
        };
        const onDisconnect = () => {
            // Reading lastError acknowledges a browser connection failure.
            void chrome.runtime?.lastError;
            close(false);
        };
        sidePanelShortcutPorts.set(tabId, lease);
        try {
            port.onMessage.addListener(onMessage);
            port.onDisconnect.addListener(onDisconnect);
            timer = setTimeout(() => close(true), 3000);
            if (!isCurrent()) close(true);
            else port.postMessage(message);
        } catch (_) {
            close(true);
        }
    });
}

async function publishSidePanelShortcutScope(
    tabId = activePanelTabContext.tabId,
    enabled = activePanelTabContext.activated
) {
    const numericTabId = Number(tabId);
    if (!Number.isInteger(numericTabId) || numericTabId < 0) return false;
    const publication = (sidePanelShortcutPublications.get(numericTabId) || 0) + 1;
    sidePanelShortcutPublications.set(numericTabId, publication);
    // A replacement or disable closes the old lease synchronously. Browser
    // destruction of the side-panel context also disconnects its live ports.
    sidePanelShortcutPorts.get(numericTabId)?.cancel();
    const panelContext = activePanelTabContext;
    const expectedUrl = panelContext.url;
    // A disable must invalidate a pending enable even if injection has not yet
    // created its receiver. Recovery rechecks this before sending any message.
    const isCurrent = () =>
        sidePanelShortcutPublications.get(numericTabId) === publication &&
        activePanelTabContext === panelContext &&
        panelContext.url === expectedUrl &&
        panelContext.activated === true && Number(panelContext.tabId) === numericTabId;
    try {
        if (enabled !== true) {
            const response = await SciLLM.sendTabMessageIfPresent(chrome, numericTabId, {
                action: 'setSidePanelShortcutScope', enabled: false, shortcuts: {}, portScoped: true
            });
            return response?.success === true;
        }
        const probe = await sendTabMessage(numericTabId, {
            action: 'prepareSidePanelShortcutScope'
        }, {
            expectedUrl,
            contextKey: `${panelContext.key || ''}:scope:${publication}`,
            isCurrent
        });
        if (probe?.success !== true || !isCurrent() ||
            typeof probe.documentIdentity !== 'string' || !probe.documentIdentity.trim() ||
            typeof probe.navigationIdentity !== 'string' || !probe.navigationIdentity.trim()) return false;
        return await connectSidePanelShortcutScope(numericTabId, {
            action: 'setSidePanelShortcutScope', enabled: true,
            shortcuts: currentKeyboardShortcuts(), expectedUrl,
            expectedDocumentIdentity: probe.documentIdentity,
            expectedNavigationIdentity: probe.navigationIdentity
        }, isCurrent);
    } catch (_) {
        return false;
    }
}

function capturePanelContext(taskToken = 0) {
    return {
        ...SciLLM.capturePanelContext(activePanelTabContext, taskToken),
        url: activePanelTabContext.url,
        pdfMode: activePanelTabContext.pdfMode === true
    };
}

function isCurrentPanelContext(panelContext) {
    return SciLLM.isCurrentPanelContext(activePanelTabContext, panelContext);
}

function isCurrentReviewOutlineTask(panelContext) {
    return isCurrentPanelContext(panelContext) &&
        Number(panelContext?.taskToken) === reviewOutlineTaskGeneration;
}

function isCurrentParagraphSummaryTask(panelContext) {
    return isCurrentPanelContext(panelContext) &&
        Number(panelContext?.taskToken) === paragraphSummaryTaskGeneration;
}

function panelTabDocumentKey(tab = {}) {
    const tabId = Number(tab.id);
    const url = SciLLM.normalizeTabDocumentUrl(tab.url || tab.pendingUrl);
    return Number.isInteger(tabId) && url ? `${tabId}|${url}` : '';
}

let pdfReaderNoticeState = null;
let pdfReaderNoticeRequestSequence = 0;
let sidePanelNotificationMutationRevision = 0;

function notificationPanelKey() {
    return activePanelTabContext.pdfMode && pdfReaderNoticeState?.panelKey === activePanelTabContext.key
        ? pdfReaderNoticeState.historyKey : activePanelTabContext.key;
}

function notificationSessionStorageKey(panelKey = notificationPanelKey()) {
    const source = String(panelKey || '');
    if (!source) return '';
    let hash = 2166136261;
    for (let index = 0; index < source.length; index += 1) {
        hash ^= source.charCodeAt(index);
        hash = Math.imul(hash, 16777619);
    }
    const tabId = Number(source.split('|', 1)[0]) || 0;
    return `sci-side-panel-notifications-v1-${tabId}-${(hash >>> 0).toString(16)}`;
}

function formatSidePanelNotificationTime(timestamp, includeDate = false) {
    const date = new Date(Number(timestamp) || Date.now());
    const options = {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
    };
    if (includeDate) {
        options.month = '2-digit';
        options.day = '2-digit';
    }
    return new Intl.DateTimeFormat('zh-CN', options).format(date);
}

function renderSidePanelNotificationHistory() {
    const center = document.getElementById('sidePanelNotificationCenter');
    const latest = document.getElementById('sidePanelNotificationLatest');
    const time = document.getElementById('sidePanelNotificationTime');
    const history = document.getElementById('sidePanelNotificationHistory');
    if (!center || !latest || !time || !history) return;
    const newest = sidePanelNotificationHistory[0] || null;
    latest.textContent = newest?.message || '暂无通知';
    latest.title = newest?.message || '暂无通知';
    time.textContent = newest
        ? formatSidePanelNotificationTime(newest.timestamp) : '--:--';
    time.dateTime = newest ? new Date(newest.timestamp).toISOString() : '';
    center.classList.toggle('has-error', newest?.type === 'error');
    history.replaceChildren();
    if (!sidePanelNotificationHistory.length) {
        history.appendChild(createWorkspaceElement(
            'li', 'side-panel-notification-empty', '还没有通知'
        ));
        return;
    }
    const today = new Date().toDateString();
    sidePanelNotificationHistory.forEach(item => {
        const row = createWorkspaceElement(
            'li',
            `side-panel-notification-item${item.type === 'error' ? ' is-error' : ''}`
        );
        const rowTime = document.createElement('time');
        const includeDate = new Date(item.timestamp).toDateString() !== today;
        rowTime.dateTime = new Date(item.timestamp).toISOString();
        rowTime.textContent = formatSidePanelNotificationTime(item.timestamp, includeDate);
        row.append(rowTime, createWorkspaceElement('span', '', item.message));
        history.appendChild(row);
    });
}

function persistSidePanelNotificationHistory() {
    const storageKey = notificationSessionStorageKey();
    if (!storageKey || !chrome.storage?.session) return;
    void chrome.storage.session.set({
        [storageKey]: { scope: notificationPanelKey(),
            items: sidePanelNotificationHistory.map(item => ({ ...item })) }
    }).catch(() => undefined);
}

async function loadSidePanelNotificationHistory(panelKey = notificationPanelKey(), isCurrent = () => true) {
    const storageKey = notificationSessionStorageKey(panelKey);
    if (!storageKey || !chrome.storage?.session) return [];
    const mutationRevision = sidePanelNotificationMutationRevision;
    try {
        const stored = await chrome.storage.session.get(storageKey);
        if (panelKey !== notificationPanelKey() || !isCurrent()) return [];
        const record = stored?.[storageKey];
        // The compact storage key is only an index; exact scope proves ownership.
        // Legacy web history can migrate, but unbound arrays never enter a PDF.
        const items = record?.scope === panelKey && Array.isArray(record.items)
            ? record.items : !activePanelTabContext.pdfMode && Array.isArray(record) ? record : [];
        const loaded = items.slice(0, SIDE_PANEL_NOTIFICATION_HISTORY_LIMIT)
            .map(item => ({
                message: String(item?.message || '').trim().slice(0, 600),
                type: item?.type === 'error' ? 'error'
                    : item?.type === 'success' ? 'success' : 'info',
                timestamp: Math.max(0, Number(item?.timestamp) || 0) || Date.now(),
                ...(item?.pdfNoticeKey ? { pdfNoticeKey: String(item.pdfNoticeKey).slice(0, 100) } : {})
            }))
            .filter(item => item.message);
        if (mutationRevision !== sidePanelNotificationMutationRevision) {
            const seen = new Set();
            sidePanelNotificationHistory = [...sidePanelNotificationHistory, ...loaded]
                .sort((left, right) => right.timestamp - left.timestamp)
                .filter(item => {
                    const key = item.pdfNoticeKey || JSON.stringify([item.type, item.timestamp, item.message]);
                    if (seen.has(key)) return false;
                    seen.add(key);
                    return true;
                }).slice(0, SIDE_PANEL_NOTIFICATION_HISTORY_LIMIT);
            persistSidePanelNotificationHistory();
        } else sidePanelNotificationHistory = loaded;
        sidePanelNotificationMutationRevision += 1;
        renderSidePanelNotificationHistory();
        return sidePanelNotificationHistory;
    } catch (_) {
        return [];
    }
}

function recordSidePanelNotification(message, type = 'info', timestamp = Date.now(), pdfNoticeKey = '') {
    const normalizedMessage = String(message || '').normalize('NFKC')
        .replace(/\s+/g, ' ').trim().slice(0, 600);
    if (!normalizedMessage) return null;
    const normalizedType = type === 'error' ? 'error'
        : type === 'success' ? 'success' : 'info';
    const normalizedTimestamp = Math.max(0, Number(timestamp) || 0) || Date.now();
    if (pdfNoticeKey) {
        const prior = sidePanelNotificationHistory.find(item => item.pdfNoticeKey === pdfNoticeKey);
        if (prior?.message === normalizedMessage && prior?.type === normalizedType &&
            prior.timestamp >= normalizedTimestamp) return prior;
        sidePanelNotificationHistory = sidePanelNotificationHistory.filter(item =>
            item.pdfNoticeKey !== pdfNoticeKey);
    }
    const newest = sidePanelNotificationHistory[0];
    const transientHighlightProgress = value => /(?:当前段落已完成并保存|当前小块结果已渲染|LLM 正在分析(?:正文)?|正在使用 LLM 分析)/u
        .test(String(value || ''));
    if (!pdfNoticeKey && ((newest?.message === normalizedMessage &&
        normalizedTimestamp - newest.timestamp < 1500) ||
        (transientHighlightProgress(newest?.message) &&
            transientHighlightProgress(normalizedMessage) &&
            normalizedTimestamp - newest.timestamp < 60000))) {
        // 分块进度是一个持续更新的状态，不应让 0 条候选等中间消息
        // 挤满通知历史。保留最近状态，最终完成/失败消息仍单独入列。
        newest.message = normalizedMessage;
        newest.timestamp = normalizedTimestamp;
        newest.type = normalizedType;
    } else {
        sidePanelNotificationHistory.unshift({
            message: normalizedMessage,
            type: normalizedType,
            timestamp: normalizedTimestamp,
            ...(pdfNoticeKey ? { pdfNoticeKey } : {})
        });
        sidePanelNotificationHistory =
            sidePanelNotificationHistory.slice(0, SIDE_PANEL_NOTIFICATION_HISTORY_LIMIT);
    }
    const center = document.getElementById('sidePanelNotificationCenter');
    if (center && !center.open) center.classList.add('has-unread');
    sidePanelNotificationMutationRevision += 1;
    renderSidePanelNotificationHistory();
    persistSidePanelNotificationHistory();
    return sidePanelNotificationHistory[0];
}

function isCurrentPdfReaderNoticeSender(sender) {
    return activePanelTabContext.pdfMode && activePanelTabContext.activated &&
        sender?.id === chrome.runtime.id &&
        Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
        SciLLM.normalizeTabDocumentUrl(sender?.url) === activePanelTabContext.url;
}

function renderPdfReaderNoticeActions(snapshot, panelContext) {
    const container = document.getElementById('pdfReaderNoticeActions');
    if (!container) return;
    container.replaceChildren();
    const actions = (snapshot?.actions || []).filter(action =>
        ['pdfReaderRetry', 'pdfReaderOpenSettings'].includes(action.id));
    container.hidden = !actions.length;
    for (const action of actions) {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = action.label;
        button.addEventListener('click', async () => {
            if (!isCurrentPanelContext(panelContext) || pdfReaderNoticeState?.snapshot !== snapshot) return;
            button.disabled = true;
            try {
                const result = await sendTabMessage(panelContext.tabId, {
                    action: 'runPdfReaderNoticeAction', id: action.id, scope: snapshot
                });
                if (!isCurrentPanelContext(panelContext) || pdfReaderNoticeState?.snapshot !== snapshot) return;
                if (!result?.success) showStatus(result?.error?.message || 'PDF 操作未完成，请重试。', 'error');
                await refreshPdfReaderNotices();
            } catch (error) {
                if (isCurrentPanelContext(panelContext) && pdfReaderNoticeState?.snapshot === snapshot) {
                    showStatus(error.message, 'error');
                }
            } finally { button.disabled = false; }
        });
        container.appendChild(button);
    }
}

async function refreshPdfReaderNotices() {
    if (!activePanelTabContext.pdfMode || !activePanelTabContext.activated) return null;
    const context = capturePanelContext();
    const requestSequence = ++pdfReaderNoticeRequestSequence;
    const snapshot = await SciLLM.sendTabMessageIfPresent(chrome, context.tabId,
        { action: 'getPdfReaderNotices' }).catch(() => null);
    if (requestSequence !== pdfReaderNoticeRequestSequence || !isCurrentPanelContext(context) ||
        !snapshot?.success || !snapshot.readerInstanceId ||
        SciLLM.normalizeTabDocumentUrl(snapshot.readerUrl) !== context.url ||
        !Array.isArray(snapshot.notices)) return null;
    const sourceKey = `${snapshot.sourceUrl}|${snapshot.documentHash ||
        `${snapshot.readerInstanceId}:${snapshot.sourceEpoch}`}`;
    const historyKey = `${activePanelTabContext.key}|pdf:${sourceKey}`;
    const newDocument = historyKey !== pdfReaderNoticeState?.historyKey;
    const historyLoaded = !newDocument && pdfReaderNoticeState?.historyLoaded;
    pdfReaderNoticeState = { panelKey: activePanelTabContext.key, historyKey, snapshot, historyLoaded };
    if (newDocument) {
        sidePanelNotificationHistory = [];
        sidePanelNotificationMutationRevision += 1;
        renderSidePanelNotificationHistory();
    }
    if (!historyLoaded) {
        await loadSidePanelNotificationHistory(historyKey, () =>
            requestSequence === pdfReaderNoticeRequestSequence && isCurrentPanelContext(context));
        if (requestSequence !== pdfReaderNoticeRequestSequence || !isCurrentPanelContext(context)) return null;
        pdfReaderNoticeState.historyLoaded = true;
    }
    for (const notice of snapshot.notices.slice(0, 6)) {
        if (!['reader', 'quota', 'figure', 'save', 'remote-source', 'embed'].includes(notice.id)) continue;
        recordSidePanelNotification(notice.message, notice.type, notice.timestamp,
            `pdf:${notice.id}:${notice.type}`);
    }
    renderPdfReaderNoticeActions(snapshot, context);
    return snapshot;
}

function closeSidePanelDisclosureOnEscape(event, details, trigger) {
    if (event?.key !== 'Escape' || details?.open !== true) return false;
    event.preventDefault?.();
    details.open = false;
    trigger?.focus?.();
    return true;
}

function setupSidePanelNotificationCenter() {
    const center = document.getElementById('sidePanelNotificationCenter');
    const summary = document.getElementById('sidePanelNotificationSummary');
    if (!center) return;
    center.addEventListener('toggle', () => {
        if (center.open) center.classList.remove('has-unread');
    });
    document.addEventListener('pointerdown', event => {
        if (center.open && !center.contains(event.target)) center.open = false;
    });
    document.addEventListener('keydown', event => {
        closeSidePanelDisclosureOnEscape(event, center, summary);
    });
    renderSidePanelNotificationHistory();
}

function setupSidePanelMoreTools() {
    const details = document.getElementById('sidePanelMoreTools');
    const summary = document.getElementById('sidePanelMoreToolsSummary');
    const menu = details?.querySelector('.side-panel-more-tools-menu');
    if (!details || !summary || !menu) return;
    document.addEventListener('pointerdown', event => {
        if (details.open && !details.contains(event.target)) details.open = false;
    });
    document.addEventListener('keydown', event => {
        closeSidePanelDisclosureOnEscape(event, details, summary);
    });
    menu.addEventListener('click', event => {
        if (!event.target.closest('button[role="menuitem"]')) return;
        setTimeout(() => { details.open = false; }, 0);
    });
}

function cacheCurrentPanelTabState() {
    const key = activePanelTabContext.key;
    if (!key || !activePanelTabContext.activated || !currentWorkspaceSnapshot ||
        ['preparing', 'analyzing'].includes(prepareState)) return;
    panelTabStateCache.delete(key);
    panelTabStateCache.set(key, {
        preparedDocumentState,
        currentArticleDocument,
        prepareState,
        manualAnnotationState: { ...manualAnnotationState },
        matchCounts: { ...matchCounts },
        activeWorkspaceView,
        workspaceGeneration,
        currentWorkspaceSnapshot,
        articleChatVisibleTurnCount,
        currentArticleArchiveProbe,
        sidePanelNotificationHistory: sidePanelNotificationHistory.map(item => ({ ...item })),
        visibleHighlightSources: [...visibleHighlightSources],
        figureAnalysisState: { ...figureAnalysisState },
        figureMetaExpansion: normalizeFigureMetaExpansionEntries(
            [...figureMetaExpansionState.entries()]
        ),
        figureOverviewExpansion: [...figureOverviewExpansionState.entries()],
        reviewOutlineState: { ...reviewOutlineState }
    });
    while (panelTabStateCache.size > PANEL_TAB_STATE_CACHE_LIMIT) {
        panelTabStateCache.delete(panelTabStateCache.keys().next().value);
    }
}

function resetPanelArticleState() {
    const resetContext = () => {
        literatureNoteDocumentState = null;
        literatureNoteTemplateSelection = null;
        literatureNoteTemplateSelectionBase = { templateId: '', updatedAt: 0 };
        literatureNoteTemplateSelectionConflict = false;
        literatureNoteTemplateChangeSequence += 1;
        literatureNoteDirtyFields.clear();
        literatureNoteDirtyRevisions.clear();
        literatureNoteFieldEditVersions.clear();
        literatureNoteSaveTimer = null;
        closeLiteratureNoteDrawer();
    };
    if (literatureNoteDocumentState) {
        const leave = flushLiteratureNoteBeforeContextLeave({
            cancelScheduledSave: () => {
                clearTimeout(literatureNoteSaveTimer);
                literatureNoteSaveTimer = null;
            },
            enqueueSave: reserveLiteratureNoteDocumentStatePersistence,
            resetContext,
            showWarning: () => {
                const status = document.getElementById('literatureNoteStatus');
                if (status) status.textContent = t(
                    '笔记保存队列已满，请稍后重试'
                );
            }
        });
        if (!leave.accepted) return false;
    } else {
        clearTimeout(literatureNoteSaveTimer);
        resetContext();
    }
    replaceMechanismGenerationUiController();
    cancelActiveSupplementalPlacementDrag('context-switch');
    disposeSupplementalPlacementBindings();
    articlePreparationSequence += 1;
    workspaceRefreshSequence += 1;
    articleStructureRefreshCoordinator?.invalidate();
    manualSummarySequence += 1;
    regexApplySequence += 1;
    preferenceMutationCoordinator.beginIntent();
    stopFigureProgressPolling();
    figureWorkspaceProgressSignature = '';
    figureProgressRenderSignature = '';
    figureExpansionState.clear();
    figurePanelExpansionState.clear();
    figureWorkspaceViewState.clear();
    figureMetaExpansionState.clear();
    figureOverviewExpansionState.clear();
    figureSectionExpansionState.clear();
    figureEvidenceExpansionState.clear();
    panelFollowupDraftState.clear();
    figureQuickNavActiveId = '';
    figureQuickNavExpandedFigureId = '';
    figureKeyboardShortcutArmed = false;
    lastFigureModuleShortcutPress = {
        key: '',
        pressedAt: 0
    };
    figureOriginalViewerState = {
        open: false,
        tabId: null,
        figureId: '',
        captionVisible: false,
        requestSequence: figureOriginalViewerState.requestSequence + 1
    };
    figureCaptionSidebarState = {
        visible: false,
        figureId: ''
    };
    clearTimeout(figureQuickNavHoverTimer);
    figureQuickNavHoverTimer = null;
    articleChatTurnElements.clear();
    articleChatVisibleTurnCount = articleChatHistoryPageSize;
    articleChatFollowLatest = true;
    articleChatRenderedDocumentKey = '';
    articleChatScrollToLatestActive = false;
    stopReviewOutlineProgressPolling();
    figureTaskGeneration += 1;
    reviewOutlineTaskGeneration += 1;
    paragraphSummaryTaskGeneration += 1;
    abbreviationDialogRequestSequence += 1;
    figureAnalysisState = {
        running: false, phase: 'idle', currentFigure: 0, totalFigures: 0,
        completedFigures: 0, failedFigures: 0, figureLabel: '', message: '', figureProgress: []
    };
    crossFigureLogicRunning = false;
    mechanismChainLlmRequestKey = '';
    mechanismNetworkViewController.clear();
    mechanismNetworkMeasuredSizes.clear();
    mechanismNetworkLayoutCache.clear();
    mechanismNetworkMeasurementScheduler.clear();
    mechanismNetworkResizeController.clear();
    workspaceParagraphSummaryState.clear();
    reviewOutlineState = {
        running: false, phase: 'idle', completedParagraphs: 0, totalParagraphs: 0,
        completedChunks: 0, totalChunks: 0, message: '', hasOutline: false,
        globalSynthesisAvailable: null
    };
    preparedDocumentState = null;
    currentArticleDocument = null;
    prepareState = 'idle';
    manualAnnotationState = {
        tabId: null,
        documentId: '',
        documentHash: '',
        canonicalUrl: '',
        title: '',
        annotationCount: 0,
        unresolvedCount: 0
    };
    matchCounts = {};
    activeWorkspaceView = 'navigation';
    workspaceGeneration = 1;
    clearTimeout(workspaceUiSaveTimer);
    workspaceUiSaveTimer = null;
    currentWorkspaceSnapshot = null;
    updatePopupPdfSemanticNavigation(null, null);
    currentArticleAbbreviationSnapshot = {
        entries: [],
        automaticCount: 0,
        manualCount: 0,
        globalCount: 0,
        excludedCount: 0,
        translatedCount: 0,
        documentKey: '',
        tabId: null
    };
    const abbreviationDialog = document.getElementById('articleAbbreviationDialog');
    if (abbreviationDialog?.open) abbreviationDialog.close();
    currentArticleArchiveProbe = null;
    sidePanelNotificationHistory = [];
    sidePanelNotificationMutationRevision += 1;
    pdfReaderNoticeState = null;
    pdfReaderNoticeRequestSequence += 1;
    renderPdfReaderNoticeActions(null, null);
    visibleHighlightSources = new Set(HIGHLIGHT_SOURCE_FILTERS);
    renderSidePanelNotificationHistory();
    lastArticlePreparationError = null;
    setArticleArchivePrompt(null);
    renderArticleNavigationTree(null);
    renderEvidenceLedger(null);
    renderHighlightDistributionSnapshot(null);
    renderFigureWorkspaceSnapshot(null);
    renderArticleChatSnapshot(null);
    renderManualAnnotationSummary();
    renderCategories();
    updateApplyButton();
    switchWorkspaceView('navigation', { persist: false });
    return true;
}

function isCurrentFigureTask(token, tabId) {
    return token === figureTaskGeneration &&
        Number(tabId) === Number(activePanelTabContext.tabId);
}

function renderInactiveTabState(tab = null) {
    document.getElementById('sidePanelApp')?.classList.add('is-tab-inactive');
    const title = document.getElementById('sidePanelPaperTitle');
    const statusText = document.getElementById('sidePanelDocumentStatusText');
    const status = document.getElementById('sidePanelDocumentStatus');
    const navigationStatus = document.getElementById('articleNavigationStatus');
    const retry = document.getElementById('retryArticlePreparation');
    if (title) title.textContent = tab?.title || '当前页面';
    if (statusText) statusText.textContent = '此标签页尚未激活，点击侧栏任意位置即可激活';
    if (navigationStatus) navigationStatus.textContent = '点击侧栏后读取当前论文结构';
    status?.classList.remove('is-error', 'is-ready');
    status?.classList.add('is-idle');
    if (retry) retry.hidden = true;
}

async function activateCurrentTabFromSidePanel() {
    if (activePanelTabContext.activated) return true;
    if (inactiveTabActivationPromise) return inactiveTabActivationPromise;
    inactiveTabActivationPromise = (async () => {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前标签页');
        const statusText = document.getElementById('sidePanelDocumentStatusText');
        if (statusText) {
            statusText.textContent = SciLLM.isLikelyPdfUrl?.(
                tab.url || tab.pendingUrl,
                tab.title
            )
                ? '正在激活并准备解析当前 PDF…'
                : '正在激活当前标签页…';
        }
        const response = await chrome.runtime.sendMessage({
            type: 'SIDE_PANEL_ACTIVATE_CURRENT_TAB',
            tabId: tab.id,
            url: SciLLM.normalizeTabDocumentUrl(tab.url || tab.pendingUrl)
        });
        if (!response?.success) {
            throw new Error(response?.error?.message || '激活当前标签页失败');
        }
        await synchronizeActiveTabContext({ force: true });
        return true;
    })().catch(error => {
        renderInactiveTabState();
        showStatus(`激活当前标签页失败：${error.message}`, 'error');
        return false;
    }).finally(() => {
        inactiveTabActivationPromise = null;
    });
    return inactiveTabActivationPromise;
}

function setupInactiveTabClickActivation() {
    document.addEventListener('click', event => {
        if (!panelUiReady || activePanelTabContext.activated ||
            inactiveTabActivationPromise) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        void activateCurrentTabFromSidePanel();
    }, true);
}

function restorePanelTabState(cached) {
    preparedDocumentState = cached.preparedDocumentState || null;
    currentArticleDocument = cached.currentArticleDocument || null;
    prepareState = cached.prepareState || 'idle';
    manualAnnotationState = { ...cached.manualAnnotationState };
    matchCounts = { ...cached.matchCounts };
    activeWorkspaceView = cached.activeWorkspaceView || 'navigation';
    workspaceGeneration = Math.max(1, Number(cached.workspaceGeneration) || 1);
    currentWorkspaceSnapshot = cached.currentWorkspaceSnapshot || null;
    updatePopupPdfSemanticNavigation(null, currentWorkspaceSnapshot);
    articleChatVisibleTurnCount = Math.max(
        articleChatHistoryPageSize,
        Number(cached.articleChatVisibleTurnCount) ||
            Number(currentWorkspaceSnapshot?.chat?.turns?.length) || 0
    );
    currentArticleArchiveProbe = cached.currentArticleArchiveProbe || null;
    sidePanelNotificationHistory = (Array.isArray(cached.sidePanelNotificationHistory)
        ? cached.sidePanelNotificationHistory : []).map(item => ({ ...item }));
    sidePanelNotificationMutationRevision += 1;
    visibleHighlightSources = new Set(
        (Array.isArray(cached.visibleHighlightSources)
            ? cached.visibleHighlightSources : HIGHLIGHT_SOURCE_FILTERS)
            .filter(source => HIGHLIGHT_SOURCE_FILTERS.includes(source))
    );
    restoreFigureMetaExpansionState(
        figureMetaExpansionState, cached.figureMetaExpansion
    );
    restoreFigureOverviewExpansionState(cached.figureOverviewExpansion);
    renderSidePanelNotificationHistory();
    reviewOutlineState = { ...reviewOutlineState, ...cached.reviewOutlineState };
    document.getElementById('sidePanelApp')?.classList.remove('is-tab-inactive');
    renderArticleWorkspaceSnapshot(currentWorkspaceSnapshot);
    resumeFigureProgressFromWorkspaceSnapshot(currentWorkspaceSnapshot);
    setArticleArchivePrompt(currentArticleArchiveProbe);
    renderManualAnnotationSummary();
    syncPreparedSelection();
    renderCategories();
    updateApplyButton();
    switchWorkspaceView(activeWorkspaceView, { persist: false });
}

async function synchronizeActiveTabContext({ force = false } = {}) {
    if (!panelUiReady) return null;
    const requestId = ++tabContextRequestSequence;
    const tab = await queryPanelTargetTab();
    if (requestId !== tabContextRequestSequence) return null;
    const key = panelTabDocumentKey(tab);
    const activated = Boolean(key &&
        await SciLLM.isTabActivated(chrome.storage.session, tab));
    if (requestId !== tabContextRequestSequence) return null;
    if (!force && activePanelTabContext.key === key &&
        activePanelTabContext.activated === activated) {
        void publishSidePanelShortcutScope(tab?.id, activated);
        return activePanelTabContext;
    }

    const editorLeaveResult = await figureWorkspaceEditorLifecycle.leaveContext();
    if (requestId !== tabContextRequestSequence) return null;

    const previousTabId = activePanelTabContext.tabId;
    const previousActivated = activePanelTabContext.activated;
    cacheCurrentPanelTabState();
    if (!resetPanelArticleState()) {
        void scheduleContextSyncAfterDrain({
            drain: literatureNotePersistenceCoordinator.whenDrained(),
            generation: requestId,
            currentGeneration: () => tabContextRequestSequence,
            schedule: () => scheduleActiveTabContextSync({ force: true })
        });
        return activePanelTabContext;
    }
    tabContextSequence += 1;
    activePanelTabContext = {
        tabId: tab?.id ?? null,
        url: SciLLM.normalizeTabDocumentUrl(tab?.url || tab?.pendingUrl),
        key,
        activated,
        pdfMode: SciLLM.isPdfReaderUrl?.(tab?.url || tab?.pendingUrl) === true,
        tabContextSequence
    };
    if (previousActivated && Number(previousTabId) !== Number(tab?.id)) {
        void publishSidePanelShortcutScope(previousTabId, false);
    }
    void publishSidePanelShortcutScope(tab?.id, activated);
    if (figureWorkspaceUnsavedContextWarning &&
        !['saved', 'unchanged', 'idle'].includes(editorLeaveResult?.status)) {
        showStatus(figureWorkspaceUnsavedContextWarning, 'error');
    }

    if (!activated) {
        renderInactiveTabState(tab);
        return activePanelTabContext;
    }

    document.getElementById('sidePanelApp')?.classList.remove('is-tab-inactive');
    if (activePanelTabContext.pdfMode) {
        await refreshPdfReaderNotices();
        if (requestId !== tabContextRequestSequence) return null;
        const pdfWorkspace = await sendTabMessage(tab.id, {
            action: 'getPdfWorkspaceState'
        }).catch(() => null);
        if (requestId !== tabContextRequestSequence) return null;
        if (!pdfWorkspace?.ready) {
            const failed = pdfWorkspace?.state === 'error';
            if (!failed && pdfWorkspace?.nativeReadable &&
                pdfWorkspace?.state === 'idle') {
                await loadSidePanelNotificationHistory();
                if (requestId !== tabContextRequestSequence) return null;
                renderNativePdfReadingBaseline(pdfWorkspace, tab);
                updateApplyButton();
                return activePanelTabContext;
            }
            renderArticleConnectionStage(
                failed
                    ? 'PDF 读取或索引失败，请查看右侧通知中的详情并重试'
                    : '正在读取 PDF 原页与文字索引；完成后会自动连接…',
                tab?.title || '文献 PDF'
            );
            updateApplyButton();
            return activePanelTabContext;
        }
    }
    const cached = !force && !activePanelTabContext.pdfMode ? panelTabStateCache.get(key) : null;
    if (cached) {
        panelTabStateCache.delete(key);
        panelTabStateCache.set(key, cached);
        restorePanelTabState(cached);
        void refreshArticleWorkspace();
        return activePanelTabContext;
    }

    await loadSidePanelNotificationHistory();
    if (requestId !== tabContextRequestSequence) return null;
    const snapshot = await initializeCurrentArticle();
    if (requestId === tabContextRequestSequence && snapshot) cacheCurrentPanelTabState();
    return activePanelTabContext;
}

function scheduleActiveTabContextSync(options = {}) {
    clearTimeout(tabContextSyncTimer);
    tabContextSyncTimer = setTimeout(() => {
        tabContextSyncTimer = null;
        void synchronizeActiveTabContext(options);
    }, 0);
}

function ensureArticleStructureRefreshCoordinator() {
    if (articleStructureRefreshCoordinator) return articleStructureRefreshCoordinator;
    articleStructureRefreshCoordinator = createArticleStructureRefreshCoordinator({
        refresh(_message, panelContext) {
            if (!isCurrentPanelContext(panelContext)) return null;
            return refreshArticleWorkspace({ panelContext });
        }
    });
    return articleStructureRefreshCoordinator;
}

function setupActiveTabSynchronization() {
    chrome.tabs.onActivated.addListener(() => scheduleActiveTabContextSync());
    chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
        if (changeInfo.url) {
            scheduleActiveTabContextSync();
        } else if (changeInfo.status === 'complete' &&
            tabId === activePanelTabContext.tabId) {
            scheduleActiveTabContextSync({ force: true });
        }
    });
    chrome.tabs.onRemoved.addListener(tabId => {
        const prefix = `${Number(tabId)}|`;
        [...panelTabStateCache.keys()].forEach(key => {
            if (key.startsWith(prefix)) panelTabStateCache.delete(key);
        });
    });
    function formatPanelLlmOperationProgress(value = {}) {
        const phase = String(value.phase || '');
        const elapsed = Math.max(0, Number(value.elapsedSeconds) || 0);
        const timeout = Math.max(0, Number(value.timeoutSeconds) || 0);
        const completed = Math.max(0, Number(value.completed) || 0);
        const total = Math.max(0, Number(value.total) || 0);
        if (phase === 'provider_request_started') {
            return timeout ? `已向模型发送请求，最长等待 ${timeout} 秒…` : '已向模型发送请求…';
        }
        if (phase === 'provider_waiting') {
            return `模型正在处理（已等待 ${elapsed} 秒${timeout ? `，最长 ${timeout} 秒` : ''}）…`;
        }
        const messages = {
            literature_note_requesting: '正在发送当前论文的正文证据…',
            literature_note_compact_retry: '请求暂时失败，正在压缩正文证据后重试…',
            literature_note_schema_retry: '模型返回格式不完整，正在自动修复…',
            literature_note_fail_closed: '正在保留有正文来源的字段，并将其余字段标为缺失…',
            literature_note_complete: '模型已返回，正在核验证据并填写模板…',
            cross_figure_logic: '正在梳理跨图研究逻辑…',
            mechanism_vocabulary: '正在提取机制节点词表…',
            mechanism_vocabulary_repair: '机制节点词表格式不完整，正在进行一次有界修复…',
            mechanism_edge_batch_repair: '当前 Panel 批次格式不完整，正在进行一次有界修复…',
            mechanism_coverage_repair: '正在修复 Panel 覆盖关系…',
            mechanism_coverage_fail_closed: '正在保留已验证关系并收敛未覆盖 Panel…'
        };
        if (phase === 'mechanism_edges') {
            return total ? `正在生成 Panel 机制关系（${completed}/${total}）…`
                : '正在生成 Panel 机制关系…';
        }
        return messages[phase] || '';
    }

    chrome.runtime.onMessage.addListener((message, sender) => {
        if (message?.type === 'PANEL_TAB_ACTIVATED') {
            scheduleActiveTabContextSync();
        }
        if (message?.type === 'ARTICLE_WORKSPACE_SAVE_PROGRESS' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId)) {
            renderArticleWorkspaceSaveProgress(message);
        }
        if (message?.type === 'LLM_OPERATION_PROGRESS' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            const progress = mechanismGenerationOwnData(message, 'progress');
            const taskType = mechanismGenerationOwnData(progress, 'taskType');
            if (taskType === 'crossFigure' &&
                Number(sender?.tab?.id) === Number(activeMechanismGenerationTabId)) {
                const progressStatus = mechanismGenerationOwnData(progress, 'status');
                const terminal = ['complete', 'needs_review', 'failed', 'cancelled',
                    'revision_conflict'].includes(progressStatus);
                const accepted = terminal
                    ? mechanismGenerationUiController.complete(progress)
                    : mechanismGenerationUiController.progress(progress);
                if (accepted) renderMechanismGenerationStatus();
            } else {
                if (taskType === 'highlight' && highlightTaskState.running) {
                    highlightTaskState = {
                        ...highlightTaskState,
                        phase: String(progress?.phase || ''),
                        completed: Math.max(0, Number(progress?.completed) || 0),
                        total: Math.max(0, Number(progress?.total) || 0)
                    };
                    updateApplyButton();
                }
                const progressMessage = formatPanelLlmOperationProgress(message.progress);
                if (progressMessage) {
                    showStatus(progressMessage, 'success');
                    if (String(message.progress?.phase || '').startsWith('literature_note_') ||
                        (literatureNoteAutofillPromise &&
                            ['provider_request_started', 'provider_waiting']
                                .includes(String(message.progress?.phase || '')))) {
                        updateLiteratureNoteOperationProgress(message.progress);
                        const noteStatus = document.getElementById('literatureNoteStatus');
                        if (noteStatus) noteStatus.textContent = progressMessage;
                    }
                }
            }
        }
        if (message?.type === 'PDF_WORKSPACE_READY' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            showStatus(
                `PDF 已准备完成：${Number(message.paragraphCount) || 0} 个段落、` +
                    `${Number(message.figureCount) || 0} 张 Figure；全文问答和图解现在可用` +
                    (message.mineruQuotaText ? `。${message.mineruQuotaText}` : ''),
                'success'
            );
            scheduleActiveTabContextSync({ force: true });
        }
        if (message?.type === 'PDF_WORKSPACE_INDEXED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            showStatus(
                `PDF 已建立统一索引：${Number(message.paragraphCount) || 0} 个段落、` +
                    `${Number(message.figureCount) || 0} 张完整 Figure；五个模块现在共用同一份正文`,
                'success'
            );
            scheduleActiveTabContextSync({ force: true });
        }
        if (message?.type === 'PDF_WORKSPACE_ERROR' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId)) {
            showStatus(
                message.scope === 'enhancement'
                    ? `PDF 增强识别未完成：${String(message.message || message.error || '请重试').slice(0, 350)}`
                    : `PDF 解析未完成：${String(message.error || '请返回文献页查看具体原因').slice(0, 250)}`,
                'error'
            );
        }
        if (message?.type === 'SIDE_PANEL_GLOBAL_SHORTCUT' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            runGlobalKeyboardShortcutKey(String(message.key || ''));
        }
        if (message?.type === 'ARTICLE_STRUCTURE_CHANGED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            ensureArticleStructureRefreshCoordinator().enqueue(
                message,
                sender.tab.id,
                capturePanelContext()
            );
        }
        if (message?.type === 'ABBREVIATION_MEMORY_CHANGED') {
            const dialog = document.getElementById('articleAbbreviationDialog');
            void refreshGlobalAbbreviationMemoryCount()
                .then(() => {
                    if (dialog?.open) return showArticleAbbreviationTable();
                    return null;
                })
                .catch(() => {});
        }
        if (message?.type === 'ARTICLE_ABBREVIATIONS_CHANGED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            const dialog = document.getElementById('articleAbbreviationDialog');
            if (dialog?.open) void showArticleAbbreviationTable();
        }
        if (message?.type === 'ARTICLE_CHAT_STATE_CHANGED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            applyArticleChatStateEvent(message.event);
        }
        if (message?.type === 'ARTICLE_CHAT_OPEN_REQUESTED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            closeLiteratureNoteDrawer();
            switchWorkspaceView('chat');
            document.getElementById('articleChatQuestion')?.focus();
        }
        if (message?.type === 'FIGURE_WORKSPACE_STATE_CHANGED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            void refreshArticleWorkspace();
        }
        if (message?.type === 'FIGURE_ORIGINAL_VIEWER_STATE_CHANGED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
            const preserveCrossFigureSidebar =
                shouldPreserveCrossFigureSidebar(message.navigationMode);
            figureOriginalViewerState = {
                open: message.open === true,
                tabId: sender.tab.id,
                figureId: String(message.figureId || ''),
                captionVisible: message.captionVisible === true,
                requestSequence: figureOriginalViewerState.requestSequence + 1
            };
            if (message.open === true && message.captionVisible === true &&
                message.figureId) {
                showFigureCaptionSidebar(String(message.figureId));
            } else if (previousCaptionVisible) {
                hideFigureCaptionSidebar(String(message.figureId || ''));
            } else if (message.open === true && message.figureId &&
                !preserveCrossFigureSidebar) {
                followFigureOriginalViewerInSidebar(String(message.figureId));
            }
        }
        if (message?.type === 'MANUAL_ANNOTATION_STATE_CHANGED' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            const applied = applyManualAnnotationStateEvent(message.event, sender.tab.id);
            if (applied) {
                void refreshArticleWorkspace();
            } else {
                void refreshManualAnnotationSummaryAfterUnverifiedEvent(sender.tab.id);
            }
        }
        if (message?.type === 'PDF_READER_NOTICES_CHANGED' &&
            isCurrentPdfReaderNoticeSender(sender)) {
            // Pull from the current reader; never record a delayed event's message payload.
            void refreshPdfReaderNotices();
        }
        if (message?.type === 'ARTICLE_NOTIFICATION' &&
            Number(sender?.tab?.id) === Number(activePanelTabContext.tabId) &&
            activePanelTabContext.activated) {
            recordSidePanelNotification(
                message.message,
                message.level,
                message.timestamp
            );
        }
    });
}

function createSidebarFocusModeController({
    root,
    announcementElement = null,
    statusElement = null,
    documentRef = typeof document === 'object' ? document : null,
    requestFrame = callback => (
        typeof requestAnimationFrame === 'function'
            ? requestAnimationFrame(callback)
            : callback()
    ),
    shouldDeferEscape = () => false,
    MutationObserverCtor = typeof MutationObserver === 'function' ? MutationObserver : null
} = {}) {
    if (!root || !documentRef) return null;
    const focusClass = 'is-sidebar-focus-mode';
    let active = root.classList.contains(focusClass);
    let languageObserver = null;
    let statusObserver = null;

    const currentAnnouncement = () => {
        const english = String(documentRef.documentElement?.lang || '')
            .toLowerCase().startsWith('en');
        if (english) {
            return active ? 'Focus mode on. Toggle with your shortcut, or press Escape to exit.' : '';
        }
        return active ? '专注阅读已开启；按专用快捷键切换，或按 Esc 退出。' : '';
    };
    const sync = () => {
        const announcement = currentAnnouncement();
        if (announcementElement && announcementElement.textContent !== announcement) {
            announcementElement.textContent = announcement;
        }
    };
    const syncEssentialStatus = () => {
        if (!statusElement) return;
        const text = String(statusElement.textContent || '').trim();
        const retry = statusElement.querySelector?.('#retryArticlePreparation');
        const essential = statusElement.classList?.contains('is-error') ||
            (retry && retry.hidden === false) ||
            /仅公开预览|public\s+preview|正在|读取中|加载中|提取中|prepar|loading|extract|失败|错误|error|不可用|unavailable/iu.test(text);
        statusElement.toggleAttribute('data-sidebar-focus-essential', Boolean(essential));
    };
    const scrollRegions = () => Array.from(new Set(root.querySelectorAll(
        '[data-sidebar-focus-scroll], .workspace-view, #articleChatMessages, .literature-note-form'
    )));
    const preserveScrollAcrossLayout = changeLayout => {
        const positions = scrollRegions().map(element => [element, element.scrollTop]);
        changeLayout();
        requestFrame(() => {
            positions.forEach(([element, scrollTop]) => {
                if (element?.isConnected === false) return;
                element.scrollTop = scrollTop;
            });
        });
    };
    const setActive = nextValue => {
        const next = nextValue === true;
        if (next === active) {
            sync();
            return active;
        }
        preserveScrollAcrossLayout(() => {
            active = next;
            root.classList.toggle(focusClass, active);
            sync();
        });
        return active;
    };
    const toggle = () => setActive(!active);
    const hasExistingEscapeTarget = event => {
        if (event?.defaultPrevented || event?.isComposing) return true;
        if (event?.target?.closest?.(
            'input, textarea, select, [contenteditable="true"], ' +
            '[contenteditable="plaintext-only"]'
        )) return true;
        const priorityTargets = documentRef.querySelectorAll?.(
            'dialog[open], details[data-sidebar-focus-escape-priority][open], ' +
            '[data-sidebar-focus-escape-priority]:not(details):not([hidden])'
        ) || [];
        return Array.from(priorityTargets).some(element => {
            if (typeof element.checkVisibility === 'function') {
                return element.checkVisibility({
                    checkOpacity: true,
                    checkVisibilityCSS: true
                });
            }
            return typeof element.getClientRects !== 'function' ||
                element.getClientRects().length > 0;
        });
    };
    const handleKeydown = event => {
        if (event?.key !== 'Escape' || !active || hasExistingEscapeTarget(event) ||
            shouldDeferEscape(event)) return;
        event.preventDefault?.();
        setActive(false);
    };

    documentRef.addEventListener('keydown', handleKeydown);
    if (MutationObserverCtor && documentRef.documentElement) {
        languageObserver = new MutationObserverCtor(sync);
        languageObserver.observe(documentRef.documentElement, {
            attributes: true,
            attributeFilter: ['lang']
        });
    }
    if (MutationObserverCtor && statusElement) {
        statusObserver = new MutationObserverCtor(syncEssentialStatus);
        statusObserver.observe(statusElement, {
            attributes: true,
            attributeFilter: ['class', 'hidden'],
            childList: true,
            characterData: true,
            subtree: true
        });
    }
    syncEssentialStatus();
    sync();
    return {
        isActive: () => active,
        setActive,
        toggle,
        sync,
        destroy() {
            documentRef.removeEventListener('keydown', handleKeydown);
            languageObserver?.disconnect();
            statusObserver?.disconnect();
        }
    };
}

let sidebarFocusModeController = null;

function sidebarFocusEscapeHasPriority() {
    if (activeWorkspaceView !== 'mechanism') return false;
    if (figureWorkspaceInlineEditController.getState()?.active) return true;
    const state = mechanismNetworkViewController.getState();
    return Boolean(state?.selectedNodeId || state?.selectedEdgeId || state?.focusEnabled);
}

function setupSidebarFocusMode() {
    if (sidebarFocusModeController) return sidebarFocusModeController;
    sidebarFocusModeController = createSidebarFocusModeController({
        root: document.getElementById('sidePanelApp'),
        announcementElement: document.getElementById('sidebarFocusAnnouncement'),
        statusElement: document.getElementById('sidePanelDocumentStatus'),
        shouldDeferEscape: sidebarFocusEscapeHasPriority
    });
    return sidebarFocusModeController;
}

function switchWorkspaceView(viewId, { persist = true, loadNotes = true } = {}) {
    // Keep saved r14 state and existing analysis shortcuts usable after consolidation.
    const requested = viewId === 'analysis' ? 'highlights' : viewId;
    const target = ['navigation', 'highlights', 'figures', 'mechanism', 'chat', 'notes'].includes(requested)
        ? requested : 'navigation';
    literatureNoteOpenSequence += 1;
    activeWorkspaceView = target;
    if (viewId === 'analysis') {
        const controls = document.getElementById('highlightControls');
        if (controls) controls.open = true;
    }
    document.getElementById('sidePanelApp')?.classList.toggle(
        'is-mechanism-view', target === 'mechanism'
    );
    document.querySelectorAll('[data-workspace-view]').forEach(view => {
        const active = view.dataset.workspaceView === target;
        view.hidden = !active;
        view.classList.toggle('active', active);
    });
    const navigationTarget = target === 'mechanism' ? 'figures' : target;
    document.querySelectorAll('[data-workspace-target]').forEach(button => {
        const selected = button.dataset.workspaceTarget === navigationTarget;
        button.setAttribute('aria-selected', String(selected));
        button.tabIndex = selected ? 0 : -1;
        if (button.dataset.workspaceTarget === 'figures') {
            button.setAttribute('aria-controls', target === 'mechanism'
                ? 'workspace-mechanism' : 'workspace-figures');
        }
    });
    const figurePanelHeaderFieldsControl = document.getElementById(
        'figurePanelHeaderFieldsControl'
    );
    if (figurePanelHeaderFieldsControl) {
        figurePanelHeaderFieldsControl.hidden = target !== 'figures';
        if (target !== 'figures') closeFigurePanelHeaderFieldsMenu();
    }
    document.querySelectorAll('[data-workspace-tools]').forEach(tools => {
        tools.hidden = tools.dataset.workspaceTools !== target;
    });
    sidebarFocusModeController?.sync();
    if (persist) scheduleActiveWorkspaceUiStateSave();
    if (target === 'notes' && loadNotes) {
        void openLiteratureNoteDrawer({ activate: false }).catch(error => {
            showStatus(`笔记加载失败：${error.message}`, 'error');
        });
    }
}

function scheduleActiveWorkspaceUiStateSave() {
    clearTimeout(workspaceUiSaveTimer);
    const workspace = currentWorkspaceSnapshot?.localWorkspace;
    const tabId = activePanelTabContext.tabId;
    if (!workspace?.workspaceId || !activePanelTabContext.activated || !tabId) return;
    workspaceUiSaveTimer = setTimeout(() => {
        workspaceUiSaveTimer = null;
        const uiState = {
            activeWorkspaceView,
            figureExpansion: [...figureExpansionState.entries()],
            figurePanelExpansion: [...figurePanelExpansionState.entries()],
            figureMetaExpansion: [...figureMetaExpansionState.entries()],
            figureOverviewExpansion: [...figureOverviewExpansionState.entries()]
        };
        void sendTabMessage(tabId, {
            action: 'saveArticleWorkspaceUiState',
            relativePath: 'ui/state.json',
            uiState
        }).catch(() => undefined);
    }, 160);
}

function setAllOutlineLevelsExpanded(expanded) {
    const container = document.getElementById('articleNavigationTree');
    if (!container) return;
    if (!expanded) {
        container.querySelectorAll('details.workspace-tree-node')
            .forEach(details => { details.open = false; });
        return;
    }
    container.querySelectorAll('details.workspace-tree-node:not([data-leaf="true"])')
        .forEach(details => { details.open = true; });
}

function setAllFigureLevelsExpanded(expanded) {
    const container = document.getElementById('figureWorkspace');
    if (!container) return;
    container.querySelectorAll('details.workspace-figure-card').forEach(details => {
        details.open = expanded;
        if (details.dataset.figureId) {
            figureExpansionState.set(details.dataset.figureId, expanded);
        }
    });
    if (!expanded) {
        container.querySelectorAll('details.workspace-figure-panel-card').forEach(details => {
            details.open = false;
            figurePanelExpansionState.set(
                panelWorkspaceKey(details.dataset.figureId, details.dataset.panelId), false
            );
        });
    }
}

function collapseAllFigurePanels() {
    for (const key of figurePanelExpansionState.keys()) {
        figurePanelExpansionState.set(key, false);
    }
    document.querySelectorAll(
        '#figureWorkspace details.workspace-figure-panel-card'
    ).forEach(details => {
        details.open = false;
        figurePanelExpansionState.set(
            panelWorkspaceKey(details.dataset.figureId, details.dataset.panelId),
            false
        );
    });
    scheduleActiveWorkspaceUiStateSave();
}

function openWorkspaceView(viewId) {
    switchWorkspaceView(viewId);
    if (viewId !== 'notes') void refreshArticleWorkspace();
    if (viewId === 'analysis' || viewId === 'highlights') void refreshManualAnnotationSummary();
}

async function jumpToArticleAbbreviationSource(entry, dialog) {
    const status = document.getElementById('articleAbbreviationStatus');
    const abbreviation = String(entry?.abbreviation || '').trim();
    const target = {
        kind: 'paragraph',
        paragraphId: String(entry?.paragraphId || ''),
        sourceKey: String(entry?.sourceKey || ''),
        quote: abbreviation,
        navigationRevision: Math.max(0, Number(entry?.navigationRevision) || 0)
    };
    if (!target.paragraphId && !target.sourceKey) {
        if (status) status.textContent = `无法定位 ${abbreviation || '该缩写'} 的原文位置。`;
        return false;
    }
    const focused = await focusWorkspaceSource(target);
    if (!focused) {
        if (status) status.textContent = `未找到 ${abbreviation || '该缩写'} 在当前正文中的首次出现位置。`;
        return false;
    }
    // Keep the table, its scroll position and edits available for the next jump.
    showStatus(`已定位 ${abbreviation} 在正文中的首次出现位置。`, 'success');
    return true;
}

function articleAbbreviationInitial(value) {
    const normalized = String(value || '').normalize('NFKC').trim().toUpperCase();
    const latin = normalized.match(/[A-Z]/);
    return latin ? latin[0] : '#';
}

function renderArticleAbbreviationAlphabetNav(entries = []) {
    const nav = document.getElementById('articleAbbreviationAlphabetNav');
    const wrap = document.getElementById('articleAbbreviationTableWrap');
    if (!nav || !wrap) return;
    const initials = new Set((Array.isArray(entries) ? entries : [])
        .map(entry => articleAbbreviationInitial(entry?.abbreviation)));
    nav.replaceChildren();
    [...'ABCDEFGHIJKLMNOPQRSTUVWXYZ', '#'].forEach(letter => {
        const button = createWorkspaceElement(
            'button', 'abbreviation-alphabet-button', letter
        );
        button.type = 'button';
        button.disabled = !initials.has(letter);
        button.setAttribute('aria-label', button.disabled
            ? `没有以 ${letter} 开头的缩写`
            : `跳转到以 ${letter} 开头的缩写`);
        button.addEventListener('click', () => {
            const row = Array.from(
                document.querySelectorAll('#articleAbbreviationTableBody tr')
            ).find(item => item.dataset.abbreviationInitial === letter);
            if (!row) return;
            wrap.scrollTo({
                top: Math.max(0, row.offsetTop - 36),
                behavior: 'smooth'
            });
            document.querySelectorAll('.abbreviation-table-row.is-alphabet-target')
                .forEach(item => item.classList.remove('is-alphabet-target'));
            row.classList.add('is-alphabet-target');
            row.querySelector('.abbreviation-table-jump')?.focus({ preventScroll: true });
            setTimeout(() => row.classList.remove('is-alphabet-target'), 1200);
        });
        nav.appendChild(button);
    });
    nav.hidden = entries.length === 0;
}

async function loadArticleAbbreviationSnapshot({ forceRefresh = false } = {}) {
    const tab = await queryPanelTargetTab();
    if (!tab?.id) throw new Error('无法获取当前论文页面');
    const requestedDocumentKey = panelTabDocumentKey(tab);
    const response = await sendTabMessage(tab.id, {
        action: 'getArticleAbbreviations',
        forceRefresh
    });
    if (!response?.success || !response.abbreviations) {
        throw new Error(response?.error || '无法读取本文缩略词表');
    }
    const currentTab = await queryPanelTargetTab();
    if (!requestedDocumentKey ||
        panelTabDocumentKey(currentTab) !== requestedDocumentKey) {
        const error = new Error('当前查看的论文已切换，请重新打开缩略词表');
        error.code = 'ABBREVIATION_TAB_CHANGED';
        throw error;
    }
    currentArticleAbbreviationSnapshot = {
        ...response.abbreviations,
        documentKey: requestedDocumentKey,
        tabId: Number(tab.id)
    };
    return currentArticleAbbreviationSnapshot;
}

function abbreviationSourceLabel(sourceType) {
    return ({
        automatic: '自动',
        manual: '手动',
        global: '全局',
        'automatic+global': '自动+全局'
    })[sourceType] || '自动';
}

function renderArticleAbbreviationStatus(snapshot) {
    const status = document.getElementById('articleAbbreviationStatus');
    if (!status) return;
    const entries = Array.isArray(snapshot?.entries) ? snapshot.entries : [];
    if (!entries.length) {
        status.textContent = '未调用 LLM；仅保留正文中有明确全称关系或全局记忆命中的缩写。';
        return;
    }
    status.textContent =
        `共 ${entries.length} 项 · 自动 ${Number(snapshot.automaticCount) || 0}` +
        ` · 手动 ${Number(snapshot.manualCount) || 0}` +
        ` · 全局命中 ${Number(snapshot.globalCount) || 0}` +
        ` · 中文 ${Number(snapshot.translatedCount) || 0}/${entries.length}` +
        ` · 全局词库 ${globalAbbreviationMemoryEntryCount} 项`;
}

async function persistArticleAbbreviationTranslations(translations) {
    const tab = await queryPanelTargetTab();
    if (!tab?.id) throw new Error('无法获取当前论文页面');
    const response = await sendTabMessage(tab.id, {
        action: 'updateArticleAbbreviationTranslations',
        translations
    });
    if (!response?.success || !response.abbreviations) {
        throw new Error(response?.error || '中文含义保存失败');
    }
    currentArticleAbbreviationSnapshot = response.abbreviations;
    return response.abbreviations;
}

function renderArticleAbbreviationTable(snapshot = currentArticleAbbreviationSnapshot) {
    const dialog = document.getElementById('articleAbbreviationDialog');
    const body = document.getElementById('articleAbbreviationTableBody');
    const empty = document.getElementById('articleAbbreviationEmpty');
    if (!dialog || !body || !empty) return;
    const entries = Array.isArray(snapshot?.entries) ? snapshot.entries : [];
    body.replaceChildren();
    entries.forEach(entry => {
        const row = document.createElement('tr');
        row.className = 'abbreviation-table-row';
        row.dataset.abbreviationInitial = articleAbbreviationInitial(entry.abbreviation);
        row.title = `跳转到 ${entry.abbreviation} 在正文中首次出现的位置`;
        const createJumpCell = (text, label) => {
            const cell = document.createElement('td');
            const button = createWorkspaceElement(
                'button', 'abbreviation-table-jump', text
            );
            button.type = 'button';
            button.setAttribute(
                'aria-label',
                `${label}；跳转到正文首次出现位置`
            );
            button.addEventListener('click', () => {
                void jumpToArticleAbbreviationSource(entry, dialog);
            });
            cell.appendChild(button);
            return cell;
        };
        const abbreviation = createJumpCell(
            entry.abbreviation,
            `缩写 ${entry.abbreviation}`
        );
        const fullName = createJumpCell(
            entry.fullName,
            `${entry.abbreviation} 的全称 ${entry.fullName}`
        );
        const meaningCell = document.createElement('td');
        const meaningEditor = document.createElement('div');
        meaningEditor.className = 'abbreviation-meaning-editor';
        const meaningInput = document.createElement('input');
        meaningInput.type = 'text';
        meaningInput.className = 'abbreviation-meaning-input';
        meaningInput.maxLength = 240;
        meaningInput.value = String(entry.meaningZh || '');
        meaningInput.placeholder = '可手动填写中文';
        meaningInput.dataset.origin = String(entry.meaningSource || '');
        meaningInput.setAttribute(
            'aria-label',
            `${entry.abbreviation} 的中文含义`
        );
        const saveMeaning = createWorkspaceElement(
            'button', 'abbreviation-meaning-save', '保存'
        );
        saveMeaning.type = 'button';
        saveMeaning.hidden = true;
        saveMeaning.setAttribute('aria-label', `保存 ${entry.abbreviation} 的中文含义`);
        const originalMeaning = meaningInput.value;
        const updateDirtyState = () => {
            saveMeaning.hidden = meaningInput.value.trim() === originalMeaning.trim();
        };
        meaningInput.addEventListener('input', updateDirtyState);
        meaningInput.addEventListener('keydown', event => {
            if (event.key === 'Enter' && !saveMeaning.hidden) {
                event.preventDefault();
                saveMeaning.click();
            } else if (event.key === 'Escape') {
                meaningInput.value = originalMeaning;
                updateDirtyState();
            }
        });
        saveMeaning.addEventListener('click', async () => {
            const meaningZh = meaningInput.value.trim();
            if (meaningZh && !/[\u3400-\u9fff]/u.test(meaningZh)) {
                showStatus('中文含义至少应包含一个中文字符。', 'error');
                meaningInput.focus();
                return;
            }
            saveMeaning.disabled = true;
            meaningInput.disabled = true;
            try {
                const next = await persistArticleAbbreviationTranslations([{
                    abbreviation: entry.abbreviation,
                    fullName: entry.fullName,
                    meaningZh,
                    origin: 'manual'
                }]);
                renderArticleAbbreviationTable(next);
                showStatus(
                    meaningZh
                        ? `已保存 ${entry.abbreviation} 的中文含义`
                        : `已清空 ${entry.abbreviation} 的中文含义`,
                    'success'
                );
            } catch (error) {
                saveMeaning.disabled = false;
                meaningInput.disabled = false;
                showStatus(`中文含义保存失败：${error.message}`, 'error');
            }
        });
        meaningEditor.append(meaningInput, saveMeaning);
        meaningCell.appendChild(meaningEditor);

        const sourceCell = document.createElement('td');
        sourceCell.className = 'abbreviation-source-cell';
        const sourceBadge = createWorkspaceElement(
            'span',
            'abbreviation-source-badge',
            abbreviationSourceLabel(entry.sourceType)
        );
        sourceBadge.dataset.source = String(entry.sourceType || 'automatic');
        sourceCell.appendChild(sourceBadge);

        const deleteCell = document.createElement('td');
        deleteCell.className = 'abbreviation-delete-cell';
        const remove = createWorkspaceElement(
            'button', 'abbreviation-row-delete', '×'
        );
        remove.type = 'button';
        remove.title = '从本文缩略词表移除';
        remove.setAttribute('aria-label', `从本文缩略词表移除 ${entry.abbreviation}`);
        remove.addEventListener('click', async () => {
            if (!confirm(`从本文缩略词表移除 ${entry.abbreviation}？`)) return;
            remove.disabled = true;
            try {
                const tab = await queryPanelTargetTab();
                if (!tab?.id) throw new Error('无法获取当前论文页面');
                const response = await sendTabMessage(tab.id, {
                    action: 'removeArticleAbbreviation',
                    abbreviation: entry.abbreviation
                });
                if (!response?.success || !response.abbreviations) {
                    throw new Error(response?.error || '移除失败');
                }
                currentArticleAbbreviationSnapshot = response.abbreviations;
                renderArticleAbbreviationTable(response.abbreviations);
                showStatus(`已从本文缩略词表移除 ${entry.abbreviation}`, 'success');
            } catch (error) {
                remove.disabled = false;
                showStatus(`移除缩略词失败：${error.message}`, 'error');
            }
        });
        deleteCell.appendChild(remove);
        row.append(abbreviation, fullName, meaningCell, sourceCell, deleteCell);
        body.appendChild(row);
    });
    renderArticleAbbreviationAlphabetNav(entries);
    empty.hidden = entries.length > 0;
    renderArticleAbbreviationStatus(snapshot);
}

async function refreshGlobalAbbreviationMemoryCount() {
    const response = await chrome.runtime.sendMessage({
        type: 'ABBREVIATION_MEMORY_GET'
    });
    if (!response?.success) {
        throw new Error(response?.error?.message || '无法读取全局缩略词库');
    }
    const memory = SciLLM.normalizeGlobalAbbreviationMemory(response.data?.memory);
    globalAbbreviationMemoryEntryCount = memory.entries.length;
    return memory;
}

async function showArticleAbbreviationTable({ forceRefresh = false } = {}) {
    const dialog = document.getElementById('articleAbbreviationDialog');
    if (!dialog) return;
    document.getElementById('articleAbbreviationFeedback')?.remove();
    const requestSequence = ++abbreviationDialogRequestSequence;
    try {
        const [snapshot] = await Promise.all([
            loadArticleAbbreviationSnapshot({ forceRefresh }),
            refreshGlobalAbbreviationMemoryCount().catch(() => null)
        ]);
        if (requestSequence !== abbreviationDialogRequestSequence) return;
        renderArticleAbbreviationTable(snapshot);
    } catch (error) {
        if (requestSequence !== abbreviationDialogRequestSequence) return;
        renderArticleAbbreviationTable({
            entries: [],
            automaticCount: 0,
            manualCount: 0,
            globalCount: 0,
            translatedCount: 0
        });
        const status = document.getElementById('articleAbbreviationStatus');
        if (status) status.textContent = `缩略词表读取失败：${error.message}`;
    }
    if (!dialog.open) dialog.showModal();
}

async function mergeIntoGlobalAbbreviationMemory(entries, {
    incrementSupport = false
} = {}) {
    const response = await chrome.runtime.sendMessage({
        type: 'ABBREVIATION_MEMORY_MERGE',
        entries,
        incrementSupport
    });
    if (!response?.success) {
        throw new Error(response?.error?.message || '全局缩略词库更新失败');
    }
    globalAbbreviationMemoryEntryCount =
        Number(response.data?.memory?.entries?.length) || 0;
    return response.data;
}

async function importCurrentArticleAbbreviationsToGlobal() {
    const button = document.getElementById('importArticleAbbreviationsToGlobal');
    const entries = Array.isArray(currentArticleAbbreviationSnapshot?.entries)
        ? currentArticleAbbreviationSnapshot.entries : [];
    if (!entries.length) {
        showStatus('本文缩略词表为空，没有可导入的项目。', 'error');
        return;
    }
    if (button) {
        button.disabled = true;
        button.textContent = '正在导入…';
    }
    try {
        const result = await mergeIntoGlobalAbbreviationMemory(entries, {
            incrementSupport: true
        });
        renderArticleAbbreviationStatus(currentArticleAbbreviationSnapshot);
        showStatus(
            `已导入全局记忆：新增 ${result.stats?.added || 0}、` +
            `更新 ${result.stats?.updated || 0}、已有 ${result.stats?.skipped || 0} 项`,
            'success'
        );
    } catch (error) {
        showStatus(`导入全局记忆失败：${error.message}`, 'error');
    } finally {
        if (button) {
            button.disabled = false;
            button.textContent = '本文导入全局记忆';
        }
    }
}

async function exportGlobalAbbreviationMemoryFile() {
    const button = document.getElementById('exportGlobalAbbreviationMemory');
    if (button) {
        button.disabled = true;
        button.textContent = '正在导出…';
    }
    try {
        const memory = await refreshGlobalAbbreviationMemoryCount();
        const payload = SciLLM.createGlobalAbbreviationMemoryExport(memory);
        const date = new Date().toISOString().slice(0, 10);
        downloadBlob(
            new Blob([JSON.stringify(payload, null, 2)], {
                type: 'application/json;charset=utf-8'
            }),
            `brevess-global-abbreviations-${date}.json`
        );
        renderArticleAbbreviationStatus(currentArticleAbbreviationSnapshot);
        showStatus(`已导出 ${payload.entryCount} 项全局缩略词，可直接分享 JSON 文件。`, 'success');
    } catch (error) {
        showStatus(`全局词库导出失败：${error.message}`, 'error');
    } finally {
        if (button) {
            button.disabled = false;
            button.textContent = '导出词库';
        }
    }
}

async function importGlobalAbbreviationMemoryFile(file) {
    if (!file) return;
    const button = document.getElementById('importGlobalAbbreviationMemoryButton');
    if (button) {
        button.disabled = true;
        button.textContent = '正在导入…';
    }
    try {
        if (file.size > 5 * 1024 * 1024) {
            throw new Error('词库文件超过 5 MB');
        }
        const parsed = JSON.parse(await file.text());
        const imported = SciLLM.parseGlobalAbbreviationMemoryImport(parsed);
        const result = await mergeIntoGlobalAbbreviationMemory(imported.entries);
        renderArticleAbbreviationStatus(currentArticleAbbreviationSnapshot);
        showStatus(
            `词库导入完成：新增 ${result.stats?.added || 0}、` +
            `更新 ${result.stats?.updated || 0}、跳过 ${result.stats?.skipped || 0} 项`,
            'success'
        );
    } catch (error) {
        const message = error?.code === 'INVALID_ABBREVIATION_MEMORY_IMPORT'
            ? '文件不是有效的 Brevess 全局缩略词库'
            : error.message;
        showStatus(`词库导入失败：${message}`, 'error');
    } finally {
        if (button) {
            button.disabled = false;
            button.textContent = '导入词库';
        }
    }
}

async function translateArticleAbbreviationsWithSummaryModel() {
    if (abbreviationTranslationPending) return;
    if (!requireUsableLlm('缩略词中文含义')) return;
    const entries = (Array.isArray(currentArticleAbbreviationSnapshot?.entries)
        ? currentArticleAbbreviationSnapshot.entries : [])
        .filter(entry => !String(entry.meaningZh || '').trim());
    if (!entries.length) {
        showStatus('当前缩略词都已有中文含义；手动内容不会被自动覆盖。', 'success');
        return;
    }
    const button = document.getElementById('translateArticleAbbreviations');
    const feedbackSequence = ++abbreviationButtonFeedbackSequence;
    abbreviationTranslationPending = true;
    if (button) {
        button.disabled = true;
        button.classList.add('is-llm-pending');
        button.setAttribute('aria-busy', 'true');
        button.textContent = `获取中 0/${entries.length}`;
    }
    try {
        const response = await sendLlmMessage({
            type: 'LLM_TRANSLATE_ABBREVIATIONS',
            entries: entries.map(entry => ({
                abbreviation: entry.abbreviation,
                fullName: entry.fullName
            }))
        });
        const obtainedCount = Array.isArray(response.translations)
            ? response.translations.length : 0;
        if (button) button.textContent = `已取得 ${obtainedCount}/${entries.length}，正在保存`;
        const next = await persistArticleAbbreviationTranslations(
            response.translations || []
        );
        if (button) button.textContent = `已保存 ${obtainedCount}/${entries.length}`;
        renderArticleAbbreviationTable(next);
        showStatus(
            `已补齐 ${response.translations?.length || 0} 项中文含义`,
            'success',
            response.notificationUsage
        );
    } catch (error) {
        if (button) button.textContent = '获取失败，重试';
        showStatus(`中文含义生成失败：${error.message}`, 'error');
    } finally {
        abbreviationTranslationPending = false;
        if (button) {
            button.disabled = false;
            button.classList.remove('is-llm-pending');
            button.removeAttribute('aria-busy');
            const terminalText = button.textContent;
            setTimeout(() => {
                if (!abbreviationTranslationPending &&
                    abbreviationButtonFeedbackSequence === feedbackSequence &&
                    button.textContent === terminalText) {
                    button.textContent = '一键获取';
                }
            }, 2400);
        }
    }
}

function handleWorkspaceTabKeydown(event) {
    if (event.altKey || event.ctrlKey || event.metaKey) return;
    const tabs = [...document.querySelectorAll('[data-workspace-target]')];
    const current = tabs.indexOf(event.currentTarget);
    if (current < 0 || !['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 :
        (current + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
    event.preventDefault();
    event.stopPropagation();
    tabs[next].focus();
    tabs[next].click();
}

function setupWorkspaceNavigation() {
    document.querySelectorAll('[data-workspace-target]').forEach(button => {
        button.addEventListener('click', () => {
            openWorkspaceView(button.dataset.workspaceTarget);
        });
        button.addEventListener('keydown', handleWorkspaceTabKeydown);
    });
    document.getElementById('refreshArticleNavigation')?.addEventListener('click', event => {
        void runWorkspaceRefreshButton(event.currentTarget);
    });
    document.getElementById('showArticleAbbreviations')?.addEventListener('click', () => {
        void showArticleAbbreviationTable();
    });
    document.getElementById('importArticleAbbreviationsToGlobal')
        ?.addEventListener('click', () => {
            void importCurrentArticleAbbreviationsToGlobal();
        });
    document.getElementById('exportGlobalAbbreviationMemory')
        ?.addEventListener('click', () => {
            void exportGlobalAbbreviationMemoryFile();
        });
    document.getElementById('importGlobalAbbreviationMemoryButton')
        ?.addEventListener('click', () => {
            document.getElementById('importGlobalAbbreviationMemoryFile')?.click();
        });
    document.getElementById('importGlobalAbbreviationMemoryFile')
        ?.addEventListener('change', event => {
            const input = event.currentTarget;
            const file = input.files?.[0] || null;
            input.value = '';
            void importGlobalAbbreviationMemoryFile(file);
        });
    document.getElementById('translateArticleAbbreviations')
        ?.addEventListener('click', () => {
            void translateArticleAbbreviationsWithSummaryModel();
        });
    document.getElementById('expandAllOutlineLevels')?.addEventListener('click', () => {
        setAllOutlineLevelsExpanded(true);
    });
    document.getElementById('collapseAllOutlineLevels')?.addEventListener('click', () => {
        setAllOutlineLevelsExpanded(false);
    });
    document.getElementById('expandAllFigureLevels')?.addEventListener('click', () => {
        setAllFigureLevelsExpanded(true);
    });
    document.getElementById('collapseAllFigureLevels')?.addEventListener('click', () => {
        setAllFigureLevelsExpanded(false);
    });
    document.getElementById('refreshFigureInventory')?.addEventListener('click', event => {
        void runWorkspaceRefreshButton(event.currentTarget);
    });
    setupFigureResultEditor();
    setupFigureKeyboardNavigation();
    setupGlobalKeyboardShortcuts();
    switchWorkspaceView(activeWorkspaceView);
}

async function runWorkspaceRefreshButton(button) {
    if (!button || button.getAttribute('aria-busy') === 'true') return null;
    button.classList.add('is-refresh-clicked');
    button.setAttribute('aria-busy', 'true');
    button.disabled = true;
    requestAnimationFrame(() => {
        setTimeout(() => button.classList.remove('is-refresh-clicked'), 150);
    });
    try {
        return await refreshArticleWorkspace({ announce: true });
    } finally {
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.classList.remove('is-refresh-clicked');
    }
}

async function openSidePanelSettingsPage(anchor = 'categoryWorkspace', trigger = null) {
    if (trigger?.dataset?.pending === 'true') return;
    if (trigger) {
        trigger.dataset.pending = 'true';
        trigger.disabled = true;
    }
    try {
        await chrome.tabs.create({
            url: String(anchor).includes('://')
                ? String(anchor)
                : chrome.runtime.getURL(anchor === 'categoryWorkspace'
                    ? 'options.html#categoryWorkspace'
                    : `options.html#${anchor}`)
        });
    } catch (error) {
        showStatus(`打开设置页面失败：${error.message}`, 'error');
    } finally {
        if (trigger) {
            delete trigger.dataset.pending;
            trigger.disabled = false;
        }
    }
}

function setupSidePanelSettingsShortcut() {
    const editScenarios = document.getElementById('editReadingScenarios');
    editScenarios?.addEventListener('click', () => {
        void openSidePanelSettingsPage('page=modes', editScenarios);
    });
    const openSidePanelSettings = document.getElementById('openSidePanelSettings');
    if (openSidePanelSettings) {
        openSidePanelSettings.addEventListener('click', () => {
            void openSidePanelSettingsPage(
                chrome.runtime.getURL('options.html#categoryWorkspace'),
                openSidePanelSettings
            );
        });
    }
    [
        'openLiteratureNoteModelSettings',
        'openArticleChatModelSettings'
    ].forEach(id => {
        const button = document.getElementById(id);
        if (!button) return;
        button.addEventListener('click', () => {
            void openSidePanelSettingsPage('page=models', button);
        });
    });
}

function appendScientificInlineText(parent, value) {
    const text = String(value ?? '');
    const tokenPattern = /<(sup|sub)>([^<\n]*)<\/\1>/gi;
    let cursor = 0;
    for (const match of text.matchAll(tokenPattern)) {
        if (match.index > cursor) {
            parent.appendChild(document.createTextNode(text.slice(cursor, match.index)));
        }
        const script = document.createElement(match[1].toLowerCase());
        script.textContent = match[2];
        parent.appendChild(script);
        cursor = match.index + match[0].length;
    }
    if (cursor < text.length) {
        parent.appendChild(document.createTextNode(text.slice(cursor)));
    }
    return parent;
}

function createWorkspaceElement(tagName, className = '', text = '') {
    const element = document.createElement(tagName);
    if (className) element.className = className;
    if (text !== '' && text !== null && text !== undefined) {
        appendScientificInlineText(element, text);
    }
    return element;
}

async function focusWorkspaceSourceDetailed(target, panelContext = capturePanelContext()) {
    if (!isCurrentPanelContext(panelContext)) return {
        success: false, focused: false, citationResult: null,
        code: 'PANEL_CONTEXT_CHANGED'
    };
    const response = await sendTabMessage(panelContext.tabId, {
        action: 'focusArticleWorkspaceSource',
        target
    });
    if (!isCurrentPanelContext(panelContext)) return {
        success: false, focused: false, citationResult: response?.citationResult || null,
        code: 'PANEL_CONTEXT_CHANGED'
    };
    return {
        ...(response && typeof response === 'object' ? response : {}),
        success: response?.success === true,
        focused: response?.success === true && response?.focused === true,
        citationResult: response?.citationResult || null
    };
}

async function focusWorkspaceSource(target, panelContext = capturePanelContext()) {
    const response = await focusWorkspaceSourceDetailed(target, panelContext);
    return Boolean(response?.success && response?.focused);
}

function clearPdfSemanticNavigationPending() {
    document.querySelectorAll('#articleNavigationTree [data-pdf-semantic-focus]')
        .forEach(button => {
            button.classList.remove('is-pending');
            button.removeAttribute('aria-busy');
        });
}

function ensurePdfSemanticFocusCoordinator() {
    if (pdfSemanticFocusCoordinator) return pdfSemanticFocusCoordinator;
    pdfSemanticFocusCoordinator = createPdfSemanticFocusCoordinator({
        focus(target, context) {
            return focusWorkspaceSourceDetailed(target, context.panelContext);
        },
        isCurrent(context) {
            return Boolean(context?.button?.isConnected &&
                context.navigation === currentPdfSemanticNavigation &&
                isCurrentPanelContext(context.panelContext));
        },
        setPending(pending, _target, context) {
            clearPdfSemanticNavigationPending();
            if (pending && context?.button?.isConnected) {
                context.button.classList.add('is-pending');
                context.button.setAttribute('aria-busy', 'true');
            }
        },
        announce(description) {
            const status = document.getElementById('articleNavigationFocusStatus');
            if (!status) return;
            status.dataset.state = description.state;
            status.textContent = description.message;
        }
    });
    return pdfSemanticFocusCoordinator;
}

function buildOutlineSummaryIndex(outline, standaloneParagraphs = []) {
    const sections = new Map();
    const paragraphs = new Map();
    function visit(node) {
        const value = {
            summary: String(node?.summary || ''),
            paragraphs: Array.isArray(node?.paragraphs) ? node.paragraphs : []
        };
        if (node?.sectionId) sections.set(String(node.sectionId), value);
        const title = String(node?.title || '').normalize('NFKC').replace(/\s+/g, ' ').trim();
        if (title) sections.set(`title:${title.toLowerCase()}`, value);
        value.paragraphs.forEach(paragraph => {
            const paragraphId = String(paragraph?.paragraphId || '');
            if (paragraphId) paragraphs.set(paragraphId, paragraph);
        });
        (Array.isArray(node?.children) ? node.children : []).forEach(visit);
    }
    (Array.isArray(outline?.nodes) ? outline.nodes : []).forEach(visit);
    (Array.isArray(standaloneParagraphs) ? standaloneParagraphs : [])
        .forEach(paragraph => {
            const paragraphId = String(paragraph?.paragraphId || '');
            if (paragraphId) paragraphs.set(paragraphId, paragraph);
        });
    return { sections, paragraphs };
}

function workspaceParagraphsForNode(snapshot, node) {
    return (Array.isArray(snapshot?.paragraphs) ? snapshot.paragraphs : [])
        .filter(paragraph =>
            String(paragraph.sectionId || '') === String(node.sectionId || ''));
}

function renderWorkspaceBilingualTitle(button, node = {}) {
    const primary = String(node.title || '未命名章节')
        .normalize('NFKC').replace(/\s+/g, ' ').trim();
    const display = String(node.displayTitle || primary)
        .normalize('NFKC').replace(/\r\n?/g, '\n').trim();
    let lines = display.split(/\n+/)
        .map(line => line.replace(/\s+/g, ' ').trim())
        .filter(Boolean);
    if (lines.length === 1 && primary &&
        lines[0].toLocaleLowerCase().startsWith(primary.toLocaleLowerCase())) {
        const remainder = lines[0].slice(primary.length).trim();
        lines = [primary, ...(remainder ? [remainder] : [])];
    }
    const translations = lines.filter(line =>
        line.toLocaleLowerCase() !== primary.toLocaleLowerCase());
    const primaryLine = createWorkspaceElement(
        'span', 'workspace-tree-title-primary', primary || lines[0] || '未命名章节'
    );
    button.replaceChildren(primaryLine);
    translations.forEach(translation => {
        button.appendChild(createWorkspaceElement(
            'span', 'workspace-tree-title-translation', translation
        ));
    });
}

function pdfSemanticNavigationIdentity(value) {
    if (!value || typeof value !== 'object' || value.schemaVersion !== 1 ||
        value.type !== 'pdf-semantic-navigation' || !Array.isArray(value.sections) ||
        typeof value.documentId !== 'string' || !value.documentId ||
        typeof value.documentHash !== 'string' || !value.documentHash ||
        !Number.isSafeInteger(value.documentGeneration) || value.documentGeneration < 1 ||
        !Number.isSafeInteger(value.revision) || value.revision < 1) return '';
    return [value.documentId, value.documentHash, value.documentGeneration, value.revision,
        String(value.semanticCacheKey || ''), String(value.semanticProvenanceKey || '')]
        .join('\u0000');
}

function popupPdfSemanticNavigationCounts(navigation) {
    const sectionIds = new Set();
    const paragraphIds = new Set();
    const visit = sections => (Array.isArray(sections) ? sections : []).forEach(section => {
        if (typeof section?.sectionId === 'string' && section.sectionId) {
            sectionIds.add(section.sectionId);
        }
        (Array.isArray(section?.paragraphTargets) ? section.paragraphTargets : [])
            .forEach(target => {
                if (typeof target?.paragraphId === 'string' && target.paragraphId) {
                    paragraphIds.add(target.paragraphId);
                }
            });
        visit(section?.children);
    });
    visit(navigation?.sections);
    return Object.freeze({
        sectionCount: sectionIds.size,
        paragraphCount: paragraphIds.size
    });
}

function isTrustedPopupPdfParagraphTarget(target, navigation) {
    const quote = target?.expectedNormalizedQuote;
    const pageNumbers = target?.pageNumbers;
    return Boolean(target?.kind === 'paragraph' &&
        target.documentId === navigation.documentId &&
        target.documentHash === navigation.documentHash &&
        target.documentGeneration === navigation.documentGeneration &&
        target.revision === navigation.revision &&
        target.semanticCacheKey === navigation.semanticCacheKey &&
        target.semanticProvenanceKey === navigation.semanticProvenanceKey &&
        typeof target.paragraphId === 'string' && target.paragraphId &&
        Number.isSafeInteger(target.pageNumber) && target.pageNumber > 0 &&
        Array.isArray(pageNumbers) && pageNumbers.length > 0 && pageNumbers.length <= 32 &&
        pageNumbers.every((pageNumber, index) => Number.isSafeInteger(pageNumber) &&
            pageNumber > 0 && (index === 0 || pageNumber > pageNumbers[index - 1])) &&
        pageNumbers[0] === target.pageNumber &&
        Number.isSafeInteger(target.normalizedStart) && target.normalizedStart >= 0 &&
        Number.isSafeInteger(target.normalizedEnd) &&
        target.normalizedEnd > target.normalizedStart &&
        typeof quote === 'string' && quote.length ===
            target.normalizedEnd - target.normalizedStart);
}

function isTrustedPopupPdfSemanticSection(section, navigation, seen = new Set()) {
    if (!section || typeof section !== 'object' ||
        typeof section.sectionId !== 'string' || !section.sectionId ||
        seen.has(section.sectionId) || typeof section.title !== 'string' ||
        !Number.isSafeInteger(section.level) || section.level < 1 || section.level > 6 ||
        !Array.isArray(section.paragraphTargets) || !Array.isArray(section.children)) return false;
    seen.add(section.sectionId);
    return section.paragraphTargets.every(target =>
        isTrustedPopupPdfParagraphTarget(target, navigation)) &&
        section.children.every(child =>
            isTrustedPopupPdfSemanticSection(child, navigation, seen));
}

function normalizePopupPdfSemanticNavigation(value, snapshot = currentWorkspaceSnapshot) {
    const identity = pdfSemanticNavigationIdentity(value);
    if (!identity) return null;
    const snapshotDocumentId = String(snapshot?.documentId || '');
    const snapshotDocumentHash = String(snapshot?.documentHash || '');
    const seenSections = new Set();
    if ((snapshotDocumentId && snapshotDocumentId !== value.documentId) ||
        (snapshotDocumentHash && snapshotDocumentHash !== value.documentHash) ||
        !value.sections.every(section =>
            isTrustedPopupPdfSemanticSection(section, value, seenSections))) return null;
    return value;
}

function updatePopupPdfSemanticNavigation(value, snapshot = currentWorkspaceSnapshot) {
    const next = normalizePopupPdfSemanticNavigation(value, snapshot);
    if (pdfSemanticNavigationIdentity(next) !==
        pdfSemanticNavigationIdentity(currentPdfSemanticNavigation)) {
        pdfSemanticFocusCoordinator?.invalidate();
        clearPdfSemanticNavigationPending();
        const status = document.getElementById('articleNavigationFocusStatus');
        if (status) {
            status.textContent = '';
            delete status.dataset.state;
        }
    }
    currentPdfSemanticNavigation = next;
    return next;
}

function trustedPopupPdfFocusTarget(target, navigation) {
    if (!isTrustedPopupPdfParagraphTarget(target, navigation)) return null;
    return {
        ...target,
        kind: 'paragraph',
        quote: target.expectedNormalizedQuote
    };
}

function runPopupPdfSemanticFocus(button, target, navigation) {
    const trustedTarget = trustedPopupPdfFocusTarget(target, navigation);
    if (!trustedTarget) return Promise.resolve({ applied: false,
        reasonCode: 'PDF_FOCUS_STALE' });
    const status = document.getElementById('articleNavigationFocusStatus');
    if (status) {
        status.dataset.state = 'pending';
        status.textContent = '正在定位 PDF 原文…';
    }
    return ensurePdfSemanticFocusCoordinator().run(trustedTarget, {
        button,
        navigation,
        panelContext: capturePanelContext()
    });
}

function renderPopupPdfSemanticNavigation(container, navigation, treeState = {}) {
    container.dataset.pdfSemanticNavigation = 'true';
    container.setAttribute('role', 'tree');
    const hadTree = treeState.hadTree === true;
    const previouslyOpen = treeState.previouslyOpen instanceof Set
        ? treeState.previouslyOpen : new Set();
    function appendSection(section, parent, depth = 0) {
        const details = createWorkspaceElement(
            'details', 'workspace-tree-node workspace-pdf-semantic-node'
        );
        details.dataset.nodeKey = section.sectionId;
        details.setAttribute('role', 'treeitem');
        details.setAttribute('aria-level', String(depth + 1));
        details.dataset.treeDepth = String(Math.min(3, Math.max(0, depth)));
        details.dataset.leaf = String(
            section.children.length === 0 && section.paragraphTargets.length === 0
        );
        details.open = hadTree ? previouslyOpen.has(section.sectionId)
            : depth === 0 && section.children.length > 0;
        const summary = createWorkspaceElement('summary', 'workspace-tree-summary');
        const toggle = createWorkspaceElement(
            'button', 'workspace-tree-toggle'
        );
        toggle.type = 'button';
        toggle.disabled = section.children.length === 0 &&
            section.paragraphTargets.length === 0;
        const updateToggle = () => {
            toggle.setAttribute('aria-expanded', String(details.open));
            toggle.setAttribute('aria-label',
                `${details.open ? '收起' : '展开'}${section.title || '当前标题'}`);
        };
        toggle.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            if (!toggle.disabled) details.open = !details.open;
        });
        details.addEventListener('toggle', updateToggle);
        updateToggle();
        const firstTarget = section.paragraphTargets[0] || null;
        const jump = createWorkspaceElement(
            'button', 'workspace-tree-jump workspace-pdf-semantic-section-jump',
            section.title || '未命名章节'
        );
        jump.type = 'button';
        jump.disabled = !firstTarget;
        jump.dataset.pdfSemanticFocus = 'section';
        jump.replaceChildren(createWorkspaceElement(
            'span', 'workspace-pdf-semantic-title', section.title || '未命名章节'
        ));
        if (String(section.source || '').startsWith('implicit-')) {
            jump.appendChild(createWorkspaceElement(
                'span', 'workspace-pdf-semantic-inferred', '推断'
            ));
        }
        jump.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            void runPopupPdfSemanticFocus(jump, firstTarget, navigation);
        });
        const count = createWorkspaceElement(
            'span', 'workspace-tree-count', `${section.paragraphTargets.length} 段`
        );
        summary.append(toggle, jump, count);
        details.appendChild(summary);
        const body = createWorkspaceElement('div', 'workspace-pdf-semantic-children');
        body.setAttribute('role', 'group');
        let paragraphContainer = body;
        if (depth === 0 && section.children.length && section.paragraphTargets.length) {
            paragraphContainer = createWorkspaceElement(
                'details', 'workspace-tree-node workspace-pdf-semantic-paragraphs'
            );
            paragraphContainer.dataset.nodeKey = `${section.sectionId}:paragraphs`;
            paragraphContainer.setAttribute('role', 'treeitem');
            paragraphContainer.setAttribute('aria-level', String(depth + 2));
            paragraphContainer.open = previouslyOpen.has(paragraphContainer.dataset.nodeKey);
            const paragraphSummary = createWorkspaceElement('summary', 'workspace-pdf-semantic-paragraph-summary');
            paragraphSummary.append(
                createWorkspaceElement('span', '', t('本节段落')),
                createWorkspaceElement('span', 'workspace-tree-count', `${section.paragraphTargets.length}`)
            );
            paragraphContainer.appendChild(paragraphSummary);
            body.appendChild(paragraphContainer);
        }
        section.paragraphTargets.forEach((target, index) => {
            const label = String(target.expectedNormalizedQuote || '')
                .replace(/\s+/gu, ' ').trim();
            const button = createWorkspaceElement(
                'button', 'workspace-pdf-semantic-paragraph',
                `第 ${index + 1} 段 · ${label.slice(0, 180)}`
            );
            button.type = 'button';
            button.dataset.pdfSemanticFocus = 'paragraph';
            button.dataset.paragraphId = target.paragraphId;
            button.title = label;
            button.addEventListener('click', () => {
                void runPopupPdfSemanticFocus(button, target, navigation);
            });
            paragraphContainer.appendChild(button);
        });
        section.children.forEach(child => appendSection(child, body, depth + 1));
        details.appendChild(body);
        parent.appendChild(details);
    }
    navigation.sections.forEach(section => appendSection(section, container, 0));
}

async function runSingleParagraphSummary(
    paragraph,
    panelContext = capturePanelContext(paragraphSummaryTaskGeneration)
) {
    const paragraphId = String(paragraph?.paragraphId || '');
    if (!isCurrentParagraphSummaryTask(panelContext) || !paragraphId ||
        workspaceParagraphSummaryState.get(paragraphId)?.loading) return;
    if (!requireUsableLlm('段落概述')) return;
    workspaceParagraphSummaryState.set(paragraphId, { loading: true, error: '' });
    renderArticleNavigationTree(currentWorkspaceSnapshot);
    try {
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'analyzeReviewParagraphWithLLM',
            paragraphId,
            sourceKey: String(paragraph?.sourceKey || ''),
            navigationRevision: Number(paragraph?.navigationRevision) || 0,
            documentId: preparedDocumentState?.documentId ||
                manualAnnotationState?.documentId,
            documentHash: preparedDocumentState?.documentHash ||
                manualAnnotationState?.documentHash
        });
        if (!isCurrentParagraphSummaryTask(panelContext)) return;
        if (!response?.success) {
            const error = new Error(response?.error || '单段摘要生成失败');
            error.code = response?.code;
            throw error;
        }
        workspaceParagraphSummaryState.delete(paragraphId);
        await refreshArticleWorkspace({ panelContext });
        if (!isCurrentParagraphSummaryTask(panelContext)) return;
        showStatus('段落概述已生成', 'success', response.usage);
    } catch (error) {
        if (!isCurrentParagraphSummaryTask(panelContext)) return;
        if (error?.code === 'PARAGRAPH_STALE') {
            const message = '该段落已更新或不再存在，请刷新文章导航后重试';
            workspaceParagraphSummaryState.set(paragraphId, {
                loading: false,
                error: message
            });
            renderArticleNavigationTree(currentWorkspaceSnapshot);
            showStatus(message, 'error');
            return;
        }
        workspaceParagraphSummaryState.set(paragraphId, {
            loading: false,
            error: error.message || '单段摘要生成失败'
        });
        renderArticleNavigationTree(currentWorkspaceSnapshot);
        showStatus('单段摘要生成失败：' + error.message, 'error');
    }
}

function paragraphNoteFor(snapshot, paragraphId) {
    return (Array.isArray(snapshot?.paragraphNotes) ? snapshot.paragraphNotes : [])
        .find(item => String(item?.paragraphId || '') === String(paragraphId || '')) || null;
}

function closeParagraphNoteEditor() {
    paragraphNoteEditorTarget = null;
    const dialog = document.getElementById('paragraphNoteDialog');
    if (dialog?.open) dialog.close();
}

function openParagraphNoteEditor(paragraph, snapshot = currentWorkspaceSnapshot) {
    const paragraphId = String(paragraph?.paragraphId || '');
    if (!paragraphId) return;
    const existing = paragraphNoteFor(snapshot, paragraphId);
    paragraphNoteEditorTarget = {
        paragraphId,
        sourceKey: String(paragraph?.sourceKey || ''),
        navigationRevision: Number(paragraph?.navigationRevision || snapshot?.revision || 0)
    };
    const quote = document.getElementById('paragraphNoteQuote');
    const input = document.getElementById('paragraphNoteText');
    const status = document.getElementById('paragraphNoteStatus');
    const remove = document.getElementById('deleteParagraphNote');
    if (quote) quote.textContent = String(
        paragraph?.displayText || paragraph?.text || existing?.quote || ''
    ).slice(0, 480);
    if (input) input.value = String(existing?.note || '');
    if (status) status.textContent = existing?.updatedAt
        ? `上次保存：${new Date(existing.updatedAt).toLocaleString()}` : '';
    if (remove) remove.hidden = !existing?.note;
    const dialog = document.getElementById('paragraphNoteDialog');
    if (!dialog) return;
    if (!dialog.open) dialog.showModal();
    requestAnimationFrame(() => input?.focus());
}

async function saveParagraphNoteValue(note) {
    if (!paragraphNoteEditorTarget) return;
    const status = document.getElementById('paragraphNoteStatus');
    const save = document.getElementById('saveParagraphNote');
    const remove = document.getElementById('deleteParagraphNote');
    if (save) save.disabled = true;
    if (remove) remove.disabled = true;
    if (status) {
        status.classList.remove('is-error');
        status.textContent = '正在保存到本文工作区…';
    }
    try {
        const panelContext = capturePanelContext();
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'updateArticleParagraphNote',
            ...paragraphNoteEditorTarget,
            note: String(note || '')
        });
        if (!isCurrentPanelContext(panelContext)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'PARAGRAPH_NOTE_SAVE_FAILED');
            error.code = response?.code;
            throw error;
        }
        const nextSnapshot = response.snapshot ? {
            ...response.snapshot,
            localWorkspace: currentWorkspaceSnapshot?.localWorkspace
        } : {
            ...(currentWorkspaceSnapshot || {}),
            paragraphNotes: response.paragraphNotes || []
        };
        renderArticleWorkspaceSnapshot(nextSnapshot);
        showStatus(note ? '段落笔记已保存' : '段落笔记已删除', 'success');
        closeParagraphNoteEditor();
    } catch (error) {
        if (status) {
            status.classList.add('is-error');
            status.textContent = error?.code === 'PARAGRAPH_STALE'
                ? '原文段落已变化，请刷新导航后重新打开笔记。'
                : `保存失败：${error.message}`;
        }
    } finally {
        if (save) save.disabled = false;
        if (remove) remove.disabled = false;
    }
}

function renderArticleNavigationTree(snapshot = currentWorkspaceSnapshot) {
    const container = document.getElementById('articleNavigationTree');
    if (!container) return;
    const hadTree = Boolean(container.querySelector('details.workspace-tree-node'));
    const previouslyOpen = new Set(
        Array.from(container.querySelectorAll('details.workspace-tree-node[open]'))
            .map(details => details.dataset.nodeKey).filter(Boolean)
    );
    container.replaceChildren();
    delete container.dataset.pdfSemanticNavigation;
    container.removeAttribute('role');
    const semanticNavigation = normalizePopupPdfSemanticNavigation(
        currentPdfSemanticNavigation,
        snapshot
    );
    if (semanticNavigation) {
        renderPopupPdfSemanticNavigation(container, semanticNavigation, {
            hadTree, previouslyOpen
        });
        return;
    }
    if (currentPdfSemanticNavigation) updatePopupPdfSemanticNavigation(null, snapshot);
    const nodes = Array.isArray(snapshot?.nodes) ? snapshot.nodes : [];
    if (!nodes.length) {
        if (snapshot?.pdfNativeMode === true) {
            const baseline = createWorkspaceElement(
                'section', 'workspace-pdf-native-baseline'
            );
            baseline.append(
                createWorkspaceElement('h3', '', 'PDF 原始阅读工具已启用'),
                createWorkspaceElement(
                    'p', '',
                    '可在原 PDF 页面翻页、缩放和搜索；含文字层的页面支持划选、高亮与批注，这些操作不需要 MinerU 或 LLM。'
                ),
                createWorkspaceElement(
                    'p', 'workspace-muted',
                    '含文字层的 PDF 会自动建立正文索引，可继续使用亮文、问答和解图。扫描件缺少可选文字时，可在页面顶部选择“增强文本识别”；阅读画面始终保留原 PDF。'
                )
            );
            container.appendChild(baseline);
            return;
        }
        container.appendChild(createWorkspaceElement(
            'div', 'workspace-empty', '暂未识别到稳定的正文标题。可等待页面加载完成后刷新。'
        ));
        return;
    }
    const summaryIndex = buildOutlineSummaryIndex(
        snapshot?.reviewOutline,
        snapshot?.paragraphSummaries
    );
    const paragraphNotes = new Map(
        (Array.isArray(snapshot?.paragraphNotes) ? snapshot.paragraphNotes : [])
            .map(item => [String(item?.paragraphId || ''), item])
            .filter(([paragraphId]) => Boolean(paragraphId))
    );

    function appendNode(node, parent, depth = 0) {
        const children = Array.isArray(node.children) ? node.children : [];
        const leaf = children.length === 0;
        const nodeKey = String(node.sectionId || node.sourceKey ||
            `${depth}:${node.order || 0}:${node.title || ''}`);
        const details = createWorkspaceElement('details', 'workspace-tree-node');
        details.dataset.nodeKey = nodeKey;
        details.dataset.treeDepth = String(Math.min(3, Math.max(0, depth)));
        details.dataset.leaf = String(leaf);
        details.open = hadTree ? previouslyOpen.has(nodeKey) : false;
        const summary = createWorkspaceElement('summary', 'workspace-tree-summary');
        const analysisToggle = document.createElement('input');
        analysisToggle.type = 'checkbox';
        analysisToggle.className = 'workspace-section-analysis-toggle';
        analysisToggle.checked = node.analysisSelected === true;
        analysisToggle.indeterminate = node.analysisIndeterminate === true;
        analysisToggle.disabled = !Array.isArray(node.analysisSectionIds) ||
            node.analysisSectionIds.length === 0;
        analysisToggle.setAttribute(
            'aria-label',
            `${node.displayTitle || node.title || '当前章节'}参与规则和 LLM 分析`
        );
        analysisToggle.addEventListener('click', event => event.stopPropagation());
        analysisToggle.addEventListener('change', async event => {
            event.stopPropagation();
            const panelContext = capturePanelContext();
            analysisToggle.disabled = true;
            try {
                const response = await sendTabMessage(panelContext.tabId, {
                    action: 'setArticleAnalysisSectionSelection',
                    sectionIds: node.analysisSectionIds,
                    selected: analysisToggle.checked
                });
                if (!isCurrentPanelContext(panelContext)) return;
                if (!response?.success || !response.snapshot) {
                    throw new Error(response?.error || 'SECTION_SELECTION_FAILED');
                }
                renderArticleWorkspaceSnapshot(response.snapshot);
                showStatus(
                    `已更新分析范围：当前包含 ${response.selectedParagraphCount || 0} 段正文。`,
                    'success'
                );
            } catch (error) {
                if (!isCurrentPanelContext(panelContext)) return;
                analysisToggle.checked = !analysisToggle.checked;
                analysisToggle.disabled = false;
                showStatus(`无法更新章节分析范围：${error.message}`, 'error');
            }
        });
        const toggle = createWorkspaceElement(
            'button', 'workspace-tree-toggle'
        );
        toggle.type = 'button';
        toggle.disabled = leaf && Number(node.paragraphCount || 0) === 0;
        const updateToggle = () => {
            toggle.setAttribute('aria-expanded', String(details.open));
            const action = details.open ? '收起' : '展开';
            toggle.setAttribute('aria-label', leaf
                ? `${action}${node.title || '当前标题'}的段落摘要`
                : `${action}${node.title || '当前标题'}的下级标题`);
        };
        toggle.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            if (!toggle.disabled) details.open = !details.open;
        });
        details.addEventListener('toggle', updateToggle);
        updateToggle();
        const jump = createWorkspaceElement(
            'button', 'workspace-tree-jump',
            ''
        );
        renderWorkspaceBilingualTitle(jump, node);
        jump.type = 'button';
        jump.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            void focusWorkspaceSource({
                kind: 'section', sectionId: node.sectionId, sourceKey: node.sourceKey
            });
        });
        const count = createWorkspaceElement(
            'span', 'workspace-tree-count', `${node.paragraphCount || 0} 段`
        );
        summary.append(analysisToggle, toggle, jump, count);
        details.appendChild(summary);
        if (leaf) {
            const nodeParagraphs = workspaceParagraphsForNode(snapshot, node);
            const list = createWorkspaceElement('div', 'workspace-paragraph-list');
            nodeParagraphs.forEach((paragraph, index) => {
                const paragraphId = String(paragraph.paragraphId || '');
                const saved = summaryIndex.paragraphs.get(paragraphId);
                const task = workspaceParagraphSummaryState.get(paragraphId) || {};
                const label = saved?.summary
                    ? `第 ${index + 1} 段 · ${saved.summary}`
                    : `第 ${index + 1} 段 · ${String(
                        paragraph.displayText || paragraph.text || ''
                    ).replace(/<\/?(?:sup|sub)>/gi, '').slice(0, 96)}`;
                const className = 'workspace-paragraph-jump' +
                    (task.loading ? ' is-loading' : '') +
                    (task.error ? ' is-error' : '');
                const button = createWorkspaceElement('button', className, label);
                button.type = 'button';
                button.dataset.paragraphId = paragraphId;
                button.disabled = task.loading || reviewOutlineState.running;
                button.title = task.error || paragraph.text || label;
                button.addEventListener('click', async event => {
                    event.preventDefault();
                    event.stopImmediatePropagation();
                    const panelContext = capturePanelContext(paragraphSummaryTaskGeneration);
                    const focused = await focusWorkspaceSource({
                        kind: 'paragraph',
                        paragraphId,
                        sourceKey: paragraph.sourceKey,
                        navigationRevision: Number(paragraph.navigationRevision ||
                            snapshot?.revision || 0)
                    }, panelContext);
                    if (!isCurrentParagraphSummaryTask(panelContext)) return;
                    if (!focused) {
                        showStatus('无法定位该段落；请刷新文章导航后重试。', 'error');
                    }
                }, { capture: true });
                const summarize = createWorkspaceElement(
                    'button',
                    'workspace-paragraph-summary-action',
                    '概述'
                );
                summarize.type = 'button';
                summarize.disabled = task.loading || reviewOutlineState.running;
                summarize.title = task.error
                    ? `概述生成失败：${task.error}` : '生成该段概述';
                summarize.addEventListener('click', event => {
                    event.preventDefault();
                    event.stopPropagation();
                    if (!hasUsableLlm()) {
                        showStatus(llmUnavailableMessage('段落概述'), 'error');
                        return;
                    }
                    const panelContext = capturePanelContext(paragraphSummaryTaskGeneration);
                    void runSingleParagraphSummary(paragraph, panelContext);
                });
                const note = createWorkspaceElement(
                    'button',
                    'workspace-paragraph-note-action' +
                        (paragraphNotes.get(paragraphId)?.note ? ' has-note' : ''),
                    paragraphNotes.get(paragraphId)?.note ? '已记' : '笔记'
                );
                note.type = 'button';
                note.title = paragraphNotes.get(paragraphId)?.note
                    ? `编辑笔记：${paragraphNotes.get(paragraphId).note}`
                    : '添加不消耗 token 的手动点评';
                note.addEventListener('click', event => {
                    event.preventDefault();
                    event.stopPropagation();
                    openParagraphNoteEditor(paragraph, snapshot);
                });
                const row = createWorkspaceElement('div', 'workspace-paragraph-row');
                row.append(button, summarize, note);
                list.appendChild(row);
            });
            details.appendChild(list);
        }
        children.forEach(child => appendNode(child, details, depth + 1));
        parent.appendChild(details);
    }
    nodes.forEach(node => appendNode(node, container, 0));
}

function renderEvidenceLedger(snapshot = currentWorkspaceSnapshot) {
    const container = document.getElementById('evidenceLedger');
    if (!container) return;
    container.replaceChildren(createWorkspaceElement('h3', '', '论文证据台账'));
    const ledger = snapshot?.ledger;
    const relations = Array.isArray(ledger?.relationSummaries) ? ledger.relationSummaries : [];
    const warnings = Array.isArray(ledger?.reviewWarnings) ? ledger.reviewWarnings : [];
    const audits = Array.isArray(ledger?.auditItems) ? ledger.auditItems : [];
    if (!relations.length && !warnings.length && !audits.length) {
        container.appendChild(createWorkspaceElement(
            'div', 'workspace-empty', '完成 AI 分析后，核心证据与审读提醒会显示在这里。'
        ));
        return;
    }
    const groups = [
        ['核心证据', relations, item => `${item.labelZh || '证据关系'} · ${(item.annotationIds || []).length} 条`],
        ['审读提醒', warnings, item => item.reasonZh || '需要复核'],
        ['待核查', audits, item => item.messageZh || '待核查信息']
    ];
    groups.forEach(([label, items, format]) => {
        if (!items.length) return;
        container.appendChild(createWorkspaceElement('h4', 'workspace-result-heading', `${label}（${items.length}）`));
        items.forEach(item => {
            const button = createWorkspaceElement('button', 'workspace-result-item', format(item));
            button.type = 'button';
            button.addEventListener('click', () => void focusWorkspaceSource({
                kind: 'evidence',
                annotationIds: item.annotationIds || [
                    ...(item.claimAnnotationIds || []), ...(item.evidenceAnnotationIds || [])
                ],
                relationId: item.relationId || ''
            }));
            container.appendChild(button);
        });
    });
}

function renderHighlightDistributionSnapshot(snapshot = currentWorkspaceSnapshot) {
    const container = document.getElementById('highlightDistribution');
    if (!container) return;
    container.replaceChildren(createWorkspaceElement('h3', '', '高亮分布'));
    if (snapshot?.pdfNativeMode === true) {
        const baseline = createWorkspaceElement(
            'section', 'workspace-pdf-native-baseline'
        );
        baseline.append(
            createWorkspaceElement('h3', '', 'PDF 原始批注'),
            createWorkspaceElement(
                'p', '',
                '可在左侧 PDF 工具栏直接使用文本高亮、手写、文本框和批注；原始 PDF 阅读不需要 MinerU。'
            )
        );
        container.appendChild(baseline);
        return;
    }
    const distribution = snapshot?.highlightDistribution || {
        sourceCounts: {}, categories: [], rows: [], totalHighlights: 0
    };
    const sourceMeta = {
        regex: { label: '正则', className: 'is-regex', members: ['regex'] },
        llm: { label: 'LLM', className: 'is-llm', members: ['llm'] },
        // 智能检索和其他用户触发的标注也跟随“手动”视图开关，避免产生
        // 第四种无法单独控制的页面高亮。
        manual: {
            label: '手动', className: 'is-manual',
            members: ['manual', 'semantic', 'other']
        }
    };
    const legend = createWorkspaceElement('div', 'workspace-distribution-legend');
    Object.entries(sourceMeta).forEach(([source, meta]) => {
        const count = meta.members.reduce((total, member) =>
            total + (Number(distribution.sourceCounts?.[member]) || 0), 0);
        const button = createWorkspaceElement(
            'button', `workspace-distribution-legend-item ${meta.className}`,
            `${meta.label} ${count}`
        );
        button.type = 'button';
        button.dataset.highlightSourceToggle = source;
        button.setAttribute('aria-pressed', String(visibleHighlightSources.has(source)));
        button.title = `${visibleHighlightSources.has(source) ? '隐藏' : '显示'}${meta.label}高亮`;
        button.addEventListener('click', () => {
            if (visibleHighlightSources.has(source)) visibleHighlightSources.delete(source);
            else visibleHighlightSources.add(source);
            renderHighlightDistributionSnapshot(currentWorkspaceSnapshot);
            void sendTabMessage(activePanelTabContext.tabId, {
                action: 'setHighlightSourceVisibility',
                visibleSources: [...visibleHighlightSources]
            }).catch(() => undefined);
        });
        legend.appendChild(button);
    });
    container.appendChild(legend);
    let visibleRowCount = 0;
    (distribution.rows || []).forEach(row => {
        const block = createWorkspaceElement('section', 'workspace-distribution-row');
        const title = createWorkspaceElement('button', 'workspace-distribution-title', row.title);
        title.type = 'button';
        title.addEventListener('click', () => void focusWorkspaceSource({
            kind: 'section', sectionId: row.sectionId
        }));
        block.appendChild(title);
        const cells = createWorkspaceElement('div', 'workspace-distribution-cells');
        (distribution.categories || []).forEach(category => {
            const value = row.cells?.[category.categoryId];
            if (!value?.count) return;
            const sourceGroups = value.sources && typeof value.sources === 'object'
                ? value.sources : Object.fromEntries((value.items || []).map(item => [
                    item.source || 'other', {
                        count: (value.items || []).filter(candidate =>
                            (candidate.source || 'other') === (item.source || 'other')).length,
                        items: (value.items || []).filter(candidate =>
                            (candidate.source || 'other') === (item.source || 'other'))
                    }
                ]));
            Object.entries(sourceMeta).forEach(([source, meta]) => {
                if (!visibleHighlightSources.has(source)) return;
                const memberValues = meta.members
                    .map(member => sourceGroups[member])
                    .filter(value => value?.count);
                const sourceValue = {
                    count: memberValues.reduce((total, value) => total + value.count, 0),
                    items: memberValues.flatMap(value => value.items || [])
                };
                if (!sourceValue.count) return;
                const label = `${meta.label} · ${category.name} ${sourceValue.count}`;
                const title = (sourceValue.items || []).slice(0, 8).map(item => {
                    const lines = [item.quote || ''];
                    if (item.sourceQuery) lines.push(`检索意图：${item.sourceQuery}`);
                    if (item.note) lines.push(`备注：${item.note}`);
                    return lines.filter(Boolean).join('\n');
                }).filter(Boolean).join('\n\n');
                if (sourceValue.items.length > 1) {
                    const group = createWorkspaceElement(
                        'details', `workspace-distribution-group ${meta.className}`
                    );
                    group.style.setProperty(
                        '--workspace-highlight-color', category.color || '#0b4778'
                    );
                    const summary = createWorkspaceElement(
                        'summary', 'workspace-distribution-cell', label
                    );
                    summary.title = '展开查看每一处原文命中';
                    group.appendChild(summary);
                    const occurrences = createWorkspaceElement(
                        'div', 'workspace-distribution-occurrences'
                    );
                    sourceValue.items.forEach((item, itemIndex) => {
                        const occurrence = createWorkspaceElement(
                            'button', 'workspace-distribution-occurrence',
                            `${itemIndex + 1}. ${String(item.quote || '查看原文位置').slice(0, 120)}`
                        );
                        occurrence.type = 'button';
                        occurrence.dataset.highlightId = item.highlightId || '';
                        occurrence.title = String(item.quote || title || '查看原文位置');
                        occurrence.addEventListener('click', event => {
                            event.stopPropagation();
                            void focusWorkspaceSource({
                                kind: 'highlight', highlightId: item.highlightId || ''
                            });
                        });
                        occurrences.appendChild(occurrence);
                    });
                    group.appendChild(occurrences);
                    cells.appendChild(group);
                } else {
                    const button = createWorkspaceElement(
                        'button', `workspace-distribution-cell ${meta.className}`, label
                    );
                    button.type = 'button';
                    button.style.setProperty(
                        '--workspace-highlight-color', category.color || '#0b4778'
                    );
                    button.title = title;
                    const item = sourceValue.items[0] || {};
                    button.addEventListener('click', () => void focusWorkspaceSource({
                        kind: 'highlight', highlightId: item.highlightId || ''
                    }));
                    cells.appendChild(button);
                }
            });
        });
        if (!cells.childElementCount) return;
        block.appendChild(cells);
        container.appendChild(block);
        visibleRowCount += 1;
    });
    if (!visibleRowCount) {
        container.appendChild(createWorkspaceElement(
            'div', 'workspace-empty',
            visibleHighlightSources.size
                ? '当前筛选类型在正文中没有高亮。'
                : '三类高亮均已隐藏；可点击上方按钮重新显示。'
        ));
    }
    if (activePanelTabContext.tabId) {
        void sendTabMessage(activePanelTabContext.tabId, {
            action: 'setHighlightSourceVisibility',
            visibleSources: [...visibleHighlightSources]
        }).catch(() => undefined);
    }
}

function appendFigureWorkspaceField(parent, label, value) {
    if (!value) return;
    const row = createWorkspaceElement('p', 'workspace-figure-field');
    row.append(
        createWorkspaceElement('strong', '', `${label}\uff1a`),
        document.createTextNode(String(value))
    );
    parent.appendChild(row);
}

function figureWorkspaceEditDescriptorKey(descriptor = {}) {
    if (descriptor.scope === 'mechanism-node') {
        return JSON.stringify({
            scope: 'mechanism-node', nodeId: String(descriptor.nodeId || ''),
            field: 'label'
        });
    }
    if (descriptor.scope === 'mechanism-edge') {
        return JSON.stringify({
            scope: 'mechanism-edge', edgeId: String(descriptor.edgeId || ''),
            field: 'label'
        });
    }
    if (descriptor.scope === 'meta') {
        return JSON.stringify({
            scope: 'meta', collection: String(descriptor.collection || ''),
            index: Number(descriptor.index), field: 'value'
        });
    }
    if (descriptor.scope === 'evidence-block' || descriptor.scope === 'evidence-transition') {
        return JSON.stringify({
            scope: descriptor.scope,
            figureId: String(descriptor.figureId || ''),
            blockId: String(descriptor.blockId || ''),
            field: String(descriptor.field || '')
        });
    }
    return JSON.stringify({
        scope: descriptor.scope === 'panel' ? 'panel' : 'overview',
        figureId: String(descriptor.figureId || ''),
        ...(descriptor.scope === 'panel'
            ? { panelId: String(descriptor.panelId || '') } : {}),
        field: String(descriptor.field || '')
    });
}

function selectFigureWorkspaceEditTarget(candidates, descriptorKey, presentationHint) {
    const matches = (Array.isArray(candidates) ? candidates : [])
        .filter(element => element?.dataset?.figureEditPath === descriptorKey);
    const occurrence = presentationHint?.occurrence === 'row' ||
        presentationHint?.occurrence === 'column' ? presentationHint.occurrence : '';
    const nodeId = typeof presentationHint?.nodeId === 'string'
        ? presentationHint.nodeId : '';
    if (occurrence && nodeId) {
        const preferred = matches.find(element =>
            element.dataset.figureEditOccurrence === occurrence &&
            element.dataset.mechanismNodeId === nodeId);
        if (preferred) return preferred;
    }
    return matches[0] || null;
}

function findFigureWorkspaceEditTarget(descriptor, presentationHint = null) {
    const key = figureWorkspaceEditDescriptorKey(descriptor);
    return selectFigureWorkspaceEditTarget(
        [...document.querySelectorAll('[data-figure-edit-path]')],
        key,
        presentationHint
    );
}

function resolveFigureWorkspaceInlineEditMount(target, descriptorKey, findTarget) {
    if (target?.isConnected === true &&
        target?.dataset?.figureEditPath === descriptorKey) return target;
    return typeof findTarget === 'function' ? findTarget() : null;
}

function updateFigureWorkspaceInlineEditStatus(state = {}) {
    const editor = document.querySelector('.workspace-figure-inline-editor');
    const output = editor?.parentElement?.querySelector('[data-figure-edit-status]');
    if (output) {
        output.textContent = String(state.message || '').slice(0, 160);
        output.dataset.state = String(state.type || 'editing');
    }
    if (editor) {
        const pending = state.type === 'pending';
        editor.readOnly = pending;
        editor.setAttribute('aria-busy', String(pending));
    }
    const mechanismStatus = document.getElementById('mechanismChainSaveStatus');
    if (mechanismStatus && activeWorkspaceView === 'mechanism') {
        mechanismStatus.textContent = String(state.message || '已保存').slice(0, 160);
        mechanismStatus.dataset.state = String(state.type || 'saved');
    }
}

async function openFigureWorkspaceInlineEditor(target, descriptor, value, label, isList) {
    if (!target?.isConnected || activeSupplementalPlacementCleanup) return;
    const occurrence = target.dataset.figureEditOccurrence;
    const nodeId = target.dataset.mechanismNodeId;
    const presentationHint = descriptor?.scope === 'mechanism-node' &&
        (occurrence === 'row' || occurrence === 'column') &&
        nodeId === String(descriptor.nodeId || '')
        ? { occurrence, nodeId } : null;
    const started = await figureWorkspaceEditorLifecycle.begin(descriptor, value, {
        mount: target,
        context: captureFigureWorkspaceEditContext(),
        presentationHint
    });
    if (started.status !== 'started') return;
    const descriptorKey = figureWorkspaceEditDescriptorKey(descriptor);
    const liveTarget = resolveFigureWorkspaceInlineEditMount(
        target, descriptorKey, () => findFigureWorkspaceEditTarget(descriptor)
    );
    if (!liveTarget?.isConnected) {
        figureWorkspaceInlineEditController.abort('detached');
        return;
    }
    liveTarget.removeAttribute('role');
    liveTarget.tabIndex = -1;
    const editor = createWorkspaceElement('textarea', 'workspace-figure-inline-editor');
    editor.value = String(value ?? '');
    editor.maxLength = 4000;
    editor.rows = descriptor.field === 'note' ? 5
        : descriptor.scope === 'mechanism-node' ? 2 : (isList ? 4 : 3);
    editor.setAttribute('aria-label', `${label}；Ctrl 或 Command 加 Enter 保存，Escape 取消`);
    editor.setAttribute('aria-describedby', `${liveTarget.id}-instructions`);
    const instructions = createWorkspaceElement(
        'small', 'workspace-figure-inline-instructions',
        `${isList ? '每行一项；' : ''}Ctrl/⌘+Enter 保存，Escape 取消`
    );
    instructions.id = `${liveTarget.id}-instructions`;
    const editStatus = createWorkspaceElement('small', 'workspace-figure-inline-status', '');
    editStatus.dataset.figureEditStatus = 'true';
    editStatus.setAttribute('aria-live', 'polite');
    liveTarget.replaceChildren(editor, instructions, editStatus);
    editor.addEventListener('input', () => {
        figureWorkspaceInlineEditController.update(editor.value);
    });
    editor.addEventListener('keydown', event => {
        if (event.isComposing) return;
        if (event.key === 'Escape') {
            event.preventDefault();
            figureWorkspaceInlineEditController.cancel();
            return;
        }
        if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
            event.preventDefault();
            void figureWorkspaceInlineEditController.save('shortcut');
        }
    });
    editor.addEventListener('blur', () => {
        void figureWorkspaceInlineEditController.blur();
    });
    editor.focus();
    editor.setSelectionRange(editor.value.length, editor.value.length);
}

function appendFigureWorkspaceViewField(parent, field, identity = {}) {
    const row = createWorkspaceElement(
        'section',
        `workspace-figure-view-field${field?.key === 'note' ? ' workspace-panel-note' : ''}`
    );
    row.dataset.field = String(field?.key || '');
    if (identity.figureId) row.dataset.figureId = identity.figureId;
    if (identity.panelId) row.dataset.panelId = identity.panelId;
    row.appendChild(createWorkspaceElement(
        'strong', 'workspace-figure-view-field-label', `${field?.label || ''}：`
    ));
    const values = Array.isArray(field?.value)
        ? field.value.map(value => String(value || '').trim()).filter(Boolean)
        : [];
    const editValue = Object.prototype.hasOwnProperty.call(field || {}, 'editValue')
        ? field.editValue : field?.value;
    const descriptor = identity.descriptor && typeof identity.descriptor === 'object'
        ? { ...identity.descriptor }
        : {
            scope: identity.panelId ? 'panel' : 'overview',
            figureId: String(identity.figureId || ''),
            ...(identity.panelId ? { panelId: String(identity.panelId) } : {}),
            field: String(field?.key || '')
        };
    const path = figureWorkspaceEditDescriptorKey(descriptor);
    const target = createWorkspaceElement('div', 'workspace-figure-edit-target');
    target.id = `figure-edit-${Math.random().toString(36).slice(2)}`;
    target.dataset.figureEditPath = path;
    target.tabIndex = 0;
    target.setAttribute('role', 'button');
    target.setAttribute(
        'aria-label', `${field?.label || '字段'}：双击或按 Enter、空格编辑`
    );
    target.setAttribute('aria-keyshortcuts', 'Enter Space');
    if (values.length) {
        const list = createWorkspaceElement('ul', 'workspace-figure-view-list');
        values.forEach(value => list.appendChild(createWorkspaceElement('li', '', value)));
        target.appendChild(list);
    } else if (String(field?.value || '').trim()) {
        target.appendChild(createWorkspaceElement(
            'span', 'workspace-figure-view-value', String(field.value)
        ));
    } else {
        const placeholder = createWorkspaceElement(
            'span', 'workspace-figure-empty-value', '尚未填写'
        );
        placeholder.dataset.figureWorkspacePlaceholder = 'true';
        target.appendChild(placeholder);
    }
    const edit = () => void openFigureWorkspaceInlineEditor(
        target,
        descriptor,
        Array.isArray(editValue)
            ? editValue.map(value => String(value || '').trim()).filter(Boolean).join('\n')
            : String(editValue || ''),
        String(field?.label || '字段'),
        Array.isArray(editValue)
    );
    target.addEventListener('dblclick', edit);
    target.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            edit();
        }
    });
    row.appendChild(target);
    parent.appendChild(row);
}

function figureOverviewExpansionKey(snapshot, figureId) {
    const workspace = snapshot?.localWorkspace || {};
    const document = String(workspace.workspaceId || workspace.canonicalUrl || snapshot?.url || '');
    if (!document || !figureId) return '';
    return JSON.stringify([document, Number(workspace.workspaceGeneration) || 0,
        String(workspace.contentHash || snapshot?.documentHash || ''), String(figureId)]);
}

function projectFigureOverviewField(field) {
    const original = field?.value;
    const projected = { ...field, editValue: Object.hasOwn(field || {}, 'editValue')
        ? field.editValue : original };
    if (Array.isArray(original) || typeof original !== 'string') return projected;
    const text = original.trim();
    // Recognize explicit markers even after legacy scalar normalization joins lines.
    const markers = [...text.matchAll(/(?:^|\s)(?:[-*•]\s+|[1-9]\d*\.\s+|[1-9]\d*[)）、]\s*|[一二三四五六七八九十]+[、）)]\s*)/gu)];
    if (markers.length > 1 && markers[0].index === 0) {
        projected.value = markers.map((marker, index) => text.slice(marker.index,
            markers[index + 1]?.index ?? text.length).trim());
        return projected;
    }
    if (!['claimBoundary', 'authorAssembly', 'remainingQuestion'].includes(field.key)) return projected;
    const cuts = [];
    const stack = [];
    const pairs = { '(': ')', '（': '）', '[': ']', '【': '】', '“': '”', '「': '」', '"': '"' };
    for (let index = 0; index < text.length; index += 1) {
        const char = text[index];
        if (stack.length && char === stack.at(-1)) { stack.pop(); continue; }
        if (Object.hasOwn(pairs, char)) { stack.push(pairs[char]); continue; }
        if (stack.length) continue;
        if (char === ';' || char === '；') cuts.push(index + 1);
        else if (field.key === 'authorAssembly' && /先/u.test(text.slice(0, index)) &&
            /[,，]/u.test(char) && /^(?:再(?:用|以|通过)|接着|随后|最后)/u.test(text.slice(index + 1).trimStart())) {
            cuts.push(index + 1);
        }
    }
    if (!cuts.length) return projected;
    const points = [0, ...cuts, text.length].map((start, index, offsets) =>
        text.slice(start, offsets[index + 1] ?? text.length).trim()).filter(Boolean);
    // Do not sever a condition from its consequence or a quoted/bracketed clause.
    if (points.length < 2 || stack.length || points.slice(1).some(point =>
        /^(?:则|否则|因此|从而|故|所以|因而|then\b|otherwise\b|therefore\b|thus\b|hence\b)/iu.test(point))) return projected;
    projected.value = points;
    return projected;
}

function restoreFigureOverviewExpansionState(entries) {
    figureOverviewExpansionState.clear();
    (Array.isArray(entries) ? entries.slice(-256) : []).forEach(entry => {
        if (Array.isArray(entry) && typeof entry[0] === 'string' && entry[0].length <= 2048 &&
            typeof entry[1] === 'boolean') figureOverviewExpansionState.set(entry[0], entry[1]);
    });
}

function appendFigureWorkspaceOverview(parent, view, snapshot = currentWorkspaceSnapshot) {
    const overview = createWorkspaceElement('details', 'workspace-figure-overview');
    const key = figureOverviewExpansionKey(snapshot, view.figureId);
    overview.dataset.figureOverviewKey = key;
    // Default collapsed is a reversible UI choice, not a change to scientific data.
    overview.open = key ? figureOverviewExpansionState.get(key) === true : false;
    const summary = createWorkspaceElement('summary', 'workspace-figure-overview-summary', '整图概览');
    overview.appendChild(summary);
    const body = createWorkspaceElement('div', 'workspace-figure-overview-body');
    (Array.isArray(view?.overview) ? view.overview : []).forEach(field => {
        appendFigureWorkspaceViewField(body, projectFigureOverviewField(field), { figureId: view.figureId });
    });
    overview.appendChild(body);
    const rememberExpansion = () => {
        if (!overview.isConnected) return;
        if (key) {
            figureOverviewExpansionState.set(key, overview.open);
            while (figureOverviewExpansionState.size > 256) {
                figureOverviewExpansionState.delete(figureOverviewExpansionState.keys().next().value);
            }
            scheduleActiveWorkspaceUiStateSave();
        }
    };
    // Native toggle is asynchronous: record click/keyboard activation before a live redraw.
    summary.addEventListener('click', event => {
        event.preventDefault();
        overview.open = !overview.open;
        rememberExpansion();
    });
    overview.addEventListener('toggle', () => {
        if (!overview.isConnected) return;
        rememberExpansion();
        const editing = figureWorkspaceInlineEditController.getState().active?.descriptor;
        if (!overview.open && editing?.scope === 'overview' && editing.figureId === view.figureId) {
            void figureWorkspaceInlineEditController.flush('collapse').then(result => {
                if (overview.isConnected && ['failed', 'conflict', 'stale_response', 'context_changed'].includes(result?.status)) overview.open = true;
            });
        }
    });
    parent.appendChild(overview);
}

const FIGURE_RESULT_EDITOR_OVERVIEW_FIELDS = Object.freeze([
    ['figureQuestion', '本图问题'],
    ['coreConclusion', '核心结论'],
    ['claimBoundary', '证据边界'],
    ['authorAssembly', '组图思想']
]);
const FIGURE_RESULT_EDITOR_PANEL_FIELDS = Object.freeze([
    ['phenotypeName', '表型名称'],
    ['methods', '方法（每行一项）', 'list'],
    ['purpose', '目的'],
    ['design', '设计'],
    ['comparison', '比较'],
    ['directObservation', '直接观察'],
    ['localInference', '局部推论'],
    ['contribution', '对论证链的贡献']
]);
const FIGURE_RESULT_EDITOR_DEEP_FIELDS = Object.freeze([
    ['qualitativeQuantitativeLink', '定性与定量互证'],
    ['negativeResultValue', '阴性结果的价值'],
    ['paperArgumentRole', '全文论证角色'],
    ['deepAuthorStrategy', '深层组图策略'],
    ['alternativeExplanations', '替代解释（每行一项）', 'list'],
    ['missingLinksIfPanelRemoved', '删除 Panel 后缺失的论证（每行一项）', 'list']
]);

function cloneFigureResultForEditor(value) {
    if (!value || typeof value !== 'object') return null;
    try {
        return typeof structuredClone === 'function'
            ? structuredClone(value) : JSON.parse(JSON.stringify(value));
    } catch (_) {
        return JSON.parse(JSON.stringify(value));
    }
}

function setFigureResultEditorPath(target, path, value) {
    let cursor = target;
    path.slice(0, -1).forEach((part, index) => {
        if (cursor?.[part] === undefined || cursor?.[part] === null) {
            cursor[part] = typeof path[index + 1] === 'number' ? [] : {};
        }
        cursor = cursor[part];
    });
    if (cursor) cursor[path.at(-1)] = value;
}

function appendFigureResultEditorField(parent, label, value, path, {
    valueType = 'text',
    help = ''
} = {}) {
    const field = createWorkspaceElement('label', 'figure-result-editor-field');
    field.appendChild(createWorkspaceElement('span', '', label));
    const input = document.createElement('textarea');
    input.rows = valueType === 'list' ? 3 : 4;
    input.maxLength = valueType === 'list' ? 12000 : 6000;
    input.value = valueType === 'list'
        ? (Array.isArray(value) ? value.join('\n') : '')
        : String(value || '');
    input.dataset.figureEditPath = JSON.stringify(path);
    input.dataset.figureEditValueType = valueType;
    input.setAttribute('aria-label', label);
    field.appendChild(input);
    if (help) field.appendChild(createWorkspaceElement('small', '', help));
    parent.appendChild(field);
    return input;
}

function createFigureResultEditorSection(title, description = '') {
    const section = createWorkspaceElement('section', 'figure-result-editor-section');
    section.appendChild(createWorkspaceElement('h3', '', title));
    if (description) section.appendChild(createWorkspaceElement('p', '', description));
    return section;
}

function createFigureResultEditorSubsection(title, { open = false } = {}) {
    const details = createWorkspaceElement('details', 'figure-result-editor-subsection');
    details.open = open;
    details.appendChild(createWorkspaceElement('summary', '', title));
    const fields = createWorkspaceElement('div', 'figure-result-editor-subsection-fields');
    details.appendChild(fields);
    return { details, fields };
}

function renderFigureResultEditor(result) {
    const body = document.getElementById('figureResultEditorBody');
    if (!body) return;
    body.replaceChildren();

    const overview = createFigureResultEditorSection(
        '整图结论',
        '这里的修改会同步影响完成态的一句话结论和后续主图串解输入。'
    );
    FIGURE_RESULT_EDITOR_OVERVIEW_FIELDS.forEach(([key, label]) => {
        appendFigureResultEditorField(overview, label, result?.[key], [key]);
    });
    body.appendChild(overview);

    const panels = Array.isArray(result?.panels) ? result.panels : [];
    if (panels.length) {
        const panelSection = createFigureResultEditorSection(
            `Panel 解读 · ${panels.length}`,
            'Panel 编号、证据类型等结构字段保持不变；可修订所有面向读者的解释文字。'
        );
        panels.forEach((panel, index) => {
            const panelId = String(panel?.panel || index + 1).toUpperCase();
            const subsection = createFigureResultEditorSubsection(
                `Panel ${panelId}`,
                { open: index === 0 }
            );
            FIGURE_RESULT_EDITOR_PANEL_FIELDS.forEach(([key, label, type]) => {
                appendFigureResultEditorField(
                    subsection.fields,
                    label,
                    panel?.[key],
                    ['panels', index, key],
                    { valueType: type === 'list' ? 'list' : 'text' }
                );
            });
            panelSection.appendChild(subsection.details);
        });
        body.appendChild(panelSection);
    }

    const chain = Array.isArray(result?.argumentChain) ? result.argumentChain : [];
    if (chain.length) {
        const chainSection = createFigureResultEditorSection('多米诺论证链');
        chain.forEach((step, index) => {
            const refs = (step?.panels || []).join('、') || '整图';
            const subsection = createFigureResultEditorSubsection(
                `步骤 ${index + 1} · ${refs}`
            );
            appendFigureResultEditorField(
                subsection.fields, '确立了什么', step?.established,
                ['argumentChain', index, 'established']
            );
            appendFigureResultEditorField(
                subsection.fields, '为什么进入下一步', step?.handoff,
                ['argumentChain', index, 'handoff']
            );
            chainSection.appendChild(subsection.details);
        });
        body.appendChild(chainSection);
    }

    const groups = Array.isArray(result?.panelGroups) ? result.panelGroups : [];
    if (groups.length) {
        const groupSection = createFigureResultEditorSection('证据组织');
        groups.forEach((group, index) => {
            const refs = (group?.panels || []).join('、') || `证据组 ${index + 1}`;
            const subsection = createFigureResultEditorSubsection(`Panel ${refs}`);
            appendFigureResultEditorField(
                subsection.fields, '共同目标', group?.groupGoal,
                ['panelGroups', index, 'groupGoal']
            );
            appendFigureResultEditorField(
                subsection.fields, '组小结', group?.groupConclusion,
                ['panelGroups', index, 'groupConclusion']
            );
            groupSection.appendChild(subsection.details);
        });
        body.appendChild(groupSection);
    }

    const bridges = Array.isArray(result?.logicBridges) ? result.logicBridges : [];
    if (bridges.length) {
        const bridgeSection = createFigureResultEditorSection('组间逻辑连接');
        bridges.forEach((bridge, index) => {
            const relation = [bridge?.fromGroup, bridge?.toGroup]
                .filter(Boolean).join(' ⇒ ') || `连接 ${index + 1}`;
            const subsection = createFigureResultEditorSubsection(relation);
            appendFigureResultEditorField(
                subsection.fields, '下一步必要性', bridge?.bridge,
                ['logicBridges', index, 'bridge']
            );
            bridgeSection.appendChild(subsection.details);
        });
        body.appendChild(bridgeSection);
    }

    if (result?.analysisDepth === 'deep') {
        const deepSection = createFigureResultEditorSection('深度证据审查');
        FIGURE_RESULT_EDITOR_DEEP_FIELDS.forEach(([key, label, type]) => {
            appendFigureResultEditorField(
                deepSection, label, result?.[key], [key],
                { valueType: type === 'list' ? 'list' : 'text' }
            );
        });
        body.appendChild(deepSection);
    }
}

function collectFigureResultEditorResult() {
    const result = cloneFigureResultForEditor(figureResultEditorState.result);
    if (!result) return null;
    document.querySelectorAll('#figureResultEditorBody [data-figure-edit-path]')
        .forEach(input => {
            let path = [];
            try {
                path = JSON.parse(input.dataset.figureEditPath || '[]');
            } catch (_) {
                return;
            }
            if (!Array.isArray(path) || !path.length) return;
            const raw = String(input.value || '').normalize('NFKC')
                .replace(/\r\n?/g, '\n').trim();
            const value = input.dataset.figureEditValueType === 'list'
                ? raw.split(/\n+/).map(item => item.trim()).filter(Boolean)
                : raw;
            setFigureResultEditorPath(result, path, value);
        });
    return result;
}

function setFigureResultEditorPending(pending, message = '', error = false) {
    figureResultEditorState.saving = pending === true;
    const status = document.getElementById('figureResultEditorStatus');
    if (status) {
        status.textContent = message;
        status.classList.toggle('is-error', error);
    }
    ['saveFigureResultEditor', 'restoreFigureModelResult', 'cancelFigureResultEditor',
        'closeFigureResultEditor'].forEach(id => {
        const button = document.getElementById(id);
        if (button) button.disabled = pending === true;
    });
}

function closeFigureResultEditor() {
    const dialog = document.getElementById('figureResultEditorDialog');
    if (dialog?.open) dialog.close();
    figureResultEditorState = {
        figureId: '',
        analysisDepth: 'standard',
        result: null,
        saving: false
    };
}

function openFigureResultEditor(figure, result) {
    const dialog = document.getElementById('figureResultEditorDialog');
    if (!dialog || !figure?.figureId || !result) return;
    const analysisDepth = result.analysisDepth === 'deep' ? 'deep' : 'standard';
    figureResultEditorState = {
        figureId: String(figure.figureId),
        analysisDepth,
        result: cloneFigureResultForEditor(result),
        saving: false
    };
    const title = document.getElementById('figureResultEditorTitle');
    if (title) {
        title.textContent = `编辑 ${figure.figureLabel || figure.figureId} 解读`;
    }
    const hasManualEdit = Boolean(figure?.manualEdits?.[analysisDepth]);
    const restore = document.getElementById('restoreFigureModelResult');
    if (restore) {
        restore.hidden = !hasManualEdit;
        restore.dataset.confirmRestore = 'false';
        restore.textContent = '恢复模型原文';
    }
    renderFigureResultEditor(figureResultEditorState.result);
    setFigureResultEditorPending(
        false,
        hasManualEdit ? '当前显示的是人工修订版。' : '尚未保存人工修订。'
    );
    if (!dialog.open) dialog.showModal();
    requestAnimationFrame(() =>
        dialog.querySelector('textarea')?.focus({ preventScroll: true }));
}

async function saveFigureResultEditor() {
    if (figureResultEditorState.saving) return;
    const result = collectFigureResultEditorResult();
    if (!result) return;
    if (![result.figureQuestion, result.coreConclusion, result.authorAssembly]
        .some(value => String(value || '').trim())) {
        setFigureResultEditorPending(
            false, '本图问题、核心结论和组图思想不能同时为空。', true
        );
        return;
    }
    const panelContext = capturePanelContext();
    setFigureResultEditorPending(true, '正在保存人工修订…');
    try {
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'updateFigureAnalysisResult',
            figureId: figureResultEditorState.figureId,
            analysisDepth: figureResultEditorState.analysisDepth,
            result
        });
        if (!response?.success) {
            throw new Error(response?.error || 'FIGURE_RESULT_EDIT_SAVE_FAILED');
        }
        if (!isCurrentPanelContext(panelContext)) return;
        const figureId = figureResultEditorState.figureId;
        closeFigureResultEditor();
        figureExpansionState.set(figureId, true);
        await refreshArticleWorkspace();
        showStatus(`${figureId} 的人工修订已保存`, 'success');
    } catch (error) {
        if (isCurrentPanelContext(panelContext)) {
            setFigureResultEditorPending(
                false, `保存失败：${error.message}`, true
            );
        }
    }
}

async function restoreFigureModelResult() {
    if (figureResultEditorState.saving) return;
    const restore = document.getElementById('restoreFigureModelResult');
    if (restore?.dataset.confirmRestore !== 'true') {
        if (restore) {
            restore.dataset.confirmRestore = 'true';
            restore.textContent = '再次点击确认恢复';
        }
        setFigureResultEditorPending(
            false, '再次点击将删除本层级的人工修订，并恢复模型原文。'
        );
        return;
    }
    const panelContext = capturePanelContext();
    setFigureResultEditorPending(true, '正在恢复模型原文…');
    try {
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'restoreFigureAnalysisResult',
            figureId: figureResultEditorState.figureId,
            analysisDepth: figureResultEditorState.analysisDepth
        });
        if (!response?.success) {
            throw new Error(response?.error || 'FIGURE_RESULT_EDIT_RESTORE_FAILED');
        }
        if (!isCurrentPanelContext(panelContext)) return;
        const figureId = figureResultEditorState.figureId;
        closeFigureResultEditor();
        figureExpansionState.set(figureId, true);
        await refreshArticleWorkspace();
        showStatus(`${figureId} 已恢复模型原文`, 'success');
    } catch (error) {
        if (isCurrentPanelContext(panelContext)) {
            setFigureResultEditorPending(
                false, `恢复失败：${error.message}`, true
            );
        }
    }
}

function setupFigureResultEditor() {
    const form = document.getElementById('figureResultEditorForm');
    const dialog = document.getElementById('figureResultEditorDialog');
    form?.addEventListener('submit', event => {
        event.preventDefault();
        void saveFigureResultEditor();
    });
    document.getElementById('cancelFigureResultEditor')
        ?.addEventListener('click', closeFigureResultEditor);
    document.getElementById('closeFigureResultEditor')
        ?.addEventListener('click', closeFigureResultEditor);
    document.getElementById('restoreFigureModelResult')
        ?.addEventListener('click', () => void restoreFigureModelResult());
    dialog?.addEventListener('close', () => {
        if (!figureResultEditorState.saving) {
            figureResultEditorState = {
                figureId: '',
                analysisDepth: 'standard',
                result: null,
                saving: false
            };
        }
    });
}

function truncateFigurePanelHeaderText(value, maximumCodePoints) {
    const points = Array.from(String(value || '').trim());
    const maximum = Math.max(0, Math.floor(Number(maximumCodePoints) || 0));
    if (points.length <= maximum) return points.join('');
    if (maximum === 0) return '';
    if (maximum === 1) return '…';
    return `${points.slice(0, maximum - 1).join('')}…`;
}

function formatFigurePanelHeaderDetails(viewPanel, preferences) {
    const selected = preferences || {};
    const localizeDisplay = typeof localizeFigureWorkspaceDisplayValue === 'function'
        ? localizeFigureWorkspaceDisplayValue : value => value;
    const order = [
        'evidenceType', 'purpose', 'experimentalMethods',
        'statisticalMethods', 'comparison', 'directObservation'
    ];
    const details = [];
    let detailCodePoints = 0;
    for (const key of order) {
        if (selected[key] !== true) continue;
        const value = viewPanel?.[key];
        let segment = '';
        if (Array.isArray(value)) {
            const items = [];
            for (const item of value) {
                const text = String(localizeDisplay(item) || '').trim();
                if (!text) continue;
                items.push(truncateFigurePanelHeaderText(
                    text, FIGURE_PANEL_HEADER_MAX_SEGMENT_CODE_POINTS
                ));
                if (items.length >= FIGURE_PANEL_HEADER_MAX_LIST_ITEMS) break;
            }
            segment = truncateFigurePanelHeaderText(
                items.join('、'), FIGURE_PANEL_HEADER_MAX_SEGMENT_CODE_POINTS
            );
        } else {
            segment = truncateFigurePanelHeaderText(
                localizeDisplay(value),
                FIGURE_PANEL_HEADER_MAX_SEGMENT_CODE_POINTS
            );
        }
        if (!segment) continue;
        const separatorLength = details.length ? 3 : 0;
        const available = FIGURE_PANEL_HEADER_MAX_DETAILS_CODE_POINTS -
            detailCodePoints - separatorLength;
        if (available <= 0) break;
        const bounded = truncateFigurePanelHeaderText(segment, available);
        if (!bounded) break;
        details.push(bounded);
        detailCodePoints += separatorLength + Array.from(bounded).length;
        if (bounded !== segment) break;
    }
    return details;
}

function formatFigurePanelHeader(viewPanel, preferences = figurePanelHeaderFieldsState) {
    if (typeof preferences === 'string') {
        return String(preferences || viewPanel?.displayId || viewPanel?.panel || '').trim();
    }
    return [
        String(viewPanel?.displayId || viewPanel?.panelId || '').trim(),
        ...formatFigurePanelHeaderDetails(viewPanel, preferences)
    ].filter(Boolean).join(' · ');
}

function appendFigurePanelSummary(summary, viewPanel, {
    displayId = viewPanel?.displayId,
    analyzed = false,
    evidenceGroupIndex = 0,
    evidenceGroupLabel = ''
} = {}) {
    const label = createWorkspaceElement(
        'span', 'workspace-panel-id', String(displayId || viewPanel?.panelId || '?')
    );
    if (analyzed && evidenceGroupIndex > 0) {
        label.dataset.evidenceGroup = String(evidenceGroupIndex);
        label.title = evidenceGroupLabel
            ? `同色 Panel 属于同一证据功能组：${evidenceGroupLabel}`
            : '同色 Panel 属于同一证据功能组';
    }
    const details = formatFigurePanelHeaderDetails(viewPanel, figurePanelHeaderFieldsState);
    const description = createWorkspaceElement('span', 'workspace-panel-description');
    const selectedKeys = Object.keys(figurePanelHeaderFieldsState || {})
        .filter(key => figurePanelHeaderFieldsState[key] === true);
    if (!details.length && selectedKeys.length) {
        const fields = Array.isArray(viewPanel?.fields) ? viewPanel.fields : [];
        const reviewedEmpty = selectedKeys.every(key => fields.some(field =>
            field.key === key && field.humanReviewed === true &&
            !String(field.value || '').trim()));
        const fallbackKeys = ['purpose', 'directObservation', 'phenotypeName',
            'design', 'comparison', 'contribution'];
        const fallback = reviewedEmpty ? '' : fallbackKeys.map(key => {
            const saved = fields.find(field => field.key === key);
            return String(saved ? saved.value || '' : viewPanel?.[key] || '').trim();
        }).find(Boolean);
        details.push(fallback ? truncateFigurePanelHeaderText(
            fallback, FIGURE_PANEL_HEADER_MAX_DETAILS_CODE_POINTS
        ) : reviewedEmpty ? '描述已清空' : '描述待补');
        description.title = fallback
            ? `所选标题字段暂无内容，显示已有描述：${fallback}`
            : reviewedEmpty ? '所选标题字段已人工清空' : '尚无可显示的 Panel 描述';
    }
    description.textContent = details.join(' · ');
    summary.replaceChildren(label, ...(details.length ? [description] : []));
    return summary;
}

function panelFollowupPresetOptions() {
    return (Array.isArray(llmSettingsState?.settings?.figurePanelFollowupPresets)
        ? llmSettingsState.settings.figurePanelFollowupPresets : [])
        .filter(preset => preset?.id && preset?.name && preset?.prompt)
        .map(preset => ({
            id: String(preset.id),
            topic: String(preset.topic || ''),
            name: String(preset.name),
            prompt: String(preset.prompt)
        }));
}

function panelWorkspaceKey(figureId, panelId) {
    return `${String(figureId || '')}::${String(panelId || '').toUpperCase()}`;
}

function formatFigurePanelInputBasis(value) {
    if (!value || typeof value !== 'object') return '';
    const mode = {
        panel_crop: 'Panel 裁切图',
        figure_image: '最佳单张 Figure 图',
        caption_context: '图注与相关正文（未发送图片）'
    }[value.inputMode] || '按容量规划的证据';
    const size = value.pixelsSupplied && value.imageWidth && value.imageHeight
        ? ` · ${value.imageWidth}×${value.imageHeight} px` : '';
    const retry = Number(value.attempts) > 1 ? ` · 共 ${value.attempts} 次模型请求` : '';
    return `${mode}${size}${retry}`;
}

function getPanelFollowupDraft(figureId, panelId) {
    const key = panelWorkspaceKey(figureId, panelId);
    if (!panelFollowupDraftState.has(key)) {
        panelFollowupDraftState.set(key, { open: false, topics: new Set(), question: '' });
    }
    return panelFollowupDraftState.get(key);
}

function createFigurePanelUiText(figureLabel, panelId, {
    round = 0,
    totalRounds = 0,
    preferredDisplayId = '',
    isSupplemental = false
} = {}) {
    const displayId = String(
        preferredDisplayId || SciLLM.figurePanelDisplayId(
            figureLabel, isSupplemental, panelId
        )
    );
    return {
        displayId,
        historyHeading: `历史追问 · ${displayId}（${totalRounds} 轮）`,
        roundHeading: `${displayId} · 第 ${round} 轮`,
        followupRunning: `正在追问 ${displayId}…`,
        followupComplete: `已完成 ${displayId} 的定向追问`,
        analysisRunning: `正在解读 ${displayId}…`,
        analysisComplete: `${displayId} 解读完成`
    };
}

function figurePanelUiText(figureId, panelId, options = {}) {
    const figure = (currentWorkspaceSnapshot?.figures?.figures || [])
        .find(item => item.figureId === figureId);
    const view = figureWorkspaceViewState.get(figureId);
    const normalizedPanelId = String(panelId || '').trim().toUpperCase();
    const viewPanel = view?.panels?.find(panel => panel.panelId === normalizedPanelId);
    return createFigurePanelUiText(
        view?.figureLabel || figure?.figureLabel || figureId,
        normalizedPanelId,
        {
            ...options,
            isSupplemental: view?.isSupplemental ?? figure?.isSupplemental === true,
            preferredDisplayId: viewPanel?.displayId || options.preferredDisplayId
        }
    );
}

function normalizePanelFollowupSourceRefs(figure, panelId, value) {
    const normalizedPanelId = String(panelId || '').trim().toUpperCase();
    const figureId = String(figure?.figureId || '').trim().slice(0, 80);
    const panelRef = String(
        SciLLM.figurePanelDisplayId(
            figure?.figureLabel, figure?.isSupplemental === true, normalizedPanelId
        ) || normalizedPanelId
    ).slice(0, 120);
    const result = panelRef
        ? [{
            kind: 'panel', ref: panelRef, figureId, panelId: normalizedPanelId,
            paragraphId: '', quote: ''
        }]
        : [];
    const knownParagraphIds = new Set(
        [
            ...(Array.isArray(figure?.contextParagraphIds) ? figure.contextParagraphIds : []),
            ...(Array.isArray(figure?.contextParagraphs) ? figure.contextParagraphs
                .map(item => item?.paragraphId) : [])
        ].slice(0, 32).map(item => String(item || '').slice(0, 120)).filter(Boolean)
    );
    const seen = new Set();
    (Array.isArray(value) ? value : []).slice(0, 24).forEach(source => {
        if (!source || typeof source !== 'object' || Array.isArray(source)) return;
        if (Object.keys(source).some(key => ![
            'kind', 'ref', 'figureId', 'panelId', 'paragraphId', 'sentenceId',
            'quote', 'locatorKind', 'scope', 'binding', 'location'
        ].includes(key))) return;
        const paragraphId = String(source.paragraphId || '').trim().slice(0, 120);
        const ref = String(source.ref || '').trim().slice(0, 120);
        const pdfSemantic = source.locatorKind === 'pdf-semantic';
        const binding = source.binding;
        const owner = binding?.binding;
        const location = source.location;
        const fragments = Array.isArray(location?.sourceFragments)
            ? location.sourceFragments.slice(0, 64).map(fragment => ({
                pageNumber: Number(fragment?.pageNumber),
                start: Number(fragment?.start), end: Number(fragment?.end)
            })) : [];
        const validPdf = pdfSemantic && binding?.figureId === figureId &&
            /^[a-f0-9]{64}$/u.test(String(owner?.documentHash || '')) &&
            Number.isSafeInteger(Number(owner?.documentGeneration)) &&
            Number(owner.documentGeneration) > 0 &&
            Number.isSafeInteger(Number(owner?.semanticRevision)) &&
            Number(owner.semanticRevision) > 0 &&
            /^[a-f0-9]{64}$/u.test(String(binding?.semanticContextDigest || '')) &&
            location?.paragraphId === paragraphId && location?.locatorStatus === 'resolved' &&
            typeof location?.expectedNormalizedQuote === 'string' &&
            location.expectedNormalizedQuote.length > 0 && fragments.length > 0 &&
            fragments.every(fragment => Number.isSafeInteger(fragment.pageNumber) &&
                fragment.pageNumber > 0 && Number.isSafeInteger(fragment.start) &&
                fragment.start >= 0 && Number.isSafeInteger(fragment.end) &&
                fragment.end > fragment.start) &&
            source.scope?.kind === 'pdf-figure-panel' &&
            source.scope.figureId === figureId &&
            source.scope.panelId === normalizedPanelId;
        if (source.kind !== 'paragraph' || (ref && ref !== paragraphId) ||
            (!knownParagraphIds.has(paragraphId) && !validPdf) ||
            (pdfSemantic && !validPdf) || seen.has(paragraphId)) return;
        seen.add(paragraphId);
        result.push({
            kind: 'paragraph',
            ref: paragraphId,
            paragraphId,
            quote: validPdf ? location.expectedNormalizedQuote.slice(0, 600)
                : String(source.quote || '').normalize('NFKC')
                    .replace(/[\u0000-\u001F\u007F]/g, '').trim().slice(0, 600),
            ...(validPdf ? {
                figureId,
                panelId: normalizedPanelId,
                sentenceId: String(source.sentenceId || location.sentenceId || '').slice(0, 160),
                locatorKind: 'pdf-semantic',
                scope: { kind: 'pdf-figure-panel', figureId,
                    panelId: normalizedPanelId },
                binding: JSON.parse(JSON.stringify(binding)),
                location: {
                    paragraphId,
                    ...(location.sentenceId
                        ? { sentenceId: String(location.sentenceId).slice(0, 160) } : {}),
                    expectedNormalizedQuote: String(location.expectedNormalizedQuote).slice(0, 50000),
                    locatorStatus: 'resolved',
                    locatorPrecision: String(location.locatorPrecision || '').slice(0, 40),
                    sourceFragments: fragments
                }
            } : {})
        });
    });
    return result;
}

async function focusPanelFollowupParagraphSource(
    figure,
    source,
    panelContext = capturePanelContext(),
    focus = focusWorkspaceSource,
    isCurrent = isCurrentPanelContext,
    report = showStatus
) {
    let focused = false;
    try {
        if (isCurrent(panelContext)) {
            const target = {
                kind: 'figure-followup-paragraph',
                figureId: String(figure?.figureId || ''),
                paragraphId: String(source?.paragraphId || '')
            };
            const quote = String(source?.quote || '').trim();
            if (quote) target.quote = quote;
            if (source?.locatorKind === 'pdf-semantic') {
                Object.assign(target, {
                    panelId: String(source.panelId || ''),
                    sentenceId: String(source.sentenceId || ''),
                    locatorKind: 'pdf-semantic',
                    scope: source.scope,
                    binding: source.binding,
                    location: source.location
                });
            }
            focused = await focus(target);
            focused = focused === true && isCurrent(panelContext);
        }
    } catch (_) {
        focused = false;
    }
    if (!focused) {
        report('无法定位原文依据，论文页面可能已更新。', 'error');
    }
    return focused;
}

function jumpToPanelFollowupSource(
    source,
    panelContext = capturePanelContext(),
    switchView = switchWorkspaceView,
    navigate = navigateFigureQuickAnchor,
    isCurrent = isCurrentPanelContext,
    report = showStatus
) {
    return (async () => {
        const figureId = String(source?.figureId || '').trim().slice(0, 80);
        const normalizedPanelId = String(source?.panelId || '').trim().toUpperCase();
        let focused = false;
        try {
            if (figureId && /^[A-Z0-9][A-Z0-9.+-]{0,7}$/.test(normalizedPanelId) &&
                isCurrent(panelContext)) {
                switchView('figures');
                focused = await navigate(figureId, normalizedPanelId);
                focused = focused === true && isCurrent(panelContext);
            }
        } catch (_) {
            focused = false;
        }
        if (!focused) report('无法定位原文依据，论文页面可能已更新。', 'error');
        return focused;
    })();
}

function appendPanelFollowupSourceRefs(parent, figure, panelId, value) {
    const sources = normalizePanelFollowupSourceRefs(figure, panelId, value?.sourceRefs);
    if (!sources.length) return;
    const panelContext = Object.freeze({ ...capturePanelContext() });
    const wrap = createWorkspaceElement('span', 'workspace-panel-followup-sources');
    sources.forEach((source, index) => {
        const button = createWorkspaceElement(
            'button',
            'article-chat-inline-citation workspace-panel-followup-source',
            String(index + 1)
        );
        button.type = 'button';
        button.title = `定位证据 ${index + 1}：${source.ref}`;
        button.setAttribute?.('aria-label', button.title);
        if (source.kind === 'panel') {
            button.addEventListener('click', () => {
                void jumpToPanelFollowupSource(source, panelContext);
            });
        } else {
            if (source.quote) button.dataset.quote = source.quote;
            button.addEventListener('click', () => {
                void focusPanelFollowupParagraphSource(figure, source, panelContext);
            });
        }
        wrap.appendChild(button);
    });
    parent.appendChild(wrap);
}

function appendPanelFollowupHistory(
    root, figure, panelId, panelDisplayId, currentAnswer = null
) {
    const history = Array.isArray(figure?.panelFollowupHistories?.[panelId])
        ? figure.panelFollowupHistories[panelId] : [];
    const priorHistory = currentAnswer?.answer && history.length >= 2
        ? history.slice(0, -2) : history;
    if (!priorHistory.length) return;

    const details = document.createElement('details');
    details.className = 'workspace-panel-followup-history';
    details.open = true;
    const summary = document.createElement('summary');
    const totalRounds = Math.ceil(priorHistory.length / 2);
    const historyText = createFigurePanelUiText(figure?.figureLabel, panelId, {
        totalRounds,
        preferredDisplayId: panelDisplayId
    });
    summary.textContent = historyText.historyHeading;
    details.appendChild(summary);
    const turns = createWorkspaceElement('div', 'workspace-panel-followup-history-turns');
    for (let index = 0; index < priorHistory.length; index += 2) {
        const round = createWorkspaceElement('section', 'workspace-panel-followup-history-round');
        const uiText = createFigurePanelUiText(figure?.figureLabel, panelId, {
            round: Math.floor(index / 2) + 1,
            totalRounds,
            preferredDisplayId: panelDisplayId
        });
        round.appendChild(createWorkspaceElement(
            'strong',
            'workspace-panel-followup-history-round-title',
            uiText.roundHeading
        ));
        priorHistory.slice(index, index + 2).forEach(item => {
            const assistant = item?.role === 'assistant';
            const message = createWorkspaceElement(
                'div',
                `workspace-panel-followup-history-message is-${assistant ? 'assistant' : 'user'}`
            );
            if (assistant) message.appendChild(renderArticleChatMarkdown(String(item?.content || '')));
            else message.textContent = `问题：${String(item?.content || '')}`;
            if (assistant) appendPanelFollowupSourceRefs(message, figure, panelId, item);
            round.appendChild(message);
        });
        turns.appendChild(round);
    }
    details.appendChild(turns);
    root.appendChild(details);
}

function createPanelFollowupControl(figure, panel, panelDisplayId = '') {
    const panelId = String(panel?.panel || '').toUpperCase();
    const uiText = createFigurePanelUiText(figure?.figureLabel, panelId, {
        preferredDisplayId: panelDisplayId
    });
    const displayId = uiText.displayId;
    const followupKey = panelWorkspaceKey(figure.figureId, panelId);
    const followups = figure?.panelFollowups && typeof figure.panelFollowups === 'object'
        ? figure.panelFollowups : {};
    const errors = figure?.panelFollowupErrors && typeof figure.panelFollowupErrors === 'object'
        ? figure.panelFollowupErrors : {};
    const loading = figure?.panelFollowupLoading?.[panelId] === true;
    const draft = getPanelFollowupDraft(figure.figureId, panelId);
    const root = createWorkspaceElement('section', 'workspace-panel-followup');
    root.dataset.panelFollowupKey = followupKey;
    const toggle = createWorkspaceElement(
        'button', 'btn btn-secondary workspace-panel-followup-toggle', '追问此 Panel'
    );
    toggle.type = 'button';
    toggle.setAttribute('aria-expanded', String(draft.open));
    const chooser = createWorkspaceElement('div', 'workspace-panel-followup-chooser');
    chooser.hidden = !draft.open;
    const choices = createWorkspaceElement('div', 'workspace-panel-followup-options');
    const presets = panelFollowupPresetOptions();
    presets.forEach(preset => {
        const choice = createWorkspaceElement('label', 'workspace-panel-followup-option');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.value = preset.id;
        checkbox.checked = draft.topics.has(preset.id);
        checkbox.addEventListener('change', () => {
            if (checkbox.checked) draft.topics.add(preset.id);
            else draft.topics.delete(preset.id);
        });
        choice.title = preset.prompt;
        choice.append(checkbox, document.createTextNode(preset.name));
        choices.appendChild(choice);
    });
    const customLabel = createWorkspaceElement('label', 'workspace-panel-followup-custom');
    customLabel.appendChild(createWorkspaceElement('span', '', '自定义问题（可单独提交）'));
    const customQuestion = document.createElement('textarea');
    customQuestion.rows = 3;
    customQuestion.maxLength = 1200;
    customQuestion.placeholder = '例如：为什么作者在这个 Panel 选择这一统计方法？';
    customQuestion.value = draft.question;
    customQuestion.addEventListener('input', () => { draft.question = customQuestion.value; });
    customLabel.appendChild(customQuestion);
    const submit = createWorkspaceElement('button', 'btn btn-primary workspace-panel-followup-submit',
        loading ? '正在向 LLM 追问…' : '提交追问');
    submit.type = 'button';
    submit.disabled = loading;
    submit.addEventListener('click', () => {
        const submissionGeneration = figureTaskGeneration;
        const presetIds = Array.from(chooser.querySelectorAll('input[type="checkbox"]:checked'))
            .map(input => input.value);
        const selectedPresets = presets.filter(preset => presetIds.includes(preset.id));
        const topics = [...new Set(selectedPresets.map(preset => preset.topic).filter(Boolean))];
        const customPresetQuestions = selectedPresets
            .filter(preset => !preset.topic)
            .map(preset => `${preset.name}：${preset.prompt}`);
        const question = [
            customQuestion.value.trim(),
            ...customPresetQuestions
        ].filter(Boolean).join('\n\n');
        const historyLabel = [
            selectedPresets.map(preset => preset.name).join('、'),
            customQuestion.value.trim()
        ].filter(Boolean).join('；');
        if (!presetIds.length && !question) {
            showStatus('请选择追问方向或输入自定义问题', 'error');
            return;
        }
        submit.disabled = true;
        submit.textContent = '正在向 LLM 追问…';
        const localStatus = root.querySelector('.workspace-panel-followup-status');
        const idleStatusText = answer?.answer
            ? '回答已生成并显示在下方。' : '提交后，回答会直接显示在此 Panel 内。';
        let terminalStatusText = idleStatusText;
        if (localStatus) {
            localStatus.classList.add('is-loading');
            localStatus.textContent = `正在生成 ${displayId} 的回答，完成后会自动定位到这里…`;
        }
        void runFigurePanelFollowup(
            figure.figureId, panelId, topics, question, historyLabel
        )
            .then(result => {
                terminalStatusText = result?.stale === true
                    ? idleStatusText : '回答已生成并显示在下方。';
            })
            .catch(async error => {
                if (submissionGeneration !== figureTaskGeneration) return;
                terminalStatusText = error?.code === 'CANCELLED'
                    ? '追问已取消，可修改问题后重试。'
                    : (answer?.answer
                        ? '回答已生成并显示在下方。'
                        : '追问失败，可修改问题后重试。');
                await refreshArticleWorkspace().catch(() => null);
                if (submissionGeneration !== figureTaskGeneration) return;
                showStatus('Panel 追问失败：' + error.message, 'error');
            })
            .finally(() => {
                submit.disabled = false;
                submit.textContent = '提交追问';
                if (localStatus) {
                    localStatus.classList.remove('is-loading');
                    localStatus.textContent = terminalStatusText;
                }
            });
    });
    chooser.append(choices, customLabel, submit);
    toggle.addEventListener('click', () => {
        chooser.hidden = !chooser.hidden;
        draft.open = !chooser.hidden;
        toggle.setAttribute('aria-expanded', String(!chooser.hidden));
    });
    root.append(toggle, chooser);
    const answer = followups[panelId];
    root.appendChild(createWorkspaceElement(
        'p', `workspace-panel-followup-status${loading ? ' is-loading' : ''}`,
        loading
            ? `正在生成 ${displayId} 的回答，完成后会自动定位到这里…`
            : (answer?.answer ? '回答已生成并显示在下方。' : '提交后，回答会直接显示在此 Panel 内。')
    ));
    appendPanelFollowupHistory(root, figure, panelId, displayId, answer);
    if (answer?.answer) {
        const result = createWorkspaceElement('section', 'workspace-panel-followup-answer');
        result.tabIndex = -1;
        result.setAttribute('aria-live', 'polite');
        result.dataset.panelFollowupAnswer = followupKey;
        if (panelFollowupRevealKey === followupKey) {
            result.classList.add('is-newly-revealed');
        }
        result.appendChild(createWorkspaceElement('strong', '', `${displayId} 追问回答`));
        if (answer.customQuestion) {
            result.appendChild(createWorkspaceElement(
                'p', 'workspace-panel-followup-question', `你的问题：${answer.customQuestion}`
            ));
        }
        const answerParagraph = renderArticleChatMarkdown(answer.answer);
        appendPanelFollowupSourceRefs(answerParagraph, figure, panelId, answer);
        result.appendChild(answerParagraph);
        const inputBasis = formatFigurePanelInputBasis(answer.inputBasis);
        if (inputBasis) result.appendChild(createWorkspaceElement(
            'p', 'workspace-panel-input-basis', `本次依据：${inputBasis}`
        ));
        root.appendChild(result);
    } else if (errors[panelId]) {
        root.appendChild(createWorkspaceElement('p', 'workspace-figure-error', errors[panelId]));
    }
    return root;
}

function revealPanelFollowupAnswer(followupKey) {
    const selector = `[data-panel-followup-answer="${CSS.escape(followupKey)}"]`;
    const answer = document.querySelector(selector);
    if (!answer) return false;
    answer.classList.add('is-newly-revealed');
    answer.scrollIntoView({ behavior: 'smooth', block: 'center' });
    answer.focus({ preventScroll: true });
    setTimeout(() => answer.classList.remove('is-newly-revealed'), 520);
    return true;
}

function stabilizePanelFollowupAnswer(followupKey) {
    const selector = `[data-panel-followup-answer="${CSS.escape(followupKey)}"]`;
    const answer = document.querySelector(selector);
    if (!answer) return false;
    const view = answer.closest('[data-workspace-view="figures"]');
    const answerRect = answer.getBoundingClientRect();
    const viewRect = view?.getBoundingClientRect();
    const inViewport = Boolean(viewRect && answerRect.bottom >= viewRect.top &&
        answerRect.top <= viewRect.bottom);
    if (!inViewport) answer.scrollIntoView({ behavior: 'auto', block: 'center' });
    if (document.activeElement !== answer) answer.focus({ preventScroll: true });
    return true;
}

function figureCatalogPanelIds(figure, result) {
    const seen = new Set();
    return [
        ...(Array.isArray(figure?.panelHints) ? figure.panelHints : []),
        ...(Array.isArray(result?.panels) ? result.panels.map(panel => panel?.panel) : []),
        ...Object.keys(figure?.panelAnalyses || {})
    ].map(value => String(value || '').trim().toUpperCase())
        .filter(value => /^[A-Z0-9][A-Z0-9.+-]{0,7}$/.test(value) &&
            !seen.has(value) && Boolean(seen.add(value)));
}

function figurePanelReferenceMatches(values, panelId) {
    const target = String(panelId || '').trim().toUpperCase();
    return (Array.isArray(values) ? values : [])
        .some(value => String(value || '').trim().toUpperCase() === target);
}

function formatFigurePanelReferences(view, values) {
    const panels = new Map((Array.isArray(view?.panels) ? view.panels : [])
        .map(panel => [String(panel.panelId || '').toUpperCase(), panel.displayId]));
    return (Array.isArray(values) ? values : [])
        .map(value => {
            const panelId = String(value || '').trim().toUpperCase();
            return panels.get(panelId) ||
                SciLLM.figurePanelDisplayId(
                    view?.figureLabel, view?.isSupplemental === true, panelId
                );
        })
        .filter(Boolean)
        .join('、');
}

function figurePanelEvidenceGroup(result, panel, panelId) {
    const panelGroups = Array.isArray(result?.panelGroups) ? result.panelGroups : [];
    const groupIndex = panelGroups.findIndex(group =>
        figurePanelReferenceMatches(group?.panels, panelId)
    );
    if (groupIndex >= 0) {
        const group = panelGroups[groupIndex];
        return {
            key: `panel-group:${groupIndex}`,
            label: String(group?.groupGoal || group?.groupConclusion || `证据组 ${groupIndex + 1}`)
        };
    }
    const argumentChain = Array.isArray(result?.argumentChain) ? result.argumentChain : [];
    const chainIndex = argumentChain.findIndex(step =>
        figurePanelReferenceMatches(step?.panels, panelId)
    );
    if (chainIndex >= 0) {
        return {
            key: `argument-step:${chainIndex}`,
            label: String(argumentChain[chainIndex]?.established || `论证步骤 ${chainIndex + 1}`)
        };
    }
    const role = String(panel?.role || 'evidence');
    const method = String(panel?.methodCategory || 'other');
    const phenotype = String(panel?.phenotypeName || '').normalize('NFKC').trim().toLowerCase();
    return {
        key: `fallback:${role}:${method}:${phenotype}`,
        label: [panel?.role, METHOD_CATEGORY_LABELS[panel?.methodCategory], panel?.phenotypeName]
            .filter(Boolean).join(' · ') || '证据单元'
    };
}

function localizeFigureWorkspaceDisplayValue(value) {
    if (Array.isArray(value)) {
        return value.map(item => localizeFigureWorkspaceDisplayValue(item));
    }
    if (typeof value !== 'string') return value;
    const labels = {
        phenotype_measurement: '表型测量',
        'phenotype measurement': '表型测量',
        caption_statement: '图注陈述',
        'caption statement': '图注陈述',
        direct_observation: '直接观察',
        'direct observation': '直接观察',
        experimental_control: '实验对照',
        'experimental control': '实验对照',
        statistical_comparison: '统计比较',
        'statistical comparison': '统计比较',
        mechanistic_inference: '机制推断',
        'mechanistic inference': '机制推断',
        representative_image: '代表性图像',
        'representative image': '代表性图像',
        quantification: '定量分析',
        localization: '定位观察',
        time_course: '时间序列',
        'time course': '时间序列',
        dose_response: '剂量反应',
        'dose response': '剂量反应'
    };
    const normalized = value.normalize('NFKC').trim();
    const label = labels[normalized];
    const translate = typeof t === 'function' ? t : text => text;
    return label ? translate(label) : value;
}

function localizeFigureWorkspacePanelField(field) {
    if (!field || typeof field !== 'object') return field;
    const localizeDisplay = typeof localizeFigureWorkspaceDisplayValue === 'function'
        ? localizeFigureWorkspaceDisplayValue : value => value;
    let localizedValue = localizeDisplay(field.value);
    if (!['experimentalMethods', 'statisticalMethods'].includes(field.key) ||
        !Array.isArray(localizedValue)) {
        return { ...field, value: localizedValue };
    }
    const localize = typeof SciLLM.localizeFigureMethodLabel === 'function'
        ? SciLLM.localizeFigureMethodLabel : value => String(value || '');
    return {
        ...field,
        value: localizedValue.map(value => {
            const source = String(value || '');
            try {
                return String(localize(source) || source);
            } catch (_) {
                return source;
            }
        })
    };
}

function appendFigureWorkspaceViewPanelFields(parent, viewPanel) {
    [
        'purpose', 'evidenceType', 'phenotypeName', 'experimentalMethods',
        'statisticalMethods', 'design', 'comparison', 'directObservation',
        'localInference', 'contribution'
    ].forEach(key => {
        const field = viewPanel?.fields?.find(item => item.key === key);
        if (field) appendFigureWorkspaceViewField(
            parent, localizeFigureWorkspacePanelField(field), {
            figureId: viewPanel.figureId,
            panelId: viewPanel.panelId
            }
        );
    });
}

function bindFigureEvidenceExpansion(details, stateKey) {
    if (details.dataset) details.dataset.evidenceExpansionKey = stateKey;
    details.open = figureEvidenceExpansionState.get(stateKey) === true;
    details.addEventListener('toggle', () => {
        figureEvidenceExpansionState.set(stateKey, details.open);
    });
    return details;
}

function summarizeFigureEvidenceLabel(value, fallback = '') {
    const primitiveText = input => {
        if (!['string', 'number', 'boolean', 'bigint'].includes(typeof input)) return '';
        try {
            return String(input).normalize('NFKC').replace(/\s+/gu, ' ').trim();
        } catch (_) {
            return '';
        }
    };
    let text = primitiveText(value);
    if (!text) {
        text = primitiveText(fallback) || '证据条目';
    }
    return text;
}

function figureEvidenceSummaryParts(block) {
    const parts = [];
    for (const field of ['groupGoal', 'groupConclusion', 'established']) {
        const state = block?.fieldStates?.[field];
        const value = String(state ? state.value ?? '' : block?.[field] ?? '').trim();
        if (!value) continue;
        const key = value.normalize('NFKC').replace(/\s+/gu, ' ');
        const existing = parts.find(part => part.value.normalize('NFKC').replace(/\s+/gu, ' ') === key);
        if (existing) existing.fields.push(field);
        else parts.push({ value, fields: [field] });
    }
    return parts;
}

function appendFigureEvidenceEditableField(
    parent, label, figureId, block, field, scope = 'evidence-block', displayValue
) {
    const state = block?.fieldStates?.[field];
    const sourceValue = state ? state.value : block?.[field];
    appendFigureWorkspaceViewField(parent, {
        key: field,
        label,
        value: String(displayValue === undefined ? (sourceValue || '') : displayValue),
        editValue: String(sourceValue ?? '')
    }, {
        descriptor: {
            scope,
            figureId: String(figureId || ''),
            blockId: String(block?.id || ''),
            field
        }
    });
}

function bindFigureEvidenceEditFlush(details, figureId, {
    blockIds = [], panelIds = []
} = {}) {
    const ownedBlockIds = new Set(blockIds.map(value => String(value || '')).filter(Boolean));
    const ownedPanelIds = new Set(panelIds.map(value =>
        String(value || '').trim().toUpperCase()
    ).filter(Boolean));
    details.addEventListener('toggle', () => {
        if (details.open) return;
        const editing = figureWorkspaceInlineEditController.getState().active?.descriptor;
        if (editing?.figureId === figureId &&
            (ownedBlockIds.has(String(editing?.blockId || '')) ||
                ownedPanelIds.has(String(editing?.panelId || '').trim().toUpperCase()))) {
            void figureWorkspaceInlineEditController.flush('collapse');
        }
    });
    return details;
}

function resolveFigureEvidencePaperQuestion({
    draft = null, noteState = null, noteTemplates = [], crossFigureLogic = null
} = {}) {
    const text = value => {
        if (!['string', 'number', 'boolean', 'bigint'].includes(typeof value)) return '';
        try {
            return String(value).normalize('NFKC').replace(/\s+/gu, ' ').trim().slice(0, 2400);
        } catch (_) {
            return '';
        }
    };
    const questionText = value => {
        if (value && typeof value === 'object' && !Array.isArray(value)) {
            return text(value.value) || text(value.text) || text(value.statement);
        }
        return text(value);
    };
    const meta = draft?.meta && typeof draft.meta === 'object' ? draft.meta : {};
    const metaQuestions = (Array.isArray(meta.scientificQuestions)
        ? meta.scientificQuestions : [meta.scientificQuestion]
    ).filter(Boolean);
    const reviewedMeta = metaQuestions.find(item =>
        item?.humanReviewed === true && item?.relationType === 'root'
    ) || metaQuestions.find(item => item?.humanReviewed === true);
    const rootMeta = metaQuestions.find(item => item?.relationType === 'root') || metaQuestions[0];
    const acceptedNoteFieldIds = new Set([
        'research_question', 'research_questions', 'scientific_question',
        'scientific_questions', 'key_questions'
    ]);
    const noteValues = noteState?.valuesByTemplate &&
        typeof noteState.valuesByTemplate === 'object'
        ? noteState.valuesByTemplate : {};
    const orderedTemplates = Array.isArray(noteTemplates) ? noteTemplates.slice() : [];
    const activeTemplateId = text(noteState?.templateId);
    orderedTemplates.sort((left, right) =>
        Number(text(right?.id) === activeTemplateId) - Number(text(left?.id) === activeTemplateId)
    );
    let noteQuestion = '';
    for (const template of orderedTemplates) {
        const templateId = text(template?.id);
        const values = noteValues?.[templateId];
        if (!values || typeof values !== 'object') continue;
        for (const field of Array.isArray(template?.fields) ? template.fields : []) {
            const rawFieldId = text(field?.id);
            const fieldId = rawFieldId.toLowerCase();
            const label = text(field?.label);
            if (!acceptedNoteFieldIds.has(fieldId) &&
                !/(?:科学|研究|关键).*问题/u.test(label)) continue;
            noteQuestion = text(values?.[rawFieldId]) ||
                (rawFieldId !== fieldId ? text(values?.[fieldId]) : '');
            if (noteQuestion) break;
        }
        if (noteQuestion) break;
    }
    if (!noteQuestion) {
        for (const values of Object.values(noteValues).slice(0, 20)) {
            if (!values || typeof values !== 'object') continue;
            for (const fieldId of acceptedNoteFieldIds) {
                noteQuestion = text(values?.[fieldId]);
                if (noteQuestion) break;
            }
            if (noteQuestion) break;
        }
    }
    const candidates = [
        [questionText(reviewedMeta), '已保存的人工复核全文问题'],
        [noteQuestion, '文献笔记'],
        [questionText(meta?.researchLogic?.questionTrace?.coreQuestion), '研究逻辑'],
        [questionText(rootMeta), '全文元数据'],
        [questionText(crossFigureLogic?.centralScientificQuestion), '跨图研究逻辑']
    ];
    const resolved = candidates.find(([value]) => Boolean(value));
    return resolved
        ? { value: resolved[0], source: resolved[1], missing: false }
        : { value: '文章科学问题尚未取得', source: '', missing: true };
}

function resolveFigureEvidenceUpstreamContext(block, {
    previousBlock = null, incomingTransitions = [], paperQuestion = null
} = {}) {
    const text = value => {
        if (!['string', 'number', 'boolean', 'bigint'].includes(typeof value)) return '';
        try {
            return String(value).normalize('NFKC').replace(/\s+/gu, ' ').trim().slice(0, 1200);
        } catch (_) {
            return '';
        }
    };
    const firstSentence = value => {
        const normalized = text(value);
        if (!normalized) return '';
        const terminal = normalized.search(/[。！？!?]|\.\s/u);
        return (terminal >= 0 ? normalized.slice(0, terminal + 1) : normalized).trim();
    };
    const fragment = value => firstSentence(value)
        .replace(/[。！？!?；;,.，]+$/u, '').trim().slice(0, 600);
    const sentence = value => {
        const compact = firstSentence(value).slice(0, 900);
        if (!compact) return '';
        return /[。！？!?]$/u.test(compact) ? compact : `${compact}。`;
    };
    const state = block?.fieldStates?.upstreamContext;
    if (state?.humanReviewed === true && !text(state.value)) {
        return { value: '', missing: false, source: 'reviewed-empty' };
    }
    const saved = sentence(state ? state.value : block?.upstreamContext);
    if (saved) return { value: saved, missing: false, source: 'saved' };
    const goal = fragment(block?.groupGoal || block?.established);
    if (paperQuestion) {
        const question = fragment(paperQuestion?.value);
        if (!question || paperQuestion?.missing) return {
            value: '尚未取得论文科学问题，暂无法说明本块承接关系。',
            missing: true,
            source: 'missing-paper-question'
        };
        return {
            value: goal
                ? `围绕论文科学问题“${question}”，本证据块聚焦“${goal}”。`
                : `围绕论文科学问题“${question}”，本证据块展开首轮证据检验。`,
            missing: false,
            source: paperQuestion?.source || 'paper-question'
        };
    }
    const previousBlockId = text(previousBlock?.id);
    const transitions = (Array.isArray(incomingTransitions) ? incomingTransitions : [])
        .filter(item => previousBlockId && text(item?.fromBlockId) === previousBlockId);
    const incoming = transitions.map(item => fragment(
        item?.transitionToNext || item?.handoff || item?.bridge || item?.nextGoal
    )).find(Boolean);
    const unresolved = incoming || fragment(
        previousBlock?.handoff || previousBlock?.transitionToNext
    );
    if (unresolved) return {
        value: goal
            ? `针对前序留下的“${unresolved}”，本证据块聚焦“${goal}”。`
            : `本证据块承接前序留下的“${unresolved}”。`,
        missing: false,
        source: incoming ? 'incoming-transition' : 'previous-handoff'
    };
    return {
        value: '尚未取得前一证据块的未决问题，暂无法说明本块承接关系。',
        missing: true,
        source: 'missing-upstream-context'
    };
}

function createFigureEvidencePanelsDetails(figureId, block, panelCount) {
    const body = createWorkspaceElement('div', 'workspace-evidence-panels-body');
    body.dataset.evidencePanelsBody = 'true';
    body.dataset.evidenceBlockId = String(block?.id || '');
    body.setAttribute('aria-label', `${panelCount} 个 Panel`);
    return body;
}

function createFigureEvidenceBlockDetails(figureId, block, index, {
    previousBlock = null,
    incomingTransitions = [],
    panelCount = 0,
    paperQuestion = null
} = {}) {
    const details = createWorkspaceElement('details', 'workspace-evidence-block');
    details.open = false;
    const blockId = String(block?.id || '');
    details.dataset.evidenceBlockId = blockId;
    const parts = figureEvidenceSummaryParts(block);
    const headingPart = ['groupConclusion', 'established', 'groupGoal']
        .map(field => parts.find(part => part.fields.includes(field))).find(Boolean);
    const label = summarizeFigureEvidenceLabel(
        headingPart?.value || (block?.sourceType === 'bridge' ? block?.transitionToNext : ''),
        block?.sourceType === 'bridge' ? '\u672a\u5339\u914d\u7684\u7ec4\u95f4\u8fde\u63a5' : '暂无证据小结'
    );
    const summary = createWorkspaceElement(
        'summary', 'workspace-evidence-block-summary'
    );
    const panelIds = block?.sourceType !== 'bridge' && Array.isArray(block?.panelIds)
        ? [...new Set(block.panelIds.map(panelId => String(panelId || '').trim()).filter(Boolean))]
        : [];
    if (panelIds.length) {
        const panels = createWorkspaceElement('span', 'workspace-evidence-block-panels');
        const separator = panelIds.every(id => /^[A-Za-z]$/u.test(id)) ? '' : ' · ';
        panels.textContent = `证据块${index + 1}：${panelIds.join(separator)}`;
        summary.appendChild(panels);
    } else summary.textContent = `证据块${index + 1}`;
    const description = createWorkspaceElement('span', 'workspace-evidence-block-description', label);
    description.title = headingPart?.value || label;
    summary.appendChild(description);
    details.appendChild(summary);
    const body = createWorkspaceElement('div', 'workspace-evidence-block-body');
    const upstream = createWorkspaceElement('section', 'workspace-evidence-direction is-upstream');
    const upstreamContext = resolveFigureEvidenceUpstreamContext(block, {
        previousBlock, incomingTransitions, paperQuestion
    });
    upstream.classList.toggle('is-missing', upstreamContext.missing);
    appendFigureEvidenceEditableField(
        upstream, '承上', figureId, block, 'upstreamContext', 'evidence-block',
        upstreamContext.value
    );
    body.appendChild(upstream);
    const core = createWorkspaceElement('section', 'workspace-evidence-core');
    core.appendChild(createWorkspaceElement('strong', 'workspace-evidence-synthesis-label', '证据小结'));
    const synthesis = createWorkspaceElement('div', 'workspace-evidence-synthesis');
    for (const part of parts) {
        const paragraph = createWorkspaceElement('p', '', part.value);
        paragraph.dataset.sourceFields = part.fields.join(' ');
        synthesis.appendChild(paragraph);
    }
    if (!parts.length) synthesis.textContent = '暂无证据小结';
    core.appendChild(synthesis);
    // Three independently editable sources are preserved; the merged display is never saved as one field.
    const sources = createWorkspaceElement('details', 'workspace-evidence-summary-editor');
    sources.appendChild(createWorkspaceElement('summary', '', '分别修订来源字段'));
    [
        ['\u5171\u540c\u76ee\u6807', 'groupGoal'],
        ['\u7ec4\u5c0f\u7ed3', 'groupConclusion'],
        ['\u786e\u7acb\u4e86\u4ec0\u4e48', 'established']
    ].forEach(([fieldLabel, field]) => appendFigureEvidenceEditableField(
        sources, fieldLabel, figureId, block, field, 'evidence-block'
    ));
    bindFigureEvidenceExpansion(sources, `${figureId}::evidence-sources::${blockId}`);
    bindFigureEvidenceEditFlush(sources, figureId, { blockIds: [blockId] });
    core.appendChild(sources);
    appendFigureEvidenceEditableField(core, '证据等级', figureId, block, 'evidenceLevel', 'evidence-block');
    body.appendChild(core);
    if (panelCount > 0) {
        body.appendChild(createFigureEvidencePanelsDetails(figureId, block, panelCount));
    }
    details.appendChild(body);
    bindFigureEvidenceExpansion(details, `${figureId}::evidence::${blockId}`);
    return bindFigureEvidenceEditFlush(details, figureId, {
        blockIds: [blockId],
        panelIds: Array.isArray(block?.panelIds) ? block.panelIds : []
    });
}

function canonicalFigurePanelOrder(viewPanels, _evidenceLayout = []) {
    return (Array.isArray(viewPanels) ? viewPanels : []).slice().sort((left, right) =>
        String(left?.panelId || '').localeCompare(String(right?.panelId || ''), undefined, {
            numeric: true,
            sensitivity: 'base'
        })
    );
}

function appendFigurePanelCatalog(parent, figure, result, view) {
    const viewPanels = Array.isArray(view?.panels) ? view.panels : [];
    parent.appendChild(createWorkspaceElement(
        'h4', 'workspace-figure-section-title', 'Panel 目录与按需解读'
    ));
    if (!viewPanels.length) {
        parent.appendChild(createWorkspaceElement(
            'p', 'workspace-figure-panel-empty',
            '图注中没有稳定的 Panel 标签；仍可使用上方“解图”。'
        ));
        return;
    }
    const resultPanels = Array.isArray(result?.panels) ? result.panels : [];
    const storedEvidenceLayout = Array.isArray(view?.evidenceBlocks)
        ? view.evidenceBlocks
        : (typeof SciLLM.buildEvidenceBlocks === 'function'
            ? SciLLM.buildEvidenceBlocks(result) : []);
    const orderedPanels = canonicalFigurePanelOrder(viewPanels, storedEvidenceLayout);
    const hasStoredEvidenceGroups = storedEvidenceLayout.some(item =>
        item?.kind === 'evidence' && item?.sourceType !== 'bridge' &&
        Array.isArray(item?.panelIds) && item.panelIds.length > 0
    );
    const evidenceLayout = typeof SciLLM.buildFigureEvidenceDisplayLayout === 'function'
        ? SciLLM.buildFigureEvidenceDisplayLayout(storedEvidenceLayout, orderedPanels)
        : storedEvidenceLayout;
    const evidenceBlocks = evidenceLayout.filter(item => item?.kind === 'evidence');
    const blockIndexes = new Map(evidenceBlocks.map((block, index) => [block.id, index]));
    const blockByPanel = new Map();
    evidenceBlocks.forEach(block => {
        (Array.isArray(block?.panelIds) ? block.panelIds : []).forEach(panelId => {
            const normalized = String(panelId || '').trim().toUpperCase();
            if (normalized && !blockByPanel.has(normalized)) blockByPanel.set(normalized, block);
        });
    });
    const transitionsIntoBlock = new Map();
    evidenceLayout.forEach(item => {
        if (item?.kind === 'transition' && item?.fromBlockId) {
            const targetBlockId = String(item.toBlockId || '');
            if (targetBlockId) {
                const incoming = transitionsIntoBlock.get(targetBlockId) || [];
                incoming.push(item);
                transitionsIntoBlock.set(targetBlockId, incoming);
            }
        }
    });
    const panelCountByBlock = new Map();
    orderedPanels.forEach(panel => {
        const block = blockByPanel.get(String(panel?.panelId || '').trim().toUpperCase());
        if (block) {
            panelCountByBlock.set(block.id, (panelCountByBlock.get(block.id) || 0) + 1);
        }
    });
    const renderedBlockIds = new Set();
    const panelHostByBlock = new Map();
    const evidenceGroupIndexes = new Map();
    const paperQuestion = figureKeyboardNumber(figure) === 1
        ? resolveFigureEvidencePaperQuestion({
            draft: currentWorkspaceSnapshot?.figures?.draft ||
                currentWorkspaceSnapshot?.figureWorkspaceDraft,
            noteState: literatureNoteDocumentState,
            noteTemplates: literatureNoteTemplates(),
            crossFigureLogic: currentWorkspaceSnapshot?.figures?.crossFigureLogic?.result
        })
        : null;
    const ensureEvidenceBlockRendered = block => {
        if (!block?.id) return null;
        if (renderedBlockIds.has(block.id)) return panelHostByBlock.get(block.id) || null;
        renderedBlockIds.add(block.id);
        const blockIndex = blockIndexes.get(block.id) || 0;
        const blockDetails = createFigureEvidenceBlockDetails(
            figure.figureId, block, blockIndex, {
                previousBlock: evidenceBlocks[blockIndex - 1] || null,
                incomingTransitions: transitionsIntoBlock.get(block.id) || [],
                panelCount: panelCountByBlock.get(block.id) || 0,
                paperQuestion: blockIndex === 0 ? paperQuestion : null
            }
        );
        parent.appendChild(blockDetails);
        const panelHost = blockDetails.querySelector('[data-evidence-panels-body="true"]');
        panelHostByBlock.set(block.id, panelHost || null);
        return panelHost || null;
    };
    evidenceBlocks.forEach(block => ensureEvidenceBlockRendered(block));
    let orphanPanelHost = null;
    const ensureOrphanPanelHost = () => {
        if (!hasStoredEvidenceGroups) return parent;
        if (orphanPanelHost) return orphanPanelHost;
        const section = createWorkspaceElement('section', 'workspace-evidence-orphans');
        section.appendChild(createWorkspaceElement(
            'h5', 'workspace-evidence-orphans-title', '待确认分组'
        ));
        orphanPanelHost = createWorkspaceElement('div', 'workspace-evidence-orphan-panels');
        section.appendChild(orphanPanelHost);
        parent.appendChild(section);
        return orphanPanelHost;
    };
    orderedPanels.forEach(viewPanel => {
        const panelId = viewPanel.panelId;
        const panel = resultPanels.find(item =>
            String(item?.panel || '').toUpperCase() === panelId) ||
            figure?.panelAnalyses?.[panelId] || { panel: panelId };
        const analyzed = Boolean(panel?.purpose || panel?.directObservation || panel?.contribution);
        const loading = figure?.panelAnalysisLoading?.[panelId] === true;
        const evidenceBlock = blockByPanel.get(String(panelId || '').trim().toUpperCase());
        const evidenceGroup = evidenceBlock ? {
            key: evidenceBlock.id,
            label: String(
                evidenceBlock.groupGoal || evidenceBlock.groupConclusion ||
                evidenceBlock.established || '证据单元'
            )
        } : (!hasStoredEvidenceGroups && analyzed
            ? figurePanelEvidenceGroup(result, panel, panelId) : null);
        if (evidenceGroup && !evidenceGroupIndexes.has(evidenceGroup.key)) {
            evidenceGroupIndexes.set(evidenceGroup.key, evidenceGroupIndexes.size + 1);
        }
        const panelHost = evidenceBlock
            ? ensureEvidenceBlockRendered(evidenceBlock)
            : ensureOrphanPanelHost();
        const panelDetails = createWorkspaceElement('details', 'workspace-figure-panel-card');
        panelDetails.classList.toggle('is-llm-pending', loading);
        const panelKey = panelWorkspaceKey(figure.figureId, panelId);
        panelDetails.id = viewPanel.panelAnchorId;
        panelDetails.dataset.figureId = figure.figureId;
        panelDetails.dataset.panelId = panelId;
        if (evidenceGroup) {
            panelDetails.dataset.evidenceGroup = String(
                ((evidenceGroupIndexes.get(evidenceGroup.key) - 1) % 6) + 1
            );
            panelDetails.dataset.evidenceBlockId = String(evidenceBlock?.id || evidenceGroup.key);
        }
        panelDetails.open = figurePanelExpansionState.get(panelKey) === true;
        panelDetails.addEventListener('toggle', () => {
            figurePanelExpansionState.set(panelKey, panelDetails.open);
            const editing = figureWorkspaceInlineEditController.getState().active?.descriptor;
            if (!panelDetails.open && editing?.figureId === figure.figureId &&
                editing?.panelId === panelId) {
                void figureWorkspaceInlineEditController.flush('collapse');
            }
        });
        panelDetails.appendChild(appendFigurePanelSummary(
            createWorkspaceElement('summary'),
            viewPanel,
            {
                displayId: formatFigurePanelHeader(panel, viewPanel.displayId),
                analyzed,
                evidenceGroupIndex: evidenceGroup
                    ? ((evidenceGroupIndexes.get(evidenceGroup.key) - 1) % 6) + 1
                    : 0,
                evidenceGroupLabel: evidenceGroup?.label || ''
            }
        ));
        const actions = createWorkspaceElement('div', 'workspace-panel-actions');
        const analyze = createWorkspaceElement(
            'button', 'btn btn-figure workspace-panel-analyze',
            loading ? '正在解读此 Panel…' : (analyzed ? '重新解读此 Panel' : '解读此 Panel')
        );
        analyze.type = 'button';
        analyze.disabled = loading;
        analyze.classList.toggle('is-llm-pending', loading);
        analyze.title = hasUsableLlm()
            ? '解读此 Panel'
            : llmUnavailableMessage('Panel 解读');
        analyze.addEventListener('click', () => {
            figureExpansionState.set(figure.figureId, true);
            figurePanelExpansionState.set(panelKey, true);
            void runSingleFigurePanelAnalysis(figure.figureId, panelId);
        });
        const ask = createWorkspaceElement(
            'button', 'btn btn-secondary workspace-panel-ask', '提问此 Panel'
        );
        ask.type = 'button';
        ask.disabled = false;
        ask.title = hasUsableLlm()
            ? '围绕此 Panel 继续追问'
            : llmUnavailableMessage('Panel 追问');
        actions.append(analyze, ask);
        panelDetails.appendChild(actions);
        appendFigureWorkspaceViewPanelFields(panelDetails, viewPanel);
        if (analyzed) {
            [
                ['方法来源', panel.methodSource],
                ['观察来源', panel.observationSource]
            ].forEach(([label, value]) => appendFigureWorkspaceField(panelDetails, label, value));
            appendFigureWorkspaceField(
                panelDetails,
                '本次解读依据',
                formatFigurePanelInputBasis(panel.inputBasis)
            );
        } else {
            panelDetails.appendChild(createWorkspaceElement(
                'p', 'workspace-figure-caption',
                '目录识别不消耗 Token。点击“解读此 Panel”后才会调用所配置的 Figure 模型。'
            ));
        }
        const error = figure?.panelAnalysisErrors?.[panelId];
        if (error) panelDetails.appendChild(createWorkspaceElement(
            'p', 'workspace-figure-error', error
        ));
        const followup = createPanelFollowupControl(figure, panel, viewPanel.displayId);
        const followupDraft = getPanelFollowupDraft(figure.figureId, panelId);
        const followupToggle = followup.querySelector('.workspace-panel-followup-toggle');
        const followupChooser = followup.querySelector('.workspace-panel-followup-chooser');
        if (followupToggle) followupToggle.hidden = true;
        if (followupChooser) followupChooser.hidden = false;
        followup.hidden = followupDraft.open !== true;
        ask.textContent = followup.hidden ? '提问此 Panel' : '收起提问';
        ask.addEventListener('click', () => {
            followup.hidden = !followup.hidden;
            followupDraft.open = !followup.hidden;
            ask.textContent = followup.hidden ? '提问此 Panel' : '收起提问';
            if (!followup.hidden) {
                panelDetails.open = true;
                figurePanelExpansionState.set(panelKey, true);
                followup.querySelector('textarea')?.focus();
            }
        });
        panelDetails.appendChild(followup);
        const note = viewPanel?.fields?.find(field => field.key === 'note');
        if (note) appendFigureWorkspaceViewField(panelDetails, note, {
            figureId: viewPanel.figureId,
            panelId: viewPanel.panelId
        });
        (panelHost || parent).appendChild(panelDetails);
    });
}

function createCollapsibleFigureResultSection(figureId, sectionId, title, count = 0) {
    const stateKey = `${figureId}::section::${sectionId}`;
    const details = createWorkspaceElement('details', 'workspace-figure-result-section');
    details.dataset.figureSection = sectionId;
    details.open = figureSectionExpansionState.get(stateKey) === true;
    details.addEventListener('toggle', () => {
        figureSectionExpansionState.set(stateKey, details.open);
    });
    const label = count > 0 ? `${title} · ${count}` : title;
    details.appendChild(createWorkspaceElement(
        'summary', 'workspace-figure-result-summary', label
    ));
    return details;
}

function renderCrossFigureLogicSnapshot(container, crossFigureLogic) {
    if (!crossFigureLogic) return;
    const logic = crossFigureLogic.result;
    if (!logic && !crossFigureLogic.loading && !crossFigureLogic.error) return;
    const details = createWorkspaceElement('details', 'workspace-cross-figure-card');
    details.classList.toggle('is-llm-pending', crossFigureLogic.loading === true);
    // Completed integrated analyses start as an overview. Users expand only
    // the Figure whose evidence chain they want to inspect.
    details.open = crossFigureLogic.loading === true;
    details.appendChild(createWorkspaceElement(
        'summary', 'workspace-cross-figure-summary',
        crossFigureLogic.loading
            ? '正在梳理主图之间的多米诺逻辑…'
            : '主图多米诺总链（跨图梳理）'
    ));
    if (crossFigureLogic.loading) {
        details.appendChild(createWorkspaceElement(
            'p', 'workspace-cross-figure-subtitle',
            '正在把每张主图的已建立证据、下一步必要性与补图支撑串成全文论证链。'
        ));
    }
    if (crossFigureLogic.error) {
        details.appendChild(createWorkspaceElement(
            'p', 'workspace-figure-error',
            `跨图总链生成失败：${crossFigureLogic.error}`
        ));
    }
    if (logic) {
        details.appendChild(createWorkspaceElement(
            'p', 'workspace-cross-figure-subtitle', logic.overallThesis
        ));
        const analyzedCount = Array.isArray(logic.analyzedMainFigureIds)
            ? logic.analyzedMainFigureIds.length : 0;
        const mainCount = Array.isArray(logic.mainFigureIds) ? logic.mainFigureIds.length : 0;
        details.appendChild(createWorkspaceElement(
            'p', 'workspace-figure-coverage',
            `主图证据输入：${analyzedCount}/${mainCount} 张已有逐图解读；其余按图注谨慎串联。`
        ));
        const dominoChain = Array.isArray(logic.dominoChain) ? logic.dominoChain : [];
        const linkByFigure = new Map(dominoChain.map(link => [
            String(link?.fromFigureId || ''), link
        ]));
        const supportByMainFigure = new Map();
        (Array.isArray(logic.supplementalSupport) ? logic.supplementalSupport : [])
            .forEach(item => {
                const mainFigureId = String(
                    item?.supportsFigureId || item?.mainFigureId || item?.targetFigureId || ''
                );
                if (!mainFigureId) return;
                const items = supportByMainFigure.get(mainFigureId) || [];
                items.push(item);
                supportByMainFigure.set(mainFigureId, items);
            });
        const splitPoints = value => String(value || '').normalize('NFKC')
            .split(/(?:\n+|(?<=[。！？；.!?;])\s*)/)
            .map(item => item.replace(/^[\s•·\-–—]+/, '').trim())
            .filter(Boolean).slice(0, 8);
        (Array.isArray(logic.nodes) ? logic.nodes : []).forEach((node, index) => {
            const block = createWorkspaceElement('details', 'workspace-cross-figure-node');
            block.open = false;
            const summary = createWorkspaceElement('summary', 'workspace-cross-figure-node-summary');
            const jump = createWorkspaceElement(
                'button', '', `${index + 1}. ${node.figureLabel || node.figureId}`
            );
            jump.type = 'button';
            jump.addEventListener('click', () => void focusWorkspaceSource({
                kind: 'figure', figureId: node.figureId
            }));
            const overview = createWorkspaceElement(
                'span', 'workspace-cross-figure-node-overview', node.established || '待补充本图结论'
            );
            summary.append(jump, overview);
            block.appendChild(summary);
            const body = createWorkspaceElement('div', 'workspace-cross-figure-node-body');
            appendFigureWorkspaceField(
                body, '本图任务', CROSS_FIGURE_ROLE_LABELS[node.role] || node.role
            );
            appendFigureWorkspaceField(body, '本图确立', node.established);
            appendFigureWorkspaceField(
                body, '证据等级',
                CROSS_FIGURE_EVIDENCE_LABELS[node.evidenceLevel] || node.evidenceLevel
            );
            const link = linkByFigure.get(String(node.figureId || '')) || {};
            const nextQuestion = link.transition || node.transition;
            if (nextQuestion) {
                const handoff = createWorkspaceElement(
                    'section', 'workspace-cross-figure-handoff'
                );
                appendFigureWorkspaceField(handoff, '下一图要解决的问题', nextQuestion);
                appendFigureWorkspaceField(handoff, '当前证据边界', link.evidenceBoundary);
                body.appendChild(handoff);
            }
            const support = supportByMainFigure.get(String(node.figureId || '')) || [];
            if (support.length) {
                const supplementWrap = createWorkspaceElement(
                    'section', 'workspace-cross-figure-supplements'
                );
                supplementWrap.appendChild(createWorkspaceElement(
                    'h4', 'workspace-figure-section-title', '紧跟本图的补充证据'
                ));
                support.forEach(item => {
                    const supplement = createWorkspaceElement(
                        'article', 'workspace-cross-figure-support'
                    );
                    const supplementJump = createWorkspaceElement(
                        'button', '', item.figureLabel || item.figureId || '补充材料'
                    );
                    supplementJump.type = 'button';
                    supplementJump.addEventListener('click', () => void focusWorkspaceSource({
                        kind: 'figure', figureId: item.figureId
                    }));
                    supplement.appendChild(supplementJump);
                    const points = [
                        ...splitPoints(item.contribution),
                        ...splitPoints(item.established),
                        ...splitPoints(item.limitation).map(text => `边界：${text}`)
                    ].filter((text, pointIndex, all) => all.indexOf(text) === pointIndex);
                    if (points.length) {
                        const list = document.createElement('ul');
                        points.forEach(text => list.appendChild(
                            createWorkspaceElement('li', '', text)
                        ));
                        supplement.appendChild(list);
                    }
                    supplementWrap.appendChild(supplement);
                });
                body.appendChild(supplementWrap);
            }
            block.appendChild(body);
            details.appendChild(block);
        });
        appendFigureWorkspaceField(details, '全链边界', logic.claimBoundary);
        if (Array.isArray(logic.missingFigureIds) && logic.missingFigureIds.length) {
            details.appendChild(createWorkspaceElement(
                'p', 'workspace-figure-coverage is-incomplete',
                `待补主图节点：${logic.missingFigureIds.join('、')}`
            ));
        }
    }
    container.appendChild(details);
}

function getFigureProgressEntries(status) {
    if (Array.isArray(status?.figureProgress)) return status.figureProgress;
    if (status?.figureProgressById && typeof status.figureProgressById === 'object') {
        return Object.values(status.figureProgressById);
    }
    return [];
}

function summarizeFigureButtonProgress(status = {}) {
    const entriesByFigure = new Map();
    getFigureProgressEntries(status).forEach((progress, index) => {
        const key = String(progress?.figureId || `figure-${index}`);
        entriesByFigure.set(key, progress || {});
    });
    const entries = [...entriesByFigure.values()];
    const completedFromEntries = entries.filter(progress =>
        progress.completed === true && progress.failed !== true).length;
    const completedFigures = Math.max(
        0,
        Number(status.completedFigures) || 0,
        completedFromEntries,
        ...entries.map(progress => Number(progress.completedFigures) || 0)
    );
    const totalFigures = Math.max(
        0,
        Number(status.totalFigures) || 0,
        ...entries.map(progress => Number(progress.totalFigures) || 0)
    );
    let savedPanels = 0;
    let validatedPanels = 0;
    let identifiablePanels = 0;
    entries.forEach(progress => {
        const saved = Math.max(0, Number(progress.savedPanelCount) || 0);
        const validated = Math.max(0, Number(progress.validatedPanelCount) || 0);
        const unresolved = normalizeFigureRecoveryPanelLabels(progress.unresolvedPanels).length;
        savedPanels += saved;
        validatedPanels += validated;
        identifiablePanels += Math.max(0, saved - Math.min(saved, unresolved));
    });
    return {
        completedFigures: Math.min(totalFigures || completedFigures, completedFigures),
        totalFigures,
        savedPanels,
        validatedPanels,
        identifiablePanels
    };
}

function figureButtonProgressLabel(status = {}) {
    const summary = summarizeFigureButtonProgress(status);
    const parts = [];
    if (summary.totalFigures) {
        parts.push(`${summary.completedFigures}/${summary.totalFigures} 图完成`);
    }
    if (summary.savedPanels || summary.validatedPanels) {
        parts.push(`已存 ${summary.savedPanels} Panel`);
        parts.push(`可识别 ${summary.identifiablePanels}`);
        if (summary.validatedPanels > summary.savedPanels) {
            parts.push(`已校验 ${summary.validatedPanels}`);
        }
    }
    return parts.join(' · ');
}

function singleFigureButtonProgressLabel(progress = {}) {
    const saved = Math.max(0, Number(progress.savedPanelCount) || 0);
    const validated = Math.max(0, Number(progress.validatedPanelCount) || 0);
    const expected = Math.max(
        0,
        Number(progress.expectedPanelCount) ||
        (Array.isArray(progress.expectedPanels) ? progress.expectedPanels.length : 0)
    );
    const unresolved = normalizeFigureRecoveryPanelLabels(progress.unresolvedPanels).length;
    const identifiable = Math.max(0, saved - Math.min(saved, unresolved));
    if (!saved && !validated) return '解图中…';
    return `已存 ${saved}${expected ? `/${expected}` : ''} · 可识别 ${identifiable}` +
        (validated > saved ? ` · 已校验 ${validated}` : '');
}

function hasRunningFigureProgress(status = figureAnalysisState) {
    const phase = String(status?.phase || '').toLowerCase();
    if (status?.running === false ||
        ['idle', 'completed', 'partial', 'failed', 'cancelled'].includes(phase)) {
        return false;
    }
    return status?.running === true || getFigureProgressEntries(status)
        .some(progress => progress?.running === true);
}

function resumeFigureProgressFromWorkspaceSnapshot(snapshot, {
    announce = false,
    tabId = activePanelTabContext.tabId
} = {}) {
    const status = snapshot?.figures?.status;
    if (!status || typeof status !== 'object') return null;
    const applied = applyFigureAnalysisProgress(status, announce);
    if (hasRunningFigureProgress(status) && tabId) {
        startFigureProgressPolling(tabId);
    }
    return applied;
}

function normalizeFigureRecoveryPanelLabels(value) {
    return [...new Set((Array.isArray(value) ? value : [])
        .map(item => String(item || '').normalize('NFKC').trim().toUpperCase())
        .filter(item => item.length <= 8 && /^[A-Z0-9][A-Z0-9.+-]*$/.test(item)))]
        .slice(0, 30);
}

function figureRecoveryInputModeBadge(inputMode, translate = t) {
    const key = {
        caption_context: '图注/正文回退',
        figure_image: '整张 Figure 图片',
        panel_crop: 'Panel 裁切图'
    }[String(inputMode || '')] || '';
    return key ? translate(key) : '';
}

function figureRecoveryRetryLabels(figure, result, progress) {
    progress ||= {};
    const incomplete = new Set([
        ...normalizeFigureRecoveryPanelLabels(progress.missingPanels),
        ...normalizeFigureRecoveryPanelLabels(progress.unresolvedPanels),
        ...normalizeFigureRecoveryPanelLabels(result?.panelCoverage?.missingPanels),
        ...normalizeFigureRecoveryPanelLabels(result?.panelCoverage?.unresolvedPanels),
        ...normalizeFigureRecoveryPanelLabels(result?.unresolvedPanels),
        ...normalizeFigureRecoveryPanelLabels(
            (Array.isArray(result?.panels) ? result.panels : [])
                .filter(panel => panel?.status === 'not_identifiable')
                .map(panel => panel.panel)
        )
    ]);
    return normalizeFigureRecoveryPanelLabels(figure?.panelHints)
        .filter(panel => incomplete.has(panel));
}

function figureRecoveryPhaseText(phase, translate = t) {
    const key = {
        figure_panel_recovery_started: '正在仅请求缺失 Panel',
        figure_panel_recovery_checkpoint_pending: '已校验的 Panel 正在等待保存',
        figure_panel_recovery_checkpoint: '已保存有效 Panel，准备补齐缺失 Panel',
        figure_panel_recovery_batch_pending: '缺失 Panel 批次已校验，正在保存',
        figure_panel_recovery_batch_complete: '缺失 Panel 批次已保存',
        figure_panel_recovery_complete: '缺失 Panel 恢复完成',
        figure_panel_batch_pending: '当前 Panel 分批已校验，正在保存',
        figure_panel_batch_complete: '当前 Panel 分批已保存，继续下一批'
    }[String(phase || '')] || '';
    return key ? translate(key) : '';
}

function figureRecoveryRetryPresentation(figure, result, progress, translate = t) {
    const labels = figureRecoveryRetryLabels(figure, result, progress);
    const pendingDeep = figure?.activeDepth === 'deep' && Boolean(figure?.pendingDeep) &&
        !figure?.deep;
    if (!labels.length) {
        return { labels, enabled: false, label: '', ariaLabel: '', explanation: '' };
    }
    if (pendingDeep) {
        const label = translate('重新运行深度解读以补齐缺失 Panel');
        const explanation = translate('深度解读的缺失 Panel 需要重新运行深度解读');
        return {
            labels,
            enabled: true,
            action: 'deep_rerun',
            label,
            ariaLabel: `${label} ${labels.join('、')}`,
            explanation
        };
    }
    const label = `${translate('重试缺失 Panel')}：${labels.join('、')}`;
    return {
        labels,
        enabled: true,
        action: 'missing_panels',
        label,
        ariaLabel: `${translate('重试缺失 Panel')} ${labels.join('、')}`,
        explanation: ''
    };
}

function runKeyedFigureRecoveryAction(key, task, onLock, onUnlock) {
    const normalizedKey = String(key || '').slice(0, 240);
    if (!normalizedKey || typeof task !== 'function') return Promise.resolve(null);
    const lockCallback = typeof onLock === 'function' ? onLock : () => {};
    const unlockCallback = typeof onUnlock === 'function' ? onUnlock : () => {};
    const existing = figureRecoveryInFlightActions.get(normalizedKey);
    if (existing) return existing;
    lockCallback();
    const promise = Promise.resolve().then(task).finally(() => {
        if (figureRecoveryInFlightActions.get(normalizedKey) === promise) {
            figureRecoveryInFlightActions.delete(normalizedKey);
            unlockCallback();
        }
    });
    figureRecoveryInFlightActions.set(normalizedKey, promise);
    return promise;
}

function createFigureRecoveryOperationId(action, figureId) {
    let nonce = '';
    try {
        nonce = globalThis.crypto?.randomUUID?.().replace(/[^a-z0-9]/giu, '') || '';
    } catch (_) {}
    if (!nonce) {
        nonce = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}`;
    }
    const safeAction = String(action || 'retry').replace(/[^a-z0-9_-]/giu, '').slice(0, 16);
    const safeFigure = String(figureId || 'figure').replace(/[^a-z0-9_.-]/giu, '').slice(0, 24);
    return `figure-recovery:${safeAction}:${safeFigure}:${nonce}`.slice(0, 96);
}

function formatFigureElapsed(progress = {}, now = Date.now(), translate = t) {
    const snapshotElapsed = Number(progress.elapsedSeconds);
    const started = Number(progress.startedAt) || 0;
    const elapsedSeconds = Number.isFinite(snapshotElapsed) && snapshotElapsed >= 0
        ? Math.floor(snapshotElapsed)
        : (!started || now < started ? 0 : Math.floor((now - started) / 1000));
    if (!started && !Number.isFinite(snapshotElapsed)) return '';
    if (elapsedSeconds < 60) {
        return `${translate('已用时')} ${elapsedSeconds} ${translate('秒')}`;
    }
    return `${translate('已用时')} ${Math.floor(elapsedSeconds / 60)} ${translate('分')} ` +
        `${elapsedSeconds % 60} ${translate('秒')}`;
}

function formatFigureProgress(progress = {}, now = Date.now()) {
    const phase = String(progress.phase || 'preparing');
    const expectedPanels = Array.isArray(progress.expectedPanels) ? progress.expectedPanels : [];
    const expectedPanelCount = Math.max(0, Number(progress.expectedPanelCount) || expectedPanels.length);
    const recognizedPanelCount = Number.isFinite(Number(progress.recognizedPanelCount))
        ? Math.max(0, Number(progress.recognizedPanelCount)) : null;
    const batchRecognizedPanelCount = Number.isFinite(Number(progress.batchRecognizedPanelCount))
        ? Math.max(0, Number(progress.batchRecognizedPanelCount)) : null;
    const unexpectedPanels = Array.isArray(progress.unexpectedPanels)
        ? progress.unexpectedPanels.map(String).slice(0, 30) : [];
    const cancelledPhaseText = phase === 'cancelled'
        ? t('本批 Figure 解读已取消') : '';
    const recoveryPhaseText = figureRecoveryPhaseText(phase);
    const phaseText = cancelledPhaseText || recoveryPhaseText || t({
        queued: '等待前面的 Figure 完成',
        paused: '已暂停，当前请求结束后不再发送新请求',
        preparing: '正在准备图片与正文上下文',
        caption_text_only: '仅使用图注与正文证据',
        figure_requesting: '正在发送 Figure 请求',
        figure_inventory: '正在读取原图中的 Panel 标签',
        figure_inventory_ready: 'Panel 目录已核对，正在开始解读',
        figure_model_processing: '模型正在处理这张 Figure',
        figure_response_received: '已收到模型响应，正在检查返回内容',
        figure_validating: '正在校验返回结构',
        figure_assembling: '正在整理 Figure 解读',
        figure_synthesizing: 'Panel 已提取，正在综合整图证据链',
        figure_synthesis_complete: '整图证据链综合完成',
        figure_schema_retry: '返回结构不完整，正在自动修正',
        figure_panel_planning: '正在规划 Panel 证据输入',
        figure_panel_schema_retry: 'Panel 返回结构不完整，正在自动修正',
        figure_panel_transient_retry: 'Panel 请求暂时失败，正在等待自动重试',
        figure_panel_token_retry: '正在调整 Panel 输出令牌上限',
        figure_panel_output_retry: '正在增加 Panel 输出令牌上限',
        figure_panel_retry: '正在降低 Panel 输入容量',
        figure_panel_complete: 'Panel 解读已完成',
        figure_compact_fallback: '整图返回不稳定，已切换为 Panel 提取后再综合',
        provider_telemetry: '模型已返回，正在读取用量与完成状态',
        figure: '✓',
        failed: 'Figure 解读失败',
        figure_fallback: '视觉输入被拒绝，正在改用图注与正文',
        figure_retry: '请求暂时失败，正在等待自动重试',
        token_limit_retry: '正在调整输出令牌上限后重试',
        output_token_retry: '正在增加输出令牌后重试',
        output_compact_retry: '输出过长，正改用紧凑 JSON 重试'
    }[phase] || '正在处理 Figure');
    const details = [];
    const totalFigures = Math.max(0, Number(progress.totalFigures) || 0);
    if (totalFigures) {
        details.push(`${t('批次进度')}：${Math.min(totalFigures,
            Math.max(0, Number(progress.completedFigures) || 0))}/${totalFigures} ${t('张')}`);
    }
    if (expectedPanelCount) {
        details.push(`${t('预期 Panel')}：${expectedPanels.length
            ? expectedPanels.join('、') : `${expectedPanelCount} ${t('个')}`}`);
    } else {
        details.push(t('图注中未识别到可核验的 Panel 标签'));
    }
    const totalPanelBatches = Math.max(0, Number(progress.totalPanelBatches) || 0);
    if (totalPanelBatches) {
        details.push(`${t('Panel 分批')}：${Math.min(totalPanelBatches,
            Math.max(0, Number(progress.completedPanelBatches) || 0))}/${totalPanelBatches}`);
    }
    if (recognizedPanelCount !== null) {
        details.push(`${t('已识别')} ${recognizedPanelCount} ${t('个 Panel')}`);
    }
    if (batchRecognizedPanelCount !== null) {
        details.push(`${t('本批有效 Panel')}：${batchRecognizedPanelCount}`);
    }
    const missingPanels = normalizeFigureRecoveryPanelLabels(progress.missingPanels);
    if (missingPanels.length) details.push(`${t('待补 Panel')}：${missingPanels.join('、')}`);
    const unresolvedPanels = normalizeFigureRecoveryPanelLabels(progress.unresolvedPanels);
    if (unresolvedPanels.length) {
        details.push(`${t('尚不可识别 Panel')}：${unresolvedPanels.join('、')}`);
    }
    const savedPanelCount = Math.max(0, Number(progress.savedPanelCount) || 0);
    const validatedPanelCount = Math.max(0, Number(progress.validatedPanelCount) || 0);
    if (progress.checkpointStatus === 'pending_save' && validatedPanelCount) {
        details.push(`${t('已校验')} ${validatedPanelCount} ${t('个 Panel')}；${t('等待保存')}`);
    } else if (savedPanelCount || validatedPanelCount) {
        details.push(`${t('已保存')} ${savedPanelCount} ${t('个 Panel')}；` +
            `${t('已校验')} ${validatedPanelCount} ${t('个 Panel')}`);
    }
    const inputModeBadge = figureRecoveryInputModeBadge(progress.inputMode);
    if (inputModeBadge) details.push(`${t('输入依据')}：${inputModeBadge}`);
    const ignoredUnexpectedPanelCount = Math.max(
        0, Number(progress.ignoredUnexpectedPanelCount) || unexpectedPanels.length
    );
    if (ignoredUnexpectedPanelCount) {
        const labels = unexpectedPanels.length ? `（${unexpectedPanels.join('、')}）` : '';
        details.push(`${t('已忽略模型重复返回的')} ${ignoredUnexpectedPanelCount} ` +
            `${t('个批次外 Panel')}${labels}`);
    }
    if (progress.capabilityMode === 'caption_text_only' || phase === 'caption_text_only') {
        details.push(t('当前有效模型不接收图片；本次仅发送图注与正文证据'));
    }
    if (progress.visionFallback || phase === 'figure_fallback') {
        details.push(t('视觉请求未被接受，已回退到图注与正文证据'));
    }
    if (phase === 'figure_retry') {
        const seconds = Math.max(1, Math.ceil((Number(progress.waitMs) || 0) / 1000));
        details.push(`${seconds} ${t('秒后自动重试')}${progress.attempt
            ? ` (${t('第')} ${progress.attempt} ${t('次')})` : ''}`);
    }
    const route = progress.route && typeof progress.route === 'object' ? progress.route : {};
    const effectiveProfileName = String(route.effectiveProfileName || route.name || '').trim();
    const routeModel = String(route.model || progress.model || '').trim();
    const capabilityMode = String(route.capabilityMode || progress.capabilityMode || '').trim();
    const fallbackReason = String(route.fallbackReason || '').trim();
    if (effectiveProfileName || routeModel || capabilityMode) {
        const target = [effectiveProfileName || progress.providerId || 'provider', routeModel]
            .filter(Boolean).join(' / ');
        details.push(`${t('有效路由')}：${target}${capabilityMode
            ? `; ${t('能力')}：${capabilityMode}` : ''}`);
    }
    if (fallbackReason) {
        details.push(`${t('路由回退')}：${fallbackReason}`);
    }
    const elapsed = formatFigureElapsed(progress, now, t);
    const elapsedDetailIndex = elapsed ? details.length : -1;
    if (elapsed) details.push(elapsed);
    return { phaseText, details, elapsedDetailIndex };
}

function figureSummaryPresentation(result, _figure, view = null) {
    const text = value => typeof value === 'string'
        ? value.normalize('NFKC').replace(/\s+/gu, ' ').trim() : '';
    const fields = Array.isArray(view?.overview) ? view.overview : [];
    const field = key => view
        ? fields.find(item => item?.key === key) || { value: '' }
        : { value: result?.[key] };
    const conclusion = field('coreConclusion');
    const render = (value, source) => ({ text: value,
        fullText: value, source, state: 'available' });
    // A reviewed blank is an intentional title choice, not missing model content.
    if (conclusion.humanReviewed === true) {
        const value = text(conclusion.value);
        return value ? render(value, 'coreConclusion')
            : { text: '简要已清空', fullText: '', source: 'coreConclusion', state: 'cleared' };
    }
    for (const key of ['coreConclusion', 'authorAssembly', 'figureQuestion']) {
        const value = text(field(key).value);
        if (/[\u3400-\u9fff]/u.test(value)) return render(value, key);
    }
    // A translated source title is not a synthesized scientific conclusion.
    return { text: '中文简要待补', fullText: '', source: '', state: 'missing' };
}

function compactFigureResultConclusion(result, figure, view = null) {
    return figureSummaryPresentation(result, figure, view).text;
}

function figureSourceCaption(figure) {
    return String(figure?.caption || '')
        .replace(/(?:show|hide)\s+full\s+caption|figure\s+viewer|figure360|(?:显示|隐藏)完整图注/giu, ' ')
        .replace(/\s+/gu, ' ').trim();
}

function completedStandaloneFigurePanelIds(figure) {
    const analyses = figure?.panelAnalyses;
    if (!analyses || typeof analyses !== 'object' || Array.isArray(analyses)) return [];
    const hasText = value => {
        const raw = value && typeof value === 'object' && !Array.isArray(value)
            ? value.value : value;
        if (Array.isArray(raw)) return raw.some(item => String(item || '').trim());
        return String(raw || '').trim().length > 0;
    };
    return Object.keys(analyses).map(value => String(value || '').trim().toUpperCase())
        .filter(panelId => {
            if (!/^[A-Z0-9][A-Z0-9.+-]{0,7}$/.test(panelId)) return false;
            const panel = analyses[panelId];
            return panel && typeof panel === 'object' && !Array.isArray(panel) &&
                [panel.purpose, panel.directObservation, panel.contribution].some(hasText);
        });
}

function completedStandaloneFigureFollowupPanelIds(figure) {
    const followups = figure?.panelFollowups;
    if (!followups || typeof followups !== 'object' || Array.isArray(followups)) return [];
    return Object.keys(followups).map(value => String(value || '').trim().toUpperCase())
        .filter(panelId => {
            if (!/^[A-Z0-9][A-Z0-9.+-]{0,7}$/.test(panelId)) return false;
            const followup = followups[panelId];
            return followup && typeof followup === 'object' && !Array.isArray(followup) &&
                String(followup.answer || '').trim().length > 0;
        });
}

function figurePanelCompletionPresentation(figure, progress = null, result = null) {
    const panelIds = completedStandaloneFigurePanelIds(figure);
    const followupPanelIds = completedStandaloneFigureFollowupPanelIds(figure);
    const phase = String(progress?.phase || '').toLowerCase();
    const terminal = progress?.failed === true || ['failed', 'cancelled'].includes(phase);
    const completed = !terminal && (progress?.completed === true || phase === 'figure');
    const checkpointPending = String(progress?.checkpointStatus || '').toLowerCase() ===
        'pending_save';
    const taskType = String(progress?.route?.taskType || progress?.taskType || '').trim();
    const expectedPanels = normalizeFigureRecoveryPanelLabels(progress?.expectedPanels);
    const expectedLanded = landedPanels => !expectedPanels.length ||
        expectedPanels.every(panelId => landedPanels.includes(panelId));
    const interpretationLanded = taskType === 'figure_panel_interpretation' &&
        panelIds.length > 0 && expectedLanded(panelIds);
    const followupLanded = taskType === 'figure_panel_followup' &&
        followupPanelIds.length > 0 && expectedLanded(followupPanelIds) &&
        followupPanelIds.some(panelId => panelIds.includes(panelId));
    const targetedPanelLanded = interpretationLanded || followupLanded;
    const awaitingPersistence = completed && !result && !terminal &&
        (checkpointPending || !targetedPanelLanded);
    const panelOnlyComplete = completed && !result && !terminal && targetedPanelLanded &&
        !checkpointPending;
    const restoredPanelOnly = !progress && !result && panelIds.length > 0;
    const label = panelIds.length ? `已解读 ${panelIds.length} 个 Panel` : '';
    return {
        completed,
        panelIds,
        panelOnlyComplete,
        restoredPanelOnly,
        awaitingPersistence,
        label
    };
}

function figureWorkspaceResultStatus({
    figure, progress = null, result = null, partialResult = false, progressDisplay = null,
    summaryPresentation = null
} = {}) {
    const completion = figurePanelCompletionPresentation(figure, progress, result);
    if (progress?.failed) return result ? '重试失败，原结果已保留' : '解读失败';
    if (progress?.running === true) return progressDisplay?.phaseText || '正在精读';
    if (completion.panelOnlyComplete || completion.restoredPanelOnly) return completion.label;
    if (completion.awaitingPersistence) return '正在校验与保存';
    if (partialResult) return '部分结果已保留';
    if (result && summaryPresentation?.state === 'missing') return '已解读 · 中文简要待补';
    if (result && summaryPresentation?.state === 'cleared') return '已解读 · 简要已清空';
    if (result) return '✓';
    return figure?.sourceExternal ? '补充证据待解读' : '待解读';
}

function renderFigureProgress(details, progress, result = null, figure = null, view = null) {
    if (!progress) return;
    const display = formatFigureProgress(progress);
    const completionState = figurePanelCompletionPresentation(figure, progress, result);
    const completed = completionState.completed;
    if (completed && result) return;
    const block = createWorkspaceElement(
        'section',
        `workspace-figure-progress${progress.failed ? ' is-error' : ''}` +
        `${progress.running ? ' is-running' : ''}${completed ? ' is-complete' : ''}`
    );
    block.dataset.figureId = String(progress.figureId || '');
    if (completed) {
        if (completionState.panelOnlyComplete) {
            const completion = createWorkspaceElement('div', 'workspace-figure-completion');
            const check = createWorkspaceElement('span', 'workspace-figure-completion-check', '✓');
            check.setAttribute('role', 'img');
            check.setAttribute('aria-label', 'Panel 解读已完成');
            completion.append(
                check,
                createWorkspaceElement(
                    'p', 'workspace-figure-progress-conclusion', completionState.label
                )
            );
            block.appendChild(completion);
            details.appendChild(block);
            return;
        }
        if (!result) {
            block.classList.remove('is-complete');
            block.classList.add('is-running');
            block.appendChild(createWorkspaceElement(
                'p', 'workspace-figure-progress-phase',
                '模型结果已返回，正在完成校验与保存…'
            ));
            details.appendChild(block);
            return;
        }
        const completion = createWorkspaceElement('div', 'workspace-figure-completion');
        const check = createWorkspaceElement('span', 'workspace-figure-completion-check', '✓');
        check.setAttribute('role', 'img');
        check.setAttribute('aria-label', 'Figure 解读已完成');
        completion.append(
            check,
            createWorkspaceElement(
                'p', 'workspace-figure-progress-conclusion',
                compactFigureResultConclusion(result, figure, view)
            )
        );
        block.appendChild(completion);
        details.appendChild(block);
        return;
    }
    block.appendChild(createWorkspaceElement(
        'p', 'workspace-figure-progress-phase', display.phaseText
    ));
    display.details.forEach((detail, index) => {
        const line = createWorkspaceElement('p', 'workspace-figure-progress-detail', detail);
        if (index === display.elapsedDetailIndex) line.dataset.figureElapsed = 'true';
        block.appendChild(line);
    });
    details.appendChild(block);
}

function figureProgressUiSignature(status = {}) {
    const progressEntries = getFigureProgressEntries(status).map(progress => {
        const route = progress?.route && typeof progress.route === 'object'
            ? progress.route : {};
        return {
            figureId: String(progress?.figureId || ''),
            figureLabel: String(progress?.figureLabel || ''),
            phase: String(progress?.phase || ''),
            running: progress?.running === true,
            failed: progress?.failed === true,
            completed: progress?.completed === true,
            cacheHit: progress?.cacheHit === true,
            checkpointStatus: String(progress?.checkpointStatus || ''),
            taskType: String(progress?.taskType || ''),
            expectedPanels: Array.isArray(progress?.expectedPanels)
                ? progress.expectedPanels.map(String) : [],
            expectedPanelCount: Number(progress?.expectedPanelCount) || 0,
            recognizedPanelCount: Number(progress?.recognizedPanelCount) || 0,
            batchRecognizedPanelCount: Number(progress?.batchRecognizedPanelCount) || 0,
            unexpectedPanels: Array.isArray(progress?.unexpectedPanels)
                ? progress.unexpectedPanels.map(String) : [],
            ignoredUnexpectedPanelCount:
                Number(progress?.ignoredUnexpectedPanelCount) || 0,
            missingPanels: normalizeFigureRecoveryPanelLabels(progress?.missingPanels),
            unresolvedPanels: normalizeFigureRecoveryPanelLabels(progress?.unresolvedPanels),
            inputMode: String(progress?.inputMode || ''),
            savedPanelCount: Number(progress?.savedPanelCount) || 0,
            validatedPanelCount: Number(progress?.validatedPanelCount) || 0,
            completedPanelBatches: Number(progress?.completedPanelBatches) || 0,
            totalPanelBatches: Number(progress?.totalPanelBatches) || 0,
            completedFigures: Number(progress?.completedFigures) || 0,
            totalFigures: Number(progress?.totalFigures) || 0,
            capabilityMode: String(progress?.capabilityMode || ''),
            visionFallback: progress?.visionFallback === true,
            waitMs: Number(progress?.waitMs) || 0,
            attempt: Number(progress?.attempt) || 0,
            providerId: String(progress?.providerId || ''),
            model: String(progress?.model || ''),
            route: {
                effectiveProfileName: String(route.effectiveProfileName || ''),
                name: String(route.name || ''),
                model: String(route.model || ''),
                capabilityMode: String(route.capabilityMode || ''),
                fallbackReason: String(route.fallbackReason || ''),
                taskType: String(route.taskType || '')
            }
        };
    }).sort((left, right) => left.figureId.localeCompare(right.figureId));
    return JSON.stringify(progressEntries);
}

function updateFigureElapsedLabels(status = {}) {
    const progressById = new Map(getFigureProgressEntries(status)
        .map(progress => [String(progress?.figureId || ''), progress])
        .filter(([figureId]) => Boolean(figureId)));
    document.querySelectorAll('.workspace-figure-progress[data-figure-id]').forEach(block => {
        const progress = progressById.get(block.dataset.figureId || '');
        if (!progress) return;
        const elapsed = formatFigureElapsed(progress);
        let line = block.querySelector('[data-figure-elapsed="true"]');
        if (!elapsed) {
            line?.remove();
            return;
        }
        if (!line) {
            line = createWorkspaceElement('p', 'workspace-figure-progress-detail');
            line.dataset.figureElapsed = 'true';
            block.appendChild(line);
        }
        if (line.textContent !== elapsed) line.textContent = elapsed;
    });
}

async function navigateFigureQuickAnchor(figureId, panelId = '', {
    collapsePanels = false
} = {}) {
    const figures = currentWorkspaceSnapshot?.figures?.figures || [];
    const figure = figures.find(item => String(item?.figureId || '') === String(figureId || ''));
    const normalizedPanelId = String(panelId || '').trim().toUpperCase();
    if (!figure || (normalizedPanelId && !figureCatalogPanelIds(
        figure,
        figure.activeDepth === 'standard' ? figure.standard : (figure.deep || figure.standard)
    ).includes(normalizedPanelId))) return false;
    panelId = normalizedPanelId;
    if (figureWorkspaceRenderCoordinator.getState().editing) return false;
    figureQuickNavActiveId = figureId;
    figures.forEach(figure => {
        figureExpansionState.set(figure.figureId, figure.figureId === figureId);
    });
    for (const key of figurePanelExpansionState.keys()) {
        if (collapsePanels || !key.startsWith(`${figureId}::`)) {
            figurePanelExpansionState.set(key, false);
        }
    }
    figureExpansionState.set(figureId, true);
    if (panelId) {
        figurePanelExpansionState.set(panelWorkspaceKey(figureId, panelId), true);
    }
    return new Promise(resolve => {
        const focusTarget = () => requestAnimationFrame(() => {
            const selector = normalizedPanelId
                ? '.workspace-figure-panel-card[data-figure-id][data-panel-id]'
                : '.workspace-figure-card[data-figure-id]';
            const target = Array.from(document.querySelectorAll(selector)).find(item =>
                item.dataset.figureId === figureId &&
                (!normalizedPanelId || item.dataset.panelId === normalizedPanelId)
            );
            if (!target) {
                resolve(false);
                return;
            }
            [
                target.closest('details.workspace-evidence-block')
            ].filter(Boolean).forEach(ancestor => {
                ancestor.open = true;
                const stateKey = ancestor.dataset.evidenceExpansionKey;
                if (stateKey) figureEvidenceExpansionState.set(stateKey, true);
            });
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            target.querySelector('summary')?.focus({ preventScroll: true });
            resolve(true);
        });
        const request = figureWorkspaceRenderCoordinator.request(
            currentWorkspaceSnapshot, focusTarget
        );
        if (request?.status !== 'rendered') resolve(false);
    });
}

function followFigureOriginalViewerInSidebar(figureId) {
    if (!figureId) return;
    switchWorkspaceView('figures');
    navigateFigureQuickAnchor(figureId, '', { collapsePanels: true });
}

function isCrossFigureLogicCurrentlyVisible() {
    if (figureCaptionSidebarState.visible) return false;
    const view = document.querySelector('.workspace-view[data-workspace-view="figures"]');
    const card = view?.querySelector('.workspace-cross-figure-card[open]');
    if (!view || view.hidden || !card) return false;
    const viewRect = view.getBoundingClientRect();
    const cardRect = card.getBoundingClientRect();
    return cardRect.bottom > viewRect.top + 16 &&
        cardRect.top < viewRect.bottom - 16;
}

function shouldPreserveCrossFigureSidebar(navigationMode) {
    return navigationMode === 'direction' && isCrossFigureLogicCurrentlyVisible();
}

function figureCaptionPanelLabel(block, blockCount, figure) {
    const panels = Array.isArray(block?.panels)
        ? block.panels.map(value => String(value || '').toUpperCase()).filter(Boolean)
        : [];
    if (!panels.length) return blockCount > 1 ? '整图说明' : '整图图注';
    const contiguous = panels.every((panel, index) =>
        index === 0 ||
        panel.charCodeAt(0) === panels[index - 1].charCodeAt(0) + 1
    );
    const displayIds = panels.map(panelId =>
        SciLLM.figurePanelDisplayId(
            figure?.figureLabel, figure?.isSupplemental === true, panelId
        )
    );
    return contiguous && panels.length > 1
        ? `${displayIds[0]}–${displayIds.at(-1)}`
        : displayIds.join('、');
}

function figureCaptionBlocks(figure) {
    const stored = Array.isArray(figure?.captionBlocks)
        ? figure.captionBlocks.filter(block => String(block?.text || '').trim())
        : [];
    if (stored.length) return stored;
    if (typeof SciLLM.splitFigureCaptionByPanelGroups === 'function') {
        return SciLLM.splitFigureCaptionByPanelGroups(figure?.caption || '');
    }
    const caption = String(figure?.caption || '').trim();
    return caption ? [{ kind: 'overview', panels: [], text: caption }] : [];
}

function renderFigureCaptionSidebarSnapshot(
    snapshot = currentWorkspaceSnapshot,
    figureId = figureCaptionSidebarState.figureId
) {
    const container = document.getElementById('figureWorkspace');
    if (!container) return;
    container.classList.add('is-caption-mode');
    container.replaceChildren();
    const figures = Array.isArray(snapshot?.figures?.figures)
        ? snapshot.figures.figures : [];
    const figure = figures.find(item => item.figureId === figureId) || null;
    const summary = document.getElementById('figureWorkspaceSummary');
    if (summary) {
        summary.textContent = figure
            ? `${figure.figureLabel || figure.figureId} · 图注`
            : '正在读取当前 Figure 图注…';
    }
    renderFigureQuickNav([]);
    if (!figure) {
        container.appendChild(createWorkspaceElement(
            'div',
            'workspace-empty',
            '暂未取得当前 Figure 图注，正在刷新论文图片目录…'
        ));
        return;
    }
    const heading = createWorkspaceElement(
        'section',
        'workspace-figure-caption-heading'
    );
    heading.append(
        createWorkspaceElement(
            'h3',
            'workspace-figure-caption-title',
            figure.figureLabel || figure.figureId || 'Figure 图注'
        ),
        createWorkspaceElement(
            'p',
            'workspace-figure-caption-hint',
            '以下内容直接来自网页图注；合并描述的 Panel 保持为同一块。'
        )
    );
    container.appendChild(heading);
    const blocks = figureCaptionBlocks(figure);
    if (!blocks.length) {
        container.appendChild(createWorkspaceElement(
            'div',
            'workspace-empty',
            '该 Figure 暂无可读取的网页图注。'
        ));
        return;
    }
    blocks.forEach(block => {
        const section = createWorkspaceElement(
            'section',
            'workspace-figure-caption-block'
        );
        const panels = Array.isArray(block?.panels)
            ? block.panels.map(String).filter(Boolean) : [];
        section.dataset.panels = panels.join(',');
        section.append(
            createWorkspaceElement(
                'h4',
                'workspace-figure-caption-block-title',
                figureCaptionPanelLabel(block, blocks.length, figure)
            ),
            createWorkspaceElement(
                'p',
                'workspace-figure-caption-block-text',
                String(block?.text || '').trim()
            )
        );
        container.appendChild(section);
    });
}

function showFigureCaptionSidebar(figureId) {
    if (!figureId) return;
    figureCaptionSidebarState = {
        visible: true,
        figureId
    };
    switchWorkspaceView('figures');
    renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
    const figures = currentWorkspaceSnapshot?.figures?.figures || [];
    if (!figures.some(figure => figure.figureId === figureId)) {
        void refreshArticleWorkspace();
    }
}

function hideFigureCaptionSidebar(figureId = '') {
    const restoreFigureId = String(
        figureId || figureCaptionSidebarState.figureId || ''
    );
    figureCaptionSidebarState = {
        visible: false,
        figureId: ''
    };
    const container = document.getElementById('figureWorkspace');
    container?.classList.remove('is-caption-mode');
    renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
    if (restoreFigureId) {
        followFigureOriginalViewerInSidebar(restoreFigureId);
    }
}

function isEditableKeyboardTarget(target) {
    return target instanceof Element && Boolean(target.closest(
        'input, textarea, select, option, [contenteditable]:not([contenteditable="false"]), [role="textbox"], dialog'
    ));
}

function figureKeyboardNumber(figure) {
    const direct = Number(figure?.figureNumber);
    if (Number.isInteger(direct) && direct > 0) return direct;
    const labelMatch = String(figure?.figureLabel || '')
        .match(/\b(?:figure|fig\.?)\s*([0-9]{1,3})\b/i);
    if (labelMatch) return Number(labelMatch[1]);
    const idMatch = String(figure?.figureId || '').match(/^figure-([0-9]{1,3})$/i);
    return idMatch ? Number(idMatch[1]) : 0;
}

function currentFigureKeyboardTarget(figures) {
    const items = Array.isArray(figures) ? figures : [];
    return items.find(figure => figure.figureId === figureQuickNavActiveId) ||
        items.find(figure => figureExpansionState.get(figure.figureId) === true) ||
        items.find(figure => !figure.isSupplemental) ||
        items[0] || null;
}

function navigateFigureKeyboardTarget(figure, panelId = '') {
    if (!figure?.figureId) return false;
    const normalizedPanelId = String(panelId || '').trim().toUpperCase();
    const result = figure.activeDepth === 'standard'
        ? figure.standard : (figure.deep || figure.standard);
    const view = figureWorkspaceViewState.resolve({
        figure,
        modelResult: result,
        draft: currentWorkspaceSnapshot?.figures?.draft ||
            currentWorkspaceSnapshot?.figureWorkspaceDraft
    });
    const viewPanel = view.panels.find(panel => panel.panelId === normalizedPanelId);
    const displayId = viewPanel?.displayId || normalizedPanelId;
    if (normalizedPanelId) {
        if (!viewPanel) {
            showStatus(
                `${figure.figureLabel || figure.figureId} 没有可跳转的 ${displayId}`,
                'error'
            );
            return false;
        }
    }
    switchWorkspaceView('figures');
    navigateFigureQuickAnchor(figure.figureId, normalizedPanelId);
    void focusWorkspaceSource({
        kind: 'figure',
        figureId: figure.figureId
    }).catch(() => false);
    showStatus(
        normalizedPanelId
            ? `已跳转到 ${displayId}`
            : `已跳转到 ${figure.figureLabel || figure.figureId}`,
        'success'
    );
    return true;
}

function figureKeyboardResult(figure) {
    return figure?.activeDepth === 'standard'
        ? figure.standard : (figure?.deep || figure?.standard);
}

function currentFigurePanelKeyboardTarget(figure, panelIds) {
    const focusedPanel = document.activeElement instanceof Element
        ? document.activeElement.closest('.workspace-figure-panel-card[data-panel-id]')
        : null;
    if (focusedPanel?.dataset?.figureId === figure?.figureId &&
        panelIds.includes(String(focusedPanel.dataset.panelId || '').toUpperCase())) {
        return String(focusedPanel.dataset.panelId || '').toUpperCase();
    }
    return panelIds.find(panelId =>
        figurePanelExpansionState.get(panelWorkspaceKey(figure.figureId, panelId)) === true
    ) || panelIds[0] || '';
}

function adjacentFigureKeyboardTarget(figures, currentFigure, offset) {
    if (!figures.length) return null;
    const foundIndex = figures.findIndex(figure =>
        figure.figureId === currentFigure?.figureId
    );
    const currentIndex = foundIndex >= 0 ? foundIndex : 0;
    return figures[(currentIndex + offset + figures.length) % figures.length] || null;
}

function handleFigureKeyboardShortcut(event) {
    if (!figureKeyboardShortcutArmed || event.defaultPrevented || event.isComposing ||
        event.repeat || event.ctrlKey || event.metaKey || event.altKey ||
        isEditableKeyboardTarget(event.target)) return;
    const figures = Array.isArray(currentWorkspaceSnapshot?.figures?.figures)
        ? currentWorkspaceSnapshot.figures.figures : [];
    if (!figures.length) return;
    let handled = false;
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        const currentFigure = currentFigureKeyboardTarget(figures);
        const targetFigure = adjacentFigureKeyboardTarget(
            figures,
            currentFigure,
            event.key === 'ArrowLeft' ? -1 : 1
        );
        if (targetFigure) {
            const panelIds = figureCatalogPanelIds(
                targetFigure,
                figureKeyboardResult(targetFigure)
            );
            handled = navigateFigureKeyboardTarget(
                targetFigure,
                panelIds.includes('A') ? 'A' : (panelIds[0] || '')
            );
        }
    } else if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        const figure = currentFigureKeyboardTarget(figures);
        if (figure) {
            const panelIds = figureCatalogPanelIds(figure, figureKeyboardResult(figure));
            const currentPanelId = currentFigurePanelKeyboardTarget(figure, panelIds);
            const currentIndex = Math.max(0, panelIds.indexOf(currentPanelId));
            const targetIndex = Math.max(
                0,
                Math.min(
                    panelIds.length - 1,
                    currentIndex + (event.key === 'ArrowUp' ? -1 : 1)
                )
            );
            if (panelIds[targetIndex]) {
                handled = navigateFigureKeyboardTarget(figure, panelIds[targetIndex]);
            }
        }
    } else if (/^[1-9]$/.test(event.key)) {
        const requestedNumber = Number(event.key);
        const figure = figures.find(item =>
            !item.isSupplemental && figureKeyboardNumber(item) === requestedNumber
        );
        if (figure) {
            handled = navigateFigureKeyboardTarget(figure);
        } else {
            showStatus(`当前论文没有 Figure ${requestedNumber}`, 'error');
            handled = true;
        }
    }
    if (handled) event.preventDefault();
}

function currentKeyboardShortcuts() {
    return SciLLM.normalizeKeyboardShortcuts(
        llmSettingsState?.settings?.keyboardShortcuts
    );
}

function clickShortcutControl(elementId) {
    const control = document.getElementById(elementId);
    if (!control) return false;
    control.click();
    return true;
}

function runGlobalKeyboardShortcut(actionId) {
    if (actionId === 'focusReading') {
        const controller = sidebarFocusModeController || setupSidebarFocusMode();
        if (!controller) return false;
        controller.toggle();
        return true;
    }
    if (actionId === 'semanticFind') {
        void sendTabMessage(activePanelTabContext.tabId, { action: 'openSemanticFind' })
            .catch(error => showStatus(error.message, 'error'));
        return true;
    }
    const workspaceTargets = {
        figures: 'figures',
        navigation: 'navigation',
        analysis: 'analysis',
        highlights: 'highlights',
        chat: 'chat'
    };
    if (workspaceTargets[actionId]) {
        openWorkspaceView(workspaceTargets[actionId]);
        return true;
    }
    if (actionId === 'collapseFigurePanels') {
        if (activeWorkspaceView !== 'figures') return false;
        collapseAllFigurePanels();
        return true;
    }
    const controlIds = {
        zotero: 'exportEnhancedSnapshotToZotero',
        ppt: 'exportPptMaterials',
        scanLocal: 'scanArticleWorkspace',
        saveLocal: 'saveCurrentArticleWorkspace',
        deleteLocal: 'clearArticleWorkspace',
        exportJson: 'exportCurrentArticleArchive',
        importJson: 'importCurrentArticleArchiveButton',
        settings: 'openSidePanelSettings'
    };
    return clickShortcutControl(controlIds[actionId]);
}

async function openFigureOneOriginalFromShortcut() {
    switchWorkspaceView('figures');
    let snapshot = currentWorkspaceSnapshot;
    let figures = Array.isArray(snapshot?.figures?.figures)
        ? snapshot.figures.figures : [];
    if (!figures.length) {
        snapshot = await refreshArticleWorkspace();
        figures = Array.isArray(snapshot?.figures?.figures)
            ? snapshot.figures.figures : [];
    }
    const figure = figures.find(item =>
        !item.isSupplemental && figureKeyboardNumber(item) === 1
    );
    if (!figure?.figureId) {
        showStatus('当前论文没有可打开的 Figure 1', 'error');
        return false;
    }
    followFigureOriginalViewerInSidebar(figure.figureId);
    try {
        await showFigureOriginalImage(figure.figureId);
        return true;
    } catch (error) {
        showStatus(error.message, 'error');
        return false;
    }
}

function runGlobalKeyboardShortcutKey(value) {
    if (figureOriginalViewerState.open) return false;
    const key = SciLLM.normalizeKeyboardShortcutKey(value, '');
    if (!key) return false;
    const shortcuts = currentKeyboardShortcuts();
    const definition = SciLLM.KEYBOARD_SHORTCUT_DEFINITIONS.find(item =>
        shortcuts[item.actionId] === key
    );
    if (!definition) return false;
    if (definition.actionId === 'figures') {
        const pressedAt = Date.now();
        const doublePressed = lastFigureModuleShortcutPress.key === key &&
            pressedAt - lastFigureModuleShortcutPress.pressedAt <= 450;
        lastFigureModuleShortcutPress = doublePressed
            ? { key: '', pressedAt: 0 }
            : { key, pressedAt };
        if (doublePressed) {
            void openFigureOneOriginalFromShortcut();
            return true;
        }
    } else {
        lastFigureModuleShortcutPress = {
            key: '',
            pressedAt: 0
        };
    }
    return runGlobalKeyboardShortcut(definition.actionId);
}

function handleGlobalKeyboardShortcut(event) {
    if (event.defaultPrevented || event.isComposing ||
        event.repeat || event.ctrlKey || event.metaKey || event.altKey ||
        isEditableKeyboardTarget(event.target) ||
        !runGlobalKeyboardShortcutKey(event.key)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
}

function setupGlobalKeyboardShortcuts() {
    document.addEventListener('keydown', handleGlobalKeyboardShortcut, true);
    chrome.storage.onChanged.addListener((changes, areaName) => {
        if (areaName !== 'local' || !changes.sciLlmSettingsV2) return;
        void sendLlmMessage({ type: 'LLM_GET_SETTINGS' })
            .then(nextState => {
                llmSettingsState = nextState;
                return publishSidePanelShortcutScope();
            })
            .catch(() => undefined);
    });
}

function figureOriginalViewerDirection(key) {
    return {
        ArrowLeft: 'previous',
        ArrowRight: 'next',
        ArrowUp: 'first',
        ArrowDown: 'last'
    }[key] || '';
}

async function syncFigureOriginalViewerState() {
    const tab = await queryPanelTargetTab();
    if (!tab?.id || !activePanelTabContext.activated ||
        Number(tab.id) !== Number(activePanelTabContext.tabId)) {
        const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
        figureOriginalViewerState = {
            open: false,
            tabId: tab?.id ?? null,
            figureId: '',
            captionVisible: false,
            requestSequence: figureOriginalViewerState.requestSequence + 1
        };
        if (previousCaptionVisible) hideFigureCaptionSidebar();
        return figureOriginalViewerState;
    }
    const requestSequence = ++figureOriginalViewerState.requestSequence;
    try {
        const response = await sendTabMessage(tab.id, {
            action: 'getFigureOriginalImageState'
        });
        if (requestSequence !== figureOriginalViewerState.requestSequence) {
            return figureOriginalViewerState;
        }
        const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
        figureOriginalViewerState = {
            open: response?.success === true && response?.open === true,
            tabId: tab.id,
            figureId: String(response?.figureId || ''),
            captionVisible: response?.captionVisible === true,
            requestSequence
        };
        if (figureOriginalViewerState.open &&
            figureOriginalViewerState.captionVisible &&
            figureOriginalViewerState.figureId) {
            showFigureCaptionSidebar(figureOriginalViewerState.figureId);
        } else if (previousCaptionVisible) {
            hideFigureCaptionSidebar(figureOriginalViewerState.figureId);
        }
    } catch (_) {
        if (requestSequence === figureOriginalViewerState.requestSequence) {
            const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
            figureOriginalViewerState = {
                open: false,
                tabId: tab.id,
                figureId: '',
                captionVisible: false,
                requestSequence
            };
            if (previousCaptionVisible) hideFigureCaptionSidebar();
        }
    }
    return figureOriginalViewerState;
}

async function forwardFigureOriginalViewerKey(key) {
    const tabId = Number(figureOriginalViewerState.tabId);
    if (!Number.isInteger(tabId)) return;
    const requestSequence = ++figureOriginalViewerState.requestSequence;
    const direction = figureOriginalViewerDirection(key);
    const figureNumber = /^[0-9]$/.test(key)
        ? (key === '0' ? 10 : Number(key)) : 0;
    const isNavigation = Boolean(direction || figureNumber);
    const preserveCrossFigureSidebar =
        shouldPreserveCrossFigureSidebar(direction ? 'direction' : 'number');
    if (key === 'Escape') {
        const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
        figureOriginalViewerState = {
            open: false,
            tabId,
            figureId: '',
            captionVisible: false,
            requestSequence
        };
        if (previousCaptionVisible) hideFigureCaptionSidebar();
    }
    try {
        const response = await sendTabMessage(tabId, isNavigation ? {
            action: 'navigateFigureOriginalImage',
            direction,
            figureNumber
        } : {
            action: 'closeFigureOriginalImage'
        });
        if (requestSequence !== figureOriginalViewerState.requestSequence) return;
        if (isNavigation && response?.success) {
            figureOriginalViewerState = {
                open: response.open !== false,
                tabId,
                figureId: String(response.figureId || ''),
                captionVisible: response.captionVisible === true,
                requestSequence
            };
            if (response.figureId) {
                if (response.captionVisible === true) {
                    showFigureCaptionSidebar(String(response.figureId));
                } else if (!preserveCrossFigureSidebar) {
                    followFigureOriginalViewerInSidebar(String(response.figureId));
                }
            }
        } else if (!isNavigation || response?.code === 'VIEWER_NOT_OPEN') {
            const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
            figureOriginalViewerState = {
                open: false,
                tabId,
                figureId: '',
                captionVisible: false,
                requestSequence
            };
            if (previousCaptionVisible) hideFigureCaptionSidebar();
        }
    } catch (_) {
        if (requestSequence === figureOriginalViewerState.requestSequence) {
            const previousCaptionVisible = figureOriginalViewerState.captionVisible === true;
            figureOriginalViewerState = {
                open: false,
                tabId,
                figureId: '',
                captionVisible: false,
                requestSequence
            };
            if (previousCaptionVisible) hideFigureCaptionSidebar();
        }
    }
}

function handleFigureOriginalViewerKeyboard(event) {
    const direction = figureOriginalViewerDirection(event.key);
    const figureNumberKey = /^[0-9]$/.test(event.key);
    if (!figureOriginalViewerState.open ||
        (!direction && !figureNumberKey && event.key !== 'Escape') ||
        event.defaultPrevented || event.isComposing || event.repeat ||
        event.ctrlKey || event.metaKey || event.altKey ||
        isEditableKeyboardTarget(event.target)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    void forwardFigureOriginalViewerKey(event.key);
}

function setupFigureKeyboardNavigation() {
    const eligibleSelector = '#sidePanelApp';
    document.addEventListener('keydown', handleFigureOriginalViewerKeyboard, true);
    document.addEventListener('pointermove', event => {
        figureKeyboardShortcutArmed = event.target instanceof Element &&
            Boolean(event.target.closest(eligibleSelector));
    }, { passive: true });
    document.addEventListener('pointerleave', () => {
        figureKeyboardShortcutArmed = false;
    });
    document.addEventListener('keydown', handleFigureKeyboardShortcut);
    document.querySelector(eligibleSelector)?.addEventListener('pointerenter', () => {
        void syncFigureOriginalViewerState();
    });
    window.addEventListener('focus', () => {
        void syncFigureOriginalViewerState();
    });
}

function renderFigureQuickNav(figures) {
    const nav = document.getElementById('figureQuickNav');
    if (!nav) return;
    clearTimeout(figureQuickNavHoverTimer);
    figureQuickNavHoverTimer = null;
    nav.replaceChildren();
    const items = Array.isArray(figures) ? figures : [];
    if (!items.length) {
        nav.hidden = true;
        return;
    }
    if (!items.some(figure => figure.figureId === figureQuickNavActiveId)) {
        figureQuickNavActiveId = items.find(figure => figure.standard || figure.deep)?.figureId ||
            items[0].figureId;
    }
    const figureMarkers = createWorkspaceElement('div', 'figure-quick-nav-figures');
    items.forEach(figure => {
        const item = createWorkspaceElement('div', 'figure-quick-nav-item');
        item.dataset.figureId = figure.figureId;
        item.dataset.figureKind = figure.isSupplemental === true ? 'supplemental' : 'main';
        item.classList.toggle('is-supplemental', figure.isSupplemental === true);
        const marker = createWorkspaceElement('button', 'figure-quick-nav-marker');
        marker.type = 'button';
        marker.setAttribute('aria-label', `跳转到 ${figure.figureLabel || figure.figureId}`);
        marker.setAttribute('aria-current', String(figure.figureId === figureQuickNavActiveId));
        marker.appendChild(createWorkspaceElement('span', 'figure-quick-nav-tick'));
        marker.addEventListener('click', () => navigateFigureQuickAnchor(figure.figureId));

        const flyout = createWorkspaceElement('div', 'figure-quick-nav-flyout');
        const modelResult = figure.activeDepth === 'standard'
            ? figure.standard : (figure.deep || figure.standard);
        const view = figureWorkspaceViewState.get(figure.figureId) ||
            figureWorkspaceViewState.resolve({
                figure,
                modelResult,
                draft: currentWorkspaceSnapshot?.figures?.draft ||
                    currentWorkspaceSnapshot?.figureWorkspaceDraft
            });
        const viewPanels = (Array.isArray(view?.panels) ? view.panels : [])
            .slice().sort((left, right) => String(left.panelId).localeCompare(
                String(right.panelId), undefined, {
            numeric: true,
            sensitivity: 'base'
        }));
        const panelIds = viewPanels.map(viewPanel => viewPanel.panelId);
        const panelPopover = createWorkspaceElement('div', 'figure-quick-nav-panel-popover');
        panelPopover.setAttribute('aria-label', `${figure.figureLabel || figure.figureId} 的 Panel`);
        viewPanels.forEach(viewPanel => {
            const panelId = viewPanel.panelId;
            const panelButton = createWorkspaceElement(
                'button', 'figure-quick-nav-panel-button', viewPanel.displayId
            );
            panelButton.type = 'button';
            panelButton.addEventListener('click', event => {
                event.stopPropagation();
                navigateFigureQuickAnchor(figure.figureId, panelId);
            });
            panelPopover.appendChild(panelButton);
        });
        const label = createWorkspaceElement(
            'button', 'figure-quick-nav-label', figure.figureLabel || figure.figureId
        );
        label.type = 'button';
        label.addEventListener('click', () => navigateFigureQuickAnchor(figure.figureId));
        flyout.append(panelPopover, label);

        const closePanels = () => {
            item.classList.remove('show-panels');
            if (figureQuickNavExpandedFigureId === figure.figureId) {
                figureQuickNavExpandedFigureId = '';
            }
        };
        const activateItem = () => {
            clearTimeout(figureQuickNavHoverTimer);
            figureQuickNavHoverTimer = null;
            nav.querySelectorAll('.figure-quick-nav-item.show-panels').forEach(other => {
                if (other !== item) other.classList.remove('show-panels');
            });
            figureQuickNavExpandedFigureId = panelIds.length ? figure.figureId : '';
            item.classList.toggle('show-panels', panelIds.length > 0);
            figureQuickNavActiveId = figure.figureId;
            nav.querySelectorAll('.figure-quick-nav-marker').forEach(button => {
                const owner = button.closest('.figure-quick-nav-item');
                button.setAttribute('aria-current', String(owner?.dataset.figureId === figure.figureId));
            });
        };
        item.addEventListener('mouseenter', activateItem);
        item.addEventListener('focusin', activateItem);
        item.addEventListener('mouseleave', () => {
            clearTimeout(figureQuickNavHoverTimer);
            figureQuickNavHoverTimer = setTimeout(closePanels, 45);
        });
        item.addEventListener('focusout', event => {
            if (item.contains(event.relatedTarget)) return;
            clearTimeout(figureQuickNavHoverTimer);
            figureQuickNavHoverTimer = setTimeout(closePanels, 45);
        });
        item.append(marker, flyout);
        figureMarkers.appendChild(item);
    });
    nav.appendChild(figureMarkers);
    const closeAllPanelFlyouts = () => {
        nav.querySelectorAll('.figure-quick-nav-item.show-panels').forEach(item => {
            item.classList.remove('show-panels');
        });
        figureQuickNavExpandedFigureId = '';
    };
    const scheduleCloseAllPanelFlyouts = () => {
        clearTimeout(figureQuickNavHoverTimer);
        figureQuickNavHoverTimer = setTimeout(() => {
            if (!nav.matches(':hover') && !nav.matches(':focus-within')) {
                closeAllPanelFlyouts();
            }
        }, 45);
    };
    // Item-level leave handlers cover normal pointer travel. These container
    // handlers also close a flyout after fast movement, forced pointer events,
    // or a focus transition that skips the originating item.
    nav.onmouseleave = scheduleCloseAllPanelFlyouts;
    nav.onfocusout = event => {
        if (!nav.contains(event.relatedTarget)) scheduleCloseAllPanelFlyouts();
    };
    nav.hidden = false;
}

function mechanismWorkspaceDraft(snapshot = currentWorkspaceSnapshot) {
    return snapshot?.figures?.draft || snapshot?.figureWorkspaceDraft || null;
}

function mechanismWorkspaceFigures(snapshot = currentWorkspaceSnapshot) {
    return Array.isArray(snapshot?.figures?.figures)
        ? snapshot.figures.figures.slice(0, 128) : [];
}

function mechanismWorkspaceAudit(draft = mechanismWorkspaceDraft()) {
    return typeof draft?.mechanismGeneration === 'string'
        ? SciLLM.readMechanismGenerationAudit(draft.mechanismGeneration) : null;
}

function setMechanismChainSaveStatus(message, state = 'saved') {
    const status = document.getElementById('mechanismChainSaveStatus');
    if (!status) return;
    status.textContent = String(message || '').slice(0, 160);
    status.dataset.state = state;
}

function mechanismNetworkPaperIdentity(workspace = null) {
    const live = workspace || currentWorkspaceSnapshot?.localWorkspace || {};
    const archive = currentArticleArchiveIdentity();
    const documentId = String(archive.documentId || '').normalize('NFKC').trim();
    const title = Array.from(String(
        archive.title || currentWorkspaceSnapshot?.title || ''
    ).normalize('NFKC')
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/gu, '')
        .replace(/\s+/gu, ' ').trim()).slice(0, 500).join('');
    return {
        workspaceId: String(live.workspaceId || ''),
        workspaceGeneration: Number(live.workspaceGeneration) || 0,
        canonicalUrl: String(live.canonicalUrl || currentWorkspaceSnapshot?.url || ''),
        contentHash: String(live.contentHash || live.revision || '')
            .replace(/^sha256:/u, ''),
        ...(documentId ? { documentId } : {}),
        ...(title ? { title } : {})
    };
}

function normalizeMechanismNetworkViewMode(value) {
    return value === 'actual-size' ? 'actual-size' : 'fit-width';
}

function mechanismNetworkViewPaperKey(identity) {
    identity = identity && typeof identity === 'object' ? identity : Object.create(null);
    const read = (key, maximum) => {
        try {
            if (!identity || typeof identity !== 'object' || Array.isArray(identity)) return '';
            const descriptor = Object.getOwnPropertyDescriptor(identity, key);
            if (!descriptor || !Object.hasOwn(descriptor, 'value') ||
                typeof descriptor.value !== 'string') return '';
            return Array.from(descriptor.value.normalize('NFKC')
                .replace(/[\u0000-\u001F\u007F]/gu, ' ').trim())
                .slice(0, maximum).join('');
        } catch (_) { return ''; }
    };
    const documentId = read('documentId', 220);
    if (documentId) return `document:${documentId}`;
    const canonicalUrl = read('canonicalUrl', 600);
    const contentHash = read('contentHash', 160).replace(/^sha256:/u, '');
    if (canonicalUrl || contentHash) return `paper:${canonicalUrl}\u0000${contentHash}`;
    const workspaceId = read('workspaceId', 240);
    return workspaceId ? `workspace:${workspaceId}` : '';
}

function createMechanismNetworkViewModeCache(maximum = 12) {
    const limit = Number.isSafeInteger(maximum)
        ? Math.max(1, Math.min(32, maximum)) : 12;
    const entries = new Map();
    const safeKey = value => typeof value === 'string'
        ? Array.from(value).slice(0, 1000).join('') : '';
    return Object.freeze({
        get(rawKey) {
            const key = safeKey(rawKey);
            if (!key || !entries.has(key)) return 'fit-width';
            const mode = entries.get(key);
            entries.delete(key);
            entries.set(key, mode);
            return mode;
        },
        set(rawKey, rawMode) {
            const key = safeKey(rawKey);
            const mode = normalizeMechanismNetworkViewMode(rawMode);
            if (!key) return mode;
            entries.delete(key);
            entries.set(key, mode);
            while (entries.size > limit) entries.delete(entries.keys().next().value);
            return mode;
        },
        clear() { entries.clear(); },
        size() { return entries.size; }
    });
}

function applyMechanismMermaidViewMode(diagram, rawMode) {
    const mode = normalizeMechanismNetworkViewMode(rawMode);
    if (!diagram || typeof diagram !== 'object') return mode;
    if (diagram.dataset) diagram.dataset.viewMode = mode;
    const svg = typeof diagram.querySelector === 'function'
        ? diagram.querySelector('svg') : null;
    if (!svg) return mode;
    let naturalWidth = 520;
    try {
        const viewBox = String(svg.getAttribute('viewBox') || '').trim().split(/[\s,]+/u);
        const candidate = Number(viewBox.length === 4 ? viewBox[2] : svg.getAttribute('width'));
        if (Number.isFinite(candidate) && candidate > 0) {
            naturalWidth = Math.min(16384, candidate);
        }
    } catch (_) { naturalWidth = 520; }
    diagram.style?.setProperty('--mechanism-mermaid-natural-width', `${naturalWidth}px`);
    return mode;
}

function createMechanismMermaidViewControls(
    diagram, paperKey, cache, translate = value => String(value || '')
) {
    const group = document.createElement('div');
    group.className = 'workspace-mechanism-view-controls';
    group.setAttribute('role', 'group');
    group.setAttribute('aria-label', translate('机制图缩放'));
    const buttons = new Map();
    const apply = rawMode => {
        const mode = cache?.set?.(paperKey, rawMode) ||
            normalizeMechanismNetworkViewMode(rawMode);
        applyMechanismMermaidViewMode(diagram, mode);
        buttons.forEach((button, key) => {
            button.setAttribute('aria-pressed', String(key === mode));
        });
        return mode;
    };
    [
        ['fit-width', translate('适合宽度'), translate('适合宽度')],
        ['actual-size', '100%', translate('实际大小（100%）')]
    ].forEach(([mode, label, accessibleName]) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'workspace-mechanism-view-mode';
        button.dataset.mechanismViewMode = mode;
        button.textContent = label;
        button.setAttribute('aria-label', accessibleName);
        button.addEventListener('click', () => apply(mode));
        buttons.set(mode, button);
        group.appendChild(button);
    });
    const reset = document.createElement('button');
    reset.type = 'button';
    reset.className = 'workspace-mechanism-view-mode';
    reset.dataset.mechanismViewReset = '';
    reset.textContent = translate('恢复视图');
    reset.setAttribute('aria-label', translate('恢复适合宽度并回到图起点'));
    reset.addEventListener('click', () => {
        apply('fit-width');
        diagram.scrollTo?.({ left: 0, top: 0, behavior: 'smooth' });
    });
    group.appendChild(reset);
    apply(cache?.get?.(paperKey));
    return group;
}

const MECHANISM_REGION_TARGETS = Object.freeze({
    'saved-graph': 'mechanismGraphRegion',
    'saved-evidence': 'mechanismEvidenceRegion',
    'pending-graph': 'mechanismPendingGraphRegion',
    'pending-evidence': 'mechanismPendingEvidenceRegion',
    'pending-unresolved': 'mechanismPendingUnresolvedRegion'
});

function refreshMechanismSectionNavigation(root = document) {
    let available = 0;
    root.querySelectorAll?.('[data-mechanism-region]').forEach(button => {
        const targetId = MECHANISM_REGION_TARGETS[button.dataset.mechanismRegion];
        const exists = Boolean(targetId && document.getElementById(targetId));
        button.hidden = !exists;
        button.disabled = !exists;
        if (!exists) button.removeAttribute('aria-current');
        if (exists) available += 1;
    });
    const navigation = document.getElementById('mechanismSectionNavigation');
    if (navigation) navigation.hidden = available === 0;
}

function scrollToMechanismRegion(region, trigger = null) {
    const targetId = MECHANISM_REGION_TARGETS[String(region || '')];
    const target = targetId ? document.getElementById(targetId) : null;
    if (!target) return false;
    if (!target.hasAttribute('tabindex')) target.tabIndex = -1;
    target.focus({ preventScroll: true });
    target.scrollIntoView({ behavior: 'smooth', block: 'start', inline: 'nearest' });
    trigger?.setAttribute?.('aria-current', 'location');
    return true;
}

function prepareMechanismPendingPreviewNavigation(section, snapshot = null) {
    if (!section || typeof section.querySelector !== 'function') return null;
    section.id = 'mechanismPendingRegion';
    const graph = section.querySelector('.workspace-mechanism-mermaid-section');
    const evidence = section.querySelector('.mechanism-pending-preview-evidence');
    const unresolved = section.querySelector('.mechanism-pending-preview-nonrelation');
    [
        [graph, 'mechanismPendingGraphRegion'],
        [evidence, 'mechanismPendingEvidenceRegion'],
        [unresolved, 'mechanismPendingUnresolvedRegion']
    ].forEach(([target, id]) => {
        if (!target) return;
        target.id = id;
        target.tabIndex = -1;
    });
    const diagram = graph?.querySelector('.workspace-mechanism-mermaid');
    if (diagram && !graph.querySelector('[data-mechanism-pending-view-controls]')) {
        const paperKey = mechanismNetworkViewPaperKey(
            mechanismNetworkPaperIdentity(snapshot?.localWorkspace)
        );
        const digest = String(section.dataset?.canonicalDigest || '').slice(0, 96);
        const controls = createMechanismMermaidViewControls(
            diagram, `${paperKey}:pending:${digest}`, mechanismNetworkViewModeCache, t
        );
        controls.dataset.mechanismPendingViewControls = '';
        graph.insertBefore(controls, diagram);
    }
    const panelContext = Object.freeze({ ...capturePanelContext() });
    section.querySelectorAll('[data-mechanism-source-panel]').forEach(button => {
        if (button.dataset.mechanismSourceActionReady === 'true') return;
        const figureId = String(button.dataset.figureId || '').trim().slice(0, 80);
        const panelId = String(button.dataset.panelId || '').trim().toUpperCase();
        if (!figureId || !/^[A-Z0-9][A-Z0-9.+-]{0,7}$/u.test(panelId)) return;
        button.addEventListener('click', () => {
            void jumpToPanelFollowupSource({ kind: 'panel', figureId, panelId }, panelContext);
        });
        button.dataset.mechanismSourceActionReady = 'true';
    });
    refreshMechanismSectionNavigation();
    return { graph, evidence, unresolved };
}

function createMechanismRelationLegend(translate = value => String(value || '')) {
    const legend = document.createElement('div');
    legend.className = 'workspace-mechanism-relation-legend';
    legend.setAttribute('role', 'list');
    legend.setAttribute('aria-label', translate('关系图例'));
    [
        ['causal', '→', '因果联系'],
        ['positive', '＋', '正向/促进'],
        ['negative', '−', '负向/抑制'],
        ['correlative', '┄', '相关联系'],
        ['contested', '!', '争议联系']
    ].forEach(([className, symbol, label]) => {
        const item = document.createElement('span');
        item.className = `workspace-mechanism-relation-legend-item is-${className}`;
        item.setAttribute('role', 'listitem');
        const mark = document.createElement('span');
        mark.className = 'workspace-mechanism-relation-legend-mark';
        mark.setAttribute('aria-hidden', 'true');
        mark.textContent = symbol;
        item.append(mark, document.createTextNode(translate(label)));
        legend.appendChild(item);
    });
    return legend;
}

function mechanismNetworkExportFilename(extension) {
    const title = String(currentArticleArchiveIdentity().title || 'mechanism-network')
        .normalize('NFKC').replace(/[<>:"/\\|?*\u0000-\u001f]+/gu, '-')
        .replace(/\s+/gu, ' ').trim().slice(0, 80) || 'mechanism-network';
    return `${title}-mechanism-network.${extension}`;
}

function mechanismNetworkExportLayout(graph) {
    const viewport = document.getElementById('mechanismNetworkViewport');
    const width = Math.max(900, Math.min(1800, Number(viewport?.clientWidth) || 900));
    return SciLLM.createMechanismNetworkLayout(graph, { viewportWidth: width });
}

function mechanismSvgToPngBlob(svg, layout) {
    const plan = SciLLM.createMechanismNetworkPngPlan({
        width: layout.width,
        height: layout.height + 72
    }, { scale: 2 });
    return new Promise((resolve, reject) => {
        const source = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });
        const objectUrl = URL.createObjectURL(source);
        const image = new Image();
        image.onload = () => {
            try {
                const canvas = document.createElement('canvas');
                canvas.width = plan.width;
                canvas.height = plan.height;
                const context = canvas.getContext('2d');
                if (!context || typeof canvas.toBlob !== 'function') {
                    throw new Error('MECHANISM_NETWORK_PNG_UNAVAILABLE');
                }
                context.fillStyle = '#ffffff';
                context.fillRect(0, 0, plan.width, plan.height);
                context.drawImage(image, 0, 0, plan.width, plan.height);
                canvas.toBlob(blob => {
                    URL.revokeObjectURL(objectUrl);
                    if (blob) resolve(blob);
                    else reject(new Error('MECHANISM_NETWORK_PNG_UNAVAILABLE'));
                }, 'image/png');
            } catch (error) {
                URL.revokeObjectURL(objectUrl);
                reject(error);
            }
        };
        image.onerror = () => {
            URL.revokeObjectURL(objectUrl);
            reject(new Error('MECHANISM_NETWORK_PNG_UNAVAILABLE'));
        };
        image.src = objectUrl;
    });
}

async function exportMechanismNetwork(format) {
    const button = document.getElementById('openMechanismExportMenu');
    if (button?.disabled) return;
    if (button) button.disabled = true;
    try {
        const draft = mechanismWorkspaceDraft();
        const chain = draft?.mechanismChain;
        if (!chain) throw new Error('MECHANISM_NETWORK_EXPORT_EMPTY');
        const normalizedFormat = String(format || '').toLowerCase();
        if (!['png', 'svg', 'json'].includes(normalizedFormat)) {
            throw new Error('MECHANISM_NETWORK_EXPORT_FORMAT_INVALID');
        }
        if (normalizedFormat === 'json') {
            const rawGeneration = typeof draft.mechanismGeneration === 'string'
                ? draft.mechanismGeneration : null;
            const generation = rawGeneration
                ? SciLLM.readMechanismGenerationEnvelope(rawGeneration) : null;
            const mechanismGeneration = generation?.envelopeKind === 'durable'
                ? rawGeneration : null;
            const serialized = JSON.stringify(SciLLM.createMechanismNetworkJson({
                chain,
                paper: mechanismNetworkPaperIdentity(),
                mechanismGeneration
            }));
            downloadBlob(new Blob([serialized], {
                type: 'application/json;charset=utf-8'
            }), mechanismNetworkExportFilename('json'));
        } else {
            const graph = SciLLM.createMechanismGraphExportDto(
                mechanismWorkspaceAudit(draft) || chain
            );
            if (!graph?.nodes?.length) throw new Error('MECHANISM_NETWORK_EXPORT_EMPTY');
            const layout = mechanismNetworkExportLayout(graph);
            const svg = SciLLM.serializeMechanismAuditSvg({ graph, layout });
            const blob = normalizedFormat === 'svg'
                ? new Blob([svg], { type: 'image/svg+xml;charset=utf-8' })
                : await mechanismSvgToPngBlob(svg, layout);
            downloadBlob(blob, mechanismNetworkExportFilename(normalizedFormat));
        }
        closeMechanismNetworkExportMenu();
        showStatus(`图表梳理已导出为 ${normalizedFormat.toUpperCase()}`, 'success');
    } catch (_) {
        showStatus('图表梳理导出失败，请检查网络结构后重试。', 'error');
    } finally {
        if (button) button.disabled = false;
    }
}

function mechanismNetworkImportFailureCode(error) {
    const allowed = new Set([
        'MECHANISM_NETWORK_IMPORT_INVALID',
        'MECHANISM_NETWORK_IMPORT_CANCELLED',
        'MECHANISM_NETWORK_IMPORT_PAPER_MISMATCH',
        'MECHANISM_NETWORK_IMPORT_FAILED',
        'FIGURE_WORKSPACE_CONTEXT_INVALID',
        'FIGURE_WORKSPACE_CONTEXT_MISMATCH',
        'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED',
        'FIGURE_WORKSPACE_LIFECYCLE_CHANGED',
        'FIGURE_WORKSPACE_REVISION_INVALID',
        'FIGURE_WORKSPACE_REVISION_CONFLICT',
        'FIGURE_WORKSPACE_SAVE_ASSET_MISSING',
        'FIGURE_WORKSPACE_SAVE_FROZEN',
        'FIGURE_WORKSPACE_SAVE_REJECTED',
        'FIGURE_WORKSPACE_SAVE_RESPONSE_MISSING',
        'FIGURE_WORKSPACE_SAVE_UNCHANGED'
    ]);
    if (typeof error?.code === 'string' && allowed.has(error.code)) return error.code;
    if (typeof error?.message === 'string' && allowed.has(error.message)) return error.message;
    return 'MECHANISM_NETWORK_IMPORT_FAILED';
}

async function importMechanismNetworkFile(file) {
    let stage = 'validate';
    if (!file || typeof file.text !== 'function' ||
        !Number.isSafeInteger(file.size) || file.size < 1 ||
        file.size > MECHANISM_NETWORK_IMPORT_MAX_BYTES) {
        showStatus('图表梳理 JSON 无效或超过 2 MB。', 'error');
        return { success: false, code: 'MECHANISM_NETWORK_IMPORT_INVALID' };
    }
    try {
        stage = 'read';
        const jsonText = await file.text();
        if (jsonText.length > MECHANISM_NETWORK_IMPORT_MAX_BYTES) {
            throw new Error('MECHANISM_NETWORK_IMPORT_INVALID');
        }
        const importKind = SciLLM.classifyMechanismNetworkJson(jsonText);
        let legacyGraph = null;
        let legacyChain = null;
        if (importKind.kind === 'legacy_graph') {
            legacyGraph = SciLLM.parseMechanismGraphExport(jsonText);
            if (!confirm(
                '这是旧版机制图 JSON。继续导入会丢失 Panel 证据、别名与审计信息。是否继续？'
            )) {
                showStatus('已取消旧版机制图导入。', 'info');
                return {
                    success: false,
                    cancelled: true,
                    code: 'MECHANISM_NETWORK_IMPORT_CANCELLED'
                };
            }
            legacyChain = {
                initialized: true,
                nodes: legacyGraph.nodes.map(node => ({
                    id: node.id,
                    label: {
                        value: node.label, humanReviewed: false, editedAt: 0
                    }
                })),
                edges: legacyGraph.edges.map(edge => ({
                    id: edge.id, from: edge.from, to: edge.to,
                    label: {
                        value: edge.label, humanReviewed: false, editedAt: 0
                    },
                    polarity: edge.polarity, panelEvidence: [],
                    humanReviewed: false, editedAt: 0
                })),
                panelAliases: {},
                reviewTombstones: { nodes: [], edges: [], evidence: [] }
            };
            SciLLM.validateMechanismWorkspaceImport(
                mechanismWorkspaceDraft(), legacyChain, null
            );
        } else {
            const preflight = SciLLM.parseMechanismNetworkJson(
                jsonText, mechanismNetworkPaperIdentity()
            );
            SciLLM.validateMechanismWorkspaceImport(
                mechanismWorkspaceDraft(),
                preflight.mechanismChain,
                preflight.mechanismGeneration
            );
        }
        const context = captureFigureWorkspaceEditContext();
        stage = 'ensure';
        const ensured = await sendTabMessage(context.tabId, {
            action: 'ensureArticleWorkspace', forceRefresh: true
        });
        if (!ensured?.success || !ensured.workspace ||
            !ensured.restoreAuthorization?.token ||
            !isCurrentFigureWorkspaceEditContext(context)) {
            throw new Error('MECHANISM_NETWORK_IMPORT_PAPER_MISMATCH');
        }
        const paper = mechanismNetworkPaperIdentity(ensured.workspace);
        stage = 'parse';
        let restoreJsonText = jsonText;
        if (importKind.kind === 'workspace') {
            SciLLM.parseMechanismNetworkJson(jsonText, paper);
        } else {
            restoreJsonText = JSON.stringify(SciLLM.createMechanismNetworkJson({
                chain: legacyChain, paper, mechanismGeneration: null
            }));
            SciLLM.parseMechanismNetworkJson(restoreJsonText, paper);
        }
        stage = 'restore';
        const response = await sendTabMessage(context.tabId, {
            action: 'restoreMechanismNetworkDraft',
            jsonText: restoreJsonText,
            expectedRevision: Number(mechanismWorkspaceDraft()?.revision || 0),
            restoreTarget: {
                authorizationToken: String(ensured.restoreAuthorization.token),
                current: {
                    workspaceId: paper.workspaceId,
                    workspaceGeneration: paper.workspaceGeneration,
                    canonicalUrl: paper.canonicalUrl,
                    contentHash: paper.contentHash
                },
                documentId: paper.documentId
            }
        });
        if (!response?.success || !response.draft) {
            throw new Error(response?.code || 'MECHANISM_NETWORK_IMPORT_FAILED');
        }
        stage = 'integrate';
        if (!isCurrentFigureWorkspaceEditContext(context) ||
            !integrateMechanismChainDraft(response.draft, context)) {
            throw new Error('MECHANISM_NETWORK_IMPORT_FAILED');
        }
        closeMechanismNetworkExportMenu();
        showStatus('图表梳理 JSON 已安全导入。', 'success');
        return response;
    } catch (error) {
        showStatus('图表梳理导入失败；文件必须属于当前论文且格式有效。', 'error');
        return {
            success: false,
            code: mechanismNetworkImportFailureCode(error),
            stage
        };
    }
}

function closeMechanismNetworkExportMenu({ restoreFocus = false } = {}) {
    const menu = document.getElementById('mechanismNetworkExportMenu');
    const button = document.getElementById('openMechanismExportMenu');
    if (menu) menu.hidden = true;
    button?.setAttribute('aria-expanded', 'false');
    if (restoreFocus) button?.focus();
}

function setupMechanismNetworkExportMenu() {
    const button = document.getElementById('openMechanismExportMenu');
    const menu = document.getElementById('mechanismNetworkExportMenu');
    const input = document.getElementById('importMechanismNetworkFile');
    if (!button || !menu || button.dataset.listenerAttached === 'true') return;
    button.dataset.listenerAttached = 'true';
    button.addEventListener('click', () => {
        const opening = menu.hidden;
        menu.hidden = !opening;
        button.setAttribute('aria-expanded', String(opening));
        if (opening) menu.querySelector('[role="menuitem"]')?.focus();
    });
    menu.querySelectorAll('[data-mechanism-export]').forEach(item => {
        item.addEventListener('click', () => void exportMechanismNetwork(
            item.dataset.mechanismExport
        ));
    });
    document.getElementById('importMechanismNetworkButton')?.addEventListener(
        'click', () => input?.click()
    );
    input?.addEventListener('change', () => {
        const file = input.files?.[0] || null;
        input.value = '';
        if (file) void importMechanismNetworkFile(file);
    });
    document.addEventListener('pointerdown', event => {
        if (menu.hidden || menu.contains(event.target) || button.contains(event.target)) return;
        closeMechanismNetworkExportMenu();
    });
    document.addEventListener('keydown', event => {
        if (event.key === 'Escape' && !menu.hidden) {
            event.preventDefault();
            closeMechanismNetworkExportMenu({ restoreFocus: true });
        }
    });
}

function integrateMechanismChainDraft(draft, context) {
    if (!draft || !currentWorkspaceSnapshot ||
        !isCurrentFigureWorkspaceEditContext(context)) return false;
    const revision = Number(draft.revision);
    const currentRevision = Number(mechanismWorkspaceDraft()?.revision ?? 0);
    if (!Number.isSafeInteger(revision) || revision < currentRevision) return false;
    currentWorkspaceSnapshot = {
        ...currentWorkspaceSnapshot,
        figureWorkspaceDraft: draft,
        figures: { ...(currentWorkspaceSnapshot.figures || {}), draft }
    };
    figureWorkspaceRenderCoordinator.request(currentWorkspaceSnapshot);
    return true;
}

function persistMechanismChainMutation(
    rawMutation,
    context = captureFigureWorkspaceEditContext()
) {
    const mutation = rawMutation && typeof rawMutation === 'object'
        ? { ...rawMutation } : {};
    const contextKey = mechanismChainContextKey(context);
    if (!mechanismChainSaveQueues.has(contextKey) && mechanismChainSaveQueues.size >= 16) {
        return Promise.resolve({
            success: false, code: 'FIGURE_WORKSPACE_SAVE_BUSY'
        });
    }
    const prior = mechanismChainSaveQueues.get(contextKey) || Promise.resolve();
    const operation = prior.catch(() => null).then(async () => {
        if (!isCurrentFigureWorkspaceEditContext(context)) {
            return { success: false, stale: true, code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED' };
        }
        const expectedRevision = Number(mechanismWorkspaceDraft()?.revision ?? 0);
        if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0) {
            throw new Error('FIGURE_WORKSPACE_REVISION_INVALID');
        }
        setMechanismChainSaveStatus('保存中…', 'pending');
        const response = await SciLLM.sendTabMessageWithRecovery(chrome, context.tabId, {
            action: 'updateFigureWorkspaceDraft',
            mutation: { ...mutation, expectedRevision },
            workspaceTarget: buildFigureWorkspaceEditTarget(context)
        });
        if (!response?.success || !response?.draft) {
            const error = new Error(response?.error || '机制链保存失败');
            error.code = response?.code || response?.error ||
                'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED';
            throw error;
        }
        if (!isCurrentFigureWorkspaceEditContext(context)) {
            return { ...response, stale: true };
        }
        integrateMechanismChainDraft(response.draft, context);
        setMechanismChainSaveStatus('已保存', 'saved');
        return response;
    }).catch(error => {
        if (isCurrentFigureWorkspaceEditContext(context)) {
            setMechanismChainSaveStatus('保存失败；请重试', 'error');
            showStatus('机制链保存失败；请重试。', 'error');
        }
        throw error;
    });
    const queued = operation.catch(() => null);
    mechanismChainSaveQueues.set(contextKey, queued);
    queued.finally(() => {
        if (mechanismChainSaveQueues.get(contextKey) === queued) {
            mechanismChainSaveQueues.delete(contextKey);
        }
    });
    return operation;
}

const mechanismActionCoordinator = createMechanismActionCoordinator({
    getEditorState() {
        return figureWorkspaceInlineEditController.getState();
    },
    flushEditor(reason) {
        return figureWorkspaceInlineEditController.flush(reason);
    },
    persist(mutation, context) {
        return persistMechanismChainMutation(mutation, context);
    },
    status: setMechanismChainSaveStatus
});

function safelyPersistMechanismChainMutation(
    mutation,
    context = captureFigureWorkspaceEditContext()
) {
    return Promise.resolve()
        .then(() => mechanismActionCoordinator.run(mutation, context))
        .catch(() => null);
}

function setMechanismNodeRemovalPending(nodeId, pending) {
    const id = String(nodeId || '');
    document.querySelectorAll('.workspace-mechanism-matrix-remove-node')
        .forEach(button => {
            if (button.dataset.nodeId !== id) return;
            button.disabled = pending;
            button.setAttribute('aria-busy', String(pending));
        });
}

const mechanismNodeRemovalCoordinator = createMechanismNodeRemovalCoordinator({
    remove(nodeId) {
        const context = captureFigureWorkspaceEditContext();
        return safelyPersistMechanismChainMutation({
            type: 'remove_mechanism_node', nodeId
        }, context);
    },
    setPending: setMechanismNodeRemovalPending
});

const mechanismChainSeedCoordinator = createMechanismChainSeedCoordinator({
    captureContext: captureFigureWorkspaceEditContext,
    keyForContext: mechanismChainContextKey,
    maximum: 8,
    seed(chain, context) {
        return persistMechanismChainMutation({
            type: 'seed_mechanism_chain', chain
        }, context);
    }
});

function mechanismWorkspaceId(prefix) {
    const random = Math.random().toString(36).slice(2, 10);
    return `${prefix}-${Date.now().toString(36)}-${random}`.slice(0, 80);
}

function createMechanismNetworkViewController(options) {
    options = options && typeof options === 'object' ? options : {};
    const getChain = typeof options.getChain === 'function'
        ? options.getChain : () => ({ nodes: [], edges: [] });
    const createId = typeof options.createId === 'function'
        ? options.createId : prefix => `${prefix}-${Date.now()}`;
    const runMutation = typeof options.runMutation === 'function'
        ? options.runMutation : async () => ({ success: false });
    const render = typeof options.render === 'function' ? options.render : () => undefined;
    const focusSet = typeof options.focusSet === 'function'
        ? options.focusSet : () => ({ nodeIds: new Set(), edgeIds: new Set() });
    const state = options.state && typeof options.state === 'object'
        ? options.state : { selectedNodeId: '', selectedEdgeId: '', focusEnabled: false };
    const safeId = value => typeof value === 'string' ? value.slice(0, 200) : '';
    const nodeIds = () => new Set((Array.isArray(getChain()?.nodes) ? getChain().nodes : [])
        .map(node => safeId(node?.id)).filter(Boolean));

    function clear() {
        state.selectedNodeId = '';
        state.selectedEdgeId = '';
        state.focusEnabled = false;
    }
    function selectNode(value) {
        const id = safeId(value);
        state.selectedNodeId = nodeIds().has(id) ? id : '';
        state.selectedEdgeId = '';
        render();
        return state.selectedNodeId;
    }
    function selectEdge(value) {
        const id = safeId(value);
        const edges = Array.isArray(getChain()?.edges) ? getChain().edges : [];
        state.selectedEdgeId = edges.some(edge => safeId(edge?.id) === id) ? id : '';
        state.selectedNodeId = '';
        render();
        return state.selectedEdgeId;
    }
    function toggleFocus() {
        if (!state.selectedNodeId && !state.selectedEdgeId) state.focusEnabled = false;
        else state.focusEnabled = !state.focusEnabled;
        render();
        return state.focusEnabled;
    }
    function focused() {
        if (!state.focusEnabled) return null;
        return focusSet(getChain(), {
            nodeId: state.selectedNodeId,
            edgeId: state.selectedEdgeId
        });
    }
    async function addBranch(fromNodeId, direction = 'downstream') {
        const from = safeId(fromNodeId);
        if (!nodeIds().has(from)) return {
            success: false, code: 'FIGURE_WORKSPACE_TARGET_INVALID'
        };
        const nodeId = safeId(createId('mechanism-node'));
        const edgeId = safeId(createId('mechanism-edge'));
        if (!nodeId || !edgeId) return {
            success: false, code: 'FIGURE_WORKSPACE_ID_INVALID'
        };
        const upstream = direction === 'upstream';
        return runMutation({
            type: 'add_mechanism_branch',
            node: { id: nodeId, label: '' },
            edge: {
                id: edgeId,
                from: upstream ? nodeId : from,
                to: upstream ? from : nodeId,
                label: '', polarity: 'neutral', panelEvidence: []
            }
        });
    }
    async function addConnection(rawFrom, rawTo, rawPolarity = 'neutral') {
        const from = safeId(rawFrom);
        const to = safeId(rawTo);
        const polarity = ['neutral', 'positive', 'negative'].includes(rawPolarity)
            ? rawPolarity : 'neutral';
        const allowed = nodeIds();
        if (!allowed.has(from) || !allowed.has(to)) return {
            success: false, code: 'FIGURE_WORKSPACE_TARGET_INVALID'
        };
        if (from === to && polarity === 'neutral') return {
            success: false, code: 'MECHANISM_NETWORK_SELF_LOOP_POLARITY_REQUIRED'
        };
        const id = safeId(createId('mechanism-edge'));
        if (!id) return { success: false, code: 'FIGURE_WORKSPACE_ID_INVALID' };
        return runMutation({
            type: 'add_mechanism_edge',
            edge: { id, from, to, label: '', polarity, panelEvidence: [] }
        });
    }
    return Object.freeze({
        clear, selectNode, selectEdge, toggleFocus, focused, addBranch, addConnection,
        getState: () => ({
            selectedNodeId: state.selectedNodeId,
            selectedEdgeId: state.selectedEdgeId,
            focusEnabled: state.focusEnabled === true
        })
    });
}

const mechanismNetworkViewController = createMechanismNetworkViewController({
    state: mechanismNetworkViewState,
    getChain: () => mechanismWorkspaceDraft()?.mechanismChain || { nodes: [], edges: [] },
    createId: mechanismWorkspaceId,
    runMutation: safelyPersistMechanismChainMutation,
    render: () => renderMechanismChainWorkspace(currentWorkspaceSnapshot),
    focusSet: (chain, selection) => SciLLM.mechanismNetworkFocusSet(chain, selection)
});

async function addMechanismNodeAfter(afterIndex = null) {
    const context = captureFigureWorkspaceEditContext();
    const draft = mechanismWorkspaceDraft();
    const nodes = Array.isArray(draft?.mechanismChain?.nodes)
        ? draft.mechanismChain.nodes.slice(0, 64) : [];
    const insertion = Number.isSafeInteger(afterIndex)
        ? Math.max(0, Math.min(nodes.length, afterIndex + 1)) : nodes.length;
    const nodeId = mechanismWorkspaceId('mechanism-node');
    return safelyPersistMechanismChainMutation({
        type: 'insert_mechanism_node', index: insertion,
        node: { id: nodeId, label: '' },
        edgeId: mechanismWorkspaceId('mechanism-edge')
    }, context);
}

async function removeMechanismNode(nodeId) {
    return mechanismNodeRemovalCoordinator.remove(nodeId);
}

async function reorderMechanismNode(nodeId, index) {
    const context = captureFigureWorkspaceEditContext();
    return safelyPersistMechanismChainMutation({
        type: 'reorder_mechanism_node', nodeId, index
    }, context);
}

function appendMechanismInlineField(parent, descriptor, value, label, className) {
    const target = createWorkspaceElement('div', className, String(value || ''));
    target.id = `mechanism-edit-${Math.random().toString(36).slice(2)}`;
    target.dataset.figureEditPath = figureWorkspaceEditDescriptorKey(descriptor);
    target.tabIndex = 0;
    target.setAttribute('role', 'button');
    const english = interfaceLanguage().startsWith('en');
    target.setAttribute('aria-label', `${label}${english ? ': ' : '：'}${
        t('双击或按 Enter 编辑')
    }`);
    if (!String(value || '').trim()) {
        target.textContent = t('双击填写');
        target.classList.add('workspace-figure-empty-value');
    }
    const edit = () => void openFigureWorkspaceInlineEditor(
        target, descriptor, String(value || ''), label, false
    );
    target.addEventListener('dblclick', edit);
    target.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            edit();
        }
    });
    parent.appendChild(target);
    return target;
}

function mechanismEvidenceClassFor(reference, optionsByIdentity) {
    return reference?.evidenceClass ||
        optionsByIdentity.get(`${reference.figureId}\u0000${reference.panelId}`)
            ?.evidenceClass || 'other';
}

function appendMechanismEdgeEvidence(
    parent, edge, options, optionsByIdentity, evidenceFigures
) {
    const evidenceRow = createWorkspaceElement('div', 'workspace-mechanism-evidence-row');
    const used = new Set();
    const displayCounts = new Map();
    options.forEach(option => displayCounts.set(
        option.displayId, (displayCounts.get(option.displayId) || 0) + 1
    ));
    const figureLabels = new Map(evidenceFigures.map(figure => [
        String(figure?.figureId || ''),
        String(figure?.figureLabel || figure?.figureId || '')
    ]));
    const optionLabel = option => displayCounts.get(option.displayId) > 1
        ? `${option.displayId} — ${figureLabels.get(option.figureId) || option.figureId} · ${option.figureId}`
        : option.displayId;
    (Array.isArray(edge?.panelEvidence) ? edge.panelEvidence : []).forEach((reference, index) => {
        const identity = `${reference.figureId}\u0000${reference.panelId}`;
        used.add(identity);
        const evidenceClass = mechanismEvidenceClassFor(reference, optionsByIdentity);
        const chip = createWorkspaceElement(
            'span', `workspace-mechanism-evidence is-${evidenceClass}`,
            reference.value || optionsByIdentity.get(identity)?.displayId || t('未解析 Panel')
        );
        const replacement = document.createElement('select');
        replacement.className = 'workspace-mechanism-evidence-replacement';
        replacement.setAttribute('aria-label', interfaceLanguage().startsWith('en')
            ? `Replace Panel evidence ${chip.textContent}`
            : `替换 Panel 证据 ${chip.textContent}`);
        options.slice(0, 512).forEach(option => {
            const optionIdentity = `${option.figureId}\u0000${option.panelId}`;
            const entry = new Option(optionLabel(option), optionIdentity);
            entry.selected = optionIdentity === identity;
            replacement.appendChild(entry);
        });
        replacement.addEventListener('change', () => {
            const option = optionsByIdentity.get(replacement.value);
            if (!option) return;
            const manualOverride = reference.evidenceClassSource === 'manual';
            void safelyPersistMechanismChainMutation({
                type: 'update_mechanism_edge_evidence', edgeId: edge.id, index,
                expectedFigureId: reference.figureId,
                expectedPanelId: reference.panelId,
                evidence: {
                    figureId: option.figureId, panelId: option.panelId,
                    evidenceClass: manualOverride
                        ? evidenceClass : (option.evidenceClass || 'other'),
                    evidenceClassSource: manualOverride ? 'manual' : 'inferred'
                }
            });
        });
        const classSelect = document.createElement('select');
        classSelect.className = 'workspace-mechanism-evidence-class';
        classSelect.setAttribute('aria-label', interfaceLanguage().startsWith('en')
            ? `Set the evidence class for ${chip.textContent}`
            : `设置 ${chip.textContent} 的证据类别`);
        [['充分性', 'sufficiency'], ['必要性', 'necessity'], ['其他', 'other']]
            .forEach(([label, value]) => {
                const entry = new Option(t(label), value);
                entry.selected = value === evidenceClass;
                classSelect.appendChild(entry);
            });
        classSelect.addEventListener('change', () => {
            if (!['sufficiency', 'necessity', 'other'].includes(classSelect.value)) return;
            void safelyPersistMechanismChainMutation({
                type: 'update_mechanism_edge_evidence', edgeId: edge.id, index,
                expectedFigureId: reference.figureId,
                expectedPanelId: reference.panelId,
                evidence: {
                    figureId: reference.figureId, panelId: reference.panelId,
                    evidenceClass: classSelect.value,
                    evidenceClassSource: 'manual'
                }
            });
        });
        const remove = createWorkspaceElement('button', '', '×');
        remove.type = 'button';
        remove.setAttribute('aria-label', interfaceLanguage().startsWith('en')
            ? `Remove Panel evidence ${chip.textContent}`
            : `移除 Panel 证据 ${chip.textContent}`);
        remove.addEventListener('click', () => void safelyPersistMechanismChainMutation({
            type: 'remove_mechanism_edge_evidence', edgeId: edge.id, index,
            expectedFigureId: reference.figureId,
            expectedPanelId: reference.panelId
        }));
        chip.appendChild(remove);
        const item = createWorkspaceElement('div', 'workspace-mechanism-evidence-item');
        item.append(chip, replacement, classSelect);
        evidenceRow.appendChild(item);
    });
    const select = document.createElement('select');
    select.className = 'workspace-mechanism-evidence-select';
    select.setAttribute('aria-label', t('添加联系的 Panel 证据'));
    select.appendChild(new Option(t('＋ 添加 Panel 证据'), ''));
    options.filter(option => !used.has(`${option.figureId}\u0000${option.panelId}`))
        .slice(0, 512).forEach(option => {
            select.appendChild(new Option(optionLabel(option),
                `${option.figureId}\u0000${option.panelId}`));
        });
    select.addEventListener('change', () => {
        const option = optionsByIdentity.get(select.value);
        select.value = '';
        if (!option) return;
        void safelyPersistMechanismChainMutation({
            type: 'add_mechanism_edge_evidence', edgeId: edge.id,
            evidence: {
                figureId: option.figureId, panelId: option.panelId,
                evidenceClass: option.evidenceClass || 'other',
                evidenceClassSource: 'inferred'
            }
        });
    });
    evidenceRow.appendChild(select);
    const manual = document.createElement('input');
    manual.type = 'text';
    manual.className = 'workspace-mechanism-manual-reference';
    manual.maxLength = 80;
    manual.placeholder = t('例如 2A 或 S2A');
    manual.setAttribute('aria-label', t('手工录入 Panel 证据编号'));
    const addManual = createWorkspaceElement('button', '', t('添加编号'));
    addManual.type = 'button';
    addManual.addEventListener('click', () => {
        try {
            const option = SciLLM.resolveMechanismPanelEvidenceReference(
                manual.value, evidenceFigures
            );
            manual.value = '';
            void safelyPersistMechanismChainMutation({
                type: 'add_mechanism_edge_evidence', edgeId: edge.id,
                evidence: {
                    figureId: option.figureId, panelId: option.panelId,
                    evidenceClass: option.evidenceClass || 'other',
                    evidenceClassSource: 'inferred'
                }
            });
        } catch (error) {
            const ambiguous = error?.code === 'FIGURE_WORKSPACE_PANEL_REFERENCE_AMBIGUOUS';
            setMechanismChainSaveStatus(
                t(ambiguous ? '该编号对应多个 Panel，请从列表选择' : '未找到唯一对应的 Panel'),
                'error'
            );
        }
    });
    evidenceRow.append(manual, addManual);
    parent.appendChild(evidenceRow);
}

async function seedMechanismChainFromCrossFigure(
    snapshot = currentWorkspaceSnapshot,
    {
        explicit = false,
        crossLogic = snapshot?.figures?.crossFigureLogic?.result,
        generationContext = null
    } = {}
) {
    const context = generationContext || captureFigureWorkspaceEditContext();
    if (!isCurrentFigureWorkspaceEditContext(context) ||
        !mechanismSnapshotMatchesContext(snapshot, context)) return {
        success: false, stale: true, code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED'
    };
    const current = mechanismWorkspaceDraft(snapshot)?.mechanismChain;
    if (!explicit && (current?.initialized === true ||
        (Array.isArray(current?.nodes) && current.nodes.length))) return null;
    const generated = SciLLM.mechanismChainFromCrossFigure(
        crossLogic, mechanismWorkspaceFigures(snapshot)
    );
    if (!generated.nodes.length) return null;
    const chain = {
        nodes: generated.nodes.map(node => ({ id: node.id, label: node.label })),
        edges: generated.edges.map(edge => ({
            id: edge.id, from: edge.sourceId, to: edge.targetId,
            label: edge.label, polarity: edge.polarity || 'neutral',
            panelEvidence: edge.panelEvidence.map(item => ({
                figureId: item.figureId, panelId: item.panelId,
                evidenceClass: item.evidenceClass || 'other',
                evidenceClassSource: 'inferred'
            }))
        })),
        generationIssues: generated.validationIssues
    };
    if (explicit) {
        return safelyPersistMechanismChainMutation({
            type: 'replace_mechanism_chain', chain
        }, context);
    }
    return mechanismChainSeedCoordinator.start(chain, context);
}

function openMechanismChainWorkspace() {
    switchWorkspaceView('mechanism');
    renderMechanismChainWorkspace(currentWorkspaceSnapshot);
    const draft = mechanismWorkspaceDraft()?.mechanismChain;
    const hasNodes = Array.isArray(draft?.nodes) && draft.nodes.length > 0;
    const initialized = draft?.initialized === true;
    const hasCrossLogic = Boolean(
        currentWorkspaceSnapshot?.figures?.crossFigureLogic?.result
    );
    const hasPendingResult = Boolean(
        currentWorkspaceSnapshot?.figures?.crossFigureLogic?.pendingResult
    );
    // Reopening a saved candidate is a read action. Do not silently start
    // another paid generation merely because the editable chain is empty.
    if (hasPendingResult) return;
    if (!initialized && !hasNodes && hasCrossLogic) {
        void seedMechanismChainFromCrossFigure(currentWorkspaceSnapshot).catch(() => null);
        return;
    }
    // Manual entry is local. AI generation requires its separate explicit action.
}

const mechanismNetworkMeasuredSizes = new Map();
const mechanismNetworkLayoutCache = SciLLM.createMechanismLayoutCache(input =>
    SciLLM.createMechanismNetworkLayout(input.chain, input.options), 12);
const mechanismNetworkMeasurementScheduler = SciLLM.createMechanismFrameScheduler(
    callback => requestAnimationFrame(callback)
);

function createMechanismNetworkResizeController(options) {
    options = options && typeof options === 'object' ? options : {};
    const schedule = typeof options.schedule === 'function'
        ? options.schedule : callback => requestAnimationFrame(callback);
    const cancel = typeof options.cancel === 'function'
        ? options.cancel : token => cancelAnimationFrame(token);
    const isActive = typeof options.isActive === 'function'
        ? options.isActive : () => false;
    const isEditing = typeof options.isEditing === 'function'
        ? options.isEditing : () => false;
    const render = typeof options.render === 'function' ? options.render : () => undefined;
    let width = 0;
    let pending = null;
    let generation = 0;

    function resize(rawWidth) {
        if (!isActive() || isEditing()) return false;
        const nextWidth = Math.max(0, Math.round(Number(rawWidth) || 0));
        if (!nextWidth || nextWidth === width) return false;
        width = nextWidth;
        generation += 1;
        const requestedGeneration = generation;
        if (pending !== null) cancel(pending);
        pending = schedule(() => {
            if (requestedGeneration !== generation) return;
            pending = null;
            if (!isActive() || isEditing()) return;
            render(width);
        });
        return true;
    }

    function clear() {
        generation += 1;
        if (pending !== null) cancel(pending);
        pending = null;
        width = 0;
    }

    return Object.freeze({
        resize, clear,
        getState: () => ({ pending: pending !== null, width })
    });
}

const mechanismNetworkResizeController = createMechanismNetworkResizeController({
    isActive: () => activeWorkspaceView === 'mechanism' &&
        document.querySelector('[data-workspace-view="mechanism"]')?.hidden === false,
    isEditing: () => figureWorkspaceRenderCoordinator.getState().editing,
    render: () => renderMechanismChainWorkspace(currentWorkspaceSnapshot)
});
let mechanismNetworkResizeRenderingSetup = false;

function setupMechanismNetworkResizeRendering() {
    if (mechanismNetworkResizeRenderingSetup) return;
    mechanismNetworkResizeRenderingSetup = true;
    window.addEventListener('resize', () => {
        const viewport = document.getElementById('mechanismNetworkViewport');
        mechanismNetworkResizeController.resize(viewport?.clientWidth);
    }, { passive: true });
}

function appendMechanismSvgMarkers(svg) {
    const namespace = 'http://www.w3.org/2000/svg';
    const defs = document.createElementNS(namespace, 'defs');
    [['neutral', '#52778b'], ['positive', '#b4413d'], ['negative', '#2866a5']]
        .forEach(([polarity, color]) => {
            const marker = document.createElementNS(namespace, 'marker');
            marker.id = `mechanism-arrow-${polarity}`;
            marker.setAttribute('viewBox', '0 0 10 10');
            marker.setAttribute('refX', '9');
            marker.setAttribute('refY', '5');
            marker.setAttribute('markerWidth', '7');
            marker.setAttribute('markerHeight', '7');
            marker.setAttribute('orient', 'auto-start-reverse');
            const arrow = document.createElementNS(namespace, 'path');
            arrow.setAttribute('d', 'M 0 0 L 10 5 L 0 10 z');
            arrow.setAttribute('fill', color);
            marker.appendChild(arrow);
            defs.appendChild(marker);
        });
    svg.appendChild(defs);
}

function mechanismNetworkCanvasScale(viewportWidth, layoutWidth) {
    const viewport = Math.max(0, Number(viewportWidth) || 0);
    const layout = Math.max(1, Number(layoutWidth) || 1);
    return Math.min(1, Math.max(0.78, viewport / layout));
}

function renderLegacyMechanismNetwork(chain, host, options = {}) {
    const namespace = 'http://www.w3.org/2000/svg';
    const viewportWidth = Math.max(
        320, Number(host?.parentElement?.clientWidth || host?.clientWidth) || 680
    );
    const revisionKey = Number.isSafeInteger(options.revision) ? options.revision : 0;
    const sizeMap = mechanismNetworkMeasuredSizes.get(revisionKey) || new Map();
    const layout = mechanismNetworkLayoutCache.get({
        chain,
        revision: revisionKey,
        options: {
            viewportWidth,
            nodeSizes: sizeMap,
            layoutPreferences: chain?.layoutPreferences
        }
    });
    const canvasScale = mechanismNetworkCanvasScale(viewportWidth, layout.width);
    const canvasWidth = Math.max(viewportWidth, Math.ceil(layout.width * canvasScale));
    const canvasHeight = Math.max(160, Math.ceil(layout.height * canvasScale));
    const svg = document.createElementNS(namespace, 'svg');
    svg.classList.add('workspace-mechanism-edge-layer');
    svg.setAttribute('viewBox', `0 0 ${layout.width} ${layout.height}`);
    svg.setAttribute('preserveAspectRatio', 'xMidYMin meet');
    svg.setAttribute('aria-hidden', 'true');
    appendMechanismSvgMarkers(svg);
    const nodeLayer = createWorkspaceElement('div', 'workspace-mechanism-node-layer');
    const edgeLabelLayer = createWorkspaceElement(
        'div', 'workspace-mechanism-edge-label-layer'
    );
    const nodesById = new Map((Array.isArray(chain?.nodes) ? chain.nodes : [])
        .map(node => [node.id, node]));
    const edgesById = new Map((Array.isArray(chain?.edges) ? chain.edges : [])
        .map(edge => [edge.id, edge]));
    const viewState = mechanismNetworkViewController.getState();
    const focus = mechanismNetworkViewController.focused();

    layout.edges.forEach(edgeLayout => {
        const edge = edgesById.get(edgeLayout.id);
        if (!edge) return;
        const polarity = ['positive', 'negative'].includes(edge.polarity)
            ? edge.polarity : 'neutral';
        const visible = document.createElementNS(namespace, 'path');
        visible.classList.add(
            'workspace-mechanism-edge-visible', `is-${polarity}`,
            ...(edgeLayout.feedback ? ['is-feedback'] : []),
            ...(edgeLayout.selfLoop ? ['is-self-loop'] : []),
            ...(viewState.selectedEdgeId === edge.id ? ['is-selected'] : []),
            ...(focus && !focus.edgeIds.has(edge.id) ? ['is-dimmed'] : [])
        );
        visible.setAttribute('d', edgeLayout.path);
        visible.setAttribute('marker-end', `url(#mechanism-arrow-${polarity})`);
        const hit = document.createElementNS(namespace, 'path');
        hit.classList.add('workspace-mechanism-edge-hit');
        hit.dataset.edgeId = edge.id;
        hit.setAttribute('d', edgeLayout.hitPath || edgeLayout.path);
        hit.addEventListener('click', () =>
            mechanismNetworkViewController.selectEdge(edge.id));
        svg.append(visible, hit);

        const label = createWorkspaceElement(
            'section', `workspace-mechanism-edge-label is-${polarity}`
        );
        label.dataset.edgeId = edge.id;
        label.classList.toggle('is-selected', viewState.selectedEdgeId === edge.id);
        label.classList.toggle('is-dimmed', Boolean(focus && !focus.edgeIds.has(edge.id)));
        label.style.left = `${edgeLayout.labelX}px`;
        label.style.top = `${edgeLayout.labelY}px`;
        label.tabIndex = 0;
        label.setAttribute('role', 'button');
        label.setAttribute('aria-label', SciLLM.mechanismEdgeAccessibleName({
            fromLabel: nodesById.get(edge.from)?.label?.value || edge.from,
            toLabel: nodesById.get(edge.to)?.label?.value || edge.to,
            polarity,
            evidenceCount: Array.isArray(edge.panelEvidence)
                ? edge.panelEvidence.length : 0
        }));
        appendMechanismInlineField(label, {
            scope: 'mechanism-edge', edgeId: edge.id, field: 'label'
        }, edge.label?.value, '机制联系', 'workspace-mechanism-edge-text');
        if (polarity !== 'neutral') {
            label.appendChild(createWorkspaceElement(
                'span', 'workspace-mechanism-polarity-label',
                polarity === 'negative' ? '负反馈' : '正反馈'
            ));
        }
        label.addEventListener('click', event => {
            if (event.target.closest(
                '[data-figure-edit-path], textarea, input, select, button'
            )) return;
            mechanismNetworkViewController.selectEdge(edge.id);
        });
        edgeLabelLayer.appendChild(label);
    });

    layout.nodes.forEach((nodeLayout, index) => {
        const node = nodesById.get(nodeLayout.id);
        if (!node) return;
        const card = createWorkspaceElement('article', 'workspace-mechanism-node');
        card.dataset.nodeId = node.id;
        card.classList.toggle('is-selected', viewState.selectedNodeId === node.id);
        card.classList.toggle('is-dimmed', Boolean(focus && !focus.nodeIds.has(node.id)));
        card.style.left = `${nodeLayout.x}px`;
        card.style.top = `${nodeLayout.y}px`;
        card.style.width = `${nodeLayout.width}px`;
        card.style.minHeight = `${nodeLayout.height}px`;
        appendMechanismInlineField(card, {
            scope: 'mechanism-node', nodeId: node.id, field: 'label'
        }, node.label?.value, `机制节点 ${index + 1}`, 'workspace-mechanism-node-label');
        const actions = createWorkspaceElement('div', 'workspace-mechanism-node-actions');
        const insert = createWorkspaceElement('button', '', '添加分支');
        const remove = createWorkspaceElement('button', 'is-danger', '删除');
        [insert, remove].forEach(button => { button.type = 'button'; });
        insert.addEventListener('click', () => void mechanismNetworkViewController
            .addBranch(node.id, 'downstream'));
        remove.addEventListener('click', () => void removeMechanismNode(node.id));
        actions.append(insert, remove);
        card.appendChild(actions);
        card.addEventListener('click', event => {
            if (event.target.closest(
                '[data-figure-edit-path], textarea, input, select, button'
            )) return;
            mechanismNetworkViewController.selectNode(node.id);
        });
        nodeLayer.appendChild(card);
    });

    [svg, nodeLayer, edgeLabelLayer].forEach(layer => {
        layer.style.width = `${layout.width}px`;
        layer.style.height = `${layout.height}px`;
        layer.style.transform = `scale(${canvasScale})`;
        layer.style.transformOrigin = 'top left';
    });
    host.replaceChildren(svg, nodeLayer, edgeLabelLayer);
    host.style.setProperty('--mechanism-canvas-width', `${canvasWidth}px`);
    host.style.setProperty('--mechanism-canvas-height', `${canvasHeight}px`);
    host.style.height = `${canvasHeight}px`;

    if (!options.measured && typeof requestAnimationFrame === 'function') {
        mechanismNetworkMeasurementScheduler.request(() => {
            if (!host.isConnected) return;
            const measured = new Map();
            let changed = false;
            nodeLayer.querySelectorAll('.workspace-mechanism-node').forEach(card => {
                const id = card.dataset.nodeId;
                const width = Math.ceil(card.scrollWidth || card.offsetWidth || 0);
                const height = Math.ceil(card.scrollHeight || card.offsetHeight || 0);
                if (!id || !width || !height) return;
                measured.set(id, { width, height });
                const previous = sizeMap.get(id);
                if (!previous || Math.abs(previous.width - width) > 2 ||
                    Math.abs(previous.height - height) > 2) changed = true;
            });
            if (!changed) return;
            mechanismNetworkMeasuredSizes.set(revisionKey, measured);
            while (mechanismNetworkMeasuredSizes.size > 8) {
                mechanismNetworkMeasuredSizes.delete(
                    mechanismNetworkMeasuredSizes.keys().next().value
                );
            }
            renderLegacyMechanismNetwork(chain, host, { ...options, measured: true });
        });
    }
    return layout;
}

let mechanismMermaidGeneration = 0;

function createMechanismMermaidFocusHandoff(options) {
    options = options && typeof options === 'object' ? options : {};
    const captureContext = typeof options.captureContext === 'function'
        ? options.captureContext : () => null;
    const isContextCurrent = typeof options.isContextCurrent === 'function'
        ? options.isContextCurrent : () => false;
    let pending = null;
    const safeId = value => typeof value === 'string'
        ? Array.from(value).slice(0, 200).join('') : '';

    function queue(kind, rawId, sourceGeneration) {
        const id = safeId(rawId);
        const generation = Number(sourceGeneration);
        if (!['node', 'edge'].includes(kind) || !id ||
            !Number.isSafeInteger(generation) || generation < 0 ||
            generation >= Number.MAX_SAFE_INTEGER) return false;
        pending = Object.freeze({
            kind,
            id,
            renderGeneration: generation + 1,
            context: captureContext()
        });
        return true;
    }

    function cancel(kind, rawId, renderGeneration) {
        const id = safeId(rawId);
        if (!pending || pending.kind !== kind || pending.id !== id ||
            pending.renderGeneration !== Number(renderGeneration)) return false;
        pending = null;
        return true;
    }

    function restore(diagram, renderGeneration) {
        if (!pending) return false;
        const generation = Number(renderGeneration);
        if (!Number.isSafeInteger(generation) || generation !== pending.renderGeneration) {
            if (Number.isSafeInteger(generation) && generation > pending.renderGeneration) {
                pending = null;
            }
            return false;
        }
        const target = pending;
        pending = null;
        if (!isContextCurrent(target.context) || !diagram?.isConnected) return false;
        const datasetKey = target.kind === 'node'
            ? 'mechanismNodeId' : 'mechanismEdgeId';
        const candidates = diagram.querySelectorAll(
            target.kind === 'node' ? '[data-mechanism-node-id]'
                : '[data-mechanism-edge-id]'
        );
        const element = [...candidates].find(candidate =>
            candidate.dataset?.[datasetKey] === target.id);
        if (!element?.isConnected || typeof element.focus !== 'function') return false;
        element.focus();
        return true;
    }

    return Object.freeze({ queue, cancel, restore });
}

const mechanismMermaidFocusHandoff = createMechanismMermaidFocusHandoff({
    captureContext: () => capturePanelContext(),
    isContextCurrent: context => isCurrentPanelContext(context)
});

function interfaceLanguage() {
    return SciLLM.normalizeInterfaceLanguage?.(
        llmSettingsState?.settings?.language || 'zh-CN'
    ) || 'zh-CN';
}

function t(value) {
    return SciLLM.translateInterfaceText?.(value, interfaceLanguage()) || String(value || '');
}

const MECHANISM_GENERATION_STAGE_LABELS = Object.freeze({
    collecting_panel_evidence: '正在收集 Panel 证据',
    canonicalizing_nodes: '正在规范化机制节点',
    mapping_claim_relations: '正在映射主张关系',
    assembling_graph: '正在组装机制图',
    repairing_unresolved: '正在修复未解析证据',
    validating_final_result: '正在验证最终结果'
});

function createLiveMechanismGenerationUiController(tabId = null) {
    const targetTabId = Number(tabId);
    return createMechanismGenerationUiController({
        normalizeEvidenceFirstVersions: SciLLM.normalizeEvidenceFirstVersions,
        cancel(operation) {
            if (!Number.isSafeInteger(targetTabId) || targetTabId < 0 || !operation) {
                return Promise.resolve({ success: false, code: 'MECHANISM_CANCEL_FAILED' });
            }
            return sendTabMessage(targetTabId, {
                action: 'cancelCrossFigureLogicWithLLM',
                operationId: operation.operationId,
                operationEpoch: operation.epoch,
                ...operation.binding
            });
        }
    });
}

function stopMechanismGenerationElapsedTimer() {
    clearInterval(mechanismGenerationElapsedTimer);
    mechanismGenerationElapsedTimer = null;
}

function ensureMechanismGenerationElapsedTimer() {
    if (mechanismGenerationElapsedTimer) return;
    mechanismGenerationElapsedTimer = setInterval(() => {
        const presentation = mechanismGenerationUiController.presentation();
        renderMechanismGenerationStatus();
        if (!presentation.active) stopMechanismGenerationElapsedTimer();
    }, 1000);
}

function mechanismGenerationStatusLabel(presentation) {
    if (presentation.stillProcessing) {
        return t(`模型仍在处理（已等待 ${presentation.elapsedSeconds} 秒）`);
    }
    if (presentation.status === 'queued') return t('机制链任务排队中');
    if (presentation.status === 'working') return t('机制链生成处理中');
    if (presentation.status === 'retrying') return t('机制链生成正在重试');
    if (presentation.status === 'cancelling') return t('正在取消机制链生成');
    if (presentation.status === 'cancelled') return t('机制链生成已取消');
    if (presentation.status === 'needs_review') return t('机制链需要人工核验');
    if (presentation.status === 'revision_conflict' ||
        presentation.code === 'MECHANISM_REVISION_CONFLICT') {
        return t('机制链工作区版本冲突');
    }
    if (presentation.code === 'MECHANISM_OPERATION_DEADLINE_EXCEEDED') {
        return t('机制链生成超时');
    }
    if (presentation.code === 'MECHANISM_PROVIDER_REQUEST_BUDGET_EXCEEDED') {
        return t('机制链请求额度已用尽');
    }
    if (presentation.status === 'failed') return t('机制链生成失败');
    if (presentation.status === 'complete') return t('机制链生成完成');
    return '';
}

function renderMechanismGenerationStatus() {
    const host = document.getElementById('mechanismGenerationStatus');
    const stage = document.getElementById('mechanismGenerationStage');
    const detail = document.getElementById('mechanismGenerationDetail');
    const cancel = document.getElementById('cancelMechanismGeneration');
    if (!host || !stage || !detail || !cancel) return;
    const presentation = mechanismGenerationUiController.presentation();
    const visible = presentation.status !== 'idle';
    host.hidden = !visible;
    host.dataset.status = presentation.status;
    host.setAttribute('aria-busy', String(presentation.active));
    stage.textContent = t(MECHANISM_GENERATION_STAGE_LABELS[presentation.stage] || '');
    const progressText = presentation.total > 0
        ? ` ${Math.min(presentation.completed, presentation.total)}/${presentation.total}` : '';
    detail.textContent = `${mechanismGenerationStatusLabel(presentation)}${progressText}`.trim();
    cancel.hidden = !presentation.active;
    cancel.disabled = !presentation.cancellable;
    cancel.textContent = presentation.status === 'cancelling'
        ? t('正在取消机制链生成') : t('取消机制链生成');
    crossFigureLogicRunning = presentation.active;
    document.querySelectorAll('[data-mechanism-generate]').forEach(button => {
        button.disabled = presentation.active;
        button.setAttribute('aria-busy', String(presentation.active));
    });
    updateFigureButton();
    if (presentation.active) ensureMechanismGenerationElapsedTimer();
    else stopMechanismGenerationElapsedTimer();
    if (visible) synchronizeOperationNotice(host,
        presentation.operation?.operationId || `${presentation.stage}:${presentation.status}`,
        !presentation.active, presentation.status === 'complete' ? 3200 : 6000);
}

async function cancelActiveMechanismGeneration() {
    const operationId = mechanismGenerationUiController.presentation().operation?.operationId;
    if (!operationId) return { success: true, cancelled: false };
    const pending = mechanismGenerationUiController.cancel();
    renderMechanismGenerationStatus();
    const response = await pending;
    if (mechanismGenerationUiController.presentation().operation?.operationId === operationId) {
        renderMechanismGenerationStatus();
    }
    return response;
}

function restoreMechanismGenerationFromLiveSnapshot(
    snapshot,
    { tabId = activePanelTabContext.tabId, documentId = '' } = {}
) {
    const targetTabId = Number(tabId);
    const liveDocumentId = String(documentId || preparedDocumentState?.documentId ||
        manualAnnotationState?.documentId || '');
    if (!Number.isSafeInteger(targetTabId) || targetTabId < 0) {
        return false;
    }
    const candidate = createLiveMechanismGenerationUiController(targetTabId);
    if (!restoreMechanismGenerationControllerFromWorkspaceSnapshot(
        candidate, snapshot, liveDocumentId, SciLLM
    )) return false;
    const restoredOperationId = candidate.presentation().operation?.operationId;
    const current = mechanismGenerationUiController.presentation();
    if (current.operation) {
        if (Number(activeMechanismGenerationTabId) !== targetTabId ||
            current.operation?.operationId !== restoredOperationId) return false;
        if (!restoreMechanismGenerationControllerFromWorkspaceSnapshot(
            mechanismGenerationUiController, snapshot, liveDocumentId, SciLLM
        )) return false;
        renderMechanismGenerationStatus();
        return true;
    }
    stopMechanismGenerationElapsedTimer();
    activeMechanismGenerationTabId = targetTabId;
    mechanismGenerationUiController = candidate;
    renderMechanismGenerationStatus();
    return true;
}

function replaceMechanismGenerationUiController(tabId = null) {
    const previous = mechanismGenerationUiController;
    if (previous.presentation().active) void previous.cancel();
    stopMechanismGenerationElapsedTimer();
    activeMechanismGenerationTabId = Number.isSafeInteger(Number(tabId))
        ? Number(tabId) : null;
    mechanismGenerationUiController = createLiveMechanismGenerationUiController(tabId);
    renderMechanismGenerationStatus();
    return mechanismGenerationUiController;
}

function mechanismMatrixNodeAxisModel(matrix) {
    const nodes = Array.isArray(matrix?.nodes) ? matrix.nodes.slice(0, 64) : [];
    return {
        columns: nodes,
        rows: nodes,
        orientation: 'column-source-row-target'
    };
}

function createMechanismMatrixCellEditorController(options) {
    options = options && typeof options === 'object' ? options : Object.create(null);
    const captureContext = typeof options.captureContext === 'function'
        ? options.captureContext : () => null;
    const isContextCurrent = typeof options.isContextCurrent === 'function'
        ? options.isContextCurrent : () => false;
    const getPanel = typeof options.getPanel === 'function' ? options.getPanel : () => null;
    const resolveEvidence = typeof options.resolveEvidence === 'function'
        ? options.resolveEvidence : null;
    const createId = typeof options.createId === 'function' ? options.createId : () => '';
    const mutate = typeof options.mutate === 'function'
        ? options.mutate : async () => ({ success: false });
    const refresh = typeof options.refresh === 'function'
        ? options.refresh : async () => null;
    const setPending = typeof options.setPending === 'function'
        ? options.setPending : () => undefined;
    const restoreFocus = typeof options.restoreFocus === 'function'
        ? options.restoreFocus : () => undefined;
    let active = null;
    let pending = false;
    const safeId = value => typeof value === 'string' ? value.slice(0, 200) : '';
    const safeClass = value => ['sufficiency', 'necessity', 'other'].includes(value)
        ? value : '';
    const failure = code => ({ success: false, code });

    function open(cell) {
        const sourceId = safeId(cell?.sourceId);
        const targetId = safeId(cell?.targetId);
        if (!sourceId || !targetId) return null;
        const edgePolarities = Object.create(null);
        const polarityDescriptors = cell?.edgePolarities && typeof cell.edgePolarities === 'object'
            ? Object.getOwnPropertyDescriptors(cell.edgePolarities) : {};
        Object.entries(polarityDescriptors).slice(0, 64).forEach(([edgeId, descriptor]) => {
            if (!Object.hasOwn(descriptor, 'value')) return;
            const id = safeId(edgeId);
            const polarity = descriptor.value;
            if (id && ['neutral', 'positive', 'negative'].includes(polarity)) {
                edgePolarities[id] = polarity;
            }
        });
        active = Object.freeze({
            sourceId,
            targetId,
            sourceLabel: String(cell?.sourceLabel || '').slice(0, 200),
            targetLabel: String(cell?.targetLabel || '').slice(0, 200),
            edgeId: safeId(cell?.edgeId),
            edgeIds: Object.freeze([...new Set([
                safeId(cell?.edgeId),
                ...(Array.isArray(cell?.edgeIds) ? cell.edgeIds.map(safeId) : [])
            ].filter(Boolean))].slice(0, 64)),
            edgePolarities: Object.freeze(edgePolarities),
            focusKey: String(cell?.focusKey || '').slice(0, 401),
            context: captureContext()
        });
        return active;
    }

    async function run(mutationOrFactory) {
        const session = active;
        if (!session || !isContextCurrent(session.context)) {
            return failure('FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED');
        }
        if (pending) return failure('FIGURE_WORKSPACE_MATRIX_CELL_PENDING');
        pending = true;
        setPending(true);
        try {
            const buildMutation = () => typeof mutationOrFactory === 'function'
                ? mutationOrFactory() : mutationOrFactory;
            let mutation = buildMutation();
            if (!mutation) return failure('FIGURE_WORKSPACE_PANEL_CONTEXT_STALE');
            let response;
            try {
                response = await mutate(mutation, session.context);
                if (response?.code === 'FIGURE_WORKSPACE_REVISION_CONFLICT') {
                    const error = new Error(response.code);
                    error.code = response.code;
                    throw error;
                }
            } catch (error) {
                if (error?.code !== 'FIGURE_WORKSPACE_REVISION_CONFLICT') throw error;
                await refresh(session.context);
                if (!isContextCurrent(session.context)) {
                    return failure('FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED');
                }
                mutation = buildMutation();
                if (!mutation) return failure('FIGURE_WORKSPACE_PANEL_CONTEXT_STALE');
                response = await mutate(mutation, session.context);
            }
            if (!isContextCurrent(session.context) || response?.stale) {
                return failure('FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED');
            }
            if (response?.success) restoreFocus(session.focusKey);
            return response || failure('FIGURE_WORKSPACE_DRAFT_SAVE_FAILED');
        } catch (error) {
            return failure(String(error?.code || 'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED'));
        } finally {
            pending = false;
            setPending(false);
        }
    }

    function activeEvidence(item, { requirePanel = true } = {}) {
        const edgeId = safeId(item?.edgeId);
        if (!active || !active.edgeIds.includes(edgeId) ||
            !Number.isSafeInteger(item?.index) || item.index < 0) return null;
        const figureId = safeId(item.figureId);
        const panelId = safeId(item.panelId);
        if (!figureId || !panelId) return null;
        if (requirePanel && !getPanel(`${figureId}\u0000${panelId}`)) return null;
        return { edgeId, figureId, panelId };
    }

    function currentEvidence(item, options = {}) {
        const immutable = activeEvidence(item, options);
        if (!immutable) return null;
        if (!resolveEvidence) return { ...immutable, index: item.index };
        const resolved = resolveEvidence(
            immutable.edgeId, immutable.figureId, immutable.panelId
        );
        if (!resolved || safeId(resolved.edgeId) !== immutable.edgeId ||
            safeId(resolved.figureId) !== immutable.figureId ||
            safeId(resolved.panelId) !== immutable.panelId ||
            !Number.isSafeInteger(resolved.index) || resolved.index < 0) return null;
        return { ...immutable, index: resolved.index };
    }

    function add(panelKey, evidenceClass, polarity = 'neutral', selectedEdgeId = '') {
        if (!active || !isContextCurrent(active.context)) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED'));
        }
        const panel = getPanel(String(panelKey || '').slice(0, 300));
        if (!panel) return Promise.resolve(failure('FIGURE_WORKSPACE_PANEL_CONTEXT_STALE'));
        const normalizedClass = safeClass(evidenceClass);
        if (!normalizedClass) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_VALUE_INVALID'));
        }
        const selfLoop = active.sourceId === active.targetId;
        const normalizedPolarity = ['positive', 'negative'].includes(polarity)
            ? polarity : 'neutral';
        const requestedEdgeId = safeId(selectedEdgeId) || active.edgeId;
        if (requestedEdgeId && !active.edgeIds.includes(requestedEdgeId)) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_TARGET_INVALID'));
        }
        const existingPolarity = requestedEdgeId
            ? active.edgePolarities[requestedEdgeId] : '';
        if (selfLoop && requestedEdgeId &&
            !['positive', 'negative'].includes(existingPolarity)) {
            return Promise.resolve(failure('MECHANISM_NETWORK_SELF_LOOP_POLARITY_REQUIRED'));
        }
        if (selfLoop && !requestedEdgeId && normalizedPolarity === 'neutral') {
            return Promise.resolve(failure('MECHANISM_NETWORK_SELF_LOOP_POLARITY_REQUIRED'));
        }
        const edgeId = requestedEdgeId || safeId(createId('mechanism-edge'));
        if (!edgeId) return Promise.resolve(failure('FIGURE_WORKSPACE_ID_INVALID'));
        return run({
            type: 'upsert_mechanism_cell_evidence',
            edgeId,
            edge: {
                from: active.sourceId,
                to: active.targetId,
                polarity: selfLoop
                    ? (existingPolarity || normalizedPolarity) : 'neutral'
            },
            evidence: {
                figureId: safeId(panel.figureId), panelId: safeId(panel.panelId),
                evidenceClass: normalizedClass, evidenceClassSource: 'manual'
            }
        });
    }

    function alias(item, value) {
        const evidence = activeEvidence(item);
        if (!evidence || typeof value !== 'string') {
            return Promise.resolve(failure('FIGURE_WORKSPACE_PANEL_CONTEXT_STALE'));
        }
        return run({
            type: 'set_mechanism_panel_alias',
            figureId: evidence.figureId, panelId: evidence.panelId,
            value: Array.from(value).slice(0, 80).join('')
        });
    }

    function setClass(item, evidenceClass) {
        const normalizedClass = safeClass(evidenceClass);
        if (!normalizedClass) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_VALUE_INVALID'));
        }
        return run(() => {
            const evidence = currentEvidence(item);
            return evidence ? {
            type: 'update_mechanism_edge_evidence', edgeId: evidence.edgeId,
            index: evidence.index,
            expectedFigureId: evidence.figureId, expectedPanelId: evidence.panelId,
            evidence: { figureId: evidence.figureId, panelId: evidence.panelId,
                evidenceClass: normalizedClass,
                evidenceClassSource: 'manual' }
            } : null;
        });
    }

    function replace(item, panelKey, evidenceClass) {
        const replacement = getPanel(String(panelKey || '').slice(0, 300));
        const normalizedClass = safeClass(evidenceClass);
        if (!replacement) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_PANEL_CONTEXT_STALE'));
        }
        if (!normalizedClass) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_VALUE_INVALID'));
        }
        return run(() => {
            const current = currentEvidence(item, { requirePanel: false });
            return current ? {
            type: 'update_mechanism_edge_evidence', edgeId: current.edgeId,
            index: current.index,
            expectedFigureId: current.figureId, expectedPanelId: current.panelId,
            evidence: {
                figureId: safeId(replacement.figureId),
                panelId: safeId(replacement.panelId),
                evidenceClass: normalizedClass, evidenceClassSource: 'manual'
            }
            } : null;
        });
    }

    function remove(item) {
        if (!activeEvidence(item, { requirePanel: false })) {
            return Promise.resolve(failure('FIGURE_WORKSPACE_VALUE_INVALID'));
        }
        return run(() => {
            const current = currentEvidence(item, { requirePanel: false });
            return current ? {
                type: 'remove_mechanism_edge_evidence', edgeId: current.edgeId,
                index: current.index,
                expectedFigureId: current.figureId, expectedPanelId: current.panelId
            } : null;
        });
    }

    return Object.freeze({ open, add, alias, setClass, replace, remove,
        getState: () => ({ active, pending }) });
}

function formatMechanismRelationUiText(edge, language = interfaceLanguage()) {
    const english = String(language || '').toLowerCase().startsWith('en');
    let raw = '';
    let generatedLabel = edge?.labelSource === 'generated';
    try {
        const label = edge?.label;
        raw = typeof label === 'string' ? label
            : typeof label?.value === 'string' ? label.value : '';
        if (label && typeof label === 'object' && label.humanReviewed === false) {
            generatedLabel = true;
        } else if (label && typeof label === 'object' && label.humanReviewed === true) {
            generatedLabel = false;
        }
    } catch (_) { raw = ''; }
    raw = Array.from(raw.normalize('NFKC').replace(/\s+/gu, ' ').trim())
        .slice(0, 180).join('');
    const token = raw.toLowerCase();
    const generatedTokens = new Set(['associated with', 'decreases', 'increases', 'affects']);
    if (raw && (!generatedLabel || !generatedTokens.has(token))) return raw;
    if (edge?.relationKind === 'correlative' || edge?.lineStyle === 'dashed' ||
        token === 'associated with') return english ? 'associated with' : '相关';
    if (edge?.polarity === 'negative' || token === 'decreases') {
        return english ? 'decreases' : '抑制';
    }
    if (edge?.polarity === 'positive' || token === 'increases') {
        return english ? 'increases' : '促进';
    }
    return english ? 'affects' : '影响';
}

function formatMechanismEvidenceCodeLabel(code, translate = t) {
    const labels = {
        S: '充分性', N: '必要性', R: '救援实验', E: '上位性', I: '定向干预',
        A: '相关性', O: '观察 / 定位', '0': '阴性结果', C: '反证',
        '?': '结论不明 / 未知'
    };
    const label = labels[typeof code === 'string' ? code : '?'] || labels['?'];
    return typeof translate === 'function' ? translate(label) : label;
}

function formatMechanismAuditReason(reason, translate = t) {
    const labels = {
        incompatible_panel_claims: 'Panel 内的主张互不相容',
        unqualified_causal_test: '因果检验不满足纳入条件',
        missing_node_evidence: '缺少可定位的节点证据',
        unsupported_composite_relation: '复合关系暂不支持',
        self_relation_not_allowed: '不允许自指关系',
        missing_audit_placement: '缺少审计定位',
        missing_evidence_record: '缺少证据记录',
        unmapped_relation_term: '关系术语未能映射',
        missing_relation_mapping: '缺少关系映射',
        source_backed_schematic: '来源支持的示意图，不作为机制证据'
    };
    const raw = typeof reason === 'string'
        ? Array.from(reason.replace(/[\u0000-\u001F\u007F]/gu, ' '))
            .slice(0, 240).join('').trim()
        : '';
    const label = labels[raw];
    return label && typeof translate === 'function' ? translate(label) : (label || raw);
}

function formatMechanismMatrixUiText(key, values) {
    values = values && typeof values === 'object' ? values : Object.create(null);
    const english = interfaceLanguage().startsWith('en');
    const unnamed = english ? 'Unnamed node' : '未填写节点';
    const rawOrFallback = value => typeof value === 'string' && value
        ? value : unnamed;
    const source = rawOrFallback(values.source);
    const target = rawOrFallback(values.target);
    const name = rawOrFallback(values.name);
    const evidenceClass = values.evidenceClass === 'sufficiency'
        ? (english ? 'Sufficiency evidence' : '充分性证据')
        : (values.evidenceClass === 'necessity'
            ? (english ? 'Necessity evidence' : '必要性证据')
            : (english ? 'Related / other evidence' : '其他或相关性证据'));
    const polarity = ['positive', 'increases'].includes(values.polarity)
        ? (english ? 'Positive / promoting' : '正向/促进')
        : (['negative', 'decreases'].includes(values.polarity)
            ? (english ? 'Negative / inhibitory' : '负向/抑制')
            : (english ? 'Neutral' : '中性'));
    const index = Number.isSafeInteger(values.index) && values.index > 0
        ? values.index : 1;
    const safeText = (value, maximum = 200) => typeof value === 'string'
        ? Array.from(value.normalize('NFKC').replace(/\s+/g, ' ').trim())
            .slice(0, maximum).join('')
        : '';
    const relationLabel = safeText(values.relationLabel) || polarity;
    const relationId = safeText(values.relationId) || (english ? 'unknown' : '未知');
    const relationKind = values.relationKind === 'correlative'
        ? (english ? 'Correlative relation' : '相关联系')
        : (english ? 'Causal relation' : '因果联系');
    const contested = values.contested === true
        ? (english ? 'Contested relation' : '争议联系') : '';
    const relationBadge = [
        english ? `Relation ${index}` : `第 ${index} 条联系`,
        relationLabel, relationKind, polarity, contested
    ].filter(Boolean).join(' · ');
    const claimCode = ['S', 'N', 'R', 'E', 'I', 'A', 'O', '0', 'C', '?']
        .includes(values.claimCode) ? values.claimCode : '?';
    const auditDisposition = values.mappingStatus === 'unique'
        ? (english ? 'editable relationship evidence' : '可编辑的关系证据')
        : values.placementKind === 'node_only'
            ? (english ? 'node-only placement, view only' : '仅节点定位，只读')
            : values.mappingStatus === 'ambiguous'
                ? (english ? 'ambiguous mapping, view only' : '定位存在歧义，只读')
                : (english ? 'unresolved mapping, view only' : '无法定位编辑对象，只读');
    const viewReason = values.placementKind === 'node_only'
        ? (english ? 'Node-only evidence with no owner relation; view only'
            : '仅定位到节点，未绑定所属联系；只读')
        : values.mappingStatus === 'ambiguous'
            ? (english ? 'Multiple candidate relations; view only'
                : '存在多个候选联系；只读')
            : (english ? 'No verified owner relation; view only'
                : '未找到可验证的所属联系；只读');
    const templates = english ? {
        cellHeading: `Evidence cell: ${source} → ${target}`,
        editCell: `Edit Panel evidence from ${source} to ${target}`,
        deleteNode: `Delete mechanism node: ${name}`,
        panelName: `Panel name: ${name}`,
        replacePanel: `Replace Panel: ${name}`,
        evidenceClass: `Evidence class: ${name}`,
        ownerEdge: `Link ${index} (${polarity})`,
        relationBadge,
        originalDisplayIdLabel: 'Original display ID',
        figureIdLabel: 'Figure ID',
        panelIdLabel: 'Panel ID',
        ownerRelationLabel: 'Owner relation',
        ownerRelation: `Relation ${index} (${polarity}) · ${relationLabel} · ${relationId}`,
        viewReason,
        evidence: `Panel evidence ${name}; class: ${evidenceClass}`,
        auditedEvidence: `Audited Panel evidence ${name}; class: ${evidenceClass}; ` +
            `claim code: ${claimCode}; ${auditDisposition}`
    } : {
        cellHeading: `证据单元格：${source} → ${target}`,
        editCell: `编辑 ${source} 到 ${target} 的 Panel 证据`,
        deleteNode: `删除机制节点：${name}`,
        panelName: `Panel 名称：${name}`,
        replacePanel: `替换 Panel：${name}`,
        evidenceClass: `证据类别：${name}`,
        ownerEdge: `第 ${index} 条联系（${polarity}）`,
        relationBadge,
        originalDisplayIdLabel: '原始标识',
        figureIdLabel: 'Figure ID',
        panelIdLabel: 'Panel ID',
        ownerRelationLabel: '所属联系',
        ownerRelation: `第 ${index} 条联系（${polarity}） · ${relationLabel} · ${relationId}`,
        viewReason,
        evidence: `Panel 证据 ${name}；类别：${evidenceClass}`,
        auditedEvidence: `已审计 Panel 证据 ${name}；类别：${evidenceClass}；` +
            `证据代码：${claimCode}；${auditDisposition}`
    };
    return templates[key] || '';
}

function mechanismMatrixEvidenceEditItem(chain, sourceId, targetId, item) {
    const edgeId = String(item?.ownerEdgeId || item?.edgeId || '');
    const index = Number(item?.evidenceIndex);
    if (!edgeId || !Number.isSafeInteger(index) || index < 0) return null;
    const chainEdges = Array.isArray(chain?.edges) ? chain.edges.slice(0, 64) : [];
    const edge = chainEdges
        .find(candidate => candidate?.id === edgeId &&
            candidate?.from === sourceId && candidate?.to === targetId);
    const reference = Array.isArray(edge?.panelEvidence) ? edge.panelEvidence[index] : null;
    if (!reference || reference.figureId !== item?.figureId ||
        reference.panelId !== item?.panelId) return null;
    const parallelEdges = chainEdges.filter(candidate =>
        candidate?.from === sourceId && candidate?.to === targetId);
    const relationOrdinal = parallelEdges.indexOf(edge) + 1;
    const safeText = (value, maximum) => typeof value === 'string'
        ? Array.from(value.normalize('NFKC').replace(/\s+/g, ' ').trim())
            .slice(0, maximum).join('')
        : '';
    const originalDisplayId = typeof item?.originalDisplayId === 'string'
        ? Array.from(item.originalDisplayId).slice(0, 80).join('') : '';
    return {
        edgeId, index,
        figureId: String(item.figureId || ''), panelId: String(item.panelId || ''),
        displayName: String(item.displayName || ''),
        originalDisplayId: originalDisplayId ||
            safeText(reference.value, 80) || safeText(item.displayName, 80),
        evidenceClass: String(item.evidenceClass || 'other'),
        ownerRelationId: edgeId,
        ownerRelationOrdinal: relationOrdinal > 0 ? relationOrdinal : 1,
        ownerRelationPolarity: ['positive', 'negative'].includes(edge.polarity)
            ? edge.polarity : 'neutral',
        ownerRelationKind: edge.relationKind === 'correlative'
            ? 'correlative' : 'causal',
        ownerRelationContested: edge.contested === true,
        ownerRelationLabel: safeText(edge.label?.value, 180),
        ownerRelationLabelSource: safeText(edge.label?.value, 180) &&
            edge.label?.humanReviewed !== false ? 'source' : 'generated'
    };
}

function resolveCurrentMechanismEvidence(edgeId, figureId, panelId) {
    const chain = mechanismWorkspaceDraft()?.mechanismChain;
    const edge = (Array.isArray(chain?.edges) ? chain.edges.slice(0, 64) : [])
        .find(candidate => candidate?.id === edgeId);
    if (!edge) return null;
    const matches = [];
    (Array.isArray(edge.panelEvidence) ? edge.panelEvidence.slice(0, 64) : [])
        .forEach((reference, index) => {
            if (reference?.figureId === figureId && reference?.panelId === panelId) {
                matches.push(index);
            }
        });
    return matches.length === 1
        ? { edgeId, index: matches[0], figureId, panelId } : null;
}

function appendMechanismMatrixNodeHeader(parent, node, index, axis) {
    const label = node?.label || '';
    const description = interfaceLanguage().startsWith('en')
        ? `Mechanism node ${index + 1}` : `机制节点 ${index + 1}`;
    parent.classList.add('workspace-mechanism-matrix-node-header', `is-${axis}`);
    parent.dataset.figureEditOccurrence = axis;
    parent.dataset.mechanismNodeId = node.id;
    const editTarget = appendMechanismInlineField(parent, {
        scope: 'mechanism-node', nodeId: node.id, field: 'label'
    }, label, description, 'workspace-mechanism-matrix-node-label');
    editTarget.dataset.figureEditOccurrence = axis;
    editTarget.dataset.mechanismNodeId = node.id;
    const remove = createWorkspaceElement(
        'button', 'workspace-mechanism-matrix-remove-node', t('删除节点')
    );
    remove.type = 'button';
    remove.dataset.nodeId = node.id;
    remove.disabled = mechanismNodeRemovalCoordinator.isPending(node.id);
    remove.setAttribute('aria-busy', String(remove.disabled));
    remove.setAttribute('aria-label', formatMechanismMatrixUiText('deleteNode', {
        name: label || description
    }));
    remove.addEventListener('click', event => {
        event.stopPropagation();
        void removeMechanismNode(node.id);
    });
    parent.appendChild(remove);
}

function openMechanismMatrixCellEditor({
    anchor, editorHost, chain, source, target, matrixCell,
    evidenceOptions, optionsByIdentity,
    selectedEvidence = null, existingEvidenceOnly = false,
    auditedEvidenceOrdinal = -1
}) {
    document.querySelectorAll('.workspace-mechanism-matrix-cell-editor')
        .forEach(editor => editor.remove());
    const edgeId = String(matrixCell?.edgeIds?.[0] || '');
    const focusKey = `${source.id}\u0000${target.id}`;
    const editor = createWorkspaceElement(
        'div', 'workspace-mechanism-matrix-cell-editor'
    );
    editor.setAttribute('role', 'dialog');
    editor.setAttribute('aria-modal', 'false');
    const headingId = `mechanism-cell-editor-${Math.random().toString(36).slice(2)}`;
    const heading = createWorkspaceElement(
        'h4', 'workspace-mechanism-matrix-cell-editor-title',
        formatMechanismMatrixUiText('cellHeading', {
            source: source.label, target: target.label
        })
    );
    heading.id = headingId;
    editor.setAttribute('aria-labelledby', headingId);
    const close = createWorkspaceElement('button', '', t('关闭'));
    close.type = 'button';
    close.setAttribute('aria-label', t('关闭证据单元格编辑器'));
    const controls = [];
    const panelContext = capturePanelContext();
    const focusAuditedEvidenceOrdinal = existingEvidenceOnly &&
        Number.isSafeInteger(auditedEvidenceOrdinal) &&
        auditedEvidenceOrdinal >= 0 && auditedEvidenceOrdinal < 1024
        ? auditedEvidenceOrdinal : -1;
    const status = createWorkspaceElement(
        'p', 'workspace-mechanism-matrix-cell-status', ''
    );
    status.setAttribute('role', 'status');
    status.setAttribute('aria-live', 'polite');
    const setPending = pending => {
        controls.forEach(control => { control.disabled = pending; });
        editor.setAttribute('aria-busy', String(pending));
    };
    const restoreFocus = key => queueMicrotask(() => {
        const targetCell = [...document.querySelectorAll(
            '.workspace-mechanism-matrix td[data-source-node-id][data-target-node-id]'
        )].find(candidate =>
            `${candidate.dataset.sourceNodeId}\u0000${candidate.dataset.targetNodeId}` === key);
        const auditedTarget = focusAuditedEvidenceOrdinal >= 0
            ? targetCell?.querySelector(
                '.workspace-mechanism-matrix-evidence.is-editable' +
                `[data-audited-evidence-ordinal="${focusAuditedEvidenceOrdinal}"]`
            ) : null;
        (auditedTarget || targetCell?.querySelector(
            '.workspace-mechanism-matrix-cell-edit'
        ))?.focus();
    });
    const controller = createMechanismMatrixCellEditorController({
        captureContext: captureFigureWorkspaceEditContext,
        isContextCurrent: isCurrentFigureWorkspaceEditContext,
        getPanel: key => optionsByIdentity.get(key) || null,
        resolveEvidence: resolveCurrentMechanismEvidence,
        createId: mechanismWorkspaceId,
        mutate: (mutation, context) => mechanismActionCoordinator.run(mutation, context),
        refresh: () => refreshArticleWorkspace({ panelContext }),
        setPending,
        restoreFocus
    });
    controller.open({
        sourceId: source.id, sourceLabel: source.label,
        targetId: target.id, targetLabel: target.label,
        edgeId, edgeIds: matrixCell?.edgeIds,
        edgePolarities: Object.fromEntries(
            (Array.isArray(chain?.edges) ? chain.edges : [])
                .filter(edge => matrixCell?.edgeIds?.includes(edge.id))
                .map(edge => [edge.id, edge.polarity || 'neutral'])
        ),
        focusKey
    });
    const closeEditor = () => {
        editor.remove();
        anchor?.focus();
    };
    close.addEventListener('click', closeEditor);
    const header = createWorkspaceElement('div', 'workspace-mechanism-matrix-cell-editor-header');
    header.append(heading, close);
    editor.append(header, status);

    const showEditorResult = response => {
        if (response?.success) {
            status.textContent = t('已保存');
            status.dataset.state = 'saved';
            return true;
        }
        const messages = {
            FIGURE_WORKSPACE_PANEL_CONTEXT_STALE: t('Panel 证据已变化，请重新打开此单元格'),
            FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED: t('论文上下文已变化，请重新打开证据表'),
            FIGURE_WORKSPACE_MATRIX_CELL_PENDING: t('正在保存，请稍候'),
            MECHANISM_NETWORK_SELF_LOOP_POLARITY_REQUIRED: t('自环联系必须选择正向或负向极性')
        };
        status.textContent = messages[response?.code] || t('证据未保存，请刷新后重试');
        status.dataset.state = 'error';
        return false;
    };
    const perform = async operation => {
        try {
            return showEditorResult(await operation());
        } catch (_) {
            return showEditorResult({ success: false });
        }
    };

    let defaultFocusTarget = null;
    if (!existingEvidenceOnly) {
        const addPanel = document.createElement('select');
        addPanel.className = 'workspace-mechanism-matrix-cell-panel';
        addPanel.setAttribute('aria-label', t('选择 Panel 证据'));
        addPanel.appendChild(new Option(t('选择 Panel'), ''));
        evidenceOptions.slice(0, 512).forEach(option => addPanel.appendChild(new Option(
            option.displayId,
            `${option.figureId}\u0000${option.panelId}`
        )));
        const addClass = document.createElement('select');
        addClass.className = 'workspace-mechanism-matrix-cell-class';
        addClass.setAttribute('aria-label', t('证据类别'));
        [['充分性', 'sufficiency'], ['必要性', 'necessity'], ['其他', 'other']]
            .forEach(([label, value]) => addClass.appendChild(new Option(t(label), value)));
        const polarity = document.createElement('select');
        polarity.className = 'workspace-mechanism-matrix-cell-polarity';
        polarity.setAttribute('aria-label', t('自环联系极性'));
        [['请选择极性', 'neutral'], ['正向', 'positive'], ['负向/抑制', 'negative']]
            .forEach(([label, value]) => polarity.appendChild(new Option(t(label), value)));
        const ownerEdge = document.createElement('select');
        ownerEdge.className = 'workspace-mechanism-matrix-cell-owner-edge';
        ownerEdge.setAttribute('aria-label', t('选择要添加证据的联系'));
        const ownerEdges = (Array.isArray(chain?.edges) ? chain.edges.slice(0, 64) : [])
            .filter(candidate => matrixCell?.edgeIds?.includes(candidate.id));
        ownerEdges.forEach((candidate, index) => ownerEdge.appendChild(new Option(
            formatMechanismMatrixUiText('ownerEdge', {
                index: index + 1, polarity: candidate.polarity
            }),
            candidate.id
        )));
        ownerEdge.hidden = ownerEdges.length < 2;
        polarity.hidden = source.id !== target.id || ownerEdges.length > 0;
        const add = createWorkspaceElement('button', '', t('添加证据'));
        add.type = 'button';
        add.addEventListener('click', async () => {
            await perform(() => controller.add(
                addPanel.value, addClass.value, polarity.value, ownerEdge.value
            ));
        });
        controls.push(addPanel, addClass, ownerEdge, polarity, add);
        const addRow = createWorkspaceElement('div', 'workspace-mechanism-matrix-cell-add');
        addRow.append(addPanel, addClass, ownerEdge, polarity, add);
        editor.appendChild(addRow);
        defaultFocusTarget = addPanel;
    }

    const matrixEvidence = Array.isArray(matrixCell?.evidence)
        ? matrixCell.evidence.slice(0, 64) : [];
    const selectedEditItem = existingEvidenceOnly
        ? mechanismMatrixEvidenceEditItem(chain, source.id, target.id, selectedEvidence)
        : null;
    const evidence = existingEvidenceOnly
        ? (selectedEditItem ? [selectedEvidence] : [])
        : matrixEvidence;
    if (existingEvidenceOnly && selectedEditItem) {
        const identity = createWorkspaceElement(
            'dl', 'workspace-mechanism-matrix-evidence-identity'
        );
        const appendIdentity = (field, label, value) => {
            const entry = createWorkspaceElement('div', '');
            entry.dataset.mechanismIdentity = field;
            entry.append(
                createWorkspaceElement('dt', '', label),
                createWorkspaceElement('dd', '', value)
            );
            identity.appendChild(entry);
        };
        appendIdentity('original-display-id',
            formatMechanismMatrixUiText('originalDisplayIdLabel'),
            selectedEditItem.originalDisplayId);
        appendIdentity('figure-id', formatMechanismMatrixUiText('figureIdLabel'),
            selectedEditItem.figureId);
        appendIdentity('panel-id', formatMechanismMatrixUiText('panelIdLabel'),
            selectedEditItem.panelId);
        appendIdentity('owner-relation',
            formatMechanismMatrixUiText('ownerRelationLabel'),
            formatMechanismMatrixUiText('ownerRelation', {
                index: selectedEditItem.ownerRelationOrdinal,
                polarity: selectedEditItem.ownerRelationPolarity,
                relationLabel: selectedEditItem.ownerRelationLabel,
                relationId: selectedEditItem.ownerRelationId
            }));
        editor.appendChild(identity);
    }
    evidence.forEach(item => {
        const editItem = mechanismMatrixEvidenceEditItem(
            chain, source.id, target.id, item
        );
        if (!editItem) return;
        const row = createWorkspaceElement('div', 'workspace-mechanism-matrix-cell-evidence');
        row.dataset.ownerEdgeId = editItem.edgeId;
        row.dataset.evidenceIndex = String(editItem.index);
        const selectedOwnerEdgeId = String(
            selectedEvidence?.ownerEdgeId || selectedEvidence?.edgeId || ''
        );
        if (selectedOwnerEdgeId === editItem.edgeId &&
            Number(selectedEvidence?.evidenceIndex) === editItem.index &&
            selectedEvidence?.figureId === editItem.figureId &&
            selectedEvidence?.panelId === editItem.panelId) {
            row.classList.add('is-selected');
        }
        const alias = document.createElement('input');
        alias.type = 'text';
        alias.maxLength = 80;
        alias.className = 'workspace-mechanism-matrix-cell-alias';
        alias.value = item.displayName;
        alias.setAttribute('aria-label', formatMechanismMatrixUiText('panelName', {
            name: item.displayName
        }));
        const saveAlias = createWorkspaceElement('button', '', t('保存名称'));
        saveAlias.type = 'button';
        saveAlias.addEventListener('click', async () => {
            await perform(() => controller.alias(editItem, alias.value));
        });
        const replacement = document.createElement('select');
        replacement.className = 'workspace-mechanism-matrix-cell-replacement';
        replacement.setAttribute('aria-label', formatMechanismMatrixUiText('replacePanel', {
            name: item.displayName
        }));
        evidenceOptions.slice(0, 512).forEach(option => {
            const key = `${option.figureId}\u0000${option.panelId}`;
            const entry = new Option(option.displayId, key);
            entry.selected = option.figureId === item.figureId && option.panelId === item.panelId;
            replacement.appendChild(entry);
        });
        const classSelect = document.createElement('select');
        classSelect.className = 'workspace-mechanism-matrix-cell-class';
        classSelect.setAttribute('aria-label', formatMechanismMatrixUiText('evidenceClass', {
            name: item.displayName
        }));
        [['充分性', 'sufficiency'], ['必要性', 'necessity'], ['其他', 'other']]
            .forEach(([label, value]) => {
                const entry = new Option(t(label), value);
                entry.selected = value === item.evidenceClass;
                classSelect.appendChild(entry);
            });
        replacement.addEventListener('change', async () => {
            await perform(() => controller.replace(
                editItem, replacement.value, classSelect.value
            ));
        });
        classSelect.addEventListener('change', async () => {
            await perform(() => controller.setClass(editItem, classSelect.value));
        });
        const remove = createWorkspaceElement(
            'button', 'workspace-mechanism-matrix-cell-remove', t('删除证据')
        );
        remove.type = 'button';
        remove.addEventListener('click', async () => {
            await perform(() => controller.remove(editItem));
        });
        controls.push(alias, saveAlias, replacement, classSelect, remove);
        row.append(alias, saveAlias, replacement, classSelect, remove);
        editor.appendChild(row);
    });
    editor.addEventListener('keydown', event => {
        if (event.key === 'Escape') {
            event.preventDefault();
            closeEditor();
        }
    });
    editorHost.appendChild(editor);
    (selectedEvidence
        ? editor.querySelector('.workspace-mechanism-matrix-cell-evidence.is-selected input')
        : defaultFocusTarget)?.focus();
}

function normalizeMechanismPanelDispositions(
    chain, evidenceOptions, panelDispositionsOverride, linkedPanelKeys
) {
    const MAX_DISPOSITIONS = 512;
    const plain = value => {
        try {
            if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
            const prototype = Object.getPrototypeOf(value);
            return prototype === Object.prototype || prototype === null;
        } catch (_) {
            return false;
        }
    };
    const own = (value, key) => {
        if (!plain(value)) return undefined;
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.prototype.hasOwnProperty.call(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) {
            return undefined;
        }
    };
    const text = (value, maximum, preserveWhitespace = false) => {
        if (typeof value !== 'string') return '';
        const bounded = Array.from(value).slice(0, maximum).join('')
            .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
        return preserveWhitespace ? bounded : bounded.replace(/\s+/g, ' ').trim();
    };
    const values = (value, maximum) => {
        let length;
        try {
            if (!Array.isArray(value)) return null;
            length = value.length;
        } catch (_) {
            return null;
        }
        if (length > maximum) return null;
        const result = [];
        for (let index = 0; index < length; index += 1) {
            let descriptor;
            try { descriptor = Object.getOwnPropertyDescriptor(value, String(index)); }
            catch (_) { return null; }
            if (!descriptor || !Object.prototype.hasOwnProperty.call(descriptor, 'value')) {
                return null;
            }
            result.push(descriptor.value);
        }
        return result;
    };
    const catalog = new Map();
    const addCatalogEntry = entry => {
        if (!plain(entry)) return;
        const explicitKey = text(own(entry, 'panelKey'), 100);
        const figureId = text(own(entry, 'figureId'), 80);
        const panelId = text(own(entry, 'panelId'), 16);
        const key = explicitKey || (figureId && panelId ? `${figureId}:${panelId}` : '');
        const originalDisplayId = text(
            own(entry, 'originalDisplayId') || own(entry, 'displayId'), 100
        );
        if (!key || !originalDisplayId || catalog.has(key)) return;
        catalog.set(key, {
            originalDisplayId,
            displayAlias: text(own(entry, 'displayAlias'), 120, true)
        });
    };
    const optionValues = values(evidenceOptions, MAX_DISPOSITIONS);
    if (optionValues) optionValues.forEach(addCatalogEntry);

    const aliases = own(chain, 'panelAliases');
    const rawDispositions = panelDispositionsOverride === undefined
        ? own(chain, 'panelDispositions') : panelDispositionsOverride;
    const dispositions = values(rawDispositions, MAX_DISPOSITIONS);
    if (!dispositions) return [];
    const normalized = [];
    const seen = new Set();
    const conflicted = new Set();
    for (const raw of dispositions) {
        if (!plain(raw)) continue;
        const panelKey = text(own(raw, 'panelKey'), 100);
        const status = text(own(raw, 'status'), 24).toLowerCase();
        const catalogEntry = catalog.get(panelKey);
        if (!panelKey || !catalogEntry ||
            !['linked', 'unlinked', 'excluded', 'ambiguous'].includes(status)) continue;
        if (seen.has(panelKey)) {
            conflicted.add(panelKey);
            continue;
        }
        seen.add(panelKey);
        const liveStatus = linkedPanelKeys instanceof Set
            ? (linkedPanelKeys.has(panelKey) ? 'linked'
                : status === 'linked' ? 'unlinked' : status)
            : status;
        if (liveStatus === 'linked') continue;
        const aliasEntry = own(aliases, panelKey);
        const displayAlias = text(own(aliasEntry, 'value'), 120, true) ||
            catalogEntry.displayAlias;
        const statusReason = text(
            own(raw, 'statusReason') || own(raw, 'reason'), 600
        );
        const rawCandidates = own(raw, 'candidatePanelKeys');
        let candidateDisplayNames = [];
        if (rawCandidates !== undefined) {
            const candidateValues = values(rawCandidates, 24);
            if (!candidateValues) continue;
            const candidateKeys = candidateValues.map(value => text(value, 100));
            if (candidateKeys.some((key, index) => !key || key === panelKey ||
                !catalog.has(key) || candidateKeys.indexOf(key) !== index)) continue;
            candidateDisplayNames = candidateKeys.map(key => {
                const candidate = catalog.get(key);
                const candidateAlias = text(own(own(aliases, key), 'value'), 120, true) ||
                    candidate.displayAlias;
                return candidateAlias || candidate.originalDisplayId;
            });
        }
        if ((liveStatus === 'unlinked' || liveStatus === 'excluded') &&
            status !== 'linked' && !statusReason) continue;
        if (liveStatus === 'ambiguous' && !statusReason &&
            !candidateDisplayNames.length) continue;
        normalized.push({
            panelKey,
            originalDisplayId: catalogEntry.originalDisplayId,
            displayAlias,
            displayName: displayAlias || catalogEntry.originalDisplayId,
            status: liveStatus,
            statusReason,
            ...(candidateDisplayNames.length ? { candidateDisplayNames } : {}),
            ...(status === 'linked' && liveStatus === 'unlinked'
                ? { missingLiveLink: true } : {})
        });
    }
    return normalized.filter(item => !conflicted.has(item.panelKey));
}

function createMechanismPanelDispositionAudit(
    chain, evidenceOptions, panelDispositions, linkedPanelKeys
) {
    const dispositions = normalizeMechanismPanelDispositions(
        chain, evidenceOptions, panelDispositions, linkedPanelKeys
    );
    if (!dispositions.length) return null;
    const audit = createWorkspaceElement(
        'section', 'workspace-mechanism-panel-disposition-audit'
    );
    audit.setAttribute('aria-label', t('未关联 Panel 审计'));
    audit.append(
        createWorkspaceElement('h4', '', t('未关联 Panel 审计')),
        createWorkspaceElement(
            'p', 'workspace-mechanism-panel-disposition-help',
            t('未关联 Panel 不会显示为联系证据，以下条目保留其审计状态与原因。')
        )
    );
    const auditList = createWorkspaceElement(
        'ul', 'workspace-mechanism-panel-disposition-list'
    );
    const statusLabels = {
        unlinked: '未关联', excluded: '已排除', ambiguous: '存在歧义'
    };
    dispositions.forEach(disposition => {
        const reason = disposition.statusReason ||
            (Array.isArray(disposition.candidateDisplayNames) &&
                disposition.candidateDisplayNames.length
                ? `${t('候选 Panel')}: ${disposition.candidateDisplayNames.join(', ')}`
                : disposition.missingLiveLink
                    ? t('当前证据表中没有关联联系。') : '');
        const item = createWorkspaceElement(
            'li', `workspace-mechanism-panel-disposition is-${disposition.status}`
        );
        item.dataset.panelDispositionKey = disposition.panelKey;
        item.dataset.panelDisposition = disposition.status;
        item.dataset.panelDispositionStatus = disposition.status;
        item.append(
            createWorkspaceElement(
                'span', 'workspace-mechanism-panel-disposition-name',
                disposition.displayName
            ),
            createWorkspaceElement(
                'span', 'workspace-mechanism-panel-disposition-status',
                t(statusLabels[disposition.status])
            ),
            createWorkspaceElement(
                'span', 'workspace-mechanism-panel-disposition-reason',
                reason
            )
        );
        auditList.appendChild(item);
    });
    audit.appendChild(auditList);
    return audit;
}

function renderMechanismEvidenceMatrix(chain, host, options = {}) {
    const audited = options.audit?.version === 'mechanism-audit-view-v1';
    const relationUiText = typeof formatMechanismRelationUiText === 'function'
        ? formatMechanismRelationUiText
        : relation => typeof relation?.label === 'string' ? relation.label : '';
    const evidenceCodeLabel = typeof formatMechanismEvidenceCodeLabel === 'function'
        ? formatMechanismEvidenceCodeLabel
        : code => ({
            S: 'Sufficiency', N: 'Necessity', R: 'Rescue', E: 'Epistasis',
            I: 'Directional intervention', A: 'Association',
            O: 'Observation / localization', '0': 'Null result',
            C: 'Counterevidence', '?': 'Inconclusive / unknown'
        })[code] || 'Inconclusive / unknown';
    const auditReason = typeof formatMechanismAuditReason === 'function'
        ? formatMechanismAuditReason : value => String(value || '');
    const evidenceOptions = Array.isArray(options.evidenceOptions)
        ? options.evidenceOptions.slice(0, 512) : [];
    const matrix = audited
        ? SciLLM.createMechanismAuditEvidenceView(chain, options.audit, evidenceOptions)
        : SciLLM.createMechanismEvidenceMatrix(chain);
    const axes = mechanismMatrixNodeAxisModel(matrix);
    const optionsByIdentity = options.optionsByIdentity instanceof Map
        ? options.optionsByIdentity : new Map(evidenceOptions.map(option => [
            `${option.figureId}\u0000${option.panelId}`, option
        ]));
    const relationPresentation = (matrixCell, item, sourceId, targetId) => {
        const edgeId = typeof item?.ownerEdgeId === 'string'
            ? item.ownerEdgeId : typeof item?.edgeId === 'string' ? item.edgeId : '';
        if (!edgeId) return null;
        const declaredMatches = (Array.isArray(matrixCell?.relationDescriptors)
            ? matrixCell.relationDescriptors : []).filter(value => value?.id === edgeId);
        const declared = declaredMatches.length === 1 ? declaredMatches[0] : null;
        if (declared) return {
            id: edgeId,
            ordinal: Number.isSafeInteger(declared.ordinal) && declared.ordinal > 0
                ? declared.ordinal : 1,
            polarity: declared.polarity,
            relationKind: declared.relationKind,
            contested: declared.contested === true,
            label: typeof declared.label === 'string' ? declared.label : '',
            labelSource: declared.labelSource === 'generated' ? 'generated' : 'source'
        };
        const candidates = (Array.isArray(chain?.edges) ? chain.edges.slice(0, 64) : [])
            .filter(edge => edge?.from === sourceId && edge?.to === targetId);
        const index = candidates.findIndex(edge => edge?.id === edgeId);
        const edge = index >= 0 ? candidates[index] : null;
        return edge ? {
            id: edgeId,
            ordinal: index + 1,
            polarity: edge.polarity,
            relationKind: edge.relationKind,
            contested: edge.contested === true,
            label: typeof edge.label?.value === 'string' ? edge.label.value : '',
            labelSource: edge.label?.value && edge.label?.humanReviewed !== false
                ? 'source' : 'generated'
        } : null;
    };
    const appendRelationIdentity = (chip, relation) => {
        const relationText = formatMechanismMatrixUiText('relationBadge', {
            index: relation.ordinal,
            polarity: relation.polarity,
            relationKind: relation.relationKind,
            contested: relation.contested === true,
            relationLabel: relationUiText(relation, interfaceLanguage())
        });
        const badge = createWorkspaceElement(
            'span', 'workspace-mechanism-matrix-relation-badge', relationText
        );
        badge.dataset.ownerEdgeId = String(relation.id || '');
        badge.dataset.relationKind = relation.relationKind === 'correlative'
            ? 'correlative' : 'causal';
        badge.dataset.polarity = String(relation.polarity || 'neutral');
        badge.dataset.contested = String(relation.contested === true);
        badge.dataset.labelSource = relation.labelSource === 'generated'
            ? 'generated' : 'source';
        badge.setAttribute('aria-hidden', 'true');
        chip.appendChild(badge);
        const accessibleName = chip.getAttribute('aria-label') || chip.title || '';
        const detailedName = `${accessibleName}${
            interfaceLanguage().startsWith('en') ? '; ' : '；'
        }${relationText}`;
        chip.title = detailedName;
        chip.setAttribute('aria-label', detailedName);
    };
    const wrap = createWorkspaceElement('section', 'workspace-mechanism-matrix-section');
    wrap.id = 'mechanismEvidenceRegion';
    wrap.tabIndex = -1;
    wrap.append(
        createWorkspaceElement('h3', '', t('证据表')),
        createWorkspaceElement(
            'p', 'workspace-mechanism-matrix-help',
            t('列为上游节点，行为下游节点。')
        )
    );
    const toolbar = createWorkspaceElement('div', 'workspace-mechanism-matrix-toolbar');
    const addNode = createWorkspaceElement(
        'button', 'workspace-mechanism-matrix-add-node',
        interfaceLanguage().startsWith('en') ? 'Add node' : '新增节点'
    );
    addNode.type = 'button';
    addNode.addEventListener('click', () => void addMechanismNodeAfter());
    toolbar.appendChild(addNode);
    wrap.appendChild(toolbar);
    const scroll = createWorkspaceElement('div', 'workspace-mechanism-matrix-scroll');
    const table = createWorkspaceElement('table', 'workspace-mechanism-matrix');
    const editorHost = createWorkspaceElement(
        'div', 'workspace-mechanism-matrix-editor-host'
    );
    const head = document.createElement('thead');
    const headRow = document.createElement('tr');
    const corner = document.createElement('th');
    corner.scope = 'col';
    corner.textContent = t('结果 ↓ / 来源 →');
    headRow.appendChild(corner);
    axes.columns.forEach((node, index) => {
        const cell = document.createElement('th');
        cell.scope = 'col';
        appendMechanismMatrixNodeHeader(cell, node, index, 'column');
        headRow.appendChild(cell);
    });
    head.appendChild(headRow);
    const body = document.createElement('tbody');
    const cells = new Map(matrix.cells.map(cell => [`${cell.from}\u0000${cell.to}`, cell]));
    axes.rows.forEach((target, targetIndex) => {
        const row = document.createElement('tr');
        const label = document.createElement('th');
        label.scope = 'row';
        appendMechanismMatrixNodeHeader(label, target, targetIndex, 'row');
        row.appendChild(label);
        axes.columns.forEach(source => {
            const cell = document.createElement('td');
            const matrixCell = cells.get(`${source.id}\u0000${target.id}`) || {
                from: source.id, to: target.id, edgeIds: [], evidence: []
            };
            const evidence = matrixCell?.evidence || [];
            cell.dataset.lineStyle = matrixCell?.lineStyle || 'none';
            cell.dataset.contested = String(matrixCell?.contested === true);
            cell.dataset.diagonal = String(source.id === target.id);
            if (matrixCell?.lineStyle === 'dashed') cell.classList.add('is-correlation-only');
            if (matrixCell?.contested === true) cell.classList.add('is-contested');
            if (source.id === target.id) cell.classList.add('is-diagonal');
            evidence.forEach((item, auditedEvidenceOrdinal) => {
                if (audited) {
                    const code = ['S', 'N', 'R', 'E', 'I', 'A', 'O', '0', 'C', '?']
                        .includes(item.claimCode) ? item.claimCode : '?';
                    const evidenceClass = ['sufficiency', 'necessity', 'other']
                        .includes(item.evidenceClass) ? item.evidenceClass : 'other';
                    const placementKind = item.placementKind === 'node_only'
                        ? 'node_only' : 'relation';
                    const reportedMappingStatus = [
                        'unique', 'ambiguous', 'unmapped', 'node_only'
                    ]
                        .includes(item.mappingStatus) ? item.mappingStatus : 'unmapped';
                    const editItem = placementKind === 'relation' &&
                        reportedMappingStatus === 'unique'
                        ? mechanismMatrixEvidenceEditItem(
                            chain, source.id, target.id, item
                        ) : null;
                    const editable = placementKind === 'relation' &&
                        reportedMappingStatus === 'unique' && Boolean(editItem);
                    const mappingStatus = reportedMappingStatus === 'unique' && !editable
                        ? 'unmapped' : reportedMappingStatus;
                    const chip = createWorkspaceElement(
                        editable ? 'button' : 'span',
                        `workspace-mechanism-matrix-evidence is-${evidenceClass} ` +
                            (editable ? 'is-editable' : 'is-view-only'),
                        item.displayName
                    );
                    if (editable) chip.type = 'button';
                    else chip.setAttribute('role', 'note');
                    chip.dataset.evidenceCode = code;
                    chip.dataset.placementKind = placementKind;
                    chip.dataset.mappingStatus = mappingStatus;
                    chip.dataset.auditedEvidenceOrdinal = String(auditedEvidenceOrdinal);
                    chip.title = formatMechanismMatrixUiText('auditedEvidence', {
                        name: item.displayName,
                        evidenceClass,
                        claimCode: code,
                        placementKind,
                        mappingStatus
                    });
                    chip.setAttribute('aria-label', chip.title);
                    if (editable && matrixCell.edgeIds?.length > 1) {
                        const declaredRelation = relationPresentation(
                            matrixCell, item, source.id, target.id
                        );
                        if (declaredRelation) {
                            const relation = editItem.ownerRelationLabel &&
                                editItem.ownerRelationLabelSource === 'source'
                                ? {
                                    ...declaredRelation,
                                    label: editItem.ownerRelationLabel,
                                    labelSource: 'source'
                                }
                                : declaredRelation;
                            appendRelationIdentity(chip, relation);
                        }
                    }
                    if (!editable) {
                        const reason = createWorkspaceElement(
                            'span', 'workspace-mechanism-matrix-view-reason',
                            formatMechanismMatrixUiText('viewReason', {
                                placementKind,
                                mappingStatus
                            })
                        );
                        reason.setAttribute('aria-hidden', 'true');
                        chip.appendChild(reason);
                    }
                    if (editable) {
                        chip.addEventListener('click', event => {
                            event.stopPropagation();
                            openMechanismMatrixCellEditor({
                                anchor: chip, editorHost, chain, source, target, matrixCell,
                                evidenceOptions, optionsByIdentity, selectedEvidence: item,
                                existingEvidenceOnly: true, auditedEvidenceOrdinal
                            });
                        });
                    }
                    cell.appendChild(chip);
                    return;
                }
                const chip = createWorkspaceElement('button',
                    `workspace-mechanism-matrix-evidence is-${item.evidenceClass}`);
                chip.type = 'button';
                chip.textContent = item.displayName;
                chip.title = formatMechanismMatrixUiText('evidence', {
                    name: item.displayName, evidenceClass: item.evidenceClass
                });
                chip.setAttribute('aria-label', chip.title);
                const relationPresentationItem = relationPresentation(
                    matrixCell, item, source.id, target.id
                );
                if (relationPresentationItem && matrixCell.edgeIds?.length > 1) {
                    appendRelationIdentity(chip, relationPresentationItem);
                }
                const editEvidence = event => {
                    event.stopPropagation();
                    openMechanismMatrixCellEditor({
                        anchor: chip, editorHost, chain, source, target, matrixCell,
                        evidenceOptions, optionsByIdentity, selectedEvidence: item
                    });
                };
                chip.addEventListener('click', editEvidence);
                cell.appendChild(chip);
            });
            cell.dataset.sourceNodeId = source.id;
            cell.dataset.targetNodeId = target.id;
            if (!audited) {
                const editCell = createWorkspaceElement(
                    'button', 'workspace-mechanism-matrix-cell-edit',
                    evidence.length ? t('编辑') : '＋'
                );
                editCell.type = 'button';
                editCell.setAttribute('aria-label', formatMechanismMatrixUiText('editCell', {
                    source: source.label, target: target.label
                }));
                editCell.addEventListener('click', () => {
                    openMechanismMatrixCellEditor({
                        anchor: editCell, editorHost, chain, source, target, matrixCell,
                        evidenceOptions, optionsByIdentity
                    });
                });
                cell.appendChild(editCell);
            }
            row.appendChild(cell);
        });
        body.appendChild(row);
    });
    table.append(head, body);
    scroll.appendChild(table);
    const legend = createWorkspaceElement(
        'div', 'workspace-mechanism-matrix-legend'
    );
    legend.setAttribute('aria-label', t('证据类别'));
    legend.setAttribute('role', 'list');
    if (audited) {
        [
            ['S', 's'], ['N', 'n'], ['R', 'r'], ['E', 'e'], ['I', 'i'],
            ['A', 'a'], ['O', 'o'], ['0', 'zero'], ['C', 'c'], ['?', 'unknown']
        ].forEach(([code, className]) => {
            const label = evidenceCodeLabel(code);
            const item = createWorkspaceElement(
                'span', `workspace-mechanism-matrix-legend-item is-${className}`
            );
            item.setAttribute('role', 'listitem');
            item.title = label;
            const codeNode = createWorkspaceElement(
                'span', `workspace-mechanism-evidence-code is-${className}`, code
            );
            codeNode.dataset.evidenceCode = code;
            codeNode.setAttribute('aria-hidden', 'true');
            item.append(codeNode, document.createTextNode(label));
            item.setAttribute('aria-label', `${code}: ${label}`);
            legend.appendChild(item);
        });
    } else {
        [
            ['other', '其他或相关性证据'],
            ['sufficiency', '充分性证据'],
            ['necessity', '必要性证据']
        ].forEach(([className, label]) => {
            const item = createWorkspaceElement(
                'span', `workspace-mechanism-matrix-legend-item is-${className}`,
                t(label)
            );
            item.setAttribute('role', 'listitem');
            legend.appendChild(item);
        });
    }
    const linkedPanelKeys = new Set(matrix.cells.flatMap(cell =>
        (Array.isArray(cell?.evidence) ? cell.evidence : [])
            .map(item => typeof item?.panelKey === 'string' ? item.panelKey : '')
            .filter(Boolean)
    ));
    const audit = createMechanismPanelDispositionAudit(
        chain, evidenceOptions, options.panelDispositions, linkedPanelKeys
    );
    wrap.append(scroll, editorHost);
    if (audit) wrap.appendChild(audit);
    if (audited && options.audit.disconnectedEvidence?.length) {
        const disconnected = createWorkspaceElement(
            'section',
            'workspace-mechanism-audit-region workspace-mechanism-disconnected-audit'
        );
        disconnected.setAttribute('aria-label', t('未连通证据审计'));
        disconnected.appendChild(createWorkspaceElement(
            'h4', '', t('未连通但有证据的节点')
        ));
        const list = createWorkspaceElement('ul', 'workspace-mechanism-audit-list');
        options.audit.disconnectedEvidence.slice(0, 64).forEach(item => {
            const codes = Array.isArray(item?.codes) ? item.codes.join(' / ') : '';
            const count = Math.max(0, Number(item?.claimCount) || 0);
            const countLabel = interfaceLanguage().startsWith('en')
                ? `${count} claim${count === 1 ? '' : 's'}` : `${count} 条主张`;
            list.appendChild(createWorkspaceElement(
                'li', '', `${item?.label || ''} · ${codes} · ${countLabel}`
            ));
        });
        disconnected.appendChild(list);
        wrap.appendChild(disconnected);
    }
    if (audited && options.audit.unresolvedEvidence?.length) {
        const unresolved = createWorkspaceElement(
            'section',
            'workspace-mechanism-audit-region workspace-mechanism-unresolved-audit'
        );
        unresolved.setAttribute('aria-label', t('未解析证据审计'));
        unresolved.appendChild(createWorkspaceElement(
            'h4', '', t('尚未解析的证据')
        ));
        const list = createWorkspaceElement('ul', 'workspace-mechanism-audit-list');
        options.audit.unresolvedEvidence.slice(0, 512).forEach(item => {
            list.appendChild(createWorkspaceElement(
                'li', '', `${item?.panelKey || ''} · ${item?.code || '?'} · ${
                    auditReason(item?.reason)
                }`
            ));
        });
        unresolved.appendChild(list);
        wrap.appendChild(unresolved);
    }
    if (audited && options.audit.exclusions?.length) {
        const exclusions = createWorkspaceElement(
            'section',
            'workspace-mechanism-audit-region workspace-mechanism-exclusion-audit'
        );
        exclusions.setAttribute('aria-label', t('排除证据审计'));
        exclusions.appendChild(createWorkspaceElement(
            'h4', '', t('示意图 / 非证据排除项')
        ));
        const list = createWorkspaceElement('ul', 'workspace-mechanism-audit-list');
        options.audit.exclusions.slice(0, 512).forEach(item => list.appendChild(
            createWorkspaceElement('li', '', `${item?.panelKey || ''} · ${
                auditReason(item?.reason)
            }`)
        ));
        exclusions.appendChild(list);
        wrap.appendChild(exclusions);
    }
    wrap.appendChild(legend);
    host.appendChild(wrap);
}

function bindMechanismMermaidInteractions(diagram, chain, options) {
    const nodes = Array.isArray(chain?.nodes) ? chain.nodes : [];
    const edges = Array.isArray(chain?.edges) ? chain.edges : [];
    options = options && typeof options === 'object' ? options : {};
    const renderGeneration = Number.isSafeInteger(options.renderGeneration)
        ? options.renderGeneration : Number(diagram?.dataset?.mechanismRenderGeneration);
    const focusHandoff = options.focusHandoff ||
        (typeof mechanismMermaidFocusHandoff === 'object'
            ? mechanismMermaidFocusHandoff : null);
    const selectNode = typeof options.selectNode === 'function'
        ? options.selectNode : id => mechanismNetworkViewController.selectNode(id);
    const selectEdge = typeof options.selectEdge === 'function'
        ? options.selectEdge : id => mechanismNetworkViewController.selectEdge(id);
    const english = interfaceLanguage().startsWith('en');
    const boundedText = (value, maximum = 180) => typeof value === 'string'
        ? Array.from(value.normalize('NFKC').replace(/\s+/g, ' ').trim())
            .slice(0, maximum).join('')
        : '';
    const nodeLabel = (node, index) => boundedText(
        typeof node?.label === 'string' ? node.label : node?.label?.value
    ) || (english ? `Mechanism node ${index + 1}` : `机制节点 ${index + 1}`);
    const labelsById = new Map(nodes.map((node, index) => [
        node?.id, nodeLabel(node, index)
    ]));
    const relationFormatter = typeof formatMechanismRelationUiText === 'function'
        ? formatMechanismRelationUiText
        : (edge, language) => {
            const raw = boundedText(
                typeof edge?.label === 'string' ? edge.label : edge?.label?.value
            );
            if (raw) return raw;
            const localEnglish = String(language || '').startsWith('en');
            return edge?.polarity === 'negative'
                ? (localEnglish ? 'decreases' : '抑制')
                : edge?.polarity === 'positive'
                    ? (localEnglish ? 'increases' : '促进')
                    : (localEnglish ? 'affects' : '影响');
        };
    const edgeLabel = edge => {
        const relation = boundedText(relationFormatter(edge, english ? 'en' : 'zh-CN'));
        if (edge?.contested !== true) return relation;
        return english ? `contested: ${relation}` : `有争议：${relation}`;
    };
    const bind = (element, { id, kind, select, accessibleName }) => {
        if (!element || !id) return;
        element.dataset[kind === 'node' ? 'mechanismNodeId' : 'mechanismEdgeId'] = id;
        element.classList.add('workspace-mechanism-mermaid-target');
        element.tabIndex = 0;
        element.setAttribute('role', 'button');
        element.setAttribute('aria-label', accessibleName);
        element.addEventListener('click', event => {
            event.stopPropagation();
            select(id);
        });
        element.addEventListener('keydown', event => {
            if (event.key !== 'Enter' && event.key !== ' ') return;
            event.preventDefault();
            event.stopPropagation();
            const queued = focusHandoff?.queue(kind, id, renderGeneration) === true;
            const selected = select(id);
            if (queued && selected !== id) {
                focusHandoff.cancel(kind, id, renderGeneration + 1);
            }
        });
    };
    diagram.querySelectorAll('g.node').forEach((element, index) => bind(element, {
        id: nodes[index]?.id,
        kind: 'node',
        accessibleName: english
            ? `Mechanism node ${index + 1}: ${nodeLabel(nodes[index], index)}`
            : `机制节点 ${index + 1}：${nodeLabel(nodes[index], index)}`,
        select: selectNode
    }));
    const edgeGroups = [...diagram.querySelectorAll('g.edgePath')];
    const edgeCarriers = edgeGroups.length
        ? edgeGroups : [...diagram.querySelectorAll('path.flowchart-link')];
    edgeCarriers.forEach((element, index) => {
        const edge = edges[index];
        bind(element, {
            id: edge?.id,
            kind: 'edge',
            accessibleName: english
                ? `Relation ${index + 1}: ${labelsById.get(edge?.from) || edge?.from || ''}` +
                    ` → ${labelsById.get(edge?.to) || edge?.to || ''}; ${edgeLabel(edge)}`
                : `联系 ${index + 1}：${labelsById.get(edge?.from) || edge?.from || ''}` +
                    ` → ${labelsById.get(edge?.to) || edge?.to || ''}；${edgeLabel(edge)}`,
            select: selectEdge
        });
    });
}

function createMechanismAuditInteractionModel(graph, chain) {
    const chainNodes = Array.isArray(chain?.nodes) ? chain.nodes : [];
    const chainEdges = Array.isArray(chain?.edges) ? chain.edges : [];
    const editableNodeIds = new Set(chainNodes.map(node => node?.id).filter(Boolean));
    const nodes = (Array.isArray(graph?.nodes) ? graph.nodes : []).map(node => ({
        id: editableNodeIds.has(node?.id) ? node.id : '',
        label: typeof node?.label === 'string' ? node.label : ''
    }));
    const edges = (Array.isArray(graph?.edges) ? graph.edges : []).map(edge => {
        const matches = chainEdges.filter(candidate =>
            candidate?.from === edge?.from && candidate?.to === edge?.to);
        const interactionEdge = {
            id: matches.length === 1 ? matches[0].id : '',
            from: typeof edge?.from === 'string' ? edge.from : '',
            to: typeof edge?.to === 'string' ? edge.to : '',
            label: typeof edge?.label === 'string' ? edge.label : '',
            polarity: ['positive', 'negative', 'neutral'].includes(edge?.polarity)
                ? edge.polarity : 'neutral',
            evidenceCount: matches.length === 1 && Array.isArray(matches[0]?.panelEvidence)
                ? Math.min(64, matches[0].panelEvidence.length) : 0
        };
        Object.defineProperties(interactionEdge, {
            lineStyle: {
                value: edge?.lineStyle === 'dashed' ? 'dashed' : 'solid'
            },
            relationKind: {
                value: edge?.lineStyle === 'dashed' ? 'correlative' : 'causal'
            },
            contested: { value: edge?.contested === true },
            labelSource: { value: 'generated' }
        });
        return interactionEdge;
    });
    return { nodes, edges };
}

function renderMechanismNetwork(chain, host, options = {}) {
    const generation = ++mechanismMermaidGeneration;
    host.style.removeProperty('height');
    host.style.removeProperty('--mechanism-canvas-width');
    host.style.removeProperty('--mechanism-canvas-height');
    const shell = createWorkspaceElement('div', 'workspace-mechanism-synthesis');
    const graphSection = createWorkspaceElement('section', 'workspace-mechanism-mermaid-section');
    graphSection.id = 'mechanismGraphRegion';
    graphSection.tabIndex = -1;
    graphSection.append(
        createWorkspaceElement('h3', '', t('机制图')),
        createWorkspaceElement(
            'p', 'workspace-mechanism-matrix-help',
            t('机制节点按全文证据凝练；箭头只表达机制方向，证据 Panel 统一列在下方证据表。')
        )
    );
    const diagram = createWorkspaceElement('div', 'mermaid workspace-mechanism-mermaid');
    const direction = (host.clientWidth || document.documentElement.clientWidth || 0) <= 520
        ? 'TD'
        : 'LR';
    diagram.dataset.direction = direction;
    diagram.dataset.mechanismRenderGeneration = String(generation);
    const auditGraph = options.audit
        ? SciLLM.createMechanismGraphExportDto(options.audit) : null;
    const interactionModel = auditGraph
        ? createMechanismAuditInteractionModel(auditGraph, chain) : chain;
    diagram.textContent = auditGraph && !auditGraph.edges.length
        ? t('当前仅有节点证据；未生成关系边。')
        : auditGraph
            ? SciLLM.createMechanismAuditMermaidDefinition(auditGraph, {
                direction, language: interfaceLanguage(), generatedRelationLabels: true
            })
        : SciLLM.createMechanismMermaidDefinition(chain, {
            language: interfaceLanguage(), direction
        });
    if (auditGraph && !auditGraph.edges.length) diagram.classList.remove('mermaid');
    graphSection.appendChild(diagram);
    shell.appendChild(graphSection);
    renderMechanismEvidenceMatrix(chain, shell, options);
    host.replaceChildren(shell);
    if (auditGraph && !auditGraph.edges.length) return {
        width: host.clientWidth || 0, height: host.scrollHeight || 0
    };
    if (!globalThis.mermaid?.run) {
        diagram.classList.remove('mermaid');
        diagram.textContent = t('机制图组件尚未就绪，请刷新后重试。');
        return { width: host.clientWidth || 0, height: host.scrollHeight || 0 };
    }
    const paperKey = mechanismNetworkViewPaperKey(
        options.paperIdentity || mechanismNetworkPaperIdentity()
    );
    const viewControls = createMechanismMermaidViewControls(
        diagram, paperKey, mechanismNetworkViewModeCache, t
    );
    graphSection.insertBefore(viewControls, diagram);
    graphSection.appendChild(createMechanismRelationLegend(t));
    Promise.resolve(SciLLM.renderMechanismDiagramInMeasurableHost(diagram, {
        mermaid: globalThis.mermaid
    }))
        .then(() => {
            if (generation !== mechanismMermaidGeneration || !diagram.isConnected) return;
            diagram.querySelector('svg')?.setAttribute('aria-label', t('全文机制图'));
            applyMechanismMermaidViewMode(
                diagram, mechanismNetworkViewModeCache.get(paperKey)
            );
            bindMechanismMermaidInteractions(diagram, interactionModel);
            mechanismMermaidFocusHandoff.restore(diagram, generation);
        })
        .catch(() => {
            if (generation !== mechanismMermaidGeneration || !diagram.isConnected) return;
            diagram.classList.remove('mermaid');
            diagram.textContent = t('机制图渲染失败，节点与证据表仍可继续编辑。');
        });
    return { width: host.clientWidth || 0, height: host.scrollHeight || 0 };
}

function renderMechanismSelectionInspector(
    chain, evidenceOptions, optionsByIdentity, evidenceFigures
) {
    const inspector = document.getElementById('mechanismSelectionInspector');
    if (!inspector) return;
    inspector.replaceChildren();
    const state = mechanismNetworkViewController.getState();
    const nodes = Array.isArray(chain?.nodes) ? chain.nodes : [];
    const edges = Array.isArray(chain?.edges) ? chain.edges : [];
    const node = nodes.find(item => item.id === state.selectedNodeId);
    const edge = edges.find(item => item.id === state.selectedEdgeId);
    if (!node && !edge) {
        inspector.hidden = true;
        return;
    }
    inspector.hidden = false;
    const heading = createWorkspaceElement(
        'div', 'workspace-mechanism-inspector-heading',
        node ? t('节点设置') : t('联系设置')
    );
    const close = createWorkspaceElement('button', '', t('关闭'));
    close.type = 'button';
    close.addEventListener('click', () => {
        mechanismNetworkViewController.clear();
        renderMechanismChainWorkspace(currentWorkspaceSnapshot);
    });
    heading.appendChild(close);
    inspector.appendChild(heading);
    if (node) {
        inspector.appendChild(createWorkspaceElement(
            'p', 'workspace-mechanism-inspector-summary', node.label?.value || t('未填写节点')
        ));
        const actions = createWorkspaceElement('div', 'workspace-mechanism-inspector-actions');
        const upstream = createWorkspaceElement('button', '', t('新增上游'));
        const downstream = createWorkspaceElement('button', '', t('新增下游分支'));
        const remove = createWorkspaceElement('button', 'is-danger', t('删除节点'));
        [upstream, downstream, remove].forEach(button => { button.type = 'button'; });
        upstream.addEventListener('click', () => void mechanismNetworkViewController
            .addBranch(node.id, 'upstream'));
        downstream.addEventListener('click', () => void mechanismNetworkViewController
            .addBranch(node.id, 'downstream'));
        remove.addEventListener('click', () => void removeMechanismNode(node.id));
        actions.append(upstream, downstream, remove);
        inspector.appendChild(actions);

        const connection = createWorkspaceElement('div', 'workspace-mechanism-connection-form');
        const target = document.createElement('select');
        target.setAttribute('aria-label', t('连接到现有节点'));
        nodes.forEach(candidate => target.appendChild(new Option(
            candidate.label?.value || t('未填写节点'), candidate.id
        )));
        const polarity = document.createElement('select');
        polarity.setAttribute('aria-label', t('联系极性'));
        [['中性', 'neutral'], ['正向', 'positive'], ['负向/抑制', 'negative']]
            .forEach(([label, value]) => polarity.appendChild(new Option(t(label), value)));
        const connect = createWorkspaceElement('button', '', t('添加联系'));
        connect.type = 'button';
        connect.addEventListener('click', () => void mechanismNetworkViewController
            .addConnection(node.id, target.value, polarity.value));
        connection.append(target, polarity, connect);
        inspector.appendChild(connection);
        return;
    }

    const endpointForm = createWorkspaceElement('div', 'workspace-mechanism-endpoint-form');
    const endpointSelect = (label, field, current) => {
        const select = document.createElement('select');
        select.setAttribute('aria-label', label);
        nodes.forEach(candidate => {
            const option = new Option(candidate.label?.value || t('未填写节点'), candidate.id);
            option.selected = candidate.id === current;
            select.appendChild(option);
        });
        select.addEventListener('change', () => void safelyPersistMechanismChainMutation({
            type: 'update_mechanism_edge', edgeId: edge.id, field, value: select.value
        }));
        return select;
    };
    endpointForm.append(
        endpointSelect(t('上游节点'), 'from', edge.from),
        endpointSelect(t('下游节点'), 'to', edge.to)
    );
    const polarity = document.createElement('select');
    polarity.className = 'workspace-mechanism-polarity-select';
    polarity.setAttribute('aria-label', t('联系极性'));
    [['中性', 'neutral'], ['正向', 'positive'], ['负向/抑制', 'negative']]
        .forEach(([label, value]) => {
            const option = new Option(t(label), value);
            option.selected = value === (edge.polarity || 'neutral');
            polarity.appendChild(option);
        });
    polarity.addEventListener('change', () => void safelyPersistMechanismChainMutation({
        type: 'update_mechanism_edge', edgeId: edge.id,
        field: 'polarity', value: polarity.value
    }));
    endpointForm.appendChild(polarity);
    inspector.appendChild(endpointForm);
    appendMechanismEdgeEvidence(
        inspector, edge, evidenceOptions, optionsByIdentity, evidenceFigures
    );
    const remove = createWorkspaceElement('button', 'btn btn-danger-outline', t('删除联系'));
    remove.type = 'button';
    remove.addEventListener('click', () => void safelyPersistMechanismChainMutation({
        type: 'remove_mechanism_edge', edgeId: edge.id
    }));
    inspector.appendChild(remove);
}

function renderMechanismChainWorkspace(
    snapshot = currentWorkspaceSnapshot,
    { coordinated = false } = {}
) {
    if (!coordinated) return figureWorkspaceRenderCoordinator.request(snapshot);
    const container = document.getElementById('mechanismChainList');
    const issues = document.getElementById('mechanismChainIssues');
    if (!container || !issues) return;
    container.replaceChildren();
    issues.replaceChildren();
    refreshMechanismSectionNavigation();
    const draft = mechanismWorkspaceDraft(snapshot);
    const chain = draft?.mechanismChain || { nodes: [], edges: [] };
    const auditPresentation = mechanismWorkspaceAudit(draft);
    const pendingMechanism = snapshot?.figures?.crossFigureLogic
        ?.pendingResult?.evidenceFirstMechanism;
    if (pendingMechanism && typeof SciLLM.renderMechanismPendingPreview === 'function') {
        void Promise.resolve(SciLLM.renderMechanismPendingPreview(pendingMechanism, {
            mermaid: globalThis.mermaid, mount: issues
        })).then(section => {
            if (!section || !issues.contains(section)) return;
            prepareMechanismPendingPreviewNavigation(section, snapshot);
        });
    }
    const nodes = Array.isArray(chain.nodes) ? chain.nodes.slice(0, 64) : [];
    const edges = Array.isArray(chain.edges) ? chain.edges.slice(0, 64) : [];
    const figures = mechanismWorkspaceFigures(snapshot);
    const draftFigures = draft?.figures && typeof draft.figures === 'object'
        ? draft.figures : {};
    const evidenceFigureIds = new Set();
    const evidenceFigures = figures.map(figure => {
        const figureId = String(figure?.figureId || '');
        evidenceFigureIds.add(figureId);
        const draftPanels = draftFigures?.[figureId]?.panels;
        return {
            ...figure,
            panelHints: [...new Set([
                ...(Array.isArray(figure?.panelHints) ? figure.panelHints : []),
                ...Object.keys(draftPanels && typeof draftPanels === 'object'
                    ? draftPanels : {})
            ])].slice(0, 64)
        };
    });
    Object.values(draftFigures).slice(0, 128).forEach(figure => {
        const figureId = String(figure?.figureId || '');
        if (!figureId || evidenceFigureIds.has(figureId)) return;
        evidenceFigures.push({
            figureId,
            figureLabel: String(figure?.figureLabel || figureId),
            isSupplemental: figure?.isSupplemental === true,
            panelHints: Object.keys(figure?.panels || {}).slice(0, 64)
        });
    });
    const evidenceOptions = SciLLM.mechanismPanelEvidenceOptions(evidenceFigures);
    const optionsByIdentity = new Map(evidenceOptions.map(option => [
        `${option.figureId}\u0000${option.panelId}`, option
    ]));
    const visibleIssues = draft?.mechanismGeneration
        ? SciLLM.mechanismChainValidationIssues(
            chain, evidenceFigures, draft?.mechanismGeneration
        )
        : SciLLM.mechanismChainValidationIssues(chain, evidenceFigures);
    if (visibleIssues.length) {
        const list = createWorkspaceElement('ul', 'workspace-mechanism-validation-list');
        visibleIssues.slice(0, 16).forEach(item => list.appendChild(
            createWorkspaceElement('li', '', t(item.message || '机制链需要人工检查。'))
        ));
        issues.appendChild(list);
    }
    if (!nodes.length) {
        mechanismNetworkViewController.clear();
        renderMechanismSelectionInspector(
            chain, evidenceOptions, optionsByIdentity, evidenceFigures
        );
        const focusButton = document.getElementById('focusMechanismPath');
        if (focusButton) {
            focusButton.disabled = true;
            focusButton.setAttribute('aria-pressed', 'false');
        }
        const empty = createWorkspaceElement(
            'div', 'workspace-empty workspace-mechanism-empty',
            hasUsableLlm()
                ? t('正在等待机制链生成；也可以先新增节点，手动构建机制链。')
                : t('未配置 LLM 也可以使用：点击“新增链条节点”开始结构化记录。')
        );
        container.appendChild(empty);
        const audit = createMechanismPanelDispositionAudit(
            chain, evidenceOptions,
            snapshot?.figures?.crossFigureLogic?.result?.panelDispositions,
            new Set()
        );
        if (audit) container.appendChild(audit);
        refreshMechanismSectionNavigation();
        return;
    }
    renderMechanismNetwork(chain, container, {
        revision: Number.isSafeInteger(draft?.revision) ? draft.revision : 0,
        audit: auditPresentation,
        evidenceOptions,
        optionsByIdentity,
        evidenceFigures,
        panelDispositions: snapshot?.figures?.crossFigureLogic?.result?.panelDispositions,
        paperIdentity: mechanismNetworkPaperIdentity(snapshot?.localWorkspace)
    });
    renderMechanismSelectionInspector(
        chain, evidenceOptions, optionsByIdentity, evidenceFigures
    );
    refreshMechanismSectionNavigation();
    const focusButton = document.getElementById('focusMechanismPath');
    if (focusButton) {
        const state = mechanismNetworkViewController.getState();
        focusButton.setAttribute('aria-pressed', String(state.focusEnabled));
        focusButton.disabled = !state.selectedNodeId && !state.selectedEdgeId;
    }
}

function renderResearchLogicMapSnapshot(container, snapshot) {
    const card = createWorkspaceElement('section', 'workspace-logic-map-card');
    const header = createWorkspaceElement('div', 'workspace-logic-map-card-header');
    const copy = createWorkspaceElement('div');
    copy.append(
        createWorkspaceElement('h3', '', t('图表梳理')),
        createWorkspaceElement(
            'p', '',
            '在当前侧栏紧凑查看分支、汇合、反馈和 Panel 证据。'
        )
    );
    const draft = mechanismWorkspaceDraft(snapshot);
    const count = Array.isArray(draft?.mechanismChain?.nodes)
        ? draft.mechanismChain.nodes.length : 0;
    header.append(copy, createWorkspaceElement(
        'span', 'workspace-logic-map-count', `${count} 节点`
    ));
    const hasResult = count > 0 || Boolean(snapshot?.figures?.crossFigureLogic?.result ||
        snapshot?.figures?.crossFigureLogic?.pendingResult);
    const actions = createWorkspaceElement('div', 'workspace-logic-map-actions');
    const button = createWorkspaceElement(
        'button', 'workspace-logic-map-open', t(hasResult ? '编辑修改' : '手动绘制')
    );
    button.type = 'button';
    button.addEventListener('click', openMechanismChainWorkspace);
    const generate = createWorkspaceElement('button', 'workspace-logic-map-open',
        t(hasResult ? '重新生成' : 'AI生成'));
    generate.type = 'button';
    generate.dataset.mechanismGenerate = 'true';
    generate.disabled = crossFigureLogicRunning;
    generate.setAttribute('aria-busy', String(crossFigureLogicRunning));
    generate.addEventListener('click', () => {
        if (crossFigureLogicRunning || generate.disabled) return;
        generate.disabled = true;
        generate.setAttribute('aria-busy', 'true');
        // Existing generation owns identity checks, pending review and protection
        // of saved/manual content; never replace the chain here.
        void runCrossFigureLogic({ returnView: 'mechanism', seedMode: 'auto' })
            .finally(() => {
                generate.disabled = crossFigureLogicRunning;
                generate.setAttribute('aria-busy', String(crossFigureLogicRunning));
            }).catch(() => null);
    });
    actions.append(button, generate);
    card.append(header, actions);
    container.appendChild(card);
}

function persistFigureWorkspaceMetaMutation(
    rawMutation,
    context = captureFigureWorkspaceEditContext()
) {
    const mutation = rawMutation && typeof rawMutation === 'object'
        ? { ...rawMutation } : {};
    const contextKey = mechanismChainContextKey(context);
    if (!contextKey) return Promise.resolve({
        success: false, code: 'FIGURE_WORKSPACE_CONTEXT_INVALID'
    });
    if (!figureWorkspaceMetaSaveQueues.has(contextKey) &&
        figureWorkspaceMetaSaveQueues.size >= 16) {
        return Promise.resolve({ success: false, code: 'FIGURE_WORKSPACE_SAVE_BUSY' });
    }
    const prior = figureWorkspaceMetaSaveQueues.get(contextKey) || Promise.resolve();
    const operation = prior.catch(() => null).then(async () => {
        if (!isCurrentFigureWorkspaceEditContext(context)) return {
            success: false, stale: true,
            code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED'
        };
        const expectedRevision = Number(mechanismWorkspaceDraft()?.revision ?? 0);
        if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0) {
            throw new Error('FIGURE_WORKSPACE_REVISION_INVALID');
        }
        const response = await SciLLM.sendTabMessageWithRecovery(chrome, context.tabId, {
            action: 'updateFigureWorkspaceDraft',
            mutation: { ...mutation, expectedRevision },
            workspaceTarget: buildFigureWorkspaceEditTarget(context)
        });
        if (!response?.success || !response?.draft) {
            const error = new Error(response?.error || 'Figure 笔记结构保存失败');
            error.code = response?.code || response?.error ||
                'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED';
            throw error;
        }
        if (!isCurrentFigureWorkspaceEditContext(context)) {
            return { ...response, stale: true };
        }
        return response;
    });
    const queued = operation.catch(() => null);
    figureWorkspaceMetaSaveQueues.set(contextKey, queued);
    queued.finally(() => {
        if (figureWorkspaceMetaSaveQueues.get(contextKey) === queued) {
            figureWorkspaceMetaSaveQueues.delete(contextKey);
        }
    });
    return operation;
}

function createFigureWorkspaceMetaActionCoordinator(options) {
    options = options && typeof options === 'object' ? options : {};
    const keyForContext = typeof options.keyForContext === 'function'
        ? options.keyForContext : () => '';
    const isContextCurrent = typeof options.isContextCurrent === 'function'
        ? options.isContextCurrent : () => false;
    const persist = typeof options.persist === 'function'
        ? options.persist : async () => ({ success: false });
    const integrate = typeof options.integrate === 'function'
        ? options.integrate : () => false;
    const pending = new Map();
    return Object.freeze({
        run(rawMutation, rawContext, rawOperation = {}) {
            const mutation = rawMutation && typeof rawMutation === 'object'
                ? Object.freeze({ ...rawMutation }) : Object.freeze({});
            const context = rawContext && typeof rawContext === 'object'
                ? Object.freeze({ ...rawContext }) : Object.freeze({});
            const contextKey = String(keyForContext(context) || '').slice(0, 1000);
            if (!contextKey) return Promise.resolve({
                success: false, code: 'FIGURE_WORKSPACE_CONTEXT_INVALID'
            });
            if (pending.has(contextKey)) return Promise.resolve({
                success: false, code: 'FIGURE_WORKSPACE_META_ACTION_PENDING'
            });
            const isAttached = typeof rawOperation.isAttached === 'function'
                ? rawOperation.isAttached : () => true;
            const setDisabled = typeof rawOperation.setDisabled === 'function'
                ? rawOperation.setDisabled : () => undefined;
            const focus = typeof rawOperation.focus === 'function'
                ? rawOperation.focus : () => undefined;
            if (!isContextCurrent(context) || !isAttached()) {
                return Promise.resolve({
                    success: false, stale: true,
                    code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED'
                });
            }
            setDisabled(true);
            let persistence;
            try {
                persistence = persist(mutation, context);
            } catch (error) {
                persistence = Promise.reject(error);
            }
            const action = Promise.resolve(persistence)
                .then(response => {
                    if (!isContextCurrent(context) || !isAttached()) return {
                        ...(response || {}), success: false, stale: true,
                        code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED'
                    };
                    if (!response?.success || !response?.draft) return response;
                    integrate(response.draft, context);
                    if (!isContextCurrent(context)) return {
                        ...response, success: false, stale: true,
                        code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED'
                    };
                    focus(response);
                    return response;
                }).finally(() => {
                    if (pending.get(contextKey) === action) pending.delete(contextKey);
                    setDisabled(false);
                });
            pending.set(contextKey, action);
            return action;
        },
        getState() {
            return { pendingKeys: [...pending.keys()] };
        }
    });
}

const figureWorkspaceMetaActionCoordinator = createFigureWorkspaceMetaActionCoordinator({
    keyForContext: mechanismChainContextKey,
    isContextCurrent: isCurrentFigureWorkspaceEditContext,
    persist: persistFigureWorkspaceMetaMutation,
    integrate: integrateMechanismChainDraft
});

async function safelyPersistFigureWorkspaceMetaMutation(
    mutation,
    context = captureFigureWorkspaceEditContext(),
    operation = {}
) {
    if (figureWorkspaceInlineEditController.getState()?.active) {
        const flushed = await figureWorkspaceInlineEditController.flush('meta-action');
        if (!['saved', 'unchanged', 'idle'].includes(flushed?.status)) {
            return { success: false, code: 'FIGURE_WORKSPACE_ACTIVE_EDIT_NOT_SAVED' };
        }
    }
    try {
        const response = await figureWorkspaceMetaActionCoordinator.run(
            mutation, context, operation
        );
        if (response?.code === 'FIGURE_WORKSPACE_META_ACTION_PENDING') return response;
        if (response?.success === false) {
            const error = new Error(response.code || 'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED');
            error.code = response.code || 'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED';
            throw error;
        }
        return response;
    } catch (_) {
        if (isCurrentFigureWorkspaceEditContext(context)) {
            showStatus('背景或科学问题保存失败；输入已保留，请重试。', 'error');
        }
        return { success: false, code: 'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED' };
    }
}

function createFigureWorkspaceMetaActionOperation(source, focus) {
    const buttons = Array.from(document.querySelectorAll(
        '.workspace-figure-meta-add, .workspace-figure-meta-remove'
    ));
    const disabled = new Map(buttons.map(button => [button, button.disabled === true]));
    return {
        isAttached: () => source?.isConnected === true,
        setDisabled(value) {
            buttons.forEach(button => {
                if (!button?.isConnected) return;
                button.disabled = value === true ? true : disabled.get(button) === true;
            });
        },
        focus
    };
}

function focusFigureWorkspaceMetaMutation(collection, index, context) {
    requestAnimationFrame(() => {
        if (!isCurrentFigureWorkspaceEditContext(context)) return;
        const boundedIndex = Math.max(0, Math.min(63, Number(index) || 0));
        const target = document.getElementById(
            `figure-meta-edit-${collection}-${boundedIndex}`
        ) || document.querySelector(
            `.workspace-figure-meta-add[data-meta-collection="${collection}"]`
        );
        if (target?.isConnected && typeof target.focus === 'function') target.focus();
    });
}

function scientificQuestionRelationLabel(value) {
    return ({
        root: '总问题',
        progressive: '递进',
        parallel: '并列',
        branch: '分支',
        convergent: '汇合',
        validation: '验证'
    })[String(value || '').trim().toLowerCase()] || '总问题';
}

function buildScientificQuestionRelationMutationValue(
    item,
    relationType,
    parentQuestionIds
) {
    const allowed = new Set([
        'root', 'progressive', 'parallel', 'branch', 'convergent', 'validation'
    ]);
    const questionId = String(item?.questionId || '').trim();
    const relation = allowed.has(String(relationType || '').trim().toLowerCase())
        ? String(relationType).trim().toLowerCase() : 'root';
    const parents = relation === 'root' ? [] : [...new Set(
        (Array.isArray(parentQuestionIds) ? parentQuestionIds : [])
            .map(value => String(value || '').trim())
            .filter(value => value && value !== questionId)
    )];
    const text = String(item?.text ?? item?.value ?? '');
    return {
        questionId,
        text,
        value: text,
        relationType: relation,
        parentQuestionIds: parents,
        supportingFigureIds: [...new Set(
            (Array.isArray(item?.supportingFigureIds) ? item.supportingFigureIds : [])
                .map(value => String(value || '').trim()).filter(Boolean)
        )]
    };
}

function paperMetaSourceRefsForEvidenceIds(logic, evidenceIds) {
    const wanted = new Set(Array.isArray(evidenceIds) ? evidenceIds : []);
    const refs = [];
    const seen = new Set();
    (Array.isArray(logic?.atomicEvidence) ? logic.atomicEvidence : []).forEach(atom => {
        if (!wanted.has(atom?.evidenceId)) return;
        (Array.isArray(atom?.sourceRefs) ? atom.sourceRefs : []).forEach(ref => {
            const key = `${ref?.paragraphId || ''}|${ref?.sourceIdentity || ''}|${ref?.quote || ''}`;
            if (!key.replace(/\|/g, '') || seen.has(key)) return;
            seen.add(key);
            refs.push(ref);
        });
    });
    return refs.slice(0, 16);
}

function appendPaperMetaSourceChips(container, refs, startAt = 1) {
    (Array.isArray(refs) ? refs : []).forEach((ref, index) => {
        const button = createWorkspaceElement(
            'button', 'article-chat-inline-citation research-logic-source-chip',
            String(startAt + index)
        );
        button.type = 'button';
        button.title = String(ref?.quote || '定位正文证据').slice(0, 240);
        button.setAttribute('aria-label', `定位正文证据 ${startAt + index}`);
        button.addEventListener('click', async () => {
            const panelContext = capturePanelContext();
            button.disabled = true;
            try {
                const response = await sendTabMessage(panelContext.tabId, {
                    action: 'focusArticleWorkspaceSource',
                    target: {
                        kind: 'paragraph',
                        paragraphId: String(ref?.paragraphId || ''),
                        sourceIdentity: String(ref?.sourceIdentity || ''),
                        sourceKey: String(ref?.sourceKey || ''),
                        textHash: String(ref?.textHash || ''),
                        quote: String(ref?.quote || '')
                    }
                });
                if (!response?.success || !response?.focused) {
                    showStatus('未能定位这条正文证据；页面可能刚刚更新。', 'error');
                }
            } finally {
                if (button.isConnected) button.disabled = false;
            }
        });
        container.appendChild(button);
    });
}

function renderResearchLogicTabs(container, logic) {
    const core = logic?.questionTrace?.coreQuestion;
    if (!core) return;
    const card = createWorkspaceElement('section', 'research-logic-card');
    card.setAttribute('aria-label', '研究逻辑分层结果');
    const tabDefinitions = [
        ['core', '核心问题'],
        ['why', '为什么值得问'],
        ['progression', '论文如何推进'],
        ['audit', '证据强度']
    ];
    const tablist = createWorkspaceElement('div', 'research-logic-tabs');
    tablist.setAttribute('role', 'tablist');
    const panels = new Map();
    const selectTab = key => {
        activeResearchLogicTab = tabDefinitions.some(([id]) => id === key) ? key : 'core';
        tablist.querySelectorAll('[role="tab"]').forEach(button => {
            const selected = button.dataset.researchTab === activeResearchLogicTab;
            button.setAttribute('aria-selected', String(selected));
            button.tabIndex = selected ? 0 : -1;
        });
        panels.forEach((panel, id) => { panel.hidden = id !== activeResearchLogicTab; });
    };
    tabDefinitions.forEach(([key, label]) => {
        const button = createWorkspaceElement('button', '', label);
        button.type = 'button';
        button.dataset.researchTab = key;
        button.setAttribute('role', 'tab');
        button.addEventListener('click', () => selectTab(key));
        tablist.appendChild(button);
    });
    card.appendChild(tablist);

    const corePanel = createWorkspaceElement('div', 'research-logic-panel');
    corePanel.setAttribute('role', 'tabpanel');
    corePanel.appendChild(createWorkspaceElement('span', 'research-logic-node-label', 'Q0 · 论文核心问题'));
    corePanel.appendChild(createWorkspaceElement('h4', '', String(core.text || '')));
    if (core.authorWording) {
        corePanel.appendChild(createWorkspaceElement(
            'p', 'research-logic-author-wording', `作者表述：${core.authorWording}`
        ));
    }
    const coreMeta = createWorkspaceElement(
        'p', 'research-logic-meta',
        `${core.origin === 'author_explicit' ? '作者明确' : 'Brevess 重构'} · ` +
        `置信度 ${core.confidence || '未知'} · ` +
        `${(core.evidenceIds || []).length} 个证据原子`
    );
    appendPaperMetaSourceChips(
        coreMeta, paperMetaSourceRefsForEvidenceIds(logic, core.evidenceIds)
    );
    corePanel.appendChild(coreMeta);
    panels.set('core', corePanel);

    const whyPanel = createWorkspaceElement('div', 'research-logic-panel research-logic-trace');
    whyPanel.setAttribute('role', 'tabpanel');
    const evidenceById = new Map((logic.atomicEvidence || []).map(item => [item.evidenceId, item]));
    (logic.questionTrace?.bridge || []).forEach((step, index) => {
        const node = createWorkspaceElement('article', 'research-logic-trace-node');
        node.appendChild(createWorkspaceElement(
            'span', 'research-logic-node-label', `${step.type}${index + 1}`
        ));
        const statements = (step.evidenceIds || []).map(id => evidenceById.get(id)?.statement)
            .filter(Boolean);
        node.appendChild(createWorkspaceElement(
            'p', '', step.statement || statements.join('；') || '证据待补充'
        ));
        const meta = createWorkspaceElement('small', '',
            step.origin === 'author_explicit' ? '作者明确' : 'Brevess 重构');
        appendPaperMetaSourceChips(
            meta, paperMetaSourceRefsForEvidenceIds(logic, step.evidenceIds)
        );
        node.appendChild(meta);
        whyPanel.appendChild(node);
    });
    panels.set('why', whyPanel);

    const progressionPanel = createWorkspaceElement(
        'div', 'research-logic-panel research-logic-progression'
    );
    progressionPanel.setAttribute('role', 'tabpanel');
    (logic.progression || []).forEach(question => {
        const node = createWorkspaceElement('article', 'research-logic-progression-node');
        node.appendChild(createWorkspaceElement(
            'span', 'research-logic-node-label',
            `${question.questionId} · 来自 ${(question.generatedFrom || []).join('、') || 'Q0'}`
        ));
        node.appendChild(createWorkspaceElement('h4', '', question.text));
        const rows = [
            ['假设', question.hypothesis], ['如何检验', question.test],
            ['得到什么', question.result], ['允许得出的结论', question.warrantedConclusion],
            ['仍未解决', question.remainingGap]
        ];
        rows.filter(([, value]) => value).forEach(([label, value]) => {
            const row = createWorkspaceElement('p', 'research-logic-progress-row');
            row.append(
                createWorkspaceElement('strong', '', `${label}：`),
                document.createTextNode(String(value))
            );
            node.appendChild(row);
        });
        const meta = createWorkspaceElement(
            'small', '', `证据等级：${question.causalLevel || '待核验'}`
        );
        appendPaperMetaSourceChips(
            meta, paperMetaSourceRefsForEvidenceIds(logic, question.evidenceIds)
        );
        node.appendChild(meta);
        progressionPanel.appendChild(node);
    });
    panels.set('progression', progressionPanel);

    const auditPanel = createWorkspaceElement('div', 'research-logic-panel');
    auditPanel.setAttribute('role', 'tabpanel');
    auditPanel.appendChild(createWorkspaceElement(
        'p', logic.audit?.validCoreQuestion ? 'research-logic-audit-ok' : 'research-logic-audit-warning',
        logic.audit?.validCoreQuestion
            ? `Q0 已通过来源与结果泄漏检查；覆盖 ${logic.audit?.evidenceCoverage || logic.atomicEvidence?.length || 0} 个证据原子。`
            : 'Q0 仍需人工核验，当前不会将其当作确定结论。'
    ));
    const issues = Array.isArray(logic.audit?.issues) ? logic.audit.issues : [];
    if (issues.length) {
        const list = createWorkspaceElement('ul', 'research-logic-audit-list');
        issues.forEach(issue => list.appendChild(createWorkspaceElement('li', '', issue)));
        auditPanel.appendChild(list);
    }
    panels.set('audit', auditPanel);
    panels.forEach(panel => card.appendChild(panel));
    selectTab(activeResearchLogicTab);
    container.appendChild(card);
}

function paperMetaTaskButtonLabel(state = {}, fallbackLabel = '') {
    const changedFields = Math.max(0, Number(state.changedFields) || 0);
    if (state.running) {
        if (state.phase === 'saving') {
            return changedFields
                ? `已取得 ${changedFields} 项，正在保存`
                : '正文已核对，正在保存';
        }
        if (state.phase === 'integrating') return '已收到结果，正在核对正文证据';
        return '正在提取正文证据…';
    }
    if (state.phase === 'complete') {
        return changedFields ? `已保存 ${changedFields} 项` : '正文已核对，无新增项';
    }
    if (state.phase === 'failed') return '提取失败，点击重试';
    return fallbackLabel;
}

function updatePaperMetaTaskButtons(taskKind) {
    const state = paperMetaTaskState[taskKind];
    if (!state) return;
    document.querySelectorAll(`[data-paper-meta-task="${taskKind}"]`).forEach(button => {
        const fallbackLabel = String(button.dataset.defaultLabel || button.textContent || '');
        button.dataset.defaultLabel ||= fallbackLabel;
        button.textContent = paperMetaTaskButtonLabel(state, button.dataset.defaultLabel);
        button.disabled = state.running === true;
        button.classList.toggle('is-llm-pending', state.running === true);
        button.setAttribute('aria-busy', String(state.running === true));
    });
}

function createPaperMetaTaskButton(taskKind, label) {
    const state = paperMetaTaskState[taskKind];
    const button = createWorkspaceElement(
        'button', 'literature-note-paper-meta-extract',
        paperMetaTaskButtonLabel(state, label)
    );
    button.type = 'button';
    button.dataset.paperMetaTask = taskKind;
    button.dataset.defaultLabel = label;
    button.disabled = state?.running === true;
    button.classList.toggle('is-llm-pending', state?.running === true);
    button.setAttribute('aria-busy', String(state?.running === true));
    button.addEventListener('click', () => void runPaperMetaExtraction(taskKind));
    return button;
}

function renderFigureWorkspaceMetaSnapshot(container, draft, { placement = 'header' } = {}) {
    if (!container) return;
    const meta = draft?.meta && typeof draft.meta === 'object' ? draft.meta : {};
    if (placement === 'header') {
        const actions = createWorkspaceElement('div', 'workspace-paper-meta-actions');
        actions.append(
            createPaperMetaTaskButton('research_logic', '提取研究背景与科学问题'),
            createWorkspaceElement(
                'p', '', '不需要先解图；按正文证据生成 Q0 与 Q1–Q4 推进链。'
            )
        );
        container.appendChild(actions);
        renderResearchLogicTabs(container, meta.researchLogic);
    }
    const definitions = [
        {
            collection: 'backgroundItems', title: '研究背景',
            kind: 'research background', addType: 'add_background_item',
            removeType: 'remove_background_item', itemLabel: '背景'
        },
        {
            collection: 'scientificQuestions', title: '科学问题',
            kind: 'scientific question', addType: 'add_scientific_question',
            removeType: 'remove_scientific_question', itemLabel: '问题'
        },
        {
            collection: 'innovationPoints', title: '全文创新点',
            kind: 'paper innovation', addType: 'add_innovation_point',
            removeType: 'remove_innovation_point', itemLabel: '创新点', placement: 'footer',
            extractionTask: 'innovation', extractionLabel: '提取创新点'
        },
        {
            collection: 'limitationPoints', title: '研究局限',
            kind: 'paper limitation', addType: 'add_limitation_point',
            removeType: 'remove_limitation_point', itemLabel: '局限', placement: 'footer',
            extractionTask: 'limitations', extractionLabel: '提取研究局限'
        }
    ].filter(definition => (definition.placement || 'header') === placement);
    definitions.forEach(definition => {
        const collection = definition.collection;
        const items = Array.isArray(meta[collection])
            ? meta[collection].slice(0, 64) : [];
        const details = createWorkspaceElement('details', 'workspace-figure-meta-card');
        details.dataset.metaKind = definition.kind;
        details.open = figureMetaExpansionState.get(collection) === true;
        details.addEventListener('toggle', () => {
            figureMetaExpansionState.set(collection, details.open);
            scheduleActiveWorkspaceUiStateSave();
        });
        const summary = createWorkspaceElement('summary', 'workspace-figure-meta-summary');
        summary.append(
            createWorkspaceElement('strong', '', definition.title),
            createWorkspaceElement('span', '', `${items.length} 条`)
        );
        details.appendChild(summary);
        if (definition.extractionTask) {
            const taskRow = createWorkspaceElement('div', 'workspace-paper-meta-block-action');
            taskRow.appendChild(createPaperMetaTaskButton(
                definition.extractionTask, definition.extractionLabel
            ));
            details.appendChild(taskRow);
        }
        const list = createWorkspaceElement('ol', 'workspace-figure-meta-list');
        if (!items.length) {
            const empty = createWorkspaceElement(
                'li', 'workspace-figure-empty-value',
                '尚未生成；可点击下方新增后填写。'
            );
            empty.dataset.metaEmpty = collection;
            list.appendChild(empty);
        }
        items.forEach((item, index) => {
            const row = createWorkspaceElement('li', 'workspace-figure-meta-item');
            const descriptor = {
                scope: 'meta', collection, index, field: 'value'
            };
            const target = createWorkspaceElement('div', 'workspace-figure-edit-target');
            target.id = `figure-meta-edit-${collection}-${index}`;
            target.dataset.figureEditPath = figureWorkspaceEditDescriptorKey(descriptor);
            target.tabIndex = 0;
            target.setAttribute('role', 'button');
            target.setAttribute('aria-label',
                `${definition.itemLabel} ${index + 1}：双击或按 Enter 编辑`);
            const value = String(item?.value || '');
            target.appendChild(createWorkspaceElement(
                'span', value ? 'workspace-figure-view-value' : 'workspace-figure-empty-value',
                value || '双击填写'
            ));
            const edit = () => void openFigureWorkspaceInlineEditor(
                target, descriptor, value,
                `${definition.title} ${index + 1}`, false
            );
            target.addEventListener('dblclick', edit);
            target.addEventListener('keydown', event => {
                if (event.key !== 'Enter' && event.key !== ' ') return;
                event.preventDefault();
                edit();
            });
            const remove = createWorkspaceElement(
                'button', 'workspace-figure-meta-remove', '删除'
            );
            remove.type = 'button';
            remove.setAttribute('aria-label', `删除${definition.itemLabel} ${index + 1}`);
            remove.addEventListener('click', () => {
                const context = captureFigureWorkspaceEditContext();
                const focusIndex = Math.min(index, Math.max(0, items.length - 2));
                void safelyPersistFigureWorkspaceMetaMutation({
                    type: definition.removeType, index
                }, context, createFigureWorkspaceMetaActionOperation(
                    remove,
                    () => focusFigureWorkspaceMetaMutation(collection, focusIndex, context)
                ));
            });
            let primary = target;
            if (collection === 'scientificQuestions') {
                const question = item && typeof item === 'object' ? item : {};
                const wrapper = createWorkspaceElement('div', 'workspace-figure-meta-question');
                wrapper.appendChild(target);
                const questionById = new Map(items.map(candidate => [
                    String(candidate?.questionId || ''),
                    String(candidate?.value || candidate?.text || candidate?.questionId || '')
                ]));
                const parents = (Array.isArray(question.parentQuestionIds)
                    ? question.parentQuestionIds : []).filter(Boolean);
                const figures = (Array.isArray(question.supportingFigureIds)
                    ? question.supportingFigureIds : []).filter(Boolean);
                const metadata = createWorkspaceElement(
                    'p', 'workspace-figure-view-value',
                    `关系：${scientificQuestionRelationLabel(question.relationType)}；` +
                    `上游：${parents.map(parentId => questionById.get(parentId) || parentId)
                        .join('、') || '无'}；` +
                    `支持 Figure：${figures.join('、') || '待补充'}`
                );
                wrapper.appendChild(metadata);

                const relationEditor = createWorkspaceElement(
                    'details', 'workspace-figure-meta-card'
                );
                relationEditor.appendChild(createWorkspaceElement(
                    'summary', 'workspace-figure-meta-summary', '修改问题关系'
                ));
                const relationSelect = createWorkspaceElement(
                    'select', 'workspace-scientific-question-relation'
                );
                [
                    ['root', '总问题'], ['progressive', '递进'],
                    ['parallel', '并列'], ['branch', '分支'],
                    ['convergent', '汇合'], ['validation', '验证']
                ].forEach(([optionValue, optionLabel]) => {
                    const option = document.createElement('option');
                    option.value = optionValue;
                    option.textContent = optionLabel;
                    relationSelect.appendChild(option);
                });
                relationSelect.value = String(question.relationType || 'root');
                const parentChoices = createWorkspaceElement(
                    'div', 'question-link-grid'
                );
                items.slice(0, index).forEach(candidate => {
                    const parentId = String(candidate?.questionId || '');
                    if (!parentId) return;
                    const label = document.createElement('label');
                    const checkbox = document.createElement('input');
                    checkbox.type = 'checkbox';
                    checkbox.className = 'workspace-scientific-question-parent';
                    checkbox.value = parentId;
                    checkbox.checked = parents.includes(parentId);
                    label.append(
                        checkbox,
                        document.createTextNode(
                            String(candidate?.value || candidate?.text || parentId)
                        )
                    );
                    parentChoices.appendChild(label);
                });
                const saveRelation = createWorkspaceElement(
                    'button', 'workspace-figure-meta-add', '保存关系'
                );
                saveRelation.type = 'button';
                const updateSaveAvailability = () => {
                    const checked = parentChoices.querySelectorAll('input:checked').length;
                    saveRelation.disabled = relationSelect.value === 'convergent'
                        ? checked < 2
                        : relationSelect.value !== 'root' && checked < 1;
                };
                relationSelect.addEventListener('change', updateSaveAvailability);
                parentChoices.addEventListener('change', updateSaveAvailability);
                updateSaveAvailability();
                saveRelation.addEventListener('click', () => {
                    const context = captureFigureWorkspaceEditContext();
                    const parentQuestionIds = Array.from(
                        parentChoices.querySelectorAll('input:checked')
                    ).map(input => input.value);
                    const baseOperation = createFigureWorkspaceMetaActionOperation(
                        saveRelation,
                        () => focusFigureWorkspaceMetaMutation(collection, index, context)
                    );
                    void safelyPersistFigureWorkspaceMetaMutation({
                        type: 'update_scientific_question',
                        index,
                        value: buildScientificQuestionRelationMutationValue(
                            question, relationSelect.value, parentQuestionIds
                        )
                    }, context, {
                        ...baseOperation,
                        setDisabled(disabled) {
                            relationSelect.disabled = disabled;
                            parentChoices.querySelectorAll('input').forEach(input => {
                                input.disabled = disabled;
                            });
                            saveRelation.disabled = disabled;
                            baseOperation.setDisabled(disabled);
                            if (!disabled) updateSaveAvailability();
                        }
                    });
                });
                relationEditor.append(
                    relationSelect,
                    parentChoices.childElementCount
                        ? parentChoices
                        : createWorkspaceElement(
                            'p', 'workspace-figure-empty-value', '当前没有可作为上游的问题'
                        ),
                    saveRelation
                );
                wrapper.appendChild(relationEditor);
                primary = wrapper;
            }
            row.append(primary, remove);
            list.appendChild(row);
        });
        const add = createWorkspaceElement(
            'button', 'workspace-figure-meta-add', `新增${definition.itemLabel}`
        );
        add.type = 'button';
        add.dataset.metaCollection = collection;
        add.disabled = items.length >= 64;
        add.addEventListener('click', () => {
            const context = captureFigureWorkspaceEditContext();
            void safelyPersistFigureWorkspaceMetaMutation({
                type: definition.addType, value: ''
            }, context, createFigureWorkspaceMetaActionOperation(
                add,
                () => focusFigureWorkspaceMetaMutation(collection, items.length, context)
            ));
        });
        details.append(list, add);
        container.appendChild(details);
    });
}

function syncFigureQuickNavFromScroll() {
    const view = document.querySelector('.workspace-view[data-workspace-view="figures"]');
    if (!view || view.hidden) return;
    const cards = Array.from(view.querySelectorAll('.workspace-figure-card[data-figure-id]'));
    if (!cards.length) return;
    const viewTop = view.getBoundingClientRect().top + 24;
    const closest = cards.reduce((best, card) => {
        const distance = Math.abs(card.getBoundingClientRect().top - viewTop);
        return !best || distance < best.distance ? { card, distance } : best;
    }, null)?.card;
    const figureId = closest?.dataset.figureId || '';
    if (!figureId || figureId === figureQuickNavActiveId) return;
    figureQuickNavActiveId = figureId;
    document.querySelectorAll('#figureQuickNav .figure-quick-nav-marker').forEach(marker => {
        const owner = marker.closest('.figure-quick-nav-item');
        marker.setAttribute('aria-current', String(owner?.dataset.figureId === figureId));
    });
}

function renderSupplementalFigureCoverage(snapshot = currentWorkspaceSnapshot) {
    const container = document.getElementById('supplementalFigureCoverage');
    const body = document.getElementById('supplementalFigureCoverageBody');
    const toggleSummary = document.getElementById('supplementalFigureCoverageSummary');
    if (!container || !body || !toggleSummary) return;
    let importTarget = null;
    try {
        importTarget = supplementalFigureImportTools.buildTarget(
            snapshot,
            activePanelTabContext.tabId,
            preparedDocumentState?.documentHash || manualAnnotationState.documentHash
        );
    } catch (_) {}
    const supplemental = snapshot?.figures?.supplemental || {};
    const coverage = supplemental.coverage || null;
    const materials = Array.isArray(supplemental.materials)
        ? supplemental.materials : [];
    const references = Array.isArray(supplemental.references)
        ? supplemental.references : [];
    const shouldShow = Boolean(
        supplemental.binding || materials.length || references.length ||
        Number(coverage?.foundFigureCount) > 0
    );
    container.hidden = !shouldShow;
    body.replaceChildren();
    if (!shouldShow) return;

    const status = String(coverage?.status || 'unparsed');
    const statusLabels = {
        complete: '覆盖完整',
        found: '已找到，待补全解读',
        partial: '仍有缺失',
        unparsed: '等待解析',
        none: '未发现引用'
    };
    const missingCount = Array.isArray(coverage?.missingFigureLabels)
        ? coverage.missingFigureLabels.length : 0;
    toggleSummary.textContent = supplemental.binding
        ? (statusLabels[status] || '等待解析')
        : `${statusLabels[status] || '等待解析'}${missingCount ? ` · 缺 ${missingCount} 张` : ''}`;
    const badge = createWorkspaceElement(
        'span',
        `supplemental-coverage-badge is-${status}`,
        statusLabels[status] || '等待解析'
    );
    const expandedStatus = createWorkspaceElement('div', 'supplemental-coverage-header');
    expandedStatus.appendChild(badge);
    body.appendChild(expandedStatus);

    if (supplemental.binding) {
        const sync = supplemental.parentSync || {};
        body.appendChild(createWorkspaceElement(
            'p',
            `supplemental-coverage-summary${sync.status === 'error' ? ' is-error' : ''}`,
            sync.status === 'synced'
                ? '补充图目录已同步回原论文；后续解图结果也会持续更新。'
                : sync.status === 'error'
                    ? `同步回原论文失败：${sync.error || '请重试保存'}`
                    : 'PDF 解析完成后，补充图会自动同步回原论文工作区。'
        ));
        return;
    }

    const expected = Number(coverage?.expectedFigureCount) || 0;
    const found = Number(coverage?.foundFigureCount) || 0;
    const analyzed = Number(coverage?.analyzedFigureCount) || 0;
    body.appendChild(createWorkspaceElement(
        'p',
        'supplemental-coverage-summary',
        `正文提及 ${expected} 张补充图；已纳入 ${found} 张，其中 ${analyzed} 张已解读。`
    ));
    if (Array.isArray(coverage?.missingFigureLabels) &&
        coverage.missingFigureLabels.length) {
        body.appendChild(createWorkspaceElement(
            'p',
            'supplemental-coverage-missing',
            `尚缺：${coverage.missingFigureLabels.join('、')}`
        ));
    }
    if (supplemental.logicRefreshRequired) {
        body.appendChild(createWorkspaceElement(
            'p',
            'supplemental-coverage-hint is-action',
            supplemental.logicRefreshRequired
        ));
    }

    const pdfMaterials = materials.filter(material =>
        ['pdf', 'attachment'].includes(material?.kind) && material?.url
    );
    if (pdfMaterials.length) {
        const list = createWorkspaceElement('div', 'supplemental-material-list');
        pdfMaterials.slice(0, 12).forEach(material => {
            const row = createWorkspaceElement('div', 'supplemental-material-row');
            const label = createWorkspaceElement(
                'span', 'supplemental-material-label',
                material.title || '补充材料 PDF'
            );
            const action = createWorkspaceElement(
                'button', 'btn btn-secondary supplemental-material-action',
                '下载后选择 PDF'
            );
            action.type = 'button';
            action.addEventListener('click', () =>
                void openSupplementalMaterialPdf(material, importTarget)
                    .catch(error => showStatus(error.message, 'error'))
            );
            row.append(label, action);
            list.appendChild(row);
        });
        body.appendChild(list);
    } else if (expected > found) {
        body.appendChild(createWorkspaceElement(
            'p',
            'supplemental-coverage-hint',
            '请先手动下载补充材料，再选择本地 PDF；插件不会自动下载或代传期刊附件。'
        ));
        const localAction = createWorkspaceElement(
            'button',
            'btn btn-secondary supplemental-material-local-action',
            '选择本地补充 PDF'
        );
        localAction.type = 'button';
        localAction.addEventListener('click', () =>
            void openSupplementalMaterialPdf({
                materialId: `manual-supplement-${Date.now()}`,
                title: '本地补充材料 PDF',
                url: ''
            }, importTarget).catch(error => showStatus(error.message, 'error'))
        );
        body.appendChild(localAction);
    }
}

function disposeSupplementalPlacementBindings() {
    [...supplementalPlacementBindingCleanups].forEach(cleanup => {
        try { cleanup(); } catch (_) {}
    });
    supplementalPlacementBindingCleanups.clear();
}

function cancelActiveSupplementalPlacementDrag(reason = 'cancelled') {
    const cleanup = activeSupplementalPlacementCleanup;
    if (!cleanup) return;
    activeSupplementalPlacementCleanup = null;
    cleanup(reason);
}

function integrateSupplementalPlacementDraft(draft, context) {
    if (!draft || !currentWorkspaceSnapshot ||
        !isCurrentFigureWorkspaceEditContext(context)) return false;
    const returnedRevision = Number(draft.revision);
    const liveRevision = Number(
        currentWorkspaceSnapshot?.figures?.draft?.revision ??
        currentWorkspaceSnapshot?.figureWorkspaceDraft?.revision ?? 0
    );
    if (!Number.isSafeInteger(returnedRevision) || returnedRevision < liveRevision) {
        return false;
    }
    currentWorkspaceSnapshot = {
        ...currentWorkspaceSnapshot,
        figureWorkspaceDraft: draft,
        figures: { ...(currentWorkspaceSnapshot.figures || {}), draft }
    };
    figureWorkspaceRenderCoordinator.request(currentWorkspaceSnapshot);
    return true;
}

function persistSupplementalFigurePlacements(
    placements,
    context = captureFigureWorkspaceEditContext()
) {
    const normalizedPlacements = SciLLM.normalizeSupplementalPlacements(placements);
    const operation = supplementalPlacementSaveQueue.catch(() => null).then(async () => {
        if (!isCurrentFigureWorkspaceEditContext(context)) {
            return { success: false, stale: true, code: 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED' };
        }
        const expectedRevision = Number(
            currentWorkspaceSnapshot?.figures?.draft?.revision ??
            currentWorkspaceSnapshot?.figureWorkspaceDraft?.revision ?? 0
        );
        if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0) {
            throw new Error('FIGURE_WORKSPACE_REVISION_INVALID');
        }
        const mutation = {
            type: 'set_supplemental_placements', expectedRevision,
            placements: normalizedPlacements
        };
        const response = await SciLLM.sendTabMessageWithRecovery(chrome, context.tabId, {
            action: 'updateFigureWorkspaceDraft', mutation,
            workspaceTarget: buildFigureWorkspaceEditTarget(context)
        });
        if (!response?.success || !response?.draft) {
            const error = new Error(response?.error || '补充图位置保存失败');
            error.code = response?.code || response?.error ||
                'FIGURE_WORKSPACE_DRAFT_SAVE_FAILED';
            throw error;
        }
        if (!isCurrentFigureWorkspaceEditContext(context)) {
            return { ...response, stale: true };
        }
        integrateSupplementalPlacementDraft(response.draft, context);
        return response;
    });
    supplementalPlacementSaveQueue = operation.catch(() => null);
    return operation;
}

function supplementalPlacementForMove(figureId, direction, orderedFigures) {
    const items = Array.isArray(orderedFigures) ? orderedFigures.slice(0, 128) : [];
    const identities = items.map(item => String(item?.figureId || ''));
    if (identities.some((id, index) => !id || identities.indexOf(id) !== index)) return null;
    const index = items.findIndex(item =>
        item?.isSupplemental === true && String(item?.figureId || '') === String(figureId || '')
    );
    const delta = direction < 0 ? -1 : direction > 0 ? 1 : 0;
    const destination = index + delta;
    if (index < 0 || !delta || destination < 0 || destination >= items.length) return null;
    const [item] = items.splice(index, 1);
    items.splice(destination, 0, item);
    return supplementalPlacementsFromOrder(items);
}

function supplementalPlacementsFromOrder(orderedFigures) {
    const items = Array.isArray(orderedFigures) ? orderedFigures.slice(0, 128) : [];
    const identities = items.map(item => String(item?.figureId || ''));
    if (identities.some((id, index) => !id || identities.indexOf(id) !== index)) return null;
    const placements = [];
    const ranks = new Map();
    let slot = 0;
    items.forEach(figure => {
        if (figure?.isSupplemental !== true) {
            slot += 1;
            return;
        }
        const figureId = String(figure?.figureId || '');
        if (!figureId) return;
        const rank = ranks.get(slot) || 0;
        ranks.set(slot, rank + 1);
        placements.push({ figureId, slot, rank });
    });
    return SciLLM.normalizeSupplementalPlacements(placements);
}

function supplementalDropOrder(figureId, orderedFigures, cards, clientY) {
    const items = Array.isArray(orderedFigures) ? orderedFigures.slice(0, 128) : [];
    const identities = items.map(item => String(item?.figureId || ''));
    if (identities.some((id, index) => !id || identities.indexOf(id) !== index)) return null;
    const itemById = new Map(items
        .map(item => [String(item?.figureId || ''), item]));
    const target = itemById.get(String(figureId || ''));
    if (!target?.isSupplemental) return null;
    const remaining = items
        .filter(item => String(item?.figureId || '') !== String(figureId || ''));
    const visibleCards = (Array.isArray(cards) ? cards : [])
        .filter(card => card?.isConnected !== false &&
            String(card?.dataset?.figureId || '') !== String(figureId || ''));
    let insertion = visibleCards.length;
    for (let index = 0; index < visibleCards.length; index += 1) {
        const rect = visibleCards[index].getBoundingClientRect();
        if (Number(clientY) < rect.top + rect.height / 2) {
            insertion = index;
            break;
        }
    }
    remaining.splice(Math.max(0, Math.min(remaining.length, insertion)), 0, target);
    return { ordered: remaining, insertion, cards: visibleCards };
}

function bindSupplementalFigurePlacementInteractions({
    summary, card, actions, figure, displayFigures, container
}) {
    if (!summary || !card || !actions || figure?.isSupplemental !== true) return;
    let ghost = null;
    let dropLine = null;
    let context = null;
    let suppressClick = false;
    let currentDropOrder = null;
    let disposed = false;
    let cancelDrag = null;
    let clickReleaseTimer = null;
    let capturedPointerId = null;
    let ownsRenderLock = false;
    const originalTouchAction = summary.style.touchAction;

    const cards = () => Array.from(
        container.querySelectorAll(':scope > .workspace-figure-card[data-figure-id]')
    );
    const positionDragArtifacts = event => {
        if (ghost) {
            ghost.style.left = `${Math.max(8, Number(event?.clientX) + 12 || 8)}px`;
            ghost.style.top = `${Math.max(8, Number(event?.clientY) + 12 || 8)}px`;
        }
        currentDropOrder = supplementalDropOrder(
            figure.figureId, displayFigures, cards(), event?.clientY
        );
        if (!dropLine || !currentDropOrder) return;
        const reference = currentDropOrder.cards[currentDropOrder.insertion] ||
            currentDropOrder.cards.at(-1);
        if (!reference) return;
        const rect = reference.getBoundingClientRect();
        const afterLast = currentDropOrder.insertion >= currentDropOrder.cards.length;
        dropLine.style.left = `${rect.left}px`;
        dropLine.style.width = `${rect.width}px`;
        dropLine.style.top = `${afterLast ? rect.bottom : rect.top}px`;
    };
    const cleanupActive = () => {
        try { card.classList.remove('is-placement-dragging'); } catch (_) {}
        try { ghost?.remove(); } catch (_) {}
        try { dropLine?.remove(); } catch (_) {}
        ghost = null;
        dropLine = null;
        currentDropOrder = null;
        if (capturedPointerId !== null) {
            tryReleaseSupplementalPointerCapture(summary, capturedPointerId);
            capturedPointerId = null;
        }
        try { summary.style.touchAction = originalTouchAction; } catch (_) {}
        if (activeSupplementalPlacementCleanup === cancelDrag) {
            activeSupplementalPlacementCleanup = null;
        }
        if (ownsRenderLock) {
            ownsRenderLock = false;
            try { figureWorkspaceRenderCoordinator.setEditing(false); } catch (_) {}
        }
        if (suppressClick && clickReleaseTimer === null) {
            clickReleaseTimer = setTimeout(() => {
                clickReleaseTimer = null;
                suppressClick = false;
            }, 0);
        }
    };
    const gesture = createSupplementalFigurePlacementGesture({
        isConnected: () => summary.isConnected === true && context &&
            isCurrentFigureWorkspaceEditContext(context) &&
            !figureWorkspaceRenderCoordinator.getState().editing,
        activate(record) {
            cancelActiveSupplementalPlacementDrag('replaced');
            if (!trySetSupplementalPointerCapture(summary, record.pointerId)) return false;
            capturedPointerId = record.pointerId;
            activeSupplementalPlacementCleanup = cancelDrag;
            suppressClick = true;
            figureWorkspaceRenderCoordinator.setEditing(true);
            ownsRenderLock = true;
            card.classList.add('is-placement-dragging');
            summary.style.touchAction = 'none';
            ghost = createWorkspaceElement(
                'div', 'workspace-supplemental-drag-ghost',
                figure.figureLabel || figure.figureId || 'Supplemental Figure'
            );
            dropLine = createWorkspaceElement('div', 'workspace-supplemental-drop-line');
            document.body.append(ghost, dropLine);
            positionDragArtifacts({ clientX: record.startX, clientY: record.startY });
        },
        move(_record, event) {
            event.preventDefault?.();
            positionDragArtifacts(event);
        },
        drop(record, event) {
            event.preventDefault?.();
            positionDragArtifacts(event);
            const placements = currentDropOrder
                ? supplementalPlacementsFromOrder(currentDropOrder.ordered) : null;
            tryReleaseSupplementalPointerCapture(summary, record.pointerId);
            capturedPointerId = null;
            if (!placements || !isCurrentFigureWorkspaceEditContext(context)) return;
            void persistSupplementalFigurePlacements(placements, context)
                .catch(error => showStatus(`补充图位置保存失败：${error.message}`, 'error'));
        },
        cancel(record) {
            tryReleaseSupplementalPointerCapture(summary, record.pointerId);
            capturedPointerId = null;
        },
        cleanup: cleanupActive,
        onError(error) {
            showStatus(`补充图拖动已取消：${error?.message || '指针状态异常'}`, 'error');
        }
    });
    cancelDrag = () => {
        if (!gesture.destroy()) cleanupActive();
    };
    const onPointerDown = event => {
        if (gesture.pointerDown(event)) context = captureFigureWorkspaceEditContext();
    };
    const onPointerMove = event => gesture.pointerMove(event);
    const onPointerUp = event => gesture.pointerUp(event);
    const onPointerCancel = event => gesture.pointerCancel(event);
    const onContextMenu = event => {
        const state = gesture.getState();
        if (!state.tracking) return;
        if (state.active) event.preventDefault();
        gesture.destroy();
    };
    const onClick = event => {
        if (!suppressClick) return;
        event.preventDefault();
        event.stopImmediatePropagation();
    };
    summary.addEventListener('pointerdown', onPointerDown);
    summary.addEventListener('pointermove', onPointerMove);
    summary.addEventListener('pointerup', onPointerUp);
    summary.addEventListener('pointercancel', onPointerCancel);
    summary.addEventListener('lostpointercapture', onPointerCancel);
    summary.addEventListener('contextmenu', onContextMenu);
    summary.addEventListener('click', onClick, true);

    const menu = createWorkspaceElement('details', 'workspace-supplemental-placement-menu');
    const menuSummary = createWorkspaceElement('summary', '', '调整位置');
    menuSummary.setAttribute('aria-label', `调整 ${figure.figureLabel || figure.figureId} 的位置`);
    const menuButtons = createWorkspaceElement('div', 'workspace-supplemental-placement-buttons');
    const index = displayFigures.findIndex(item => item.figureId === figure.figureId);
    const up = createWorkspaceElement('button', 'btn btn-secondary', '上移');
    const down = createWorkspaceElement('button', 'btn btn-secondary', '下移');
    up.type = down.type = 'button';
    up.disabled = index <= 0;
    down.disabled = index < 0 || index >= displayFigures.length - 1;
    up.title = up.disabled ? '已到最上方；主图顺序固定' : '向上移动一个位置';
    down.title = down.disabled ? '已到最下方；主图顺序固定' : '向下移动一个位置';
    const keyboardController = createSupplementalPlacementKeyboardController({
        canMove: direction => direction < 0
            ? index > 0 : direction > 0 && index < displayFigures.length - 1,
        setDisabled(upDisabled, downDisabled) {
            up.disabled = upDisabled;
            down.disabled = downDisabled;
        },
        getPlacements: direction => supplementalPlacementForMove(
            figure.figureId, direction, displayFigures
        ),
        captureContext: captureFigureWorkspaceEditContext,
        isContextCurrent: isCurrentFigureWorkspaceEditContext,
        isAttached: () => card.isConnected && up.isConnected && down.isConnected,
        persist: persistSupplementalFigurePlacements,
        onFailure(error) {
            showStatus(`补充图位置保存失败：${error.message}`, 'error');
        }
    });
    const moveByKeyboard = direction => {
        if (figureWorkspaceRenderCoordinator.getState().editing) {
            showStatus('请先完成当前 Figure 编辑，再调整补充图位置', 'error');
            return;
        }
        void keyboardController.move(direction);
    };
    up.addEventListener('click', event => {
        event.preventDefault();
        moveByKeyboard(-1);
    });
    down.addEventListener('click', event => {
        event.preventDefault();
        moveByKeyboard(1);
    });
    menuButtons.append(up, down);
    menu.append(menuSummary, menuButtons, createWorkspaceElement(
        'span', 'workspace-supplemental-placement-hint', '仅补充图可移动；主图顺序固定'
    ));
    actions.appendChild(menu);

    const cleanupBinding = () => {
        if (disposed) return;
        disposed = true;
        gesture.destroy();
        cleanupActive();
        clearTimeout(clickReleaseTimer);
        clickReleaseTimer = null;
        suppressClick = false;
        summary.removeEventListener('pointerdown', onPointerDown);
        summary.removeEventListener('pointermove', onPointerMove);
        summary.removeEventListener('pointerup', onPointerUp);
        summary.removeEventListener('pointercancel', onPointerCancel);
        summary.removeEventListener('lostpointercapture', onPointerCancel);
        summary.removeEventListener('contextmenu', onContextMenu);
        summary.removeEventListener('click', onClick, true);
        supplementalPlacementBindingCleanups.delete(cleanupBinding);
    };
    supplementalPlacementBindingCleanups.add(cleanupBinding);
}

function createPdfFigureArtworkPageControl(figure) {
    const container = createWorkspaceElement('div', 'workspace-pdf-artwork-control');
    const toggle = createWorkspaceElement('button', 'btn btn-secondary workspace-figure-action',
        figure.artworkCoverage === 'complete' ? '修改图像页' : '核对图像页');
    toggle.type = 'button';
    toggle.dataset.pdfArtworkToggle = figure.figureId;
    toggle.setAttribute('aria-expanded', 'false');
    const form = createWorkspaceElement('form', 'workspace-pdf-artwork-form');
    form.hidden = true;
    const label = createWorkspaceElement('label', '', '完整图像的 PDF 页码（最多 4 页）');
    const input = createWorkspaceElement('input', 'form-input');
    input.type = 'text';
    input.value = (figure.artworkPageNumbers || [figure.sourcePage]).join(', ');
    input.placeholder = '例如 5-6 或 5,6';
    input.setAttribute('aria-label', '完整图像的 PDF 页码');
    input.dataset.pdfArtworkPages = figure.figureId;
    label.appendChild(input);
    const checkLabel = createWorkspaceElement('label', 'workspace-pdf-artwork-confirm');
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.required = true;
    checkbox.dataset.pdfArtworkConfirmed = figure.figureId;
    checkLabel.append(checkbox, document.createTextNode('已查看原页，确认包含此 Figure 的全部图像与 Panel'));
    const save = createWorkspaceElement('button', 'btn btn-primary', '保存图像页');
    save.type = 'submit';
    save.dataset.pdfArtworkSave = figure.figureId;
    const feedback = createWorkspaceElement('p', 'workspace-source-note');
    feedback.setAttribute('role', 'status');
    form.append(label, checkLabel, save, feedback);
    toggle.addEventListener('click', () => {
        form.hidden = !form.hidden;
        toggle.setAttribute('aria-expanded', String(!form.hidden));
        if (!form.hidden) input.focus();
    });
    form.addEventListener('submit', async event => {
        event.preventDefault();
        if (!checkbox.checked || save.disabled) return;
        const token = figureTaskGeneration;
        save.disabled = true;
        feedback.textContent = '正在保存…';
        try {
            const pages = [];
            for (const part of input.value.trim().split(/[,，\s]+/u).filter(Boolean)) {
                const match = /^(\d+)(?:[-–](\d+))?$/u.exec(part);
                if (!match) throw new Error('请使用页码或连续范围，例如 5-6。');
                const start = Number(match[1]);
                const end = Number(match[2] || match[1]);
                if (start < 1 || end < start || end > figure.pdfPageCount || end - start > 3) {
                    throw new Error(`页码须在 1–${figure.pdfPageCount} 内，最多选择 4 页。`);
                }
                for (let page = start; page <= end; page++) pages.push(page);
            }
            if (!pages.length || pages.length > 4 || new Set(pages).size !== pages.length) {
                throw new Error('请选择 1–4 个不重复的页码。');
            }
            const tab = await queryPanelTargetTab();
            if (!tab?.id || !isCurrentFigureTask(token, tab.id)) return;
            const response = await sendTabMessage(tab.id, {
                action: 'setPdfFigureArtworkPages', figureId: figure.figureId,
                documentHash: figure.documentHash, pageNumbers: pages, coverageConfirmed: true
            });
            if (!isCurrentFigureTask(token, tab.id)) return;
            if (!response?.success) throw new Error(response?.error || '图像页保存失败，请重试。');
            feedback.textContent = '已保存，后续视觉解读将使用这些页。';
            await refreshArticleWorkspace();
        } catch (error) {
            if (figureTaskGeneration === token) feedback.textContent = error.message;
        } finally {
            save.disabled = false;
        }
    });
    container.append(toggle, form);
    return container;
}

function renderFigureWorkspaceSnapshot(
    snapshot = currentWorkspaceSnapshot,
    { coordinated = false } = {}
) {
    if (!coordinated) return figureWorkspaceRenderCoordinator.request(snapshot);
    const container = document.getElementById('figureWorkspace');
    if (!container) return;
    if (figureCaptionSidebarState.visible) {
        renderFigureCaptionSidebarSnapshot(
            snapshot,
            figureCaptionSidebarState.figureId
        );
        return;
    }
    container.classList.remove('is-caption-mode');
    disposeSupplementalPlacementBindings();
    container.replaceChildren();
    const figures = Array.isArray(snapshot?.figures?.figures) ? snapshot.figures.figures : [];
    const figureWorkspaceDraft = snapshot?.figures?.draft ||
        snapshot?.figureWorkspaceDraft || null;
    const snapshotStatus = snapshot?.figures?.status || null;
    const liveStatus = getFigureProgressEntries(figureAnalysisState).length
        ? figureAnalysisState : snapshotStatus;
    const figureProgress = new Map(getFigureProgressEntries(liveStatus)
        .map(progress => [String(progress?.figureId || ''), progress])
        .filter(([figureId]) => Boolean(figureId)));
    const summary = document.getElementById('figureWorkspaceSummary');
    if (summary) {
        const supplemental = figures.filter(figure => figure.isSupplemental).length;
        summary.textContent = figures.length
            ? `\u5df2\u53d1\u73b0 ${figures.length} \u5f20\u56fe\uff08${supplemental} \u5f20\u8865\u5145\u56fe\uff09`
            : '\u6b63\u5728\u8bfb\u53d6\u8bba\u6587\u56fe\u7247\u76ee\u5f55\u2026';
    }
    renderSupplementalFigureCoverage(snapshot);
    // 论文级提取已移至文献笔记；解图页只保留 Figure、Panel 与机制内容。
    renderResearchLogicMapSnapshot(container, snapshot);
    if (!figures.length) {
        container.appendChild(createWorkspaceElement(
            'div', 'workspace-empty', '\u6682\u672a\u8bc6\u522b\u5230\u56fe\uff1b\u8bf7\u5237\u65b0\u8bba\u6587\u5de5\u4f5c\u533a\u540e\u91cd\u8bd5\u3002'
        ));
        renderFigureQuickNav([]);
        return;
    }
    const displayFigures = SciLLM.orderFigureWorkspaceItems(figures,
        figureWorkspaceDraft?.supplementalPlacements);
    const displayFigureIdCounts = new Map();
    displayFigures.forEach(figure => {
        const figureId = String(figure?.figureId || '');
        if (!figureId) return;
        displayFigureIdCounts.set(figureId, (displayFigureIdCounts.get(figureId) || 0) + 1);
    });
    const movableSupplementalFigureIds = new Set(displayFigures
        .filter(figure => figure?.isSupplemental === true &&
            displayFigureIdCounts.get(String(figure?.figureId || '')) === 1)
        .map(figure => String(figure.figureId)));
    displayFigures.forEach(figure => {
        const completedResult = figure.activeDepth === 'standard'
            ? figure.standard : (figure.deep || figure.standard);
        const pendingResult = figure.activeDepth === 'standard'
            ? figure.pendingStandard : (figure.pendingDeep || figure.pendingStandard);
        const result = completedResult || pendingResult;
        const partialResult = !completedResult && Boolean(pendingResult);
        const view = figureWorkspaceViewState.resolve({
            figure,
            modelResult: result,
            draft: snapshot?.figures?.draft || snapshot?.figureWorkspaceDraft
        });
        const resultDepth = result?.analysisDepth === 'deep' ? 'deep' : 'standard';
        const manuallyEdited = Boolean(figure?.manualEdits?.[resultDepth]);
        const progress = figureProgress.get(figure.figureId) || null;
        const progressDisplay = progress ? formatFigureProgress(progress) : null;
        const loading = figure.deepLoading === true || progress?.running === true;
        const details = createWorkspaceElement('details', 'workspace-figure-card');
        details.classList.toggle('is-llm-pending', loading);
        details.classList.toggle('is-supplemental', figure.isSupplemental === true);
        details.id = view.figureAnchorId;
        details.dataset.figureId = figure.figureId;
        details.open = figureExpansionState.has(figure.figureId)
            ? figureExpansionState.get(figure.figureId) : figure.expanded === true;
        details.addEventListener('toggle', () => {
            figureExpansionState.set(figure.figureId, details.open);
            if (details.open) {
                figureQuickNavActiveId = figure.figureId;
                renderFigureQuickNav(displayFigures);
            }
        });
        const summaryPresentation = figureSummaryPresentation(result, figure, view);
        const status = figureWorkspaceResultStatus({
            figure, progress, result, partialResult, progressDisplay, summaryPresentation
        });
        const summary = createWorkspaceElement('summary', 'workspace-figure-summary');
        const summaryHeading = createWorkspaceElement(
            'span',
            'workspace-figure-summary-heading',
            `${figure.figureLabel || figure.figureId || 'Figure'} · ${status}`
        );
        summary.appendChild(summaryHeading);
        if (summaryPresentation.state === 'available') {
            const conclusion = createWorkspaceElement(
                'span',
                'workspace-figure-summary-conclusion',
                summaryPresentation.text
            );
            conclusion.title = summaryPresentation.fullText;
            conclusion.dataset.summarySource = summaryPresentation.source;
            summary.appendChild(conclusion);
        }
        details.appendChild(summary);
        if (figure.sourceKind === 'pdf-page-caption') {
            const visualPages = result?.pdfEvidenceBinding?.visualEvidenceSet?.requiredArtworkPageNumbers ||
                result?.pdfEvidenceBinding?.assetProof?.pageNumbers || figure.artworkPageNumbers || [figure.sourcePage];
            const sourceNote = result?.basis === 'caption_context'
                ? '文字依据：图注与相关正文（未读取图片）。'
                : result?.basis === 'vision_text'
                    ? `图像依据：PDF 第 ${visualPages.join('、')} 页原页。`
                    : figure.artworkCoverage === 'complete'
                        ? `已核对图像页：${visualPages.join('、')}。`
                        : '图像范围待核对；图注所在页可能不包含完整 Figure。';
            details.appendChild(createWorkspaceElement('p', 'workspace-source-note',
                sourceNote +
                (figure.needsReview ? '图注边界待复核，可核对原页后再解读。' : '')));
        }
        const actions = createWorkspaceElement('div', 'workspace-figure-actions');
        const jump = createWorkspaceElement(
            'button', 'btn btn-secondary workspace-figure-action', '跳转'
        );
        jump.type = 'button';
        const jumpDestination = (figure.sourceExternal || figure.sourceKind === 'pdf-page-caption') && Number(figure.sourcePage) > 0
            ? `PDF 第 ${Math.floor(Number(figure.sourcePage))} 页`
            : figure.sourceExternal ? '外部来源' : '正文图注';
        jump.title = `跳转到 ${figure.figureLabel || figure.figureId} · ${jumpDestination}`;
        jump.setAttribute('aria-label', jump.title);
        jump.addEventListener('click', () => {
            if (figure.sourceExternal && figure.sourceUrl) {
                void chrome.tabs.create({ url: figure.sourceUrl });
                return;
            }
            void focusWorkspaceSource({ kind: 'figure', figureId: figure.figureId });
        });
        const original = createWorkspaceElement(
            'button', 'btn btn-secondary workspace-figure-action', '原图'
        );
        original.type = 'button';
        original.disabled = !figure.hasImage;
        original.title = figure.hasImage ? `查看 ${figure.figureLabel || figure.figureId} 原图` : '当前未取得原图';
        original.setAttribute('aria-label', original.title);
        original.addEventListener('click', () => {
            void showFigureOriginalImage(figure.figureId).catch(error =>
                showStatus(error.message, 'error'));
        });
        const analyze = createWorkspaceElement(
            'button', 'btn btn-figure workspace-figure-action',
            loading ? singleFigureButtonProgressLabel(progress || {}) : '解图'
        );
        analyze.type = 'button';
        analyze.classList.add('workspace-figure-analyze-action');
        analyze.disabled = loading;
        analyze.setAttribute('aria-busy', String(loading));
        analyze.setAttribute('aria-label', `${figure.figureLabel || figure.figureId}：${analyze.textContent}`);
        analyze.title = hasUsableLlm()
            ? (figure.sourceExternal
                ? '使用已导入原论文工作区的补充图、图注和 Panel 直接解读，不切换页面'
                : '解读此 Figure')
            : llmUnavailableMessage('Figure 解读');
        analyze.addEventListener('click', () => {
            if (figure.sourceExternal) {
                void runExternalSupplementalFigureAnalysis(figure);
                return;
            }
            void runSingleFigureAnalysis(figure.figureId);
        });
        actions.append(jump, original, analyze);
        details.appendChild(actions);
        if (figure.sourceExternal) {
            const secondaryActions = createWorkspaceElement('div', 'workspace-figure-secondary-actions');
            const editSupplemental = createWorkspaceElement(
                'button',
                'btn btn-secondary workspace-figure-action workspace-figure-source-edit-action',
                '编辑手动图'
            );
            editSupplemental.type = 'button';
            editSupplemental.disabled = loading;
            editSupplemental.title = '修改 Figure 编号、PDF 页码、图注，或替换上传图片';
            editSupplemental.addEventListener('click', () =>
                openSupplementalFigureEditDialog(figure)
            );
            const deleteSupplemental = createWorkspaceElement(
                'button',
                'btn workspace-figure-action workspace-figure-delete-action',
                '删除'
            );
            deleteSupplemental.type = 'button';
            deleteSupplemental.disabled = loading;
            deleteSupplemental.addEventListener('click', () => {
                void deleteSupplementalFigureFromWorkspace(figure).catch(error =>
                    showStatus(`删除失败：${error.message}`, 'error')
                );
            });
            secondaryActions.append(editSupplemental, deleteSupplemental);
            details.appendChild(secondaryActions);
        }
        if (figure.sourceKind === 'pdf-page-caption') {
            details.appendChild(createPdfFigureArtworkPageControl(figure));
        }
        if (figure.isSupplemental === true &&
            movableSupplementalFigureIds.has(figure.figureId)) {
            const placementActions = createWorkspaceElement('div', 'workspace-figure-placement-actions');
            details.appendChild(placementActions);
            bindSupplementalFigurePlacementInteractions({
                summary, card: details, actions: placementActions, figure, displayFigures, container
            });
        }
        renderFigureProgress(details, progress, result, figure, view);
        appendFigureWorkspaceOverview(details, view, snapshot);
        const sourceCaption = figureSourceCaption(figure);
        if (sourceCaption) {
            const source = createWorkspaceElement('details', 'workspace-figure-source-text');
            source.appendChild(createWorkspaceElement('summary', '', '原题与图注'));
            source.appendChild(createWorkspaceElement('p', '', sourceCaption));
            details.appendChild(source);
        }
        appendFigurePanelCatalog(details, figure, result, view);
        if (result) {
            if (manuallyEdited) {
                details.appendChild(createWorkspaceElement(
                    'p', 'workspace-figure-edited-note',
                    '当前显示人工修订版；模型原文仍可恢复'
                ));
            }
            if (result.unlabeledOverview === true) {
                details.appendChild(createWorkspaceElement(
                    'p', 'workspace-figure-coverage',
                    '网页图注未提供稳定的 Panel 标签；以下为整图证据概览，未臆造 Panel 编号。'
                ));
            }
            const coverage = result.panelCoverage;
            if (coverage?.expectedPanels?.length) {
                const coverageText = coverage.missingPanels?.length
                    ? `Panel \u8986\u76d6\u5f85\u8865\uff1a${formatFigurePanelReferences(view, coverage.missingPanels)}`
                    : `Panel \u8986\u76d6\u5b8c\u6574\uff1a${formatFigurePanelReferences(view, coverage.expectedPanels)}`;
                details.appendChild(createWorkspaceElement(
                    'p', coverage.missingPanels?.length ? 'workspace-figure-coverage is-incomplete' : 'workspace-figure-coverage', coverageText
                ));
            }
            const inputMode = String(
                progress?.inputMode || result.inputMode ||
                (result.basis === 'caption_context' ? 'caption_context' : '')
            );
            const inputBadge = figureRecoveryInputModeBadge(inputMode);
            const retryPresentation = figureRecoveryRetryPresentation(
                figure, result, progress || {}
            );
            const retryPanels = retryPresentation.labels;
            if (inputBadge || retryPanels.length) {
                const recovery = createWorkspaceElement(
                    'section', 'workspace-figure-recovery-status'
                );
                if (inputBadge) {
                    recovery.appendChild(createWorkspaceElement(
                        'span',
                        `workspace-figure-input-badge is-${inputMode}`,
                        inputBadge
                    ));
                }
                if (retryPanels.length) {
                    recovery.appendChild(createWorkspaceElement(
                        'p', 'workspace-figure-coverage is-incomplete',
                        `${t('待补 Panel')}：${formatFigurePanelReferences(view, retryPanels)}`
                    ));
                    const retry = createWorkspaceElement(
                        'button',
                        'btn btn-secondary workspace-figure-retry-missing-action',
                        retryPresentation.label
                    );
                    retry.type = 'button';
                    const recoveryAction = retryPresentation.action || 'missing_panels';
                    const recoveryKey = [
                        Number(activePanelTabContext.tabId) || 0,
                        String(figure.figureId || ''),
                        recoveryAction
                    ].join(':');
                    const recoveryLocked = figureRecoveryInFlightActions.has(recoveryKey);
                    retry.disabled = loading || recoveryLocked || !retryPresentation.enabled;
                    retry.setAttribute('aria-busy', recoveryLocked ? 'true' : 'false');
                    retry.setAttribute('aria-label', retryPresentation.ariaLabel);
                    if (retryPresentation.explanation) {
                        retry.title = retryPresentation.explanation;
                        recovery.appendChild(createWorkspaceElement(
                            'p', 'workspace-figure-coverage',
                            retryPresentation.explanation
                        ));
                    }
                    if (retryPresentation.enabled) {
                        retry.addEventListener('click', () => {
                            retry.disabled = true;
                            retry.setAttribute('aria-busy', 'true');
                            void runFigureRecoveryFromUi(
                                figure, retryPanels, retryPresentation, retry
                            );
                        });
                    }
                    recovery.appendChild(retry);
                }
                details.appendChild(recovery);
            }
            if (result.analysisDepth === 'deep') {
                details.appendChild(createWorkspaceElement('h4', 'workspace-figure-section-title', '\u6df1\u5ea6\u8bc1\u636e\u5ba1\u67e5'));
                [
                    ['\u5b9a\u6027\u4e0e\u5b9a\u91cf\u4e92\u8bc1', result.qualitativeQuantitativeLink],
                    ['\u9634\u6027\u7ed3\u679c\u7684\u4ef7\u503c', result.negativeResultValue],
                    ['\u5168\u6587\u8bba\u8bc1\u89d2\u8272', result.paperArgumentRole],
                    ['\u6df1\u5c42\u7ec4\u56fe\u7b56\u7565', result.deepAuthorStrategy]
                ].forEach(([label, value]) => appendFigureWorkspaceField(details, label, value));
                (Array.isArray(result.controlAnalysis) ? result.controlAnalysis : []).forEach(control => {
                    const block = createWorkspaceElement('section', 'workspace-figure-chain-step');
                    appendFigureWorkspaceField(block, '\u5bf9\u7167 Panel',
                        formatFigurePanelReferences(view, control.panels));
                    appendFigureWorkspaceField(block, '\u5bf9\u7167\u7c7b\u578b', control.controlType);
                    appendFigureWorkspaceField(block, '\u6392\u9664\u7684\u66ff\u4ee3\u89e3\u91ca', control.excludedExplanation);
                    appendFigureWorkspaceField(block, '\u5bf9\u7167\u5145\u5206\u6027', control.adequacy);
                    details.appendChild(block);
                });
                (Array.isArray(result.evidenceRelations) ? result.evidenceRelations : []).forEach(relation => {
                    const block = createWorkspaceElement('section', 'workspace-figure-chain-step');
                    const panelRefs = formatFigurePanelReferences(view, relation.panels);
                    if (panelRefs) appendFigureWorkspaceField(block, 'Panel', panelRefs);
                    appendFigureWorkspaceField(block, '\u8bc1\u636e\u5173\u7cfb', relation.relationLevel);
                    appendFigureWorkspaceField(block, '\u5224\u65ad\u4f9d\u636e', relation.rationale);
                    details.appendChild(block);
                });
                appendFigureWorkspaceField(
                    details,
                    '\u66ff\u4ee3\u89e3\u91ca',
                    (result.alternativeExplanations || []).join('\uff1b')
                );
                appendFigureWorkspaceField(
                    details,
                    '\u5220\u9664 Panel \u540e\u7f3a\u5931\u7684\u8bba\u8bc1',
                    (result.missingLinksIfPanelRemoved || []).join('\uff1b')
                );
            }
        } else if (figure.standardError || figure.deepError) {
            details.appendChild(createWorkspaceElement(
                'p', 'workspace-figure-error', figure.standardError || figure.deepError
            ));
        } else {
            details.appendChild(createWorkspaceElement(
                'p', 'workspace-figure-caption', '\u5df2\u5728\u76ee\u5f55\u4e2d\uff0c\u53ef\u76f4\u63a5\u5355\u56fe\u7cbe\u8bfb\u3002'
            ));
        }
        container.appendChild(details);
    });
    renderFigureQuickNav(displayFigures);
}

function reconcileArticleWorkspaceSnapshot(current, incoming) {
    if (!incoming || typeof incoming !== 'object') return incoming || null;
    if (incoming.figures?.inventoryReady === false) return incoming;
    function identityOf(snapshot) {
        const workspace = snapshot?.localWorkspace;
        const workspaceId = String(workspace?.workspaceId || '').trim().toLowerCase();
        const workspaceGeneration = Number(workspace?.workspaceGeneration);
        const contentHash = String(workspace?.contentHash || '')
            .trim().toLowerCase().replace(/^sha256:/u, '');
        let canonicalUrl = '';
        try {
            canonicalUrl = SciLLM.normalizeWorkspaceCanonicalUrl(workspace?.canonicalUrl);
        } catch (_) {}
        if (!/^workspace:[a-f0-9]{64}$/u.test(workspaceId) ||
            !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
            !/^[a-f0-9]{64}$/u.test(contentHash) || !canonicalUrl) return null;
        return { workspaceId, workspaceGeneration, canonicalUrl, contentHash };
    }
    const currentIdentity = identityOf(current);
    const incomingIdentity = identityOf(incoming);
    const sameIdentity = currentIdentity && incomingIdentity &&
        currentIdentity.workspaceId === incomingIdentity.workspaceId &&
        currentIdentity.workspaceGeneration === incomingIdentity.workspaceGeneration &&
        currentIdentity.canonicalUrl === incomingIdentity.canonicalUrl &&
        currentIdentity.contentHash === incomingIdentity.contentHash;
    if (!sameIdentity) return incoming;
    const currentDraft = current?.figures?.draft || current?.figureWorkspaceDraft || null;
    const incomingDraft = incoming?.figures?.draft || incoming?.figureWorkspaceDraft || null;
    const currentRevision = Number(currentDraft?.revision);
    const incomingRevision = Number(incomingDraft?.revision);
    const hasCurrentRevision = Number.isSafeInteger(currentRevision) && currentRevision >= 0;
    const hasIncomingRevision = Number.isSafeInteger(incomingRevision) && incomingRevision >= 0;
    const selectedDraft = hasCurrentRevision &&
        (!hasIncomingRevision || currentRevision > incomingRevision)
        ? currentDraft : incomingDraft;
    if (!selectedDraft) return incoming;
    return {
        ...incoming,
        figureWorkspaceDraft: selectedDraft,
        figures: { ...(incoming.figures || {}), draft: selectedDraft }
    };
}

function renderArticleWorkspaceSnapshot(snapshot) {
    snapshot = reconcileArticleWorkspaceSnapshot(currentWorkspaceSnapshot, snapshot);
    currentWorkspaceSnapshot = snapshot || null;
    workspaceGeneration = Math.max(1,
        Number(snapshot?.localWorkspace?.workspaceGeneration) || workspaceGeneration || 1
    );
    const status = document.getElementById('articleNavigationStatus');
    const title = document.getElementById('sidePanelPaperTitle');
    const statusText = document.getElementById('sidePanelDocumentStatusText');
    if (title) title.textContent = snapshot?.title || '当前页面';
    const diagnostics = snapshot?.diagnostics || {};
    const publisher = ({ 'pdf-workspace': 'PDF 文献', generic: '网页文献' })[snapshot?.publisherFamily]
        || snapshot?.publisherFamily || '网页文献';
    const semanticCounts = popupPdfSemanticNavigationCounts(
        normalizePopupPdfSemanticNavigation(currentPdfSemanticNavigation, snapshot)
    );
    const summary = `${publisher} · ` +
        `${semanticCounts.sectionCount || diagnostics.headingCount || 0} 个标题 · ` +
        `${semanticCounts.paragraphCount || diagnostics.paragraphCount || 0} 段` +
        (snapshot?.access?.status === 'public_preview' ? '页面内容（含参考文献等公开资料）' : '正文');
    const warning = (snapshot?.warnings || []).map(item => item.message).filter(Boolean).join(' ');
    if (status) status.textContent = warning ? `${summary} · ${warning}` : summary;
    if (statusText) statusText.textContent = snapshot?.access?.status === 'public_preview'
        ? `已激活 · 仅公开预览 · ${publisher}` : `已激活 · ${publisher}`;
    const connectionStatus = document.getElementById('sidePanelDocumentStatus');
    connectionStatus?.classList.remove('is-error');
    connectionStatus?.classList.add('is-ready');
    const retry = document.getElementById('retryArticlePreparation');
    if (retry) retry.hidden = true;
    renderArticleNavigationTree(snapshot);
    renderEvidenceLedger(snapshot);
    renderHighlightDistributionSnapshot(snapshot);
    renderFigureWorkspaceSnapshot(snapshot);
    renderArticleChatSnapshot(snapshot);
    return snapshot;
}

function getArticleChatProfiles() {
    const profiles = llmSettingsState?.settings?.profiles || {};
    const order = Array.isArray(llmSettingsState?.settings?.profileOrder)
        ? llmSettingsState.settings.profileOrder : Object.keys(profiles);
    return order.map(profileId => [profileId, profiles[profileId]])
        .filter(([, profile]) => {
            const config = profile?.config || {};
            return profile.providerId !== 'typesafe' &&
                (typeof SciLLM.providerSupportsTask !== 'function' ||
                SciLLM.providerSupportsTask(profile.providerId, 'article_chat')) &&
                (profile.providerId === 'codex-local' || config.hasApiKey === true) &&
                Boolean(String(config.model || '').trim()) &&
                (profile.providerId !== 'openai-compatible' || Boolean(String(config.baseUrl || '').trim()));
        });
}

function hasUsableLlm() {
    if (llmSettingsState?.settings?.consentGranted !== true) return false;
    return getArticleChatProfiles().length > 0;
}

function llmUnavailableMessage(featureLabel = '该功能') {
    const profiles = getArticleChatProfiles();
    if (profiles.length > 0 &&
        llmSettingsState?.settings?.consentGranted !== true) {
        return `${featureLabel}的模型已配置；请在设置的“正文发送许可”中勾选同意并保存。`;
    }
    return `请先在设置中保存可供${featureLabel}使用的模型。`;
}

function requireUsableLlm(featureLabel) {
    if (hasUsableLlm()) return true;
    showStatus(llmUnavailableMessage(featureLabel), 'error');
    return false;
}

function resolveConfiguredTaskProfile(settings, taskId, usableProfiles = []) {
    if (!settings || typeof settings !== 'object') return null;
    const profiles = settings.profiles && typeof settings.profiles === 'object'
        ? settings.profiles : {};
    const policy = settings.taskPolicies?.[taskId];
    const profileId = policy?.mode === 'profile' && typeof policy.profileId === 'string'
        ? policy.profileId : String(settings.globalProfileId || '');
    const allowed = new Set((Array.isArray(usableProfiles) ? usableProfiles : [])
        .map(entry => Array.isArray(entry) ? entry[0] : '').filter(Boolean));
    if (!profileId || !Object.hasOwn(profiles, profileId) || !allowed.has(profileId)) return null;
    return [profileId, profiles[profileId]];
}

function renderLiteratureNoteModelStatus() {
    const hint = document.getElementById('literatureNoteModelHint');
    const label = hint?.querySelector('span');
    const settingsButton = document.getElementById('openLiteratureNoteModelSettings');
    if (!hint || !label) return;
    const profiles = getArticleChatProfiles();
    const configured = resolveConfiguredTaskProfile(
        llmSettingsState?.settings, 'literature_note_autofill', profiles
    );
    const ready = hasUsableLlm() && Boolean(configured);
    hint.classList.toggle('is-ready', ready);
    label.textContent = ready
        ? `${t('AI 填写配置模型')}：${configured?.[1]?.name || t('未命名模型')}`
        : profiles.length && llmSettingsState?.settings?.consentGranted !== true
            ? t('模型已配置；授予正文发送许可后即可 AI 填写。')
            : profiles.length
                ? t('无法确认 AI 填写的任务模型；请检查任务设置与全局回退。')
            : t('AI 填写需要已配置的模型。');
    if (settingsButton) settingsButton.hidden = ready;
}

function renderArticleChatModelStatus(profiles = getArticleChatProfiles()) {
    const status = document.getElementById('articleChatModelStatus');
    const label = status?.querySelector('span');
    const settingsButton = document.getElementById('openArticleChatModelSettings');
    if (!status || !label) return;
    const ready = hasUsableLlm() && profiles.length > 0;
    const selected = profiles.find(([profileId]) => profileId === articleChatSelectedProfileId)
        || profiles[0];
    status.classList.toggle('is-ready', ready);
    label.textContent = ready
        ? `${t('本轮模型')}：${selected?.[1]?.name || t('当前模型')}`
        : profiles.length
            ? t('模型已配置；尚未授予正文发送许可。')
            : t('尚未连接可用于全文问答的模型。');
    if (settingsButton) settingsButton.hidden = ready;
}

function renderArticleChatProfileOptions() {
    const select = document.getElementById('articleChatProfile');
    if (!select) return;
    const profiles = getArticleChatProfiles();
    const preferred = articleChatSelectedProfileId ||
        llmSettingsState?.settings?.globalProfileId || profiles[0]?.[0] || '';
    select.replaceChildren();
    profiles.forEach(([profileId, profile]) => {
        const option = document.createElement('option');
        option.value = profileId;
        option.textContent = `${profile?.name || '未命名模型'} · ${profile?.config?.model || ''}`;
        select.appendChild(option);
    });
    if (!profiles.length) {
        const option = document.createElement('option');
        option.value = '';
        option.textContent = t('尚未配置可用模型');
        select.appendChild(option);
    }
    articleChatSelectedProfileId = profiles.some(([profileId]) => profileId === preferred)
        ? preferred : (profiles[0]?.[0] || '');
    select.value = articleChatSelectedProfileId;
    select.disabled = profiles.length === 0;
    renderArticleChatModelStatus(profiles);
}

function renderArticleChatHighlightCategoryOptions() {
    const select = document.getElementById('articleChatHighlightCategory');
    if (!select) return;
    const previous = select.value;
    const previousColor = document.getElementById('articleChatHighlightColor')?.value;
    const categories = getAvailableCategoryEntries(
        llmSettingsState?.availableCategories,
        'llm'
    );
    select.replaceChildren();
    categories.forEach(([categoryId, category]) => {
        const option = document.createElement('option');
        option.value = categoryId;
        option.textContent = categoryId === 'semantic_match'
            ? t('智能检索匹配') : (category.name || categoryId);
        option.dataset.categoryName = category.name || categoryId;
        option.dataset.categoryColor = category.color || '#2F80ED';
        select.appendChild(option);
    });
    const preferred = categories.some(([categoryId]) => categoryId === previous)
        ? previous
        : categories.some(([categoryId]) => categoryId === 'semantic_match')
            ? 'semantic_match' : (categories[0]?.[0] || '');
    select.value = preferred;
    select.disabled = categories.length === 0;
    if (!(previous && preferred === previous && /^#[0-9a-f]{6}$/i.test(previousColor || ''))) {
        syncArticleChatHighlightColor();
    }
}

function syncArticleChatHighlightColor() {
    const select = document.getElementById('articleChatHighlightCategory');
    const color = document.getElementById('articleChatHighlightColor');
    const selected = select?.selectedOptions?.[0];
    if (color && selected?.dataset.categoryColor) {
        color.value = selected.dataset.categoryColor;
    }
}

function renderArticleSemanticHighlightControls() {
    const select = document.getElementById('articleSemanticHighlightProfile');
    if (!select) return;
    const profiles = getArticleChatProfiles();
    const preferred = select.value ||
        llmSettingsState?.settings?.globalProfileId || profiles[0]?.[0] || '';
    select.replaceChildren();
    profiles.forEach(([profileId, profile]) => {
        const option = document.createElement('option');
        option.value = profileId;
        option.textContent = `${profile?.name || '未命名模型'} · ${profile?.config?.model || ''}`;
        select.appendChild(option);
    });
    if (!profiles.length) {
        const option = document.createElement('option');
        option.value = '';
        option.textContent = t('尚未配置可用模型');
        select.appendChild(option);
    }
    select.value = profiles.some(([profileId]) => profileId === preferred)
        ? preferred : (profiles[0]?.[0] || '');
    select.disabled = profiles.length === 0;
    const highlight = document.getElementById('highlightArticleChatMatches');
    if (highlight) highlight.disabled = !select.value ||
        !document.getElementById('articleChatHighlightCategory')?.value;
}

function articleChatOutlineScopes(snapshot = currentWorkspaceSnapshot) {
    const results = [];
    const seen = new Set();
    const paragraphs = Array.isArray(snapshot?.paragraphs) ? snapshot.paragraphs : [];
    const descendantSourceKeys = node => {
        const values = [];
        const collect = item => {
            const sourceKey = String(item?.sourceKey || '').trim();
            if (sourceKey) values.push(sourceKey);
            (Array.isArray(item?.children) ? item.children : []).forEach(collect);
        };
        collect(node);
        return [...new Set(values)];
    };
    const visit = (nodes, depth = 0) => {
        (Array.isArray(nodes) ? nodes : []).forEach(node => {
            const sectionId = String(node?.sectionId || '');
            const title = String(node?.displayTitle || node?.title || '').trim();
            // Keep the @ scope catalog aligned with the navigation tree. Empty
            // outline leaves are still selectable, while parent nodes retain
            // every descendant section that the navigation analysis toggle uses.
            const sectionIds = (Array.isArray(node?.analysisSectionIds) &&
                node.analysisSectionIds.length
                ? node.analysisSectionIds : [sectionId])
                .map(value => String(value || '')).filter(Boolean);
            const paragraphCount = paragraphs.filter(paragraph =>
                sectionIds.includes(String(paragraph?.sectionId || ''))
            ).length;
            if (sectionId && title && sectionIds.length && !seen.has(sectionId)) {
                seen.add(sectionId);
                results.push({
                    id: sectionId,
                    name: title,
                    detail: paragraphCount > 0
                        ? `${String(node?.sectionKind || '章节')} · ${paragraphCount} 段`
                        : `${String(node?.sectionKind || '章节')} · 目录标题`,
                    sectionIds,
                    sourceKeys: descendantSourceKeys(node),
                    depth: Math.max(0, depth)
                });
            }
            visit(node?.children, depth + 1);
        });
    };
    visit(snapshot?.nodes);
    return results;
}

function selectedWorkspaceAnalysisSectionIds(snapshot = currentWorkspaceSnapshot) {
    const selected = new Set();
    const visit = nodes => {
        (Array.isArray(nodes) ? nodes : []).forEach(node => {
            if (node?.analysisSelected === true) {
                (Array.isArray(node.analysisSectionIds) ? node.analysisSectionIds : [])
                    .map(String).filter(Boolean).forEach(sectionId => selected.add(sectionId));
                return;
            }
            visit(node?.children);
        });
    };
    visit(snapshot?.nodes);
    return [...selected];
}

function articleChatQuickPrompts() {
    return (Array.isArray(llmSettingsState?.settings?.articleChatQuickPrompts)
        ? llmSettingsState.settings.articleChatQuickPrompts : [])
        .filter(item => item?.id && item?.name && item?.prompt)
        .map(item => ({
            id: String(item.id),
            name: String(item.name),
            detail: String(item.prompt),
            prompt: String(item.prompt)
        }));
}

function renderArticleChatContextScopes() {
    const container = document.getElementById('articleChatContextScopes');
    if (!container) return;
    container.replaceChildren();
    articleChatContextScopes.forEach(scope => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'article-chat-context-chip';
        button.dataset.scopeId = scope.id;
        button.title = `移除章节范围：${scope.name}`;
        const label = document.createElement('span');
        appendScientificInlineText(label, `@${scope.name}`);
        const icon = document.createElement('i');
        icon.className = 'ph ph-x';
        icon.setAttribute('aria-hidden', 'true');
        button.append(label, icon);
        container.appendChild(button);
    });
    container.hidden = articleChatContextScopes.size === 0;
}

function articleChatContextScopePayload() {
    const sectionIds = [];
    const sectionTitles = [];
    const scopes = [];
    const seen = new Set();
    articleChatContextScopes.forEach(scope => {
        sectionTitles.push(scope.name);
        scopes.push({
            scopeId: String(scope.id || ''),
            name: String(scope.name || ''),
            sectionIds: [...new Set((Array.isArray(scope.sectionIds)
                ? scope.sectionIds : []).map(String).filter(Boolean))],
            sourceKeys: [...new Set((Array.isArray(scope.sourceKeys)
                ? scope.sourceKeys : []).map(String).filter(Boolean))]
        });
        scope.sectionIds.forEach(sectionId => {
            if (!seen.has(sectionId)) {
                seen.add(sectionId);
                sectionIds.push(sectionId);
            }
        });
    });
    return { sectionIds, sectionTitles, scopes };
}

function preflightArticleChatContextScope(contextScope,
    snapshot = currentWorkspaceSnapshot) {
    if (typeof SciLLM.resolveArticleChatContextScope !== 'function') {
        return { success: true, contextScope };
    }
    const resolution = SciLLM.resolveArticleChatContextScope(contextScope, {
        nodes: snapshot?.nodes,
        paragraphs: snapshot?.paragraphs
    });
    if (resolution.requested && !resolution.complete) {
        return {
            success: false,
            code: 'ARTICLE_CHAT_SCOPE_EMPTY',
            contextScope: resolution.contextScope
        };
    }
    return { success: true, contextScope: resolution.contextScope };
}

function articleChatInputTrigger(input) {
    const caret = Math.max(0, Number(input?.selectionStart) || 0);
    const prefix = String(input?.value || '').slice(0, caret);
    const match = prefix.match(/(^|\s)([@/])([^\s@/]*)$/u);
    if (!match) return null;
    return {
        symbol: match[2],
        query: match[3].normalize('NFKC').toLowerCase(),
        start: caret - match[2].length - match[3].length,
        end: caret
    };
}

function closeArticleChatCommandMenu() {
    const menu = document.getElementById('articleChatCommandMenu');
    if (menu) {
        menu.hidden = true;
        menu.replaceChildren();
    }
    articleChatCommandItems = [];
    articleChatCommandActiveIndex = -1;
    articleChatCommandTrigger = null;
}

function setArticleChatCommandActive(index) {
    if (!articleChatCommandItems.length) return;
    articleChatCommandActiveIndex =
        (index + articleChatCommandItems.length) % articleChatCommandItems.length;
    document.querySelectorAll('.article-chat-command-option').forEach((node, itemIndex) => {
        const active = itemIndex === articleChatCommandActiveIndex;
        node.classList.toggle('is-active', active);
        node.setAttribute('aria-selected', active ? 'true' : 'false');
        if (active) node.scrollIntoView({ block: 'nearest' });
    });
}

function updateArticleChatCommandMenu() {
    const input = document.getElementById('articleChatQuestion');
    const menu = document.getElementById('articleChatCommandMenu');
    if (!input || !menu) return;
    const trigger = articleChatInputTrigger(input);
    if (!trigger) {
        closeArticleChatCommandMenu();
        return;
    }
    const source = trigger.symbol === '@'
        ? articleChatOutlineScopes()
        : articleChatQuickPrompts();
    const filteredItems = source.filter(item => {
        if (!trigger.query) return true;
        return `${item.name} ${item.detail}`.normalize('NFKC').toLowerCase()
            .includes(trigger.query);
    });
    const items = trigger.symbol === '@'
        ? filteredItems
        : filteredItems.slice(0, 20);
    if (!items.length) {
        closeArticleChatCommandMenu();
        return;
    }
    articleChatCommandTrigger = trigger;
    articleChatCommandItems = items;
    articleChatCommandActiveIndex = 0;
    menu.replaceChildren();
    items.forEach((item, index) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'article-chat-command-option';
        button.dataset.commandIndex = String(index);
        button.setAttribute('role', 'option');
        button.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
        const name = document.createElement('strong');
        appendScientificInlineText(name, `${trigger.symbol}${item.name}`);
        const meta = document.createElement('em');
        meta.textContent = trigger.symbol === '@' ? item.detail : '快捷提示';
        const detail = document.createElement('small');
        detail.textContent = item.detail;
        button.append(name, meta, detail);
        menu.appendChild(button);
    });
    menu.hidden = false;
}

function selectArticleChatCommand(index = articleChatCommandActiveIndex) {
    const item = articleChatCommandItems[index];
    const trigger = articleChatCommandTrigger;
    const input = document.getElementById('articleChatQuestion');
    if (!item || !trigger || !input) return false;
    if (trigger.symbol === '@') {
        articleChatContextScopes.set(item.id, item);
        input.setRangeText('', trigger.start, trigger.end, 'end');
        renderArticleChatContextScopes();
    } else {
        const replacement = `${item.prompt} `;
        input.setRangeText(replacement, trigger.start, trigger.end, 'end');
    }
    closeArticleChatCommandMenu();
    input.focus();
    return true;
}

function normalizeArticleChatCitationText(value) {
    return String(value || '').normalize('NFKC').replace(/\s+/g, ' ').trim().toLowerCase();
}

function resolvePopupPdfArticleChatEvidence(item, navigation) {
    if (!navigation || typeof navigation !== 'object' ||
        typeof SciLLM.migratePdfArticleChatEvidence !== 'function') return null;
    const locatorFields = [
        'locatorKind', 'documentId', 'documentHash', 'documentGeneration', 'revision',
        'semanticCacheKey', 'semanticProvenanceKey', 'paragraphId', 'normalizedStart',
        'normalizedEnd', 'expectedNormalizedQuote'
    ];
    const paragraphTargetFields = [
        'kind', 'documentId', 'documentHash', 'documentGeneration', 'revision',
        'semanticCacheKey', 'semanticProvenanceKey', 'paragraphId', 'pageNumber',
        'normalizedStart', 'normalizedEnd', 'expectedNormalizedQuote'
    ];
    const targetsByParagraphId = new Map();
    const sections = Array.isArray(navigation.sections) ? [...navigation.sections] : null;
    let navigationValid = Boolean(sections);
    let visitedSections = 0;
    while (navigationValid && sections.length) {
        const section = sections.shift();
        visitedSections += 1;
        if (!section || typeof section !== 'object' || visitedSections > 20000 ||
            !Array.isArray(section.paragraphTargets) || !Array.isArray(section.children)) {
            navigationValid = false;
            break;
        }
        for (const target of section.paragraphTargets) {
            if (!isTrustedPopupPdfParagraphTarget(target, navigation)) {
                navigationValid = false;
                break;
            }
            const existing = targetsByParagraphId.get(target.paragraphId);
            if (existing) {
                const samePages = JSON.stringify(existing.pageNumbers || [existing.pageNumber]) ===
                    JSON.stringify(target.pageNumbers || [target.pageNumber]);
                if (!samePages ||
                    !paragraphTargetFields.every(field => existing[field] === target[field])) {
                    navigationValid = false;
                    break;
                }
                continue;
            }
            if (targetsByParagraphId.size >= 10000) {
                navigationValid = false;
                break;
            }
            targetsByParagraphId.set(target.paragraphId, target);
        }
        if (!navigationValid) break;
        sections.unshift(...section.children);
    }
    const paragraphs = navigationValid ? [...targetsByParagraphId.values()].map(target => ({
        paragraphId: target.paragraphId,
        normalizedText: target.expectedNormalizedQuote,
        normalizedStart: target.normalizedStart,
        normalizedEnd: target.normalizedEnd,
        pageNumber: target.pageNumber,
        legacyParagraphIds: (target.pageNumbers || [target.pageNumber])
            .map(pageNumber => `pdf-page-${pageNumber}`)
    })) : null;
    const context = paragraphs ? {
        documentId: navigation.documentId,
        documentHash: navigation.documentHash,
        documentGeneration: navigation.documentGeneration,
        revision: navigation.revision,
        semanticCacheKey: navigation.semanticCacheKey,
        semanticProvenanceKey: navigation.semanticProvenanceKey,
        paragraphs
    } : null;
    const sourceLocator = item?.locator && typeof item.locator === 'object'
        ? item.locator
        : item?.semanticLocator && typeof item.semanticLocator === 'object'
            ? item.semanticLocator
            : item?.locatorKind === 'pdf-semantic' ? item : null;
    const copyLocator = locator => locator && typeof locator === 'object'
        ? Object.fromEntries(locatorFields.map(field => [field, locator[field]])) : null;
    const explicitPageAnchor = item?.pageAnchor && typeof item.pageAnchor === 'object'
        ? { paragraphId: item.pageAnchor.paragraphId, pageNumber: item.pageAnchor.pageNumber }
        : null;
    const locatorTarget = targetsByParagraphId.get(sourceLocator?.paragraphId);
    const legacyMatch = /^pdf-page-(\d+)$/u.exec(String(item?.paragraphId || ''));
    const pageNumber = Number(item?.pageNumber) || Number(legacyMatch?.[1]) || 0;
    const pageAnchor = explicitPageAnchor ||
        (locatorTarget?.pageNumbers?.length === 1 && locatorTarget?.pageNumber > 0
        ? { paragraphId: `pdf-page-${locatorTarget.pageNumber}`,
            pageNumber: locatorTarget.pageNumber }
        : legacyMatch && pageNumber > 0
            ? { paragraphId: `pdf-page-${pageNumber}`, pageNumber }
            : null);
    let input;
    if (sourceLocator) {
        input = { locator: copyLocator(sourceLocator) };
        if (pageAnchor) input.pageAnchor = pageAnchor;
    } else {
        input = {
            paragraphId: String(item?.paragraphId || ''),
            pageNumber
        };
        const quote = typeof item?.quote === 'string'
            ? item.quote : typeof item?.support === 'string' ? item.support : null;
        if (quote !== null) input.quote = quote;
        if (pageAnchor) input.pageAnchor = pageAnchor;
    }
    const migration = SciLLM.migratePdfArticleChatEvidence(input, context);
    const locator = migration?.locator || null;
    const suggestedLocator = migration?.suggestedLocator || null;
    const preservedLocator = migration?.preservedLocator || null;
    return Object.freeze({
        ...migration,
        locator,
        suggestedLocator,
        preservedLocator,
        semanticMigration: true,
        candidateCount: migration?.status === 'verified' ? 1
            : migration?.status === 'ambiguous' ? 2 : 0,
        reason: String(migration?.degradedReasonCode || ''),
        target: migration?.status === 'verified' && locator
            ? locator
            : migration?.status === 'degraded' && migration?.precision === 'page-only' &&
                migration?.pageAnchor ? migration.pageAnchor : null
    });
}

function resolveArticleChatEvidenceTarget(
    item,
    snapshot,
    semanticNavigation = currentPdfSemanticNavigation
) {
    const semanticVerification = resolvePopupPdfArticleChatEvidence(item, semanticNavigation);
    if (semanticVerification) return semanticVerification;
    return SciLLM.verifyArticleChatEvidence({
        ...item,
        documentRevision: Number(item?.documentRevision || snapshot?.revision) || 0
    }, snapshot);
}

function isArticleChatCitationFocusable(verification) {
    if (verification?.semanticMigration === true) {
        return Boolean(
            (verification.status === 'verified' && verification.locator) ||
            (verification.status === 'degraded' && verification.precision === 'page-only' &&
                verification.pageAnchor)
        );
    }
    return Boolean(verification?.status === 'verified' && verification?.target);
}

function createArticleChatCitationFocusTarget(item, verification, snapshot) {
    if (!isArticleChatCitationFocusable(verification)) return null;
    if (verification.semanticMigration === true) {
        const locator = verification.locator && { ...verification.locator };
        const pageAnchor = verification.pageAnchor
            ? { ...verification.pageAnchor } : null;
        const evidence = locator ? {
            ...locator,
            locator,
            quote: locator.expectedNormalizedQuote,
            pageAnchor,
            status: verification.status,
            precision: verification.precision,
            degradedReasonCode: verification.degradedReasonCode,
            rebound: verification.rebound === true
        } : {
            paragraphId: pageAnchor.paragraphId,
            pageNumber: pageAnchor.pageNumber,
            pageAnchor,
            status: verification.status,
            precision: verification.precision,
            degradedReasonCode: verification.degradedReasonCode,
            rebound: verification.rebound === true
        };
        return {
            kind: 'article-chat-citation',
            evidence,
            documentRevision: Number(snapshot?.revision) || 0
        };
    }
    return {
        kind: 'article-chat-citation',
        evidence: {
            paragraphId: verification.target.paragraphId || item?.paragraphId,
            sourceKey: verification.target.sourceKey || item?.sourceKey,
            textHash: verification.target.textHash || item?.textHash,
            sectionTitle: verification.target.sectionTitle || item?.sectionTitle,
            sectionPath: verification.target.sectionPath || item?.sectionPath,
            quote: item?.quote || '',
            support: item?.support || '',
            documentHash: item?.documentHash || snapshot?.documentHash || ''
        },
        documentRevision: Number(snapshot?.revision) || 0
    };
}

function articleChatCitationStatusText(
    status,
    reason = '',
    precision = '',
    pageNumber = 0
) {
    if (status === 'degraded' && precision === 'page-only') {
        return pageNumber > 0
            ? `待核验：仅可定位到第 ${pageNumber} 页（页级证据）`
            : '待核验：仅可进行页级定位';
    }
    if (status === 'ambiguous') return '待核验：原文中存在多个相同或近似位置';
    if (status === 'stale') return '待核验：正文版本已经变化';
    if (reason === 'SOURCE_ANCHOR_MISSING') return '跳转失败：原文位置当前不可见';
    return '待核验：没有找到唯一对应的原文段落';
}

function applyArticleChatCitationState(button, verification, citationNumber = 1, label = '') {
    const status = verification?.status || 'missing';
    const focusable = isArticleChatCitationFocusable(verification);
    button.classList.remove(
        'is-verified', 'is-degraded', 'is-ambiguous', 'is-missing', 'is-stale', 'is-invalid'
    );
    button.classList.add(`is-${status}`);
    button.dataset.verificationStatus = status;
    button.dataset.candidateCount = String(verification?.candidateCount || 0);
    button.dataset.precision = String(verification?.precision || '');
    button.dataset.rebound = String(verification?.rebound === true);
    button.dataset.citationFocusable = String(focusable);
    button.disabled = !focusable;
    button.textContent = status === 'verified'
        ? String(citationNumber)
        : status === 'degraded' && verification?.precision === 'page-only'
            ? '页级·待核验' : '待核验';
    const statusText = status === 'verified'
        ? `参考原文 ${citationNumber}${verification?.rebound ? ' · 已重绑' : ''} · ${
            label || '正文段落'}`
        : articleChatCitationStatusText(
            status,
            verification?.reason || verification?.degradedReasonCode,
            verification?.precision,
            Number(verification?.pageAnchor?.pageNumber) || 0
        );
    button.title = statusText;
    button.setAttribute('aria-label', statusText);
}

async function focusArticleChatCitation(item, snapshot, button = null) {
    const verification = resolveArticleChatEvidenceTarget(item, snapshot);
    const focusItem = {
        ...item,
        documentHash: item?.documentHash || snapshot?.documentHash || ''
    };
    const target = createArticleChatCitationFocusTarget(focusItem, verification, snapshot);
    if (!target) return false;
    const panelContext = capturePanelContext();
    if (button) button.disabled = true;
    try {
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'focusArticleWorkspaceSource',
            target
        });
        if (!isCurrentPanelContext(panelContext)) return false;
        const citationResult = response?.citationResult || {
            status: response?.focused ? 'verified' : 'missing',
            reason: response?.focused ? '' : 'SOURCE_ANCHOR_MISSING',
            candidateCount: 0
        };
        const focused = Boolean(response?.success && response?.focused);
        if (!focused && isCurrentPanelContext(panelContext)) {
            if (button?.isConnected) applyArticleChatCitationState(
                button, citationResult, Number(button.dataset.citationNumber) || 1,
                item?.sectionTitle || '正文段落'
            );
            showStatus(articleChatCitationStatusText(
                citationResult.status,
                citationResult.reason || citationResult.degradedReasonCode,
                citationResult.precision,
                Number(citationResult.pageAnchor?.pageNumber || citationResult.pageNumber) || 0
            ), 'error');
        }
        return focused;
    } finally {
        if (button?.isConnected && button.dataset.citationFocusable === 'true') {
            button.disabled = false;
        }
    }
}

function createArticleChatInlineCitation(item, evidenceIndex, snapshot, citationNumber) {
    const verification = resolveArticleChatEvidenceTarget(item, snapshot);
    const button = createWorkspaceElement(
        'button', 'article-chat-inline-citation', String(citationNumber)
    );
    button.type = 'button';
    button.dataset.evidenceIndex = String(evidenceIndex);
    button.dataset.citationNumber = String(citationNumber);
    button.dataset.paragraphId = verification.target?.paragraphId || '';
    button.dataset.sourceKey = verification.target?.sourceKey || '';
    const label = item?.sectionTitle || '正文段落';
    const quote = String(item?.quote || item?.support || '').trim();
    applyArticleChatCitationState(button, verification, citationNumber, label);
    if (verification.status === 'verified' && quote) {
        button.title += `\n${quote}`;
    }
    if (isArticleChatCitationFocusable(verification)) button.addEventListener('click', () => {
        void focusArticleChatCitation(item, snapshot, button);
    });
    return button;
}

function normalizeArticleChatMarkdownLinkUrl(value) {
    const rawUrl = String(value || '').trim();
    if (!rawUrl || rawUrl.length > 2048) return '';
    let parsed;
    try {
        parsed = new URL(rawUrl);
    } catch (_) {
        return '';
    }
    if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password ||
        isUnsafeArticleChatWebHostname(parsed.hostname)) return '';
    return parsed.href.length <= 2048 ? parsed.href : '';
}

function createArticleChatMarkdownLink(label, value) {
    const url = normalizeArticleChatMarkdownLinkUrl(value);
    if (!url) return null;
    const link = createWorkspaceElement('a', 'article-chat-markdown-link', label || url);
    link.href = url;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.referrerPolicy = 'no-referrer';
    link.dataset.sourceTrust = 'unverified';
    link.title = '在新标签页打开外部链接（来源未验证）';
    return link;
}

function articleChatMarkdownExplicitLinkAt(text, start) {
    if (text[start] !== '[' || text[start + 1] === '[') return null;
    let labelEnd = -1;
    for (let index = start + 1; index < text.length && text[index] !== '\n'; index += 1) {
        if (text[index] === '\\') {
            index += 1;
            continue;
        }
        if (text[index] === ']' && text[index + 1] === '(') {
            labelEnd = index;
            break;
        }
    }
    if (labelEnd < 0) return null;
    const destinationStart = labelEnd + 2;
    let parenthesisDepth = 0;
    for (let index = destinationStart; index < text.length && text[index] !== '\n'; index += 1) {
        const character = text[index];
        if (/\s/u.test(character)) return null;
        if (character === '\\') {
            index += 1;
            continue;
        }
        if (character === '(') {
            parenthesisDepth += 1;
        } else if (character === ')') {
            if (parenthesisDepth > 0) {
                parenthesisDepth -= 1;
                continue;
            }
            const label = text.slice(start + 1, labelEnd)
                .replace(/\\([\\[\]()])/g, '$1');
            const url = text.slice(destinationStart, index)
                .replace(/\\([\\()])/g, '$1');
            if (!label || !url) return null;
            return { kind: 'link', label, url, length: index - start + 1 };
        }
    }
    return null;
}

function articleChatMarkdownBareUrlAt(text, start) {
    const prefix = text.slice(start, start + 8);
    if (!/^https?:\/\//i.test(prefix)) return null;
    let end = start;
    while (end < text.length && !/[\s<>"'`]/u.test(text[end])) end += 1;
    let candidate = text.slice(start, end);
    while (/[.,;:!?。；，！？：]$/u.test(candidate)) candidate = candidate.slice(0, -1);
    for (const [opening, closing] of [['(', ')'], ['[', ']'], ['{', '}']]) {
        while (candidate.endsWith(closing) &&
            candidate.split(closing).length > candidate.split(opening).length) {
            candidate = candidate.slice(0, -1);
        }
    }
    return candidate ? { kind: 'link', label: candidate, url: candidate, length: candidate.length } : null;
}

function articleChatInlineMarkdownTokenAt(text, start) {
    const citation = text.slice(start).match(/^\[\[(\d{1,3})\]\]/);
    if (citation) return { kind: 'citation', marker: citation[1], length: citation[0].length };
    const explicitLink = articleChatMarkdownExplicitLinkAt(text, start);
    if (explicitLink) return explicitLink;
    const autoLink = text.slice(start).match(/^<(https?:\/\/[^\s<>]+)>/i);
    if (autoLink) return {
        kind: 'link', label: autoLink[1], url: autoLink[1], length: autoLink[0].length
    };
    const scriptToken = text.slice(start).match(
        /^(?:<sup>[^<\n]+<\/sup>|<sub>[^<\n]+<\/sub>)/i
    );
    const scriptMatch = scriptToken?.[0].match(/^<(sup|sub)>([^<\n]+)<\/\1>$/i);
    if (scriptMatch) return {
        kind: 'script', tagName: scriptMatch[1].toLowerCase(), text: scriptMatch[2],
        length: scriptMatch[0].length
    };
    const delimiters = [
        ['`', 'code'], ['**', 'strong'], ['__', 'strong'], ['*', 'em'], ['_', 'em']
    ];
    for (const [delimiter, kind] of delimiters) {
        if (!text.startsWith(delimiter, start)) continue;
        const end = text.indexOf(delimiter, start + delimiter.length);
        if (end > start + delimiter.length && !text.slice(start, end).includes('\n')) {
            return {
                kind,
                text: text.slice(start + delimiter.length, end),
                length: end + delimiter.length - start
            };
        }
    }
    return articleChatMarkdownBareUrlAt(text, start);
}

function appendArticleChatInlineMarkdown(parent, value, context = {}) {
    const text = String(value || '');
    let cursor = 0;
    let plainTextStart = 0;
    while (cursor < text.length) {
        const token = articleChatInlineMarkdownTokenAt(text, cursor);
        if (!token) {
            cursor += 1;
            continue;
        }
        if (cursor > plainTextStart) {
            parent.appendChild(document.createTextNode(text.slice(plainTextStart, cursor)));
        }
        if (token.kind === 'citation') {
            const marker = token.marker;
            const evidenceIndex = (Array.isArray(context.evidence) ? context.evidence : [])
                .findIndex(item => String(item?.marker || '') === marker);
            const evidenceItem = evidenceIndex >= 0 ? context.evidence[evidenceIndex] : null;
            if (evidenceItem) {
                parent.appendChild(createArticleChatInlineCitation(
                    evidenceItem,
                    evidenceIndex,
                    context.snapshot,
                    Math.max(0, Number(context.citationNumberOffset) || 0) + evidenceIndex + 1
                ));
                context.citationIndexes?.add(evidenceIndex);
            } else {
                parent.appendChild(document.createTextNode(text.slice(cursor, cursor + token.length)));
            }
        } else if (token.kind === 'link') {
            parent.appendChild(createArticleChatMarkdownLink(token.label, token.url) ||
                document.createTextNode(text.slice(cursor, cursor + token.length)));
        } else if (token.kind === 'script') {
            const scriptMatch = ['', token.tagName, token.text];
            parent.appendChild(createWorkspaceElement(
                scriptMatch[1], '', scriptMatch[2]
            ));
        } else if (['strong', 'em'].includes(token.kind) &&
            (Number(context.inlineDepth) || 0) < 8) {
            const formatted = createWorkspaceElement(token.kind);
            appendArticleChatInlineMarkdown(formatted, token.text, {
                ...context, inlineDepth: (Number(context.inlineDepth) || 0) + 1
            });
            parent.appendChild(formatted);
        } else {
            parent.appendChild(createWorkspaceElement(token.kind, '', token.text));
        }
        cursor += token.length;
        plainTextStart = cursor;
    }
    if (plainTextStart < text.length) {
        parent.appendChild(document.createTextNode(text.slice(plainTextStart)));
    }
}

function normalizeArticleChatMarkdown(value) {
    return String(value || '')
        .replace(/\r\n?/g, '\n')
        .replace(/([。！？；;：:）)])[\t ]*(\d{1,2}[.)]\s+(?=\*\*|__|[\u3400-\u9fffA-Za-z]))/g, '$1\n\n$2')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

function isArticleChatMarkdownBlockStart(line) {
    return /^(?:#{1,4}\s+|>\s?|```|[-*+]\s+|\d+[.)]\s+)/.test(line) ||
        /^\|?.+\|.+\|?$/u.test(line);
}

function parseArticleChatMarkdownTableRow(value) {
    let line = String(value || '').trim();
    if (!line.includes('|')) return null;
    if (line.startsWith('|')) line = line.slice(1);
    if (line.endsWith('|') && !line.endsWith('\\|')) line = line.slice(0, -1);
    const cells = [];
    let cell = '';
    let code = false;
    for (let index = 0; index < line.length; index += 1) {
        const character = line[index];
        if (character === '\\' && index + 1 < line.length) {
            const escaped = line[index + 1];
            if (['|', '\\', '`'].includes(escaped)) {
                cell += escaped;
                index += 1;
                continue;
            }
        }
        if (character === '`') code = !code;
        if (character === '|' && !code) {
            cells.push(cell.trim());
            cell = '';
        } else {
            cell += character;
        }
    }
    cells.push(cell.trim());
    return cells.length >= 2 ? cells : null;
}

function articleChatMarkdownTableAlignments(cells) {
    if (!Array.isArray(cells) || cells.length < 2) return null;
    const alignments = [];
    for (const value of cells) {
        const cell = String(value || '').trim();
        if (!/^:?-{3,}:?$/u.test(cell)) return null;
        alignments.push(cell.startsWith(':') && cell.endsWith(':')
            ? 'center' : cell.endsWith(':') ? 'right' : 'left');
    }
    return alignments;
}

function createArticleChatMarkdownTable(headerCells, alignments, bodyRows, context) {
    const wrapper = createWorkspaceElement('div', 'article-chat-markdown-table-wrap');
    wrapper.setAttribute('role', 'region');
    wrapper.setAttribute('aria-label', '回答中的表格');
    wrapper.tabIndex = 0;
    const table = createWorkspaceElement('table', 'article-chat-markdown-table');
    const head = document.createElement('thead');
    const headerRow = document.createElement('tr');
    headerCells.forEach((value, index) => {
        const cell = document.createElement('th');
        cell.scope = 'col';
        cell.style.textAlign = alignments[index];
        appendArticleChatInlineMarkdown(cell, value, context);
        headerRow.appendChild(cell);
    });
    head.appendChild(headerRow);
    const body = document.createElement('tbody');
    bodyRows.forEach(row => {
        const tableRow = document.createElement('tr');
        headerCells.forEach((_, index) => {
            const cell = document.createElement('td');
            cell.style.textAlign = alignments[index];
            appendArticleChatInlineMarkdown(cell, row[index] || '', context);
            tableRow.appendChild(cell);
        });
        body.appendChild(tableRow);
    });
    table.append(head, body);
    wrapper.appendChild(table);
    return wrapper;
}

function articleChatOrderedListItemCount(value) {
    return normalizeArticleChatMarkdown(value).split('\n')
        .filter(line => /^\s*\d+[.)]\s+/.test(line)).length;
}

function renderArticleChatMarkdown(value, context = {}) {
    const root = createWorkspaceElement('div', 'article-chat-message-content');
    const renderContext = { ...context, citationIndexes: new Set() };
    const lines = normalizeArticleChatMarkdown(value).split('\n');
    let index = 0;
    let orderedItemsRendered = 0;
    while (index < lines.length) {
        const line = lines[index].trim();
        if (!line) {
            index += 1;
            continue;
        }
        if (line.startsWith('```')) {
            const language = line.slice(3).trim();
            const codeLines = [];
            index += 1;
            while (index < lines.length && !lines[index].trim().startsWith('```')) {
                codeLines.push(lines[index]);
                index += 1;
            }
            if (index < lines.length) index += 1;
            const pre = createWorkspaceElement('pre');
            const code = createWorkspaceElement('code', '', codeLines.join('\n'));
            if (language) code.dataset.language = language;
            pre.appendChild(code);
            root.appendChild(pre);
            continue;
        }
        const tableHeader = parseArticleChatMarkdownTableRow(lines[index]);
        const tableDelimiter = index + 1 < lines.length
            ? parseArticleChatMarkdownTableRow(lines[index + 1]) : null;
        const tableAlignments = articleChatMarkdownTableAlignments(tableDelimiter);
        if (tableHeader && tableAlignments && tableHeader.length === tableAlignments.length) {
            const bodyRows = [];
            index += 2;
            while (index < lines.length && lines[index].trim()) {
                const row = parseArticleChatMarkdownTableRow(lines[index]);
                if (!row) break;
                bodyRows.push(row.slice(0, tableHeader.length));
                index += 1;
            }
            root.appendChild(createArticleChatMarkdownTable(
                tableHeader, tableAlignments, bodyRows, renderContext
            ));
            continue;
        }
        const heading = line.match(/^(#{1,4})\s+(.+)$/);
        if (heading) {
            const element = createWorkspaceElement(`h${Math.min(4, heading[1].length + 2)}`);
            appendArticleChatInlineMarkdown(element, heading[2], renderContext);
            root.appendChild(element);
            index += 1;
            continue;
        }
        const listMatch = line.match(/^([-*+]|\d+[.)])\s+(.+)$/);
        if (listMatch) {
            const ordered = /^\d/.test(listMatch[1]);
            const list = createWorkspaceElement(ordered ? 'ol' : 'ul');
            if (ordered) {
                const explicitStart = Number.parseInt(listMatch[1], 10);
                const continuedStart = Math.max(
                    1,
                    (Number(context.orderedListStart) || 1) + orderedItemsRendered
                );
                const start = Math.max(explicitStart || 1, continuedStart);
                if (start > 1) list.start = start;
            }
            let listItemCount = 0;
            while (index < lines.length) {
                const itemMatch = lines[index].trim().match(/^([-*+]|\d+[.)])\s+(.+)$/);
                if (!itemMatch || /^\d/.test(itemMatch[1]) !== ordered) break;
                const item = createWorkspaceElement('li');
                appendArticleChatInlineMarkdown(item, itemMatch[2], renderContext);
                list.appendChild(item);
                listItemCount += 1;
                index += 1;
            }
            if (ordered) orderedItemsRendered += listItemCount;
            root.appendChild(list);
            continue;
        }
        if (line.startsWith('>')) {
            const quote = createWorkspaceElement('blockquote');
            appendArticleChatInlineMarkdown(quote, line.replace(/^>\s?/, ''), renderContext);
            root.appendChild(quote);
            index += 1;
            continue;
        }
        const paragraphLines = [line];
        index += 1;
        while (index < lines.length && lines[index].trim() &&
            !isArticleChatMarkdownBlockStart(lines[index].trim())) {
            paragraphLines.push(lines[index].trim());
            index += 1;
        }
        const paragraph = createWorkspaceElement('p');
        paragraphLines.forEach((paragraphLine, lineIndex) => {
            if (lineIndex) paragraph.appendChild(document.createElement('br'));
            appendArticleChatInlineMarkdown(paragraph, paragraphLine, renderContext);
        });
        root.appendChild(paragraph);
    }
    root.dataset.inlineCitationCount = String(renderContext.citationIndexes.size);
    root.dataset.inlineCitationIndexes = [...renderContext.citationIndexes].join(',');
    return root;
}

function isUnsafeArticleChatWebHostname(value) {
    const hostname = String(value || '').toLowerCase()
        .replace(/^\[|\]$/g, '').replace(/\.$/, '');
    if (!hostname || hostname === 'localhost' ||
        /(?:^|\.)(?:localhost|local|internal|intranet|home|lan|onion|test|invalid|example)$/.test(hostname)) {
        return true;
    }
    if (hostname.includes(':')) {
        const first = hostname.split(':', 1)[0];
        if (hostname === '::' || hostname === '::1' ||
            hostname.startsWith('::ffff:') ||
            /^(?:fc|fd)[0-9a-f]{0,2}$/i.test(first) ||
            /^fe[89ab][0-9a-f]?$/i.test(first) ||
            /^ff[0-9a-f]{0,2}$/i.test(first) ||
            hostname.startsWith('100:') ||
            hostname === '2001:db8::' || hostname.startsWith('2001:db8:') ||
            hostname.startsWith('2001:0:') || hostname.startsWith('2001:2:') ||
            hostname.startsWith('2002:') || hostname.startsWith('64:ff9b:1:')) {
            return true;
        }
        const mappedIpv4 = hostname.match(/:(\d{1,3}(?:\.\d{1,3}){3})$/)?.[1];
        return mappedIpv4 ? isUnsafeArticleChatWebHostname(mappedIpv4) : false;
    }
    if (/^\d+(?:\.\d+){3}$/.test(hostname)) {
        const octets = hostname.split('.').map(Number);
        if (octets.length !== 4 || octets.some(octet =>
            !Number.isInteger(octet) || octet < 0 || octet > 255)) return true;
        const [a, b, c] = octets;
        return a === 0 || a === 10 || a === 127 || a >= 224 ||
            (a === 100 && b >= 64 && b <= 127) ||
            (a === 169 && b === 254) ||
            (a === 172 && b >= 16 && b <= 31) ||
            (a === 192 && b === 0) ||
            (a === 192 && b === 168) ||
            (a === 198 && (b === 18 || b === 19)) ||
            (a === 198 && b === 51 && c === 100) ||
            (a === 203 && b === 0 && c === 113);
    }
    return !hostname.includes('.');
}

function normalizeArticleChatWebSource(source = {}) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return null;
    const rawUrl = String(source.url || '').trim();
    if (!rawUrl || rawUrl.length > 2048 ||
        typeof SciLLM.isSafeWebSourceUrl !== 'function' ||
        !SciLLM.isSafeWebSourceUrl(rawUrl)) return null;
    let parsed;
    try {
        parsed = new URL(rawUrl);
    } catch (_) {
        return null;
    }
    if (parsed.protocol !== 'https:' || parsed.username || parsed.password ||
        isUnsafeArticleChatWebHostname(parsed.hostname)) return null;
    const url = parsed.href;
    if (url.length > 2048) return null;
    const blockIds = [...new Set((Array.isArray(source.blockIds) ? source.blockIds : [])
        .map(value => String(value || '').trim().slice(0, 160)).filter(Boolean))]
        .slice(0, 160);
    if (!blockIds.length) return null;
    return {
        sourceId: String(source.sourceId || source.id || '').trim().slice(0, 160),
        url,
        title: String(source.title || '').replace(/\s+/g, ' ').trim().slice(0, 300),
        hostname: parsed.hostname.toLowerCase().replace(/\.$/, ''),
        blockIds
    };
}

function isUnverifiedArticleChatTurn(turn = {}) {
    return ['external_import', 'provider_unverified'].includes(turn?.answerProvenance?.origin) &&
        turn?.answerProvenance?.verification === 'unverified';
}

function articleChatWebSourcesForBlock(turn, blockId = '', allSources = false) {
    if (isUnverifiedArticleChatTurn(turn)) return [];
    const receiptId = String(turn?.webGrounding?.receiptId || '').trim();
    const sources = receiptId && Array.isArray(
        turn?.webGrounding?.grounding?.sources
    ) ? turn.webGrounding.grounding.sources : [];
    const targetBlockId = String(blockId || '');
    const seenUrls = new Set();
    const result = [];
    for (const source of sources) {
        const normalized = normalizeArticleChatWebSource(source);
        if (!normalized || (!allSources &&
            !normalized.blockIds.includes(targetBlockId)) || seenUrls.has(normalized.url)) {
            continue;
        }
        seenUrls.add(normalized.url);
        result.push(normalized);
        if (result.length >= 16) break;
    }
    return result;
}

function articleChatWebGroundingRevision(turn, blockId = '', allSources = false) {
    if (isUnverifiedArticleChatTurn(turn)) return 'source-unverified';
    const receiptId = String(turn?.webGrounding?.receiptId || '').slice(0, 200);
    const providerResponseId = String(
        turn?.webGrounding?.grounding?.providerResponseId || ''
    ).slice(0, 200);
    const sourceFingerprint = articleChatWebSourcesForBlock(turn, blockId, allSources)
        .map(source => JSON.stringify([
            source.sourceId, source.url, source.title, source.blockIds
        ])).join('|');
    return `${receiptId}:${providerResponseId}:${sourceFingerprint}`;
}

function createArticleChatWebSourceLink(source, index = 0) {
    const safeSource = normalizeArticleChatWebSource(source);
    if (!safeSource) return null;
    const sourceNumber = Math.max(1, Number(index) || 1);
    const label = safeSource.title || safeSource.hostname;
    const description = `联网来源 ${sourceNumber}：${label}（${safeSource.hostname}）`;
    const link = document.createElement('a');
    link.className = 'article-chat-web-source-dot';
    link.href = safeSource.url;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.referrerPolicy = 'no-referrer';
    link.title = description;
    link.setAttribute('aria-label', `打开${description}`);
    link.textContent = String(sourceNumber);
    return link;
}

function appendArticleChatWebSources(
    parent,
    turn,
    blockId = '',
    { allSources = false } = {}
) {
    const sources = articleChatWebSourcesForBlock(turn, blockId, allSources);
    if (!sources.length) return 0;
    const container = document.createElement('footer');
    container.className = 'article-chat-web-sources';
    container.setAttribute('aria-label', '本回答引用的联网来源');
    const label = document.createElement('span');
    label.className = 'article-chat-web-sources-label';
    label.textContent = '联网来源';
    container.appendChild(label);
    sources.forEach((source, index) => {
        const link = createArticleChatWebSourceLink(source, index + 1);
        if (link) container.appendChild(link);
    });
    if (container.childElementCount <= 1) return 0;
    parent.appendChild(container);
    return container.childElementCount - 1;
}

function appendArticleChatEvidence(parent, message, snapshot, inlineCitationIndexes = []) {
    const evidence = Array.isArray(message?.evidence) ? message.evidence : [];
    const limitations = String(message?.limitations || '').trim();
    const renderedIndexes = new Set(inlineCitationIndexes);
    const missingEvidence = evidence
        .map((item, evidenceIndex) => ({ item, evidenceIndex }))
        .filter(({ evidenceIndex }) => !renderedIndexes.has(evidenceIndex));
    if (missingEvidence.length) {
        const citations = createWorkspaceElement('section', 'article-chat-citation-fallback');
        citations.appendChild(createWorkspaceElement(
            'span', '',
            `${missingEvidence.length} 条证据没有绑定到回答中的具体句子，因此未生成跳转点。`
        ));
        parent.appendChild(citations);
    }
    if (limitations) {
        const details = createWorkspaceElement('details', 'article-chat-limitations');
        details.append(createWorkspaceElement('summary', '', '回答边界'));
        details.appendChild(renderArticleChatMarkdown(limitations));
        parent.appendChild(details);
    }
}

const ARTICLE_CHAT_FAILURE_MESSAGES = Object.freeze({
    ARTICLE_CHAT_SCOPE_EMPTY: '所选章节在当前论文正文中没有可用段落。请重新选择章节；不会改用全文。',
    WEB_SEARCH_UNSUPPORTED: '当前模型不支持联网搜索；请关闭“联网”后重试，或切换支持联网的模型。',
    GROUNDING_MISSING: '联网检索没有返回可核验来源；本轮回答未采用，请重试。',
    WEB_SEARCH_GROUNDING_MISSING: '联网检索没有返回可核验来源；本轮回答未采用，请重试。',
    RESPONSE_INCOMPLETE: '联网回答或来源未完整返回；本轮回答未采用，请重试。',
    WEB_SEARCH_RESPONSE_INCOMPLETE: '联网回答或来源未完整返回；本轮回答未采用，请重试。'
});

function articleChatFailureText(value, fallback = '回答失败') {
    const source = value && typeof value === 'object' ? value : {};
    const raw = typeof value === 'string' ? value : '';
    const code = String(source.errorCode || source.code || raw || '').trim();
    if (ARTICLE_CHAT_FAILURE_MESSAGES[code]) return ARTICLE_CHAT_FAILURE_MESSAGES[code];
    const nestedCode = String(source.error?.code || '').trim();
    if (ARTICLE_CHAT_FAILURE_MESSAGES[nestedCode]) {
        return ARTICLE_CHAT_FAILURE_MESSAGES[nestedCode];
    }
    const message = typeof source.error === 'string'
        ? source.error : String(source.message || '').trim();
    return ARTICLE_CHAT_FAILURE_MESSAGES[message] || message || raw || fallback;
}

function articleChatStatusText(turn = {}) {
    if (turn.intent === 'highlight' && turn.highlightError) {
        return `检索已完成，但原文高亮定位失败：${turn.highlightError}`;
    }
    if (turn.intent === 'highlight' && turn.status === 'completed') {
        return `智能检索完成，已在原文高亮 ${Number(turn.matchCount) || 0} 处匹配。`;
    }
    if (turn.intent === 'highlight' && turn.status === 'generating') {
        return '正在理解检索意图并核对可回定位的原文证据…';
    }
    if (turn.status === 'queued') return '已排队，等待上一轮完成';
    if (turn.status === 'generating') return turn.answerBlocks?.length
        ? '正在继续生成…' : '正在检索全文并组织回答…';
    if (turn.status === 'truncated') return '已保留已完成的回答片段；模型续写后仍达到实际输出上限';
    if (turn.status === 'incomplete') return '已保留通过校验的回答片段；模型续写后仍未形成完整回答';
    if (turn.status === 'cancelled') return '已取消；已完成的回答块已保留';
    if (turn.status === 'interrupted') return '已中断；已完成的回答块已保留，可手动重新生成';
    if (turn.status === 'error') return articleChatFailureText(turn);
    if (turn.status === 'unanswered') return '回答已删除，可以重新生成';
    return '';
}

function renderArticleChatBlock(
    block,
    turn,
    snapshot,
    citationNumberOffset = 0,
    orderedListStart = 1
) {
    const element = createWorkspaceElement('section', 'article-chat-answer-block');
    const blockId = String(block.blockId || '');
    const allSources = block.allSources === true;
    element.dataset.blockId = blockId;
    element.dataset.citationNumberOffset = String(citationNumberOffset);
    element.dataset.orderedListStart = String(orderedListStart);
    element.dataset.webGroundingRevision = articleChatWebGroundingRevision(
        turn, blockId, allSources
    );
    const evidence = isUnverifiedArticleChatTurn(turn) ? [] : block.evidence;
    const markdown = renderArticleChatMarkdown(block.markdown || '', {
        evidence,
        snapshot,
        citationNumberOffset,
        orderedListStart
    });
    element.appendChild(markdown);
    appendArticleChatEvidence(
        element,
        { evidence },
        snapshot,
        String(markdown.dataset.inlineCitationIndexes || '').split(',')
            .filter(Boolean).map(Number)
    );
    appendArticleChatWebSources(element, turn, blockId, { allSources });
    return element;
}

function createArticleChatTurnAction(action, label, turnId) {
    const button = createWorkspaceElement('button', 'article-chat-turn-action', label);
    button.type = 'button';
    button.dataset.articleChatAction = action;
    button.dataset.turnId = turnId;
    button.setAttribute('aria-label', `${label}：本轮问答`);
    return button;
}

function renderArticleChatTurn(turn, snapshot = currentWorkspaceSnapshot) {
    const container = document.getElementById('articleChatMessages');
    if (!container || !turn?.turnId) return null;
    const turnId = String(turn.turnId);
    let element = articleChatTurnElements.get(turnId) ||
        container.querySelector(`[data-turn-id="${turnId}"]`);
    if (!element) {
        element = createWorkspaceElement('article', 'article-chat-turn');
        element.dataset.turnId = turnId;
        const question = createWorkspaceElement(
            'div', 'article-chat-message is-user article-chat-question'
        );
        question.appendChild(createWorkspaceElement('div', 'article-chat-message-content'));
        const answer = createWorkspaceElement(
            'div', 'article-chat-message is-assistant article-chat-answer'
        );
        answer.append(
            createWorkspaceElement('header', 'article-chat-message-meta'),
            createWorkspaceElement('div', 'article-chat-answer-blocks'),
            createWorkspaceElement('p', 'article-chat-turn-status'),
            createWorkspaceElement('div', 'article-chat-turn-actions')
        );
        element.append(question, answer);
        articleChatTurnElements.set(turnId, element);
    }

    const questionContent = element.querySelector('.article-chat-question .article-chat-message-content');
    if (questionContent && questionContent.textContent !== String(turn.question || '')) {
        questionContent.textContent = String(turn.question || '');
    }
    const meta = element.querySelector('.article-chat-message-meta');
    const unverifiedImport = turn.answerProvenance?.origin === 'external_import' &&
        turn.answerProvenance?.verification === 'unverified';
    const unverifiedProvider =
        turn.answerProvenance?.origin === 'provider_unverified' &&
        turn.answerProvenance?.verification === 'unverified';
    const unverifiedSource = unverifiedImport || unverifiedProvider;
    const provenanceLabel = unverifiedProvider
        ? t('联网回答 · 来源未验证')
        : unverifiedImport ? t('外部导入 · 来源未验证') : '';
    const modelLabel = [turn.profileName, turn.model].filter(Boolean).join(' · ');
    if (meta) {
        meta.textContent = [
            provenanceLabel,
            modelLabel || (turn.status === 'queued' ? '等待调用模型' : 'LLM')
        ].filter(Boolean).join(' · ');
        meta.classList.toggle('is-unverified-import', unverifiedImport);
        meta.classList.toggle('is-unverified-source', unverifiedSource);
    }

    const streamedBlocks = Array.isArray(turn.answerBlocks) ? turn.answerBlocks : [];
    const fallbackAnswer = String(turn?.answer || '').trim();
    const blocks = streamedBlocks.length ? streamedBlocks : (fallbackAnswer ? [{
        blockId: 'answer-fallback',
        markdown: fallbackAnswer,
        evidence: [],
        allSources: true
    }] : []);
    const blockContainer = element.querySelector('.article-chat-answer-blocks');
    const expectedBlockIds = new Set(blocks.map(block => String(block.blockId || '')));
    blockContainer?.querySelectorAll('[data-block-id]').forEach(node => {
        if (!expectedBlockIds.has(node.dataset.blockId)) node.remove();
    });
    let citationNumberOffset = 0;
    let orderedListStart = 1;
    blocks.forEach(block => {
        const blockId = String(block.blockId || '');
        const blockEvidenceCount = Array.isArray(block?.evidence) ? block.evidence.length : 0;
        const orderedListItemCount = articleChatOrderedListItemCount(block?.markdown || '');
        const webGroundingRevision = articleChatWebGroundingRevision(
            turn, blockId, block.allSources === true
        );
        if (!blockId) {
            citationNumberOffset += blockEvidenceCount;
            orderedListStart += orderedListItemCount;
            return;
        }
        const existing = blockContainer.querySelector(`[data-block-id="${blockId}"]`);
        if (!existing) {
            blockContainer.appendChild(renderArticleChatBlock(
                block, turn, snapshot, citationNumberOffset, orderedListStart
            ));
        } else if (Number(existing.dataset.citationNumberOffset) !== citationNumberOffset ||
            Number(existing.dataset.orderedListStart) !== orderedListStart ||
            existing.dataset.webGroundingRevision !== webGroundingRevision) {
            existing.replaceWith(renderArticleChatBlock(
                block, turn, snapshot, citationNumberOffset, orderedListStart
            ));
        }
        citationNumberOffset += blockEvidenceCount;
        orderedListStart += orderedListItemCount;
    });

    const status = element.querySelector('.article-chat-turn-status');
    const statusText = articleChatStatusText(turn);
    if (status) {
        status.textContent = statusText;
        status.hidden = !statusText;
        status.classList.toggle('is-error', turn.status === 'error');
    }
    element.classList.toggle('is-queued', turn.status === 'queued');
    element.classList.toggle('is-generating', turn.status === 'generating');
    element.classList.toggle('is-interrupted',
        ['interrupted', 'cancelled', 'truncated', 'incomplete', 'error'].includes(turn.status));

    const actions = element.querySelector('.article-chat-turn-actions');
    if (actions) {
        actions.replaceChildren();
        if (turn.status === 'queued') {
            actions.appendChild(createArticleChatTurnAction(
                'delete-queued', '删除排队问题', turnId
            ));
        } else if (turn.status !== 'generating') {
            if (blocks.length) actions.appendChild(createArticleChatTurnAction(
                'delete-answer', '只删除回答', turnId
            ));
            actions.append(
                createArticleChatTurnAction('regenerate', '重新生成', turnId),
                createArticleChatTurnAction('delete-turn', '删除本轮', turnId)
            );
        }
    }
    return element;
}

function isArticleChatNearBottom(container = document.getElementById('articleChatMessages')) {
    if (!container) return true;
    return container.scrollHeight - container.scrollTop - container.clientHeight <= 72;
}

function updateArticleChatReturnLatest() {
    const button = document.getElementById('articleChatReturnLatest');
    if (button) button.hidden = articleChatFollowLatest ||
        isArticleChatNearBottom();
}

function scrollArticleChatToLatest({ smooth = false } = {}) {
    const container = document.getElementById('articleChatMessages');
    if (!container) return;
    articleChatFollowLatest = true;
    articleChatScrollToLatestActive = smooth;
    container.scrollTo({ top: container.scrollHeight, behavior: smooth ? 'smooth' : 'auto' });
    updateArticleChatReturnLatest();
    if (smooth) setTimeout(() => {
        if (!container.isConnected) return;
        container.scrollTop = container.scrollHeight;
        articleChatScrollToLatestActive = false;
        articleChatFollowLatest = true;
        updateArticleChatReturnLatest();
    }, 180);
}

function syncArticleChatWebSearchToggle(
    loading = currentWorkspaceSnapshot?.chat?.loading === true
) {
    const webSearchToggle = document.getElementById('articleChatWebSearch');
    if (!webSearchToggle) return;
    const enabled = articleChatWebSearchEnabled === true;
    webSearchToggle.disabled = loading || articleChatSubmitPending;
    webSearchToggle.setAttribute('aria-pressed', String(enabled));
    webSearchToggle.setAttribute(
        'aria-label',
        enabled ? '为下一轮关闭联网搜索' : '为下一轮开启联网搜索'
    );
    webSearchToggle.title = enabled
        ? '联网搜索已开启；点击后下一轮仅使用论文正文'
        : '联网搜索已关闭；点击后下一轮将检索网络';
}

function renderArticleChatSnapshot(snapshot = currentWorkspaceSnapshot) {
    renderArticleChatProfileOptions();
    renderArticleChatHighlightCategoryOptions();
    renderArticleSemanticHighlightControls();
    const container = document.getElementById('articleChatMessages');
    const coverage = document.getElementById('articleChatCoverage');
    if (!container || !coverage) return;
    const documentKey = `${snapshot?.url || ''}|${snapshot?.revision || ''}`;
    if (articleChatRenderedDocumentKey && articleChatRenderedDocumentKey !== documentKey) {
        container.querySelectorAll('[data-turn-id]').forEach(node => node.remove());
        articleChatTurnElements.clear();
        articleChatVisibleTurnCount = articleChatHistoryPageSize;
        articleChatFollowLatest = true;
        articleChatContextScopes.clear();
        renderArticleChatContextScopes();
        closeArticleChatCommandMenu();
    }
    articleChatRenderedDocumentKey = documentKey;

    const chat = snapshot?.chat || { turns: [], loading: false, error: '' };
    const turns = Array.isArray(chat.turns) ? chat.turns : [];
    const totalTurns = Math.max(turns.length, Number(chat.totalTurns) || 0);
    const visibleStart = Math.max(
        0,
        Number.isFinite(Number(chat.windowStart))
            ? Number(chat.windowStart) : totalTurns - turns.length
    );
    const visibleTurns = turns;
    const visibleIds = new Set(visibleTurns.map(turn => String(turn.turnId || '')));
    const wasNearBottom = isArticleChatNearBottom(container);

    container.querySelectorAll(':scope > .workspace-empty').forEach(node => node.remove());
    container.querySelectorAll(':scope > [data-turn-id]').forEach(node => {
        if (!visibleIds.has(node.dataset.turnId)) {
            articleChatTurnElements.delete(node.dataset.turnId);
            node.remove();
        }
    });
    visibleTurns.forEach((turn, index) => {
        const element = renderArticleChatTurn(turn, snapshot);
        const current = container.children[index];
        if (element && current !== element) container.insertBefore(element, current || null);
    });
    if (!turns.length) container.appendChild(createWorkspaceElement(
        'div', 'workspace-empty',
        '可以询问结论、机制、方法、证据强弱、局限，或让模型跨章节比较。'
    ));

    const context = chat.coverage;
    coverage.textContent = context
        ? `本轮上下文：${context.sentParagraphs || 0}/${context.totalParagraphs || 0} 段` +
            (context.truncated ? ' · 已按问题覆盖相关章节' : ' · 已发送完整正文')
        : `当前文献已建立正文索引 · ${snapshot?.paragraphs?.length || 0} 段`;
    const loading = chat.loading === true;
    const send = document.getElementById('sendArticleChat');
    const clear = document.getElementById('clearArticleChat');
    const loadEarlier = document.getElementById('articleChatLoadEarlier');
    if (send) {
        send.disabled = loading ? false : !articleChatSelectedProfileId;
        send.dataset.mode = loading ? 'cancel' : 'send';
        send.classList.toggle('is-llm-pending', loading);
        send.setAttribute('aria-busy', String(loading));
        const label = send.querySelector('span');
        const icon = send.querySelector('i');
        if (label) label.textContent = t(loading ? '取消回答' : '发送');
        if (icon) icon.className = loading
            ? 'ph ph-x' : 'ph ph-paper-plane-tilt';
        send.setAttribute('aria-label', t(loading ? '取消回答' : '发送'));
    }
    syncArticleChatWebSearchToggle(loading);
    if (clear) clear.disabled = loading || turns.length === 0;
    if (loadEarlier) {
        loadEarlier.hidden = visibleStart === 0;
        loadEarlier.textContent = visibleStart > 0
            ? `加载更早对话（还有 ${visibleStart} 轮）` : '已显示全部对话';
    }

    if (articleChatFollowLatest && wasNearBottom) {
        requestAnimationFrame(() => scrollArticleChatToLatest());
    } else {
        articleChatFollowLatest = false;
        updateArticleChatReturnLatest();
    }
}

function applyArticleChatStateEvent(event = {}) {
    if (!currentWorkspaceSnapshot) return;
    const currentChat = currentWorkspaceSnapshot.chat || { turns: [] };
    let turns = Array.isArray(currentChat.turns) ? [...currentChat.turns] : [];
    if (event.kind === 'chat_cleared') {
        turns = [];
    } else if (event.kind === 'turn_removed') {
        turns = turns.filter(turn => turn.turnId !== event.turnId);
    } else if (event.turn?.turnId) {
        const index = turns.findIndex(turn => turn.turnId === event.turn.turnId);
        if (index >= 0) turns[index] = event.turn;
        else turns.push(event.turn);
    }
    if (turns.length > articleChatVisibleTurnCount) {
        turns = turns.slice(-articleChatVisibleTurnCount);
    }
    const eventTotalTurns = Number(event.totalTurns);
    const totalTurns = Number.isFinite(eventTotalTurns)
        ? Math.max(0, eventTotalTurns)
        : Math.max(turns.length, Number(currentChat.totalTurns) || 0);
    currentWorkspaceSnapshot = {
        ...currentWorkspaceSnapshot,
        chat: {
            ...currentChat,
            turns,
            totalTurns,
            returnedTurns: turns.length,
            windowStart: Math.max(0, totalTurns - turns.length),
            hasEarlier: totalTurns > turns.length,
            loading: event.loading === true,
            operationId: String(event.operationId || ''),
            activeTurnId: String(event.activeTurnId || ''),
            error: String(event.error || ''),
            coverage: event.coverage || currentChat.coverage || null,
            memoryNeedsRebuild: event.memoryNeedsRebuild === true
        }
    };
    renderArticleChatSnapshot(currentWorkspaceSnapshot);
    cacheCurrentPanelTabState();
}

async function submitArticleChat(event) {
    event?.preventDefault();
    if (articleChatSubmitPending) return;
    const input = document.getElementById('articleChatQuestion');
    const question = String(input?.value || '').trim();
    const profileId = document.getElementById('articleChatProfile')?.value || '';
    const webSearch = Object.freeze({
        enabled: articleChatWebSearchEnabled === true
    });
    if (!question) {
        input?.focus();
        return;
    }
    if (!profileId || llmSettingsState?.settings?.consentGranted !== true) {
        showStatus('请先在设置中配置可用模型并同意发送正文', 'error');
        return;
    }
    const panelContext = capturePanelContext();
    const queuedBehindActive = currentWorkspaceSnapshot?.chat?.loading === true;
    const scopePreflight = preflightArticleChatContextScope(
        articleChatContextScopePayload()
    );
    if (!scopePreflight.success) {
        showStatus(articleChatFailureText(scopePreflight.code), 'error');
        return;
    }
    const contextScope = scopePreflight.contextScope;
    if (input) input.value = '';
    closeArticleChatCommandMenu();
    articleChatSubmitPending = true;
    syncArticleChatWebSearchToggle();
    try {
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'askArticleWithLLM', question, profileId,
            selectedProfileId: profileId,
            contextScope,
            webSearch
        });
        if (!isCurrentPanelContext(panelContext)) return;
        if (!response?.success) {
            const responseError = response?.error;
            const error = new Error(typeof responseError === 'string'
                ? responseError
                : responseError?.message || 'ARTICLE_CHAT_FAILED');
            error.code = response?.code || responseError?.code;
            throw error;
        }
        if (response.turn) {
            const existingTurns = currentWorkspaceSnapshot?.chat?.turns || [];
            const existingTotalTurns = Math.max(
                existingTurns.length,
                Number(currentWorkspaceSnapshot?.chat?.totalTurns) || 0
            );
            const alreadyPresent = existingTurns.some(turn =>
                turn.turnId === response.turn.turnId
            );
            applyArticleChatStateEvent({
                kind: 'turn_added',
                turn: response.turn,
                totalTurns: existingTotalTurns + (alreadyPresent ? 0 : 1),
                loading: currentWorkspaceSnapshot?.chat?.loading === true
            });
        }
        articleChatContextScopes.clear();
        renderArticleChatContextScopes();
        showStatus(queuedBehindActive
            ? '问题已加入队列，将使用提交时选择的模型。' : '问题已发送。', 'success');
    } catch (error) {
        if (!isCurrentPanelContext(panelContext)) return;
        if (input && !input.value) input.value = question;
        showStatus(`全文问答发送失败：${articleChatFailureText(error)}`, 'error');
    } finally {
        articleChatSubmitPending = false;
        syncArticleChatWebSearchToggle();
    }
}

async function submitArticleSemanticHighlight(event) {
    event?.preventDefault();
    const input = document.getElementById('articleSemanticHighlightQuery');
    const question = String(input?.value || '').trim();
    const profileId = document.getElementById('articleSemanticHighlightProfile')?.value || '';
    const categoryId = document.getElementById('articleChatHighlightCategory')?.value || '';
    const categoryOption = document.getElementById('articleChatHighlightCategory')
        ?.selectedOptions?.[0];
    const categoryName = String(
        categoryOption?.dataset.categoryName || categoryOption?.textContent || ''
    );
    const highlightColor = document.getElementById('articleChatHighlightColor')
        ?.value || '#2F80ED';
    if (!question) {
        input?.focus();
        return;
    }
    if (!profileId || !categoryId ||
        llmSettingsState?.settings?.consentGranted !== true) {
        showStatus('请先配置可用模型，并选择智能检索的高亮类别。', 'error');
        return;
    }
    const panelContext = capturePanelContext();
    // This independent highlights form searches the document, never a hidden
    // chat draft or the chat composer's selected chapter scope.
    const scopePreflight = preflightArticleChatContextScope({
        sectionIds: [], sectionTitles: [], scopes: []
    });
    if (!scopePreflight.success) {
        showStatus(articleChatFailureText(scopePreflight.code), 'error');
        return;
    }
    const contextScope = scopePreflight.contextScope;
    if (input) input.value = '';
    try {
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'highlightArticleMatchesWithLLM',
            question,
            profileId,
            categoryId,
            categoryName,
            highlightColor,
            contextScope
        });
        if (!isCurrentPanelContext(panelContext)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'ARTICLE_SEMANTIC_HIGHLIGHT_FAILED');
            error.code = response?.code;
            throw error;
        }
        if (response.turn) {
            const existingTurns = currentWorkspaceSnapshot?.chat?.turns || [];
            const totalTurns = Math.max(
                existingTurns.length,
                Number(currentWorkspaceSnapshot?.chat?.totalTurns) || 0
            );
            const exists = existingTurns.some(turn => turn.turnId === response.turn.turnId);
            applyArticleChatStateEvent({
                kind: 'turn_added',
                turn: response.turn,
                totalTurns: totalTurns + (exists ? 0 : 1),
                loading: currentWorkspaceSnapshot?.chat?.loading === true
            });
        }
        showStatus('智能检索已加入队列；匹配完成后会直接在原文中高亮。', 'success');
    } catch (error) {
        if (!isCurrentPanelContext(panelContext)) return;
        if (input && !input.value) input.value = question;
        showStatus(`智能检索发送失败：${articleChatFailureText(error)}`, 'error');
    }
}

async function cancelArticleChat() {
    if (!currentWorkspaceSnapshot?.chat?.loading) return;
    const panelContext = capturePanelContext();
    const response = await sendTabMessage(panelContext.tabId, {
        action: 'cancelArticleChatWithLLM'
    });
    if (!isCurrentPanelContext(panelContext)) return;
    if (!response?.success) throw new Error(response?.error || 'ARTICLE_CHAT_CANCEL_FAILED');
}

async function clearArticleChatHistory() {
    const panelContext = capturePanelContext();
    const response = await sendTabMessage(panelContext.tabId, { action: 'clearArticleChat' });
    if (!isCurrentPanelContext(panelContext)) return;
    if (!response?.success) throw new Error(response?.error || 'ARTICLE_CHAT_CLEAR_FAILED');
    await refreshArticleWorkspace({ panelContext });
}

async function mutateArticleChatTurn(action, turnId) {
    const panelContext = capturePanelContext();
    const message = { action, turnId };
    if (action === 'regenerateArticleChatTurn') {
        message.profileId = document.getElementById('articleChatProfile')?.value || '';
    }
    const response = await sendTabMessage(panelContext.tabId, message);
    if (!isCurrentPanelContext(panelContext)) return;
    if (!response?.success) throw new Error(response?.error || 'ARTICLE_CHAT_MUTATION_FAILED');
    await refreshArticleWorkspace({ panelContext });
}

async function loadEarlierArticleChatHistory() {
    const container = document.getElementById('articleChatMessages');
    const button = document.getElementById('articleChatLoadEarlier');
    const totalTurns = Math.max(
        0, Number(currentWorkspaceSnapshot?.chat?.totalTurns) || 0
    );
    if (!container || !button || button.disabled ||
        articleChatVisibleTurnCount >= totalTurns) return;
    const previousCount = articleChatVisibleTurnCount;
    const containerRect = container.getBoundingClientRect();
    const anchor = Array.from(container.querySelectorAll(':scope > [data-turn-id]'))
        .find(node => node.getBoundingClientRect().bottom > containerRect.top) ||
        container.querySelector(':scope > [data-turn-id]');
    const anchorTop = anchor?.getBoundingClientRect().top || 0;
    let compensatedScrollHeight = container.scrollHeight;
    const previousOverflowAnchor = container.style.overflowAnchor;
    button.disabled = true;
    container.style.overflowAnchor = 'none';
    try {
        articleChatFollowLatest = false;
        articleChatVisibleTurnCount = Math.min(
            totalTurns,
            articleChatVisibleTurnCount + articleChatHistoryPageSize
        );
        const snapshot = await refreshArticleWorkspace();
        if (!snapshot) {
            articleChatVisibleTurnCount = previousCount;
            throw new Error('ARTICLE_CHAT_HISTORY_LOAD_FAILED');
        }
        if (anchor?.isConnected) {
            // Newly prepended answer cards can settle over the next two frames
            // (layout containment, fonts, and entry animations). Correcting
            // immediately left the old first visible turn about one line lower.
            // A native side panel can be background-throttled while the paper
            // tab owns focus, so requestAnimationFrame is not a reliable
            // completion signal here.
            await new Promise(resolve => setTimeout(resolve, 32));
            for (let attempt = 0; attempt < 4; attempt += 1) {
                const heightDelta = container.scrollHeight - compensatedScrollHeight;
                if (heightDelta) {
                    container.scrollTop += heightDelta;
                    compensatedScrollHeight = container.scrollHeight;
                }
                const offset = anchor.getBoundingClientRect().top - anchorTop;
                if (Math.abs(offset) < 0.25) break;
                container.scrollTop += offset;
                await new Promise(resolve => setTimeout(resolve, 16));
            }
        }
    } finally {
        container.style.overflowAnchor = previousOverflowAnchor;
        button.disabled = false;
    }
}

function handleArticleChatTurnAction(event) {
    const button = event.target.closest('[data-article-chat-action]');
    if (!button) return;
    const actions = {
        'delete-turn': { action: 'deleteArticleChatTurn' },
        'delete-answer': { action: 'deleteArticleChatAnswer' },
        'delete-queued': { action: 'deleteQueuedArticleChatTurn' },
        regenerate: { action: 'regenerateArticleChatTurn' }
    };
    const mutation = actions[button.dataset.articleChatAction];
    if (!mutation) return;
    button.disabled = true;
    void mutateArticleChatTurn(mutation.action, button.dataset.turnId).catch(error => {
        button.disabled = false;
        showStatus(`无法修改本轮问答：${error.message}`, 'error');
    });
}

function withPreparationDeadline(promise, timeoutMs = 15000) {
    let timer;
    return Promise.race([
        promise,
        new Promise((_, reject) => {
            timer = setTimeout(() => {
                const error = new Error('提取超时：15 秒内未完成正文识别');
                error.code = 'ARTICLE_PREPARATION_TIMEOUT';
                reject(error);
            }, timeoutMs);
        })
    ]).finally(() => clearTimeout(timer));
}

function renderArticleConnectionStage(message, title = '') {
    const paperTitle = document.getElementById('sidePanelPaperTitle');
    const statusText = document.getElementById('sidePanelDocumentStatusText');
    const connectionStatus = document.getElementById('sidePanelDocumentStatus');
    if (paperTitle && title) paperTitle.textContent = title;
    if (statusText) statusText.textContent = message;
    connectionStatus?.classList.remove('is-error', 'is-ready');
    const retry = document.getElementById('retryArticlePreparation');
    if (retry) retry.hidden = true;
}

function renderNativePdfReadingBaseline(pdfWorkspace = {}, tab = {}) {
    const snapshot = {
        title: String(tab.title || '文献 PDF')
            .replace(/\s+-\s+Brevess PDF 阅读工作区$/u, ''),
        url: String(pdfWorkspace.sourceUrl || tab.url || ''),
        publisherFamily: 'pdf-original',
        revision: 0,
        diagnostics: {
            headingCount: 0,
            paragraphCount: 0,
            pdfNativeMode: true
        },
        pdfNativeMode: true,
        nodes: [],
        paragraphs: [],
        paragraphNotes: [],
        paragraphSummaries: [],
        ledger: {},
        highlightDistribution: {
            sourceCounts: {}, categories: [], rows: [], totalHighlights: 0
        },
        figures: { figures: [], supplemental: null },
        chat: { turns: [], loading: false }
    };
    renderArticleWorkspaceSnapshot(snapshot);
    const status = document.getElementById('articleNavigationStatus');
    if (status) status.textContent = 'PDF 原始阅读 · 不消耗 MinerU 额度';
    return snapshot;
}

function renderArticleConnectionFailure(error) {
    prepareState = 'idle';
    const paperTitle = document.getElementById('sidePanelPaperTitle');
    const statusText = document.getElementById('sidePanelDocumentStatusText');
    const connectionStatus = document.getElementById('sidePanelDocumentStatus');
    const retry = document.getElementById('retryArticlePreparation');
    if (paperTitle) paperTitle.textContent = currentWorkspaceSnapshot?.title || '当前论文';
    if (statusText) {
        statusText.textContent = error?.code === 'ARTICLE_PAGE_LOADING'
            ? '正文仍在加载，请等待页面稳定后重新提取'
            : error?.code === 'ARTICLE_PREPARATION_TIMEOUT'
            ? '提取超时：可重新提取，或直接导出适配诊断包'
            : '提取失败：' + String(error?.message || '未识别到正文');
    }
    connectionStatus?.classList.remove('is-ready');
    connectionStatus?.classList.toggle('is-error', error?.code !== 'ARTICLE_PAGE_LOADING');
    if (retry) {
        retry.hidden = false;
        retry.disabled = false;
    }
    updateApplyButton();
}

function mergeRefreshedFigureCatalog(snapshot, refreshResult) {
    const liveFigures = Array.isArray(refreshResult?.figures)
        ? refreshResult.figures.filter(figure => figure?.figureId) : [];
    if (!snapshot || !liveFigures.length) return snapshot;
    const workspace = snapshot.figures && typeof snapshot.figures === 'object'
        ? snapshot.figures : {};
    const storedFigures = Array.isArray(workspace.figures) ? workspace.figures : [];
    const storedById = new Map(
        storedFigures.map(figure => [String(figure?.figureId || ''), figure])
    );
    const liveIds = new Set(liveFigures.map(figure => String(figure.figureId)));
    const mergedFigures = liveFigures.map(liveFigure => {
        const stored = storedById.get(String(liveFigure.figureId)) || {};
        return {
            figureInputHash: '',
            activeDepth: 'deep',
            standard: null,
            standardError: '',
            deep: null,
            deepLoading: false,
            deepError: '',
            panelFollowups: {},
            panelFollowupHistories: {},
            panelFollowupLoading: {},
            panelFollowupErrors: {},
            panelAnalyses: {},
            panelAnalysisLoading: {},
            panelAnalysisErrors: {},
            expanded: false,
            ...stored,
            ...liveFigure
        };
    });
    storedFigures.forEach(figure => {
        if (figure?.figureId && !liveIds.has(String(figure.figureId))) {
            mergedFigures.push(figure);
        }
    });
    return {
        ...snapshot,
        figures: {
            ...workspace,
            figures: mergedFigures,
            totalFigures: mergedFigures.length,
            extractorRevision: String(refreshResult?.revision || ''),
            extractorProbeFigureId: String(refreshResult?.probeFigureId || '')
        }
    };
}

let workspaceRefreshInFlight = null;

async function refreshArticleWorkspace(options = {}) {
    const panelContext = options.panelContext || capturePanelContext();
    if (!isCurrentPanelContext(panelContext)) return null;
    const key = JSON.stringify([panelContext.tabId, panelContext.key, panelContext.tabContextSequence]);
    const pending = workspaceRefreshInFlight;
    if (pending?.key === key) {
        if (options.announce === true && !pending.announce) {
            await pending.promise;
            return refreshArticleWorkspace({ ...options, panelContext });
        }
        const result = await pending.promise;
        if (!result && options.throwOnError && pending.error) throw pending.error;
        return result;
    }
    const entry = { key, announce: options.announce === true, promise: null, error: null };
    entry.promise = performArticleWorkspaceRefresh({ ...options, panelContext,
        onError: error => { entry.error = error; } });
    workspaceRefreshInFlight = entry;
    try {
        const result = await entry.promise;
        if (!result && options.throwOnError && entry.error) throw entry.error;
        return result;
    }
    finally {
        if (workspaceRefreshInFlight === entry) workspaceRefreshInFlight = null;
    }
}

async function performArticleWorkspaceRefresh({
    announce = false,
    onError = () => {},
    panelContext = capturePanelContext()
} = {}) {
    const requestId = ++workspaceRefreshSequence;
    if (!isCurrentPanelContext(panelContext)) return null;
    try {
        let figureRefreshResult = null;
        if (panelContext.pdfMode !== true &&
            typeof SciLLM.ensureCompatibleContentRevision === 'function') {
            await SciLLM.ensureCompatibleContentRevision(chrome, panelContext.tabId);
        }
        if ((announce || !currentWorkspaceSnapshot) &&
            panelContext.pdfMode !== true &&
            typeof SciLLM.refreshFigureExtractorInTab === 'function') {
            figureRefreshResult = await SciLLM.refreshFigureExtractorInTab(
                chrome,
                panelContext.tabId
            );
        }
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'getArticleWorkspaceSnapshot',
            forceRefresh: announce || Boolean(figureRefreshResult),
            chatLimit: Math.max(articleChatHistoryPageSize, articleChatVisibleTurnCount)
        });
        if (!response?.success || !response.snapshot) {
            const error = new Error(response?.error || '当前页面结构不可用');
            error.code = response?.code || 'ARTICLE_WORKSPACE_READ_FAILED';
            throw error;
        }
        if (requestId !== workspaceRefreshSequence || !isCurrentPanelContext(panelContext)) {
            return null;
        }
        const refreshedSnapshot = mergeRefreshedFigureCatalog(
            response.snapshot,
            figureRefreshResult
        );
        updatePopupPdfSemanticNavigation(
            response.pdfSemanticNavigation ?? null,
            refreshedSnapshot
        );
        const snapshot = renderArticleWorkspaceSnapshot(refreshedSnapshot);
        restoreMechanismGenerationFromLiveSnapshot(snapshot, {
            tabId: panelContext.tabId
        });
        resumeFigureProgressFromWorkspaceSnapshot(snapshot, {
            tabId: panelContext.tabId
        });
        if (announce) {
            const figureLabels = (snapshot?.figures?.figures || [])
                .map(figure => figure.figureLabel || figure.figureId)
                .filter(Boolean);
            showStatus(
                figureLabels.length
                    ? `Figure 目录已刷新：${figureLabels.join('、')}`
                    : '论文侧栏已刷新',
                'success'
            );
        }
        return snapshot;
    } catch (error) {
        if (requestId !== workspaceRefreshSequence || !isCurrentPanelContext(panelContext)) {
            return null;
        }
        const status = document.getElementById('articleNavigationStatus');
        if (status) status.textContent = '读取失败：' + error.message;
        if (error?.code === 'ARTICLE_PAGE_LOADING') {
            if (status) status.textContent = error.message;
            renderArticleConnectionFailure(error);
        }
        onError(error);
        if (announce) showStatus(error.message,
            error?.code === 'ARTICLE_PAGE_LOADING' ? 'info' : 'error');
        return null;
    }
}

// 初始化
function currentArticleArchiveIdentity() {
    if (currentWorkspaceSnapshot?.publisherFamily === 'pdf-workspace' &&
        currentWorkspaceSnapshot?.documentId && currentWorkspaceSnapshot?.documentHash) {
        return {
            documentId: currentWorkspaceSnapshot.documentId,
            documentHash: currentWorkspaceSnapshot.documentHash,
            canonicalUrl: currentWorkspaceSnapshot.url || '',
            title: currentWorkspaceSnapshot.title || ''
        };
    }
    return {
        documentId: manualAnnotationState.documentId || preparedDocumentState?.documentId ||
            currentWorkspaceSnapshot?.documentId || '',
        documentHash: manualAnnotationState.documentHash || preparedDocumentState?.documentHash ||
            currentWorkspaceSnapshot?.documentHash || '',
        canonicalUrl: manualAnnotationState.canonicalUrl || currentWorkspaceSnapshot?.url || '',
        title: manualAnnotationState.title || currentWorkspaceSnapshot?.title || ''
    };
}

function articleArchivePromptDecisionKey(identity = currentArticleArchiveIdentity()) {
    const documentId = String(identity?.documentId || '').trim();
    return documentId ? `${ARTICLE_ARCHIVE_PROMPT_DECISION_PREFIX}${documentId}` : '';
}

async function readArticleArchivePromptDecision(identity = currentArticleArchiveIdentity()) {
    const key = articleArchivePromptDecisionKey(identity);
    if (!key || !chrome.storage?.session) return null;
    const stored = await chrome.storage.session.get(key).catch(() => ({}));
    return stored?.[key] || null;
}

function rememberArticleArchivePromptDecision(
    decision,
    identity = currentArticleArchiveIdentity()
) {
    const key = articleArchivePromptDecisionKey(identity);
    if (!key || !chrome.storage?.session) return Promise.resolve(false);
    articleArchivePromptDecisionRevision++;
    return chrome.storage.session.set({
        [key]: {
            decision: String(decision || 'handled'),
            documentId: String(identity.documentId || ''),
            canonicalUrl: String(identity.canonicalUrl || ''),
            decidedAt: Date.now()
        }
    }).then(() => true).catch(() => false);
}

function workspaceAlreadyHasArticleResults(snapshot = currentWorkspaceSnapshot) {
    if (!snapshot) return false;
    if (Number(manualAnnotationState?.annotationCount) > 0) return true;
    if (Number(snapshot.highlightDistribution?.totalHighlights) > 0) return true;
    if (Number(snapshot.chat?.totalTurns) > 0) return true;
    if (snapshot.ledger || snapshot.reviewOutline) return true;
    if (Array.isArray(snapshot.paragraphSummaries) && snapshot.paragraphSummaries.length) {
        return true;
    }
    if (snapshot.figures?.crossFigureLogic?.result) return true;
    return (Array.isArray(snapshot.figures?.figures) ? snapshot.figures.figures : [])
        .some(figure => Boolean(
            figure?.standard || figure?.deep ||
            Object.keys(figure?.panelAnalyses || {}).length ||
            Object.keys(figure?.panelFollowupHistories || {}).length
        ));
}

function setArticleArchivePrompt(probe = null) {
    const prompt = document.getElementById('articleArchivePrompt');
    const summary = document.getElementById('articleArchivePromptSummary');
    currentArticleArchiveProbe = probe;
    if (!prompt || !summary) return;
    prompt.hidden = !probe?.found;
    if (!probe?.found) return;
    const parts = [];
    if (probe.savedAt) parts.push(`保存于 ${new Date(probe.savedAt).toLocaleString('zh-CN')}`);
    if (probe.annotationCount) parts.push(`${probe.annotationCount} 条手动标注`);
    if (probe.hasLlmAnalysis) parts.push('含 AI 全文分析');
    if (probe.hasReviewOutline) parts.push('含逐段摘要');
    if (probe.figureCount) parts.push(`${probe.figureCount} 个图解结果`);
    const details = parts.join(' · ') || '已找到本地档案';
    const state = probe.restoreState === 'loading'
        ? '正在核验并加载，请稍候。'
        : probe.restoreState === 'failed'
            ? `加载未完成：${probe.restoreError || '请查看通知中的失败原因'}。`
            : '加载时将核验文献身份与可用结果，也可跳过后重新分析。';
    summary.textContent = `${details}。${state}`;
}

async function probeCurrentArticleArchive({ pristineBaselineProof = null } = {}) {
    const identity = currentArticleArchiveIdentity();
    const decisionRevision = articleArchivePromptDecisionRevision;
    if (!identity.documentId) {
        setArticleArchivePrompt(null);
        return null;
    }
    if (workspaceAlreadyHasArticleResults()) {
        setArticleArchivePrompt(null);
        void rememberArticleArchivePromptDecision('current-workspace', identity);
        return null;
    }
    try {
        const handled = await readArticleArchivePromptDecision(identity);
        // The former empty-workspace auto-restore could cache a false success.
        // Ignore only that automatic decision, using this preparation's proof;
        // never remove session state or undo an explicit user choice.
        const ignoredEmptyAutoRestore = handled?.decision === 'workspace-auto-restored' &&
            pristineBaselineProof &&
            isCurrentPanelContext(pristineBaselineProof.panelContext) &&
            ['documentId', 'documentHash', 'canonicalUrl'].every(key =>
                identity[key] && pristineBaselineProof.identity?.[key] === identity[key]) &&
            handled.documentId === identity.documentId &&
            handled.canonicalUrl === identity.canonicalUrl;
        if ((handled && !ignoredEmptyAutoRestore) ||
            currentArticleArchiveIdentity().documentId !== identity.documentId) {
            setArticleArchivePrompt(null);
            return null;
        }
        const probe = await sendLlmMessage({
            type: 'ARTICLE_ARCHIVE_PROBE',
            documentId: identity.documentId,
            canonicalUrl: identity.canonicalUrl
        });
        // Recheck after the asynchronous read: the user may have skipped this
        // prompt, edited results, or changed the document while it was pending.
        const finalDecision = await readArticleArchivePromptDecision(identity);
        const currentIdentity = currentArticleArchiveIdentity();
        if (decisionRevision !== articleArchivePromptDecisionRevision ||
            ['documentId', 'documentHash', 'canonicalUrl'].some(key =>
                currentIdentity[key] !== identity[key]) ||
            workspaceAlreadyHasArticleResults() ||
            (pristineBaselineProof && !isCurrentPanelContext(pristineBaselineProof.panelContext)) ||
            (finalDecision && !(ignoredEmptyAutoRestore &&
                finalDecision.decision === 'workspace-auto-restored' &&
                finalDecision.documentId === identity.documentId &&
                finalDecision.canonicalUrl === identity.canonicalUrl))) return null;
        setArticleArchivePrompt(probe);
        return probe;
    } catch (error) {
        setArticleArchivePrompt(null);
        const statusText = document.getElementById('sidePanelDocumentStatusText');
        if (statusText && error.code === 'INVALID_JSON_ASSET') {
            statusText.textContent = '本地文献档案已损坏，可重新分析后覆盖保存';
        }
        return null;
    }
}

async function getCurrentArticleArchiveFromTab(panelContext = capturePanelContext()) {
    if (!isCurrentPanelContext(panelContext)) return null;
    const response = await sendTabMessage(panelContext.tabId, {
        action: 'getArticleArchiveSnapshot'
    });
    if (!isCurrentPanelContext(panelContext)) return null;
    if (!response?.success || !response.archive) {
        throw new Error(response?.error || '当前论文档案尚未准备完成');
    }
    return {
        tabId: panelContext.tabId,
        archive: SciLLM.validateArticleArchive(response.archive)
    };
}

async function persistCurrentArticleArchive({
    announce = false,
    panelContext = capturePanelContext()
} = {}) {
    const current = await getCurrentArticleArchiveFromTab(panelContext);
    if (!current || !isCurrentPanelContext(panelContext)) return null;
    const { archive } = current;
    const saved = await sendLlmMessage({ type: 'ARTICLE_ARCHIVE_SAVE', archive });
    if (!isCurrentPanelContext(panelContext)) return null;
    if (announce) showStatus('本文高亮、备注与分析结果已保存到本地目录', 'success');
    return { archive, saved };
}

async function presentCommittedArticleRestoreResult(applied, {
    tabId = null,
    panelContext = null,
    uiState = null,
    refresh = true
} = {}) {
    const status = describeCommittedArticleRestore(applied);
    if (!status) return false;
    if (panelContext && !isCurrentPanelContext(panelContext)) return true;
    if (applied?.workspaceApplied === false || applied?.preservePanelDrafts === true) {
        showStatus(t(status.message), status.type);
        return true;
    }
    if (uiState) applyRestoredSidePanelUiState(uiState);
    if (refresh) {
        if (tabId) await refreshManualAnnotationSummary(tabId).catch(() => null);
        if (panelContext && !isCurrentPanelContext(panelContext)) return true;
        await refreshArticleWorkspace(
            panelContext ? { panelContext } : undefined
        ).catch(() => null);
    }
    if (panelContext && !isCurrentPanelContext(panelContext)) return true;
    if (uiState) applyRestoredSidePanelUiState(uiState);
    setArticleArchivePrompt(null);
    showStatus(t(status.message), status.type);
    return true;
}

async function reinitializeCommittedArticleRestore(tab, restoreTarget, applied) {
    const targetTabId = Number(tab?.id);
    const currentArchive = restoreTarget?.currentArchive || {};
    const committedProof = applied?.manualExecutionProof || {};
    const expectedIdentity = {
        documentId: String(currentArchive.documentId || ''),
        documentHash: String(currentArchive.documentHash || ''),
        canonicalUrl: String(currentArchive.canonicalUrl || ''),
        contentWorldNonce: String(committedProof.contentWorldNonce || ''),
        documentEpoch: Number(committedProof.documentEpoch) || 0,
        operationNonce: String(restoreTarget?.authorizationToken || '')
    };
    if (!Number.isSafeInteger(targetTabId) || !expectedIdentity.documentId ||
        !expectedIdentity.documentHash || !expectedIdentity.canonicalUrl ||
        !/^[a-f0-9]{32,64}$/iu.test(expectedIdentity.contentWorldNonce) ||
        !Number.isSafeInteger(expectedIdentity.documentEpoch) ||
        expectedIdentity.documentEpoch < 1 || !expectedIdentity.operationNonce ||
        String(committedProof.documentId || '') !== expectedIdentity.documentId ||
        String(committedProof.documentHash || '') !== expectedIdentity.documentHash ||
        String(committedProof.canonicalUrl || '') !== expectedIdentity.canonicalUrl) return null;
    const requestId = ++manualSummarySequence;
    const response = await sendTabMessage(targetTabId, {
        action: 'reinitializeManualAnnotations',
        expectedIdentity
    });
    if (!response?.success || response.operationNonce !== expectedIdentity.operationNonce) {
        return null;
    }
    const liveProof = await sendTabMessage(targetTabId, {
        action: 'prepareManualAnnotations'
    });
    const currentTab = await queryPanelTargetTab();
    const matchesFrozenIdentity = proof =>
        String(proof?.documentId || '') === expectedIdentity.documentId &&
        String(proof?.documentHash || '') === expectedIdentity.documentHash &&
        String(proof?.canonicalUrl || '') === expectedIdentity.canonicalUrl &&
        String(proof?.contentWorldNonce || '') === expectedIdentity.contentWorldNonce &&
        Number(proof?.documentEpoch) === expectedIdentity.documentEpoch;
    if (requestId !== manualSummarySequence ||
        !matchesFrozenIdentity(response) || !matchesFrozenIdentity(liveProof) ||
        SciLLM.manualAnnotationRefreshCommitMode({
            expectedTabId: targetTabId,
            capturedTab: tab,
            currentTab,
            response,
            liveProof,
            committedState: manualAnnotationState,
            superseded: false
        }) !== 'response') return null;
    manualAnnotationState = {
        tabId: targetTabId,
        documentId: liveProof.documentId,
        documentHash: liveProof.documentHash,
        canonicalUrl: liveProof.canonicalUrl,
        contentWorldNonce: liveProof.contentWorldNonce,
        documentEpoch: Number(liveProof.documentEpoch),
        title: String(liveProof.title || ''),
        annotationCount: Math.max(0, Number(liveProof.annotationCount) || 0),
        unresolvedCount: Math.max(0, Number(liveProof.unresolvedCount) || 0)
    };
    renderManualAnnotationSummary();
    return manualAnnotationState;
}

function articleArchiveCommitResultMatches(
    result,
    archive,
    currentArchive,
    allowContentChanged
) {
    const returnedArchive = result?.archive;
    const returnedIdentity = {
        documentId: String(returnedArchive?.documentId || ''),
        documentHash: String(returnedArchive?.documentHash || ''),
        canonicalUrl: String(returnedArchive?.canonicalUrl || '')
    };
    const archiveIdentity = {
        documentId: String(archive?.documentId || ''),
        documentHash: String(archive?.documentHash || ''),
        canonicalUrl: String(archive?.canonicalUrl || '')
    };
    const liveIdentity = {
        documentId: String(currentArchive?.documentId || ''),
        documentHash: String(currentArchive?.documentHash || ''),
        canonicalUrl: String(currentArchive?.canonicalUrl || '')
    };
    const relativePath = String(result?.relativePath || '');
    if (result?.applied !== true || result?.permission !== 'imported' ||
        !relativePath || relativePath.length > 2000 ||
        !relativePath.endsWith('.json') || relativePath.includes('\\') ||
        relativePath.includes('..') || relativePath.startsWith('/') ||
        !archiveIdentity.documentId || !archiveIdentity.documentHash ||
        !archiveIdentity.canonicalUrl || !liveIdentity.documentId ||
        !liveIdentity.documentHash || !liveIdentity.canonicalUrl ||
        returnedIdentity.documentId !== archiveIdentity.documentId ||
        returnedIdentity.documentHash !== archiveIdentity.documentHash ||
        returnedIdentity.canonicalUrl !== archiveIdentity.canonicalUrl ||
        returnedIdentity.canonicalUrl !== liveIdentity.canonicalUrl) return false;
    return allowContentChanged === true || (
        returnedIdentity.documentId === liveIdentity.documentId &&
        returnedIdentity.documentHash === liveIdentity.documentHash
    );
}

async function applyLoadedArticleArchive(archive, { imported = false, panelContext = null } = {}) {
    if (panelContext && !isCurrentPanelContext(panelContext)) return null;
    const identity = currentArticleArchiveIdentity();
    const tab = await queryPanelTargetTab();
    if (panelContext && (!isCurrentPanelContext(panelContext) || tab?.id !== panelContext.tabId)) return null;
    if (!tab?.id || !identity.documentId) throw new Error('当前论文尚未准备完成');
    const ensured = await sendTabMessage(tab.id, {
        action: 'ensureArticleWorkspace', forceRefresh: true
    });
    if (!ensured?.success || !ensured.workspace) {
        throw new Error(ensured?.error || 'ARTICLE_WORKSPACE_RESTORE_AUTHORIZATION_REQUIRED');
    }
    if (panelContext && !isCurrentPanelContext(panelContext)) return null;
    const restoreTarget = buildArticleArchiveRestoreTarget(ensured, archive);
    const currentArchive = { ...restoreTarget.currentArchive };
    const allowContentChanged = restoreTarget.allowContentChanged === true;
    const applied = await sendTabMessage(tab.id, {
        action: 'applyArticleArchiveSnapshot',
        archive,
        restoreTarget
    });
    const committedFailure = describeCommittedArticleRestore(applied);
    if (committedFailure) {
        await presentCommittedArticleRestoreResult(applied, { tabId: tab.id, panelContext });
        void rememberArticleArchivePromptDecision(
            imported ? 'imported-committed' : 'loaded-committed',
            currentArchive
        );
        return applied;
    }
    if (!applied?.success) throw new Error(applied?.error || '档案无法恢复到当前页面');
    // Background persistence is authorized only after the live content script
    // has consumed the current-page token and committed the in-page restore.
    let persisted;
    try {
        persisted = await sendLlmMessage({
            type: 'ARTICLE_ARCHIVE_COMMIT_RESTORE',
            documentId: currentArchive.documentId,
            documentHash: currentArchive.documentHash,
            canonicalUrl: currentArchive.canonicalUrl,
            archive,
            current: ensured.workspace,
            currentArchive,
            allowContentChanged,
            operationNonce: restoreTarget.authorizationToken,
            receipt: applied.restoreReceipt
        });
    } catch (error) {
        persisted = { success: false, error: error?.message || '' };
    }
    if (!articleArchiveCommitResultMatches(
        persisted,
        archive,
        currentArchive,
        allowContentChanged
    )) {
        const failure = {
            ...applied,
            success: false,
            committed: true,
            retryable: false,
            postCommitStatus: 'archive-background-commit-failed',
            error: String(persisted?.error || 'ARTICLE_ARCHIVE_COMMIT_RESTORE_FAILED')
        };
        await presentCommittedArticleRestoreResult(failure, {
            tabId: tab.id,
            panelContext,
            refresh: false
        });
        void rememberArticleArchivePromptDecision(
            imported ? 'imported-committed' : 'loaded-committed',
            currentArchive
        );
        return failure;
    }
    if (panelContext && !isCurrentPanelContext(panelContext)) return applied;
    let reinitialized = null;
    try {
        reinitialized = await reinitializeCommittedArticleRestore(
            tab,
            restoreTarget,
            applied
        );
    } catch (_) {
        reinitialized = null;
    }
    if (!reinitialized) {
        const failure = {
            ...applied,
            success: false,
            committed: true,
            retryable: false,
            postCommitStatus: 'content-reinitialize-proof-failed'
        };
        await presentCommittedArticleRestoreResult(failure, {
            tabId: tab.id,
            panelContext,
            refresh: false
        });
        void rememberArticleArchivePromptDecision(
            imported ? 'imported-committed' : 'loaded-committed',
            currentArchive
        );
        return failure;
    }
    if (panelContext && !isCurrentPanelContext(panelContext)) return applied;
    await refreshArticleWorkspace(panelContext ? { panelContext } : undefined);
    if (panelContext && !isCurrentPanelContext(panelContext)) return applied;
    setArticleArchivePrompt(null);
    void rememberArticleArchivePromptDecision(
        imported ? 'imported' : 'loaded',
        currentArchive
    );
    const message = applied.partial
        ? '页面正文与存档版本不同：备注和分析卡片已恢复，旧 AI 文本范围未强行套用。'
        : '上次的高亮、备注与 AI 分析结果已恢复。';
    showStatus(message, applied.partial ? 'error' : 'success');
    return applied;
}

function describeArticleWorkspaceRestoreError(error) {
    const message = String(error?.message || error?.code || error || '未知错误').slice(0, 650);
    const code = String(error?.code || '').slice(0, 120);
    const detail = code && !message.includes(code) ? `${message}；${code}` : message;
    if (/ARTICLE_WORKSPACE_RESTORE_COMMIT_(?:UNKNOWN|UNCONFIRMED)/u.test(detail)) {
        return `后台恢复提交结果尚未确认；请先保留页面与草稿并核对本机记录，不要直接重复恢复（${detail}）`;
    }
    if (/ARTICLE_WORKSPACE_RESTORE_(?:DRAFT_PENDING|MANUAL_CHANGED|PANEL_DRAFT)/u.test(detail)) {
        return `当前有新编辑或尚未保存的草稿，已停止恢复并保留内容；请先完成保存（${detail}）`;
    }
    if (/WORKSPACE_RESTORE_(?:CONFLICT|TOMBSTONE_CONFLICT)/u.test(detail)) {
        return `本机内容或删除记录已改变，旧档案未覆盖当前数据；请重新核对后扫描（${detail}）`;
    }
    if (/ARTICLE_WORKSPACE_RESTORE_LOCAL_CONFLICT/u.test(detail)) {
        return `本机与目录中的保存内容不同；已保留现有内容并停止本次恢复，请先核对需要保留的版本（${detail}）`;
    }
    if (/WORKSPACE_STORE_UNAVAILABLE/u.test(detail)) {
        return `暂时无法核验本机已保存内容，已停止恢复；请稍后重试（${detail}）`;
    }
    const explanation = /ARTICLE_WORKSPACE_RESTORE_TARGET_MISMATCH/u.test(detail)
        ? '当前文献身份或恢复授权与存档不匹配，请确认所在论文后重新加载'
        : /ARTICLE_WORKSPACE_RESTORE_AUTHORIZATION_REQUIRED/u.test(detail)
            ? '当前页面的恢复授权尚未准备好，请刷新论文状态后重试'
            : /ARTICLE_RESTORE_RECEIPT_INVALID/u.test(detail)
                ? '恢复回执未通过校验，无法确认后台保存状态，请先查看当前页面结果'
                : '';
    return explanation ? `${explanation}（${detail}）` : detail;
}

function runArticleWorkspaceRestoreAction(operation) {
    if (articleWorkspaceRestoreGuard.isPending()) {
        return articleWorkspaceRestoreGuard.run(() => null);
    }
    const panelContext = capturePanelContext();
    if (!isCurrentPanelContext(panelContext)) return Promise.resolve(null);
    // Request the directory ticket during the click gesture, before scheduling.
    const permissionTicket = beginArticleWorkspaceDirectoryPermissionRequest();
    return articleWorkspaceRestoreGuard.run(async () => {
        if (!isCurrentPanelContext(panelContext)) return null;
        const controls = ['loadArticleArchive', 'scanArticleWorkspace', 'reanalyzeArticle']
            .map(id => document.getElementById(id)).filter(Boolean)
            .map(button => ({ button, disabled: button.disabled,
                busy: button.getAttribute('aria-busy') }));
        controls.forEach(({ button }) => {
            button.disabled = true;
            button.setAttribute('aria-busy', 'true');
        });
        try {
            return await operation({ panelContext, permissionTicket });
        } finally {
            controls.forEach(({ button, disabled, busy }) => {
                button.disabled = disabled;
                if (busy === null) button.removeAttribute('aria-busy');
                else button.setAttribute('aria-busy', busy);
            });
        }
    });
}

async function loadCurrentArticleArchive() {
    return runArticleWorkspaceRestoreAction(loadArticleArchiveForContext);
}

async function loadArticleArchiveForContext({ panelContext, permissionTicket }) {
    const identity = currentArticleArchiveIdentity();
    if (!identity.documentId || !isCurrentPanelContext(panelContext)) return;
    const probe = currentArticleArchiveProbe;
    if (probe?.found) setArticleArchivePrompt({ ...probe, restoreState: 'loading' });
    try {
        const workspaceRestore = await restoreCurrentArticleWorkspaceFromDirectory({
            panelContext,
            announce: false,
            allowMissing: true,
            permissionTicket
        });
        if (!isCurrentPanelContext(panelContext)) return;
        if (workspaceRestore?.applied?.success ||
            workspaceRestore?.applied?.committed === true) {
            setArticleArchivePrompt(null);
            await rememberArticleArchivePromptDecision('workspace-loaded', identity);
            if (!isCurrentPanelContext(panelContext)) return workspaceRestore.applied;
            if (workspaceRestore.applied.success !== true) {
                return workspaceRestore.applied;
            }
            const pendingStatus = describePreparedArticleWorkspaceRestoreStatus(workspaceRestore.applied);
            if (pendingStatus) { showStatus(pendingStatus.message, pendingStatus.type); return workspaceRestore.applied; }
            const turnCount = Number(workspaceRestore.applied.chatTurns) || 0;
            showStatus(
                turnCount
                    ? `已从本地工作区恢复全部结果和 ${turnCount} 轮历史问答`
                    : '已从本地工作区恢复上次保存的分析结果',
                'success'
            );
            return workspaceRestore.applied;
        }
        const loaded = await sendLlmMessage({
            type: 'ARTICLE_ARCHIVE_LOAD',
            documentId: identity.documentId,
            documentHash: identity.documentHash,
            canonicalUrl: identity.canonicalUrl,
            apply: false
        });
        if (!isCurrentPanelContext(panelContext)) return;
        return await applyLoadedArticleArchive(loaded.archive, { panelContext });
    } catch (error) {
        if (!isCurrentPanelContext(panelContext)) return;
        const detail = describeArticleWorkspaceRestoreError(error);
        if (currentArticleArchiveProbe?.found) {
            setArticleArchivePrompt({ ...probe, restoreState: 'failed', restoreError: detail });
        }
        showStatus(`加载本文档案失败：${detail}`, 'error');
    }
}

function downloadArticleArchive(archive) {
    const blob = new Blob([`${JSON.stringify(archive, null, 2)}\n`], {
        type: 'application/json;charset=utf-8'
    });
    const title = String(archive.title || 'article')
        .replace(/[\\/:*?"<>|]+/g, '-').slice(0, 80) || 'article';
    downloadBlob(blob, `${title}.sci-archive.json`);
}

function exportCurrentArticleArchive() {
    return articleArchiveExportGuard.run(async () => {
        const button = document.getElementById('exportCurrentArticleArchive');
        if (button) {
            button.disabled = true;
            button.setAttribute('aria-busy', 'true');
        }
        let saved = null;
        try {
            const { archive } = await getCurrentArticleArchiveFromTab();
            downloadArticleArchive(archive);
            showStatus('本文档案已导出', 'success');
        } catch (error) {
            showStatus(`导出本文档案失败：${error.message}`, 'error');
        } finally {
            if (button) {
                button.disabled = false;
                button.removeAttribute('aria-busy');
            }
        }
    });
}

function runArticleContentExport({
    guard,
    buttonId,
    action,
    pendingMessage,
    onSuccess
}) {
    return guard.run(async () => {
        const button = document.getElementById(buttonId);
        const panelContext = capturePanelContext();
        if (!Number.isInteger(Number(panelContext.tabId))) {
            showStatus('当前论文页面尚未准备完成', 'error');
            return;
        }
        if (button) {
            button.disabled = true;
            button.setAttribute('aria-busy', 'true');
        }
        showStatus(pendingMessage, 'success');
        try {
            const response = await sendTabMessage(panelContext.tabId, { action });
            if (!response?.success) {
                const error = new Error(response?.error || '导出失败');
                error.code = response?.code || 'CONTENT_EXPORT_FAILED';
                throw error;
            }
            if (isCurrentPanelContext(panelContext)) onSuccess(response);
        } catch (error) {
            if (isCurrentPanelContext(panelContext)) {
                showStatus(`导出失败：${error.message}`, 'error');
            }
        } finally {
            if (button) {
                button.disabled = false;
                button.removeAttribute('aria-busy');
            }
        }
    });
}

function exportPptMaterials() {
    return runArticleContentExport({
        guard: pptMaterialExportGuard,
        buttonId: 'exportPptMaterials',
        action: 'exportPptMaterials',
        pendingMessage: '正在下载所有 Figure 的最高质量图片并整理 PPT 制作材料…',
        onSuccess(response) {
            const missing = Array.isArray(response.missingImageFigureIds)
                ? response.missingImageFigureIds.length : 0;
            showStatus(
                `PPT 材料包已导出：${response.figureCount || 0} 张 Figure、` +
                `${response.imageCount || 0} 个高清图文件` +
                (missing ? `；${missing} 张 Figure 未能下载原图，请查看 manifest` : ''),
                missing ? 'error' : 'success'
            );
        }
    });
}

function exportEnhancedSnapshotToZotero() {
    return runArticleContentExport({
        guard: zoteroSnapshotExportGuard,
        buttonId: 'exportEnhancedSnapshotToZotero',
        action: 'exportEnhancedSnapshotToZotero',
        pendingMessage: '正在下载 Figure 高清原图、固化原网页单栏快照并连接 Zotero…',
        onSuccess(response) {
            const imageCount = Number(response.embeddedImageCount) || 0;
            const missing = Array.isArray(response.missingImageFigureIds)
                ? response.missingImageFigureIds.length : 0;
            if (response.imported) {
                const target = response.collectionName || response.libraryName || '当前文库';
                showStatus(
                    `已保存到 Zotero「${target}」：原网页单栏增强快照内嵌 ${imageCount} 张高清原图，` +
                    `图解与全文问答已分别保存为两个子笔记` +
                    (missing ? `；${missing} 张 Figure 未能获取原图` : ''),
                    missing ? 'error' : 'success'
                );
                return;
            }
            const reason = response.directError?.message || 'Zotero 当前不可用';
            showStatus(
                `未能直接导入 Zotero（${reason}）；已下载内嵌 ${imageCount} 张高清原图的` +
                `单栏增强快照 ZIP`,
                'error'
            );
        }
    });
}

async function importCurrentArticleArchive(event) {
    const input = event.currentTarget;
    const file = input.files?.[0];
    input.value = '';
    if (!file) return;
    try {
        const archive = SciLLM.markArticleArchiveAsExternalImport(
            JSON.parse(await file.text())
        );
        const identity = currentArticleArchiveIdentity();
        if (SciLLM.articleArchiveRelativePath(archive) !==
            SciLLM.articleArchiveRelativePath(identity)) {
            throw new Error('所选档案不属于当前网页文献');
        }
        await sendLlmMessage({ type: 'ARTICLE_ARCHIVE_SAVE', archive });
        await applyLoadedArticleArchive(archive, { imported: true });
    } catch (error) {
        showStatus(`导入本文档案失败：${error.message}`, 'error');
    }
}

function currentLocalArticleWorkspace() {
    return currentWorkspaceSnapshot?.localWorkspace || null;
}

function beginArticleWorkspaceDirectoryPermissionRequest() {
    const handle = articleWorkspaceDirectoryHandle;
    if (!handle || typeof handle.requestPermission !== 'function') {
        // The settings tab may have selected a directory after this side panel
        // was opened. Reloading the handle is enough when that new permission
        // is already granted; if it is "prompt", the next click can invoke
        // requestPermission synchronously with the refreshed handle.
        const promise = refreshArticleWorkspaceDirectoryHandle().then(async refreshed => {
            if (!refreshed) return 'unconfigured';
            try {
                return await refreshed.queryPermission({ mode: 'readwrite' });
            } catch (_) {
                return 'unknown';
            }
        });
        return { started: false, promise };
    }
    try {
        // This call must happen synchronously inside the click handler. Sending
        // it through the service worker or awaiting article preparation first
        // loses the browser user activation and leaves permission at "prompt".
        const promise = Promise.resolve(
            handle.requestPermission({ mode: 'readwrite' })
        ).catch(() => 'unknown');
        return { started: true, promise };
    } catch (_) {
        return { started: true, promise: Promise.resolve('unknown') };
    }
}

async function resolveArticleWorkspaceDirectoryPermission(ticket) {
    const directPermission = await ticket?.promise;
    if (directPermission === 'granted') return 'granted';
    await articleWorkspaceDirectoryHandleReady;
    const handle = articleWorkspaceDirectoryHandle;
    if (!handle) return 'unconfigured';
    try {
        return await handle.queryPermission({ mode: 'readwrite' });
    } catch (_) {
        return 'unknown';
    }
}

function directorySyncFailureMessage(result = {}) {
    if (result.requiresReselection === true) {
        return '原文件夹句柄已失效或目录被移动，请在设置页重新选择同一个基础目录';
    }
    if (result.requiresReauthorization === true || result.permission !== 'granted') {
        return '本地文件夹权限已失效；请再次点击保存，并在浏览器提示中允许访问';
    }
    const code = String(result.errorCode || result.lastErrorCode || '').trim();
    const type = String(result.errorName || result.lastErrorName || '').trim();
    const path = String(result.failedPath || result.lastErrorPath || '').trim();
    const detail = String(result.message || result.lastError || '').trim();
    const suffix = [path, code || type, detail].filter(Boolean).join('：');
    return suffix
        ? `目录写入未完成（${suffix}），数据仍保留在待同步队列中`
        : '目录写入未完成，数据仍保留在待同步队列中，可稍后重试';
}

async function saveCurrentArticleWorkspace() {
    if (articleWorkspaceSaveGuard.isPending()) {
        return articleWorkspaceSaveGuard.run(() => undefined);
    }
    const permissionTicket = beginArticleWorkspaceDirectoryPermissionRequest();
    const operationId = `workspace-save-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    renderArticleWorkspaceSaveProgress({
        operationId,
        initialize: true,
        stage: 'permission',
        status: 'active'
    });
    return articleWorkspaceSaveGuard.run(async () => {
        const button = document.getElementById('saveCurrentArticleWorkspace');
        const panelContext = capturePanelContext();
        let saved = null;
        let activeStage = 'permission';
        if (!isCurrentPanelContext(panelContext)) return;
        if (button) {
            button.disabled = true;
            button.setAttribute('aria-busy', 'true');
        }
        try {
            const directPermission = await resolveArticleWorkspaceDirectoryPermission(
                permissionTicket
            );
            if (directPermission !== 'granted') {
                throw new Error(directPermission === 'unconfigured'
                    ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
                    : '未获得本地文件夹读写权限；请再次点击保存并允许访问');
            }
            const ensured = await sendTabMessage(panelContext.tabId, {
                action: 'ensureArticleWorkspace', forceRefresh: true
            });
            if (!ensured?.success || !ensured.workspace) {
                throw new Error(ensured?.error || '无法识别当前论文的本地工作区');
            }
            const permission = await sendLlmMessage({
                type: 'ARTICLE_WORKSPACE_SCAN_RESTORE',
                identity: ensured.workspace,
                requestPermission: false,
                permissionOnly: true
            });
            if (permission.permission !== 'granted') {
                throw new Error(permission.permission === 'unconfigured'
                    ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
                    : '未获得本地文件夹读写权限，请再次点击并允许访问');
            }
            renderArticleWorkspaceSaveProgress({
                operationId,
                stage: 'permission',
                status: 'done'
            });
            activeStage = 'content';
            saved = await sendTabMessage(panelContext.tabId, {
                action: 'saveArticleWorkspaceNow',
                operationId
            });
            if (!saved?.success) {
                throw new Error(saved?.error || '当前论文工作区保存失败');
            }
            activeStage = 'sync';
            renderArticleWorkspaceSaveProgress({
                operationId,
                stage: 'sync',
                status: 'active'
            });
            const mirrorResult = await sendLlmMessage({
                type: 'ARTICLE_WORKSPACE_MIRROR_ALL',
                workspaceId: saved.workspace?.workspaceId,
                workspaceGeneration: Number(saved.workspace?.workspaceGeneration) || 1,
                transaction: saved.transaction || null
            });
            if (mirrorResult.permission !== 'granted') {
                throw new Error(directorySyncFailureMessage(mirrorResult));
            }
            const syncResult = await sendLlmMessage({
                type: 'USER_DATA_SYNC_NOW',
                drain: true
            });
            if (syncResult.permission !== 'granted' || Number(syncResult.failed) > 0 ||
                Number(syncResult.pendingCount) > 0) {
                throw new Error(directorySyncFailureMessage(syncResult));
            }
            renderArticleWorkspaceSaveProgress({
                operationId,
                stage: 'sync',
                status: 'done'
            });
            if (!isCurrentPanelContext(panelContext)) return;
            const offline = saved.offlineSnapshot;
            const conflictWarningCount = Array.isArray(saved.warnings)
                ? saved.warnings.length : 0;
            const offlineMessage = offline?.saved === true
                ? `，含完整离线正文和 ${offline.embeddedImageCount || 0} 张嵌入图`
                : offline?.disabled === true
                    ? '；设置中已关闭离线正文保存'
                    : offline?.error
                        ? '；工作区已保存，但离线正文快照失败，请重试'
                        : '';
            showStatus(
                `已保存 ${saved.assetCount || 0} 个工作区文件和 ${saved.turnCount || 0} 轮问答到本地文件夹${offlineMessage}`,
                offline?.error || conflictWarningCount ? 'warning' : 'success'
            );
            if (conflictWarningCount) {
                showStatus(
                    `浏览器本地保存已完成；${conflictWarningCount} 项检测到更晚的并发修改，` +
                    '已保留较新版本并将在下一次自动保存时合并。',
                    'warning'
                );
            }
            if (offline?.error) {
                renderArticleWorkspaceSaveProgress({
                    operationId,
                    stage: 'offline',
                    status: 'warning'
                });
            }
        } catch (error) {
            renderArticleWorkspaceSaveProgress({
                operationId,
                stage: activeStage,
                status: saved?.success ? 'warning' : 'error'
            });
            if (saved?.success) {
                showStatus(
                    '本次结果已保存在浏览器；文件夹同步尚未完成。' +
                    String(error?.message || '请查看文件夹权限或稍后重新保存。'),
                    'warning'
                );
            } else {
                showStatus(`保存到本地文件夹失败：${error.message}`, 'error');
            }
        } finally {
            if (button) {
                button.disabled = false;
                button.removeAttribute('aria-busy');
            }
        }
    });
}

function applyRestoredSidePanelUiState(uiState = null) {
    if (!uiState || typeof uiState !== 'object') return;
    restoreFigureOverviewExpansionState(uiState.figureOverviewExpansion);
    if (Array.isArray(uiState.figureExpansion)) {
        figureExpansionState.clear();
        uiState.figureExpansion.forEach(entry => {
            if (Array.isArray(entry) && entry.length >= 2) {
                figureExpansionState.set(String(entry[0]), entry[1] === true);
            }
        });
    }
    if (Array.isArray(uiState.figurePanelExpansion)) {
        figurePanelExpansionState.clear();
        uiState.figurePanelExpansion.forEach(entry => {
            if (Array.isArray(entry) && entry.length >= 2) {
                figurePanelExpansionState.set(String(entry[0]), entry[1] === true);
            }
        });
    }
    if (Array.isArray(uiState.figureMetaExpansion)) {
        figureMetaExpansionState.clear();
        uiState.figureMetaExpansion.forEach(entry => {
            const collection = Array.isArray(entry) ? String(entry[0] || '') : '';
            if (Array.isArray(entry) && entry.length >= 2 &&
                ['backgroundItems', 'scientificQuestions', 'innovationPoints',
                    'limitationPoints'].includes(collection)) {
                figureMetaExpansionState.set(collection, entry[1] === true);
            }
        });
    }
    if (['analysis', 'navigation', 'highlights', 'figures', 'chat', 'notes']
        .includes(uiState.activeWorkspaceView)) {
        switchWorkspaceView(uiState.activeWorkspaceView, { persist: false });
    }
}

function buildArticleWorkspaceRestoreTarget(ensured, restore) {
    const authorization = ensured?.restoreAuthorization;
    const workspace = ensured?.workspace;
    const manifest = restore?.manifest;
    if (!authorization?.token || !workspace?.workspaceId || !manifest?.workspaceId) {
        throw new Error('ARTICLE_WORKSPACE_RESTORE_AUTHORIZATION_REQUIRED');
    }
    const identity = value => ({
        workspaceId: String(value?.workspaceId || ''),
        workspaceGeneration: Number(value?.workspaceGeneration) || 0,
        canonicalUrl: String(value?.canonicalUrl || ''),
        contentHash: String(value?.contentHash || value?.revision || '')
    });
    return {
        authorizationToken: String(authorization.token),
        documentId: String((ensured?.archiveIdentity ?? currentArticleArchiveIdentity()).documentId || ''),
        current: identity(workspace),
        manifest: identity(manifest),
        allowContentChanged: restore?.match === 'content-changed'
    };
}

function publicArticleWorkspaceRestoreCommitTarget(target) {
    return {
        current: { ...(target?.current || {}) },
        manifest: { ...(target?.manifest || {}) },
        allowContentChanged: target?.allowContentChanged === true
    };
}

function hasArticleWorkspaceRestorePanelDrafts() {
    return Boolean(figureWorkspaceInlineEditController.getState().active ||
        literatureNoteDirtyRevisions.size || literatureNoteTemplateSelection ||
        document.getElementById('figureResultEditorDialog')?.open ||
        document.getElementById('supplementalFigureImportDialog')?.open);
}

function assertArticleWorkspaceRestorePanelReady() {
    if (hasArticleWorkspaceRestorePanelDrafts()) {
        const error = new Error('侧栏仍有编辑或正在保存的草稿，请保存或关闭编辑后再恢复；当前内容已保留。');
        error.code = 'ARTICLE_WORKSPACE_RESTORE_PANEL_DRAFT';
        throw error;
    }
}

function preserveArticleWorkspaceRestorePanelDrafts(applied) {
    if ((!applied?.success && applied?.committed !== true) ||
        !hasArticleWorkspaceRestorePanelDrafts()) return applied;
    return { ...applied, success: false, committed: true, retryable: false,
        preservePanelDrafts: true, postCommitStatus: 'panel-draft-retained' };
}

function describePreparedArticleWorkspaceRestoreStatus(applied = {}) {
    const pending = [];
    if (applied.syncStatus === 'pending') pending.push('文件夹同步尚未完成');
    if (applied.manualRebuildDeferred === true) pending.push('人工标注显示重建尚未完成');
    return pending.length ? {
        message: `浏览器工作区恢复已提交；${pending.join('；')}。请保留当前编辑并核对恢复结果。`,
        type: 'warning'
    } : null;
}

async function commitAuthorizedArticleWorkspaceScan(
    ensured, restore, restoreTarget, receipt, applied = {}
) {
    if (applied.persistenceCommitted === true) {
        return { success: true, data: { committed: true, syncStatus: applied.syncStatus } };
    }
    try {
        return await sendLlmMessage({
            type: 'ARTICLE_WORKSPACE_COMMIT_RESTORE',
            identity: { ...ensured.workspace, documentId: restoreTarget.documentId },
            restore,
            requestPermission: false,
            receipt,
            operationNonce: restoreTarget.authorizationToken,
            restoreTarget: publicArticleWorkspaceRestoreCommitTarget(restoreTarget)
        });
    } catch (error) {
        // The page has already applied the restore and registered its receipt.
        // A transport rejection must follow the same post-commit path as a
        // background refusal, rather than becoming an ordinary load failure.
        return { success: false, error: String(error?.message ||
            'ARTICLE_WORKSPACE_COMMIT_RESTORE_FAILED') };
    }
}

function buildArticleArchiveRestoreTarget(ensured, archive) {
    const authorization = ensured?.restoreAuthorization;
    const workspace = ensured?.workspace;
    if (!authorization?.token || !workspace?.workspaceId || !archive?.documentId) {
        throw new Error('ARTICLE_WORKSPACE_RESTORE_AUTHORIZATION_REQUIRED');
    }
    const currentArchive = ensured?.archiveIdentity ?? currentArticleArchiveIdentity();
    return {
        authorizationToken: String(authorization.token),
        current: {
            workspaceId: String(workspace.workspaceId || ''),
            workspaceGeneration: Number(workspace.workspaceGeneration) || 0,
            canonicalUrl: String(workspace.canonicalUrl || ''),
            contentHash: String(workspace.contentHash || workspace.revision || '')
        },
        archive: {
            documentId: String(archive.documentId || ''),
            documentHash: String(archive.documentHash || ''),
            canonicalUrl: String(archive.canonicalUrl || '')
        },
        currentArchive: {
            documentId: String(currentArchive.documentId || ''),
            documentHash: String(currentArchive.documentHash || ''),
            canonicalUrl: String(currentArchive.canonicalUrl || '')
        },
        allowContentChanged: String(archive.documentId || '') !==
            String(currentArchive.documentId || '') ||
            String(archive.documentHash || '') !== String(currentArchive.documentHash || '')
    };
}

function isPristineFigureOnlyWorkspaceRestore(restore, ensured = null) {
    if (restore?.match !== 'exact' || restore.manifest?.workspaceGeneration !== 1 ||
        !Array.isArray(restore.assets) || !restore.assets.length || restore.assets.length > 4 ||
        !Array.isArray(restore.turns) || restore.turns.length ||
        !Array.isArray(restore.manifest?.assets) || restore.manifest.assets.length !== restore.assets.length ||
        typeof SciLLM.createFigureWorkspaceDraft !== 'function') return false;
    // Initialization may subsequently save source baselines, but those can
    // also contain an edited analysis selection. Only known default data counts.
    const allowedPaths = ['figures/workspace-draft.json', 'article/paragraphs.json',
        'article/structure.json', 'article/bibliography.json'];
    const paths = restore.assets.map(asset => asset?.relativePath);
    const manifestPaths = restore.manifest.assets.map(asset => asset?.path);
    if (new Set(paths).size !== paths.length || new Set(manifestPaths).size !== paths.length ||
        paths.some(path => !allowedPaths.includes(path) || !manifestPaths.includes(path))) return false;
    const draft = restore.assets.find(asset => asset.relativePath === 'figures/workspace-draft.json')?.content;
    if (!draft || typeof draft !== 'object' || Array.isArray(draft) ||
        ['workspaceId', 'workspaceGeneration', 'canonicalUrl'].some(key =>
            draft.binding?.[key] !== restore.manifest[key])) return false;
    // Compare the raw saved content with the current empty initializer, without
    // normalizing away edits, explicit clears, tombstones, or future fields.
    const { binding: _binding, ...content } = draft;
    const same = (left, right) => {
        if (left === right) return true;
        if (!left || !right || typeof left !== 'object' || typeof right !== 'object' ||
            Array.isArray(left) !== Array.isArray(right)) return false;
        const keys = Object.keys(left);
        return keys.length === Object.keys(right).length && keys.every(key =>
            Object.hasOwn(right, key) && same(left[key], right[key]));
    };
    if (restore.assets.length > 1) {
        const paragraphs = restore.assets.find(asset => asset.relativePath === 'article/paragraphs.json')?.content;
        const structure = restore.assets.find(asset => asset.relativePath === 'article/structure.json')?.content;
        const hasOnlyKeys = (value, keys) => value && typeof value === 'object' &&
            !Array.isArray(value) && Object.keys(value).length === keys.length &&
            keys.every(key => Object.hasOwn(value, key));
        if (!hasOnlyKeys(paragraphs, ['revision', 'paragraphs']) ||
            !Array.isArray(paragraphs.paragraphs) ||
            !hasOnlyKeys(structure, ['documentId', 'documentHash', 'title', 'url',
                'publisherFamily', 'revision', 'diagnostics', 'nodes']) ||
            !Array.isArray(structure.nodes)) return false;
        const sectionKinds = new Map();
        for (const paragraph of paragraphs.paragraphs) {
            if (!hasOnlyKeys(paragraph, ['paragraphId', 'sourceKey', 'sourceIdentity',
                'text', 'textHash', 'displayText', 'sectionId', 'sectionKind',
                'sectionTitle', 'displaySectionTitle', 'sectionPath', 'navigationRevision']) ||
                !paragraph.sectionId || typeof paragraph.sectionKind !== 'string') return false;
            if (sectionKinds.has(paragraph.sectionId) &&
                sectionKinds.get(paragraph.sectionId) !== paragraph.sectionKind) return false;
            sectionKinds.set(paragraph.sectionId, paragraph.sectionKind);
        }
        // Matches content.js defaultArticleAnalysisSectionSelection. Unknown
        // leaves or future serialized fields must retain the normal restore.
        const defaultKinds = new Set(['abstract', 'main', 'introduction',
            'results', 'discussion', 'conclusion']);
        const isDefaultNode = node => {
            if (!hasOnlyKeys(node, ['sectionId', 'sourceKey', 'title', 'displayTitle',
                'level', 'order', 'paragraphCount', 'sectionKind', 'analysisSectionIds',
                'analysisLeafSectionIds', 'analysisSelected', 'analysisIndeterminate', 'children']) ||
                !Array.isArray(node.analysisLeafSectionIds) ||
                !Array.isArray(node.children) ||
                node.analysisLeafSectionIds.some(id => !sectionKinds.has(id))) return false;
            const states = node.analysisLeafSectionIds.map(id =>
                defaultKinds.has(sectionKinds.get(id).toLowerCase()));
            return node.analysisSelected === (states.length > 0 && states.every(Boolean)) &&
                node.analysisIndeterminate === (states.some(Boolean) && !states.every(Boolean)) &&
                node.children.every(isDefaultNode);
        };
        if (!structure.nodes.every(isDefaultNode)) return false;
        const bibliography = restore.assets.find(asset => asset.relativePath === 'article/bibliography.json');
        if (bibliography) {
            // No saved provenance flag can establish "automatic": compare raw
            // data with this ensure response's fresh, same-owner DOM extraction.
            // Never normalize away user edits, explicit clears or unknown fields.
            if (ensured?.success !== true || !ensured.bibliographyBaseline ||
                ['workspaceId', 'workspaceGeneration', 'canonicalUrl'].some(key =>
                    ensured.workspace?.[key] !== restore.manifest[key]) ||
                ['documentId', 'documentHash'].some(key =>
                    !structure[key] || ensured.archiveIdentity?.[key] !== structure[key]) ||
                ensured.archiveIdentity?.canonicalUrl !== restore.manifest.canonicalUrl ||
                bibliography.content?.workspaceId !== restore.manifest.workspaceId ||
                bibliography.content?.canonicalUrl !== restore.manifest.canonicalUrl ||
                !same(bibliography.content, ensured.bibliographyBaseline)) return false;
        }
    }
    return same(content, SciLLM.createFigureWorkspaceDraft([]));
}

async function restoreCurrentArticleWorkspaceFromDirectory({
    panelContext = capturePanelContext(),
    announce = true,
    allowMissing = false,
    requestPermission = true,
    permissionTicket = null,
    onPristineBaseline = null
} = {}) {
    if (!isCurrentPanelContext(panelContext)) return null;
    if (requestPermission === true) {
        const permission = await resolveArticleWorkspaceDirectoryPermission(permissionTicket);
        if (permission !== 'granted') {
            if (allowMissing) return null;
            throw new Error(permission === 'unconfigured'
                ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
                : '未获得本地文件夹读取权限；请再次点击并允许访问');
        }
    }
    if (!isCurrentPanelContext(panelContext)) return null;
    const ensured = await sendTabMessage(panelContext.tabId, {
        action: 'ensureArticleWorkspace',
        forceRefresh: true
    });
    if (!ensured?.success || !ensured.workspace) {
        if (allowMissing) return null;
        throw new Error(ensured?.error || '无法识别当前论文的本地工作区');
    }
    if (!isCurrentPanelContext(panelContext)) return null;
    assertArticleWorkspaceRestorePanelReady();
    const scanned = await sendLlmMessage({
        type: 'ARTICLE_WORKSPACE_SCAN_RESTORE',
        operationNonce: ensured.restoreAuthorization?.token,
        identity: { ...ensured.workspace, documentId: String((ensured.archiveIdentity ?? currentArticleArchiveIdentity()).documentId || ''),
            documentHash: String((ensured.archiveIdentity ?? currentArticleArchiveIdentity()).documentHash || '') },
        ...(ensured.documentCreationToken ? { documentCreationToken: ensured.documentCreationToken } : {}),
        requestPermission: false
    });
    if (!isCurrentPanelContext(panelContext)) return null;
    if (scanned.permission !== 'granted') {
        if (allowMissing) return null;
        throw new Error(scanned.permission === 'unconfigured'
            ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
            : '未获得本地文件夹读取权限，请再次点击并允许访问');
    }
    if (!scanned.restore) {
        if (allowMissing) return null;
        showStatus('本地文件夹中没有匹配当前网页的工作区', 'error');
        return null;
    }
    // An automatically initialized empty Figure draft must not hide an older
    // saved article. Discover it through the existing archive prompt before
    // committing anything; only an explicit load can apply the legacy result.
    if (allowMissing && isPristineFigureOnlyWorkspaceRestore(scanned.restore, ensured)) {
        if (typeof onPristineBaseline === 'function') onPristineBaseline({
            panelContext,
            identity: { ...ensured.archiveIdentity, canonicalUrl: ensured.workspace.canonicalUrl }
        });
        return null;
    }
    const restoreTarget = buildArticleWorkspaceRestoreTarget(ensured, scanned.restore);
    assertArticleWorkspaceRestorePanelReady();
    const applied = preserveArticleWorkspaceRestorePanelDrafts(await sendTabMessage(panelContext.tabId, {
        action: 'applyArticleWorkspaceAssets',
        restore: {
            ...scanned.restore,
            restoreTarget
        }
    }));
    const committedFailure = describeCommittedArticleRestore(applied);
    if (committedFailure) {
        await presentCommittedArticleRestoreResult(applied, {
            tabId: panelContext.tabId,
            panelContext,
            uiState: applied.uiState
        });
        return { scanned, applied };
    }
    if (!applied?.success) {
        throw new Error(applied?.error || '本地工作区恢复失败');
    }
    const committed = await commitAuthorizedArticleWorkspaceScan(
        ensured, scanned.restore, restoreTarget, applied.restoreReceipt, applied
    );
    if (!committed?.success) {
        const failure = {
            ...applied,
            success: false,
            committed: true,
            retryable: false,
            postCommitStatus: 'workspace-background-commit-failed',
            error: String(committed?.error || 'ARTICLE_WORKSPACE_COMMIT_RESTORE_FAILED')
        };
        await presentCommittedArticleRestoreResult(failure, {
            tabId: panelContext.tabId,
            panelContext,
            uiState: applied.uiState
        });
        return { scanned, applied: failure };
    }
    if (!isCurrentPanelContext(panelContext)) return { scanned, applied };
    applyRestoredSidePanelUiState(applied.uiState);
    await refreshManualAnnotationSummary(panelContext.tabId);
    if (!isCurrentPanelContext(panelContext)) return { scanned, applied };
    await refreshArticleWorkspace({ panelContext });
    if (!isCurrentPanelContext(panelContext)) return { scanned, applied };
    applyRestoredSidePanelUiState(applied.uiState);
    const pendingStatus = describePreparedArticleWorkspaceRestoreStatus(applied);
    if (announce && pendingStatus) {
        showStatus(pendingStatus.message, pendingStatus.type);
    } else if (announce) {
        const turnCount = Number(applied.chatTurns) || 0;
        showStatus(
            applied.partial
                ? '已安全恢复问答、图解和分析卡片；正文已变化，旧文本范围未强行套用'
                : turnCount
                    ? `已恢复当前网页的本地工作区和 ${turnCount} 轮历史问答`
                    : '已恢复当前网页的本地工作区',
            applied.partial ? 'error' : 'success'
        );
    }
    return { scanned, applied };
}

async function tryAutoRestoreCurrentArticleWorkspace(
    panelContext = capturePanelContext(),
    { onPristineBaseline = null } = {}
) {
    if (!isCurrentPanelContext(panelContext) ||
        workspaceAlreadyHasArticleResults(currentWorkspaceSnapshot)) {
        return null;
    }
    try {
        const restored = await restoreCurrentArticleWorkspaceFromDirectory({
            panelContext,
            announce: false,
            allowMissing: true,
            requestPermission: false,
            onPristineBaseline
        });
        if ((!restored?.applied?.success && restored?.applied?.committed !== true) ||
            !isCurrentPanelContext(panelContext)) {
            return null;
        }
        if (restored.applied.success !== true) return restored;
        setArticleArchivePrompt(null);
        await rememberArticleArchivePromptDecision(
            'workspace-auto-restored',
            currentArticleArchiveIdentity()
        );
        if (!isCurrentPanelContext(panelContext)) return restored;
        const turnCount = Number(restored.applied.chatTurns) || 0;
        showStatus(
            turnCount
                ? `已自动恢复本地工作区和 ${turnCount} 轮历史问答`
                : '已自动恢复当前网页的本地工作区',
            'success'
        );
        return restored;
    } catch (_) {
        // Automatic restoration must never block article reading. If the
        // browser requires a fresh directory gesture, the existing explicit
        // load/scan control remains available.
        return null;
    }
}

async function scanCurrentArticleWorkspace() {
    return runArticleWorkspaceRestoreAction(scanArticleWorkspaceForContext);
}

async function scanArticleWorkspaceForContext({ panelContext, permissionTicket }) {
    if (!isCurrentPanelContext(panelContext)) return;
    const probe = currentArticleArchiveProbe;
    if (probe?.found) setArticleArchivePrompt({ ...probe, restoreState: 'loading' });
    try {
        const directPermission = await resolveArticleWorkspaceDirectoryPermission(
            permissionTicket
        );
        if (directPermission !== 'granted') {
            throw new Error(directPermission === 'unconfigured'
                ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
                : '未获得本地文件夹读取权限；请再次点击扫描并允许访问');
        }
        if (!isCurrentPanelContext(panelContext)) return;
        const ensured = await sendTabMessage(panelContext.tabId, {
            action: 'ensureArticleWorkspace', forceRefresh: true
        });
        if (!ensured?.success || !ensured.workspace) {
            throw new Error(ensured?.error || '无法识别当前论文的本地工作区');
        }
        if (!isCurrentPanelContext(panelContext)) return;
        const identity = ensured.workspace;
        assertArticleWorkspaceRestorePanelReady();
        const scanned = await sendLlmMessage({
            type: 'ARTICLE_WORKSPACE_SCAN_RESTORE',
            operationNonce: ensured.restoreAuthorization?.token,
            identity: { ...identity, documentId: String((ensured.archiveIdentity ?? currentArticleArchiveIdentity()).documentId || ''),
            documentHash: String((ensured.archiveIdentity ?? currentArticleArchiveIdentity()).documentHash || '') },
            ...(ensured.documentCreationToken ? { documentCreationToken: ensured.documentCreationToken } : {}),
            requestPermission: false
        });
        if (!isCurrentPanelContext(panelContext)) return;
        if (scanned.permission !== 'granted') {
            throw new Error(scanned.permission === 'unconfigured'
                ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
                : '未获得本地文件夹读取权限，请再次点击并允许访问');
        }
        if ((!scanned.restore && scanned.matches?.[0]?.match === 'legacy-imported') ||
            isPristineFigureOnlyWorkspaceRestore(scanned.restore, ensured)) {
            return await loadArticleArchiveForContext({ panelContext, permissionTicket });
        }
        if (!scanned.restore) {
            throw new Error('本地文件夹中没有匹配当前网页的工作区');
        }
        const restoreTarget = buildArticleWorkspaceRestoreTarget(ensured, scanned.restore);
        assertArticleWorkspaceRestorePanelReady();
        const applied = preserveArticleWorkspaceRestorePanelDrafts(await sendTabMessage(panelContext.tabId, {
            action: 'applyArticleWorkspaceAssets',
            restore: {
                ...scanned.restore,
                restoreTarget
            }
        }));
        const committedFailure = describeCommittedArticleRestore(applied);
        if (committedFailure) {
            await presentCommittedArticleRestoreResult(applied, {
                tabId: panelContext.tabId,
                panelContext,
                uiState: applied.uiState
            });
            return applied;
        }
        if (!applied?.success) throw new Error(applied?.error || '本地工作区恢复失败');
        const committed = await commitAuthorizedArticleWorkspaceScan(
            ensured, scanned.restore, restoreTarget, applied.restoreReceipt, applied
        );
        if (!committed?.success) {
            const failure = {
                ...applied,
                success: false,
                committed: true,
                retryable: false,
                postCommitStatus: 'workspace-background-commit-failed',
                error: String(committed?.error || 'ARTICLE_WORKSPACE_COMMIT_RESTORE_FAILED')
            };
            await presentCommittedArticleRestoreResult(failure, {
                tabId: panelContext.tabId,
                panelContext,
                uiState: applied.uiState
            });
            return failure;
        }
        if (!isCurrentPanelContext(panelContext)) return applied;
        applyRestoredSidePanelUiState(applied.uiState);
        await refreshManualAnnotationSummary(panelContext.tabId);
        if (!isCurrentPanelContext(panelContext)) return applied;
        await refreshArticleWorkspace({ panelContext });
        if (!isCurrentPanelContext(panelContext)) return applied;
        applyRestoredSidePanelUiState(applied.uiState);
        if (!isCurrentPanelContext(panelContext)) return applied;
        setArticleArchivePrompt(null);
        const pendingStatus = describePreparedArticleWorkspaceRestoreStatus(applied);
        if (pendingStatus) { showStatus(pendingStatus.message, pendingStatus.type); return applied; }
        showStatus(applied.partial
            ? '已安全恢复问答、图解和分析卡片；正文已变化，旧文本范围未强行套用'
            : '已恢复当前网页的本地工作区', applied.partial ? 'error' : 'success');
    } catch (error) {
        if (!isCurrentPanelContext(panelContext)) return;
        const detail = describeArticleWorkspaceRestoreError(error);
        if (currentArticleArchiveProbe?.found) {
            setArticleArchivePrompt({ ...probe, restoreState: 'failed', restoreError: detail });
        }
        showStatus(`扫描本地工作区失败：${detail}`, 'error');
    }
}

async function clearCurrentArticleWorkspace() {
    const permissionTicket = beginArticleWorkspaceDirectoryPermissionRequest();
    const button = document.getElementById('clearArticleWorkspace');
    const workspace = currentLocalArticleWorkspace();
    const panelContext = capturePanelContext();
    if (!workspace?.workspaceId || !isCurrentPanelContext(panelContext)) {
        showStatus('当前网页尚未建立本地工作区', 'error');
        return;
    }
    const counts = currentWorkspaceSnapshot?.diagnostics || {};
    const accepted = confirm(
        `确定清除“${currentWorkspaceSnapshot?.title || '当前论文'}”的本地工作区吗？\n` +
        `包含 ${currentWorkspaceSnapshot?.chat?.totalTurns || 0} 轮问答、` +
        `${currentWorkspaceSnapshot?.figures?.totalFigures || 0} 个 Figure 结果和` +
        `${counts.paragraphCount || 0} 段正文索引。此操作不可撤销。`
    );
    if (!accepted) return;
    if (button) button.disabled = true;
    try {
        const directPermission = await resolveArticleWorkspaceDirectoryPermission(
            permissionTicket
        );
        if (directPermission !== 'granted') {
            throw new Error(directPermission === 'unconfigured'
                ? '尚未设置本地保存文件夹，请先到设置页面选择文件夹'
                : '未获得本地文件夹读写权限；请再次点击清除并允许访问');
        }
        await sendLlmMessage({
            type: 'ARTICLE_WORKSPACE_SCAN_RESTORE', identity: workspace,
            requestPermission: false
        }).catch(() => null);
        const begun = await sendLlmMessage({
            type: 'ARTICLE_WORKSPACE_BEGIN_DELETE', workspaceId: workspace.workspaceId
        });
        await sendTabMessage(panelContext.tabId, { action: 'freezeArticleWorkspaceWrites' });
        const finalized = await sendLlmMessage({
            type: 'ARTICLE_WORKSPACE_FINALIZE_DELETE',
            workspaceId: workspace.workspaceId,
            tombstoneId: begun.tombstoneId
        });
        if (!finalized.deleted) {
            throw new Error('本地文件夹权限不足，清除已暂停；再次授权后可继续');
        }
        workspaceGeneration = Math.max(
            workspaceGeneration + 1,
            Number(begun.workspaceGeneration || workspace.workspaceGeneration || 1) + 1
        );
        const reset = await sendTabMessage(panelContext.tabId, {
            action: 'resetArticleWorkspaceState', workspaceGeneration
        });
        if (!reset?.success) throw new Error(reset?.error || '页面状态重置失败');
        activeWorkspaceView = 'analysis';
        await refreshArticleWorkspace({ panelContext });
        switchWorkspaceView('analysis');
        showStatus('当前网页的本地内容已清除，并已建立新的空工作区', 'success');
    } catch (error) {
        showStatus(`清除当前页本地内容失败：${error.message}`, 'error');
    } finally {
        if (button) button.disabled = false;
    }
}

function setupArticleArchiveControls() {
    document.getElementById('loadArticleArchive')
        ?.addEventListener('click', loadCurrentArticleArchive);
    document.getElementById('reanalyzeArticle')?.addEventListener('click', () => {
        void rememberArticleArchivePromptDecision('skipped');
        setArticleArchivePrompt(null);
        switchWorkspaceView('analysis');
        showStatus('已跳过旧档案，可按当前设置重新分析', 'success');
    });
    document.getElementById('exportCurrentArticleArchive')
        ?.addEventListener('click', exportCurrentArticleArchive);
    document.getElementById('exportPptMaterials')
        ?.addEventListener('click', exportPptMaterials);
    document.getElementById('exportEnhancedSnapshotToZotero')
        ?.addEventListener('click', exportEnhancedSnapshotToZotero);
    document.getElementById('saveCurrentArticleWorkspace')
        ?.addEventListener('click', saveCurrentArticleWorkspace);
    document.getElementById('importCurrentArticleArchive')
        ?.addEventListener('change', importCurrentArticleArchive);
    document.getElementById('importCurrentArticleArchiveButton')
        ?.addEventListener('click', () => {
            document.getElementById('importCurrentArticleArchive')?.click();
        });
    document.getElementById('scanArticleWorkspace')
        ?.addEventListener('click', scanCurrentArticleWorkspace);
    document.getElementById('clearArticleWorkspace')
        ?.addEventListener('click', clearCurrentArticleWorkspace);
}

function setupAdapterDiagnosticControls() {
    document.getElementById('exportAdapterDiagnosticBundle')
        ?.addEventListener('click', exportAdapterDiagnosticBundle);
    document.getElementById('retryArticlePreparation')
        ?.addEventListener('click', () => void initializeCurrentArticle({ retry: true }));
}

async function initializeCurrentArticle({ retry = false } = {}) {
    const requestId = ++articlePreparationSequence;
    const retryButton = document.getElementById('retryArticlePreparation');
    if (retryButton) {
        retryButton.hidden = true;
        retryButton.disabled = true;
    }
    renderArticleConnectionStage(
        retry ? '正在重新提取当前论文…' : '正在读取当前页面结构…',
        retry ? (currentWorkspaceSnapshot?.title || '当前论文') : '正在连接当前论文…'
    );
    try {
        const snapshot = await withPreparationDeadline((async () => {
            renderArticleConnectionStage('正在生成本地标题层级与段落索引…');
            let workspace = null;
            let lastRefreshError = null;
            const readinessDelays = retry ? [0, 250, 600] : [0, 250, 750, 1400];
            for (const delay of readinessDelays) {
                if (delay) await new Promise(resolve => setTimeout(resolve, delay));
                try {
                    workspace = await refreshArticleWorkspace({ throwOnError: true });
                } catch (error) {
                    lastRefreshError = error;
                    if (error?.code !== 'ARTICLE_PAGE_LOADING') throw error;
                }
                if (workspace) break;
                renderArticleConnectionStage('正文页面仍在加载，正在等待页面结构稳定…');
            }
            if (!workspace) throw lastRefreshError || new Error('当前页面结构不可用');
            if (analysisMode !== 'llm') {
                await refreshManualAnnotationSummary();
                requestMatchCounts();
            }
            return workspace;
        })(), 15000);
        if (requestId !== articlePreparationSequence) return null;
        renderArticleWorkspaceSnapshot(snapshot);
        const panelContext = capturePanelContext();
        let pristineBaselineProof = null;
        const restored = await tryAutoRestoreCurrentArticleWorkspace(panelContext, {
            onPristineBaseline: proof => { pristineBaselineProof = proof; }
        });
        if (requestId !== articlePreparationSequence ||
            !isCurrentPanelContext(panelContext)) return null;
        // Create the per-article directory as soon as the page is activated, but
        // only after restoration has had the first chance to read existing data.
        // The baseline action writes structure/paragraphs only; it cannot replace
        // a saved chat index, Figure result, highlight, or analysis with empties.
        await sendTabMessage(panelContext.tabId, {
            action: 'saveArticleWorkspaceBaseline'
        }).catch(() => null);
        if (requestId !== articlePreparationSequence ||
            !isCurrentPanelContext(panelContext)) return null;
        if (analysisMode === 'llm') {
            // Preparing the document is local indexing, not a model invocation.
            // Diagnostics alone never populate the state used by the Apply button.
            const isCurrent = () => requestId === articlePreparationSequence &&
                isCurrentPanelContext(panelContext);
            if (llmSettingsState?.effectiveMode === 'llm' &&
                !preparedDocumentState?.documentHash) {
                try {
                    await prepareArticleForAdaptiveAnalysis(panelContext.tabId, { isCurrent });
                } catch (error) {
                    if (isCurrent()) {
                        prepareState = 'idle';
                        updateApplyButton();
                        showStatus(`正文准备失败：${error?.message || '请重试'}`, 'error');
                    }
                }
            }
            if (!isCurrent()) return null;
            void Promise.allSettled([
                refreshLlmDiagnostics(),
                restoreFigureAnalysisProgress(),
                restoreReviewOutlineProgress()
            ]);
        }
        if (!restored) void probeCurrentArticleArchive({ pristineBaselineProof });
        return currentWorkspaceSnapshot || snapshot;
    } catch (error) {
        if (requestId !== articlePreparationSequence) return null;
        renderArticleConnectionFailure(error);
        showStatus(error?.code === 'ARTICLE_PAGE_LOADING'
            ? '页面正文尚未稳定，请等待加载完成后重新提取；页面稳定后侧栏也会自动刷新。'
            :
            `${error?.code === 'ARTICLE_PREPARATION_TIMEOUT' ? '正文提取超时' : '正文提取失败'}：` +
            '可重新提取，或导出适配诊断包用于修复',
            error?.code === 'ARTICLE_PAGE_LOADING' ? 'info' : 'error'
        );
        return null;
    } finally {
        if (requestId === articlePreparationSequence && retryButton && retryButton.hidden) {
            retryButton.disabled = false;
        }
    }
}

document.addEventListener('DOMContentLoaded', async () => {
    setupSidePanelNotificationCenter();
    setupSidePanelMoreTools();
    setupSidebarFocusMode();
    setupWorkspaceNavigation();
    setupSupplementalFigureImport();
    setupSidePanelSettingsShortcut();
    setupArticleArchiveControls();
    setupAdapterDiagnosticControls();
    setupActiveTabSynchronization();
    setupInactiveTabClickActivation();
    try {
        // 设置读取也受同一截止时间保护，避免侧栏永久停在“正在连接”。
        await withPreparationDeadline(
            Promise.all([loadSettings(), loadLlmSettings()]),
            15000
        );
        reconcileRegexSelection();

        // 渲染界面
        renderCategories();
        setupEventListeners();

        // 恢复模式选择
        document.querySelector(`input[name="highlightMode"][value="${highlightMode}"]`).checked = true;
        const analysisRadio = document.querySelector(`input[name="analysisMode"][value="${analysisMode}"]`);
        if (analysisRadio) analysisRadio.checked = true;
        updateAnalysisModeUi();
        panelUiReady = true;
        await synchronizeActiveTabContext();
    } catch (error) {
        renderArticleConnectionFailure(error);
        showStatus('侧栏初始化失败：可重新提取或导出适配诊断包', 'error');
    }
});

window.addEventListener('focus', () => {
    void refreshArticleWorkspaceDirectoryHandle();
});
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') {
        void figureWorkspaceEditorLifecycle.visibilityChanged(true);
    }
});
window.addEventListener('pagehide', () => {
    void figureWorkspaceEditorLifecycle.pagehide().catch(() => undefined);
    void publishSidePanelShortcutScope(activePanelTabContext.tabId, false);
});

// 加载设置
async function loadSettings() {
    const stored = await chrome.storage.local.get([
        'selectedCategories',
        'highlightMode'
    ]);

    if (Array.isArray(stored.selectedCategories)) {
        selectedCategories = new Set(stored.selectedCategories);
        regexSelectionStored = true;
    }
    if (stored.highlightMode) {
        highlightMode = stored.highlightMode;
    }
}

// 保存设置
async function saveSettings() {
    await chrome.storage.local.set({
        selectedCategories: Array.from(selectedCategories),
        highlightMode: highlightMode
    });
}

function getCategoryEntriesForEngine(
    engine = analysisMode, { includeUnsupported = false } = {}
) {
    return getAvailableCategoryEntries(
        llmSettingsState?.availableCategories,
        engine,
        { includeUnsupported }
    );
}

function reconcileRegexSelection() {
    const availableIds = getCategoryEntriesForEngine('regex').map(([categoryId]) => categoryId);
    const available = new Set(availableIds);
    const configured = [...getConfiguredViewSelection()]
        .filter(categoryId => available.has(categoryId));
    selectedCategories = configured.length
        ? new Set(configured)
        : regexSelectionStored
            ? new Set([...selectedCategories].filter(categoryId => available.has(categoryId)))
            : new Set(availableIds);
}

async function sendLlmMessage(message) {
    const response = await chrome.runtime.sendMessage(message);
    if (!response?.success) {
        const error = new Error(response?.error?.message || 'LLM 操作失败');
        error.code = response?.error?.code;
        error.diagnosticType = response?.error?.diagnosticType;
        error.diagnosticMessage = response?.error?.diagnosticMessage;
        throw error;
    }
    return response.data;
}

async function loadLlmSettings() {
    try {
        llmSettingsState = await sendLlmMessage({ type: 'LLM_GET_SETTINGS' });
        figurePanelHeaderFieldsState = normalizePopupFigurePanelHeaderFields(
            llmSettingsState.settings.figurePanelHeaderFields
        );
        renderFigurePanelHeaderFieldsControl();
        analysisMode = llmSettingsState.settings.mode;
        persistedAnalysisMode = analysisMode;
        readingViewId = llmSettingsState.settings.readingViewId || 'quick_story';
        persistedReadingViewId = readingViewId;
        llmSelectedCategories = getConfiguredViewSelection();
        confidenceThreshold = Number(llmSettingsState.settings.confidenceThreshold) || 0.8;
        persistedConfidenceThreshold = confidenceThreshold;
        const language = llmSettingsState.settings.language || 'zh-CN';
        SciLLM.setInterfaceLanguage?.(language);
    } catch (error) {
        analysisMode = 'regex';
        persistedAnalysisMode = 'regex';
        llmSettingsState = null;
        figurePanelHeaderFieldsState = { ...DEFAULT_FIGURE_PANEL_HEADER_FIELDS };
        renderFigurePanelHeaderFieldsControl();
    }
}

function literatureNoteWorkspaceTarget() {
    const workspace = currentWorkspaceSnapshot?.localWorkspace || {};
    const workspaceId = String(workspace.workspaceId || '').trim().toLowerCase();
    const workspaceGeneration = Number(workspace.workspaceGeneration);
    return /^workspace:[a-f0-9]{64}$/.test(workspaceId) &&
        Number.isSafeInteger(workspaceGeneration) && workspaceGeneration >= 1
        ? { workspaceId, workspaceGeneration } : null;
}

function literatureNoteDocumentKey() {
    const target = literatureNoteWorkspaceTarget();
    return String(
        target?.workspaceId || currentWorkspaceSnapshot?.url ||
        activePanelTabContext.url || activePanelTabContext.key ||
        preparedDocumentState?.documentHash || 'unbound-document'
    ).normalize('NFKC').trim().slice(0, 800);
}

function captureLiteratureNoteContext() {
    const target = literatureNoteWorkspaceTarget();
    const documentKey = literatureNoteDocumentKey();
    const workspaceId = target?.workspaceId || '';
    const workspaceGeneration = target?.workspaceGeneration || 0;
    return {
        id: `${documentKey}\u0000${workspaceId}\u0000${workspaceGeneration}`.slice(0, 1000),
        documentKey,
        workspaceId,
        workspaceGeneration,
        target: target ? { ...target } : null,
        legacyKey: String(preparedDocumentState?.documentHash || '').trim().slice(0, 128)
    };
}

function isCurrentLiteratureNoteContext(context) {
    if (!context || typeof context !== 'object') return false;
    const current = captureLiteratureNoteContext();
    return current.documentKey === context.documentKey &&
        current.workspaceId === context.workspaceId &&
        current.workspaceGeneration === context.workspaceGeneration;
}

function normalizeLiteratureNoteDocumentState(value) {
    const coreState = Number(value?.schemaVersion) >= 2 &&
        typeof SciLLM !== 'undefined'
        ? SciLLM.normalizeLiteratureNoteDocumentState?.(value) : null;
    if (coreState) return coreState;
    const source = value && typeof value === 'object' && !Array.isArray(value)
        ? value : {};
    const safeId = value => {
        const raw = String(value || '').normalize('NFKC').toLowerCase().trim().slice(0, 160);
        if (['__proto__', 'prototype', 'constructor'].includes(raw)) return '';
        const candidate = raw
            .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
        return /^[a-z][a-z0-9_]{0,79}$/.test(candidate) &&
            !['__proto__', 'prototype', 'constructor'].includes(candidate)
            ? candidate : '';
    };
    const valuesByTemplate = {};
    const rawTemplates = source.valuesByTemplate &&
        typeof source.valuesByTemplate === 'object' &&
        !Array.isArray(source.valuesByTemplate) ? source.valuesByTemplate : {};
    Object.entries(rawTemplates).slice(0, 20).forEach(([templateId, rawValues]) => {
        const normalizedTemplateId = safeId(templateId);
        if (!normalizedTemplateId || !rawValues || typeof rawValues !== 'object' ||
            Array.isArray(rawValues)) return;
        const values = {};
        Object.entries(rawValues).slice(0, 40).forEach(([fieldId, rawValue]) => {
            const normalizedFieldId = safeId(fieldId);
            if (!normalizedFieldId) return;
            const normalized = String(rawValue ?? '').normalize('NFC')
                .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
                .slice(0, 12000);
            if (normalized) values[normalizedFieldId] = normalized;
        });
        if (Object.keys(values).length) valuesByTemplate[normalizedTemplateId] = values;
    });
    const fieldStatusByTemplate = {};
    const rawStatusTemplates = Number(source.schemaVersion) === 2 &&
        source.fieldStatusByTemplate && typeof source.fieldStatusByTemplate === 'object' &&
        !Array.isArray(source.fieldStatusByTemplate)
        ? source.fieldStatusByTemplate : {};
    Object.entries(rawStatusTemplates).slice(0, 20).forEach(([templateId, rawStatuses]) => {
        const normalizedTemplateId = safeId(templateId);
        if (!normalizedTemplateId || !rawStatuses || typeof rawStatuses !== 'object' ||
            Array.isArray(rawStatuses)) return;
        const statuses = {};
        Object.entries(rawStatuses).slice(0, 40).forEach(([fieldId, rawStatus]) => {
            const normalizedFieldId = safeId(fieldId);
            const status = String(rawStatus || '');
            if (!normalizedFieldId || !['supported', 'missing'].includes(status)) return;
            const hasValue = Boolean(
                valuesByTemplate[normalizedTemplateId]?.[normalizedFieldId]
            );
            if ((status === 'missing' && hasValue) ||
                (status === 'supported' && !hasValue)) {
                return;
            }
            statuses[normalizedFieldId] = status;
        });
        if (Object.keys(statuses).length) {
            fieldStatusByTemplate[normalizedTemplateId] = statuses;
        }
    });
    const rawUpdatedAt = Number(source.updatedAt);
    const updatedAt = Number.isSafeInteger(rawUpdatedAt) && rawUpdatedAt >= 0
        ? rawUpdatedAt : 0;
    return {
        schemaVersion: 2,
        templateId: safeId(source.templateId),
        valuesByTemplate,
        fieldStatusByTemplate,
        updatedAt
    };
}

async function readLiteratureNoteWorkspaceState(targetOverride = undefined) {
    const target = targetOverride !== undefined
        ? targetOverride : literatureNoteWorkspaceTarget();
    if (!target) return null;
    const response = await chrome.runtime.sendMessage({
        type: 'ARTICLE_WORKSPACE_GET_ASSET',
        workspaceId: target.workspaceId,
        relativePath: LITERATURE_NOTE_WORKSPACE_PATH
    });
    if (!response?.success) {
        const error = new Error('LITERATURE_NOTE_WORKSPACE_READ_FAILED');
        error.code = response?.error?.code || 'LITERATURE_NOTE_WORKSPACE_READ_FAILED';
        throw error;
    }
    if (!response.data?.asset) {
        return { target, state: null, revision: 0 };
    }
    return {
        target,
        state: normalizeLiteratureNoteDocumentState(response.data.asset.content),
        revision: Math.max(0, Number(response.data.asset.revision) || 0)
    };
}

function mergeLiteratureNoteDocumentState(latest, current, dirtyFields) {
    const hasLatest = latest && typeof latest === 'object' && !Array.isArray(latest);
    const merged = normalizeLiteratureNoteDocumentState(hasLatest ? latest : current);
    const draft = normalizeLiteratureNoteDocumentState(current);
    merged.valuesByTemplate ||= {};
    merged.fieldStatusByTemplate ||= {};
    merged.fieldEvidenceByTemplate ||= {};
    merged.fieldUpdatedAtByTemplate ||= {};
    for (const dirtyKey of dirtyFields) {
        const separator = dirtyKey.indexOf('\u0000');
        if (separator <= 0) continue;
        const templateId = dirtyKey.slice(0, separator);
        const fieldId = dirtyKey.slice(separator + 1);
        merged.valuesByTemplate[templateId] ||= {};
        const draftValue = String(
            draft.valuesByTemplate?.[templateId]?.[fieldId] || ''
        ).slice(0, 12000);
        merged.fieldStatusByTemplate[templateId] ||= {};
        merged.fieldEvidenceByTemplate[templateId] ||= {};
        merged.fieldUpdatedAtByTemplate[templateId] ||= {};
        const draftStatus = draft.fieldStatusByTemplate?.[templateId]?.[fieldId];
        const draftFieldUpdatedAt =
            draft.fieldUpdatedAtByTemplate?.[templateId]?.[fieldId];
        const hasExplicitDraftRevision =
            Number.isSafeInteger(draftFieldUpdatedAt) && draftFieldUpdatedAt > 0;
        if (draftStatus === 'missing' && !hasExplicitDraftRevision &&
            merged.valuesByTemplate[templateId][fieldId]) {
            // Legacy v2 `missing` was not a durable deletion marker. Preserve a
            // value already committed by another client until the field has an
            // explicit v3 revision.
            delete merged.fieldStatusByTemplate[templateId][fieldId];
            delete merged.fieldEvidenceByTemplate[templateId][fieldId];
            continue;
        }
        if (draftStatus === 'missing' && hasExplicitDraftRevision) {
            delete merged.valuesByTemplate[templateId][fieldId];
            merged.fieldStatusByTemplate[templateId][fieldId] = 'missing';
        } else {
            merged.valuesByTemplate[templateId][fieldId] = draftValue;
        }
        if (draftStatus === 'supported') {
            merged.fieldStatusByTemplate[templateId][fieldId] = draftStatus;
        } else if (draftStatus !== 'missing') {
            delete merged.fieldStatusByTemplate[templateId][fieldId];
        }
        const draftEvidence = draft.fieldEvidenceByTemplate?.[templateId]?.[fieldId];
        if (draftEvidence) {
            merged.fieldEvidenceByTemplate[templateId][fieldId] = draftEvidence;
        } else {
            delete merged.fieldEvidenceByTemplate[templateId][fieldId];
        }
        if (hasExplicitDraftRevision) {
            merged.fieldUpdatedAtByTemplate[templateId][fieldId] = draftFieldUpdatedAt;
        }
    }
    for (const [templateId, statuses] of
        Object.entries(merged.fieldStatusByTemplate || {})) {
        for (const [fieldId, fieldStatus] of Object.entries(statuses || {})) {
            const hasValue = Boolean(merged.valuesByTemplate?.[templateId]?.[fieldId]);
            if ((fieldStatus === 'missing' && hasValue) ||
                (fieldStatus === 'supported' && !hasValue)) {
                delete merged.fieldStatusByTemplate[templateId][fieldId];
            }
        }
    }
    merged.templateId = draft.templateId || merged.templateId;
    // A merge/acknowledgement is not a new edit. Keep actual mutation clocks so
    // the visible saved state has the same revision after reopening.
    merged.updatedAt = Math.max(merged.updatedAt, draft.updatedAt);
    return merged;
}

function literatureNoteTemplates() {
    return SciLLM.normalizeLiteratureNoteTemplates?.(
        llmSettingsState?.settings?.literatureNoteTemplates
    ) || [];
}

async function loadLiteratureNoteDocumentState() {
    const loadContext = captureLiteratureNoteContext();
    const loadIntent = literatureNoteLoadGuard.begin(loadContext);
    const key = loadContext.documentKey;
    const stored = await chrome.storage.local.get(LITERATURE_NOTE_STORAGE_KEY);
    const entries = stored?.[LITERATURE_NOTE_STORAGE_KEY]?.entries || {};
    const legacyKey = String(preparedDocumentState?.documentHash || '').trim();
    const localState = normalizeLiteratureNoteDocumentState(
        entries[key] || (legacyKey && entries[legacyKey]) || null
    );
    let workspaceState = null;
    try {
        workspaceState = (await readLiteratureNoteWorkspaceState(loadContext.target))
            ?.state || null;
    } catch (_) {}
    let resolvedState = SciLLM.reconcileLiteratureNoteDocumentStates
        ? SciLLM.reconcileLiteratureNoteDocumentStates(workspaceState, localState)
        : mergeLiteratureNoteDocumentState(
            workspaceState, localState, new Set()
        );
    if (!literatureNoteLoadGuard.isCurrent(loadIntent)) {
        return literatureNoteDocumentState;
    }
    // CAS must use the confirmed local record, never reconciled workspace clocks.
    literatureNoteTemplateSelectionBase = {
        templateId: localState.templateId, updatedAt: localState.updatedAt
    };
    literatureNoteTemplateSelection = null;
    const retry = literatureNotePersistenceCoordinator.getRetrySnapshot(loadContext);
    literatureNoteTemplateSelectionConflict = retry?.templateSelectionConflict === true;
    if (retry) {
        const overlay = applyLiteratureNoteRetryOverlay({
            resolvedState,
            retry,
            merge: mergeLiteratureNoteDocumentState
        });
        resolvedState = overlay.state;
        literatureNoteTemplateSelection = overlay.templateSelection
            ? structuredClone(overlay.templateSelection) : null;
        literatureNoteTemplateSelectionRevision = Math.max(
            literatureNoteTemplateSelectionRevision,
            Number(literatureNoteTemplateSelection?.revision) || 0
        );
        overlay.dirtyRevisions.forEach((revision, fieldKey) => {
            literatureNoteDirtyFields.add(fieldKey);
            literatureNoteDirtyRevisions.set(fieldKey, revision);
            literatureNoteFieldEditVersions.set(fieldKey, revision);
            literatureNoteFieldRevision = Math.max(
                literatureNoteFieldRevision, Number(revision) || 0
            );
        });
    }
    literatureNoteDocumentState = resolvedState;
    if (retry) {
        if (!literatureNoteTemplateSelectionConflict) scheduleLiteratureNoteSave();
        const status = document.getElementById('literatureNoteStatus');
        if (status) status.textContent = literatureNoteTemplateSelectionConflict
            ? t('笔记模板保存冲突；草稿已保留，请重新选择模板后重试')
            : t('已恢复未保存的编辑，正在重试');
    }
    return literatureNoteDocumentState;
}

async function commitLiteratureNoteDocumentDelta({ delta, dirtyFields, context }) {
            const localResponse = await chrome.runtime.sendMessage({
                type: 'LITERATURE_NOTE_COMMIT_DELTA',
                documentKey: context.documentKey,
                legacyKey: context.legacyKey,
                delta: Object.freeze({
                    templateId: delta.templateId,
                    fields: Array.isArray(delta.fields) ? delta.fields : [],
                    ...(delta.templateSelection ? {
                        templateSelection: delta.templateSelection
                    } : {})
                })
            });
            const ackBase = localResponse?.data?.templateSelectionBase;
            const ackState = localResponse?.data?.state;
            const validControlledAck = !delta.templateSelection || (
                ackBase && typeof ackBase.templateId === 'string' &&
                Number.isSafeInteger(ackBase.updatedAt) && ackBase.updatedAt >= 0 &&
                ackState && Number.isSafeInteger(ackState.updatedAt) &&
                ackState.updatedAt >= ackBase.updatedAt &&
                (delta.templateSelection.mode !== 'set' || (
                    ackBase.templateId === delta.templateSelection.expectedTemplateId &&
                    ackBase.updatedAt === delta.templateSelection.expectedUpdatedAt &&
                    ackState.templateId === delta.templateId
                )));
            if (!localResponse?.success || !ackState || !validControlledAck) {
                const code = localResponse?.error?.code ||
                    'LITERATURE_NOTE_STORAGE_FAILED';
                const messages = {
                    LITERATURE_NOTE_SENDER_INVALID: '文献笔记保存请求无效',
                    LITERATURE_NOTE_DELTA_INVALID: '文献笔记内容无效或过大',
                    LITERATURE_NOTE_TEMPLATE_CONFLICT:
                        '笔记模板保存冲突；草稿已保留，请重新选择模板后重试',
                    LITERATURE_NOTE_DOCUMENT_TOO_LARGE:
                        '当前文献笔记已达到容量上限，请精简后重试',
                    LITERATURE_NOTE_STORAGE_TOO_LARGE:
                        '文献笔记本地存储已达到容量上限，请清理后重试',
                    LITERATURE_NOTE_STORAGE_FAILED: '文献笔记本地保存失败'
                };
                const error = new Error(t(
                    messages[code] || '文献笔记本地保存失败'
                ));
                error.code = code;
                error.literatureNoteRemainingDelta = Object.freeze({
                    templateId: delta.templateId,
                    fields: Array.isArray(delta.fields) ? delta.fields : [],
                    ...(delta.templateSelection ? {
                        templateSelection: delta.templateSelection
                    } : {})
                });
                throw error;
            }
            const committedState = normalizeLiteratureNoteDocumentState(
                localResponse.data.state
            );
            const workspaceResult = await persistLiteratureNoteWorkspacePending({
                target: context.target,
                committedState,
                workspacePendingFieldKeys: dirtyFields,
                readWorkspace: readLiteratureNoteWorkspaceState,
                saveWorkspace: ({ workspace, state }) => chrome.runtime.sendMessage({
                    type: 'ARTICLE_WORKSPACE_SAVE_ASSET',
                    workspaceId: workspace.target.workspaceId,
                    workspaceGeneration: workspace.target.workspaceGeneration,
                    relativePath: LITERATURE_NOTE_WORKSPACE_PATH,
                    content: state,
                    expectedRevision: workspace.revision
                }),
                merge: mergeLiteratureNoteDocumentState
            });
            return {
                ...workspaceResult,
                localState: committedState,
                templateSelectionBase: localResponse.data.templateSelectionBase,
                localPendingDelta: Object.freeze({
                    templateId: delta.templateId,
                    fields: [],
                    ...(delta.templateSelection ? {
                        templateSelection: { mode: 'preserve' }
                    } : {})
                }),
            };
}

function reserveLiteratureNoteDocumentStatePersistence(
    saveContext = captureLiteratureNoteContext()
) {
    if (!literatureNoteDocumentState ||
        (!literatureNoteDirtyRevisions.size && !literatureNoteTemplateSelection)) {
        return {
            accepted: true,
            context: saveContext,
            promise: Promise.resolve({ skipped: true, stale: false })
        };
    }
    const mutationIntent = literatureNoteLoadGuard.beginMutation(saveContext);
    let reservation;
    try {
        reservation = literatureNotePersistenceCoordinator.trySave(
            commitLiteratureNoteDocumentDelta,
            saveContext
        );
    } catch (error) {
        literatureNoteLoadGuard.endMutation(mutationIntent);
        throw error;
    }
    if (!reservation.accepted) {
        literatureNoteLoadGuard.endMutation(mutationIntent);
        return reservation;
    }
    reservation.promise.then(
        () => literatureNoteLoadGuard.endMutation(mutationIntent),
        () => literatureNoteLoadGuard.endMutation(mutationIntent)
    );
    return reservation;
}

async function persistLiteratureNoteDocumentState(
    saveContext = captureLiteratureNoteContext()
) {
    const reservation = reserveLiteratureNoteDocumentStatePersistence(saveContext);
    if (!reservation.accepted) throw reservation.error;
    saveContext = reservation.context;
    let committed;
    try {
        committed = await reservation.promise;
    } catch (error) {
        if (error.code === 'LITERATURE_NOTE_TEMPLATE_CONFLICT' &&
            isCurrentLiteratureNoteContext(saveContext)) {
            literatureNoteTemplateSelectionConflict = true;
        }
        throw error;
    }
    if (committed.stale || !isCurrentLiteratureNoteContext(saveContext)) {
        return { ...committed, stale: true };
    }
    const status = document.getElementById('literatureNoteStatus');
    if (status) status.textContent = t(
        committed.workspaceTargetFound && !committed.workspaceSaved
            ? '已保存在浏览器，等待同步到本地文件夹'
            : literatureNoteTemplateSelection || literatureNoteDirtyRevisions.size
                ? '正在保存…' : '已自动保存到本机'
    );
    return committed;
}

async function handleLiteratureNoteTemplateChange(event) {
    const selectedTemplateId = String(event.currentTarget.value || '');
    const selectionContext = captureLiteratureNoteContext();
    const selectionSequence = ++literatureNoteTemplateChangeSequence;
    const isCurrentSelection = () =>
        selectionSequence === literatureNoteTemplateChangeSequence &&
        isCurrentLiteratureNoteContext(selectionContext);
    try {
        if (!literatureNoteDocumentState) await loadLiteratureNoteDocumentState();
        if (!isCurrentSelection() || !literatureNoteDocumentState) return;
        // Only a fresh, explicit user selection may resolve an external conflict.
        // Keep all field drafts; do not blindly rebase the failed intent on retry.
        if (literatureNoteTemplateSelectionConflict) {
            const stored = await chrome.storage.local.get(LITERATURE_NOTE_STORAGE_KEY);
            if (!isCurrentSelection()) return;
            const entries = stored?.[LITERATURE_NOTE_STORAGE_KEY]?.entries || {};
            const localState = normalizeLiteratureNoteDocumentState(
                entries[selectionContext.documentKey] ||
                (selectionContext.legacyKey && entries[selectionContext.legacyKey])
            );
            literatureNoteTemplateSelectionBase = {
                templateId: localState.templateId, updatedAt: localState.updatedAt
            };
            literatureNoteTemplateSelectionConflict = false;
        }
        if (literatureNoteDocumentState.templateId !== selectedTemplateId ||
            literatureNoteTemplateSelection ||
            literatureNoteTemplateSelectionBase.templateId !== selectedTemplateId) {
            literatureNoteLoadGuard.invalidate();
            literatureNoteTemplateSelection = {
                mode: 'set', templateId: selectedTemplateId,
                expectedTemplateId: literatureNoteTemplateSelectionBase.templateId,
                expectedUpdatedAt: literatureNoteTemplateSelectionBase.updatedAt,
                revision: ++literatureNoteTemplateSelectionRevision
            };
            literatureNoteDocumentState.templateId = selectedTemplateId;
        }
        renderLiteratureNoteDrawer();
        clearTimeout(literatureNoteSaveTimer);
        literatureNoteSaveTimer = null;
        const status = document.getElementById('literatureNoteStatus');
        if (status) status.textContent = t('正在保存…');
        // Reserve synchronously before preferences/await. This bounds context
        // switches, but does not promise completion after the browser is killed.
        const persistence = persistLiteratureNoteDocumentState(selectionContext);
        void sendLlmMessage({
            type: 'LLM_UPDATE_PREFERENCES',
            preferences: { lastLiteratureNoteTemplateId: selectedTemplateId }
        }).then(state => {
            if (isCurrentSelection()) llmSettingsState = state;
        }).catch(error => {
            if (isCurrentSelection()) {
                showStatus(`笔记模板选择保存失败：${error.message}`, 'error');
            }
        });
        await persistence;
    } catch (error) {
        if (!isCurrentSelection()) return;
        const status = document.getElementById('literatureNoteStatus');
        if (status) status.textContent = `${t('保存失败')}：${t(error.message)}`;
    }
}

function scheduleLiteratureNoteSave() {
    clearTimeout(literatureNoteSaveTimer);
    const status = document.getElementById('literatureNoteStatus');
    if (status) status.textContent = t('正在保存…');
    const scheduledContext = captureLiteratureNoteContext();
    literatureNoteSaveTimer = setTimeout(() => {
        literatureNoteSaveTimer = null;
        void persistLiteratureNoteDocumentState(scheduledContext).catch(error => {
            if (status && isCurrentLiteratureNoteContext(scheduledContext)) {
                status.textContent = `${t('保存失败')}：${t(error.message)}`;
            }
        });
    }, 240);
}

function formatLlmFailureMessage(feature, error = {}) {
    const label = String(feature || 'AI 功能').normalize('NFKC')
        .replace(/\s+/g, ' ').trim().slice(0, 32) || 'AI 功能';
    const code = String(error?.code || '').trim().toUpperCase();
    const guidance = {
        REQUEST_TIMEOUT: '请求超时；模型服务可能繁忙，请稍后重试。',
        NETWORK_ERROR: '无法连接模型服务；请检查网络后重试。',
        AUTH_INVALID: 'API 凭据无效；请在模型设置中更新密钥。',
        QUOTA_EXHAUSTED: 'API 额度不足；请检查账户额度。',
        RATE_LIMITED: '请求过于频繁；请稍后重试。',
        INVALID_RESPONSE: '模型返回格式不完整；系统已停止写入，请重试。',
        MECHANISM_GRAPH_EMPTY: '模型未生成可验证的机制关系；系统未保存空图，请重试。',
        MECHANISM_OPERATION_DEADLINE_EXCEEDED: '达到本轮运行时限；本轮已停止，请核对图解进度后重试。',
        MECHANISM_PROVIDER_REQUEST_BUDGET_EXCEEDED: '达到本轮模型调用次数上限；本轮已停止，请核对图解进度后重试。',
        MECHANISM_RUN_STATE_READ_FAILED: '未能读取任务运行状态；请重新打开侧栏后重试。',
        MECHANISM_RUN_STATE_WRITE_FAILED: '保存任务运行状态未获确认；请重新打开侧栏后核对进度。',
        MECHANISM_CHECKPOINT_READ_FAILED: '未能读取阶段检查点；请重新打开侧栏后重试。',
        MECHANISM_CHECKPOINT_WRITE_FAILED: '保存阶段检查点未获确认；请重新打开侧栏后核对进度。',
        MECHANISM_WORKSPACE_SYNC_FAILED: '所需的工作区同步尚未完成；请重新打开侧栏后重试。',
        MECHANISM_REVISION_CONFLICT: '工作区已发生变化；请返回解图页刷新后重试。已有结果会保留。',
        FIGURE_WORKSPACE_LIFECYCLE_SYNC_FAILED: '工作区同步尚未完成；请重试，已有结果会保留。',
        FIGURE_OPERATION_RELEASE_UNCONFIRMED: '上次解图任务尚未确认结束；请稍后重试。',
        OUTPUT_TRUNCATED: '模型输出被截断；请稍后重试或缩小任务范围。',
        CANCELLED: '已取消。'
    };
    const fallback = label === '机制链生成'
        ? '未完成；请稍后重试。若再次失败，请保留通知并反馈。'
        : '失败；请检查模型设置或稍后重试。';
    return `${label}${guidance[code] || fallback}`;
}

function currentLiteratureNotePaperMetaProjection() {
    return createLiteratureNotePaperMetaProjection(
        mechanismWorkspaceDraft(currentWorkspaceSnapshot) || {}
    );
}

function resizeLiteratureNoteTextarea(textarea) {
    if (!textarea?.style) return 0;
    textarea.style.height = 'auto';
    textarea.style.overflowY = 'hidden';
    const height = Math.ceil(Number(textarea.scrollHeight) || 0) + 2;
    textarea.style.height = `${height}px`;
    return height;
}

function resizeLiteratureNoteTextareas(
    fields = document.getElementById('literatureNoteFields')
) {
    if (!fields) return 0;
    const textareas = [...fields.querySelectorAll('[data-literature-note-field]')];
    textareas.forEach(resizeLiteratureNoteTextarea);
    return textareas.length;
}

function syncLiteratureNoteTextarea(textarea) {
    literatureNoteSourceEditors.get(textarea)?.refresh(textarea.value);
    literatureNoteEditors.get(textarea)?.refresh();
    return resizeLiteratureNoteTextarea(textarea);
}

function renderLiteratureNoteViewToggle() {
    const button = document.getElementById('toggleLiteratureNoteMarkdown');
    if (!button) return;
    const label = t(literatureNotePreviewing ? '查看 Markdown 源码' : '查看渲染后的笔记');
    button.setAttribute('aria-label', label);
    button.setAttribute('title', label);
    button.setAttribute('aria-pressed', String(literatureNotePreviewing));
    button.querySelector('path')?.setAttribute('d', literatureNotePreviewing
        ? 'M8 5l-6 7 6 7M16 5l6 7-6 7M14 3l-4 18'
        : 'M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0');
}

function setLiteratureNotePreview(previewing, { userInitiated = false } = {}) {
    const textareas = [...document.querySelectorAll('#literatureNoteFields [data-literature-note-field]')];
    const editors = textareas.map(textarea => literatureNoteEditors.get(textarea)).filter(Boolean);
    // Preflight every field: an IME composition must not leave a mixed-mode note.
    if (editors.some(editor => !editor.canSetPreview())) {
        if (userInitiated) showStatus(t('正在组合输入，请完成输入后再切换预览。'), 'warning');
        return false;
    }
    literatureNotePreviewing = Boolean(previewing);
    if (userInitiated) literatureNoteViewRevision += 1;
    editors.forEach(editor => editor.setPreview(literatureNotePreviewing));
    if (!literatureNotePreviewing) textareas.forEach(resizeLiteratureNoteTextarea);
    renderLiteratureNoteViewToggle();
    return true;
}

function renderLiteratureNoteSourceList(textarea, projection) {
    const list = textarea.closest('.literature-note-field')
        ?.querySelector('.literature-note-source-list');
    if (!list) return;
    list.replaceChildren();
    const ids = new Map();
    (projection?.ok ? projection.references : []).forEach(reference => reference.sourceIds.forEach((id, index) => {
        if (!ids.has(id)) ids.set(id, reference.sourceNumbers[index]);
    }));
    const noteContext = captureLiteratureNoteContext();
    const findTarget = id => {
        if (!isCurrentLiteratureNoteContext(noteContext)) return null;
        const candidates = [...(currentWorkspaceSnapshot?.paragraphs || []),
            ...(currentWorkspaceSnapshot?.literatureNoteCaptionSources || [])]
            .filter(paragraph => paragraph.paragraphId === id);
        if (candidates.length !== 1 || !candidates[0].sourceKey) return null;
        return candidates[0];
    };
    ids.forEach((number, id) => {
        const paragraph = findTarget(id);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'literature-note-html-source';
        button.disabled = !paragraph;
        button.textContent = `来源 ${number} · ` + (paragraph
            ? `${String(paragraph.sectionTitle || '正文').slice(0, 120)}（引文待核验）`
            : '位置待核验');
        button.addEventListener('click', async () => {
            const current = findTarget(id);
            if (!current) {
                button.disabled = true;
                showStatus('来源已变化，请重新核对当前论文。', 'warning');
                return;
            }
            button.disabled = true;
            const panelContext = capturePanelContext();
            try {
                const result = await focusWorkspaceSourceDetailed({
                    kind: current.recordType === 'figure-caption' ? 'literature-note-caption' : 'paragraph',
                    paragraphId: id, sourceKey: current.sourceKey,
                    ...(current.recordType === 'figure-caption' ? {
                        documentHash: currentWorkspaceSnapshot?.documentHash, textHash: current.textHash
                    } : {}),
                    navigationRevision: current.navigationRevision || currentWorkspaceSnapshot?.revision
                }, panelContext);
                if (!isCurrentLiteratureNoteContext(noteContext) || !isCurrentPanelContext(panelContext)) return;
                showStatus(result?.success && result?.focused
                    ? '已定位来源，请核对它是否支持当前笔记。' : '无法精确定位该来源，请重新核对。',
                result?.success && result?.focused ? 'success' : 'warning');
            } catch (_) {
                if (isCurrentLiteratureNoteContext(noteContext)) showStatus('来源定位失败，笔记内容已保留。', 'error');
            } finally {
                if (button.isConnected) button.disabled = !findTarget(id);
            }
        });
        list.appendChild(button);
    });
    const evidence = literatureNoteDocumentState?.fieldEvidenceByTemplate
        ?.[literatureNoteDocumentState?.templateId]?.[textarea.dataset.literatureNoteField];
    const normalized = typeof SciLLM !== 'undefined'
        ? SciLLM.normalizeLiteratureNoteEvidenceRecord?.(evidence) : null;
    if (normalized?.status === 'verified') {
        normalized.locators.slice(1).forEach((_locator, index) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.dataset.literatureNoteEvidenceField = textarea.dataset.literatureNoteField;
            button.dataset.literatureNoteEvidenceIndex = String(index + 1);
            applyLiteratureNoteEvidenceElementState(button, normalized);
            list.appendChild(button);
        });
    }
    if (!ids.size && !evidence && projection?.canonicalText.trim()) {
        const label = document.createElement('small');
        label.textContent = '未附可定位来源';
        list.appendChild(label);
    }
}

function currentLiteratureNoteExport(format) {
    const templateId = literatureNoteDocumentState?.templateId;
    const template = literatureNoteTemplates().find(item => item.id === templateId);
    const result = SciLLM.createLiteratureNoteExport({
        template, values: literatureNoteDocumentState?.valuesByTemplate?.[templateId] || {},
        fieldEvidence: literatureNoteDocumentState?.fieldEvidenceByTemplate?.[templateId] || {}, format
    });
    if (!result.ok) throw new Error(result.error);
    return result.text;
}

async function copyLiteratureNote() {
    const noteContext = captureLiteratureNoteContext();
    const text = currentLiteratureNoteExport('text');
    await navigator.clipboard.writeText(text);
    if (isCurrentLiteratureNoteContext(noteContext)) showStatus('已复制当前模板笔记，来源状态一并保留。', 'success');
}

function exportLiteratureNoteMarkdown() {
    const text = currentLiteratureNoteExport('markdown');
    downloadBlob(new Blob([text], { type: 'text/markdown;charset=utf-8' }), 'BREVESS-文献笔记.md');
    showStatus('已生成 Markdown 文件；颜色使用笔记的受控标记。', 'success');
}

function ensureLiteratureNoteResizeObserver() {
    if (literatureNoteResizeObserver || typeof ResizeObserver !== 'function') return;
    const drawer = document.getElementById('literatureNoteDrawer');
    if (!drawer) return;
    literatureNoteResizeObserver = new ResizeObserver(() => {
        resizeLiteratureNoteTextareas();
    });
    literatureNoteResizeObserver.observe(drawer);
}

function applyCurrentPaperMetaToLiteratureNote(
    initialFieldRevisions = new Map(literatureNoteFieldEditVersions)
) {
    if (!literatureNoteDocumentState) {
        return { projection: currentLiteratureNotePaperMetaProjection(), changedFields: [] };
    }
    const projection = currentLiteratureNotePaperMetaProjection();
    const result = applyLiteratureNotePaperMetaProjection({
        templates: literatureNoteTemplates(),
        state: literatureNoteDocumentState,
        projection,
        initialFieldRevisions,
        currentFieldRevisions: literatureNoteFieldEditVersions
    });
    result.changedFields.forEach(({ templateId, fieldId }) => {
        markLiteratureNoteFieldDirty(`${templateId}\u0000${fieldId}`);
    });
    const activeTemplateId = String(literatureNoteDocumentState.templateId || '');
    const activeChangedFields = result.changedFields
        .filter(item => item.templateId === activeTemplateId)
        .map(item => item.fieldId);
    updateLiteratureNoteRenderedFields({
        fields: document.getElementById('literatureNoteFields'),
        templateId: activeTemplateId,
        state: literatureNoteDocumentState,
        changedFields: activeChangedFields,
        translate: t,
        resize: syncLiteratureNoteTextarea
    });
    return { projection, changedFields: result.changedFields };
}

function renderLiteratureNoteDrawer() {
    renderLiteratureNoteModelStatus();
    const templates = literatureNoteTemplates();
    const select = document.getElementById('literatureNoteTemplateSelect');
    const fields = document.getElementById('literatureNoteFields');
    if (!select || !fields || !templates.length) return;
    const preferredId = literatureNoteDocumentState?.templateId ||
        llmSettingsState?.settings?.lastLiteratureNoteTemplateId;
    const template = templates.find(item => item.id === preferredId) || templates[0];
    literatureNoteDocumentState ||= {
        schemaVersion: 3,
        templateId: '',
        valuesByTemplate: {},
        fieldStatusByTemplate: {},
        fieldEvidenceByTemplate: {},
        fieldUpdatedAtByTemplate: {},
        updatedAt: 0
    };
    literatureNoteDocumentState.templateId = template.id;
    literatureNoteDocumentState.valuesByTemplate ||= {};
    const values = literatureNoteDocumentState.valuesByTemplate[template.id] || {};
    const statuses = literatureNoteDocumentState.fieldStatusByTemplate?.[template.id] || {};
    const evidenceByField =
        literatureNoteDocumentState.fieldEvidenceByTemplate?.[template.id] || {};
    select.replaceChildren();
    templates.forEach(item => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = item.name;
        select.appendChild(option);
    });
    select.value = template.id;
    fields.querySelectorAll('[data-literature-note-field]').forEach(textarea => {
        literatureNoteEditors.get(textarea)?.destroy();
        literatureNoteEditors.delete(textarea);
        literatureNoteSourceEditors.get(textarea)?.destroy();
        literatureNoteSourceEditors.delete(textarea);
    });
    fields.replaceChildren();
    template.fields.forEach(field => {
        const label = document.createElement('div');
        label.className = 'literature-note-field';
        label.style.gridTemplateColumns = 'minmax(0, 1fr) auto';
        const title = document.createElement('span');
        title.textContent = field.label;
        const generateButton = document.createElement('button');
        generateButton.type = 'button';
        generateButton.className = 'inline-settings-button';
        generateButton.dataset.generateLiteratureNoteField = field.id;
        generateButton.textContent = values[field.id] ? 'AI 重新生成' : 'AI 生成';
        generateButton.setAttribute('aria-label', `${field.label} · ${values[field.id] ? 'AI 重新生成' : 'AI 生成'}`);
        const textarea = document.createElement('textarea');
        textarea.dataset.literatureNoteField = field.id;
        textarea.setAttribute('aria-label', field.label);
        textarea.maxLength = 12000;
        textarea.placeholder = field.placeholder || `记录${field.label}…`;
        textarea.value = String(values[field.id] || '');
        textarea.style.gridColumn = '1 / -1';
        const fieldStatus = statuses[field.id];
        const statusText = document.createElement('small');
        statusText.style.gridColumn = '1 / -1';
        statusText.className =
            `literature-note-field-status is-${fieldStatus || 'idle'}`;
        statusText.textContent = fieldStatus === 'missing' ? t('正文未提供') :
            fieldStatus === 'supported' ? t('已由正文证据填写') : '';
        statusText.setAttribute('aria-live', 'polite');
        label.append(title, textarea, statusText);
        const sourceButton = document.createElement('button');
        sourceButton.type = 'button';
        sourceButton.dataset.literatureNoteEvidenceField = field.id;
        sourceButton.dataset.literatureNoteEvidenceIndex = '0';
        sourceButton.style.gridColumn = '1 / -1';
        applyLiteratureNoteEvidenceElementState(
            sourceButton, evidenceByField[field.id]
        );
        label.append(sourceButton);
        label.insertBefore(generateButton, textarea);
        const sourceNotice = document.createElement('small');
        sourceNotice.className = 'literature-note-source-notice';
        sourceNotice.setAttribute('role', 'status');
        const sourceList = document.createElement('div');
        sourceList.className = 'literature-note-source-list';
        label.append(sourceNotice, sourceList);
        if (typeof SciLLM.attachLiteratureNoteSourceEditor === 'function') {
            const sourceEditor = SciLLM.attachLiteratureNoteSourceEditor({
                textarea,
                onError: message => { sourceNotice.textContent = message; },
                onChange: projection => renderLiteratureNoteSourceList(textarea, projection)
            });
            literatureNoteSourceEditors.set(textarea, sourceEditor);
        }
        if (typeof SciLLM.attachLiteratureNoteEditor === 'function') {
            const editor = SciLLM.attachLiteratureNoteEditor({ textarea, translate: t,
                initialPreview: literatureNotePreviewing, showToggle: false });
            editor.element.style.gridColumn = '1 / -1';
            label.insertBefore(editor.element, textarea);
            literatureNoteEditors.set(textarea, editor);
        }
        fields.appendChild(label);
        resizeLiteratureNoteTextarea(textarea);
    });
    renderLiteratureNoteViewToggle();
}

async function focusLiteratureNoteEvidenceSource(templateId, fieldId, button = null, locatorIndex = 0) {
    const evidence = literatureNoteDocumentState
        ?.fieldEvidenceByTemplate?.[templateId]?.[fieldId];
    const target = createLiteratureNoteEvidenceFocusTarget(evidence, locatorIndex);
    if (!target) return false;
    const panelContext = capturePanelContext();
    if (button) {
        button.disabled = true;
        button.setAttribute('aria-busy', 'true');
    }
    try {
        const response = await focusWorkspaceSourceDetailed(target, panelContext);
        if (!isCurrentPanelContext(panelContext)) return false;
        const feedback = describePdfSemanticFocusResult(response);
        showStatus(feedback.message, response?.success && response?.focused
            ? 'success' : 'error');
        return Boolean(response?.success && response?.focused);
    } finally {
        if (button?.isConnected) {
            const currentEvidence = literatureNoteDocumentState
                ?.fieldEvidenceByTemplate?.[templateId]?.[fieldId];
            applyLiteratureNoteEvidenceElementState(button, currentEvidence);
            button.removeAttribute('aria-busy');
        }
    }
}

function literatureNoteOperationLabel(phase, targetCount, perField = false) {
    const total = Math.max(0, Number(targetCount) || 0);
    const suffix = perField || !total ? '' : ` · 目标 ${total} 项`;
    const label = {
        provider_request_started: '已发送，等待模型',
        provider_waiting: '模型正在读取正文',
        literature_note_requesting: '正在发送正文证据',
        literature_note_compact_retry: '正在压缩正文证据后重试',
        literature_note_schema_retry: '正在修复返回格式',
        literature_note_fail_closed: '正在核验字段证据',
        literature_note_complete: '已收到结果，正在核验'
    }[String(phase || '')] || '正在分析正文证据';
    return perField ? `AI ${label}` : `${label}${suffix}`;
}

function updateLiteratureNoteOperationProgress(progress = {}) {
    if (!literatureNoteAutofillPromise) return;
    const button = document.getElementById('autofillLiteratureNote');
    const buttonLabel = button?.querySelector('span');
    const targetCount = Math.max(0, Number(button?.dataset.aiTargetCount) || 0);
    const targetFieldId = String(button?.dataset.aiTargetField || '');
    if (buttonLabel) {
        buttonLabel.textContent = literatureNoteOperationLabel(
            progress.phase, targetCount, false
        );
    }
    if (targetFieldId) {
        const target = [...document.querySelectorAll(
            '[data-generate-literature-note-field]'
        )].find(item => item.dataset.generateLiteratureNoteField === targetFieldId);
        if (target) {
            target.textContent = literatureNoteOperationLabel(progress.phase, 1, true);
        }
    }
}

async function autofillLiteratureNoteWithLLM({ fieldId = '' } = {}) {
    if (literatureNoteAutofillPromise) return literatureNoteAutofillPromise;
    if (!requireUsableLlm('文献笔记自动填写')) return null;
    if (!literatureNoteDocumentState) await loadLiteratureNoteDocumentState();
    const templates = literatureNoteTemplates();
    const templateId = String(
        literatureNoteDocumentState?.templateId ||
        document.getElementById('literatureNoteTemplateSelect')?.value || ''
    );
    const template = templates.find(item => item.id === templateId) || templates[0];
    if (!template?.fields?.length) throw new Error('当前笔记模板没有可填写字段');
    const requestedFieldId = String(fieldId || '');
    const targetField = requestedFieldId
        ? template.fields.find(field => field.id === requestedFieldId) : null;
    if (requestedFieldId && !targetField) throw new Error('当前笔记字段不存在');
    const requestTemplate = targetField
        ? { ...template, fields: [targetField] } : template;
    const noteContext = captureLiteratureNoteContext();
    const documentKey = noteContext.documentKey;
    const expectedDocumentHash = String(
        currentWorkspaceSnapshot?.documentHash ||
        preparedDocumentState?.documentHash ||
        manualAnnotationState?.documentHash || ''
    ).trim();
    const initialValues = structuredClone(
        literatureNoteDocumentState.valuesByTemplate?.[template.id] || {}
    );
    const initialFieldRevisions = new Map(literatureNoteFieldEditVersions);
    const initialViewRevision = literatureNoteViewRevision;
    const button = document.getElementById('autofillLiteratureNote');
    const buttonLabel = button?.querySelector('span');
    const fieldButtons = [...document.querySelectorAll(
        '[data-generate-literature-note-field]'
    )];
    const targetButton = fieldButtons.find(item =>
        item.dataset.generateLiteratureNoteField === requestedFieldId);
    const status = document.getElementById('literatureNoteStatus');
    const feedbackSequence = ++literatureNoteButtonFeedbackSequence;
    let terminalProgress = null;
    let savingResult = false;
    const promise = (async () => {
        if (button) {
            button.disabled = true;
            button.classList.add('is-running');
            button.setAttribute('aria-busy', 'true');
            button.dataset.aiTargetCount = String(requestTemplate.fields.length);
            button.dataset.aiTargetField = requestedFieldId;
        }
        fieldButtons.forEach(item => { item.disabled = true; });
        if (targetButton) {
            targetButton.classList.add('is-running');
            targetButton.setAttribute('aria-busy', 'true');
            targetButton.textContent = literatureNoteOperationLabel('', 1, true);
        }
        if (buttonLabel) {
            buttonLabel.textContent = literatureNoteOperationLabel(
                '', requestTemplate.fields.length, false
            );
        }
        if (status) status.textContent = targetField
            ? `正在生成“${targetField.label}”…` : '正在分析正文证据…';
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        const panelContext = capturePanelContext();
        const response = await sendTabMessage(tab.id, {
            action: 'autofillLiteratureNoteWithLLM',
            template: requestTemplate,
            forceRefresh: Boolean(targetField)
        });
        if (!isCurrentPanelContext(panelContext) ||
            literatureNoteDocumentKey() !== documentKey ||
            !isCurrentLiteratureNoteContext(noteContext) ||
            literatureNoteDocumentState?.templateId !== template.id) {
            return {
                filledCount: 0, missingCount: 0,
                preservedCount: 0, invalidCount: 0,
                cacheHit: false, stale: true
            };
        }
        if (!response?.success) {
            const error = new Error(response?.error || '文献笔记自动填写失败');
            error.code = response?.code;
            throw error;
        }
        const result = response.result || {};
        if (result.templateId !== template.id) {
            throw new Error('返回的笔记模板与当前模板不一致');
        }
        if (expectedDocumentHash &&
            String(result.documentHash || '').trim() !== expectedDocumentHash) {
            const error = new Error('论文正文身份已变化，已丢弃不属于当前文献的笔记结果');
            error.code = 'LITERATURE_NOTE_DOCUMENT_CHANGED';
            throw error;
        }
        if (!validateLiteratureNoteGenerationReceipt({
            result,
            template: requestTemplate,
            stableHash: SciLLM.stableHash
        })) {
            const error = new Error('笔记字段指令已变化，已丢弃过期的生成结果');
            error.code = 'LITERATURE_NOTE_TEMPLATE_CHANGED';
            throw error;
        }
        const targetDirtyKey = targetField ? `${template.id}\u0000${targetField.id}` : '';
        const targetEditedInFlight = targetField && (
            String(literatureNoteDocumentState.valuesByTemplate?.[template.id]?.[targetField.id] || '') !==
                String(initialValues[targetField.id] || '') ||
            Number(literatureNoteFieldEditVersions.get(targetDirtyKey) || 0) !==
                Number(initialFieldRevisions.get(targetDirtyKey) || 0)
        );
        const { counts, changedFields, sourceWarnings } = applyLiteratureNoteAutofillResult({
            template: requestTemplate,
            state: literatureNoteDocumentState,
            initialValues,
            initialFieldRevisions,
            currentFieldRevisions: literatureNoteFieldEditVersions,
            ...(targetField ? { replaceFieldIds: [targetField.id] } : {}),
            result
        });
        changedFields.forEach(fieldId => {
            markLiteratureNoteFieldDirty(`${template.id}\u0000${fieldId}`);
        });
        if (literatureNoteDocumentState.templateId === template.id) {
            updateLiteratureNoteRenderedFields({
                fields: document.getElementById('literatureNoteFields'),
                templateId: template.id,
                state: literatureNoteDocumentState,
                changedFields,
                translate: t,
                resize: syncLiteratureNoteTextarea
            });
            // Show new AI content rendered, but never interrupt source editing or
            // override a view choice made while the request was in flight.
            if (changedFields.length && initialViewRevision === literatureNoteViewRevision &&
                !document.activeElement?.closest('#literatureNoteFields textarea, #literatureNoteFields .literature-note-editor-toolbar')) {
                setLiteratureNotePreview(true);
            }
        }
        const summary = createLiteratureNoteAutofillSummary(counts, result.cacheHit === true,
            targetField ? {
                fieldLabel: targetField.label,
                unchanged: counts.filled > 0 &&
                    String(initialValues[targetField.id] || '') ===
                    String(literatureNoteDocumentState.valuesByTemplate?.[template.id]?.[targetField.id] || ''),
                preservedReason: targetEditedInFlight ? 'edited'
                    : result.fieldStatus?.[targetField.id] === 'missing' ? 'missing' : ''
            } : {});
        const obtainedLabel = `已取得 ${counts.filled}/${requestTemplate.fields.length}` +
            (counts.missing ? ` · 缺失 ${counts.missing}` : '') + '，正在保存';
        if (buttonLabel) buttonLabel.textContent = obtainedLabel;
        if (targetButton) targetButton.textContent = counts.filled
            ? 'AI 已取得，正在保存' : `${summary.buttonLabel}，正在核对保存状态`;
        savingResult = true;
        const persisted = await persistLiteratureNoteDocumentState();
        savingResult = false;
        if (persisted?.stale || !isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext)) {
            return {
                filledCount: counts.filled,
                missingCount: counts.missing,
                preservedCount: counts.preserved,
                invalidCount: counts.invalid,
                cacheHit: result.cacheHit === true,
                stale: true
            };
        }

        const localizedSummary = t(summary.message) + (sourceWarnings.length
            ? `；${sourceWarnings.length} 个字段的来源未保存，正文已保留，请对照原文核验。` : '');
        terminalProgress = {
            completed: true,
            success: summary.success,
            fieldFeedback: summary.buttonLabel,
            filled: counts.filled,
            missing: counts.missing,
            total: requestTemplate.fields.length,
            targetField: Boolean(targetField)
        };
        if (status) status.textContent = localizedSummary;
        showStatus(localizedSummary, summary.tone);
        return {
            filledCount: counts.filled,
            missingCount: counts.missing,
            preservedCount: counts.preserved,
            invalidCount: counts.invalid,
            cacheHit: result.cacheHit === true
        };
    })().catch(error => {
        if (!isCurrentLiteratureNoteContext(noteContext)) {
            return {
                filledCount: 0, missingCount: 0,
                preservedCount: 0, invalidCount: 0,
                cacheHit: false, stale: true
            };
        }
        const message = savingResult
            ? `笔记草稿保存失败，当前内容仍保留：${String(error?.message || '保存未完成').slice(0, 800)}`
            : formatLlmFailureMessage('文献笔记自动填写', error);
        terminalProgress = {
            success: false,
            saveFailed: savingResult,
            cancelled: error?.code === 'CANCELLED',
            targetField: Boolean(targetField)
        };
        if (status) status.textContent = message;
        showStatus(message, error?.code === 'CANCELLED' ? 'success' : 'error');
        throw error;
    }).finally(() => {
        if (button) {
            button.disabled = false;
            button.classList.remove('is-running');
            button.removeAttribute('aria-busy');
            delete button.dataset.aiTargetCount;
            delete button.dataset.aiTargetField;
        }
        if (buttonLabel) {
            buttonLabel.textContent = terminalProgress?.completed
                ? (terminalProgress.filled ? `已保存 ${terminalProgress.filled}/${terminalProgress.total} 项` : '未更新字段') +
                    (terminalProgress.missing ? ` · 缺失 ${terminalProgress.missing}` : '')
                : terminalProgress?.saveFailed ? '保存失败，草稿仍保留'
                : terminalProgress && !terminalProgress.cancelled
                    ? '填写失败，点击重试'
                    : 'AI 读取全文填写本模板';
        }
        fieldButtons.forEach(item => {
            item.disabled = false;
            item.classList.remove('is-running');
            item.removeAttribute('aria-busy');
            const currentValue = literatureNoteDocumentState?.valuesByTemplate?.[
                literatureNoteDocumentState?.templateId
            ]?.[item.dataset.generateLiteratureNoteField];
            const isTarget = terminalProgress?.targetField &&
                item.dataset.generateLiteratureNoteField === requestedFieldId;
            item.textContent = isTarget && terminalProgress?.completed
                ? terminalProgress.fieldFeedback
                : isTarget && terminalProgress?.saveFailed ? '保存失败，草稿仍保留'
                : isTarget && terminalProgress && !terminalProgress.cancelled
                    ? 'AI 重试'
                    : currentValue ? 'AI 重新生成' : 'AI 生成';
        });
        const terminalMainLabel = buttonLabel?.textContent || '';
        const terminalTargetLabel = targetButton?.textContent || '';
        setTimeout(() => {
            if (!literatureNoteAutofillPromise &&
                literatureNoteButtonFeedbackSequence === feedbackSequence && buttonLabel &&
                buttonLabel.textContent === terminalMainLabel) {
                buttonLabel.textContent = 'AI 读取全文填写本模板';
            }
            if (!literatureNoteAutofillPromise &&
                literatureNoteButtonFeedbackSequence === feedbackSequence && targetButton &&
                targetButton.textContent === terminalTargetLabel) {
                const currentValue = literatureNoteDocumentState?.valuesByTemplate?.[
                    literatureNoteDocumentState?.templateId
                ]?.[targetButton.dataset.generateLiteratureNoteField];
                targetButton.textContent = currentValue ? 'AI 重新生成' : 'AI 生成';
            }
        }, 2400);
        literatureNoteAutofillPromise = null;
    });
    literatureNoteAutofillPromise = promise;
    return promise;
}

async function autofillLiteratureNoteFieldWithLLM(fieldId) {
    return autofillLiteratureNoteWithLLM({ fieldId });
}

async function openLiteratureNoteDrawer({ activate = true } = {}) {
    const drawer = document.getElementById('literatureNoteDrawer');
    const button = document.getElementById('openLiteratureNote');
    if (!drawer || !button) return;
    if (activate) switchWorkspaceView('notes', { loadNotes: false });
    const requestSequence = ++literatureNoteOpenSequence;
    const panelKey = activePanelTabContext.key;
    // Input handlers update this state immediately; do not replace pending edits
    // with an older persisted snapshot when returning from another module.
    if (!literatureNoteDocumentState) await loadLiteratureNoteDocumentState();
    if (requestSequence !== literatureNoteOpenSequence || activeWorkspaceView !== 'notes' ||
        panelKey !== activePanelTabContext.key) return;
    const restored = applyCurrentPaperMetaToLiteratureNote();
    renderLiteratureNoteDrawer();
    if (restored.changedFields.length) scheduleLiteratureNoteSave();
    drawer.hidden = false;
    ensureLiteratureNoteResizeObserver();
    resizeLiteratureNoteTextareas();
    requestAnimationFrame(() => resizeLiteratureNoteTextareas());
}

function closeLiteratureNoteDrawer() {
    literatureNoteOpenSequence += 1;
    const drawer = document.getElementById('literatureNoteDrawer');
    if (drawer) drawer.hidden = true;
    if (activeWorkspaceView === 'notes') switchWorkspaceView('navigation');
}

function getReadingViewDefinition(viewId = readingViewId) {
    return llmSettingsState?.readingViews?.[viewId] || { categoryIds: [] };
}

function normalizePopupPresentationDensity(value) {
    return 'all';
}

function highlightPresentationStateKey(
    documentHash = preparedDocumentState?.documentHash,
    viewId = readingViewId
) {
    const hash = String(documentHash || '').trim();
    const view = String(viewId || '').trim();
    return hash && view ? `${hash}:${view}` : '';
}

async function restoreHighlightPresentationState() {
    const expectedKey = highlightPresentationStateKey();
    presentationDensity = 'all';
    hiddenDisplayFamilyIds = new Set();
    if (expectedKey) {
        const stored = await chrome.storage.local.get(HIGHLIGHT_PRESENTATION_STORAGE_KEY);
        if (expectedKey !== highlightPresentationStateKey()) return false;
        const entry = stored?.[HIGHLIGHT_PRESENTATION_STORAGE_KEY]?.entries?.[expectedKey] || {};
        presentationDensity = normalizePopupPresentationDensity(entry.density);
        // Scenario categories now directly control display; old family filters stay archival only.
        hiddenDisplayFamilyIds = new Set();
    }
    renderHighlightPresentationControls();
    await applyHighlightPresentationToPage({ persist: false });
    return true;
}

async function persistHighlightPresentationState() {
    const key = highlightPresentationStateKey();
    if (!key) return;
    const stored = await chrome.storage.local.get(HIGHLIGHT_PRESENTATION_STORAGE_KEY);
    const current = stored?.[HIGHLIGHT_PRESENTATION_STORAGE_KEY] || {};
    const entries = { ...(current.entries || {}) };
    entries[key] = {
        density: presentationDensity,
        hiddenFamilyIds: [...hiddenDisplayFamilyIds],
        updatedAt: new Date().toISOString()
    };
    const boundedEntries = Object.fromEntries(
        Object.entries(entries)
            .sort((left, right) => String(right[1]?.updatedAt || '')
                .localeCompare(String(left[1]?.updatedAt || '')))
            .slice(0, 200)
    );
    await chrome.storage.local.set({
        [HIGHLIGHT_PRESENTATION_STORAGE_KEY]: {
            schemaVersion: 1,
            entries: boundedEntries
        }
    });
}

async function applyHighlightPresentationToPage({ persist = true } = {}) {
    if (persist) await persistHighlightPresentationState();
    if (analysisMode !== 'llm') return null;
    const tab = await queryPanelTargetTab();
    if (!tab?.id) return null;
    const response = await sendTabMessage(tab.id, {
        action: 'applyLlmPresentation',
        density: presentationDensity,
        hiddenFamilyIds: [...hiddenDisplayFamilyIds],
        language: llmSettingsState?.settings?.language || 'zh-CN'
    });
    if (response?.success && response.applied) {
        matchCounts = response.counts || matchCounts;
        presentationFamilyCounts = response.familyCounts || {};
        renderCategories();
        renderHighlightPresentationControls();
    }
    return response;
}

function renderHighlightPresentationControls() {
    const controls = document.getElementById('highlightPresentationControls');
    const fineDetails = document.getElementById('fineCategoryDetails');
    if (!controls || !fineDetails) return;
    // Legacy family filters remain archival; current scenarios expose fine categories.
    controls.hidden = true;
    if (!fineCategoryDetailsTouched) fineDetails.open = true;
    document.querySelectorAll('input[name="presentationDensity"]').forEach(radio => {
        radio.checked = radio.value === presentationDensity;
    });

    const legend = document.getElementById('highlightFamilyLegend');
    legend.replaceChildren();
}

function getCurrentViewOverride(viewId = readingViewId) {
    void viewId;
    return { add: [], remove: [] };
}

function getConfiguredViewSelection(viewId = readingViewId) {
    const view = getReadingViewDefinition(viewId);
    const override = getCurrentViewOverride(viewId);
    const selected = new Set([...(view.categoryIds || []), ...override.add]);
    override.remove.forEach(categoryId => selected.delete(categoryId));
    return selected;
}

function getPreparedCategorySource(categoryId) {
    if (getCurrentViewOverride().add.includes(categoryId)) return 'manual';
    const source = preparedDocumentState?.categorySources
        ?.find(item => item.categoryId === categoryId)?.source;
    return source || '';
}

function syncPreparedSelection() {
    if (!Array.isArray(preparedDocumentState?.activeCategories)) {
        llmSelectedCategories = getConfiguredViewSelection();
        return;
    }
    const override = getCurrentViewOverride();
    const selected = new Set(
        (preparedDocumentState.activeCategories || []).map(category => category.categoryId)
    );
    override.add.forEach(categoryId => selected.add(categoryId));
    override.remove.forEach(categoryId => selected.delete(categoryId));
    llmSelectedCategories = selected;
}

function invalidatePreparedComposition() {
    if (preparedDocumentState) {
        preparedDocumentState = {
            ...preparedDocumentState,
            activeCategories: null,
            categorySources: []
        };
    }
    syncPreparedSelection();
}

function updateReadingViewControl() {
    const container = document.getElementById('readingViewOptions');
    if (!container) return;
    const views = llmSettingsState?.readingViews || {};
    const studyType = preparedDocumentState?.studyProfile?.primaryType;
    const recommendation = SciLLM.STUDY_VIEW_RECOMMENDATIONS?.[studyType];
    container.replaceChildren();
    Object.entries(views).forEach(([viewId, definition], index) => {
        const label = document.createElement('label');
        label.title = definition?.description || '';
        const radio = document.createElement('input');
        radio.type = 'radio';
        radio.name = 'readingView';
        radio.value = viewId;
        radio.checked = viewId === readingViewId ||
            (!Object.prototype.hasOwnProperty.call(views, readingViewId) && index === 0);
        const text = document.createElement('span');
        text.textContent = definition?.name || viewId;
        const recommendationLabel = recommendation?.defaultViewId === viewId
            ? '默认'
            : recommendation?.recommendedViewIds?.includes(viewId) ? '推荐' : '';
        if (recommendationLabel) {
            const badge = document.createElement('small');
            badge.className = 'reading-view-recommendation';
            badge.textContent = recommendationLabel;
            text.appendChild(badge);
        }
        label.append(radio, text);
        container.appendChild(label);
    });
}

function highlightButtonProgressLabel(state = {}) {
    const completed = Math.max(0, Number(state.completed) || 0);
    const total = Math.max(0, Number(state.total) || 0);
    const count = total ? `${Math.min(completed, total)}/${total}` : '';
    if (state.paused) return count ? `已暂停 · ${count}` : '全文分析已暂停';
    const phase = String(state.phase || '');
    if (phase === 'paragraph_checkpoint') {
        return count ? `已保存正文段 ${count}` : '正在保存正文段结果';
    }
    if (phase === 'chunk_checkpoint') {
        return count ? `已完成分块 ${count}` : '正在保存分析分块';
    }
    if (/retry/u.test(phase)) {
        return count ? `正在重试 · ${count}` : '正在重试当前分析分块';
    }
    if (/split/u.test(phase)) {
        return count ? `正在拆分 · ${count}` : '正在拆分过长正文';
    }
    if (phase === 'provider_request_started' || phase === 'provider_waiting') {
        return count ? `模型处理中 · ${count}` : '模型正在分析全文';
    }
    if (phase === 'complete') return count ? `分析完成 ${count}` : '全文分析完成';
    return count ? `正在分析 ${count}` : '正在分析全文';
}

function setModuleActionLabel(button, fullLabel, shortLabel, statusElementId = '') {
    if (!button) return;
    if (button.dataset?.moduleAction === undefined) {
        button.textContent = fullLabel;
        return;
    }
    button.textContent = shortLabel || fullLabel;
    button.setAttribute('aria-label', fullLabel);
    button.title = fullLabel;
    const status = statusElementId && document.getElementById(statusElementId);
    if (status) {
        const busy = button.getAttribute('aria-busy') === 'true';
        status.hidden = !busy;
        status.textContent = busy ? fullLabel : '';
    }
}

function updateApplyButton() {
    const applyButton = document.getElementById('applyHighlight');
    const setLabel = (fullLabel, shortLabel) => {
        if (applyButton.dataset.moduleAction !== undefined) {
            setModuleActionLabel(applyButton, fullLabel, shortLabel, 'highlightHeaderTaskStatus');
        } else {
            applyButton.textContent = fullLabel;
        }
    };
    delete applyButton.dataset.settingsCta;
    updateHighlightTaskControls();
    applyButton.removeAttribute('title');
    const llmPending = analysisMode === 'llm' &&
        (regexApplyPending || highlightTaskState.running || prepareState === 'analyzing');
    applyButton.classList.toggle('is-llm-pending', llmPending);
    applyButton.setAttribute('aria-busy', String(llmPending));
    if (regexApplyPending) {
        setLabel(analysisMode === 'llm'
            ? highlightButtonProgressLabel(highlightTaskState) : '正在应用高亮', '处理中');
        applyButton.disabled = true;
        return;
    }
    if (preferenceMutationCoordinator.isPending()) {
        setLabel('正在更新分析设置', '处理中');
        applyButton.disabled = true;
        return;
    }
    if (analysisMode !== 'llm') {
        setLabel(regexApplyPending ? '正在应用高亮' : '应用高亮', '高亮');
        applyButton.disabled = regexApplyPending || selectedCategories.size === 0;
        return;
    }
    if (llmSettingsState?.effectiveMode !== 'llm') {
        setLabel('先配置 API', '设置');
        applyButton.disabled = false;
        applyButton.dataset.settingsCta = 'true';
    } else if (prepareState === 'preparing') {
        setLabel('正在准备正文', '准备中');
        applyButton.disabled = true;
    } else if (prepareState === 'analyzing') {
        setLabel('正在分析全文', '处理中');
        applyButton.disabled = true;
    } else if (!preparedDocumentState?.documentHash) {
        setLabel('准备正文并分析', '高亮');
        applyButton.disabled = false;
    } else if (llmSelectedCategories.size === 0) {
        setLabel('请至少选择一个分类', '选类别');
        applyButton.disabled = true;
    } else if (preparedDocumentState.fullTextAnalyzed) {
        setLabel('重新分析全文', '重分析');
        applyButton.disabled = false;
    } else {
        setLabel('分析全文', '高亮');
        applyButton.disabled = false;
    }
}

async function controlActiveAnalysis(scope, command) {
    const tab = await queryPanelTargetTab();
    if (!tab?.id) throw new Error('无法获取当前论文页面');
    if (scope === 'highlight') {
        highlightTaskState = {
            ...highlightTaskState,
            running: command !== 'cancel',
            paused: command === 'pause' ? true : command === 'resume' ? false
                : highlightTaskState.paused,
            cancelled: command === 'cancel'
        };
        updateHighlightTaskControls();
    } else {
        if (command === 'cancel') stopFigureProgressPolling();
        figureAnalysisState = {
            ...figureAnalysisState,
            running: command !== 'cancel',
            paused: command === 'pause' ? true : command === 'resume' ? false
                : figureAnalysisState.paused,
            phase: command === 'cancel' ? 'cancelled'
                : command === 'pause' ? 'paused' : 'analyzing',
            figureProgress: getFigureProgressEntries(figureAnalysisState).map(progress => ({
                ...progress,
                running: command === 'cancel' ? false : progress.running,
                cancelled: command === 'cancel' && !progress.completed && !progress.failed
                    ? true : progress.cancelled,
                phase: command === 'cancel' && !progress.completed && !progress.failed
                    ? 'cancelled' : progress.phase
            }))
        };
        updateFigureButton();
        renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
    }
    let timer = null;
    let response = null;
    try {
        response = await Promise.race([
            sendTabMessage(tab.id, {
                action: 'controlLlmOperation', scope, command
            }),
            new Promise(resolve => {
                timer = setTimeout(() => resolve({
                    success: true,
                    pending: true,
                    code: 'CONTROL_CONFIRMATION_TIMEOUT'
                }), 2200);
            })
        ]);
    } catch (error) {
        response = {
            success: true,
            pending: true,
            code: error?.code || 'CONTROL_CONFIRMATION_FAILED'
        };
    } finally {
        if (timer !== null) clearTimeout(timer);
    }
    if (!response?.success) {
        const error = new Error(response?.error || '无法控制分析任务');
        error.code = response?.code;
        throw error;
    }
    if (scope === 'figure' && response.pending && figureAnalysisState.operationId) {
        void chrome.runtime.sendMessage({
            type: 'LLM_CONTROL_OPERATION',
            operationId: figureAnalysisState.operationId,
            command
        }).catch(() => undefined);
    }
    if (scope === 'figure' && command !== 'cancel') {
        startFigureProgressPolling(tab.id);
    }
    const label = command === 'cancel' ? '已取消' : command === 'pause' ? '已暂停' : '已继续';
    showStatus(
        `${label}${scope === 'figure' ? ' Figure 解读' : '全文 LLM 高亮'}` +
            (response.pending ? '；后台确认稍有延迟，界面已立即释放' : ''),
        'success'
    );
    return response;
}

function updateHighlightTaskControls() {
    const controls = document.getElementById('highlightTaskControls');
    const pause = document.getElementById('pauseHighlightAnalysis');
    const cancel = document.getElementById('cancelHighlightAnalysis');
    if (!controls || !pause || !cancel) return;
    const active = highlightTaskState.running && !highlightTaskState.cancelled;
    controls.hidden = !active;
    pause.textContent = highlightTaskState.paused ? '继续分析' : '暂停分析';
    pause.disabled = !active;
    cancel.disabled = !active;
}

function updateFigureTaskControls() {
    const controls = document.getElementById('figureTaskControls');
    const pause = document.getElementById('pauseFigureAnalysis');
    const cancel = document.getElementById('cancelFigureAnalysis');
    if (!controls || !pause || !cancel) return;
    const active = hasRunningFigureProgress(figureAnalysisState);
    controls.hidden = !active;
    pause.textContent = figureAnalysisState.paused ? '继续图解' : '暂停图解';
    pause.disabled = !active;
    cancel.disabled = !active;
}

function updateFigureButton() {
    const figureButton = document.getElementById('analyzeFiguresFromFigures') ||
        document.getElementById('analyzeFigures');
    if (!figureButton) return;
    const ready = hasUsableLlm();
    const running = hasRunningFigureProgress(figureAnalysisState);
    figureButton.hidden = false;
    figureButton.disabled = running;
    figureButton.classList.toggle('is-llm-pending', running || crossFigureLogicRunning);
    figureButton.setAttribute('aria-busy', String(running || crossFigureLogicRunning));
    figureButton.title = ready
        ? '依次解读全部 Figure'
        : llmUnavailableMessage('全部解图');
    if (crossFigureLogicRunning && !running) {
        const presentation = mechanismGenerationUiController.presentation();
        figureButton.textContent = presentation.total > 0
            ? `机制关系 ${Math.min(presentation.completed, presentation.total)}/` +
                `${presentation.total}`
            : '正在生成图表梳理';
    } else if (!running) {
        figureButton.textContent = '全部解图';
    } else {
        figureButton.textContent = figureButtonProgressLabel(figureAnalysisState) || '正在读取 Figure';
    }
    if (figureButton.dataset.moduleAction !== undefined) {
        setModuleActionLabel(figureButton, figureButton.textContent,
            running || crossFigureLogicRunning ? '处理中' : '解图', 'figureHeaderTaskStatus');
        if (!ready) figureButton.title = llmUnavailableMessage('全部解图');
    }
    updateFigureTaskControls();
}

function updateReviewOutlineButton() {
    const button = document.getElementById('generateReviewOutline');
    const ready = hasUsableLlm();
    let statusText = '';
    if (!reviewOutlineState.running) {
        statusText = reviewOutlineState.hasOutline
            ? '重新生成整篇逐段摘要' : '生成整篇逐段摘要';
    } else if (reviewOutlineState.phase === 'review_reduce') {
        statusText = '正在综合章节结构';
    } else if (reviewOutlineState.totalParagraphs > 0) {
        statusText = `${reviewOutlineState.completedParagraphs}/` +
            `${reviewOutlineState.totalParagraphs} 段`;
    } else {
        statusText = '正在提取正文层级';
    }
    if (button) {
        button.hidden = false;
        button.disabled = reviewOutlineState.running;
        button.classList.toggle('is-llm-pending', reviewOutlineState.running);
        button.setAttribute('aria-busy', String(reviewOutlineState.running));
        button.title = ready
            ? '生成整篇逐段摘要'
            : llmUnavailableMessage('逐段摘要');
        if (reviewOutlineState.running && reviewOutlineState.totalChunks > 0) {
            button.title = `${button.title}；分块 ${Math.min(
                reviewOutlineState.completedChunks,
                reviewOutlineState.totalChunks
            )}/${reviewOutlineState.totalChunks}`;
        }
        button.textContent = statusText;
    }
}

async function openArticleNavigator() {
    switchWorkspaceView('navigation');
    const snapshot = await refreshArticleWorkspace({ announce: true });
    if (!snapshot) return;
    const semanticCounts = popupPdfSemanticNavigationCounts(currentPdfSemanticNavigation);
    const headingCount = semanticCounts.sectionCount ||
        Number(snapshot.diagnostics?.headingCount) || 0;
    showStatus(
        headingCount
            ? `已生成本地大纲：${headingCount} 个标题`
            : '当前页面暂未识别到正文标题',
        headingCount ? 'success' : 'error'
    );
}

function validateAdapterDiagnosticBundle(value) {
    if (value?.kind !== 'sci-publisher-adapter-diagnostic' ||
        value?.schemaVersion !== 2 ||
        typeof value?.dom?.documentHtml !== 'string') {
        throw new Error('诊断包格式不完整');
    }
    return value;
}

async function diagnosticBlob(bundle) {
    const jsonBlob = new Blob([JSON.stringify(bundle, null, 2)], {
        type: 'application/json;charset=utf-8'
    });
    if (typeof CompressionStream !== 'function') {
        return { blob: jsonBlob, extension: '.json' };
    }
    const compressed = jsonBlob.stream().pipeThrough(new CompressionStream('gzip'));
    return {
        blob: await new Response(compressed).blob(),
        extension: '.json.gz'
    };
}

function diagnosticFilename(bundle, extension) {
    const hostname = String(bundle?.page?.hostname || 'page').toLowerCase()
        .replace(/[^a-z0-9.-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) || 'page';
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    return `sci-adapter-diagnostic-${hostname}-${timestamp}${extension}`;
}

function downloadBlob(blob, filename) {
    const objectUrl = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = objectUrl;
    link.download = filename;
    link.hidden = true;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
}

let adapterDiagnosticExportPending = false;

async function exportAdapterDiagnosticBundle() {
    if (adapterDiagnosticExportPending) return;
    adapterDiagnosticExportPending = true;
    const buttons = [document.getElementById('exportAdapterDiagnosticBundle')].filter(Boolean);
    buttons.forEach(button => {
        button.disabled = true;
        button.dataset.originalText ||= button.textContent;
        button.textContent = '正在生成诊断包…';
    });
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        const response = await sendTabMessage(tab.id, {
            action: 'buildAdapterDiagnosticBundle'
        });
        if (!response?.success) {
            throw new Error(response?.error || '页面没有返回适配诊断数据');
        }
        const bundle = validateAdapterDiagnosticBundle(response.bundle);
        const currentTab = await queryPanelTargetTab();
        if (currentTab?.id !== tab.id) {
            throw new Error('活动页面已变化，请在目标论文页重新导出');
        }
        const output = await diagnosticBlob(bundle);
        const filename = diagnosticFilename(bundle, output.extension);
        downloadBlob(output.blob, filename);
        showStatus(
            `适配诊断包已导出：${bundle.publisher?.family || 'generic'} · ` +
            `${bundle.candidates?.length || 0} 个候选正文根节点`,
            'success'
        );
    } catch (error) {
        showStatus('适配诊断包导出失败：' + error.message, 'error');
    } finally {
        adapterDiagnosticExportPending = false;
        buttons.forEach(button => {
            button.disabled = false;
            button.textContent = button.dataset.originalText || '导出适配诊断包';
        });
    }
}

function stopReviewOutlineProgressPolling() {
    if (reviewOutlineProgressTimer !== null) {
        clearInterval(reviewOutlineProgressTimer);
        reviewOutlineProgressTimer = null;
    }
}

function applyReviewOutlineProgress(response, announce = true) {
    if (!response?.status || typeof response.status !== 'object') return null;
    reviewOutlineState = {
        ...reviewOutlineState,
        ...response.status,
        running: Boolean(response.status.running),
        hasOutline: Boolean(response.hasOutline || reviewOutlineState.hasOutline)
    };
    updateReviewOutlineButton();
    if (announce && reviewOutlineState.running) {
        const isRecovery = reviewOutlineState.phase === 'review_retry' ||
            reviewOutlineState.phase === 'review_split';
        const progressText = isRecovery && reviewOutlineState.message
            ? reviewOutlineState.message
            : reviewOutlineState.phase === 'review_reduce'
                ? '正在综合章节结构…'
                : reviewOutlineState.totalParagraphs > 0
                    ? `正在生成逐段摘要：${reviewOutlineState.completedParagraphs}/` +
                        `${reviewOutlineState.totalParagraphs} 段…`
                    : (reviewOutlineState.message || '正在提取正文层级…');
        showStatus(progressText, 'success');
    }
    return reviewOutlineState;
}

async function refreshReviewOutlineProgress(
    tabId,
    announce = true,
    panelContext = capturePanelContext(reviewOutlineTaskGeneration)
) {
    if (!isCurrentReviewOutlineTask(panelContext) ||
        Number(tabId) !== Number(panelContext.tabId)) return null;
    try {
        const response = await sendTabMessage(tabId, { action: 'getReviewOutlineStatus' });
        if (!isCurrentReviewOutlineTask(panelContext)) return null;
        if (!response?.success) return null;
        return applyReviewOutlineProgress(response, announce);
    } catch (error) {
        return null;
    }
}

function startReviewOutlineProgressPolling(
    tabId,
    panelContext = capturePanelContext(reviewOutlineTaskGeneration)
) {
    stopReviewOutlineProgressPolling();
    const poll = async () => {
        if (!isCurrentReviewOutlineTask(panelContext)) {
            stopReviewOutlineProgressPolling();
            return;
        }
        const status = await refreshReviewOutlineProgress(tabId, true, panelContext);
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        if (status && !status.running) stopReviewOutlineProgressPolling();
    };
    void poll();
    reviewOutlineProgressTimer = setInterval(poll, 600);
}

async function restoreReviewOutlineProgress() {
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) return;
        const status = await refreshReviewOutlineProgress(tab.id, false);
        if (hasRunningFigureProgress(status)) {
            startReviewOutlineProgressPolling(tab.id);
            applyReviewOutlineProgress({ status, hasOutline: status.hasOutline }, true);
        }
    } catch (error) {
        // 当前网页不支持内容脚本时保留普通按钮状态。
    }
}

function stopFigureProgressPolling() {
    figureProgressPollingGeneration += 1;
    figureProgressRefreshSequence += 1;
    if (figureProgressTimer !== null) {
        clearInterval(figureProgressTimer);
        figureProgressTimer = null;
    }
}

function applyFigureAnalysisProgress(status, announce = true) {
    if (!status || typeof status !== 'object') return null;
    const running = hasRunningFigureProgress(status);
    const figureProgress = getFigureProgressEntries(status).map(item => ({
        ...item,
        running: running ? item.running === true : false
    }));
    const snapshot = { ...status, figureProgress };
    figureAnalysisState = {
        ...figureAnalysisState,
        ...snapshot,
        running
    };
    updateFigureButton();
    updateReviewOutlineButton();
    const renderSignature = figureProgressUiSignature(figureAnalysisState);
    if (renderSignature !== figureProgressRenderSignature) {
        figureProgressRenderSignature = renderSignature;
        renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
    } else {
        updateFigureElapsedLabels(figureAnalysisState);
    }
    if (announce && figureAnalysisState.running) {
        const activeProgress = figureProgress.find(item => item?.running === true) ||
            figureProgress[figureProgress.length - 1];
        const message = activeProgress
            ? `${activeProgress.figureLabel || activeProgress.figureId || 'Figure'}：` +
                formatFigureProgress(activeProgress).phaseText
            : figureAnalysisState.message || (
            figureAnalysisState.totalFigures > 0 && figureAnalysisState.currentFigure > 0
                ? `正在处理第 ${figureAnalysisState.currentFigure}/${figureAnalysisState.totalFigures} 张：` +
                    (figureAnalysisState.figureLabel || 'Figure')
                : '正在读取论文中的 Figure…');
        showStatus(message, 'success');
    }
    return figureAnalysisState;
}

async function refreshFigureAnalysisProgress(tabId, announce = true, taskToken = figureTaskGeneration) {
    const requestSequence = ++figureProgressRefreshSequence;
    try {
        const response = await sendTabMessage(tabId, {
            action: 'getFigureAnalysisStatus'
        });
        if (requestSequence !== figureProgressRefreshSequence) return null;
        if (!isCurrentFigureTask(taskToken, tabId)) return null;
        if (!response?.success) return null;
        const applied = applyFigureAnalysisProgress(response.status, announce);
        const signature = getFigureProgressEntries(applied).map(progress => [
            progress.figureId,
            progress.phase,
            progress.completedPanelBatches || 0,
            progress.recognizedPanelCount || 0,
            progress.completed === true
        ].join(':')).sort().join('|');
        const hasFreshResult = getFigureProgressEntries(applied).some(progress =>
            progress.phase === 'figure_panel_batch_complete' || progress.phase === 'figure'
        );
        if (hasFreshResult && signature && signature !== figureWorkspaceProgressSignature) {
            figureWorkspaceProgressSignature = signature;
            await refreshArticleWorkspace({ panelContext: capturePanelContext(taskToken) });
        }
        return applied;
    } catch (error) {
        return null;
    }
}

function startFigureProgressPolling(tabId, { waitForSnapshot = false } = {}) {
    if (figureProgressTimer !== null) return;
    const taskToken = figureTaskGeneration;
    const pollingGeneration = ++figureProgressPollingGeneration;
    let receivedRunningSnapshot = !waitForSnapshot;
    let pollInFlight = false;
    let pollSequence = 0;
    const poll = async () => {
        if (pollInFlight) return;
        pollInFlight = true;
        const currentPoll = ++pollSequence;
        try {
            const status = await refreshFigureAnalysisProgress(tabId, true, taskToken);
            if (pollingGeneration !== figureProgressPollingGeneration ||
                currentPoll !== pollSequence || !isCurrentFigureTask(taskToken, tabId)) return;
            if (status && hasRunningFigureProgress(status)) receivedRunningSnapshot = true;
            if (status && receivedRunningSnapshot && !hasRunningFigureProgress(status)) {
                stopFigureProgressPolling();
            }
        } finally {
            pollInFlight = false;
        }
    };
    void poll();
    figureProgressTimer = setInterval(poll, 600);
}

async function restoreFigureAnalysisProgress() {
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) return;
        const status = await refreshFigureAnalysisProgress(tab.id, false);
        if (hasRunningFigureProgress(status)) {
            startFigureProgressPolling(tab.id);
            applyFigureAnalysisProgress(status, true);
        }
    } catch (error) {
        // 当前网页不支持内容脚本时保持普通按钮状态。
    }
}

globalThis.addEventListener?.('beforeunload', stopFigureProgressPolling);
globalThis.addEventListener?.('unload', stopFigureProgressPolling);

async function updateLlmPreferencesCore(preferences) {
    llmSettingsState = await sendLlmMessage({
        type: 'LLM_UPDATE_PREFERENCES',
        preferences
    });
    return llmSettingsState;
}

async function updateViewCategorySelection(categoryId, checked, targetViewId) {
    const modes = (llmSettingsState?.settings?.analysisModes || []).map(mode => ({
        ...mode,
        categoryIds: Array.isArray(mode.categoryIds) ? [...mode.categoryIds] : []
    }));
    const mode = modes.find(item => item.id === targetViewId);
    if (!mode) throw new Error('分析模式不存在');
    const selected = new Set(mode.categoryIds);
    if (checked) selected.add(categoryId);
    else selected.delete(categoryId);
    mode.categoryIds = [...selected];
    return updateLlmPreferencesCore({
        analysisModes: modes,
        viewCategoryOverrides: {
            ...(llmSettingsState?.settings?.viewCategoryOverrides || {}),
            [targetViewId]: { add: [], remove: [] }
        }
    });
}

function applyPreparedComposition(prepared, document) {
    preparedDocumentState = { ...prepared, document };
    currentArticleDocument = document;
    prepareState = 'prepared';
    syncPreparedSelection();
    renderCategories();
    updateApplyButton();
    void restoreHighlightPresentationState().catch(() => undefined);
}

function queueReadingViewMutation(targetViewId) {
    const intent = preferenceMutationCoordinator.beginIntent();
    readingViewId = targetViewId;
    presentationDensity = 'all';
    hiddenDisplayFamilyIds = new Set();
    void restoreHighlightPresentationState().catch(() => undefined);
    reconcileRegexSelection();
    updateReadingViewControl();
    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateLlmPreferencesCore({ readingViewId: targetViewId }),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            persistedReadingViewId = saved.settings.readingViewId || targetViewId;
            if (analysisMode === 'llm') invalidatePreparedComposition();
            else reconcileRegexSelection();
            if (isCurrent()) {
                updateReadingViewControl();
                renderCategories();
                updateApplyButton();
            }
        },
        refresh: (_saved, { isCurrent }) => analysisMode === 'llm'
            ? refreshPreparedComposition({
                isCurrent,
                expectedViewId: targetViewId
            })
            : Promise.resolve({ prepared: false }),
        onSaveFailed: () => {
            readingViewId = persistedReadingViewId;
            updateReadingViewControl();
            if (analysisMode === 'llm') syncPreparedSelection();
            else reconcileRegexSelection();
            renderCategories();
            updateApplyButton();
            showStatus('切换分析模式失败，已恢复原选择', 'error');
        },
        onRefreshFailed: error => {
            renderCategories();
            updateApplyButton();
            showStatus(`分析模式已保存，但正文组合刷新失败：${error.message}`, 'error');
        }
    }).then(result => {
        if (result.status === 'refreshed') {
            const viewName = llmSettingsState?.readingViews?.[targetViewId]?.name || targetViewId;
            showStatus(`已切换到${viewName}`, 'success');
        }
        return result;
    });
}

function queueCategorySelectionMutation(categoryId, checked, targetViewId) {
    const intent = preferenceMutationCoordinator.beginIntent();
    const llmSelection = analysisMode === 'llm';
    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateViewCategorySelection(categoryId, checked, targetViewId),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            if (llmSelection) invalidatePreparedComposition();
            else reconcileRegexSelection();
            if (isCurrent()) {
                renderCategories();
                updateApplyButton();
            }
        },
        refresh: (_saved, { isCurrent }) => llmSelection
            ? refreshPreparedComposition({
                isCurrent,
                expectedViewId: targetViewId
            })
            : Promise.resolve({ prepared: false }),
        onSaveFailed: () => {
            if (llmSelection) syncPreparedSelection();
            else reconcileRegexSelection();
            renderCategories();
            updateApplyButton();
            showStatus('保存分类失败，已恢复原选择', 'error');
        },
        onRefreshFailed: error => {
            renderCategories();
            updateApplyButton();
            showStatus(`分类已保存，但正文组合刷新失败：${error.message}`, 'error');
        }
    });
}

function queueRestoreViewPreset(targetViewId) {
    const intent = preferenceMutationCoordinator.beginIntent();
    const llmSelection = analysisMode === 'llm';
    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => {
            const fallback = (llmSettingsState?.analysisModeDefaults || [])
                .find(mode => mode.id === targetViewId);
            if (!fallback) throw new Error('自定义分析模式没有内置预设');
            const modes = (llmSettingsState?.settings?.analysisModes || []).map(mode =>
                mode.id === targetViewId
                    ? { ...mode, categoryIds: [...fallback.categoryIds] }
                    : { ...mode, categoryIds: [...(mode.categoryIds || [])] }
            );
            return updateLlmPreferencesCore({
                analysisModes: modes,
                viewCategoryOverrides: {
                    ...(llmSettingsState?.settings?.viewCategoryOverrides || {}),
                    [targetViewId]: { add: [], remove: [] }
                }
            });
        },
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            if (llmSelection) invalidatePreparedComposition();
            else reconcileRegexSelection();
            if (isCurrent()) {
                renderCategories();
                updateApplyButton();
            }
        },
        refresh: (_saved, { isCurrent }) => llmSelection
            ? refreshPreparedComposition({
                isCurrent,
                expectedViewId: targetViewId
            })
            : Promise.resolve({ prepared: false }),
        onSaveFailed: () => {
            if (llmSelection) syncPreparedSelection();
            else reconcileRegexSelection();
            renderCategories();
            updateApplyButton();
            showStatus('恢复预设失败，已保留原分类选择', 'error');
        },
        onRefreshFailed: error => {
            renderCategories();
            updateApplyButton();
            showStatus(`预设已保存，但正文组合刷新失败：${error.message}`, 'error');
        }
    });
}

function reconcilePersistedLlmControls(saved, isCurrent) {
    const savedSettings = saved?.settings || {};
    persistedAnalysisMode = savedSettings.mode || persistedAnalysisMode;
    const savedConfidence = Number(savedSettings.confidenceThreshold);
    if (Number.isFinite(savedConfidence)) {
        persistedConfidenceThreshold = savedConfidence;
    }
    if (!isCurrent()) return;
    analysisMode = persistedAnalysisMode;
    confidenceThreshold = persistedConfidenceThreshold;
    const modeRadio = document.querySelector(
        `input[name="analysisMode"][value="${analysisMode}"]`
    );
    if (modeRadio) modeRadio.checked = true;
    matchCounts = {};
    updateAnalysisModeUi();
    renderCategories();
}

function queueAnalysisModeMutation(targetMode) {
    regexApplySequence += 1;
    const intent = preferenceMutationCoordinator.beginIntent();
    analysisMode = targetMode;
    if (targetMode === 'regex') reconcileRegexSelection();
    const modeRadio = document.querySelector(
        `input[name="analysisMode"][value="${targetMode}"]`
    );
    if (modeRadio) modeRadio.checked = true;
    matchCounts = {};
    updateAnalysisModeUi();
    renderCategories();

    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateLlmPreferencesCore({ mode: targetMode }),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            if (isCurrent() && saved.settings.mode === 'llm') {
                invalidatePreparedComposition();
            } else if (isCurrent()) {
                reconcileRegexSelection();
            }
        },
        refresh: async (saved, { isCurrent }) => {
            if (saved.settings.mode !== 'llm' || saved.effectiveMode !== 'llm') {
                prepareState = 'idle';
                stopFigureProgressPolling();
                stopReviewOutlineProgressPolling();
                requestMatchCounts();
                return { prepared: false };
            }
            return prepareCurrentArticleCore({
                isCurrent,
                expectedViewId: readingViewId
            });
        },
        onSaveFailed: () => {
            analysisMode = persistedAnalysisMode;
            confidenceThreshold = persistedConfidenceThreshold;
            const rollbackRadio = document.querySelector(
                `input[name="analysisMode"][value="${analysisMode}"]`
            );
            if (rollbackRadio) rollbackRadio.checked = true;
            updateAnalysisModeUi();
            renderCategories();
            showStatus('无法切换识别模式，已恢复原设置', 'error');
        },
        onRefreshFailed: error => {
            prepareState = 'idle';
            updateApplyButton();
            showStatus(`识别模式已保存，但正文准备失败：${error.message}`, 'error');
        }
    }).then(async result => {
        if (!preferenceMutationCoordinator.isCurrent(intent)) return result;
        if (analysisMode === 'llm' && result.status === 'refreshed') {
            await refreshLlmDiagnostics();
            await restoreFigureAnalysisProgress();
            await restoreReviewOutlineProgress();
        }
        return result;
    });
}

function queueConfidenceThresholdMutation(targetThreshold) {
    const intent = preferenceMutationCoordinator.beginIntent();
    confidenceThreshold = targetThreshold;
    renderConfidenceControl();

    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateLlmPreferencesCore({
            confidenceThreshold: targetThreshold
        }),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
        },
        refresh: async (saved, { isCurrent }) => {
            if (saved.settings.mode === 'llm' && saved.effectiveMode === 'llm') {
                await prepareCurrentArticleCore({
                    isCurrent,
                    expectedViewId: readingViewId
                });
            }
            if (!isCurrent()) return { applied: false, reason: 'superseded' };
            const tab = await queryPanelTargetTab();
            if (!tab?.id) throw new Error('无法获取当前论文页面');
            const response = await sendTabMessage(tab.id, {
                action: 'applyLlmConfidenceThreshold',
                threshold: targetThreshold
            });
            if (isCurrent() && response?.applied) {
                matchCounts = response.counts || matchCounts;
                presentationFamilyCounts = response.familyCounts || {};
                renderCategories();
            }
            return response;
        },
        onSaveFailed: () => {
            confidenceThreshold = persistedConfidenceThreshold;
            analysisMode = persistedAnalysisMode;
            const rollbackRadio = document.querySelector(
                `input[name="analysisMode"][value="${analysisMode}"]`
            );
            if (rollbackRadio) rollbackRadio.checked = true;
            updateAnalysisModeUi();
            renderCategories();
            showStatus('置信度保存失败，已恢复原设置', 'error');
        },
        onRefreshFailed: () => {
            renderConfidenceControl();
            showStatus('置信度已保存；刷新论文页面后重新分析即可应用', 'success');
        }
    }).then(async result => {
        if (!preferenceMutationCoordinator.isCurrent(intent)) return result;
        if (result.status === 'refreshed') {
            await refreshLlmDiagnostics();
            showStatus(
                `最低置信度已设为 ${Math.round(confidenceThreshold * 100)}%`,
                'success'
            );
        }
        return result;
    });
}

async function prepareArticleForAdaptiveAnalysis(tabId, {
    isCurrent = () => true,
    expectedViewId = readingViewId,
    forceRefresh = false
} = {}) {
    prepareState = 'preparing';
    updateApplyButton();
    const extracted = await sendTabMessage(tabId, {
        action: 'extractArticleForLLM',
        forceRefresh
    });
    if (!extracted?.success || !extracted.document?.paragraphs?.length) {
        throw new Error(extracted?.error || '未提取到论文正文');
    }
    if (!isCurrent()) return { stale: true };
    currentArticleDocument = extracted.document;
    const prepared = await sendLlmMessage({
        type: 'LLM_PREPARE_DOCUMENT',
        document: {
            title: extracted.document.title,
            paragraphs: extracted.document.paragraphs
        }
    });
    if (!shouldApplyPreparedResult({
        isCurrent: isCurrent(),
        expectedDocumentHash: null,
        expectedViewId,
        prepared
    })) {
        return { ...prepared, stale: true };
    }
    applyPreparedComposition(prepared, extracted.document);
    if (!isCurrent()) return { ...prepared, stale: true };
    await refreshManualAnnotationSummary(tabId);
    if (!isCurrent()) return { ...prepared, stale: true };
    return prepared;
}

async function prepareCurrentArticleCore({
    isCurrent = () => true,
    expectedViewId = readingViewId,
    forceRefresh = false
} = {}) {
    const tab = await queryPanelTargetTab();
    if (!tab?.id) throw new Error('无法获取当前论文页面');
    return prepareArticleForAdaptiveAnalysis(tab.id, {
        isCurrent,
        expectedViewId,
        forceRefresh
    });
}

async function prepareCurrentArticleForTypeChoice({
    throwOnError = false,
    forceRefresh = false
} = {}) {
    if (analysisMode !== 'llm' || llmSettingsState?.effectiveMode !== 'llm' ||
        prepareState === 'preparing' || prepareState === 'analyzing') return null;
    const intent = preferenceMutationCoordinator.beginIntent();
    const expectedViewId = readingViewId;
    lastArticlePreparationError = null;
    try {
        const prepared = await preferenceMutationCoordinator.enqueue(
            intent,
            ({ isCurrent }) => prepareCurrentArticleCore({
                isCurrent,
                expectedViewId,
                forceRefresh
            })
        );
        return prepared;
    } catch (error) {
        lastArticlePreparationError = error;
        if (preferenceMutationCoordinator.isCurrent(intent)) {
            prepareState = 'idle';
            updateApplyButton();
            showStatus(`正文准备失败：${error.message}`, 'error');
        }
        if (throwOnError) throw error;
        return null;
    }
}

async function refreshPreparedComposition({
    isCurrent = () => true,
    expectedViewId = readingViewId
} = {}) {
    const document = currentArticleDocument || preparedDocumentState?.document;
    if (!document) {
        syncPreparedSelection();
        renderCategories();
        return { applied: false, reason: 'document_unavailable' };
    }
    const expectedDocumentHash = preparedDocumentState?.documentHash || null;
    const prepared = await sendLlmMessage({
        type: 'LLM_PREPARE_DOCUMENT',
        document: {
            title: document.title,
            paragraphs: document.paragraphs
        }
    });
    const applies = shouldApplyPreparedResult({
        isCurrent: isCurrent(),
        expectedDocumentHash,
        expectedViewId,
        prepared
    });
    if (!applies) {
        if (!isCurrent()) return { applied: false, reason: 'superseded' };
        throw new Error('返回的正文组合与当前文献或分析模式不一致');
    }
    applyPreparedComposition(prepared, document);
    return { applied: true, prepared };
}

function renderConfidenceControl() {
    const slider = document.getElementById('confidenceThreshold');
    slider.value = String(confidenceThreshold);
    document.getElementById('confidenceValue').textContent =
        `${Math.round(confidenceThreshold * 100)}%`;
}

function updateAnalysisModeUi() {
    const isLlm = analysisMode === 'llm';
    document.getElementById('spanModeSection').hidden = isLlm;
    document.getElementById('llmAdaptiveControls').hidden = false;
    const hasPreset = (llmSettingsState?.analysisModeDefaults || [])
        .some(mode => mode.id === readingViewId);
    document.getElementById('restoreViewPreset').hidden = !hasPreset;
    document.getElementById('llmDiagnostics').hidden = !isLlm;
    document.getElementById('confidenceControl').hidden = !isLlm;
    updateReadingViewControl();
    renderHighlightPresentationControls();
    updateApplyButton();
    updateFigureButton();
    updateReviewOutlineButton();
    renderConfidenceControl();
}

async function refreshLlmDiagnostics() {
    const element = document.getElementById('llmDiagnostics');
    if (analysisMode !== 'llm') {
        element.hidden = true;
        return;
    }
    element.hidden = false;
    element.textContent = '正在读取当前页面的正文提取诊断…';
    try {
        const tab = await queryPanelTargetTab();
        const response = await sendTabMessage(tab.id, { action: 'getLlmDiagnostics' });
        if (!response?.success) throw new Error(response?.error || '诊断不可用');
        const diagnostics = response.diagnostics || {};
        const extraction = diagnostics.extraction || {};
        const selected = extraction.selected || {};
        const parts = [
            `提取器 ${extraction.version || '未知'}`,
            `候选区 ${extraction.candidateCount ?? 0}`,
            `已选 ${extraction.selectedRoot || '未知'}`,
            `正文 ${selected.paragraphCount ?? 0} 段`,
            '图注不参与分析',
            `共 ${selected.characterCount ?? 0} 字符`
        ];
        const unrecognized = Array.isArray(extraction.unrecognizedTextBlocks)
            ? extraction.unrecognizedTextBlocks
            : [];
        if (unrecognized.length) {
            const patterns = unrecognized.slice(0, 4)
                .map(item => `${item.root}×${item.count}/${item.characterCount}字`)
                .join('；');
            parts.push(
                `未识别长文本 ${extraction.unrecognizedTextBlockCount ?? 0} 块/` +
                `${extraction.unrecognizedCharacterCount ?? 0} 字：${patterns}`
            );
        }
        if (diagnostics.studyProfile) {
            const profile = diagnostics.studyProfile;
            const primaryName = llmSettingsState?.studyTypes?.[profile.primaryType]?.name ||
                profile.primaryType;
            parts.push(`类型 ${primaryName}（用户选择）`);
            parts.push(`模式 ${llmSettingsState?.readingViews?.[diagnostics.readingViewId]?.name || diagnostics.readingViewId}`);
            parts.push('类型已选择');
        }
        if (Number.isInteger(diagnostics.annotationCount)) {
            parts.push(`模型返回 ${diagnostics.annotationCount} 条`);
            parts.push(`成功应用 ${diagnostics.highlightedCount ?? 0} 条`);
            parts.push(`定位拒绝 ${diagnostics.rejectedCount ?? 0} 条`);
            parts.push(`阈值 ${Math.round((diagnostics.confidenceThreshold || 0.8) * 100)}%`);
            parts.push(`低于阈值隐藏 ${diagnostics.hiddenConfidenceCount || 0} 条`);
            parts.push(`呈现层隐藏 ${diagnostics.hiddenPresentationCount || 0} 条`);
            parts.push(`语义拒绝 ${diagnostics.semanticRejectedCount || 0} 条`);
            parts.push(diagnostics.ledgerAvailable === false ? '台账复核不可用' :
                `台账关系 ${diagnostics.relationCount || 0} 条/审读 ${diagnostics.auditItemCount || 0} 条`);
        }
        element.textContent = parts.join('｜');
    } catch (error) {
        element.textContent = '提取诊断不可用，请刷新论文页面后重新打开插件。';
    }
}

// 渲染类别列表
function getLlmCategoryEntries() {
    return getCategoryEntriesForEngine('llm');
}

function openCategoryRuleEditor(categoryId) {
    const url = chrome.runtime.getURL('options.html#page=categories&category=' +
        encodeURIComponent(categoryId));
    return chrome.tabs.create({ url }).catch(error => {
        showStatus(`无法打开分类规则设置：${error.message}`, 'error');
        return null;
    });
}

function createCategoryItem(key, rule, { checked, idSuffix = '' } = {}) {
        const item = document.createElement('div');
        item.className = analysisMode === 'llm'
            ? 'category-item category-item-compact'
            : 'category-item';
        
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.id = `cat-${key}${idSuffix}`;
        checkbox.checked = Boolean(checked);
        checkbox.setAttribute('aria-label', `${checkbox.checked ? '停用' : '启用'}${rule.name}`);
        checkbox.addEventListener('change', async (e) => {
            const targetViewId = readingViewId;
            try {
                await queueCategorySelectionMutation(
                    key,
                    e.target.checked,
                    targetViewId
                );
                if (analysisMode === 'regex') {
                    await saveSettings();
                }
            } catch (error) {
                if (analysisMode === 'llm') syncPreparedSelection();
                else reconcileRegexSelection();
                renderCategories();
                showStatus(`保存分类失败，已恢复原选择：${error.message}`, 'error');
            }
        });

        const colorDiv = document.createElement('div');
        colorDiv.className = 'category-color';
        colorDiv.style.backgroundColor = rule.color;
        
        const infoDiv = document.createElement('div');
        infoDiv.className = 'category-info';
        
        const nameDiv = document.createElement('div');
        nameDiv.className = 'category-name';
        nameDiv.textContent = rule.name;
        
        // 显示匹配计数
        if (matchCounts[key] !== undefined && matchCounts[key] > 0) {
            const matchBadge = document.createElement('span');
            matchBadge.className = 'match-count';
            matchBadge.textContent = matchCounts[key];
            nameDiv.appendChild(matchBadge);
        }
        
        const countDiv = document.createElement('div');
        countDiv.className = 'category-count';
        const engines = Array.isArray(rule.enabledEngines)
            ? rule.enabledEngines : ['llm', 'regex'];
        const supportedByCurrentEngine = engines.includes(analysisMode);
        if (analysisMode === 'llm') {
            const sourceLabels = {
                view_default: '视图预设',
                primary_type: '主要类型',
                manual: '用户添加'
            };
            const source = sourceLabels[getPreparedCategorySource(key)] ||
                ((getReadingViewDefinition().categoryIds || []).includes(key)
                    ? '视图预设' : '可选类别');
            countDiv.textContent = rule.persistence === 'one-off'
                ? `${source} · 仅本次会话`
                : `${source} · LLM 语义识别`;
        } else {
            countDiv.textContent = supportedByCurrentEngine
                ? (rule.persistence === 'one-off' ? '正则识别 · 仅本次会话' : '正则识别')
                : '需要 LLM 识别';
        }
        
        infoDiv.appendChild(nameDiv);
        infoDiv.appendChild(countDiv);
        
        // 操作按钮
        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'category-actions';
        
        const editBtn = document.createElement('button');
        editBtn.className = 'category-rule-button';
        editBtn.textContent = '查看/编辑规则';
        editBtn.addEventListener('click', event => {
            event.stopPropagation();
            openCategoryRuleEditor(key);
        });
        
        actionsDiv.appendChild(editBtn);

        item.appendChild(checkbox);
        item.appendChild(colorDiv);
        item.appendChild(infoDiv);
        item.appendChild(actionsDiv);
        return item;
}

function renderMoreCategoryGroups(entries, activeCategoryIds) {
    const panel = document.getElementById('moreCategoriesPanel');
    const container = document.getElementById('moreCategoryGroups');
    container.innerHTML = '';
    if (panel.hidden) return;
    const groups = getMoreCategoryGroups({
        readingViews: llmSettingsState?.readingViews || {},
        activeCategoryIds,
        entries,
        searchTerm: document.getElementById('categorySearch').value
    });
    groups.forEach(group => {
        const section = document.createElement('section');
        section.className = 'more-category-group';
        const heading = document.createElement('h4');
        heading.textContent = group.name;
        section.appendChild(heading);
        group.entries.forEach(([key, rule], index) => {
            section.appendChild(createCategoryItem(key, rule, {
                checked: false,
                idSuffix: `-more-${group.viewId}-${index}`
            }));
        });
        container.appendChild(section);
    });
    if (!groups.length) {
        const empty = document.createElement('div');
        empty.className = 'more-categories-empty';
        empty.textContent = '没有匹配的其他分类';
        container.appendChild(empty);
    }
}

function renderCategories() {
    const container = document.getElementById('categoriesContainer');
    const moreButton = document.getElementById('moreCategories');
    container.innerHTML = '';

    const entries = getCategoryEntriesForEngine(analysisMode, {
        includeUnsupported: true
    });
    const currentEntries = getCurrentViewCategoryEntries({
        entries,
        preparedState: preparedDocumentState,
        configuredCategoryIds: [...getConfiguredViewSelection()]
    });
    currentEntries.forEach(([key, rule]) => {
        container.appendChild(createCategoryItem(key, rule, { checked: true }));
    });
    moreButton.hidden = false;
    const activeCategoryIds = currentEntries.map(([categoryId]) => categoryId);
    renderMoreCategoryGroups(entries, activeCategoryIds);
    
    // 更新总匹配数
    updateTotalMatchCount();
    renderHighlightPresentationControls();
}

// 更新总匹配数
function updateTotalMatchCount() {
    const totalCount = Object.values(matchCounts).reduce((sum, count) => sum + count, 0);
    const badge = document.getElementById('totalMatchCount');
    if (totalCount > 0) {
        badge.textContent = `共 ${totalCount} 处匹配`;
        badge.style.display = 'inline-block';
    } else {
        badge.style.display = 'none';
    }
}

// 请求匹配计数
async function requestMatchCounts() {
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id || analysisMode !== 'regex') return;
        const rules = await fetchCurrentRegexRules(tab.id);
        const response = await sendTabMessage(tab.id, {
            action: 'getMatchCounts',
            rules
        });
        
        if (response && response.counts) {
            matchCounts = response.counts;
            renderCategories();
        }
    } catch (error) {
        console.log('无法获取匹配计数:', error);
    }
}

async function fetchCurrentRegexRules(tabId) {
    const requestId = ++regexApplySequence;
    const selectedIds = getCategoryEntriesForEngine('regex')
        .map(([categoryId]) => categoryId)
        .filter(categoryId => selectedCategories.has(categoryId));
    const revision = Number(llmSettingsState?.settings?.userDataCategoryRevision) || 0;
    const documentId = manualAnnotationState.tabId === tabId
        ? manualAnnotationState.documentId : '';
    const resolved = await resolveRegexDetailsAtomically({
        categoryIds: selectedIds,
        fetchDetail: categoryId => sendLlmMessage({
            type: 'CATEGORY_GET',
            categoryId
        }),
        refreshState: () => sendLlmMessage({ type: 'LLM_GET_SETTINGS' }),
        validate: async refreshed => {
            const [currentTab] = await chrome.tabs.query({
                active: true,
                currentWindow: true
            });
            const currentRevision =
                Number(refreshed?.settings?.userDataCategoryRevision) || 0;
            const currentDocumentId = manualAnnotationState.tabId === currentTab?.id
                ? manualAnnotationState.documentId : '';
            return analysisMode === 'regex' && shouldApplyRegexSnapshot({
                requestId,
                currentRequestId: regexApplySequence,
                tabId,
                currentTabId: currentTab?.id,
                documentId,
                currentDocumentId,
                revision,
                currentRevision,
                selectedIds,
                currentSelectedIds: [...selectedCategories]
            });
        }
    });
    llmSettingsState = resolved.state;
    return translateUnifiedRegexCategories(resolved.details);
}

async function applyRegexOnTab(tabId) {
    const categories = await fetchCurrentRegexRules(tabId);
    return sendTabMessage(tabId, {
        action: 'applyHighlight',
        categories,
        mode: highlightMode,
        analysisModeId: readingViewId
    });
}

function createSupplementalFigureImportTools(dependencies = {}) {
    const shared = dependencies.shared || {};
    const chromeApi = dependencies.chromeApi || globalThis.chrome;
    const cryptoApi = dependencies.cryptoApi || globalThis.crypto;
    const createImageBitmapImpl = dependencies.createImageBitmapImpl ||
        globalThis.createImageBitmap;
    const ImageImpl = dependencies.ImageImpl || globalThis.Image;
    const urlApi = dependencies.urlApi || globalThis.URL;
    const createCanvas = dependencies.createCanvas ||
        (() => globalThis.document?.createElement('canvas'));
    const btoaImpl = dependencies.btoaImpl || globalThis.btoa;
    const now = dependencies.now || (() => new Date().toISOString());
    const sendTabMessageWithRecovery = dependencies.sendTabMessageWithRecovery ||
        shared.sendTabMessageWithRecovery;
    const imageMaxSourceBytes = 20 * 1024 * 1024;
    const imageMaxBytes = Number(shared.SUPPLEMENTAL_TRANSIENT_IMAGE_MAX_BYTES) ||
        1572864;
    const imageMaxEdge = Number(shared.SUPPLEMENTAL_TRANSIENT_IMAGE_MAX_EDGE) || 1600;
    const imageMimeTypes = new Set(['image/png', 'image/jpeg', 'image/webp']);
    const extensionMimeTypes = Object.freeze({
        png: 'image/png',
        jpg: 'image/jpeg',
        jpeg: 'image/jpeg',
        webp: 'image/webp'
    });

    function importError(code, message, fieldId = '') {
        const error = new Error(message || code);
        error.code = code;
        error.fieldId = fieldId;
        return error;
    }

    function syncSourceMode(root, requestedMode) {
        const modes = ['pdf', 'manual'];
        const mode = modes.includes(String(requestedMode)) ? String(requestedMode) : 'pdf';
        const radios = [...(root?.querySelectorAll?.(
            'input[name="supplementalFigureSourceMode"]'
        ) || [])];
        const panes = [...(root?.querySelectorAll?.(
            '[data-supplemental-source-pane]'
        ) || [])];
        radios.forEach(radio => {
            radio.checked = radio.value === mode;
        });
        panes.forEach(pane => {
            pane.hidden = pane.dataset?.supplementalSourcePane !== mode;
        });
        return mode;
    }

    function validateTarget(input = {}) {
        const workspaceId = String(input.workspaceId || '').trim().toLowerCase();
        const workspaceGeneration = Number(input.workspaceGeneration);
        const targetArticleTabId = Number(input.targetArticleTabId);
        const rawCanonicalUrl = String(input.canonicalUrl || '').trim();
        const canonicalUrl = typeof shared.normalizeSupplementalUrl === 'function'
            ? shared.normalizeSupplementalUrl(rawCanonicalUrl)
            : rawCanonicalUrl;
        const rawDocumentHash = String(input.documentHash || '').trim().toLowerCase();
        const documentHashHex = rawDocumentHash.replace(/^sha256:/, '');
        const documentHash = /^[a-f0-9]{64}$/.test(documentHashHex)
            ? `sha256:${documentHashHex}` : '';
        if (!/^workspace:[a-f0-9]{64}$/.test(workspaceId) ||
            !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
            !Number.isSafeInteger(targetArticleTabId) || targetArticleTabId < 0 ||
            !canonicalUrl ||
            (rawDocumentHash && !documentHash)) {
            throw importError(
                'SUPPLEMENTAL_TARGET_INVALID',
                '当前论文工作区尚未准备完成，请刷新后重试'
            );
        }
        const target = {
            workspaceId,
            workspaceGeneration,
            targetArticleTabId,
            canonicalUrl
        };
        if (documentHash) target.documentHash = documentHash;
        return Object.freeze(target);
    }

    function buildTarget(snapshot, targetArticleTabId, documentHash = '') {
        const workspace = snapshot?.localWorkspace || {};
        return validateTarget({
            workspaceId: workspace.workspaceId,
            workspaceGeneration: workspace.workspaceGeneration,
            targetArticleTabId,
            // The article tab validates against its persisted workspace
            // identity. Prepared-document hashes and the visible page URL may
            // legitimately differ from that identity, so they are fallbacks
            // only when the workspace has not published the field yet.
            canonicalUrl: workspace.canonicalUrl || snapshot?.url,
            documentHash: workspace.contentHash || workspace.revision ||
                workspace.documentHash || snapshot?.documentHash || documentHash
        });
    }

    function validateImageFile(file) {
        const name = String(file?.name || '').trim();
        const mediaType = String(file?.type || '').trim().toLowerCase();
        const size = Number(file?.size);
        const extension = name.match(/\.([a-z0-9]+)$/i)?.[1]?.toLowerCase() || '';
        if (!file || !imageMimeTypes.has(mediaType) ||
            extensionMimeTypes[extension] !== mediaType ||
            !Number.isSafeInteger(size) || size <= 0 || size > imageMaxSourceBytes ||
            typeof file.arrayBuffer !== 'function') {
            throw importError(
                'SUPPLEMENTAL_IMAGE_INVALID',
                '请选择不超过 20 MiB 的 PNG、JPEG 或 WebP 图片，且扩展名与文件类型一致',
                'supplementalFigureImageFile'
            );
        }
        return file;
    }

    function normalizeCaption(value) {
        const caption = String(value || '').trim();
        if (!caption) {
            throw importError(
                'SUPPLEMENTAL_CAPTION_EMPTY', '请粘贴完整图注',
                'supplementalFigureImageCaption'
            );
        }
        if (caption.length > 8000) {
            throw importError(
                'SUPPLEMENTAL_CAPTION_TOO_LONG', '图注不能超过 8000 个字符',
                'supplementalFigureImageCaption'
            );
        }
        return caption;
    }

    function normalizeOptionalCaption(value) {
        const caption = String(value || '').trim();
        if (caption.length > 8000) {
            throw importError(
                'SUPPLEMENTAL_CAPTION_TOO_LONG', '图注不能超过 8000 个字符',
                'supplementalFigureImageCaption'
            );
        }
        return caption;
    }

    async function sha256Fingerprint(value) {
        if (!cryptoApi?.subtle?.digest) {
            throw importError('SUPPLEMENTAL_CRYPTO_UNAVAILABLE', '当前环境无法计算文件指纹');
        }
        const bytes = typeof value === 'string'
            ? new TextEncoder().encode(value)
            : value instanceof ArrayBuffer
                ? new Uint8Array(value)
                : new Uint8Array(value?.buffer || value || []);
        const digest = new Uint8Array(await cryptoApi.subtle.digest('SHA-256', bytes));
        return `sha256:${[...digest]
            .map(byte => byte.toString(16).padStart(2, '0')).join('')}`;
    }

    async function decodeImageFile(file) {
        let bitmapError = null;
        if (typeof createImageBitmapImpl === 'function') {
            try {
                const bitmap = await createImageBitmapImpl(file);
                return {
                    source: bitmap,
                    width: Number(bitmap?.width),
                    height: Number(bitmap?.height),
                    dispose: () => bitmap?.close?.()
                };
            } catch (error) {
                bitmapError = error;
            }
        }
        if (typeof ImageImpl === 'function' && urlApi?.createObjectURL) {
            const objectUrl = urlApi.createObjectURL(file);
            try {
                const image = new ImageImpl();
                await new Promise((resolve, reject) => {
                    image.onload = resolve;
                    image.onerror = () => reject(bitmapError ||
                        importError('SUPPLEMENTAL_IMAGE_DECODE', '图片无法解码'));
                    image.src = objectUrl;
                });
                return {
                    source: image,
                    width: Number(image.naturalWidth || image.width),
                    height: Number(image.naturalHeight || image.height),
                    dispose: () => urlApi.revokeObjectURL?.(objectUrl)
                };
            } catch (error) {
                urlApi.revokeObjectURL?.(objectUrl);
                throw error;
            }
        }
        if (bitmapError) throw bitmapError;
        throw importError('SUPPLEMENTAL_IMAGE_DECODE', '图片无法解码');
    }

    function canvasToBlob(canvas, mediaType, quality) {
        return new Promise((resolve, reject) => {
            try {
                canvas.toBlob(blob => {
                    if (blob) resolve(blob);
                    else reject(importError('SUPPLEMENTAL_IMAGE_ENCODE', '图片压缩失败'));
                }, mediaType, quality);
            } catch (error) {
                reject(error);
            }
        });
    }

    async function blobToDataUrl(blob, mediaType) {
        const bytes = new Uint8Array(await blob.arrayBuffer());
        let binary = '';
        for (let index = 0; index < bytes.length; index += 32768) {
            binary += String.fromCharCode(...bytes.subarray(index, index + 32768));
        }
        return `data:${mediaType};base64,${btoaImpl(binary)}`;
    }

    async function prepareTransientImage(file) {
        validateImageFile(file);
        const sourceBytes = await file.arrayBuffer();
        const sourceFingerprint = await sha256Fingerprint(sourceBytes);
        let decoded;
        try {
            decoded = await decodeImageFile(file);
        } catch (_) {
            throw importError(
                'SUPPLEMENTAL_IMAGE_DECODE', '无法解码这张图片，请重新导出后再试',
                'supplementalFigureImageFile'
            );
        }
        const sourceWidth = Number(decoded?.width);
        const sourceHeight = Number(decoded?.height);
        if (!Number.isFinite(sourceWidth) || !Number.isFinite(sourceHeight) ||
            sourceWidth <= 0 || sourceHeight <= 0) {
            decoded?.dispose?.();
            throw importError(
                'SUPPLEMENTAL_IMAGE_DECODE', '图片宽高无效，请重新选择',
                'supplementalFigureImageFile'
            );
        }
        const canvas = createCanvas();
        const context = canvas?.getContext?.('2d', { alpha: true });
        if (!canvas || !context || typeof canvas.toBlob !== 'function') {
            decoded?.dispose?.();
            throw importError('SUPPLEMENTAL_IMAGE_ENCODE', '当前环境无法处理图片');
        }
        let longestEdge = Math.min(imageMaxEdge, Math.max(sourceWidth, sourceHeight));
        let encoded = null;
        let outputWidth = 0;
        let outputHeight = 0;
        const qualities = file.type === 'image/png'
            ? [undefined]
            : [0.92, 0.84, 0.76, 0.68, 0.58];
        try {
            while (longestEdge >= 1 && !encoded) {
                const scale = Math.min(1, longestEdge / Math.max(sourceWidth, sourceHeight));
                outputWidth = Math.max(1, Math.round(sourceWidth * scale));
                outputHeight = Math.max(1, Math.round(sourceHeight * scale));
                canvas.width = outputWidth;
                canvas.height = outputHeight;
                context.drawImage(decoded.source, 0, 0, outputWidth, outputHeight);
                for (const quality of qualities) {
                    const candidate = await canvasToBlob(canvas, file.type, quality);
                    if (candidate.size > 0 && candidate.size <= imageMaxBytes) {
                        encoded = candidate;
                        break;
                    }
                }
                if (!encoded) {
                    if (longestEdge === 1) break;
                    longestEdge = Math.max(1, Math.floor(longestEdge * 0.82));
                }
            }
        } finally {
            decoded.dispose?.();
        }
        if (!encoded) {
            throw importError(
                'SUPPLEMENTAL_TRANSIENT_IMAGE_TOO_LARGE',
                '图片压缩后仍超过 1.5 MiB，请裁剪后重试',
                'supplementalFigureImageFile'
            );
        }
        const mediaType = imageMimeTypes.has(String(encoded.type).toLowerCase())
            ? String(encoded.type).toLowerCase() : file.type;
        const transient = {
            mediaType,
            dataUrl: await blobToDataUrl(encoded, mediaType),
            width: outputWidth,
            height: outputHeight,
            sourceFingerprint
        };
        return typeof shared.normalizeSupplementalTransientImage === 'function'
            ? shared.normalizeSupplementalTransientImage(transient, sourceFingerprint)
            : transient;
    }

    function sourceMaterialId(mode, sourceFingerprint) {
        return `manual-${mode}-${String(sourceFingerprint || '')
            .replace(/^sha256:/, '').slice(0, 16)}`;
    }

    function normalizeManualMetadata(input = {}) {
        const figureKind = String(input.figureKind || '').toLowerCase() === 'main'
            ? 'main' : 'supplemental';
        const figureLabel = typeof shared.canonicalManualFigureLabel === 'function'
            ? shared.canonicalManualFigureLabel(input.figureLabel, figureKind, '')
            : String(input.figureLabel || '').trim();
        if (figureKind === 'main' && !figureLabel) {
            throw importError(
                'MANUAL_FIGURE_LABEL',
                '主图需要填写 Figure 编号，例如 Figure 3',
                'supplementalFigureLabel'
            );
        }
        const rawPage = String(input.sourcePage ?? '').trim();
        const sourcePage = rawPage ? Number(rawPage) : 0;
        if (!Number.isSafeInteger(sourcePage) || sourcePage < 0 || sourcePage > 100000) {
            throw importError(
                'MANUAL_FIGURE_PAGE',
                'PDF 页码必须是正整数',
                'supplementalFigureSourcePage'
            );
        }
        return { figureKind, figureLabel, sourcePage };
    }

    function createImageImport(file, transientImage, caption = '', metadata = {}) {
        validateImageFile(file);
        const manualMetadata = normalizeManualMetadata(metadata);
        const sourceFingerprint = String(transientImage?.sourceFingerprint || '');
        const draftInput = {
            sourceMode: 'image',
            sourceMaterialId: sourceMaterialId('image', sourceFingerprint),
            sourceFileName: file.name,
            sourceMimeType: file.type,
            sourceFileSize: file.size,
            sourceImportedAt: now(),
            sourceFingerprint,
            caption: normalizeOptionalCaption(caption),
            ...manualMetadata
        };
        const draft = shared.createSupplementalFigureImportDraft(draftInput);
        return { draft, transientImage };
    }

    async function createCaptionImport(value, metadata = {}) {
        const caption = normalizeCaption(value);
        const manualMetadata = normalizeManualMetadata(metadata);
        const sourceFingerprint = await sha256Fingerprint(caption);
        const draft = shared.createSupplementalFigureImportDraft({
            sourceMode: 'caption',
            sourceMaterialId: sourceMaterialId('caption', sourceFingerprint),
            sourceImportedAt: now(),
            sourceFingerprint,
            caption,
            ...manualMetadata
        });
        return { draft };
    }

    function validateManualInput(file, caption, { hasExistingImage = false } = {}) {
        const normalizedCaption = normalizeOptionalCaption(caption);
        if (file) validateImageFile(file);
        if (!file && !normalizedCaption && !hasExistingImage) {
            throw importError(
                'SUPPLEMENTAL_MANUAL_INPUT_REQUIRED',
                '请上传或粘贴一张图片，或者填写图注',
                'supplementalFigureImageFile'
            );
        }
        return { file: file || null, caption: normalizedCaption };
    }

    function clipboardImageFile(clipboardData, FileImpl = globalThis.File) {
        const items = [...(clipboardData?.items || [])];
        const item = items.find(candidate =>
            candidate?.kind === 'file' && /^image\/(?:png|jpeg|webp)$/i.test(
                String(candidate?.type || '')
            )
        );
        const blob = item?.getAsFile?.();
        if (!blob) return null;
        const mediaType = String(blob.type || item.type || '').toLowerCase();
        const extension = mediaType === 'image/jpeg' ? 'jpg'
            : mediaType === 'image/webp' ? 'webp' : 'png';
        const currentName = String(blob.name || '');
        if (/\.(?:png|jpe?g|webp)$/i.test(currentName)) return blob;
        if (typeof FileImpl === 'function') {
            return new FileImpl([blob], `clipboard-${Date.now()}.${extension}`, {
                type: mediaType,
                lastModified: Date.now()
            });
        }
        try {
            Object.defineProperty(blob, 'name', {
                configurable: true,
                value: `clipboard-${Date.now()}.${extension}`
            });
        } catch (_) {}
        return blob;
    }

    function isClosedTabError(error) {
        const code = String(error?.code || '').trim().toUpperCase();
        if ([
            'TAB_NOT_FOUND',
            'NO_TAB',
            'INVALID_TAB_ID',
            'TAB_CLOSED',
            'TARGET_TAB_CLOSED'
        ].includes(code)) return true;
        return /No tab with id|Invalid tab ID|tab (?:was )?closed|tab not found/i
            .test(String(error?.message || error || ''));
    }

    function responseError(response, fallbackCode, fallbackMessage) {
        const structured = response?.error && typeof response.error === 'object'
            ? response.error : null;
        return importError(
            response?.code || structured?.code || fallbackCode,
            structured?.message || response?.error || fallbackMessage
        );
    }

    async function deliverImport(targetInput, request = {}) {
        const target = validateTarget(targetInput);
        const draft = request?.draft;
        if (!draft || typeof draft !== 'object' || Array.isArray(draft)) {
            throw importError('SUPPLEMENTAL_DRAFT_INVALID', '补充 Figure 草稿无效');
        }
        const message = {
            action: 'importSupplementalFigureDraft',
            target,
            draft
        };
        if (request.transientImage) {
            const transientImage = shared.normalizeSupplementalTransientImage(
                request.transientImage,
                request.transientImage.sourceFingerprint
            );
            message.transientImage = {
                mediaType: transientImage.mediaType,
                dataUrl: transientImage.dataUrl,
                width: transientImage.width,
                height: transientImage.height,
                sourceFingerprint: transientImage.sourceFingerprint
            };
        }
        try {
            const response = await sendTabMessageWithRecovery(
                chromeApi, target.targetArticleTabId, message
            );
            if (response?.success === false) {
                throw responseError(
                    response,
                    'SUPPLEMENTAL_IMPORT_FAILED',
                    '无法导入补充 Figure 草稿'
                );
            }
            return response;
        } catch (error) {
            if (!isClosedTabError(error)) throw error;
            const fallback = await chromeApi.runtime.sendMessage({
                type: 'ARTICLE_WORKSPACE_SAVE_SUPPLEMENTAL_DRAFT',
                target,
                draft,
                ...(message.transientImage
                    ? { transientImage: message.transientImage }
                    : {})
            });
            if (fallback?.success === false) {
                throw responseError(
                    fallback,
                    'SUPPLEMENTAL_DRAFT_SAVE_FAILED',
                    '无法保存补充 Figure 草稿'
                );
            }
            return { ...(fallback?.data || fallback || {}), savedAsDraft: true };
        }
    }

    async function deliverUpdate(targetInput, request = {}) {
        const target = validateTarget(targetInput);
        const figureId = String(request.figureId || '').trim();
        if (!figureId) {
            throw importError('SUPPLEMENTAL_FIGURE_NOT_FOUND', '没有找到要编辑的补充图');
        }
        const message = {
            action: 'updateSupplementalFigureDraft',
            target,
            figureId,
            caption: normalizeOptionalCaption(request.caption),
            figureLabel: String(request.figureLabel || '').trim(),
            sourcePage: String(request.sourcePage ?? '').trim()
        };
        if (request.transientImage) {
            const transientImage = shared.normalizeSupplementalTransientImage(
                request.transientImage,
                request.transientImage.sourceFingerprint
            );
            Object.assign(message, {
                transientImage: {
                    mediaType: transientImage.mediaType,
                    dataUrl: transientImage.dataUrl,
                    width: transientImage.width,
                    height: transientImage.height,
                    sourceFingerprint: transientImage.sourceFingerprint
                },
                sourceFingerprint: transientImage.sourceFingerprint,
                sourceFileName: String(request.sourceFileName || '').slice(0, 500),
                sourceMimeType: String(request.sourceMimeType || '').slice(0, 100),
                sourceFileSize: Math.max(0, Number(request.sourceFileSize) || 0)
            });
        }
        const response = await sendTabMessageWithRecovery(
            chromeApi, target.targetArticleTabId, message
        );
        if (response?.success === false) {
            throw responseError(response, 'SUPPLEMENTAL_UPDATE_FAILED', '补充图修改失败');
        }
        return response;
    }

    async function deliverDelete(targetInput, figureId) {
        const target = validateTarget(targetInput);
        const normalizedFigureId = String(figureId || '').trim();
        if (!normalizedFigureId) {
            throw importError('SUPPLEMENTAL_FIGURE_NOT_FOUND', '没有找到要删除的补充图');
        }
        const response = await sendTabMessageWithRecovery(
            chromeApi,
            target.targetArticleTabId,
            { action: 'deleteSupplementalFigure', target, figureId: normalizedFigureId }
        );
        if (response?.success === false) {
            throw responseError(response, 'SUPPLEMENTAL_DELETE_FAILED', '补充图删除失败');
        }
        return response;
    }

    return {
        syncSourceMode,
        validateTarget,
        buildTarget,
        validateImageFile,
        normalizeCaption,
        normalizeOptionalCaption,
        normalizeManualMetadata,
        validateManualInput,
        clipboardImageFile,
        prepareTransientImage,
        createImageImport,
        createCaptionImport,
        deliverImport,
        deliverUpdate,
        deliverDelete
    };
}

const supplementalFigureImportTools = createSupplementalFigureImportTools({
    shared: SciLLM,
    chromeApi: chrome
});

function supplementalPdfImportedPanelCount(snapshot, reportedCount = 0) {
    const figures = Array.isArray(snapshot?.figures?.figures)
        ? snapshot.figures.figures : [];
    const normalizedPanelId = value => String(
        value?.panelId ?? value?.panel ?? value ?? ''
    ).normalize('NFKC').trim().toUpperCase();
    const total = figures.filter(figure => figure?.isSupplemental === true)
        .reduce((sum, figure) => {
            const panelIds = new Set();
            const add = value => {
                const panelId = normalizedPanelId(value);
                if (panelId) panelIds.add(panelId);
            };
            (Array.isArray(figure?.panelHints) ? figure.panelHints : []).forEach(add);
            [figure?.standard, figure?.deep].forEach(analysis => {
                (Array.isArray(analysis?.panels) ? analysis.panels : []).forEach(add);
            });
            Object.keys(figure?.panelAnalyses || {}).forEach(add);
            return sum + panelIds.size;
        }, 0);
    return Math.max(total, Math.max(0, Number(reportedCount) || 0));
}

async function openSupplementalMaterialPdf(material, target, selectedFile = null) {
    target = supplementalFigureImportTools.validateTarget(target);
    let file = selectedFile;
    if (!(file instanceof Blob)) {
        file = await new Promise(resolve => {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'application/pdf,.pdf';
            input.addEventListener('change', () => resolve(input.files?.[0] || null), {
                once: true
            });
            input.click();
        });
    }
    if (!(file instanceof Blob)) return { cancelled: true };
    if (file.size > SciLLM.PDF_MINERU_MAX_FILE_BYTES) {
        throw Object.assign(new Error('补充 PDF 超过 MinerU 允许的文件大小'), {
            code: 'PDF_LOCAL_FILE_TOO_LARGE'
        });
    }
    const signature = await file.slice(0, 5).arrayBuffer();
    if (!SciLLM.hasPdfByteSignature(signature)) {
        throw Object.assign(new Error('所选文件不是有效的 PDF'), {
            code: 'SUPPLEMENTAL_PDF_INVALID'
        });
    }
    const importToken = await SciLLM.saveSupplementalPdfImportSession(file, {
        maximumBytes: SciLLM.PDF_MINERU_MAX_FILE_BYTES
    });
    const readerUrl = SciLLM.createSupplementalPdfReaderUrl?.(
        chrome.runtime.getURL.bind(chrome.runtime),
        {
            sourceUrl: material?.url,
            title: material?.title,
            materialId: material?.materialId,
            parentWorkspaceId: target.workspaceId,
            parentWorkspaceGeneration: target.workspaceGeneration,
            parentCanonicalUrl: target.canonicalUrl,
            parentDocumentHash: target.documentHash,
            parentTabId: target.targetArticleTabId
        }
    );
    if (!readerUrl) {
        await SciLLM.discardSupplementalPdfImportSession(importToken).catch(() => false);
        showStatus('这个补充材料不是可直接解析的 PDF 链接', 'error');
        return { cancelled: true };
    }
    const headlessUrl = new URL(readerUrl);
    headlessUrl.searchParams.set('supplementalImportToken', importToken);
    headlessUrl.searchParams.set('headlessImport', '1');
    const statusKey = SciLLM.supplementalPdfImportStatusKey(importToken);
    await chrome.storage.session.set({
        [statusKey]: { stage: 'queued', updatedAt: Date.now() }
    });
    let tab = null;
    try {
        tab = await chrome.tabs.create({ url: headlessUrl.href, active: false });
        await SciLLM.markTabActivated?.(chrome.storage.session, {
            ...tab,
            url: headlessUrl.href,
            pendingUrl: headlessUrl.href,
            title: material?.title || '补充材料 PDF'
        });
        showStatus('补充 PDF 已在后台交给 MinerU 解析，可继续阅读当前正文', 'success');
        const deadline = Date.now() + 20 * 60 * 1000;
        let result = null;
        while (Date.now() < deadline) {
            const stored = await chrome.storage.session.get(statusKey);
            const status = stored?.[statusKey];
            if (status?.stage === 'complete') {
                result = status;
                break;
            }
            if (status?.stage === 'error') {
                throw Object.assign(new Error(
                    status.message || 'MinerU 解析补充 PDF 失败'
                ), { code: status.code || 'SUPPLEMENTAL_PDF_IMPORT_FAILED' });
            }
            await new Promise(resolve => setTimeout(resolve, 750));
        }
        if (!result) throw Object.assign(new Error('MinerU 解析补充 PDF 超时'), {
            code: 'PDF_MINERU_TIMEOUT'
        });
        const snapshot = await refreshArticleWorkspace();
        const coverage = snapshot?.figures?.supplemental?.coverage || null;
        const missing = Array.isArray(coverage?.missingFigureLabels)
            ? coverage.missingFigureLabels : [];
        const figureCount = Math.max(0, Number(result.figureCount) || 0);
        const panelCount = supplementalPdfImportedPanelCount(
            snapshot, result.panelCount
        );
        const needsAttention = figureCount === 0 || missing.length > 0;
        const message = figureCount === 0
            ? '解析已完成，但未识别到可导入的 Figure；请重试或手动补充图片/图注'
            : missing.length
                ? `已导入 ${figureCount} 张 Figure、识别 ${panelCount} 个 Panel；尚缺 ${missing.join('、')}，请手动补充或重试`
                : `已导入 ${figureCount} 张 Figure、识别 ${panelCount} 个 Panel`;
        return { ...result, coverage, needsAttention, message };
    } finally {
        await SciLLM.discardSupplementalPdfImportSession(importToken).catch(() => false);
        await chrome.storage.session.remove(statusKey).catch(() => undefined);
        if (Number.isInteger(tab?.id)) {
            await chrome.tabs.remove(tab.id).catch(() => undefined);
        }
    }
}

let supplementalFigureImportTarget = null;
let supplementalFigureImportSession = {
    action: 'create',
    figure: null,
    clipboardFile: null
};

function supplementalFigureImportMode(form = document.getElementById(
    'supplementalFigureImportForm'
)) {
    return form?.querySelector?.(
        'input[name="supplementalFigureSourceMode"]:checked'
    )?.value || 'pdf';
}

function setSupplementalFigureImportStatus(message = '', { error = false } = {}) {
    const status = document.getElementById('supplementalFigureImportStatus');
    if (!status) return;
    status.textContent = String(message || '');
    status.classList.toggle('is-error', error);
}

function focusSupplementalFigureImportError(error) {
    const field = error?.fieldId ? document.getElementById(error.fieldId) : null;
    if (field) {
        field.setAttribute('aria-invalid', 'true');
        field.focus();
    } else {
        document.getElementById('supplementalFigureImportStatus')?.focus?.();
    }
}

function updateSupplementalFigureSelectedImage(file = null, { existing = false } = {}) {
    const label = document.getElementById('supplementalFigureSelectedImage');
    const pasteTarget = document.getElementById('supplementalFigurePasteTarget');
    if (!label) return;
    const hasImage = Boolean(file || existing);
    label.textContent = file
        ? `已选择：${file.name}（${Math.max(1, Math.ceil(file.size / 1024))} KiB）`
        : existing ? '已保留当前图片；选择或粘贴新图片可替换。'
            : '未选择图片；也可以只填写图注。';
    label.classList.toggle('has-image', hasImage);
    pasteTarget?.classList.toggle('is-ready', hasImage);
}

function setSupplementalFigureClipboardFile(file) {
    supplementalFigureImportSession.clipboardFile = file || null;
    const input = document.getElementById('supplementalFigureImageFile');
    if (input && file && typeof DataTransfer === 'function') {
        try {
            const transfer = new DataTransfer();
            transfer.items.add(file);
            input.files = transfer.files;
        } catch (_) {}
    }
    updateSupplementalFigureSelectedImage(file, {
        existing: supplementalFigureImportSession.figure?.hasImage === true
    });
}

function resetSupplementalFigureImportForm({ editingFigure = null } = {}) {
    const form = document.getElementById('supplementalFigureImportForm');
    form?.reset?.();
    const fileInput = document.getElementById('supplementalFigureImageFile');
    const pdfFileInput = document.getElementById('supplementalFigurePdfFile');
    const captionInput = document.getElementById('supplementalFigureImageCaption');
    const kindInput = document.getElementById('supplementalFigureKind');
    const labelInput = document.getElementById('supplementalFigureLabel');
    const pageInput = document.getElementById('supplementalFigureSourcePage');
    if (fileInput) fileInput.value = '';
    if (pdfFileInput) pdfFileInput.value = '';
    if (captionInput) captionInput.value = editingFigure?.caption || '';
    if (kindInput) {
        kindInput.value = editingFigure?.isSupplemental === false ? 'main' : 'supplemental';
        kindInput.disabled = Boolean(editingFigure);
    }
    if (labelInput) {
        labelInput.value = editingFigure?.figureLabel || '';
        labelInput.placeholder = kindInput?.value === 'main'
            ? '例如 Figure 3' : '例如 Figure S2（留空则自动编号）';
    }
    if (pageInput) pageInput.value = Number(editingFigure?.sourcePage) > 0
        ? String(Math.floor(Number(editingFigure.sourcePage))) : '';
    form?.querySelectorAll('[aria-invalid="true"]').forEach(field =>
        field.removeAttribute('aria-invalid')
    );
    supplementalFigureImportSession = {
        action: editingFigure ? 'edit' : 'create',
        figure: editingFigure || null,
        clipboardFile: null
    };
    document.querySelectorAll('[data-supplemental-create-only]').forEach(element => {
        element.hidden = Boolean(editingFigure);
    });
    const title = document.getElementById('supplementalFigureImportTitle');
    const description = document.getElementById('supplementalFigureImportDescription');
    const submit = document.getElementById('submitSupplementalFigureImport');
    if (title) title.textContent = editingFigure
        ? `编辑 ${editingFigure.figureLabel || '手动 Figure'}` : '手动补全 Figure';
    if (description) description.textContent = editingFigure
        ? '可修改图注，或上传、粘贴新图片替换当前图片。保存后需要重新解图。'
        : '可上传主图或补充图原图、图注，并标注它在原 PDF 中的页码。';
    if (submit) submit.textContent = editingFigure ? '保存修改' : '继续';
    supplementalFigureImportTools.syncSourceMode(
        form,
        'manual'
    );
    updateSupplementalFigureSelectedImage(null, {
        existing: editingFigure?.hasImage === true
    });
    setSupplementalFigureImportStatus('');
}

function openSupplementalFigureImportDialog() {
    const dialog = document.getElementById('supplementalFigureImportDialog');
    try {
        supplementalFigureImportTarget = supplementalFigureImportTools.buildTarget(
            currentWorkspaceSnapshot,
            activePanelTabContext.tabId,
            preparedDocumentState?.documentHash || manualAnnotationState.documentHash
        );
    } catch (error) {
        showStatus(error.message, 'error');
        return;
    }
    resetSupplementalFigureImportForm();
    dialog?.showModal();
}

function openSupplementalFigureEditDialog(figure) {
    const dialog = document.getElementById('supplementalFigureImportDialog');
    try {
        supplementalFigureImportTarget = supplementalFigureImportTools.buildTarget(
            currentWorkspaceSnapshot,
            activePanelTabContext.tabId,
            preparedDocumentState?.documentHash || manualAnnotationState.documentHash
        );
    } catch (error) {
        showStatus(error.message, 'error');
        return;
    }
    resetSupplementalFigureImportForm({ editingFigure: figure });
    dialog?.showModal();
    document.getElementById('supplementalFigureImageCaption')?.focus?.();
}

async function deleteSupplementalFigureFromWorkspace(figure) {
    const label = String(figure?.figureLabel || '这张补充图');
    if (!globalThis.confirm?.(`确定删除 ${label}？\n\n这会同时移除其解图结果和串解关系。`)) {
        return;
    }
    const target = supplementalFigureImportTools.buildTarget(
        currentWorkspaceSnapshot,
        activePanelTabContext.tabId,
        preparedDocumentState?.documentHash || manualAnnotationState.documentHash
    );
    await supplementalFigureImportTools.deliverDelete(target, figure?.figureId);
    showStatus(`${label} 已删除`, 'success');
    await refreshArticleWorkspace();
}

function closeSupplementalFigureImportDialog() {
    document.getElementById('supplementalFigureImportDialog')?.close();
}

async function submitSupplementalFigureImport(event) {
    event.preventDefault();
    const form = event.currentTarget;
    const submit = document.getElementById('submitSupplementalFigureImport');
    const mode = supplementalFigureImportMode(form);
    form.querySelectorAll('[aria-invalid="true"]').forEach(field =>
        field.removeAttribute('aria-invalid')
    );
    if (submit?.disabled) return;
    if (submit) submit.disabled = true;
    setSupplementalFigureImportStatus('正在保存并识别 Panel…');
    try {
        const target = supplementalFigureImportTools.validateTarget(
            supplementalFigureImportTarget
        );
        let importResult = null;
        if (mode === 'pdf' && supplementalFigureImportSession.action === 'create') {
            const pdfFile = document.getElementById('supplementalFigurePdfFile')
                ?.files?.[0] || null;
            if (!pdfFile) {
                const error = new Error('请先选择要解析的补充 PDF');
                error.code = 'SUPPLEMENTAL_PDF_INVALID';
                error.fieldId = 'supplementalFigurePdfFile';
                throw error;
            }
            importResult = await openSupplementalMaterialPdf({
                materialId: `manual-supplement-${Date.now()}`,
                title: '本地补充材料 PDF',
                url: ''
            }, target, pdfFile);
            if (importResult?.cancelled) return;
            setSupplementalFigureImportStatus(importResult.message, {
                error: importResult.needsAttention === true
            });
            closeSupplementalFigureImportDialog();
            showStatus(
                importResult.message,
                importResult.needsAttention === true ? 'error' : 'success'
            );
            return;
        } else {
            const fileInput = document.getElementById('supplementalFigureImageFile');
            const file = supplementalFigureImportSession.clipboardFile ||
                fileInput?.files?.[0] || null;
            const captionValue = document.getElementById(
                'supplementalFigureImageCaption'
            )?.value;
            const manual = supplementalFigureImportTools.validateManualInput(
                file,
                captionValue,
                { hasExistingImage: supplementalFigureImportSession.figure?.hasImage === true }
            );
            const metadata = supplementalFigureImportTools.normalizeManualMetadata({
                figureKind: document.getElementById('supplementalFigureKind')?.value,
                figureLabel: document.getElementById('supplementalFigureLabel')?.value,
                sourcePage: document.getElementById('supplementalFigureSourcePage')?.value
            });
            let transientImage = null;
            if (manual.file) {
                setSupplementalFigureImportStatus('正在本地校验、缩放并压缩图片…');
                transientImage = await supplementalFigureImportTools
                    .prepareTransientImage(manual.file);
            }
            if (supplementalFigureImportSession.action === 'edit') {
                const editingFigure = supplementalFigureImportSession.figure;
                importResult = await supplementalFigureImportTools.deliverUpdate(target, {
                    figureId: editingFigure?.figureId,
                    caption: manual.caption,
                    figureLabel: metadata.figureLabel,
                    sourcePage: metadata.sourcePage,
                    ...(transientImage ? {
                        transientImage,
                        sourceFileName: manual.file.name,
                        sourceMimeType: manual.file.type,
                        sourceFileSize: manual.file.size
                    } : {})
                });
            } else if (manual.file) {
                const request = supplementalFigureImportTools.createImageImport(
                    manual.file, transientImage, manual.caption, metadata
                );
                importResult = await supplementalFigureImportTools.deliverImport(target, request);
            } else {
                const request = await supplementalFigureImportTools.createCaptionImport(
                    manual.caption, metadata
                );
                importResult = await supplementalFigureImportTools.deliverImport(target, request);
            }
        }
        const importedLabel = String(importResult?.figureLabel || '补充 Figure');
        const panelHints = Array.isArray(importResult?.panelHints)
            ? importResult.panelHints : [];
        const importedMessage = `${importedLabel} ${
            supplementalFigureImportSession.action === 'edit' ? '已更新' : '已新建'
        }` +
            (panelHints.length ? `；已识别 Panel ${panelHints.join('、')}` : '；暂未识别到 Panel');
        const directoryMessage = mode === 'pdf' ? ''
            : importResult?.directoryPersisted === true
                ? '；图片和图注已写入所选文件夹'
                : '；已保存在浏览器，但所选文件夹尚未完成写入，请重新授权文件夹后点击“保存全部”';
        const persistedMessage = `${importedMessage}${directoryMessage}`;
        setSupplementalFigureImportStatus(
            mode === 'pdf' ? '已在新标签页打开 PDF 工作区' : persistedMessage
        );
        closeSupplementalFigureImportDialog();
        showStatus(
            mode === 'pdf'
                ? '已在新标签页打开补充 PDF 工作区'
                : persistedMessage,
            mode !== 'pdf' && importResult?.directoryPersisted !== true
                ? 'error' : 'success'
        );
        await refreshArticleWorkspace();
    } catch (error) {
        setSupplementalFigureImportStatus(error.message, { error: true });
        focusSupplementalFigureImportError(error);
    } finally {
        if (submit) submit.disabled = false;
    }
}

function setupSupplementalFigureImport() {
    const dialog = document.getElementById('supplementalFigureImportDialog');
    const form = document.getElementById('supplementalFigureImportForm');
    document.getElementById('openSupplementalFigureImport')?.addEventListener(
        'click', openSupplementalFigureImportDialog
    );
    document.getElementById('closeSupplementalFigureImport')?.addEventListener(
        'click', closeSupplementalFigureImportDialog
    );
    document.getElementById('cancelSupplementalFigureImport')?.addEventListener(
        'click', closeSupplementalFigureImportDialog
    );
    form?.addEventListener('change', event => {
        if (event.target?.name === 'supplementalFigureSourceMode') {
            supplementalFigureImportTools.syncSourceMode(dialog, event.target.value);
            setSupplementalFigureImportStatus('');
            return;
        }
        if (event.target?.id === 'supplementalFigureImageFile') {
            supplementalFigureImportSession.clipboardFile = null;
            updateSupplementalFigureSelectedImage(event.target.files?.[0] || null, {
                existing: supplementalFigureImportSession.figure?.hasImage === true
            });
        } else if (event.target?.id === 'supplementalFigureKind') {
            const label = document.getElementById('supplementalFigureLabel');
            if (label) label.placeholder = event.target.value === 'main'
                ? '例如 Figure 3' : '例如 Figure S2（留空则自动编号）';
        }
    });
    document.getElementById('supplementalFigurePasteTarget')?.addEventListener(
        'click', event => event.currentTarget?.focus?.()
    );
    dialog?.addEventListener('paste', event => {
        const file = supplementalFigureImportTools.clipboardImageFile(
            event.clipboardData
        );
        if (!file) return;
        event.preventDefault();
        supplementalFigureImportTools.syncSourceMode(dialog, 'manual');
        setSupplementalFigureClipboardFile(file);
        setSupplementalFigureImportStatus('已从剪贴板导入图片');
    });
    form?.addEventListener('submit', event => {
        void submitSupplementalFigureImport(event);
    });
}

async function sendTabMessage(tabId, message, options = {}) {
    if (!activePanelTabContext.activated ||
        Number(tabId) !== Number(activePanelTabContext.tabId)) {
        const error = new Error('当前标签页尚未激活，请点击侧栏任意位置激活');
        error.code = 'PANEL_TAB_NOT_ACTIVATED';
        throw error;
    }
    return SciLLM.sendTabMessageWithRecovery(chrome, tabId, message, options);
}

async function resolveSupplementalReaderTab(figure = {}) {
    const readerUrl = String(figure.sourceReaderUrl || '').trim();
    const storedTabId = Number(figure.sourceReaderTabId);
    let tab = null;
    if (Number.isInteger(storedTabId) && storedTabId >= 0) {
        tab = await chrome.tabs.get(storedTabId).catch(() => null);
        if (tab && !SciLLM.isPdfReaderUrl?.(tab.url || tab.pendingUrl)) tab = null;
    }
    if (!tab && readerUrl) {
        const tabs = await chrome.tabs.query({});
        tab = tabs.find(candidate => candidate.url === readerUrl ||
            candidate.pendingUrl === readerUrl) || null;
    }
    if (!tab && readerUrl) {
        const currentTabId = Number(activePanelTabContext.tabId);
        tab = Number.isInteger(currentTabId) && currentTabId >= 0
            ? await chrome.tabs.update(currentTabId, { url: readerUrl, active: true })
            : await chrome.tabs.create({ url: readerUrl, active: true });
        await SciLLM.markTabActivated?.(chrome.storage.session, {
            ...tab,
            url: readerUrl,
            pendingUrl: readerUrl,
            title: figure.sourceTitle || '补充材料 PDF'
        });
    } else if (tab?.id) {
        await chrome.tabs.update(tab.id, { active: true });
    }
    if (!tab?.id) throw new Error('补充 PDF 工作区已关闭，且无法恢复解析页面');
    if (Number.isInteger(tab.windowId)) {
        await chrome.windows.update(tab.windowId, { focused: true });
    }
    return tab;
}

async function waitForSupplementalReaderFigure(tabId, figure = {}) {
    const parsedLabel = SciLLM.parseFigureLabel?.(figure.figureLabel);
    const sourceFigureId = String(
        figure.originalFigureId || parsedLabel?.figureId || figure.figureId || ''
    );
    const deadline = Date.now() + 180000;
    let lastError = null;
    while (Date.now() < deadline) {
        try {
            const response = await SciLLM.sendTabMessageIfPresent(chrome, tabId, {
                action: 'getFigureWorkspaceSnapshot'
            });
            const figures = Array.isArray(response?.snapshot?.figures)
                ? response.snapshot.figures : [];
            const match = figures.find(item =>
                item.figureId === sourceFigureId ||
                item.figureLabel === figure.figureLabel
            );
            if (match) return match.figureId;
        } catch (error) {
            lastError = error;
        }
        await new Promise(resolve => setTimeout(resolve, 750));
    }
    throw lastError || new Error('补充 PDF 尚未完成解析，请稍后重试');
}

async function runExternalSupplementalFigureAnalysis(figure = {}) {
    return runSingleFigureAnalysis(String(figure?.figureId || ''));
}

async function runPaperMetaExtraction(taskKind) {
    const task = taskKind === 'innovation' || taskKind === 'limitations'
        ? taskKind : 'research_logic';
    const labels = {
        research_logic: ['研究背景与科学问题', 'analyzeResearchLogicWithLLM'],
        innovation: ['全文创新点', 'analyzePaperInnovationWithLLM'],
        limitations: ['研究局限', 'analyzePaperLimitationsWithLLM']
    };
    if (!requireUsableLlm(labels[task][0])) return;
    const state = paperMetaTaskState[task];
    if (state.running) return;
    if (!literatureNoteDocumentState) await loadLiteratureNoteDocumentState();
    const noteContext = captureLiteratureNoteContext();
    const initialFieldRevisions = new Map(literatureNoteFieldEditVersions);
    const expectedDocumentHash = String(
        currentWorkspaceSnapshot?.documentHash ||
        preparedDocumentState?.documentHash ||
        manualAnnotationState?.documentHash || ''
    ).trim();
    let tab = null;
    let panelContext = null;
    state.running = true;
    state.error = '';
    state.phase = 'requesting';
    state.changedFields = 0;
    updatePaperMetaTaskButtons(task);
    showStatus(`正在提取${labels[task][0]}…`, 'success');
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        panelContext = capturePanelContext();
        const response = await sendTabMessage(tab.id, {
            action: labels[task][1]
        });
        if (!isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext)) {
            return { stale: true };
        }
        if (!response?.success) {
            const error = new Error(response?.error || `${labels[task][0]}提取失败`);
            error.code = response?.code;
            throw error;
        }
        const result = response.result || {};
        if (expectedDocumentHash &&
            String(result.documentHash || '').trim() !== expectedDocumentHash) {
            const error = new Error('论文正文身份已变化，已丢弃不属于当前文献的提取结果');
            error.code = 'LITERATURE_NOTE_DOCUMENT_CHANGED';
            throw error;
        }
        state.phase = 'integrating';
        updatePaperMetaTaskButtons(task);
        await refreshArticleWorkspace();
        if (!isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext)) {
            return { stale: true };
        }
        const integrated = applyCurrentPaperMetaToLiteratureNote(
            initialFieldRevisions
        );
        state.changedFields = integrated.changedFields.length;
        if (integrated.changedFields.length) {
            state.phase = 'saving';
            updatePaperMetaTaskButtons(task);
            const persisted = await persistLiteratureNoteDocumentState(noteContext);
            if (persisted?.stale || !isCurrentPanelContext(panelContext) ||
                !isCurrentLiteratureNoteContext(noteContext)) {
                return { stale: true };
            }
        }
        state.phase = 'complete';
        updatePaperMetaTaskButtons(task);
        const cacheHit = result?.cache?.atomicEvidence === 'hit';
        const partial = result?.partial === true;
        showStatus(
            `${labels[task][0]}${partial ? '已部分生成，需人工核验' : '已生成'}` +
                (cacheHit ? '（已复用正文证据缓存）' : ''),
            partial ? 'warning' : 'success'
        );
        await persistCurrentArticleArchive().catch(() => null);
        return {
            success: true,
            taskKind: task,
            changedFields: integrated.changedFields,
            partial,
            cacheHit
        };
    } catch (error) {
        if (panelContext && (!isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext))) {
            return { stale: true };
        }
        state.error = String(error?.message || '提取失败');
        state.phase = 'failed';
        showStatus(`${labels[task][0]}提取失败：${state.error}`, 'error');
        return { success: false, error: state.error, code: error?.code || '' };
    } finally {
        state.running = false;
        updatePaperMetaTaskButtons(task);
        const terminalPhase = state.phase;
        setTimeout(() => {
            if (!state.running && state.phase === terminalPhase &&
                ['complete', 'failed'].includes(terminalPhase)) {
                state.phase = '';
                state.changedFields = 0;
                updatePaperMetaTaskButtons(task);
            }
        }, 2400);
    }
}

async function runFigureAnalysis() {
    if (!requireUsableLlm('逐图解读')) return;
    let tab = null;
    let taskToken = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        taskToken = figureTaskGeneration;
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        figureAnalysisState = {
            running: true,
            paused: false,
            phase: 'extracting',
            currentFigure: 0,
            totalFigures: 0,
            completedFigures: 0,
            failedFigures: 0,
            figureLabel: '',
            message: '正在读取论文中的 Figure…'
        };
        updateFigureButton();
        showStatus('正在读取论文中的 Figure…', 'success');
        startFigureProgressPolling(tab.id);
        const response = await sendTabMessage(tab.id, {
            action: 'analyzeFiguresWithLLM',
            analysisDepth: 'standard'
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (response?.cancelled || response?.code === 'CANCELLED') {
            const error = new Error('图解已取消，已完成结果会保留');
            error.code = 'CANCELLED';
            throw error;
        }
        if (!response?.success) {
            const error = new Error(response?.error || '逐图解读失败');
            error.code = response?.code;
            throw error;
        }
        const failedCount = Number(response.failedCount) || 0;
        const analyzedCount = Number(response.analyzedCount) || 0;
        const totalCount = Number(response.totalCount) || analyzedCount + failedCount;
        const details = [];
        if (response.cacheHits) details.push(response.cacheHits + ' 张来自缓存');
        if (response.visionFallbacks) {
            details.push(response.visionFallbacks + ' 张仅使用图注与正文');
        }
        if (failedCount > 0) {
            showStatus(formatEffectiveRoute(
                `逐图解读完成 ${analyzedCount}/${totalCount} 张，${failedCount} 张失败；` +
                '成功结果已保留，重试时会复用缓存' +
                (details.length ? '（' + details.join('，') + '）' : ''),
                response.route
            ),
                'error',
                response.usage
            );
        } else {
            showStatus(formatEffectiveRoute(
                '逐图解读完成：' + analyzedCount + ' 张 Figure' +
                (details.length ? '（' + details.join('，') + '）' : ''),
                response.route
            ),
                'success',
                response.usage
            );
        }
        figureAnalysisState = {
            ...figureAnalysisState,
            running: false,
            phase: failedCount > 0 ? 'partial' : 'completed',
            currentFigure: totalCount,
            totalFigures: totalCount,
            completedFigures: analyzedCount,
            failedFigures: failedCount,
            message: failedCount > 0
                ? `完成 ${analyzedCount}/${totalCount} 张，${failedCount} 张失败`
                : `完成 ${analyzedCount}/${totalCount} 张`
        };
        // Batch Figure analysis ends here. 图表梳理 is an explicit separate task.
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const progress = tab?.id
            ? await refreshFigureAnalysisProgress(tab.id, false)
            : figureAnalysisState;
        const progressText = progress?.totalFigures
            ? `（已完成 ${progress.completedFigures || 0}/${progress.totalFigures} 张` +
                (progress.failedFigures ? `，失败 ${progress.failedFigures} 张` : '') + '）'
            : '';
        if (error?.code === 'CANCELLED' || figureAnalysisState.phase === 'cancelled') {
            showStatus('Figure 解读已取消，已完成结果会保留' + progressText, 'success');
        } else {
            showStatus('逐图解读失败' + progressText + '：' + error.message, 'error');
        }
    } finally {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        stopFigureProgressPolling();
        figureAnalysisState = { ...figureAnalysisState, running: false };
        updateFigureButton();
        // A mechanism result or the reader may have changed views while the
        // batch was running. Completion refreshes data without taking focus.
        await refreshArticleWorkspace();
        await persistCurrentArticleArchive().catch(() => null);
    }
}

function currentFigureOriginalPdfRequest(figureId) {
    const id = String(figureId || '');
    const figures = Array.isArray(currentWorkspaceSnapshot?.figures?.figures)
        ? currentWorkspaceSnapshot.figures.figures : [];
    const figure = figures.find(item => String(item?.figureId || '') === id);
    if (figure?.sourceKind !== 'pdf-page-caption') return {};
    const request = {
        documentHash: String(figure.documentHash || ''),
        documentGeneration: Number(figure.pdfDocumentGeneration) || 0
    };
    const result = figure.activeDepth === 'standard'
        ? (figure.standard || figure.deep) : (figure.deep || figure.standard);
    const panelPageMap = result?.pdfPanelInventory?.panelPageMap;
    const resultBinding = result?.pdfEvidenceBinding;
    const artworkPages = Array.isArray(figure.artworkPageNumbers)
        ? figure.artworkPageNumbers : [];
    if (!panelPageMap || !artworkPages.length ||
        result?.pdfPanelInventory?.version !== 'pdf-figure-panel-inventory-v3' ||
        result.pdfPanelInventory?.provenance?.figureId !== id ||
        result.pdfPanelInventory?.provenance?.visualEvidenceSetDigest !==
            resultBinding?.visualEvidenceSet?.setDigest ||
        resultBinding?.figureId !== id ||
        resultBinding?.binding?.documentHash !== request.documentHash ||
        resultBinding?.binding?.documentGeneration !== request.documentGeneration) return request;
    const prefix = `${id}::`;
    const renderedActivePanels = Array.from(document.querySelectorAll(
        '.workspace-figure-panel-card[data-figure-id][data-panel-id]'
    )).filter(item => item.dataset.figureId === id && item.open === true);
    const renderedPanelId = String(
        renderedActivePanels[renderedActivePanels.length - 1]?.dataset?.panelId || ''
    ).toUpperCase();
    const storedPanelId = [...figurePanelExpansionState.entries()]
        .find(([key, open]) => open === true && key.startsWith(prefix))?.[0]
        ?.slice(prefix.length).toUpperCase() || '';
    const panelId = renderedPanelId || storedPanelId;
    const sourcePage = panelPageMap[panelId];
    const verifiedMarker = result.pdfPanelInventory.markers?.some(marker =>
        marker?.label === panelId && marker?.clarity === 'clear' &&
        marker?.pageNumber === sourcePage);
    if (panelId && verifiedMarker && Number.isSafeInteger(sourcePage) &&
        artworkPages.includes(sourcePage)) {
        request.panelId = panelId;
        request.sourcePage = sourcePage;
    }
    return request;
}

async function showFigureOriginalImage(figureId) {
    const panelContext = capturePanelContext();
    const pdfRequest = currentFigureOriginalPdfRequest(figureId);
    const expectsPdfPageNavigation = Boolean(
        pdfRequest.documentHash && pdfRequest.documentGeneration
    );
    const tab = await queryPanelTargetTab();
    if (!tab?.id || Number(tab.id) !== Number(panelContext.tabId) ||
        !isCurrentPanelContext(panelContext)) {
        throw new Error('当前论文页面已切换，请返回后重试');
    }
    const requestSequence = ++figureOriginalViewerState.requestSequence;
    figureOriginalViewerState = {
        open: !expectsPdfPageNavigation,
        tabId: tab.id,
        figureId: expectsPdfPageNavigation ? '' : figureId,
        captionVisible: false,
        requestSequence
    };
    let response;
    try {
        response = await sendTabMessage(tab.id, {
            action: 'showFigureOriginalImage', figureId, ...pdfRequest
        });
    } catch (error) {
        if (requestSequence === figureOriginalViewerState.requestSequence) {
            figureOriginalViewerState = {
                open: false,
                tabId: tab.id,
                figureId: '',
                captionVisible: false,
                requestSequence
            };
        }
        throw error;
    }
    if (requestSequence !== figureOriginalViewerState.requestSequence ||
        !isCurrentPanelContext(panelContext)) return;
    if (!response?.success) {
        figureOriginalViewerState = {
            open: false,
            tabId: tab.id,
            figureId: '',
            captionVisible: false,
            requestSequence
        };
        throw new Error(response?.code === 'IMAGE_NOT_FOUND'
            ? '未找到该 Figure 的高清原图' : '无法打开该 Figure 原图');
    }
    const pdfPageNavigation = response.mode === 'pdf-page';
    figureOriginalViewerState = {
        open: !pdfPageNavigation,
        tabId: tab.id,
        figureId: pdfPageNavigation ? '' : String(response.figureId || figureId),
        captionVisible: response.captionVisible === true,
        requestSequence
    };
}

async function runFigurePanelFollowup(
    figureId,
    panelId,
    topics,
    customQuestion = '',
    historyLabel = ''
) {
    if (!hasUsableLlm()) throw new Error(llmUnavailableMessage('Panel 追问'));
    const taskToken = figureTaskGeneration;
    const panelText = figurePanelUiText(figureId, panelId);
    const tab = await queryPanelTargetTab();
    if (!tab?.id || !isCurrentFigureTask(taskToken, tab.id)) {
        throw new Error('当前论文页面已切换，请返回后重试');
    }
    showStatus(panelText.followupRunning, 'success');
    let response;
    try {
        response = await sendTabMessage(tab.id, {
            action: 'askFigurePanelWithLLM',
            figureId,
            panelId,
            topics,
            customQuestion,
            historyLabel
        });
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
        throw error;
    }
    if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
    if (!response?.success) {
        const error = new Error(response?.error || 'FIGURE_PANEL_FOLLOWUP_FAILED');
        error.code = response?.code;
        throw error;
    }
    const followupKey = panelWorkspaceKey(figureId, panelId);
    const draft = getPanelFollowupDraft(figureId, panelId);
    draft.open = true;
    draft.topics.clear();
    draft.question = '';
    figureExpansionState.set(figureId, true);
    figurePanelExpansionState.set(followupKey, true);
    panelFollowupRevealKey = followupKey;
    await refreshArticleWorkspace();
    if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
    await persistCurrentArticleArchive().catch(() => null);
    if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            revealPanelFollowupAnswer(followupKey);
            setTimeout(() => {
                if (panelFollowupRevealKey !== followupKey) return;
                stabilizePanelFollowupAnswer(followupKey);
                panelFollowupRevealKey = '';
            }, 280);
        });
    });
    showStatus(
        panelText.followupComplete,
        'success',
        response.usage
    );
    return response;
}

async function runSingleFigureAnalysis(figureId) {
    if (!requireUsableLlm('Figure 解读')) return;
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        startFigureProgressPolling(tab.id, { waitForSnapshot: true });
        showStatus(`\u6b63\u5728\u7cbe\u8bfb ${figureId}\u2026`, 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'analyzeSingleFigureWithLLM', figureId, forceRefresh: true
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_ANALYSIS_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(
            `\u5df2\u5b8c\u6210 ${figureId} \u7684\u5355\u56fe\u7cbe\u8bfb`,
            'success',
            response.usage
        );
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        showStatus(error?.code === 'CANCELLED'
            ? '解图已取消，已有结果会保留。'
            : '\u5355\u56fe\u7cbe\u8bfb\u5931\u8d25\uff1a' + error.message,
        error?.code === 'CANCELLED' ? 'success' : 'error');
    } finally {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const progress = tab?.id
            ? await refreshFigureAnalysisProgress(tab.id, false, taskToken)
            : null;
        if (!hasRunningFigureProgress(progress)) stopFigureProgressPolling();
        renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
        await refreshArticleWorkspace();
        await persistCurrentArticleArchive().catch(() => null);
    }
}

function runFigureRecoveryFromUi(figure, panelIds, presentation, button = null) {
    const action = presentation?.action === 'deep_rerun'
        ? 'deep_rerun' : 'missing_panels';
    const tabId = Number(activePanelTabContext.tabId) || 0;
    const key = `${tabId}:${String(figure?.figureId || '')}:${action}`;
    return runKeyedFigureRecoveryAction(
        key,
        () => action === 'deep_rerun'
            ? runDeepFigureRecovery(figure)
            : runMissingFigurePanelRetry(figure, panelIds),
        () => {
            if (button) {
                button.disabled = true;
                button.setAttribute('aria-busy', 'true');
            }
            if (tabId) startFigureProgressPolling(tabId, { waitForSnapshot: true });
        },
        () => {
            if (button?.isConnected) {
                button.setAttribute('aria-busy', 'false');
            }
            if (tabId) {
                void refreshFigureAnalysisProgress(tabId, false, figureTaskGeneration)
                    .finally(() => renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot));
            } else {
                renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
            }
        }
    );
}

async function runDeepFigureRecovery(figure) {
    if (!requireUsableLlm('Figure 解读')) return null;
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return null;
        showStatus(t('重新运行深度解读以补齐缺失 Panel'), 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'analyzeSingleFigureDeepWithLLM',
            figureId: figure.figureId,
            operationId: createFigureRecoveryOperationId('deep', figure.figureId),
            expectedFigureInputHash: String(figure.figureInputHash || '')
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return null;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_DEEP_RETRY_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(`${figure.figureLabel || figure.figureId}：${t('深度解读恢复完成')}`,
            'success', response.usage);
        return response;
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return null;
        showStatus(error?.code === 'FIGURE_PANEL_RETRY_SCOPE_STALE'
            ? t('Figure 状态已变化，请刷新后按当前缺失 Panel 重试。')
            : `${t('深度解读恢复失败')}：${error.message}`, 'error');
        return null;
    } finally {
        if (isCurrentFigureTask(taskToken, tab?.id)) {
            await refreshArticleWorkspace();
            await persistCurrentArticleArchive().catch(() => null);
        }
    }
}

async function runMissingFigurePanelRetry(figure, panelIds) {
    if (!requireUsableLlm('Figure 解读')) return;
    const requestedPanels = normalizeFigureRecoveryPanelLabels(panelIds);
    if (!figure?.figureId || !requestedPanels.length) return;
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        showStatus(`${t('重试缺失 Panel')}：${requestedPanels.join('、')}`, 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'retryMissingFigurePanelsWithLLM',
            figureId: figure.figureId,
            panelIds: requestedPanels,
            analysisDepth: figure.activeDepth === 'deep' ? 'deep' : 'standard',
            operationId: createFigureRecoveryOperationId('panels', figure.figureId),
            expectedFigureInputHash: String(figure.figureInputHash || '')
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_PANEL_RETRY_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(
            response.partial
                ? `${t('已保留')} ${response.resolvedPanels?.length || 0} ` +
                    `${t('个恢复结果')}；${t('仍有 Panel 待补')}`
                : `${t('已完成缺失 Panel')}：${requestedPanels.join('、')}`,
            response.partial ? 'error' : 'success'
        );
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const message = error?.code === 'FIGURE_PANEL_RETRY_SCOPE_STALE'
            ? t('Figure 状态已变化，请刷新后按当前缺失 Panel 重试。')
            : error?.code === 'FIGURE_DEEP_RETRY_REQUIRES_RERUN'
                ? t('深度解读的缺失 Panel 需要重新运行深度解读')
                : `${t('缺失 Panel 重试失败')}：${error.message}`;
        showStatus(message, 'error');
    } finally {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        await refreshArticleWorkspace();
        await persistCurrentArticleArchive().catch(() => null);
    }
}

async function runSingleFigurePanelAnalysis(figureId, panelId) {
    if (!requireUsableLlm('Panel 解读')) return;
    const panelText = figurePanelUiText(figureId, panelId);
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        figureExpansionState.set(figureId, true);
        figurePanelExpansionState.set(panelWorkspaceKey(figureId, panelId), true);
        startFigureProgressPolling(tab.id, { waitForSnapshot: true });
        showStatus(panelText.analysisRunning, 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'analyzeSingleFigurePanelWithLLM',
            figureId,
            panelId,
            forceRefresh: true
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_PANEL_ANALYSIS_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(formatEffectiveRoute(
            panelText.analysisComplete, response.route
        ), 'success', response.usage);
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        showStatus(error?.code === 'CANCELLED'
            ? 'Panel 解读已取消，已有结果会保留。'
            : `Panel 解读失败：${error.message}`,
        error?.code === 'CANCELLED' ? 'success' : 'error');
    } finally {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const progress = tab?.id
            ? await refreshFigureAnalysisProgress(tab.id, false, taskToken)
            : null;
        if (!hasRunningFigureProgress(progress)) stopFigureProgressPolling();
        await refreshArticleWorkspace();
        await persistCurrentArticleArchive().catch(() => null);
    }
}

async function runCrossFigureLogic({
    returnView = activeWorkspaceView === 'mechanism' ? 'mechanism' : 'figures',
    seedMode = returnView === 'mechanism' ? 'auto' : 'none'
} = {}) {
    if (!requireUsableLlm('机制链')) return;
    let tab = null;
    let taskToken = null;
    let operationId = '';
    let completedResponse = null;
    let generationContext = null;
    let generationPanelContext = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        taskToken = figureTaskGeneration;
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        generationPanelContext = capturePanelContext();
        // Another panel or an asynchronous Figure merge may have advanced the
        // shared draft since this sidebar rendered. Read the authoritative view
        // before binding a new operation; its later CAS checks remain strict.
        const generationSnapshot = await refreshArticleWorkspace({
            panelContext: generationPanelContext
        });
        if (!isCurrentFigureTask(taskToken, tab.id) ||
            !isCurrentPanelContext(generationPanelContext)) return;
        if (!generationSnapshot) {
            const error = new Error('MECHANISM_WORKSPACE_SYNC_FAILED');
            error.code = 'MECHANISM_WORKSPACE_SYNC_FAILED';
            throw error;
        }
        if (generationSnapshot.figures?.inventoryReady === false) {
            const error = new Error('图目录尚未保存，请刷新解图目录后再生成图表梳理。');
            error.code = generationSnapshot.figures.inventoryError?.code ||
                'FIGURE_WORKSPACE_INVENTORY_SEED_FAILED';
            throw error;
        }
        generationContext = captureFigureWorkspaceEditContext();
        operationId = createMechanismOperationId();
        const binding = Object.freeze({
            documentId: generationContext.documentId,
            workspaceId: generationContext.workspaceId,
            workspaceGeneration: generationContext.workspaceGeneration,
            workspaceLifecycle: generationContext.workspaceLifecycle,
            baseWorkspaceRevision: generationContext.draftRevision,
            mechanismChainFingerprint: generationContext.mechanismChainFingerprint
        });
        const evidenceFirstVersions = SciLLM.normalizeEvidenceFirstVersions?.(
            SciLLM.EVIDENCE_FIRST_VERSIONS
        );
        if (!evidenceFirstVersions) {
            const error = new Error('MECHANISM_REQUEST_INVALID');
            error.code = 'MECHANISM_REQUEST_INVALID';
            throw error;
        }
        const generationRequest = createEvidenceFirstMechanismPopupRequest({
            evidenceFirstVersion: '2',
            evidenceFirstRouterVersion: '2',
            evidenceFirstVersions,
            operationId,
            documentId: binding.documentId,
            workspaceId: binding.workspaceId,
            baseWorkspaceRevision: binding.baseWorkspaceRevision,
            workspaceGeneration: binding.workspaceGeneration,
            workspaceLifecycle: binding.workspaceLifecycle,
            mechanismChainFingerprint: binding.mechanismChainFingerprint
        }, SciLLM);
        const controller = replaceMechanismGenerationUiController(tab.id);
        controller.start({ operationId, epoch: 0, binding, evidenceFirstVersions });
        renderMechanismGenerationStatus();
        const rawResponse = await sendTabMessage(tab.id, generationRequest);
        const response = Object.freeze({
            success: mechanismGenerationOwnData(rawResponse, 'success'),
            code: mechanismGenerationOwnData(rawResponse, 'code'),
            operationEpoch: mechanismGenerationOwnData(rawResponse, 'operationEpoch'),
            status: mechanismGenerationOwnData(rawResponse, 'status'),
            operationId: mechanismGenerationOwnData(rawResponse, 'operationId'),
            evidenceFirstVersions: mechanismGenerationOwnData(
                rawResponse, 'evidenceFirstVersions'
            ),
            result: mechanismGenerationOwnData(rawResponse, 'result'),
            workspaceCommitted: mechanismGenerationOwnData(
                rawResponse, 'workspaceCommitted'
            ),
            route: mechanismGenerationOwnData(rawResponse, 'route'),
            usage: mechanismGenerationOwnData(rawResponse, 'usage')
        });
        const presentation = mechanismGenerationUiController.presentation();
        if (!isCurrentFigureTask(taskToken, tab.id) ||
            presentation.operation?.operationId !== operationId ||
            ['cancelling', 'cancelled'].includes(presentation.status)) return;
        const responseVersions = SciLLM.normalizeEvidenceFirstVersions?.(
            response.evidenceFirstVersions
        );
        if (!responseVersions) {
            mechanismGenerationUiController.fail(operationId, 'INVALID_RESPONSE');
            renderMechanismGenerationStatus();
            const error = new Error('INVALID_RESPONSE');
            error.code = 'INVALID_RESPONSE';
            throw error;
        }
        if (response.success !== true) {
            const suppliedResponseCode = response.code;
            const responseCode = /^[A-Z][A-Z0-9_-]{2,80}$/u.test(
                String(suppliedResponseCode || '')
            ) ? String(suppliedResponseCode) : 'MECHANISM_GENERATION_FAILED';
            mechanismGenerationUiController.fail(operationId, responseCode);
            renderMechanismGenerationStatus();
            const error = new Error(responseCode);
            error.code = responseCode;
            throw error;
        }
        const responseEpoch = Number(response.operationEpoch);
        const responseStatus = String(response.status || '');
        const responseOperationId = response.operationId;
        const responseResult = response.result;
        if (responseOperationId !== operationId ||
            !Number.isSafeInteger(responseEpoch) || responseEpoch < 1 ||
            !['complete', 'needs_review', 'failed', 'cancelled',
                'revision_conflict'].includes(responseStatus)) {
            mechanismGenerationUiController.fail(operationId, 'INVALID_RESPONSE');
            renderMechanismGenerationStatus();
            const error = new Error('INVALID_RESPONSE');
            error.code = 'INVALID_RESPONSE';
            throw error;
        }
        if (responseStatus === 'complete' &&
            (!isSeedableMechanismGenerationResult(responseResult) ||
                response.workspaceCommitted !== true)) {
            mechanismGenerationUiController.fail(operationId, 'INVALID_RESPONSE');
            renderMechanismGenerationStatus();
            const error = new Error('INVALID_RESPONSE');
            error.code = 'INVALID_RESPONSE';
            throw error;
        }
        const terminalEvent = {
            status: responseStatus,
            errorCode: response.code,
            operationId,
            operationEpoch: responseEpoch,
            evidenceFirstVersions: responseVersions,
            ...binding
        };
        const acceptedTerminal = mechanismGenerationUiController.complete(terminalEvent);
        const terminalPresentation = mechanismGenerationUiController.presentation();
        if (!acceptedTerminal && (terminalPresentation.operation?.operationId !== operationId ||
            terminalPresentation.status !== responseStatus)) return;
        renderMechanismGenerationStatus();
        if (responseStatus === 'complete') {
            completedResponse = Object.freeze({
                success: true,
                status: 'complete',
                operationId,
                operationEpoch: responseEpoch,
                evidenceFirstVersions: responseVersions,
                result: responseResult,
                workspaceCommitted: true,
                route: response.route || null,
                usage: response.usage || null
            });
        } else {
            const failed = responseStatus === 'failed' || responseStatus === 'revision_conflict';
            showStatus(failed
                ? formatLlmFailureMessage('机制链生成', { code: terminalPresentation.code })
                : mechanismGenerationStatusLabel(terminalPresentation),
            failed ? 'error' : responseStatus === 'cancelled' ? 'success' : 'warning');
            // The content realm persists valid partial evidence separately from
            // the editable chain. Refresh it so a needs-review result is visible
            // immediately instead of leaving the user at an old manual node.
            if (responseStatus === 'needs_review' || responseResult?.evidenceFirstMechanism) {
                await refreshArticleWorkspace({ panelContext: generationPanelContext });
                if (isCurrentPanelContext(generationPanelContext)) {
                    switchWorkspaceView('mechanism');
                }
            }
            return {
                success: true, status: responseStatus, operationId,
                operationEpoch: responseEpoch,
                code: terminalPresentation.code
            };
        }
        const result = responseResult;
        const resultNodes = mechanismGenerationOwnData(result, 'nodes');
        const resultDominoChain = mechanismGenerationOwnData(result, 'dominoChain');
        const evidenceFirstMechanism = mechanismGenerationOwnData(
            result, 'evidenceFirstMechanism'
        );
        const evidenceNodes = mechanismGenerationOwnData(
            evidenceFirstMechanism, 'nodes'
        );
        const evidenceRelations = mechanismGenerationOwnData(
            evidenceFirstMechanism, 'relations'
        );
        const boundedArrayLength = (value, maximum) => {
            let isArray = false;
            try { isArray = Array.isArray(value); } catch (_) { return 0; }
            const length = isArray ? mechanismGenerationOwnData(value, 'length') : 0;
            return Number.isSafeInteger(length) && length >= 0 && length <= maximum
                ? length : 0;
        };
        const legacyNodeCount = boundedArrayLength(resultNodes, 128);
        const evidenceNodeCount = boundedArrayLength(evidenceNodes, 64);
        const legacyLinkCount = boundedArrayLength(resultDominoChain, 256);
        const evidenceRelationCount = boundedArrayLength(evidenceRelations, 64);
        let supportedRelationCount = 0;
        for (let index = 0; index < evidenceRelationCount; index += 1) {
            const relation = mechanismGenerationOwnData(evidenceRelations, String(index));
            if (mechanismGenerationOwnData(relation, 'relationStatus') === 'supported') {
                supportedRelationCount += 1;
            }
        }
        const nodes = legacyNodeCount || evidenceNodeCount;
        const links = legacyLinkCount || supportedRelationCount;
        showStatus(
            `跨图综合已生成：${nodes} 个节点、${links} 条跨图连接` +
                (mechanismGenerationOwnData(result, 'cacheHit') === true
                    ? '（已复用缓存）' : ''),
            'success',
            completedResponse.usage
        );
        switchWorkspaceView(returnView);
        return completedResponse;
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id) ||
            (operationId && mechanismGenerationUiController.presentation()
                .operation?.operationId !== operationId)) return;
        showStatus(error?.code === 'CANCELLED'
            ? '机制链生成已取消。'
            : formatLlmFailureMessage('机制链生成', error),
        error?.code === 'CANCELLED' ? 'success' : 'error');
        return null;
    } finally {
        const stillCurrent = isCurrentFigureTask(taskToken, tab?.id) &&
            (!operationId || mechanismGenerationUiController.presentation()
                .operation?.operationId === operationId);
        if (!stillCurrent) return;
        renderMechanismGenerationStatus();
        if (completedResponse) {
            await finalizeSuccessfulMechanismGeneration({
                response: completedResponse,
                seedMode: 'none',
                generationContext,
                refresh: () => refreshArticleWorkspace({
                    panelContext: generationPanelContext
                }),
                seed: seedMechanismChainFromCrossFigure,
                isContextCurrent: isCurrentFigureWorkspaceEditContext,
                matchesSnapshot: mechanismSnapshotMatchesContext,
                onBlocked(message) {
                    setMechanismChainSaveStatus(message, 'error');
                    showStatus(message, 'error');
                }
            }).catch(() => {
                if (returnView === 'mechanism') {
                    showStatus('机制链初始化失败；可继续手动新增节点。', 'error');
                }
            });
        } else {
            await refreshArticleWorkspace({ panelContext: generationPanelContext })
                .catch(() => null);
        }
        if (returnView === 'mechanism') {
            switchWorkspaceView('mechanism');
            figureWorkspaceRenderCoordinator.request(currentWorkspaceSnapshot);
        }
        await persistCurrentArticleArchive().catch(() => null);
    }
}

async function runReviewOutlineAnalysis({ forceRefresh = false } = {}) {
    const panelContext = capturePanelContext(reviewOutlineTaskGeneration);
    if (!isCurrentReviewOutlineTask(panelContext)) return;
    if (!requireUsableLlm('逐段摘要')) return;
    const tabId = panelContext.tabId;
    try {
        if (!preparedDocumentState) {
            await prepareArticleForAdaptiveAnalysis(tabId, {
                isCurrent: () => isCurrentReviewOutlineTask(panelContext)
            });
            if (!isCurrentReviewOutlineTask(panelContext)) return;
        }
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        showStatus('正在生成逐段摘要…', 'success');
        reviewOutlineState = {
            ...reviewOutlineState,
            running: true,
            phase: 'extracting',
            completedParagraphs: 0,
            totalParagraphs: preparedDocumentState?.document?.paragraphs?.length || 0,
            message: '正在提取正文层级…'
        };
        updateReviewOutlineButton();
        startReviewOutlineProgressPolling(tabId, panelContext);
        const selectionCustomized = currentWorkspaceSnapshot?.analysisSelectionCustomized === true;
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'analyzeReviewOutlineWithLLM',
            forceRefresh,
            documentId: preparedDocumentState.documentId,
            documentHash: preparedDocumentState.documentHash,
            scopeSectionIds: selectedWorkspaceAnalysisSectionIds(),
            scopeSelectionProvided: selectionCustomized
        });
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        if (!response?.success) {
            const error = new Error(response?.error || '论文大纲生成失败');
            error.code = response?.code;
            throw error;
        }
        reviewOutlineState = {
            ...reviewOutlineState,
            running: false,
            phase: 'completed',
            completedParagraphs: response.outline?.paragraphCount ||
                reviewOutlineState.totalParagraphs,
            hasOutline: true,
            globalSynthesisAvailable: response.outline?.globalSynthesisAvailable
        };
        switchWorkspaceView('navigation');
        await refreshArticleWorkspace({ panelContext });
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        await persistCurrentArticleArchive({ panelContext }).catch(() => null);
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const synthesisNotice = response.outline?.globalSynthesisAvailable === false
            ? '；全局组织综合暂不可用，但逐段摘要已保留'
            : '';
        showStatus(
            `论文大纲已生成：${reviewOutlineState.completedParagraphs} 段` +
                synthesisNotice,
            response.outline?.globalSynthesisAvailable === false ? 'error' : 'success',
            response.usage
        );
    } catch (error) {
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const progress = tabId
            ? await refreshReviewOutlineProgress(tabId, false, panelContext)
            : reviewOutlineState;
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const progressText = progress?.totalParagraphs
            ? `（已完成 ${progress.completedParagraphs || 0}/${progress.totalParagraphs} 段）`
            : '';
        const resumeNotice = Number(progress?.completedParagraphs) > 0
            ? '；已完成部分已保存，重新点击将从断点继续'
            : '';
        showStatus('论文大纲生成失败' + progressText + '：' + error.message +
            resumeNotice, 'error');
    } finally {
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        stopReviewOutlineProgressPolling();
        reviewOutlineState = { ...reviewOutlineState, running: false };
        updateReviewOutlineButton();
    }
}

function renderManualAnnotationSummary() {
    const summary = document.getElementById('manualAnnotationSummary');
    if (!manualAnnotationState.documentId) {
        summary.textContent = '当前页面尚未准备好手动标注数据';
    } else {
        summary.textContent = `本文手动标注 ${manualAnnotationState.annotationCount} 条` +
            ` · 待重新定位 ${manualAnnotationState.unresolvedCount} 条`;
    }
    const automaticButton = document.getElementById('clearAutomaticHighlights');
    const manualButton = document.getElementById('clearManualAnnotations');
    if (automaticButton) automaticButton.disabled = automaticClearPending;
    if (manualButton) {
        manualButton.disabled = manualClearPending ||
            !manualAnnotationState.documentId || manualAnnotationState.annotationCount === 0;
    }
}

function applyManualAnnotationStateEvent(event = {}, tabId = null) {
    if (manualAnnotationEventRefreshPromise?.tabId === Number(tabId)) return false;
    const commitMode = SciLLM.manualAnnotationEventCommitMode(
        manualAnnotationState,
        event,
        tabId,
        activePanelTabContext.tabId
    );
    if (commitMode !== 'verified') return false;
    manualSummarySequence += 1;
    manualAnnotationState = {
        ...manualAnnotationState,
        title: String(event.title || ''),
        annotationCount: Math.max(0, Number(event.annotationCount) || 0),
        unresolvedCount: Math.max(0, Number(event.unresolvedCount) || 0)
    };
    renderManualAnnotationSummary();
    return true;
}

function refreshManualAnnotationSummaryAfterUnverifiedEvent(tabId) {
    const numericTabId = Number(tabId);
    if (!Number.isSafeInteger(numericTabId)) return Promise.resolve(null);
    if (manualAnnotationEventRefreshPromise?.tabId === numericTabId) {
        return manualAnnotationEventRefreshPromise.promise;
    }
    const promise = refreshManualAnnotationSummary(numericTabId)
        .then(state => {
            if (state) void refreshArticleWorkspace();
            return state;
        })
        .finally(() => {
            if (manualAnnotationEventRefreshPromise?.promise === promise) {
                manualAnnotationEventRefreshPromise = null;
            }
        });
    manualAnnotationEventRefreshPromise = { tabId: numericTabId, promise };
    return promise;
}

async function refreshManualAnnotationSummary(tabId = null) {
    const requestId = ++manualSummarySequence;
    try {
        const capturedTab = await queryPanelTargetTab();
        const targetTabId = tabId || capturedTab?.id;
        if (!targetTabId) throw new Error('无法获取当前论文页面');
        if (Number(capturedTab?.id) !== Number(targetTabId)) return null;
        const response = await sendTabMessage(targetTabId, {
            action: 'prepareManualAnnotations'
        });
        if (!response?.success) {
            throw new Error(response?.error || '手动标注数据不可用');
        }
        const liveProof = await sendTabMessage(targetTabId, {
            action: 'prepareManualAnnotations'
        });
        const currentTab = await queryPanelTargetTab();
        const commitMode = SciLLM.manualAnnotationRefreshCommitMode({
            expectedTabId: targetTabId,
            capturedTab,
            currentTab,
            response,
            liveProof,
            committedState: manualAnnotationState,
            superseded: requestId !== manualSummarySequence
        });
        if (commitMode === 'committed') return manualAnnotationState;
        if (commitMode !== 'response') return null;
        manualAnnotationState = {
            tabId: targetTabId,
            documentId: liveProof.documentId,
            documentHash: liveProof.documentHash || '',
            canonicalUrl: liveProof.canonicalUrl || '',
            contentWorldNonce: liveProof.contentWorldNonce || '',
            documentEpoch: Number(liveProof.documentEpoch) || 0,
            title: liveProof.title || '',
            annotationCount: Math.max(0, Number(liveProof.annotationCount) || 0),
            unresolvedCount: Math.max(0, Number(liveProof.unresolvedCount) || 0)
        };
        renderManualAnnotationSummary();
        return manualAnnotationState;
    } catch (error) {
        if (requestId !== manualSummarySequence) return null;
        manualAnnotationState = {
            tabId: null,
            documentId: '',
            documentHash: '',
            canonicalUrl: '',
            title: '',
            annotationCount: 0,
            unresolvedCount: 0
        };
        renderManualAnnotationSummary();
        return null;
    }
}

async function clearAutomaticHighlightsFromCurrentTab() {
    if (automaticClearPending) return;
    automaticClearPending = true;
    renderManualAnnotationSummary();
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        const response = await sendTabMessage(tab.id, {
            action: 'clearAutomaticHighlights'
        });
        if (!response?.success) throw new Error(response?.error || '清除自动高亮失败');
        matchCounts = {};
        renderCategories();
        await persistCurrentArticleArchive().catch(() => null);
        showStatus(response.persisted === false
            ? `自动高亮已清除，手动标注保留不变；本地状态保存失败：` +
                `${response.persistenceError || '请稍后重试'}`
            : '自动高亮已清除，手动标注保留不变',
        response.persisted === false ? 'error' : 'success');
    } catch (error) {
        showStatus(`清除自动高亮失败：${error.message}`, 'error');
    } finally {
        automaticClearPending = false;
        renderManualAnnotationSummary();
    }
}

function openManualClearConfirmation() {
    if (manualClearPending || !manualAnnotationState.documentId ||
        manualAnnotationState.annotationCount === 0) return;
    document.getElementById('clearManualDescription').textContent =
        `将删除本文 ${manualAnnotationState.annotationCount} 条手动标注，` +
        `其中 ${manualAnnotationState.unresolvedCount} 条待重新定位。自动高亮不会受影响。`;
    document.getElementById('clearManualDialog').showModal();
}

async function confirmManualAnnotationClear(event) {
    event.preventDefault();
    if (manualClearPending) return;
    const snapshot = { ...manualAnnotationState };
    if (!snapshot.documentId || snapshot.annotationCount === 0) return;
    manualClearPending = true;
    renderManualAnnotationSummary();
    const confirmButton = document.getElementById('confirmClearManual');
    confirmButton.disabled = true;
    try {
        const tab = await queryPanelTargetTab();
        if (tab?.id !== snapshot.tabId ||
            manualAnnotationState.documentId !== snapshot.documentId) {
            throw new Error('当前论文已变化，请重新确认');
        }
        const currentDocument = await sendTabMessage(snapshot.tabId, {
            action: 'prepareManualAnnotations'
        });
        if (!currentDocument?.success ||
            currentDocument.documentId !== snapshot.documentId) {
            throw new Error('当前论文已变化，请重新确认');
        }
        await runManualClear({
            documentId: snapshot.documentId,
            clearDocument: ({ documentId }) => sendLlmMessage({
                type: 'ANNOTATION_CLEAR_DOCUMENT',
                documentId
            }),
            unwrap: message => sendTabMessage(snapshot.tabId, {
                action: 'clearManualAnnotations',
                ...message,
                completionType: 'ANNOTATION_CLEAR_DOCUMENT'
            })
        });
        manualAnnotationState = {
            ...snapshot,
            annotationCount: 0,
            unresolvedCount: 0
        };
        document.getElementById('clearManualDialog').close();
        await persistCurrentArticleArchive().catch(() => null);
        showStatus('本文手动标注已清除，自动高亮保留不变', 'success');
    } catch (error) {
        if (error?.backgroundCleared) {
            manualAnnotationState = {
                ...snapshot,
                annotationCount: 0,
                unresolvedCount: 0
            };
            document.getElementById('clearManualDialog').close();
            showStatus('手动标注数据已清除；请刷新页面以移除残留标记', 'error');
        } else {
            showStatus(`清除手动标注失败，页面标记保持不变：${error.message}`, 'error');
        }
    } finally {
        manualClearPending = false;
        confirmButton.disabled = false;
        renderManualAnnotationSummary();
    }
}

function normalizePopupFigurePanelHeaderFields(value) {
    const source = value && typeof value === 'object' && !Array.isArray(value)
        ? value : {};
    return Object.fromEntries(Object.entries(DEFAULT_FIGURE_PANEL_HEADER_FIELDS)
        .map(([key, fallback]) => [
            key,
            typeof source[key] === 'boolean' ? source[key] : fallback
        ]));
}

function renderFigurePanelHeaderFieldsControl() {
    document.querySelectorAll('[data-figure-panel-header-field]').forEach(checkbox => {
        const key = checkbox.dataset.figurePanelHeaderField;
        checkbox.checked = figurePanelHeaderFieldsState[key] === true;
        checkbox.disabled = figurePanelHeaderFieldsSaving;
    });
}

function closeFigurePanelHeaderFieldsMenu() {
    const button = document.getElementById('figurePanelHeaderFieldsButton');
    const menu = document.getElementById('figurePanelHeaderFieldsMenu');
    if (!button || !menu) return;
    menu.hidden = true;
    button.setAttribute('aria-expanded', 'false');
}

function setupFigurePanelHeaderFieldsMenu() {
    if (figurePanelHeaderFieldsMenuInitialized) return;
    const button = document.getElementById('figurePanelHeaderFieldsButton');
    const menu = document.getElementById('figurePanelHeaderFieldsMenu');
    if (!button || !menu) return;
    figurePanelHeaderFieldsMenuInitialized = true;
    renderFigurePanelHeaderFieldsControl();
    button.addEventListener('click', () => {
        const open = menu.hidden;
        menu.hidden = !open;
        button.setAttribute('aria-expanded', String(open));
    });
    menu.addEventListener('change', event => {
        const checkbox = event.target.closest('[data-figure-panel-header-field]');
        if (!checkbox) return;
        const key = checkbox.dataset.figurePanelHeaderField;
        if (!Object.hasOwn(DEFAULT_FIGURE_PANEL_HEADER_FIELDS, key)) return;
        const previous = { ...figurePanelHeaderFieldsState };
        const next = { ...previous, [key]: checkbox.checked === true };
        const boundedError = error => String(error?.message || '未知错误')
            .normalize('NFKC').replace(/\s+/g, ' ').trim().slice(0, 120);
        void runFigurePanelHeaderFieldsMutation({
            isPending: () => figurePanelHeaderFieldsSaving,
            previous,
            next,
            persist: value => updateLlmPreferencesCore({
                figurePanelHeaderFields: value
            }).then(saved => saved?.settings?.figurePanelHeaderFields),
            normalizeSaved: value => normalizePopupFigurePanelHeaderFields(value),
            setState: value => {
                figurePanelHeaderFieldsState = { ...value };
            },
            setPending: value => {
                figurePanelHeaderFieldsSaving = value === true;
                renderFigurePanelHeaderFieldsControl();
            },
            render: () => {
                renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
            },
            onSaveFailed: error => showStatus(
                `Panel 标题信息保存失败：${boundedError(error)}`, 'error'
            ),
            onRenderFailed: error => showStatus(
                `Panel 标题显示刷新失败：${boundedError(error)}`, 'error'
            )
        });
    });
    document.addEventListener('pointerdown', event => {
        if (menu.hidden || menu.contains(event.target) || button.contains(event.target)) return;
        closeFigurePanelHeaderFieldsMenu();
    });
    document.addEventListener('keydown', event => {
        if (event.key === 'Escape' && !menu.hidden) {
            event.preventDefault();
            closeFigurePanelHeaderFieldsMenu();
            button.focus();
        }
    });
}

